INSERT INTO public.ingredients VALUES ('019de0ab-6240-7caf-aeb8-4db50ad99d4b', '__OWNER_ID__', 'Mauve (Malva sylvestris)', 'mauve', 'Actif émollient et protecteur de référence, idéal pour apaiser les muqueuses et les peaux ultra-sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6248-7a42-bd9f-14f1d2580a53', '__OWNER_ID__', 'Copper PCA', 'copper-pca', 'Sel de cuivre du PCA, régulateur du microbiome cutané et séborégulateur, limite la prolifération des bactéries impliquées dans l''acné.', '# Copper PCA
INSERT INTO public.ingredients VALUES ('019e077b-683b-786d-8a63-cf907a72f7af', '__OWNER_ID__', 'Azelamide MEA', 'azelamide-mea', 'Dérivé amidé de l''acide azélaïque, alternative cosmétique soluble pour anti-imperfections et anti-rougeurs.', '# Azelamide MEA
INSERT INTO public.ingredients VALUES ('019e077b-683b-78bb-9b84-f84fb4dcdbc1', '__OWNER_ID__', 'Azelamidopropyl Dimethyl Amine (Epi-On)', 'azelamidopropyl-dimethyl-amine', 'Dérivé amine de l''acide azélaïque, action anti-imperfections et anti-rougeurs.', '# Azelamidopropyl Dimethyl Amine (Epi-On)
INSERT INTO public.ingredients VALUES ('019de0ab-624d-7fd8-9954-975c29cade70', '__OWNER_ID__', 'Menthe Poivrée (Mentha piperita)', 'menthe-poivree', 'Actif purifiant et rafraîchissant majeur, idéal pour rééquilibrer les peaux mixtes à grasses et stimuler l''éclat.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7549-9766-06dc1c3340f4', '__OWNER_ID__', 'Melabiome-XP', 'melabiome-xp', 'Complexe avancé de postbiotiques et prébiotiques pour le rééquilibrage et la protection du microbiome.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624e-74a2-b98b-904ebb9365f4', '__OWNER_ID__', 'Sphingomonas Ferment Extract', 'sphingomonas-ferment-extract', 'Postbiotique. Rééquilibre le microbiome cutané.', '# Sphingomonas Ferment Extract
INSERT INTO public.ingredients VALUES ('019de0ab-6242-78ae-99ce-33deed9c274c', '__OWNER_ID__', 'La Réglisse (Famille des Glycyrrhiza)', 'reglisse', 'Véritable "couteau suisse" de la dermo-cosmétique, la réglisse regroupe des actifs majeurs (Glabridine, Enoxolone, Licochalcone) agissant sur les taches, l’inflammation et le stress oxydatif.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624b-75da-ad89-709084276d28', '__OWNER_ID__', 'Aquabiome', 'aquabiome', 'Complexe d’actifs marins protecteur du microbiome cutané et de la barrière cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-763f-8359-cf194a3c7952', '__OWNER_ID__', 'SymSitive (4-t-Butylcyclohexanol)', 'symsitive', 'Régulateur de sensibilité cutanée de nouvelle génération qui agit directement sur les récepteurs sensoriels pour calmer instantanément les sensations d’inconfort.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624c-7ab6-9e6a-cfe022b11ff3', '__OWNER_ID__', 'Onopordum Acanthium Extract (Chardon argenté)', 'onopordum-acanthium-extract', 'Extrait floral de chardon écossais riche en composés phénoliques, anti-glycation et raffermissant pour peaux matures.', '# Onopordum Acanthium Extract
INSERT INTO public.ingredients VALUES ('019de0ab-6231-7a51-8bc8-329165064be6', '__OWNER_ID__', 'Squalane (Squalane)', 'squalane', 'Émollient biomimétique d''exception qui restaure le film hydrolipidique, adoucit la peau et prévient la déshydratation sans fini gras.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6231-7bc1-9509-2eddf48a6806', '__OWNER_ID__', 'Beurre de Karité (Butyrospermum parkii)', 'shea-butter', 'Actif relipidant et apaisant universel, riche en vitamines et acides gras, idéal pour nourrir et protéger les peaux les plus sèches.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-79e8-a34c-66cd66aa2ee2', '__OWNER_ID__', 'Coenzyme Q10 (Ubiquinone)', 'coenzyme-q10-hair', 'Coenzyme liposoluble de la chaîne respiratoire mitochondriale, antioxydant puissant qui protège les cellules folliculaires du vieillissement oxydatif.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6242-74da-9274-2a2300299c72', '__OWNER_ID__', 'Neutrazen', 'neutrazen', 'Neuropeptide conçu pour prévenir et réduire les signes de l’inflammation neurophage, idéal pour les peaux ultra-sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6234-77c1-a573-8c162c0c12af', '__OWNER_ID__', 'Ammonium Lactate', 'ammonium-lactate', 'Kératolytique doux et hydratant, particulièrement efficace pour les peaux sèches et rugueuses.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-735d-9a51-01cb322fd759', '__OWNER_ID__', 'Glucosamine HCl', 'glucosamine-hcl', 'Un précurseur naturel de l''acide hyaluronique qui hydrate, soutient la synthèse des glycosaminoglycanes et offre un effet exfoliant très doux.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-777d-8cde-7f86aa314559', '__OWNER_ID__', 'PCA (Pyrrolidone Carboxylic Acid)', 'pca', 'Un composant naturel du facteur d’hydratation de la peau (NMF), essentiel pour maintenir la souplesse et l’élasticité de l’épiderme.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-7b90-903d-c3a55fd737b3', '__OWNER_ID__', 'Collagen Amino Acids', 'collagen-amino-acids', 'Complexe d''acides aminés issus de l''hydrolyse du collagène, Collagen Amino Acids hydrate intensément, renforce la barrière cutanée, soutient la fermeté et apaise les peaux déshydratées ou matures pour un effet repulpant et confort immédiat.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-7ff1-bdf5-2ee548f47dd3', '__OWNER_ID__', 'Calcium PCA', 'calcium-pca', 'Sel de calcium de l''acide pyrrolidone carboxylique (PCA), composant NMF qui hydrate intensément, renforce la barrière cutanée, stimule le renouvellement cellulaire et restructure les peaux matures ou endommagées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622c-715b-bab0-6ac3df0eb423', '__OWNER_ID__', 'Arginine PCA', 'arginine-pca', 'Humectant puissant issu du facteur naturel d''hydratation (NMF), Arginine PCA hydrate en profondeur, équilibre le pH cutané, apaise et renforce la barrière pour les peaux déshydratées, sensibles ou atopiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6232-7ef8-baf6-c22f465d390e', '__OWNER_ID__', 'Lanolin Oil', 'lanolin-oil', 'Fraction huileuse purifiée de la lanoline (cire issue de la laine de mouton), émollient occlusif riche en esters cireux mimant les lipides cutanés.', '# Lanolin Oil
INSERT INTO public.ingredients VALUES ('019e077b-683b-791a-b83e-435c621fb2b1', '__OWNER_ID__', 'Acide 10-Hydroxystéarique', '10-hydroxystearic-acid', 'Acide gras hydroxylé, agoniste PPAR-α, soutien barrière cutanée et anti-inflammatoire.', '# Acide 10-Hydroxystéarique
INSERT INTO public.ingredients VALUES ('019de0ab-622c-74e3-aeb6-390499b1e1eb', '__OWNER_ID__', 'L-Tyrosine (Tyrosine)', 'tyrosine', 'L''acide aminé de la mélanogenèse et de l''éclat : le précurseur direct du pigment cutané pour une protection naturelle et un teint sublimé.', '# La Tyrosine : Le Précurseur Vital de la Mélanine et de la Photoprotection
INSERT INTO public.ingredients VALUES ('019de0ab-622c-7f41-8906-cbed11d511a6', '__OWNER_ID__', 'Lysine HCl (Chlorhydrate de Lysine)', 'lysine-hcl', 'L''acide aminé bâtisseur : un précurseur indispensable à la synthèse du collagène et un agent de renforcement structurel pour les tissus cutanés.', '# La Lysine HCl : L''Architecture et la Vitalité des Protéines Cutanées
INSERT INTO public.ingredients VALUES ('019de0ab-622e-72ed-aa52-5dced8fe75b3', '__OWNER_ID__', 'Imperata Cylindrica Root Extract', 'imperata-cylindrica-root', 'Extrait de racine de l''herbe à paillote, riche en potassium et en sucres osmolytes, qui régule le bilan hydrique cutané comme un humectant naturel.', '# Imperata Cylindrica Root Extract
INSERT INTO public.ingredients VALUES ('019de0ab-622e-739f-8f99-8074ccee86a6', '__OWNER_ID__', 'Disodium Acetyl Glucosamine Phosphate', 'disodium-acetyl-glucosamine-phosphate', 'Dérivé phosphaté de la N-acétyl glucosamine, hydratant et précurseur d''acide hyaluronique avec un effet éclaircissant doux par modulation de la mélanogenèse.', '# Disodium Acetyl Glucosamine Phosphate
INSERT INTO public.ingredients VALUES ('019e077b-683b-7b14-8047-e0c4cacde486', '__OWNER_ID__', 'Acétamidoéthoxyéthanol (Hydromanil)', 'acetamidoethoxyethanol', 'Humectant biomimétique longue durée, mime les facteurs naturels d''hydratation cutanés (NMF-like). Concentrations cosmétiques 5-10%.', '# Acétamidoéthoxyéthanol (Hydromanil)
INSERT INTO public.ingredients VALUES ('019de0ab-6240-7e25-a8af-7c0774d83a3a', '__OWNER_ID__', 'Pâquerette (Bellis perennis)', 'paquerette', 'Actif tenseur et éclaircissant de référence, idéal pour redessiner l''ovale du visage et unifier le teint.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622e-7450-b650-0d928709d26e', '__OWNER_ID__', 'Camelina Seed Oil (Camelina Sativa Seed Oil)', 'camelina-seed-oil', 'Huile légère riche en oméga-3, antioxydante et réparatrice, parfaite pour peaux sèches, sensibles ou inflammées.', '
INSERT INTO public.ingredients VALUES ('019e077b-683b-7978-a0b0-4d5196eb8aac', '__OWNER_ID__', 'Huile de Passiflore (Passiflora Edulis Seed Oil)', 'passiflora-edulis', 'Huile riche en acide linoléique et vitamine E, antioxydante et apaisante (commercialisée Passioline).', '# Huile de Passiflore (Passiflora Edulis Seed Oil)
INSERT INTO public.ingredients VALUES ('019de0ab-6233-7013-a982-02a02127b9ea', '__OWNER_ID__', 'Eau de fruit de Citron (Citrus Limon Fruit Water)', 'citrus-limon-fruit-water', 'Hydrosol de citron obtenu par distillation vapeur, riche en vitamine C, acides citrique et acides de fruits (AHA). Exfoliant doux naturel, purifiant et clarifiant, réduisant pores et prévenant comédons.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6255-780f-9c4f-6f78219742d1', '__OWNER_ID__', 'Carraghénane (Carrageenan)', 'carrageenan-dental', 'Un gélifiant naturel extrait d''algues rouges.', 'Le carraghénane est utilisé pour stabiliser la texture du dentifrice et s''assurer que les composants restent bien mélangés. Il aide à donner au produit sa consistance parfaite pour qu''il tienne bien sur la brosse à dents.', 'excipient', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.541+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, NULL);
INSERT INTO public.ingredients VALUES ('019de0ab-6234-72a8-a302-2553cfb10313', '__OWNER_ID__', 'Acide Lactique', 'lactic-acid', 'AHA hydratant, doux exfoliant et humectant.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622e-78b4-ade3-5d61f5c5fffb', '__OWNER_ID__', 'Huile de Colza (Canola Oil)', 'huile-colza', 'Huile végétale riche en Oméga-3 et Vitamine E, idéale pour nourrir intensément et apaiser les peaux sèches à atopiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623a-7f1b-b6f0-c28172de8174', '__OWNER_ID__', 'Coenzyme Q10', 'coq10', 'Puissant antioxydant naturellement présent dans la peau qui protège contre le stress oxydatif et booste l’énergie cellulaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622e-7abb-b70b-2ca5ef8f172c', '__OWNER_ID__', 'Huile de Soja (Glycine Soja)', 'huile-soja', 'Une huile fluide et pénétrante, riche en lécithine et vitamine E, qui assouplit la peau tout en la protégeant des radicaux libres.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622f-7d05-9e9d-e6c5d2aa3c71', '__OWNER_ID__', 'Huile de coco (Coconut Oil)', 'huile-coco', 'Huile végétale occlusive riche en acides gras saturés (laurique principalement), aux propriétés hydratantes et antimicrobiennes — mais controversée en raison de son potentiel comédogène élevé.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622f-7ee6-a60b-8ab20bfbd789', '__OWNER_ID__', 'Huile d’Onagre (Oenothera biennis oil)', 'huile-onagre', 'Huile végétale précieuse, source exceptionnelle d''oméga-6, qui restaure la barrière lipidique et apaise les peaux sèches et atopiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6237-7fa0-9a51-1e150327a8d3', '__OWNER_ID__', 'IGF-1 (Plant-derived)', 'nicotiana-benthamiana-octapeptide-30-sh-oligopeptide-2', 'Facteur de croissance biomimétique (IGF-1) produit par biotechnologie végétale, stimulant la prolifération cellulaire et la densité du derme.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6230-72f5-a8a9-ace6df7aaf23', '__OWNER_ID__', 'Palmitamide MEA (N-palmitoyl monoéthanolamine)', 'palmitamide-mea', 'Lipoaminoacide biomimétique apaisant, renforce la barrière et réduit l’inconfort cutané.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6230-745a-8493-754d9e1b020d', '__OWNER_ID__', 'Bourrache (Borago officinalis)', 'bourrache', 'Actif relipidant et régénérant d''exception, indispensable pour restaurer la barrière cutanée des peaux sèches à atopiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6230-75cc-b297-d32c17ded1c9', '__OWNER_ID__', 'Huile de Pépins de Raisin (Vitis vinifera) – Upcyclée', 'huile-de-pepins-de-raisin', 'L''huile upcyclée antioxydante et régénérante issue des sous-produits viticoles, pour protéger, hydrater et lutter contre le vieillissement des peaux mixtes, grasses et sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6230-7772-8360-d9868110be07', '__OWNER_ID__', 'Huile de Pépins de Figue de Barbarie (Opuntia ficus-indica)', 'huile-de-pepins-de-barbarie', 'L''huile anti-âge la plus puissante et rare, ultra-concentrée en vitamine E et acides gras essentiels, pour régénérer, raffermir et protéger les peaux matures, sèches et sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6230-7c9b-b655-74dfb65942ba', '__OWNER_ID__', 'Tournesol (Helianthus annuus L.)', 'huile-graines-tournesol', 'Le pilier de la barrière cutanée : une source exceptionnelle d''acide linoléique (Omega-6) pour restaurer, nourrir et protéger l''homéostasie des peaux sèches à atopiques. Variante hybride high-oleic disponible pour une stabilité oxydative supérieure et une conservation prolongée des formules.', '# L''Helianthus Annuus : L''Or Jaune de la Restructuration Lipidique
INSERT INTO public.ingredients VALUES ('019de0ab-6231-7e85-8be0-55a1b3ebafa1', '__OWNER_ID__', 'Glycosphingolipides (Glycosphingolipids)', 'glycosphingolipids', 'Lipides biomimétiques essentiels qui restaurent la barrière cutanée, améliorent l''hydratation profonde et renforcent la résilience des peaux sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6232-7a2b-8001-c26e55009739', '__OWNER_ID__', 'Hemp Oil (Cannabis Sativa Seed Oil)', 'cannabis-sativa-seed-oil', 'Huile de chanvre riche en oméga-3 et oméga-6 (ratio idéal 1:3), apaisante et réparatrice, adaptée aux peaux sèches, sensibles et atopiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6234-78fe-9767-c124682162cb', '__OWNER_ID__', 'Acide Malique (Malic Acid)', 'malic-acid', 'Un AHA naturel issu des pommes, offrant une exfoliation douce tout en favorisant le métabolisme énergétique cellulaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6232-7b1a-a9aa-d8a4cd2fd165', '__OWNER_ID__', 'Huile de Coton (Gossypium Herbaceum Seed Oil)', 'huile-coton', 'Une huile végétale douce et riche en acides gras essentiels, particulièrement appréciée pour son action relipidante et adoucissante sur les peaux fragiles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6236-742b-8368-6c2ae4d63ea8', '__OWNER_ID__', 'Adapalène (Adapalene)', 'adapalene', 'Rétinoïde de troisième génération hautement ciblé, utilisé pour réguler la kératinisation et traiter les lésions acnéiques.', '
INSERT INTO public.ingredients VALUES ('019e077b-683b-75b9-b86a-6b504a0bf33f', '__OWNER_ID__', 'Naringénine (Naringenin)', 'naringenin', 'Flavonoïde d''agrumes, antioxydant et anti-inflammatoire, partenaire de l''azélaïque pour les rougeurs.', '# Naringénine (Naringenin)
INSERT INTO public.ingredients VALUES ('019e077b-683b-7602-834c-832899876070', '__OWNER_ID__', 'Glucosylrutine (Glucosylrutin)', 'glucosylrutin', 'Forme glycosylée de la rutine, soluble et stable, antioxydant et photo-protecteur.', '# Glucosylrutine (Glucosylrutin)
INSERT INTO public.ingredients VALUES ('019de0ab-6236-7e5c-9847-ede9d21bacdd', '__OWNER_ID__', 'Trétinoïne (Acide rétinoïque all-trans)', 'tretinoine', 'L''actif de référence absolue en dermatologie pour le traitement de l''acné sévère et le photo-vieillissement cutané profond.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6233-75de-baf3-5c5d9b608219', '__OWNER_ID__', 'Protéase', 'protease', 'Enzyme naturelle qui digère les protéines de surface pour éliminer les cellules mortes en douceur, sans irritation acide.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6233-7730-9200-206fa7b5f255', '__OWNER_ID__', 'Papain', 'papain', 'Enzyme protéolytique naturelle extraite de la papaye, Papain offre une exfoliation enzymatique douce, élimine les cellules mortes, affine le grain de peau, apaise et illumine tout en étant adaptée aux peaux sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6233-794b-9902-29f721000509', '__OWNER_ID__', 'Malic Acid Ester (ester d’acide malique)', 'malic-acid-ester', 'Dérivé estérifié de l’acide malique, agent conditionneur et modulateur de texture haute tolérance.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6234-766b-9236-f6c55e6616b5', '__OWNER_ID__', 'AHA Esters', 'aha-esters', 'Esters d’AHA à libération prolongée pour une exfoliation douce et continue sans irritation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6234-770d-9f18-25d837b6ff90', '__OWNER_ID__', 'Ester d’Acide Malique', 'ester-acide-malique', 'AHA doux à libération modérée qui lisse le grain de peau tout en maintenant l’hydratation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6239-74c8-9254-889fd0f7383c', '__OWNER_ID__', 'Acetyl Tetrapeptide-15', 'acetyl-tetrapeptide-15', 'Peptide neuro-apaisant qui réduit la sensibilité cutanée en abaissant le seuil de réaction des terminaisons nerveuses (Skinasensyl™-like).', '# Acetyl Tetrapeptide-15
INSERT INTO public.ingredients VALUES ('019de0ab-6234-79d0-8199-5d4a2742932c', '__OWNER_ID__', 'Acide Succinique (Succinic Acid)', 'succinic-acid', 'Un actif polyvalent aux propriétés antibactériennes et exfoliantes douces, idéal pour les peaux sujettes aux imperfections.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6234-7a91-a105-128bad02f9d9', '__OWNER_ID__', 'Retinyl Acetate', 'retinyl-acetate', 'Ester de vitamine A stable et discret, offrant une introduction tout en douceur au monde des rétinoïdes pour les peaux qui privilégient la sérénité et la constance.', '
INSERT INTO public.ingredients VALUES ('019e077b-683b-763d-a7a5-b4e85641a8f2', '__OWNER_ID__', 'Rutine (Rutin)', 'rutin', 'Glycoside de la quercétine, antioxydant flavonoïde et veinotonique.', '# Rutine (Rutin)
INSERT INTO public.ingredients VALUES ('019de0ab-6231-7d3b-b21f-8a9134b2b57b', '__OWNER_ID__', 'Cholestérol (Cholesterol)', 'cholesterol', 'Lipide biomimétique fondamental qui rétablit la cohésion de la barrière cutanée et optimise la souplesse des peaux matures et sèches.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6234-7c46-b809-a1540455ec22', '__OWNER_ID__', 'Retinyl Linoleate', 'retinyl-linoleate', 'Ester rare et raffiné de vitamine A, lié à l’acide linoléique pour une touche de confort lipidique et une douceur renforcée dans les soins les plus attentifs.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6234-7d0a-9b36-20352fc01dd0', '__OWNER_ID__', 'Isotretinoin (topique)', 'isotretinoin', 'Isomère 13-cis de l’acide rétinoïque, utilisé en topique pour des indications spécifiques sévères, sous contrôle médical strict.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6234-7e13-b227-9d03cfb8b3b9', '__OWNER_ID__', 'Alitretinoin', 'alitretinoin', 'Rétinoïde pan-agoniste (9-cis-acide rétinoïque), référence systémique pour l’eczéma chronique sévère des mains, avec un profil d’efficacité reconnu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6239-756c-9a8f-5a1028bc36f3', '__OWNER_ID__', 'Acetyl Hexapeptide-51 Amide', 'acetyl-hexapeptide-51-amide', 'Peptide modulateur de l''inflamm-aging qui rééquilibre la réponse immunitaire cutanée et favorise un teint uniforme.', '# Acetyl Hexapeptide-51 Amide
INSERT INTO public.ingredients VALUES ('019de0ab-6235-7245-9f56-0aa0e0698a98', '__OWNER_ID__', 'Tazarotene', 'tazarotene', 'Rétinoïde de synthèse ultra-puissant, reconnu pour son action ciblée et profonde sur l’acné sévère, le psoriasis et le photo-vieillissement marqué.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6235-72ec-b47b-f43e51c9cce6', '__OWNER_ID__', 'Trifarotene', 'trifarotene', 'Rétinoïde de 4e génération ultra-sélectif (RAR-γ), conçu pour une action précise sur l’acné du visage et du corps avec une tolérance améliorée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6235-7378-b224-c22cee0e9ca0', '__OWNER_ID__', 'Retinyl Propionate', 'retinyl-propionate', 'Ester de rétinol plus stable et légèrement plus actif que le palmitate, offrant un équilibre subtil entre douceur et efficacité progressive.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6235-7524-8a44-ad3ba84f9a87', '__OWNER_ID__', 'Sodium Retinoyl Hyaluronate', 'sodium-retinoyl-hyaluronate', 'Un ingrédient innovant liant l’acide hyaluronique à l’acide rétinoïque pour hydrater tout en lissant le grain de peau.', '
INSERT INTO public.ingredients VALUES ('019e077b-683b-74f2-8fc2-a45a0e0c8623', '__OWNER_ID__', 'Dimethylmethoxy Chromanol (Lipochroman)', 'dimethylmethoxychromanol', 'Antioxydant bi-mode hydro/liposoluble, neutralise ROS et RNS, complément à la vitamine E.', '# Dimethylmethoxy Chromanol (Lipochroman)
INSERT INTO public.ingredients VALUES ('019e077b-683b-7545-8c35-b00f2eb8e8b9', '__OWNER_ID__', 'Tetrahydrodiferuloylmethane (THC)', 'tetrahydrodiferuloylmethane', 'Tétrahydrocurcuminoïde, dérivé incolore et stable de la curcumine, anti-inflammatoire et anti-pigmentation.', '# Tetrahydrodiferuloylmethane (THC)
INSERT INTO public.ingredients VALUES ('019de0ab-6240-7f71-a303-3c40b09d8f49', '__OWNER_ID__', 'Gluconate de Manganèse (Manganese Gluconate)', 'manganese-gluconate', 'L''oligo-élément catalyseur de la régénération dermique : un booster de la synthèse de collagène et un antioxydant cellulaire majeur pour la résilience cutanée.', '# Le Gluconate de Manganèse : Le Catalyseur de la Jeunesse Cellulaire
INSERT INTO public.ingredients VALUES ('019de0ab-6237-7a4f-9b5b-67ff707a3b8b', '__OWNER_ID__', 'Complexe de Peptides (Peptide Complex)', 'peptide-complex', 'Une synergie de messagers cellulaires conçue pour orchestrer la communication entre les couches de la peau et relancer les mécanismes de jeunesse.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6237-7b50-acda-81ca6d1dd022', '__OWNER_ID__', 'Tetrapeptide-21', 'tetrapeptide-21', 'Un peptide de communication de nouvelle génération, spécifiquement conçu pour booster la synthèse de collagène et réduire l’apparence des rides.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6237-7c1f-9932-c954d299078b', '__OWNER_ID__', 'Copper Palmitoyl Heptapeptide-14', 'copper-palmitoyl-heptapeptide-14', 'Un peptide "intelligent" encapsulé utilisant un système de drone pour délivrer du cuivre directement aux cellules productrices de collagène.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6237-7cd1-99e8-811fec9f5b39', '__OWNER_ID__', 'Heptapeptide-15 Palmitate', 'heptapeptide-15-palmitate', 'Partie intégrante de la technologie de drone, ce peptide aide à lisser les rides d’expression en ciblant les neurones cutanés.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6237-7d70-8469-7acc02450861', '__OWNER_ID__', 'Copper Tripeptide-1 Palmitamide', 'copper-tripeptide-1-palmitamide', 'Une forme stabilisée du peptide de cuivre, célèbre pour ses propriétés exceptionnelles de réparation tissulaire et de remodelage cutané.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6237-7e28-8cb3-e605e9d00f8a', '__OWNER_ID__', 'Trifluoroacetyl Tripeptide-2', 'trifluoroacetyl-tripeptide-2', 'Un peptide inhibiteur de la Progérine, la protéine marqueur du vieillissement cellulaire, pour lutter contre le relâchement et la ptose cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6237-7f0f-898e-671b89599793', '__OWNER_ID__', 'Tripeptide-1', 'tripeptide-1', 'Un peptide messager qui stimule la synthèse de protéines clés et aide à protéger la peau contre les dommages induits par l’environnement.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6231-7fcb-9315-9e8734910999', '__OWNER_ID__', 'Phytosphingosine', 'phytosphingosine', 'Lipide sphingoid naturel et skin-identical, précurseur des céramides, renforçant la barrière cutanée, antimicrobien, anti-inflammatoire et apaisant pour peaux sensibles, atopiques ou acnéiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6238-705c-81c0-248afdb71533', '__OWNER_ID__', 'Phyto-Rétinol (TGF-beta2)', 'nicotiana-benthamiana-hexapeptide-40-sh-polypeptide-76', 'Facteur de croissance végétal agissant comme un "rétinol-like" booster de collagène, sans les effets irritants du rétinol classique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6238-7117-9f46-1e1333ee7673', '__OWNER_ID__', 'EGF (Plant-derived)', 'nicotiana-benthamiana-hexapeptide-40-sh-oligopeptide-1', 'Epidermal Growth Factor (EGF) végétal qui accélère le renouvellement cellulaire et répare la barrière cutanée pour une peau visiblement plus jeune.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6238-71c3-9bc8-932bd8b4501d', '__OWNER_ID__', 'Myristoyl Nonapeptide-3', 'myristoyl-nonapeptide-3', 'Peptide de nouvelle génération mimant les effets du rétinol pour stimuler le renouvellement cellulaire sans aucune irritation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6238-7473-b294-5386c0bb0460', '__OWNER_ID__', 'Acetyl Dipeptide-1 Cetyl Ester (Calmosensine™ / Idealift™)', 'acetyl-dipeptide-1-cetyl-ester', 'Peptide neurosensoriel de pointe alliant apaisement immédiat des peaux hypersensibles et renforcement structurel anti-relâchement.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6239-7437-a54d-65d24c3df097', '__OWNER_ID__', 'Syn-Ake', 'syn-ake', 'Peptide inspiré du venin de serpent, relaxe les muscles pour effet anti-rides expressifs.', '# Syn-Ake
INSERT INTO public.ingredients VALUES ('019de0ab-6239-760b-87af-129e692ca756', '__OWNER_ID__', 'Beet Root Extract (Beta Vulgaris Root Extract)', 'beet-root-extract', 'Extrait de betterave riche en antioxydants et vitamines, hydrate, illumine et protège la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6239-76e5-9475-7c5ecdd9c76e', '__OWNER_ID__', 'Gardenia Fruit Extract (Gardenia Jasminoides Fruit Extract)', 'gardenia-fruit-extract', 'Extrait de fruit aux propriétés antioxydantes et protectrices, illumine, apaise et protège contre la lumière bleue et le stress environnemental.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6239-77a2-9381-249de76a0821', '__OWNER_ID__', 'Hibiscus Sabdariffa (Hibiscus Sabdariffa Flower Extract)', 'hibiscus-sabdariffa', 'Extrait floral riche en antioxydants et acides organiques, utilisé pour booster l''éclat, raffermir et protéger la peau contre le vieillissement oxydatif.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623a-795e-818e-0041aad6f3b1', '__OWNER_ID__', 'NAD (Nicotinamide Adénine Dinucléotide)', 'nad', 'Coenzyme essentielle au métabolisme énergétique cellulaire, elle aide à réparer l’ADN et à ralentir le vieillissement biologique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6239-78aa-82bb-4926f9277522', '__OWNER_ID__', 'Vitamine K1 (Phytonadione)', 'vitamine-k1', 'Une vitamine essentielle pour la micro-circulation, reconnue pour atténuer les rougeurs diffuses et les cernes vasculaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6239-7a72-8771-0d20e811740d', '__OWNER_ID__', 'Astaxanthine (Haematococcus Pluvialis)', 'astaxanthine', 'Une micro-algue d’eau douce, source de l’astaxanthine, l’antioxydant le plus puissant de la nature, protégeant la peau contre le stress oxydatif et le vieillissement prématuré.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623a-73ec-870f-171f169513c6', '__OWNER_ID__', 'Grenade (Punica Granatum)', 'punica-granatum', 'Un "super-fruit" riche en acide punicique et en polyphénols, offrant une action régénérante intense et un soutien précieux aux peaux matures.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623a-755c-b76b-537976a82724', '__OWNER_ID__', 'Ergothionéine', 'ergothioneine', 'Acide aminé rare d’origine fongique qui protège les mitochondries et prévient le vieillissement prématuré lié aux UV et à la pollution.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623a-781e-948f-dbfcbd2f7bd9', '__OWNER_ID__', 'Ginseng (Panax Ginseng)', 'panax-ginseng', 'Racine adaptogène légendaire qui booste la microcirculation, stimule la production de collagène et revitalise les peaux fatiguées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623b-7023-b931-5adc6d94cfb3', '__OWNER_ID__', 'Ribose', 'ribose', 'Sucre naturel (pentose) qui stimule la synthèse d’ATP pour redonner de l’énergie et de l’éclat aux cellules cutanées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623b-7833-aa57-2d307c7a3f92', '__OWNER_ID__', 'Ascophyllum Nodosum Extract (Algue Brune)', 'ascophyllum-nodosum-extract', 'Algue précieuse aux vertus détoxifiantes et éclaircissantes, idéale pour drainer les poches et illuminer le regard.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623b-7ab8-a5a9-6db29569813d', '__OWNER_ID__', 'Romarin (Rosmarinus officinalis)', 'romarin', 'Actif antioxydant et purifiant puissant, idéal pour protéger la peau du stress oxydatif et réguler les peaux mixtes.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623b-7d12-86d4-6895eb6b2686', '__OWNER_ID__', 'Extrait de Sauge Rouge (Salvia miltiorrhiza)', 'salvia-miltiorrhiza', 'L''actif d''élite de la pharmacopée asiatique : un régulateur de la microcirculation et un bouclier anti-inflammatoire pour les peaux sensibles et urbaines.', '# La Sauge Rouge (Danshen) : L''Or Pourpre de la Neuro-Cosmétique
INSERT INTO public.ingredients VALUES ('019de0ab-623c-7453-917e-59d7c309b49d', '__OWNER_ID__', 'Hélichryse Italienne ou Immortelle (Helichrysum italicum (Roth) G. Don)', 'helichryse-immortelle', 'L''actif botanique d''exception du maquis méditerranéen : une signature biochimique unique dominée par les italidiones et l''acétate de néryle, offrant une action anti-hématome sans équivalent, un soutien documenté de la microcirculation, une stimulation de la synthèse de céramides et d''acide hyaluronique endogène, et une protection anti-oxydante dermique de premier plan.', '# L''Hélichryse Italienne : L''Or Corse de la Régénération Vasculaire et Cutanée
INSERT INTO public.ingredients VALUES ('019de0ab-623e-7f8f-af08-009f515c0bc4', '__OWNER_ID__', 'EGCG Glucoside (Epigallocatechin Gallatyl Glucoside)', 'egcg-glucoside', 'Une forme stabilisée de l’EGCG, le polyphénol le plus actif du thé vert, offrant des propriétés antioxydantes et anti-inflammatoires exceptionnelles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623d-71ee-8ec9-5bac67ba6079', '__OWNER_ID__', 'Schisandra sphenanthera', 'schisandra-sphenanthera', 'Baie adaptogène riche en lignanes, utilisée pour réduire les rougeurs chroniques et protéger la peau du stress oxydatif.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623d-7363-ba8f-b81f40b02a9d', '__OWNER_ID__', 'Extrait de plancton', 'plankton-extract', 'Actif d’origine marine riche en nutriments, utilisé pour ses propriétés apaisantes, régénérantes et protectrices.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623d-74a3-a509-0b515ef93762', '__OWNER_ID__', 'Myrtille (Vaccinium myrtillus)', 'vaccinium-myrtillus', 'Extrait végétal riche en anthocyanes, utilisé pour protéger les micro-vaisseaux et lutter contre le stress oxydatif.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623d-75e8-affd-670d6808184f', '__OWNER_ID__', 'Argousier', 'hippophae-rhamnoides', 'Extrait végétal riche en vitamines C et E, caroténoïdes et acides gras, utilisé pour ses propriétés antioxydantes et régénérantes.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623e-7eb1-adee-30faccf05eb4', '__OWNER_ID__', '3-O-Glyceryl Ascorbate', '3-glyceryl-ascorbate', 'Dérivé stable et hydrophile de la vitamine C, combinant les bénéfices antioxydants de l''ascorbate avec les propriétés hydratantes du glycérol.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623f-704b-87be-8ebdf71a8021', '__OWNER_ID__', 'Ginkgo Biloba Leaf Extract', 'ginkgo-biloba', 'Extrait de feuilles de ginkgo biloba, antioxydant puissant qui améliore la microcirculation, illumine le teint et ralentit le vieillissement cutané.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623f-70ee-9972-ad87e5b993d5', '__OWNER_ID__', 'Benzotriazolyl Dodecyl p-Cresol (Tinogard TT)', 'benzotriazolyl-dodecyl-p-cresol', 'Antioxydant stabilisant de formule (HALS / phénol encombré) qui protège les huiles, parfums et actifs sensibles à l''oxydation et à la lumière, prolongeant la durée de vie des produits.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623f-7196-bed3-7a9f928477f7', '__OWNER_ID__', 'Superoxide Dismutase (SOD)', 'superoxide-dismutase', 'Enzyme antioxydante endogène qui neutralise les superoxydes générés par UV et stress oxydatif, protégeant les fibroblastes et le collagène.', '# Superoxide Dismutase (SOD)
INSERT INTO public.ingredients VALUES ('019de0ab-623f-722c-8eba-87e49ef651b3', '__OWNER_ID__', 'Sophora Japonica Flower Extract', 'sophora-japonica-flower-extract', 'Extrait floral riche en rutine et flavonoïdes, antioxydant et veinotonique qui protège la microcirculation cutanée.', '# Sophora Japonica Flower Extract
INSERT INTO public.ingredients VALUES ('019de0ab-623f-72c3-8e36-990899000186', '__OWNER_ID__', 'Ascorbyl Tetraisopalmitate (THDA / VC-IP)', 'ascorbyl-tetraisopalmitate', 'Dérivé liposoluble stable de vitamine C : pénétration profonde, éclat, réduction taches et anti-âge doux. Faible irritation, idéal peaux sèches/sensibles, mais antioxydant in vitro limité.', '
  (Tetrahexyldecyl Ascorbate / Ascorbyl Tetraisopalmitate)
INSERT INTO public.ingredients VALUES ('019de0ab-623f-73f3-8d8d-0ced760ceee2', '__OWNER_ID__', 'Cistus Monspeliensis Extract', 'cistus-monspeliensis-extract', 'Extrait de ciste de Montpellier, plante méditerranéenne riche en polyphénols, antioxydant et astringent doux.', '# Cistus Monspeliensis Extract
INSERT INTO public.ingredients VALUES ('019de0ab-623f-74b6-b3f9-36710f79fa42', '__OWNER_ID__', 'Sulfate de Dextran Sodique (Sodium Dextran Sulfate)', 'sodium-dextran-sulfate', 'Un polysaccharide sulfaté apaisant et décongestionnant, qui cible les rougeurs et l''inconfort vasculaire des peaux sensibles et réactives.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623f-75a6-92ba-2ff673b3b180', '__OWNER_ID__', 'Noni (Morinda Citrifolia)', 'morinda-citrifolia', 'Extrait de fruit de Noni riche en vitamines, polysaccharides et antioxydants puissants (flavonoïdes, coumarines, iridoïdes). Protecteur cutané et régénérant traditionnel polynésien utilisé depuis 2000 ans.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623f-7831-aa52-48ddedb6cecb', '__OWNER_ID__', 'Gingembre (Zingiber Officinale)', 'zingiber-officinale', 'Extrait de rhizome de gingembre riche en gingérols et shogaols, reconnu pour ses propriétés tonifiantes, antioxydantes, anti-inflammatoires et stimulatrices de microcirculation cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623f-7a3b-8151-c18e81c55417', '__OWNER_ID__', 'Boswellia Serrata (Encens indien)', 'boswellia-serrata', 'Extrait de résine d''Encens indien riche en acides boswelliques, reconnu pour ses puissantes propriétés apaisantes, anti-inflammatoires et régénérantes. Traditionnellement utilisé en médecine Ayurvédique depuis des millénaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-7589-ba45-89da64c5b0e8', '__OWNER_ID__', 'Asparagopsis Armata Extract', 'asparagopsis-armata-extract', 'Extrait d’algue rouge reconnu pour ses propriétés anti-rougeurs et sa capacité à inhiber les médiateurs de l’inflammation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623f-7bf1-9db1-42506f8967b5', '__OWNER_ID__', 'Avoine Colloïdale', 'colloidal-oatmeal', 'Une poudre d’avoine ultra-fine reconnue pour ses propriétés anti-inflammatoires et protectrices des peaux atopiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623f-7cad-b449-1b4d3413a7c4', '__OWNER_ID__', 'Complexe de Centella (Centella Complex)', 'centella-complex', 'Une synergie de haute précision combinant les quatre molécules actives de l’Herbe du Tigre pour une régénération tissulaire et un apaisement hors pair.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623f-7e58-a8cd-391abf4fef0f', '__OWNER_ID__', 'Poivre du Sichuan (Zanthoxylum Bungeanum)', 'zanthoxylum-bungeanum', 'Un extrait botanique aux propriétés "Botox-like" immédiates, agissant sur les micro-tensions cutanées pour un effet lissant et apaisant instantané.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623f-7f1d-88b4-fd4749342ae2', '__OWNER_ID__', 'Cypres Toujours Vert (Cupressus Sempervirens)', 'cypres', 'Une essence boisée noble, reconnue pour ses propriétés décongestionnantes et tonifiantes, idéale pour restaurer la légèreté et la vitalité cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-7394-a412-8f840b693ba4', '__OWNER_ID__', 'Extrait de Pourpier', 'portulaca-oleracea', 'Plante riche en antioxydants et en oméga-3, connue pour ses propriétés apaisantes et anti-inflammatoires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-74e3-93c4-1e3804872faa', '__OWNER_ID__', 'Eau thermale Uriage', 'uriage-thermal-spring-water', 'Eau thermale isotonique unique, naturellement riche en minéraux et oligo-éléments, qui apaise, hydrate et renforce la barrière cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6232-7171-8021-988c578b7724', '__OWNER_ID__', 'Céramide NP', 'ceramide-np', 'Lipide clé de la barrière cutanée (anciennement Céramide 3).', '# Céramide NP
INSERT INTO public.ingredients VALUES ('019de0ab-6241-713f-b01f-f7022cdd7c07', '__OWNER_ID__', 'Bleuet des Champs (Centaurea cyanus L.)', 'bleuet', 'L’allié délicat du regard et des peaux fragiles : un hydrolat traditionnellement chéri pour apaiser, rafraîchir et décongestionner le contour des yeux, tout en caressant les épidermes sensibles d’une douceur naturelle.', '# Le Bleuet des Champs : Douceur Bleutée pour le Regard et la Peau
INSERT INTO public.ingredients VALUES ('019de0ab-6241-7350-a3e2-55c93377421c', '__OWNER_ID__', 'Hamamélis de Virginie (Hamamelis virginiana L.)', 'hammamelis', 'Extrait végétal astringent riche en tanins. Peut apporter un effet tonique et décongestionnant léger, mais nécessite prudence sur peaux sensibles ou rosacée en raison de son potentiel asséchant et irritant.', '# L’Hamamélis de Virginie : Astringent Botanique à Usage Ciblé
INSERT INTO public.ingredients VALUES ('019de0ab-6241-7922-857f-04acb6642d28', '__OWNER_ID__', 'Avoine Rhealba®', 'avena-sativa', 'Extrait d''avoine spécifique sélectionné pour sa haute concentration en molécules apaisantes et sa pureté.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6241-7d36-87d3-c212cbfaeeed', '__OWNER_ID__', 'Heartleaf (Houttuynia cordata)', 'heartleaf', 'Plante herbacée originaire d''Asie de l''Est, utilisée depuis des siècles en médecine traditionnelle coréenne et japonaise. Riche en flavonoïdes, polysaccharides et polyphénols, c''est un actif apaisant, antioxydant et antibactérien — star de la K-beauty pour les peaux sensibles et réactives.', '## Origine & identité
INSERT INTO public.ingredients VALUES ('019de0ab-6241-7bab-a8b7-9a2b2e0ec645', '__OWNER_ID__', 'Rhamnose', 'rhamnose', 'Sucre végétal haute performance qui réveille les fibroblastes pour relancer la production de collagène et de fibres élastiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6242-70de-bd79-d55910043674', '__OWNER_ID__', 'Extrait d''Épilobe', 'extrait-epilobe', 'Extrait de la plante Epilobium angustifolium (aussi appelée épilobe à feuilles étroites ou fireweed), réputé pour calmer les inflammations et les rougeurs cutanées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6242-7387-bf22-62290e9dfc2d', '__OWNER_ID__', 'Tasmannia Lanceolata Fruit Extract', 'tasmannia-lanceolata', 'Extrait de poivre de Tasmanie aux propriétés apaisantes immédiates, particulièrement efficace contre les démangeaisons et l’inconfort.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6241-7f7e-a1c7-79048e4751d7', '__OWNER_ID__', 'Aloe Vera', 'aloe-vera', 'Hydratant exceptionnel et réparateur naturel, riche en vitamines et minéraux pour apaiser et régénérer la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6242-7603-94a0-a96b0693e731', '__OWNER_ID__', 'Artemisia Annua Extract', 'artemisia-annua', 'Extrait d''armoise annuelle (*Artemisia annua*), actif K-beauty apaisant et anti-rougeurs aux propriétés anti-inflammatoires et antioxydantes reconnues.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6253-75ce-9062-2af3649cda32', '__OWNER_ID__', 'Phosphatidylethanolamine (PE)', 'phosphatidylethanolamine', 'Phospholipide structural majeur des membranes cellulaires et mitochondriales. Implique dans l''autophagie, la fusion membranaire et la synthese de phosphatidylserine.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6242-7694-979e-aa0c4476371a', '__OWNER_ID__', 'Maltooligosyl Glucoside', 'maltooligosyl-glucoside', 'Polysaccharide biomimétique apaisant qui module la réponse inflammatoire et limite l''activation anormale des défenses naturelles des peaux sensibles à tendance rosacée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6254-7bd1-9c79-e1e64c697461', '__OWNER_ID__', 'Zéaxanthine', 'zeaxanthine', 'Caroténoïde xanthophylle isomère de la lutéine, concentré au centre de la macula où il assure la protection des photorécepteurs contre la lumière bleue.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6242-7731-85b0-0206e1028ba4', '__OWNER_ID__', '1-Methylhydantoin-2-Imide', 'methylhydantoin-imide', 'Actif neuro-apaisant qui réduit la réponse nerveuse excessive (modulation TRPV1) responsable des sensations de chaleur, picotements et rougeurs sur peaux hyperréactives.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6242-77c6-abf9-4a78455fd915', '__OWNER_ID__', 'Gallyl Glucoside', 'gallyl-glucoside', 'Un actif biotechnologique issu de l’acide gallique, conçu pour réguler la réponse inflammatoire et réduire visiblement les rougeurs cutanées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6232-721d-b85d-e37739f5a609', '__OWNER_ID__', 'Céramide NS', 'ceramide-ns', 'Céramide non-hydroxylé. Composant majeur des lipides intercellulaires.', '# Céramide NS
INSERT INTO public.ingredients VALUES ('019de0ab-6243-758e-9901-b76d0f46ea6f', '__OWNER_ID__', 'Mélitane', 'melitane', 'Peptide pro-pigmentant (Acetyl Hexapeptide-1) qui stimule la mélanogenèse cutanée via les récepteurs MC1-R, favorisant un bronzage naturel et une meilleure photoprotection endogène.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6243-76e1-a5b0-9a1937e0d4aa', '__OWNER_ID__', 'Diacetyl Boldine', 'diacetyl-boldine', 'Dérivé acétylé de la boldine issu de l''écorce du boldo chilien, Diacetyl Boldine (Lumiskin™) est un actif éclaircissant et antioxydant qui inhibe la tyrosinase, réduit la pigmentation et protège contre le stress oxydatif pour un teint plus uniforme et lumineux.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6243-7871-a750-6b249a6ccac4', '__OWNER_ID__', 'Sepiwhite™ (Undecylenoyl Phenylalanine)', 'sepiwhite', 'Actif éclaircissant de référence qui régule la pigmentation à la source pour un teint uniforme et une réduction visible des taches.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6243-79e9-b102-3f29394c6f94', '__OWNER_ID__', 'Melasyl™ (La Molécule Multi-Brevets)', 'melasyl', 'Une innovation de rupture en neuro-cosmétique, conçue pour intercepter les précurseurs de mélanine avant qu’ils ne marquent la peau, offrant une correction pigmentaire d’une précision inédite.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6245-71a1-a2de-12727724ad2a', '__OWNER_ID__', 'Iris Florentina Root Extract', 'iris-extract', 'Extrait naturel de racine d’iris aux propriétés éclaircissantes, purifiantes et anti-âge.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7498-bbe6-4edb5a689523', '__OWNER_ID__', 'Microbiota Regulator', 'microbiota-regulator', 'Actif régulateur du microbiote cutané qui aide à maintenir l''équilibre de la flore bactérienne pour une peau saine.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6245-7248-8764-a5845c8e754a', '__OWNER_ID__', 'Phenylethyl Resorcinol (SymWhite 377)', 'phenylethyl-resorcinol', 'Un actif éclaircissant ultra-performant inspiré d’un composé naturel du pin sylvestre, reconnu pour son exceptionnelle capacité à réduire les taches et illuminer le teint.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6248-79a6-afcf-6f254c3a18e1', '__OWNER_ID__', 'Zinc Lactate', 'zinc-lactate', 'Un sel de zinc et d’acide lactique offrant une action séborégulatrice et antibactérienne, particulièrement efficace pour assainir les peaux grasses.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6245-7300-8075-6eaeced68628', '__OWNER_ID__', 'Pea Extract (Pisum Sativum Extract)', 'pea-extract', 'Extrait de pois riche en antioxydants et protéines, utilisé pour renforcer l''élasticité, apaiser et protéger la peau sensible.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6245-73d1-b447-142c4ed70562', '__OWNER_ID__', 'Arbre à thé', 'tea-tree', 'Huile essentielle réputée pour ses propriétés antibactériennes et assainissantes, idéale pour les peaux à imperfections.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6245-7468-8e25-f6f14ffabda0', '__OWNER_ID__', 'Copper Gluconate', 'copper-gluconate', 'Un sel de cuivre essentiel qui aide à purifier la peau tout en favorisant la régénération des tissus.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6251-75cf-a24f-a824562eb60e', '__OWNER_ID__', 'Melanin (Mélanine biomimétique)', 'melanin', 'Mélanine biomimétique utilisée comme pigment teintant et protecteur contre les UV et la lumière visible (HEV/lumière bleue).', '# Mélanine (Topique)
INSERT INTO public.ingredients VALUES ('019de0ab-6251-7990-a209-471558396f8f', '__OWNER_ID__', 'Berbérine', 'berberine', 'Alcaloïde végétal isoquinoléique, principalement étudié pour ses effets sur la glycémie, les lipides sanguins et le syndrome métabolique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6245-7fdd-b751-cdacb67f12dc', '__OWNER_ID__', 'Extrait de lentille (Lens esculenta seed extract)', 'lens-esculenta-seed-extract', 'Actif d''origine naturelle riche en oligosaccharides, conçu pour resserrer les pores et affiner durablement le grain de peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6246-7136-9d38-9ea49f6a5b2c', '__OWNER_ID__', 'Comedoclastin™ (Extrait de Silybum marianum)', 'comedoclastin', 'Actif végétal breveté issu du Chardon-marie qui réduit les imperfections et limite leur réapparition en agissant à la racine.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6246-73ca-b839-7c14084ae5a9', '__OWNER_ID__', 'Zinc Sulfate (sulfate de zinc)', 'zinc-sulfate', 'Sel minéral astringent et antimicrobien, régule le sébum et apaise les peaux à imperfections.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6247-702d-b766-293d6f43bfa1', '__OWNER_ID__', 'Acide hypochloreux', 'hypochlorous-acid', 'Composé naturellement produit par les globules blancs via la myéloperoxydase. Antimicrobien puissant à large spectre et anti-inflammatoire, mais extrêmement doux. Idéal pour peaux réactives, acnéiques, rosacée, eczéma et post-procédures.', '## Qu''est-ce que c''est ?
INSERT INTO public.ingredients VALUES ('019de0ab-6248-7640-b89c-94ed86bc779d', '__OWNER_ID__', 'Charcoal Powder', 'charcoal-powder', 'Charbon activé à haut pouvoir absorbant, idéal pour purifier les pores et détoxifier la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6248-7840-b0a6-691246febfc8', '__OWNER_ID__', 'Acnesyl-X-Pro', 'acnesyl-x-pro', 'Complexe anti-acné multi-actif pour le contrôle du sébum, l’action antibactérienne et anti-comédogène.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6251-7c4d-9e96-92e678712d5c', '__OWNER_ID__', 'Bêta-carotène', 'beta-carotene', 'Caroténoïde provitamine A abondant dans les fruits et légumes colorés, précurseur principal de la vitamine A (rétinol) dans l''organisme.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6251-7de2-933d-fb0030db7652', '__OWNER_ID__', 'CDP-Choline (Citicoline)', 'cdp-choline', 'Intermédiaire naturel de la biosynthèse de la phosphatidylcholine, fournissant choline et uridine au cerveau pour soutenir les membranes neuronales et la neurotransmission.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6248-7ad0-8792-926340d749e0', '__OWNER_ID__', 'Endothelyol®', 'endothelyol', 'Complexe biotechnologique breveté ciblant les micro-vaisseaux et l’inflammation pour réduire les rougeurs chroniques et passagères.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-720e-ac16-ed9bbba17c84', '__OWNER_ID__', 'Azecoglycine (Potassium Azeloyl Diglycinate)', 'azecoglycine', 'Complexe d’acide azélaïque et de glycine agissant en synergie pour réguler le sébum et apaiser les rougeurs.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6248-7b84-8222-83fab08e3112', '__OWNER_ID__', 'Brimonidine', 'brimonidine', 'Vasoconstricteur topique agoniste α2-adrénergique (prescription), traitement de l''érythème facial persistant de la rosacée. Réduction rapide des rougeurs en ~30 minutes.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6248-7c99-9b59-b0bb1d2243f1', '__OWNER_ID__', 'Oxymétazoline', 'oxymetazoline', 'Vasoconstricteur topique agoniste α1/α2-adrénergique (prescription), traitement de l''érythème facial persistant de la rosacée. Effet rapide mais rebond vasculaire plus marqué que la brimonidine.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624a-73d3-a846-6f800844dfaa', '__OWNER_ID__', 'Chicory Root Extract (Cichorium Intybus Root Extract)', 'inuline', 'Extrait de racine de chicorée prébiotique, hydrate, équilibre le microbiome et renforce la barrière cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6248-7dae-b36d-b442f4c2d501', '__OWNER_ID__', 'Métronidazole', 'metronidazole', 'Antibiotique et antiparasitaire topique (prescription), traitement de référence de la rosacée papulo-pustuleuse. Anti-inflammatoire cutané avec une longue histoire d''efficacité clinique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6248-7f03-b350-71250e2b0207', '__OWNER_ID__', 'Ivermectine', 'ivermectine', 'Antiparasitaire topique anti-Demodex (prescription), traitement de référence de la rosacée papulo-pustuleuse. Action combinée antiparasitaire et anti-inflammatoire supérieure au métronidazole dans les études comparatives.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-7053-916e-154b598ff721', '__OWNER_ID__', 'Angiopausine™ (Extrait de Silybum marianum)', 'angiopausine', 'Actif breveté d''origine naturelle qui réduit la néovascularisation pour traiter les rougeurs installées et la couperose.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6255-765c-be06-209f3f65a368', '__OWNER_ID__', 'Peroxyde de Carbamide (Carbamide Peroxide)', 'carbamide-peroxide', 'Une forme stable de peroxyde souvent utilisée pour le blanchiment à domicile.', 'Le peroxyde de carbamide se décompose lentement en libérant du peroxyde d''hydrogène. Cette libération progressive le rend plus doux et permet une application prolongée (souvent via des gouttières), ce qui est idéal pour un blanchiment progressif avec moins de sensibilité.', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.541+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, NULL);
INSERT INTO public.ingredients VALUES ('019de0ab-6249-7d48-b255-818ecf85b4fd', '__OWNER_ID__', 'TriAsorB™ (Phénylène Bis-Diphényltriazine)', 'triasorb', 'Filtre solaire ultra-large spectre protégeant contre les rayons UVB, UVA et la lumière bleue haute énergie.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624a-7016-9397-1233ff1ab039', '__OWNER_ID__', 'Isoamyl p-Methoxycinnamate (Amiloxate)', 'isoamyl-p-methoxycinnamate', 'Filtre UVB organique liposoluble, couramment utilisé dans les formules à filtres chimiques pour sa bonne efficacité UVB et sa texture légère.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6252-70da-9a0d-3bea8fd45d66', '__OWNER_ID__', 'Choline', 'choline', 'Nutriment essentiel impliqué dans la synthèse des membranes cellulaires, de l''acétylcholine et du métabolisme des groupes méthyle.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624a-7488-8228-0ae5c10b7856', '__OWNER_ID__', 'Pseudoalteromonas Ferment Extract', 'pseudoalteromonas-ferment', 'Un postbiotique marin issu de bactéries des grands fonds, reconnu pour ses propriétés hydratantes et protectrices contre le stress environnemental.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624a-7b0b-b7a8-26bf3f3b4bc6', '__OWNER_ID__', 'D-Sensinose™ (Extrait de fermentation d''Aquaphilus dolomiae)', 'd-sensinose', 'Actif postbiotique ultra-calmant breveté agissant directement sur les neurones sensoriels pour apaiser l''hyper-réactivité cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624a-7c9b-b006-b9a995827183', '__OWNER_ID__', 'C+ Restore™ (Aquaphilus dolomiae ferment filtrate)', 'aquaphilus-dolomiae-ferment-filtrate', 'Actif postbiotique breveté issu de l''Eau thermale d''Avène, favorisant la réparation épidermique et le renforcement des défenses cutanées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624a-7ee3-866b-cd49473bd533', '__OWNER_ID__', 'Extrait d’Aquaphilus dolomiae (I-modulia®)', 'aquaphilus-dolomiae-extract', 'Actif biotechnologique postbiotique apaisant et anti-démangeaisons, issu de l’eau thermale d’Avène, idéal pour les peaux sèches et atopiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7239-bfac-c27c5b4a3a33', '__OWNER_ID__', 'Postbiotiques', 'postbiotics', 'Substances actives produites par les bactéries bénéfiques, offrant une action ciblée sur l’apaisement et la régénération cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-70ad-a83a-dd538a2a39cf', '__OWNER_ID__', 'Ruscus aculeatus (Petit-houx)', 'ruscus-aculeatus', 'Extrait racinaire du Petit-houx, arbuste sempervirent méditerranéen aux vertus veinotoniques reconnues. Riche en saponines stéroïdiennes, il améliore la microcirculation, réduit rougeurs et œdèmes, et apaise les peaux sensibles ou sujettes à couperose — un pilier discret mais puissant de la phytothérapie vasculaire européenne.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624c-7962-8c47-8aa560f510f3', '__OWNER_ID__', 'Hydrolyzed Lupine Protein', 'hydrolyzed-lupine-protein', 'Hydrolysat de protéines de lupin riche en peptides végétaux, stimule la fermeté et lisse les rides par activation de la synthèse de fibrilline.', '# Hydrolyzed Lupine Protein
INSERT INTO public.ingredients VALUES ('019de0ab-624c-7a06-8af1-a039b99538c0', '__OWNER_ID__', 'Trimethoxybenzyl Acetylsinapate', 'trimethoxybenzyl-acetylsinapate', 'Ester sinapique anti-glycation et photoprotecteur antioxydant, protège les fibres collagène/élastine du vieillissement induit par le sucre.', '# Trimethoxybenzyl Acetylsinapate
INSERT INTO public.ingredients VALUES ('019de0ab-624c-7c44-9143-c58fbce0e2a0', '__OWNER_ID__', 'Arnica des Montagnes (Arnica montana L.)', 'arnica', 'L''or jaune des alpages : un trésor botanique aux propriétés anti-inflammatoires et apaisantes, soutenu par une tradition millénaire et des recherches scientifiques prometteuses, pour une récupération cutanée optimisée.', '# L''Arnica Montana : L''Alliée Naturelle pour une Récupération Harmonieuse
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7345-b27f-3afbac3e0484', '__OWNER_ID__', 'Probiotiques', 'probiotics', 'Micro-organismes bénéfiques (sous forme de lysats) qui renforcent le microbiome cutané et les défenses naturelles de la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7799-8616-e34f98448fd4', '__OWNER_ID__', 'Acmella Oleracea Extract', 'acmella-oleracea-extract', 'Extrait végétal ''Botox-like'' naturel, relaxe les muscles faciaux pour lisser rides d''expression et raffermir la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7857-9aba-13d9bcdfa15e', '__OWNER_ID__', 'Complexe de Protéoglycanes', 'proteoglycan-complex', 'Complexe de protéoglycanes (décorines, versicane, perlécane) imitant les composants structurels naturels de la peau. Restaure densité et élasticité cutanée, hydrate profondément, retarde vieillissement visible.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7cfe-b1cc-fefc33a8fed7', '__OWNER_ID__', 'Acide Asiatique (Asiatic Acid)', 'asiatic-acid', 'Fraction pure et cristalline extraite de la Centella Asiatica, l’acide asiatique est un architecte de la reconstruction cutanée, stimulant la synthèse du collagène tout en apaisant les inflammations.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7eb1-83df-0b0fb3cbf1e7', '__OWNER_ID__', '2-Oleamido-1,3-Octadecanediol', '2-oleamido-1-3-octadecanediol', 'Un lipide synthétique biomimétique (Céramide R) agissant comme un renfort structurel pour protéger la fibre capillaire et le ciment intercellulaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7f85-a9d4-12f03335b079', '__OWNER_ID__', 'Chardon-Marie (Silybum marianum)', 'chardon-marie', 'Actif végétal breveté d’Avène issu des achènes du Chardon-Marie. Nourrissant intense, renforce la barrière cutanée, limite les imperfections et apaise les peaux sèches, atopiques ou acnéiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624c-70dc-b520-c5630182da3d', '__OWNER_ID__', 'Hydroxypalmitoyl Sphinganine', 'hydroxypalmitoyl-sphinganine', 'Un précurseur de céramide biomimétique conçu pour relancer la production naturelle de lipides et restaurer l’étanchéité de la barrière cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6252-7567-91d5-51386f338eb4', '__OWNER_ID__', 'Ergothionéine', 'ergothioneine-supplement', 'Acide aminé soufré non synthétisé par les mammifères, transporté par un système dédié (OCTN1) et considéré comme une potentielle « vitamine de longévité » grâce à sa stabilité antioxydante exceptionnelle.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-74fe-9b6e-62d77c35c6e4', '__OWNER_ID__', 'Gleditsia Seed Extract (Gleditsia Triacanthos Seed Extract)', 'gleditsia-seed-extract', 'Extrait de graines d''acacia à miel, antioxydant et protecteur, utilisé pour conditionner peau et cheveux tout en stabilisant les formules.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-79ad-ad17-2444d2f8ac79', '__OWNER_ID__', 'Ahnfeltia Concinna Extract', 'ahnfeltia-concinna', 'Un extrait d’algue rouge des eaux profondes de l’Océan Pacifique, riche en minéraux et en polymères marins pour une hydratation longue durée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-777d-8073-edad8b779e4d', '__OWNER_ID__', 'Sodium Lauroyl Methyl Isethionate', 'sodium-lauroyl-methyl-isethionate', 'Tensioactif anionique doux offrant une mousse crémeuse et un nettoyage efficace tout en restant plus tolérant que les sulfates classiques.', '
INSERT INTO public.ingredients VALUES ('019e077b-683b-7b74-9c21-3a8bd78dd064', '__OWNER_ID__', 'Cocamidopropyl Hydroxysultaine', 'cocamidopropyl-hydroxysultaine', 'Tensioactif amphotère doux dérivé de coco, mousse onctueuse, tolérance excellente, alternative au cocamidopropyl betaine.', '# Cocamidopropyl Hydroxysultaine
INSERT INTO public.ingredients VALUES ('019de0ab-624d-7e5d-9bf2-c5646d6385a5', '__OWNER_ID__', 'Verveine Officinale (Verbena officinalis)', 'verveine', 'Actif tonifiant et clarifiant aux vertus apaisantes, idéal pour réveiller l''éclat des peaux fatiguées et stressées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-7b66-b900-0c569ce8ea33', '__OWNER_ID__', 'Extrait d’Écorce de Saule Noir', 'salix-nigra', 'Extrait végétal naturellement riche en dérivés salicylés, utilisé pour purifier la peau et favoriser le renouvellement cellulaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-7c46-ac83-8762a0f98d8e', '__OWNER_ID__', 'Extrait de Riz', 'oryza-sativa', 'Extrait issu du riz, reconnu pour ses propriétés apaisantes, antioxydantes et éclaircissantes douces.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6252-77f1-9f51-82145b4a1be7', '__OWNER_ID__', 'GAA (Acide guanidinoacétique)', 'gaa', 'Précurseur direct de la créatine, avec l''avantage de traverser la barrière hémato-encéphalique via plusieurs transporteurs, augmentant la créatine cérébrale plus efficacement que la créatine elle-même.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6252-79b0-9c58-4c08de84d718', '__OWNER_ID__', 'Glucosamine', 'glucosamine-supplement', 'Aminosaccharide naturellement présent dans le cartilage, étudié pour le soutien articulaire et associé dans des études observationnelles à une réduction de la mortalité cardiovasculaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-7ceb-ab7c-d102f7bb4f9c', '__OWNER_ID__', 'Orange Douce', 'citrus-aurantium-dulcis', 'Extrait ou huile essentielle d’orange douce, utilisée pour ses propriétés tonifiantes, antioxydantes et son parfum naturel frais.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-7dbd-adbb-cff80e31b6eb', '__OWNER_ID__', 'Hydrocolloïde', 'hydrocolloid', 'Une technologie de gel absorbant qui crée un milieu humide optimal pour la cicatrisation tout en protégeant la plaie des agressions extérieures.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7577-be81-4b140e3a4d53', '__OWNER_ID__', 'Corn Starch Modified (Amidon de Maïs Modifié)', 'corn-starch-modified', 'Amidon de maïs réticulé (Distarch Phosphate) utilisé comme texturant absorbant qui matifie la peau et donne un toucher poudré sans dessécher.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624f-707b-8ecd-7516c59e2df4', '__OWNER_ID__', 'Hydroxypropyl Methylcellulose', 'hydroxypropyl-methylcellulose', 'Épaississant cellulosique utilisé pour texturer les formules aqueuses.', '# Hydroxypropyl Methylcellulose (HPMC)
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7b3d-8344-4f6aa5488e63', '__OWNER_ID__', 'Potassium Chloride', 'potassium-chloride', 'Sel de potassium utilisé pour ajuster la tonicité des formules.', '# Potassium Chloride
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7d17-9e51-c708451c5edc', '__OWNER_ID__', 'NMN (Nicotinamide Mononucléotide)', 'nmn', 'Un nucléotide précurseur du NAD+ qui booste l’énergie cellulaire et répare les dommages à l’ADN pour un effet anti-âge systémique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7dda-8557-8f34d714ec5e', '__OWNER_ID__', 'Myrte Commun (Myrtus Communis Leaf Extract)', 'myrtus-communis-leaf-extract', 'Un extrait végétal méditerranéen qui stimule les protéines de longévité cellulaire et limite la glycation des tissus.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7e9c-bac9-fdfb150d102e', '__OWNER_ID__', 'Vigne du Tonnerre (Tripterygium Wilfordii Callus Extract)', 'tripterygium-wilfordii-callus-extract', 'Un extrait de culture cellulaire (callus) utilisé en médecine traditionnelle pour ses propriétés anti-inflammatoires puissantes et sa capacité de régénération.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7f65-8850-19bcc84ab47d', '__OWNER_ID__', 'Laminaire (Laminaria Digitata)', 'laminaria-digitata', 'Une algue brune riche en alginates et sels minéraux, idéale pour revitaliser la barrière cutanée et maintenir l’équilibre osmotique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-7037-ae4f-cb8f66f7512f', '__OWNER_ID__', 'Fucus (Fucus Vesiculosus)', 'fucus-vesiculosus', 'Une algue brune riche en iode et polyphénols, utilisée pour drainer les tissus et décongestionner les zones gonflées comme le contour des yeux.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-70d1-87ca-1dd0ded6117a', '__OWNER_ID__', 'Alaria (Alaria Esculenta)', 'alaria-esculenta', 'Une algue brune surnommée "Wakamé de l’Atlantique", capable de booster la synthèse de collagène et de protéger l’élasticité de la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6253-7b6d-8a45-37eb8ce4d38d', '__OWNER_ID__', 'Psyllium (Ispaghul)', 'psyllium', 'Fibre soluble naturelle issue des teguments de Plantago ovata. Ameliore le transit, le cholesterol, la glycemie et la sante du microbiote intestinal avec un niveau de preuve eleve.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6253-7ceb-8b8d-b0fc82ba3ed7', '__OWNER_ID__', 'Spiruline', 'spiruline', 'Cyanobacterie riche en proteines, fer et phycocyanine. Source nutritionnelle dense mais controversee en raison des risques de contamination et de sa pseudo-vitamine B12 inactive.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-7162-91e0-334e9344d96a', '__OWNER_ID__', 'Wakamé (Undaria Pinnatifida)', 'undaria-pinnatifida', 'Une algue brune emblématique qui protège la matrice extracellulaire et réactive les gènes de jeunesse de la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6252-7d82-bddb-c1e8665346e1', '__OWNER_ID__', 'Lutéine', 'luteine', 'Caroténoïde xanthophylle concentré dans la macula de l''œil, essentiel à la protection rétinienne et associé au soutien de la fonction cognitive.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-722a-b48c-4990a7536a58', '__OWNER_ID__', 'Mousse d''Irlande (Chondrus Crispus)', 'chondrus-crispus', 'Une algue rouge filmogène qui protège la peau de la déshydratation et apporte un fini soyeux naturel aux formules.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-72e9-903e-01faf901f73e', '__OWNER_ID__', 'Dulse (Palmaria Palmata)', 'palmaria-palmata', 'Une algue rouge reconnue pour ses propriétés tonifiantes qui favorisent une peau lumineuse et unifiée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-73a0-972b-1ea02178c19f', '__OWNER_ID__', 'Jania Rubens (Algue Rouge Calcaire)', 'jania-rubens', 'Une algue rouge rare à structure calcaire, capable de recharger les cellules en énergie et d’offrir une hydratation ultra-ciblée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-7473-84eb-0adc326d8275', '__OWNER_ID__', 'Laitue de Mer (Ulva Lactuca)', 'ulva-lactuca', 'Une algue verte riche en magnésium et acides aminés, qui aide à maintenir l’élasticité de la peau en limitant sa dégradation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-750f-9def-615ad3069c85', '__OWNER_ID__', 'Chlorelle (Chlorella Vulgaris)', 'chlorella-vulgaris', 'Une micro-algue verte riche en chlorophylle et peptides, utilisée pour réduire la visibilité des vaisseaux (cernes) et raffermir la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6253-7e63-82cf-072a1a8363b1', '__OWNER_ID__', 'Taurine', 'taurine-supplement', 'Acide amine soufre semi-essentiel, abondant dans le cerveau, le coeur et les muscles. Implique dans l''osmoregulation, la neuroprotection, la fonction cardiovasculaire et la performance physique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6254-70c6-a8bf-76d7b7f41d4e', '__OWNER_ID__', 'TMG (Trimethylglycine / Betaine)', 'tmg', 'Donneur de groupes methyle derive de la glycine, implique dans le cycle de la methionine. Reduit l''homocysteine et soutient la methylation. Approuve FDA pour l''homocystinurie.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-75a8-9992-4fbab04a4369', '__OWNER_ID__', 'Spiruline (Spirulina Platensis)', 'spirulina-platensis', 'Une micro-algue bleue (cyanobactérie) considérée comme un super-aliment, offrant une dose massive de protéines et d’antioxydants.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-763c-9e72-d1acc9b7909e', '__OWNER_ID__', 'Dunaliella Salina (Micro-algue Orangée)', 'dunaliella-salina', 'Une micro-algue qui survit dans les milieux hypersalins en produisant une quantité phénoménale de bêta-carotène.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-777e-acd5-da7131e78b28', '__OWNER_ID__', 'Algue Bleue (Aphanizomenon Flos-aquae)', 'aphanizomenon-flos-aquae', 'Une cyanobactérie sauvage du lac Klamath, considérée comme un "super-aliment" cutané offrant un effet lissant comparable au rétinol sans l’irritation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-782c-acb0-f64e3b4f2bbb', '__OWNER_ID__', 'Vétiver (Vetiveria Zizanoides)', 'vetiveria-zizanoides', 'Une racine d’ancrage aux propriétés cicatrisantes et apaisantes, reconnue pour favoriser la régénération tissulaire tout en équilibrant le sébum.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-78e7-87dd-1f9a292b5282', '__OWNER_ID__', 'Huile de Pin des Marais (Pinus Palustris)', 'pinus-palustris', 'Un extrait résineux aux vertus tonifiantes et purifiantes, apportant la force des forêts boréales pour revitaliser les peaux ternes et fatiguées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6254-72d4-abfe-8ea9b9a82e33', '__OWNER_ID__', 'Vitamine B12 (Cobalamine)', 'vitamine-b12', 'Vitamine hydrosoluble essentielle au fonctionnement du systeme nerveux, a la formation des globules rouges et a la synthese de l''ADN. Exclusivement d''origine animale ou bacterienne.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6254-7562-88d0-575c91c50b04', '__OWNER_ID__', 'Vitamine C (Acide ascorbique)', 'vitamine-c-supplement', 'Vitamine hydrosoluble essentielle, puissant antioxydant et cofacteur de la synthese du collagene. Non synthetisee par l''organisme humain, elle doit etre apportee par l''alimentation ou la supplementation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6252-7f04-9e42-2d360ca57222', '__OWNER_ID__', 'Magnésium', 'magnesium-supplement', 'Minéral essentiel impliqué dans plus de 600 réactions enzymatiques. Cofacteur de l''ATP, régulateur neuromusculaire et cardiovasculaire, fréquemment déficient dans l''alimentation moderne.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6253-7156-ac0b-817e6ba4558e', '__OWNER_ID__', 'NAC (N-Acetylcysteine)', 'nac', 'Derive synthetique de la cysteine, precurseur du glutathion (principal antioxydant endogene). Medicament essentiel OMS, utilise en pneumologie, toxicologie et psychiatrie.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6253-7386-ac20-da7106483ce7', '__OWNER_ID__', 'Omega-3 (EPA + DHA)', 'omega-3', 'Acides gras polyinsatures essentiels impliques dans la structure des membranes neuronales (DHA) et la resolution de l''inflammation (EPA). Benefices cardiovasculaires et cognitifs documentes.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-7994-9859-dc008a51518f', '__OWNER_ID__', 'Huile de Babassu (Orbignya Oleifera)', 'huile-babassu', 'Une huile précieuse d’Amazonie, alternative légère à l’huile de coco, offrant une nutrition intense et une action protectrice sans fini gras.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-7a34-a3b8-001ed998306a', '__OWNER_ID__', 'Acides Aminés de Riz (Rice Amino Acids)', 'rice-amino-acids', 'Un cocktail de micro-nutriments essentiels issus de la protéine de riz, agissant comme des briques élémentaires pour reconstruire la barrière cutanée et fortifier la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-7ae1-a10c-9cba85a4139a', '__OWNER_ID__', 'Isosorbide Dicaprylate', 'isosorbide-dicaprylate', 'Un "boosteur" d’hydratation bio-sourcé qui régule l’expression des aquaporines pour optimiser la circulation de l’eau entre les couches de la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-7bb0-a6bb-330263d48352', '__OWNER_ID__', 'Amarante (Amaranthus Caudatus)', 'amaranthus', 'Source exceptionnelle de squalène naturel et d’acides gras, elle renforce la barrière lipidique et adoucit la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-7c5c-bb02-4a1e788e8dbc', '__OWNER_ID__', 'Extrait de Graines de Roucou (Bixa Orellana Seed Extract)', 'bixa-orellana', 'L''actif ''Sun-Prep'' et perfecteur : un concentré de caroténoïdes pour une protection antioxydante naturelle et un effet flouteur de pores immédiat.', '# Le Roucou (Urucum) : L''Actif Protecteur et Sublimateur du Teint
INSERT INTO public.ingredients VALUES ('019de0ab-6251-7536-8a0b-a3db3f642b03', '__OWNER_ID__', 'Glyceryl Caprylate/Caprate', 'glyceryl-caprylate-caprate', 'Mono-ester de glycérine et d''acides gras moyens à action conservatrice douce et émolliente, souvent utilisé en système de conservation naturel.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-7e5a-90a9-d98d1187feca', '__OWNER_ID__', 'Ophiopogon japonicus', 'ophiopogon-japonicus', 'Extrait racinaire utilisé pour ses propriétés hydratantes, apaisantes et sa capacité à réguler les sensations d’échauffement.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6250-7f73-bcf5-f59c347f6a08', '__OWNER_ID__', 'Humectants, émollients et occlusifs', 'humectants-emollients-occlusifs', 'Les trois piliers de l''hydratation cutanée. Les humectants attirent l''eau, les émollients lissent et renforcent la barrière, les occlusifs scellent l''hydratation et limitent la TEWL.', '## Les trois catégories
INSERT INTO public.ingredients VALUES ('019de0ab-6251-702e-abbb-d5833c099956', '__OWNER_ID__', 'Peptides', 'peptides', 'Chaînes d''acides aminés qui boostent le collagène et raffermissent.', '# Peptides
INSERT INTO public.ingredients VALUES ('019de0ab-6251-70c3-8e19-f6d37cef0dc5', '__OWNER_ID__', 'Spinacia Oleracea (Spinach) Leaf Extract', 'spinacia-oleracea', 'Extrait de feuilles d''épinard riche en antioxydants (flavonoïdes, caroténoïdes), protège la peau des agressions environnementales et de la pollution.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6251-715f-9c5f-1ac594b018bf', '__OWNER_ID__', 'Taraxacum Officinale (Dandelion) Leaf Extract', 'taraxacum-officinale', 'Extrait de pissenlit aux propriétés détoxifiantes et antioxydantes, aide à purifier la peau des toxines environnementales.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6251-7208-8743-bfc8dbc3fd3d', '__OWNER_ID__', 'Aristotelia Chilensis (Maqui Berry) Fruit Extract', 'aristotelia-chilensis', 'Extrait de maqui berry du Chili, l''un des antioxydants les plus puissants connus, protège contre le stress oxydatif et la pollution.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6251-72d9-a2b0-063c275ca7a4', '__OWNER_ID__', 'Tephrosia Purpurea Seed Extract', 'tephrosia-purpurea', 'Extrait de graines de Tephrosia purpurea aux propriétés anti-pollution et protectrices contre les facteurs environnementaux.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6254-779f-9408-425178ddda03', '__OWNER_ID__', 'Vitamine D3 (Cholecalciferol)', 'vitamine-d3', 'Vitamine liposoluble essentielle a la sante osseuse, immunitaire et musculaire. Synthetisee par la peau sous l''effet des UVB, souvent deficitaire en Europe du Nord.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6253-77b9-84c4-8889d27aa9e5', '__OWNER_ID__', 'Phosphatidylinositol (PI)', 'phosphatidylinositol', 'Phospholipide minoritaire mais crucial pour la signalisation cellulaire. Ses derives phosphoryles (PIP2, PIP3) controlent la proliferation, le trafic membranaire et la reponse a l''insuline.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6253-7968-80f1-0e1b1957d001', '__OWNER_ID__', 'Phosphatidylserine', 'phosphatidylserine', 'Phospholipide constitutif des membranes neuronales, implique dans la neurotransmission, la memoire et la regulation du cortisol. Benefices documentes sur le declin cognitif, le TDAH et le stress.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6254-7d5c-92fe-c8cc3cd1cb8f', '__OWNER_ID__', 'Hydroxyapatite', 'hydroxyapatite', 'Le constituant principal de l''émail (97%), capable de
INSERT INTO public.ingredients VALUES ('019de0ab-6254-7e04-8b95-4e125deb26e7', '__OWNER_ID__', 'Glycérophosphate de Calcium (Calcium Glycerophosphate)', 'calcium-glycerophosphate', 'Un agent minéralisant qui renforce l''émail et neutralise les acides.', 'Le glycérophosphate de calcium aide à maintenir un pH équilibré dans la bouche en neutralisant les acides produits par les bactéries. Il fournit une source de calcium et de phosphate, favorisant la reminéralisation naturelle des dents et renforçant la structure de l''émail contre les caries.', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.541+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, NULL);
INSERT INTO public.ingredients VALUES ('019de0ab-6254-7f66-a8e8-83a8491914d9', '__OWNER_ID__', 'Monofluorophosphate de Sodium', 'sodium-monofluorophosphate', 'Une source de fluor efficace pour protéger et renforcer les dents.', 'Moins réactif que le fluorure de sodium pur, le monofluorophosphate de sodium libère du fluor au contact de la salive. Il est souvent utilisé dans des formules complexes pour assurer une protection durable contre la déminéralisation et renforcer la structure dentaire.', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.541+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, NULL);
INSERT INTO public.ingredients VALUES ('019de0ab-6255-713c-a8ba-1c8debed1c19', '__OWNER_ID__', 'Huile de Clou de Girofle / Eugénol', 'clove-oil-eugenol', 'L''ingrédient traditionnel pour le soulagement des douleurs dentaires.', 'Riche en eugénol, l''huile de clou de girofle est reconnue pour ses vertus anesthésiantes et antibactériennes. Elle est particulièrement efficace pour calmer les douleurs dentaires mineures et assainir la bouche.', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.541+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, NULL);
INSERT INTO public.ingredients VALUES ('019de0ab-6255-71ee-b97b-44c4a678b2f9', '__OWNER_ID__', 'Thymol', 'thymol', 'Un composant naturel du thym aux propriétés antiseptiques.', 'Le thymol est un agent antibactérien qui aide à prévenir la formation de la plaque dentaire et combat la mauvaise haleine (halitose). Il apporte également une sensation de propreté et d''assainissement en profondeur.', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.541+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, NULL);
INSERT INTO public.ingredients VALUES ('019de0ab-6255-7275-bb53-8df36c0edc82', '__OWNER_ID__', 'Nitrate de Potassium (Potassium Nitrate)', 'potassium-nitrate', 'Un agent désensibilisant qui calme les nerfs de la dent.', 'Le nitrate de potassium agit en pénétrant dans les tubules dentinaires pour atteindre les terminaisons nerveuses. Il aide à bloquer la transmission des signaux de douleur causés par le froid, le chaud ou les aliments sucrés, offrant ainsi un soulagement efficace pour les dents sensibles.', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.541+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, NULL);
INSERT INTO public.ingredients VALUES ('019de0ab-6255-7348-ae5a-063a53232e66', '__OWNER_ID__', 'Fluorure Stanneux (Stannous Fluoride)', 'stannous-fluoride', 'Un actif multi-action qui protège contre les caries, la plaque et la sensibilité.', 'Le fluorure stanneux est unique car il offre une protection contre les caries tout en créant une barrière protectrice sur la dentine exposée. Il possède également des propriétés antibactériennes qui aident à réduire la plaque et à prévenir les problèmes de gencives (gingivite).', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.541+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, NULL);
INSERT INTO public.ingredients VALUES ('019de0ab-6255-7513-8f34-3f3f79870318', '__OWNER_ID__', 'Bicarbonate de Soude (Sodium Bicarbonate)', 'sodium-bicarbonate-dental', 'Un ingrédient polyvalent pour un nettoyage profond et une haleine fraîche.', 'Le bicarbonate de soude est apprécié pour ses propriétés polissantes et neutralisantes. Il aide à dissoudre les taches de surface, équilibre le pH buccal pour limiter la prolifération bactérienne et possède une action désodorisante naturelle pour l''haleine.', 'abrasif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.541+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, NULL);
INSERT INTO public.ingredients VALUES ('019de0ab-6255-75b9-8da4-236d02ce8ca6', '__OWNER_ID__', 'Peroxyde d''Hydrogène (Hydrogen Peroxide)', 'hydrogen-peroxide', 'L''agent de blanchiment chimique le plus puissant.', 'Le peroxyde d''hydrogène pénètre dans l''émail pour briser les molécules responsables des colorations profondes. En raison de sa puissance, sa concentration est très strictement réglementée dans les produits en vente libre pour éviter d''irriter les gencives ou de fragiliser les dents.', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.541+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, NULL);
INSERT INTO public.ingredients VALUES ('019de0ab-6238-7321-85eb-138ce4f7df8d', '__OWNER_ID__', 'Palmitoyl Tripeptide-38', 'palmitoyl-tripeptide-38', 'Peptide puissant (Matrixyl Synthe’6) qui stimule les 6 constituants majeurs de la matrice cutanée pour combler les rides de l’intérieur.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6255-7d13-a359-ee4f8ee5ea74', '__OWNER_ID__', 'Citrate de Zinc (Zinc Citrate)', 'zinc-citrate', 'Forme organique du zinc très utilisée en dentifrice pour inhiber la formation du tartre et réduire la plaque bactérienne.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6255-7db9-87c5-39eab5561655', '__OWNER_ID__', 'Acétate de Zinc (Zinc Acetate)', 'zinc-acetate', 'Actif anti-halitose à action rapide par neutralisation directe des composés soufrés volatils, signature de CB12.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6255-7ea9-8143-b9e6ce8e96f9', '__OWNER_ID__', 'Chlorure de Zinc (Zinc Chloride)', 'zinc-chloride', 'Sel inorganique du zinc à action antiseptique et astringente, utilisé principalement dans les bains de bouche anti-gingivite.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6255-7f91-b361-da69094c4863', '__OWNER_ID__', 'Phosphate de Zinc (Zinc Phosphate)', 'zinc-phosphate', 'Actif anti-tartre qui précipite directement dans la plaque dentaire pour bloquer sa minéralisation, en synergie avec les fluorures.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6255-7b71-908f-6aa094d8d633', '__OWNER_ID__', 'Menthol', 'menthol-dental', 'L''ingrédient phare pour une haleine fraîche.', 'Le menthol est extrait de l''huile de menthe. Il procure une sensation de fraîcheur immédiate et aide à masquer les odeurs désagréables, tout en ayant de légères propriétés antiseptiques qui contribuent à l''hygiène globale.', 'excipient', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.635+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, 'Menthol');
INSERT INTO public.ingredients VALUES ('019de0ab-6256-70d7-b1e8-baca0237d905', '__OWNER_ID__', 'Calcium Sodium Phosphosilicate (Novamin)', 'calcium-sodium-phosphosilicate', 'Biocéramique synthétique qui libère des ions calcium, sodium et phosphate au contact de la salive pour former de l''hydroxyapatite directement sur l''émail.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623e-7776-86dd-adb04c9cc938', '__OWNER_ID__', 'Magnesium Ascorbyl Phosphate (MAP)', 'magnesium-ascorbyl-phosphate', 'Dérivé stable et hydratant, booste collagène et hydrate.', '# Magnesium Ascorbyl Phosphate
INSERT INTO public.ingredients VALUES ('019de0ab-6256-7331-ab00-715b48932ae0', '__OWNER_ID__', 'Pyrophosphate de Tétrasodium (Tetrasodium Pyrophosphate)', 'tetrasodium-pyrophosphate', 'Chélateur de calcium puissant qui empêche la minéralisation de la plaque en tartre en séquestrant les ions Ca²⁺ avant leur cristallisation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-77e4-8d4c-a968826a42b3', '__OWNER_ID__', 'Ammonium Laureth Sulfate', 'ammonium-laureth-sulfate', 'Version éthoxylée du sel ammonium, tensioactif anionique doux très moussant, alternative au SLES dans les formules à pH ajusté.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-788f-b8e6-b56081d7f9ed', '__OWNER_ID__', 'Sodium Cocoyl Sulfate', 'sodium-cocoyl-sulfate', 'Mélange de sulfates d''alkyle dérivés du coco (C8–C18), tensioactif anionique naturel plus doux que le SLS pur grâce à la diversité de ses chaînes.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6257-7e4f-a441-393825251192', '__OWNER_ID__', 'Behentrimonium Methosulfate', 'behentrimonium-methosulfate', 'Tensioactif cationique C22 à contre-ion méthosulfate, conditionneur doux avec moindre risque d''accumulation que le chlorure, très utilisé dans les conditionneurs naturels et CG-friendly.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-7ded-8046-08c12ec3514e', '__OWNER_ID__', 'Polyquaternium-37', 'polyquaternium-37', 'Polymère acrylate cationique crosslinké, conditionneur et épaississant polyvalent, apporte texture gel et douceur dans les soins capillaires sans rinçage.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-7c7c-b3b0-288ae71828be', '__OWNER_ID__', 'Sodium Lauroyl Glutamate', 'sodium-lauroyl-glutamate', 'Tensioactif amino-acide très doux à chaîne C12 laurique, excellent profil tolérance pour cuirs chevelus sensibles et formules bébé.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-7d75-8f1c-1e40eb35cf40', '__OWNER_ID__', 'Sodium Lauryl Methyl Isethionate (SLMI)', 'sodium-lauryl-methyl-isethionate', 'Tensioactif anionique de nouvelle génération dérivé de l''isethionate méthylé, offre détersivité et douceur supérieures au SLES avec une mousse microstructurée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-7e87-a017-27c451e5b88e', '__OWNER_ID__', 'Sodium Coco-Sulfate (SCS)', 'sodium-coco-sulfate', 'Mélange de sulfates d''alcools gras de coco non éthoxylés, souvent présenté comme alternative naturelle au SLS, mais au profil irritant comparable.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-7f8a-a5bb-ddcf43b6bc95', '__OWNER_ID__', 'TEA Lauryl Sulfate', 'tea-lauryl-sulfate', 'Sel triéthanolamine du lauryl sulfate, tensioactif anionique liquide et dense utilisé en shampoing, moins irritant que le SLS sodique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-7ed5-8ddc-4c35cb92f3ba', '__OWNER_ID__', 'Polyquaternium-44', 'polyquaternium-44', 'Copolymère quaternaire VP/DMAPA, conditionneur filmogène à effet curl-enhancing, favorise la définition des boucles sans rigidité ni effet craquant.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622c-78a3-8d92-fdf40c076f37', '__OWNER_ID__', 'L-Leucine (Leucine)', 'leucine', 'L''acide aminé de la résilience structurelle : un activateur de la synthèse protéique et un agent de comblement naturel pour les rides de surface.', '# La Leucine : L''Expert de la Redensification et de la Souplesse
INSERT INTO public.ingredients VALUES ('019de0ab-622c-7a39-90ce-25b1f20c3261', '__OWNER_ID__', 'L-Glutamine (Glutamine)', 'glutamine', 'Le carburant de la régénération cellulaire : un acide aminé essentiel à la synthèse des protéines et au maintien de la fermeté cutanée sous stress.', '# La Glutamine : La Source d''Énergie de la Réparation Cutanée
INSERT INTO public.ingredients VALUES ('019e077b-683b-77fc-812e-7074e4079859', '__OWNER_ID__', 'Swertia Chirata Extract (Swertiamarine)', 'swertia-chirata', 'Extrait de gentiane himalayenne riche en swertiamarine, apaisant amer aux propriétés anti-inflammatoires.', '# Swertia Chirata Extract (Swertiamarine)
INSERT INTO public.ingredients VALUES ('019de0ab-623f-735f-a81c-44d97e121788', '__OWNER_ID__', 'Polygonum Cuspidatum Extract', 'polygonum-cuspidatum-extract', 'Source naturelle de resvératrol et de stilbénoïdes, antioxydant puissant et activateur des sirtuines de longévité cellulaire.', '# Polygonum Cuspidatum Extract
INSERT INTO public.ingredients VALUES ('019de0ab-6258-7014-a65d-cea2961989a5', '__OWNER_ID__', 'Cetrimonium Bromide', 'cetrimonium-bromide', 'Analogue bromure du cetrimonium chloride, conditionneur cationique C16 avec activité antimicrobienne marquée, utilisé dans les formules anti-pelliculaires et les défrisants.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-76d1-af6a-181055d1cfbb', '__OWNER_ID__', 'Licochalcone A', 'licochalcone-a', 'Antioxydant et apaisant puissant issu de la réglisse chinoise (Glycyrrhiza Inflata), particulièrement efficace contre les rougeurs induites par les UV.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-73d9-a24e-524b1685ca6b', '__OWNER_ID__', 'Arachidyl/Behenyl Alcohol', 'arachidyl-behenyl-alcohol', 'Mélange d''alcools gras C20–C22, co-émulsifiant ultra-stable pour formules riches, combinaison synergique qui améliore la texture et le dépôt conditionneur.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-7d3a-875e-f3dbc457bda6', '__OWNER_ID__', 'Polyquaternium-11', 'polyquaternium-11', 'Polymère quaternaire vinylpyrrolidone/DMAE, agent filmogène et fixateur capillaire avec effet conditionneur, présent dans laques et gels coiffants.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-76ff-882e-f684df6892e2', '__OWNER_ID__', 'Cyclotetrasiloxane (D4)', 'cyclotetrasiloxane', 'Silicone cyclique volatile D4 à 4 motifs, vecteur ultraléger mais soumis à restriction réglementaire stricte en UE en raison de sa persistance environnementale.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6254-79be-9939-1cd0fb8fb3ef', '__OWNER_ID__', 'Vitamine K2 (Menaquinone)', 'vitamine-k2', 'Vitamine liposoluble essentielle a la fixation du calcium dans les os et a la prevention des calcifications vasculaires. Souvent associee a la vitamine D3 en supplementation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6251-7709-8b2f-f58d43f91566', '__OWNER_ID__', 'Astaxanthine', 'astaxanthine-supplement', 'Caroténoïde xanthophylle (C40H52O4) issu de la microalgue Haematococcus pluvialis, considéré comme l''un des antioxydants naturels les plus puissants.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-78c7-ae43-c440d06876c7', '__OWNER_ID__', 'Triméthylsilylamodiméthicone (Trimethylsilylamodimethicone)', 'trimethylsilylamodimethicone', 'Silicone aminofonctionnelle à terminaisons triméthylsilyle, combinant la substantivité de l''amodimethicone avec une meilleure compatibilité formulatoire et un moindre jaunissement.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-798f-bd42-e32dbea8d3e3', '__OWNER_ID__', 'Silicone Quaternium-8', 'silicone-quaternium-8', 'Silicone quaternaire (silicone + ammonium quaternaire), double action conditionnante et antistatique, dépôt substantif sur fibre chargée négativement.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-7a6e-bbb0-6ac115e9f72b', '__OWNER_ID__', 'Silicone Quaternium-16', 'silicone-quaternium-16', 'Silicone quaternaire à chaîne longue, conditionneur filmogène substantif adapté aux formules réparatrices, supérieur en dépôt au Silicone Quaternium-8.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-7b20-acc0-b8abcfe18829', '__OWNER_ID__', 'Silicone Quaternium-22', 'silicone-quaternium-22', 'Silicone quaternaire de haute substantivité, particulièrement adapté aux shampoings 2-en-1 et formules rincées grâce à son excellent dépôt résistant à l''eau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6238-73b9-91b7-5a0936b9c8ae', '__OWNER_ID__', 'Acetyl Tetrapeptide-2', 'acetyl-tetrapeptide-2', 'Peptide biomimétique (Uplevity) qui stimule l’élastine et les protéines d’ancrage pour lutter contre l’affaissement du visage.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-7f80-9b54-a60f8b22a665', '__OWNER_ID__', 'Polyquaternium-55', 'polyquaternium-55', 'Polymère quaternaire silicone-organique hybride, conditionneur longue durée combinant les avantages des silicones quaternaires et des polyquaterniums organiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-70c7-a196-d4112972f43a', '__OWNER_ID__', 'Hydroxypropyl Guar', 'hydroxypropyl-guar', 'Gomme de guar hydroxypropylée non quaternaire, épaississant et conditionneur naturel doux sans charge cationique, idéal pour formules sans tensioactifs cationiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7179-905a-cfb20a18bf7b', '__OWNER_ID__', 'Honeyquat (Hydroxypropyltrimonium Honey)', 'honeyquat', 'Miel quaternisé hydroxypropyltrimonium, conditionneur naturel d''origine apicole avec double action humectante et substantive sur la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6255-7002-9081-a220f6a239ab', '__OWNER_ID__', 'Chlorhexidine', 'chlorhexidine', 'L''antiseptique de référence pour les problèmes de gencives.', 'La chlorhexidine est un agent antibactérien puissant utilisé pour lutter contre la plaque dentaire et traiter l''inflammation des gencives (gingivite). Son action est prolongée car elle se fixe sur les tissus buccaux pour libérer ses bienfaits pendant plusieurs heures.', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.541+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, NULL);
INSERT INTO public.ingredients VALUES ('019de0ab-6232-72cb-b06a-b793725752c0', '__OWNER_ID__', 'Céramide EOP', 'ceramide-eop', 'Céramide à longue chaîne. Ancre les lamelles lipidiques à l''enveloppe cornée.', '# Céramide EOP
INSERT INTO public.ingredients VALUES ('019de0ab-6248-78d2-9be8-91dc3813351f', '__OWNER_ID__', 'Sarcosine', 'sarcosine', 'Acide aminé naturel qui aide à réduire la production de sébum et à affiner le grain de peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6245-70eb-97d5-ed4311901626', '__OWNER_ID__', '4-Butylresorcinol', 'butylresorcinol', 'Inhibiteur de tyrosinase extrêmement puissant, l’un des actifs les plus efficaces contre l’hyperpigmentation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623e-76be-8b89-b610fb821816', '__OWNER_ID__', 'Sodium Ascorbyl Phosphate (SAP)', 'sodium-ascorbyl-phosphate', 'Dérivé stable, anti-acné et brighten, très doux pour peaux sensibles.', '# Sodium Ascorbyl Phosphate
INSERT INTO public.ingredients VALUES ('019de0ab-622c-7d97-8e9d-594f1beb1cd0', '__OWNER_ID__', 'Acétyl Glucosamine (N-Acetyl Glucosamine / NAG)', 'acetyl-glucosamine', 'Le précurseur d''acide hyaluronique et correcteur de teint : un sucre aminé haute performance qui booste l''hydratation endogène et réduit l''hyperpigmentation.', '# L''Acétyl Glucosamine : L''Architecte de l''Hydratation et de la Clarté
INSERT INTO public.ingredients VALUES ('019de0ab-6241-7a69-9f82-04b149128cb0', '__OWNER_ID__', 'Calendula', 'calendula-officinalis', 'Extrait floral reconnu pour ses vertus apaisantes, anti-inflammatoires et sa capacité à favoriser la réparation cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6247-76fb-8005-95749dbf92ae', '__OWNER_ID__', 'Soufre (Sulfur)', 'soufre', 'Actif anti-acné parmi les plus anciens en dermatologie. Kératolytique, séborégulateur et antibactérien, il cible comédons, points noirs et inflammations — particulièrement efficace sur les peaux grasses et acnéiques.', '## Contexte historique & réglementaire
INSERT INTO public.ingredients VALUES ('019de0ab-6252-7287-92b6-addef561e1af', '__OWNER_ID__', 'Créatine (Monohydrate)', 'creatine', 'Composé azoté naturel servant de réserve énergétique rapide (phosphocréatine). Supplément ergogénique le plus étudié et le plus efficace pour la force, la masse maigre et la performance de haute intensité.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-77e9-80b4-bd4679ac2ba9', '__OWNER_ID__', 'Huile de Chanvre (Cannabis Sativa Seed Oil)', 'hemp-oil-hair', 'Huile de graine de chanvre à ratio Ω6/Ω3 optimal (3:1), riche en acide gamma-linolénique, anti-inflammatoire pour le cuir chevelu et régulatrice de la production sébacée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6238-7642-920c-137f845624e3', '__OWNER_ID__', 'Palmitoyl Tetrapeptide-10', 'palmitoyl-tetrapeptide-10', 'L''architecte de la clarté cristalline : un peptide biomimétique qui régule l''épigénétique cutanée pour un teint uniforme, lisse et intensément lumineux.', '# Le Palmitoyl Tetrapeptide-10 : La Technologie Crystalide™ au Service de la Transparence
INSERT INTO public.ingredients VALUES ('019de0ab-6238-780a-9afe-929c85692029', '__OWNER_ID__', 'PDRN (Polydeoxyribonucleotide)', 'pdrn', 'Fragments d''ADN issus principalement de saumon. Agit sur les récepteurs A2A (inflammation, prolifération cellulaire, collagène). Prometteur en injection médicale, mais preuves très limitées en application topique (crème/sérum). Tendance 2025-2026 largement portée par le marketing.', '## Structure & origine
INSERT INTO public.ingredients VALUES ('019e077b-683b-79df-9a04-bdafc1e63515', '__OWNER_ID__', 'Myrothamnus Flabellifolia (Myramaze)', 'myrothamnus-flabellifolia', 'Plante de résurrection, polyols protecteurs (tréhalose), antioxydant et anti-déshydratation extrême.', '# Myrothamnus Flabellifolia (Myramaze)
INSERT INTO public.ingredients VALUES ('019de0ab-6232-740c-aab1-5fa93210662e', '__OWNER_ID__', 'Suif de bœuf (Beef Tallow)', 'beef-tallow', 'Graisse animale rendue, émollient et occlusif efficace pour les peaux très sèches. Comparable au karité en comportement. Les allégations marketing (similitude au sébum, richesse vitaminique) sont largement exagérées et peu étayées scientifiquement.', '## Origine
INSERT INTO public.ingredients VALUES ('019de0ab-6246-762d-af63-eed111173e61', '__OWNER_ID__', 'Gluconate de Zinc (Zinc Gluconate)', 'zinc-gluconate', 'L''oligo-élément régulateur de l''homéostasie cutanée : une action sébo-régulatrice, purifiante et cicatrisante incontournable pour les peaux à imperfections.', '# Le Gluconate de Zinc : Le Gardien de la Pureté Cutanée
INSERT INTO public.ingredients VALUES ('019de0ab-625a-7a2d-867a-1390b9644140', '__OWNER_ID__', 'Huile de Macadamia (Macadamia Ternifolia Seed Oil)', 'macadamia-oil-hair', 'Huile extraite des noix de macadamia, exceptionnellement riche en acide palmitoléique (Ω7) — acide gras rare biomimétique du sébum juvénile — qui nourrit et assouplit la fibre capillaire avec un profil sensoriel sec et soyeux.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-7b40-b2d4-d5f4e5afcbf8', '__OWNER_ID__', 'Huile d''Amande Douce (Prunus Amygdalus Dulcis Oil)', 'almond-oil-hair', 'Huile douce polyvalente extraite des amandes, riche en acide oléique et en vitamine E, adoucissante, émolliente et protectrice pour tous types de cheveux, particulièrement recommandée pour les cuirs chevelus sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-7e1f-8674-0276dc58b13c', '__OWNER_ID__', 'Huile de Camélia (Camellia Sinensis Seed Oil)', 'camellia-sinensis-oil-hair', 'Huile japonaise extraite des graines du théier, à très haute teneur en acide oléique (80–90%), légère et non grasse, elle lisse la cuticule, apporte brillance et protège la fibre de la chaleur des outils coiffants.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-7504-bed5-516588136423', '__OWNER_ID__', 'Céresine (Ceresin)', 'ceresin-hair', 'Cire minérale raffinée issue de l''ozokérite ou du pétrole, structurante et gélifiante des phases huileuses dans les pomades, graisses de coiffage et cires capillaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-7f94-9c98-16b51f57cba9', '__OWNER_ID__', 'Huile de Moringa (Moringa Oleifera Seed Oil)', 'moringa-oil-hair', 'Huile extraite des graines de l''arbre à vie africain, très stable oxydativement grâce au béhénate, elle nettoie le cuir chevelu des impuretés environnementales, conditionne la fibre et apporte légèreté et brillance.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-70db-a451-3b23ee691e2e', '__OWNER_ID__', 'Huile de Noisette (Corylus Avellana Seed Oil)', 'hazelnut-oil-hair', 'Huile finement astringente extraite des noisettes, à dominante oléique et profil sec très léger, idéale pour les cuirs chevelus gras ou mixtes — pénètre sans résidu et régule légèrement la production sébacée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-71e4-a0e8-dc918cc26e47', '__OWNER_ID__', 'Huile de Nigelle (Nigella Sativa Seed Oil)', 'black-seed-oil-hair', 'Huile de cumin noir aux propriétés anti-inflammatoires et antifongiques élevées grâce à la thymoquinone, efficace contre les pellicules, le prurit et les inflammations du cuir chevelu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-752a-af19-69a1422a684c', '__OWNER_ID__', 'Huile de Baobab (Adansonia Digitata Seed Oil)', 'baobab-oil-hair', 'Huile africaine extraite des graines du baobab, équilibrée en acides gras essentiels (Ω6, Ω9, Ω3), profondément nourrissante et réparatrice pour les cheveux secs, texturés ou chimiquement traités.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-769a-9031-5a8286694025', '__OWNER_ID__', 'Huile d''Abyssinie (Crambe Abyssinica Seed Oil)', 'crambe-abyssinica-seed-oil', 'Huile éthiopienne à teneur record en acide érucique (55–65%), formant un film ultra-léger et lissant sur la cuticule capillaire, utilisée comme alternative naturelle aux silicones pour la brillance et la protection thermique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-78d0-99cd-1b4e254d64aa', '__OWNER_ID__', 'Goudron de Houille (Coal Tar)', 'coal-tar', 'Mélange complexe de composés aromatiques issu de la distillation du charbon, actif kératolytique et anti-prurigineux historique pour le psoriasis et la dermite séborrhéique sévère.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622d-7f21-bcc6-ae7acc82c7d3', '__OWNER_ID__', 'Hydroxypropyltrimonium Hyaluronate', 'hydroxypropyltrimonium-hyaluronate', 'Forme cationique (chargée positivement) de l''acide hyaluronique qui ''colle'' littéralement à la peau et aux cheveux par attraction électrostatique.', '# Hydroxypropyltrimonium Hyaluronate
INSERT INTO public.ingredients VALUES ('019de0ab-6260-7fe9-ae19-48b4e3d3dc02', '__OWNER_ID__', 'Poudre de Shikakai (Acacia Concinna)', 'shikakai-hair', 'Poudre ayurvédique issue des gousses d''Acacia concinna, naturellement riche en saponines lavantes douces et en acide ascorbique, nettoie et fortifie la fibre sans agresser le cuir chevelu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-7a4d-b068-bc885b71fb81', '__OWNER_ID__', 'Beurre de Mangue (Mangifera Indica Seed Butter)', 'mango-butter-hair', 'Beurre léger et non comédogène extrait des graines de mangue, profil lipidique proche du beurre de cacao mais texture plus douce et moins occlusive, idéal pour adoucir et protéger sans alourdir les cheveux.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-7b94-9c43-f7230364cd4d', '__OWNER_ID__', 'Beurre de Sal (Shorea Robusta Seed Butter)', 'sal-butter-hair', 'Beurre asiatique rare issu des graines de l''arbre sal indien, à très haute teneur en acide stéarique, utilisé comme alternative au beurre de cacao pour ses propriétés structurantes et occlusives dans les soins capillaires riches.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-7d2c-b57d-40ce5ac97470', '__OWNER_ID__', 'Beurre de Madhuca (Madhuca Longifolia Seed Butter)', 'madhuca-longifolia-butter', 'Beurre ayurvédique issu des graines du mahua indien, riche en acide oléique et en fraction insaponifiable active, traditionnellement utilisé pour nourrir le cuir chevelu, stimuler la pousse et traiter les affections cutanées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6238-7973-87ac-7c665a747866', '__OWNER_ID__', 'Matrixyl 3000', 'matrixyl-3000', 'Le complexe peptidique de référence combinant deux molécules messagères pour une action anti-âge globale et une fermeté retrouvée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7287-bed4-7b6dddb4b211', '__OWNER_ID__', 'Protéine de Riz Hydrolysée (Hydrolyzed Rice Protein)', 'hydrolyzed-rice-protein', 'Protéine de riz hydrolysée riche en cystéine et méthionine, renforce la fibre capillaire en profondeur et protège contre les dommages oxydatifs.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7348-999a-52bed2447436', '__OWNER_ID__', 'Protéine d''Avoine Hydrolysée (Hydrolyzed Oat Protein)', 'hydrolyzed-oat-protein', 'Protéine d''avoine hydrolysée à profil apaisant, renforce la fibre et protège le cuir chevelu irrité grâce à ses peptides anti-inflammatoires et humectants.', '
INSERT INTO public.ingredients VALUES ('019e077b-683b-7ae2-9181-b1e99dffad54', '__OWNER_ID__', 'Glycolide', 'glycolide', 'Dimère cyclique de l''acide glycolique. Exfoliant à libération prolongée par hydrolyse cutanée progressive — moins d''irritation que l''AHA libre.', '# Glycolide
INSERT INTO public.ingredients VALUES ('019e077b-683b-7a38-bcb8-a7a2ea31a605', '__OWNER_ID__', 'Salicornia Herbacea Extract (Saliporine-8)', 'salicornia-herbacea', 'Extrait halophile riche en mannitol et osmolytes, apaisant neuro-cosmétique pour peau hyper-réactive.', '# Salicornia Herbacea Extract (Saliporine-8)
INSERT INTO public.ingredients VALUES ('019de0ab-6261-7106-8427-3ffc5af624d2', '__OWNER_ID__', 'Poudre de Reetha (Sapindus Mukorossi)', 'reetha-hair', 'Poudre de noix de lavage ayurvédique à haute teneur en saponines triterpéniques, agent moussant naturel purifiant et anti-pelliculaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7434-bb1c-baf8f8079bbc', '__OWNER_ID__', 'Protéine de Quinoa Hydrolysée (Hydrolyzed Quinoa Protein)', 'hydrolyzed-quinoa-protein', 'Protéine du quinoa hydrolysée, profil d''acides aminés complet proche de la kératine, renforce la fibre, améliore l''élasticité et protège contre la casse.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-74f9-8bd2-6dd2eb2be83c', '__OWNER_ID__', 'Acides Aminés de Blé (Wheat Amino Acids)', 'wheat-amino-acids', 'Mélange d''acides aminés libres issus du blé, pénètre profondément la fibre capillaire, hydrate le cortex et renforce la structure kératinique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7741-9279-3e9972d57dba', '__OWNER_ID__', 'Protéine de Jojoba Hydrolysée (Hydrolyzed Jojoba Esters)', 'hydrolyzed-jojoba-protein', 'Esters de jojoba hydrolysés combinant un fragment protéique et un fragment lipidique, apportent nutrition, brillance et protection thermique à la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-78c6-812f-c5f0802bcb4a', '__OWNER_ID__', 'Créatine (Creatine)', 'creatine-hair', 'Molécule guanidinoacétate naturelle, renforce la résistance mécanique de la fibre kératinique et protège contre les dommages oxydatifs et thermiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-777b-8969-01bda1226c65', '__OWNER_ID__', 'Aster Tripolium Extract', 'aster-tripolium', 'Extrait d’aster maritime qui renforce la microcirculation et calme les rougeurs diffuses.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7eff-bb94-12f15d879dae', '__OWNER_ID__', 'Acide Aspartique (Aspartic Acid)', 'aspartic-acid-hair', 'Acide aminé dicarboxylique chargé négativement, tamponne le pH de la fibre capillaire, hydrate le cortex et participe à la cohésion ionique de la kératine.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-70b5-b05e-5bc751cd1254', '__OWNER_ID__', 'Stearalkonium Chloride', 'stearalkonium-chloride', 'Tensioactif cationique C18 benzylique (alkylbenzyl ammonium), conditionneur puissant hérité des assouplissants textiles, fort dépôt sur la fibre mais risque accru d''accumulation.', '
INSERT INTO public.ingredients VALUES ('019e077b-683a-79e6-8241-307e45aa36a2', '__OWNER_ID__', 'Acetyl Zingerone', 'acetyl-zingerone', 'Antioxydant nouvelle génération dérivé du gingembre. Stabilisateur de vitamine C, anti-inflammatoire, anti-pigmentation. Usage typique 0.5–2%.', '# Acetyl Zingerone
INSERT INTO public.ingredients VALUES ('019e077b-683b-707c-b242-08c6f15b6a59', '__OWNER_ID__', 'Génistéine (Genistein)', 'genistein', 'Isoflavone du soja, antioxydant phyto-œstrogène-like, anti-âge et photoprotecteur.', '# Génistéine (Genistein)
INSERT INTO public.ingredients VALUES ('019de0ab-6232-7612-b3a0-c83f5bd4bdff', '__OWNER_ID__', 'Céramides', 'ceramides', 'Lipides naturels qui constituent 30 à 40% du poids de la couche cornée et forment le ciment de la barrière cutanée. Retiennent l''hydratation, protègent des agressions et améliorent la pénétration des actifs.', '## Rôle dans la peau
INSERT INTO public.ingredients VALUES ('019e077b-683b-71b2-a2f5-eaeee7dec794', '__OWNER_ID__', 'Quercétine (Quercetin)', 'quercetin', 'Flavonoïde antioxydant puissant, anti-inflammatoire et stabilisateur de mastocytes.', '# Quercétine (Quercetin)
INSERT INTO public.ingredients VALUES ('019e077b-683b-7441-9a5d-5bfb38ae286c', '__OWNER_ID__', 'Silybine (Silybin / Silymarine)', 'silybin', 'Flavonolignane du chardon-marie, antioxydant hépatoprotecteur, anti-âge et anti-rougeurs en topique.', '# Silybine (Silybin / Silymarine)
INSERT INTO public.ingredients VALUES ('019de0ab-625e-72c8-b38d-a2e98f663e58', '__OWNER_ID__', 'Gomme de Tara (Caesalpinia Spinosa Gum)', 'tara-gum', 'Galactomannane extrait des gousses du tara péruvien, épaississant et conditionneur naturel qui améliore le glissant et facilite le démêlage des cheveux bouclés et épais.', '
INSERT INTO public.ingredients VALUES ('019e077b-683b-7491-8064-3c5be39dcee3', '__OWNER_ID__', 'Hesperidin Methyl Chalcone', 'hesperidin-methyl-chalcone', 'Flavonoïde dérivé d''agrumes, veinotonique et anti-rougeurs, ciblé microcirculation.', '# Hesperidin Methyl Chalcone
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7e39-8b49-f0b26fa314d8', '__OWNER_ID__', 'Aquaxyl (Xylitylglucoside + Anhydroxylitol + Xylitol)', 'aquaxyl-complex', 'Complexe humectant breveté Sederma combinant trois dérivés du xylitol, réduit la perte en eau transépidermique et améliore la rétention hydrique de la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7981-8763-cfad15ddc246', '__OWNER_ID__', 'Acide Béhénique (Behenic Acid)', 'behenic-acid', 'Acide gras saturé à très longue chaîne (C22), émollient structurel de la fibre capillaire, filmogène léger et composant des lipides cuticulaires des cheveux à forte affinité pour la kératine.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-77bf-8b92-ae5b522502bd', '__OWNER_ID__', 'Kétoconazole (Ketoconazole)', 'ketoconazole', 'Antifongique azolé à action ciblée sur la biosynthèse de l''ergostérol fongique, traitement de référence de la dermite séborrhéique modérée à sévère.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622d-7fcd-8534-183d59280ff3', '__OWNER_ID__', 'Hyaluronate de Potassium', 'potassium-hyaluronate', 'Sel de potassium de l''acide hyaluronique, favorise l''équilibre hydrique constant dans les couches externes de l''épiderme.', '# Hyaluronate de Potassium (Potassium Hyaluronate)
INSERT INTO public.ingredients VALUES ('019de0ab-625f-72a8-8d3b-f07466fdda91', '__OWNER_ID__', 'Minoxidil', 'minoxidil', 'Vasodilatateur antihypertenseur reconverti en stimulant capillaire topique, seul actif OTC reconnu par la FDA pour l''alopécie androgénétique masculine et féminine.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-7404-9e82-91de84bae2b8', '__OWNER_ID__', 'Capixyl (Acetyl Tetrapeptide-3)', 'capixyl', 'Complexe breveté associant un tétrapeptide biomimétique et un extrait de trèfle rouge, stimule la matrice folliculaire et inhibe la 5α-réductase pour lutter contre l''alopécie androgénétique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-74e7-8cd5-a11d5374947a', '__OWNER_ID__', 'Redensyl', 'redensyl', 'Complexe breveté Givaudan ciblant les cellules souches folliculaires, réactive la division des cellules ORSc pour relancer la phase anagène et réduire la chute de cheveux.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622d-75d1-baa0-8a9f6364d06e', '__OWNER_ID__', 'Glycérine (Glycerin)', 'glycerin', 'L''hydratant de référence, capable de retenir son poids en eau pour assurer une hydratation continue et protéger la barrière cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6246-77f9-afa1-61eb0ed7bdea', '__OWNER_ID__', 'Acide azélaïque', 'azelaic-acid', 'Acide dicarboxylique naturel approuvé FDA pour l''acné et la rosacée. Très efficace sur l''hyperpigmentation, le melasma et l''érythème post-inflammatoire. Excellent profil de tolérance, safe grossesse.', '## Qu''est-ce que c''est ?
INSERT INTO public.ingredients VALUES ('019de0ab-6239-71b3-8c80-766cfd8e6f95', '__OWNER_ID__', 'Palmitoyl Tetrapeptide-7', 'palmitoyl-tetrapeptide-7', 'Peptide anti-inflammatoire majeur qui freine le vieillissement prématuré et préserve la fermeté de la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-75c0-9872-d0ec1e343ae1', '__OWNER_ID__', 'Procapil', 'procapil', 'Complexe breveté Sederma à triple action anti-chute : inhibe la 5α-réductase, stimule la synthèse de protéines d''ancrage folliculaire et améliore la microcirculation du cuir chevelu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-76a5-b411-d23cad706a5b', '__OWNER_ID__', 'Extrait de Ginseng (Panax Ginseng Root Extract)', 'ginseng-extract-hair', 'Extrait de racine de ginseng riche en ginsénosides, stimule la prolifération des cellules de la papille dermique et prolonge la phase anagène du cycle capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-77bf-928f-cad55a55618e', '__OWNER_ID__', 'Extrait de Cresson / Capucine', 'cresson-capucine-extract', 'Extraits riches en glucosinolates et isothiocyanates, stimulent la circulation périfolliculaire et constituent la base végétale de l''actif breveté Procapil.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-78a2-83ee-b6db2b3625b2', '__OWNER_ID__', 'Saw Palmetto (Serenoa Serrulata)', 'saw-palmetto', 'Extrait lipidique de palmier nain américain riche en acides gras et stérols, inhibiteur naturel de la 5α-réductase utilisé contre l''alopécie androgénétique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-7a5b-ba99-787dae01b8ad', '__OWNER_ID__', 'Xylitylglucoside', 'xylitylglucoside', 'Un sucre végétal innovant qui agit comme un architecte de l’eau, harmonisant les flux d’hydratation et renforçant la barrière cutanée pour une peau durablement désaltérée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624c-78ba-b42e-668b34aa18e0', '__OWNER_ID__', 'Biotine (Vitamine B8 topique)', 'biotin', 'Vitamine B8 utilisée en topique pour soutenir le métabolisme lipidique de la barrière cutanée et renforcer le confort des peaux fragiles.', '# Biotine (Topique)
INSERT INTO public.ingredients VALUES ('019de0ab-622d-7e7c-baf9-dd10c806e49a', '__OWNER_ID__', 'Sodium Acetylated Hyaluronate', 'sodium-acetylated-hyaluronate', 'Surnommé ''Super Acide Hyaluronique'', il offre une affinité exceptionnelle avec la peau pour une hydratation renforcée et une réparation de la barrière.', '# Sodium Acetylated Hyaluronate (Super HA)
INSERT INTO public.ingredients VALUES ('019de0ab-6249-717c-b796-ad5a32b4afc0', '__OWNER_ID__', 'Azelocalm', 'azelocalm', 'Acide azélaïque complexé pour une meilleure tolérance, offrant tous les bienfaits anti-rougeurs sans irritation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-75f7-92af-0a3f838bd05b', '__OWNER_ID__', 'Ozokérite (Ozokerite)', 'ozokerite-hair', 'Cire minérale fossile naturelle, mélange de cérésine et de paraffines à haut PM, précurseur naturel de la céresine raffinée utilisée dans les pomades et produits de coiffage semi-solides.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-7a83-bac7-f010a5a18550', '__OWNER_ID__', 'Extrait de Bambou', 'bambou-extract-hair', 'Extrait riche en silice organique issu des entrenœuds de bambou, renforce la structure kératinique et améliore résistance et élasticité de la fibre.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7d92-8c31-51a78987dcae', '__OWNER_ID__', 'Tetrasodium EDTA', 'tetrasodium-edta', 'Version tétrabasique de l''EDTA, chélateur de métaux dans les formules aqueuses.', '# Tetrasodium EDTA
INSERT INTO public.ingredients VALUES ('019de0ab-6260-7d1c-b492-7f24b6ced81c', '__OWNER_ID__', 'Charbon Actif (Activated Charcoal)', 'activated-charcoal-hair', 'Carbone poreux à surface spécifique ultra-élevée, adsorbe les polluants, résidus de silicones et excès de sébum du cuir chevelu avec une efficacité supérieure aux argiles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-7e0e-aee3-0b5f294de99e', '__OWNER_ID__', 'Charbon de Bambou (Bambou Charcoal)', 'bambou-charcoal-hair', 'Charbon obtenu par pyrolyse du bambou, alliant les propriétés adsorbantes du charbon actif et les oligo-éléments minéraux du végétal.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6261-71f9-b87a-d58e40dc0f80', '__OWNER_ID__', 'Poudre d''Amla (Phyllanthus Emblica)', 'amla-hair', 'Poudre de groseille indienne exceptionnellement riche en vitamine C et en tanins hydrolysables, stimule la croissance capillaire, renforce la fibre et prévient le grisonnement prématuré.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6261-72f3-8542-356d99e9dc7e', '__OWNER_ID__', 'Bis-Aminopropyl Diglycol Dimaleate', 'bis-aminopropyl-diglycol-dimaleate', 'Actif exclusif d''Olaplex, reconstruit les ponts disulfure brisés de la kératine à l''intérieur de la fibre capillaire — le seul traitement capillaire à réparer structurellement la kératine.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6261-763f-94ab-bf5c31a54b6a', '__OWNER_ID__', 'Phytantriol', 'phytantriol-hair', 'Alcool triterpénique biomimétique dérivé de la phytol (chlorophylle), conditionneur de cuticule d''exception qui apporte brillance, douceur et protection thermique sans alourdir.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6261-7750-8acb-2bd6e3359734', '__OWNER_ID__', 'Extrait de Noni (Morinda Citrifolia Fruit Extract)', 'morinda-citrifolia-extract', 'Extrait riche en proxéronine et en antioxydants phénoliques issu du fruit du noni polynésien, stimule la régénération cellulaire du cuir chevelu et protège la fibre du vieillissement oxydatif.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6261-7a4d-a4c6-c32e02285c82', '__OWNER_ID__', 'Palmitoyl Myristyl Serinate', 'palmitoyl-myristyl-serinate', 'Ester lipopeptidique biomimétique de la 18-MEA capillaire, restaure la couche lipidique externe hydrophobe de la cuticule et réduit le coefficient de friction de la fibre.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622a-76bb-90b3-f10377a63539', '__OWNER_ID__', 'Mannitol', 'mannitol', 'Sucre naturel (polyol) utilisé pour ses propriétés hydratantes et sa capacité à protéger d''autres actifs contre l''oxydation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-7031-8ec0-263b9f85137b', '__OWNER_ID__', 'Alanine', 'alanine', 'Un acide aminé essentiel du Facteur Naturel d''Hydratation (NMF), qui hydrate, soutient la réparation cutanée et renforce la cohésion du stratum corneum.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-720e-b472-a9a90137760a', '__OWNER_ID__', 'Lactate de Sodium (Sodium Lactate)', 'sodium-lactate', 'Le sel sodique de l''acide lactique, composant majeur du Facteur Naturel d''Hydratation (NMF), humectant puissant et régulateur de pH naturel.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622d-710e-ae7e-8582e657c8c3', '__OWNER_ID__', 'L-Histidine (Histidine)', 'histidine', 'L''acide aminé régulateur de barrière : un précurseur de l''acide urocanique qui assure la protection UV naturelle et l''équilibre du pH cutané.', '# L''Histidine : Le Pilier de la Protection Solaire et du pH Physiologique
INSERT INTO public.ingredients VALUES ('019de0ab-622d-728f-b4c4-ae05c6ae63d2', '__OWNER_ID__', 'L-Sérine (Serine)', 'serine', 'L''architecte de l''hydratation naturelle : un acide aminé clé pour la synthèse des céramides et le maintien du NMF (Natural Moisturizing Factor).', '# La Sérine : Le Pilier de l''Hydratation Biologique et de la Barrière Cutanée
INSERT INTO public.ingredients VALUES ('019de0ab-622d-7418-95de-4ae23a488c0f', '__OWNER_ID__', 'Propylène Glycol (Monopropylène Glycol)', 'propylene-glycol', 'L''agent de vectorisation polyvalent : un humectant haute performance qui optimise la pénétration des actifs tout en stabilisant les formules dermo-cosmétiques.', '# Le Propylène Glycol : Le Vecteur d''Efficacité Moléculaire
INSERT INTO public.ingredients VALUES ('019de0ab-622b-753f-bf84-2b7dde42c7ec', '__OWNER_ID__', 'Hydroxyéthyl Urée (Hydroxyethyl Urea)', 'hydroxyethyl-urea', 'Un dérivé de l''urée particulièrement bien toléré, qui hydrate en profondeur et améliore l''élasticité cutanée sans l''effet kératolytique de l''urée pure.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-7694-a64d-191e5a30ce75', '__OWNER_ID__', 'Glycine', 'glycine', 'Le plus petit des acides aminés, mais un géant de la structure cutanée, constituant majeur du collagène pour une peau plus ferme et élastique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-783c-a1ee-1c73b432ceb5', '__OWNER_ID__', 'Tréhalose', 'trehalose', 'Surnommé "le sucre de la résurrection", il protège les cellules contre les chocs thermiques et la déshydratation extrême.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-78e2-9c61-a4ffefdbc827', '__OWNER_ID__', 'Xylitol', 'xylitol', 'Un sucre de bouleau aux vertus hygroscopiques puissantes, capable de capter l’humidité tout en limitant la prolifération des bactéries indésirables.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-79b6-a89a-6c0f471d4749', '__OWNER_ID__', 'Anhydroxylitol', 'anhydroxylitol', 'Dérivé déshydraté du xylitol, cet actif stabilise l’hydratation cutanée en agissant sur la cohésion des cellules de l’épiderme.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-7afc-bb08-d5b1705303f8', '__OWNER_ID__', 'Betaine', 'betaine', 'Actif hydratant d’origine végétale (souvent issu de la betterave) qui aide la peau à retenir l’eau et à mieux résister au stress environnemental.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622b-7e38-bccf-0d0509ba1538', '__OWNER_ID__', 'Glyceryl Glucoside', 'glyceryl-glucoside', 'Humectant naturel et biomimétique (souvent issu de biotechnologie), Glyceryl Glucoside stimule l''expression d''AQP3, booste l''hydratation cellulaire profonde, renforce la barrière et offre un confort longue durée pour peaux déshydratées et sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622c-7355-9f51-7298ba0162c9', '__OWNER_ID__', 'Sodium PCA (Sodium Pyrrolidone Carboxylic Acid)', 'sodium-pca', 'Humectant physiologique issu du NMF, hydrate intensément et maintient l’équilibre cutané.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622c-76da-82e5-c3d7a77838ee', '__OWNER_ID__', 'L-Phénylalanine (Phenylalanine)', 'phenylalanine', 'L''acide aminé régulateur de la pigmentation : un précurseur de la mélanine essentiel pour l''uniformité du teint et le traitement des troubles pigmentaires.', '# La Phénylalanine : Le Chef d''Orchestre de la Pigmentation Cutanée
INSERT INTO public.ingredients VALUES ('019de0ab-622d-7705-8965-aa2595748495', '__OWNER_ID__', 'Pentylène Glycol (Pentylene Glycol)', 'pentylene-glycol', 'Humectant multifonctionnel d''origine végétale qui booste l''hydratation, améliore la pénétration des actifs et stabilise les formules haute tolérance.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622d-7835-9bd5-45b4bd4ac33d', '__OWNER_ID__', 'Acide hyaluronique (Sodium Hyaluronate)', 'sodium-hyaluronate', 'Humectant capable de retenir 1000x son poids en eau.', '# Sodium Hyaluronate
INSERT INTO public.ingredients VALUES ('019de0ab-622d-78fe-8c25-40e9df153270', '__OWNER_ID__', 'Urée', 'urea', 'Composé naturellement présent dans le stratum corneum, membre des Natural Moisturizing Factors (NMF). À faible concentration, humectant puissant. À haute concentration, kératolytique — dissout et ramollit la kératine accumulée. Un actif unique qui hydrate et exfolie selon sa formulation.', '## Origine & identité
INSERT INTO public.ingredients VALUES ('019de0ab-622d-7c39-a88e-7962a5749e51', '__OWNER_ID__', 'Acide Hyaluronique', 'hyaluronic-acid', 'Humectant star capable de retenir jusqu''à 1000× son poids en eau.', '# Acide Hyaluronique
INSERT INTO public.ingredients VALUES ('019de0ab-622d-7d0b-b143-e17e127002e8', '__OWNER_ID__', 'Acide Hyaluronique Hydrolysé', 'hydrolyzed-hyaluronic-acid', 'Forme fragmentée d''acide hyaluronique à très bas poids moléculaire pour une pénétration plus profonde dans l''épiderme.', '# Acide Hyaluronique Hydrolysé (Hydrolyzed Hyaluronic Acid)
INSERT INTO public.ingredients VALUES ('019de0ab-622d-7dc6-bd26-152f1ded99da', '__OWNER_ID__', 'Sodium Hyaluronate Crosspolymer', 'sodium-hyaluronate-crosspolymer', 'Acide hyaluronique réticulé formant un maillage 3D à la surface de la peau pour une hydratation continue et longue durée.', '# Sodium Hyaluronate Crosspolymer
INSERT INTO public.ingredients VALUES ('019de0ab-622e-7076-90c2-6f94bf1ff644', '__OWNER_ID__', 'Snow Mushroom', 'snow-mushroom', 'Alternative naturelle à l’acide hyaluronique, capable de retenir jusqu’à 500 fois son poids en eau pour une hydratation profonde et repulpante.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622e-71a8-a15b-d7bf5a03b40e', '__OWNER_ID__', 'Acide Polyglutamique', 'polyglutamic-acid', 'Un hydratant ultra-puissant capable de retenir 4 à 5 fois plus d’eau que l’acide hyaluronique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622e-74f7-8e33-eef6ad448b12', '__OWNER_ID__', 'Rosehip Seed Oil (Rosa Canina Seed Oil)', 'rosehip-seed-oil', 'Huile de graines d''églantier régénérante, riche en acides gras essentiels et vitamines, idéale pour cicatriser, hydrater et lutter contre les signes de l''âge.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622e-75b4-adc4-b651dfe448b6', '__OWNER_ID__', 'Huile d''Avocat (Persea Gratissima Oil)', 'avocado-oil', 'Une huile végétale riche en acides gras insaturés et en vitamine E, très nourrissante et régénérante, idéale pour les peaux sèches et matures.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622f-7b72-ae5e-6d3dea53e69b', '__OWNER_ID__', 'Cire d’Abeille', 'cera-alba', 'Un ingrédient naturel protecteur qui forme un film non-occlusif à la surface de la peau pour prévenir le dessèchement.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6230-7937-9277-9ee3d0870e77', '__OWNER_ID__', 'Huile de Jojoba (Simmondsia chinensis)', 'huile-jojoba', 'L''huile-cire mimétique du sébum humain, régulatrice, hydratante et apaisante, parfaite pour équilibrer, réparer et protéger tous les types de peaux, y compris sensibles et atopiques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6230-7ae2-b3cd-6ac90ac8dfdc', '__OWNER_ID__', 'Huile d’Argan (Argania spinosa)', 'huile-argan', 'L’huile nourrissante, réparatrice et antioxydante par excellence, issue de l’arganier marocain, pour hydrater, apaiser et protéger les peaux sèches, sensibles et matures.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6231-70da-8d2f-5800bd4535d8', '__OWNER_ID__', 'Diméthicone (Polydiméthylsiloxane)', 'dimethicone', 'Le bouclier protecteur haute performance : un polymère de silicone inerte offrant un fini soyeux inégalé et une protection barrière contre les agressions extérieures.', '# Le Diméthicone : L''Expert du Conditionnement et de la Protection Cutanée
INSERT INTO public.ingredients VALUES ('019de0ab-622e-7694-82aa-fc548c57bc02', '__OWNER_ID__', 'Glycéryl Stéarate (Glyceryl Stearate)', 'glyceryl-stearate', 'Un émulsifiant émollient naturel qui stabilise les formules crème et renforce le film hydrolipidique de la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622e-774c-b192-632872e3dd81', '__OWNER_ID__', 'Alcool Cétéarylique (Cetearyl Alcohol)', 'cetearyl-alcohol', 'Un alcool gras émollient et épaississant qui nourrit et adoucit la peau sans l''assécher, souvent confondu à tort avec les alcools irritants.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622e-77f7-a13b-e82a30a29ddd', '__OWNER_ID__', 'Triglycérides Caprylique/Caprique (Caprylic/Capric Triglyceride)', 'caprylic-capric-triglyceride', 'Huile estérifiée issue de la noix de coco, offrant un toucher soyeux non gras et une excellente protection de la barrière cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622f-78ce-b545-ef5b37efc68b', '__OWNER_ID__', 'Ceramide NG', 'ceramide-ng', 'Un lipide intercellulaire essentiel (anciennement Céramide 2) qui renforce le ciment de la peau pour empêcher la déshydratation et l’intrusion d’irritants.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6235-7691-9fe0-f07caab1b218', '__OWNER_ID__', 'Rétinol', 'retinol', 'Dérivé de la vitamine A, puissant anti-âge qui accélère le renouvellement cellulaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6231-72b8-8345-cf15e4bb4fac', '__OWNER_ID__', 'Polyisobutène Hydrogéné (Hydrogenated Polyisobutene)', 'hydrogenated-polyisobutene', 'L''émollient de haute pureté au fini brillant : une alternative synthétique au squalane offrant une protection barrière supérieure et un toucher soyeux.', '# Le Polyisobutène Hydrogéné : L''Émollient Sublimateur de Barrière
INSERT INTO public.ingredients VALUES ('019de0ab-6231-74cf-ba19-78ff8c18019e', '__OWNER_ID__', 'Tribehenin (Glyceryl Tribehenate)', 'tribehenin', 'L''expert de la structuration lipidique : un triglycéride à longue chaîne qui scelle l''hydratation et apporte une onctuosité sophistiquée aux formules barrières.', '# La Tribehenin : L''Agent de Cohésion et de Protection Cutanée
INSERT INTO public.ingredients VALUES ('019de0ab-6231-769d-9083-6cee864652b6', '__OWNER_ID__', 'Glyceryl Dibehenate', 'glyceryl-dibehenate', 'L''architecte de la texture et du confort : un ester de glycérol haute performance qui structure les formules et offre un fini velouté longue durée.', '# Le Glyceryl Dibehenate : L''Agent de Texture aux Vertus Émollientes
INSERT INTO public.ingredients VALUES ('019de0ab-6231-7854-8cfd-bcb249abf526', '__OWNER_ID__', 'Dicaprylyl Ether', 'dicaprylyl-ether', 'L''alternative végétale aux silicones : un émolllient au toucher ''dry-touch'' exceptionnel qui sublime la sensorialité sans alourdir la formule.', '# Le Dicaprylyl Ether : L''Élégance Sensorielle Haute Performance
INSERT INTO public.ingredients VALUES ('019de0ab-622e-7959-8ba0-a1d3982ac7fa', '__OWNER_ID__', 'Butylene Glycol', 'butylene-glycol', 'Humectant synthétique multifonction, qui attire l''humidité et améliore la sensorialité des formules skincare sans alourdir.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622e-7a16-8e66-77ac561959d6', '__OWNER_ID__', 'Acide Oléique (Oméga-9)', 'oleic-acid', 'L’acide gras le plus abondant de notre film hydrolipidique, essentiel pour la souplesse de la peau et l’absorption des actifs.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622e-7b53-9865-2755adc77e68', '__OWNER_ID__', 'Beurre de Cacao (Theobroma Cacao)', 'theobroma-cacao-butter', 'Un beurre végétal généreux, riche en polyphénols antioxydants, offrant une protection barrière exceptionnelle et un parfum naturellement gourmand.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622f-7ac6-9f8d-17e374f90484', '__OWNER_ID__', 'Camellia Japonica Seed Oil', 'camellia-japonica-seed-oil', 'Une huile précieuse utilisée par les Japonaises depuis des siècles pour ses vertus antioxydantes, nourrissantes et sa texture ultra-fine.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622f-7c4a-9212-f3fef3fb44ea', '__OWNER_ID__', 'Prunus Armeniaca Kernel Oil', 'prunus-armeniaca-kernel-oil', 'Une huile illuminatrice qui redonne du peps aux peaux ternes tout en renforçant le film hydrolipidique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6230-7058-9a41-ac78ada8ac31', '__OWNER_ID__', 'Ricinus Communis Seed Oil (Huile de Ricin)', 'ricinus-communis-seed-oil', 'Huile végétale dense et protectrice, reconnue pour ses propriétés fortifiantes, adoucissantes et purifiantes.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6232-7be7-a89c-af6b75b46b00', '__OWNER_ID__', 'Ethylhexyl Palmitate', 'ethylhexyl-palmitate', 'Un ester émollient polyvalent offrant une texture soyeuse et une excellente capacité d’étalement, souvent utilisé comme alternative aux silicones.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6235-78ae-96f8-fef7f414a1d2', '__OWNER_ID__', 'Bakuchiol', 'bakuchiol', 'Alternative végétale douce au rétinol, anti-âge sans irritation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6232-7c88-bc1d-063cb1e5a3d5', '__OWNER_ID__', 'C15-19 Alkane', 'c15-19-alkane', 'Alcane biomimétique d''origine végétale (canne à sucre / olive), émollient sec qui remplace silicones et huiles minérales avec un toucher fluide et non gras.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6232-7d2b-8388-bde0452322bc', '__OWNER_ID__', 'C10-18 Triglycerides', 'c10-18-triglycerides', 'Triglycérides solides à chaînes moyennes-longues, lipides biomimétiques qui structurent la phase grasse et apportent un confort cutané proche du sébum.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6232-7dea-85e9-46af68c4214a', '__OWNER_ID__', 'Helianthus Annuus Seed Wax (Cire de Tournesol)', 'helianthus-annuus-seed-wax', 'Cire végétale issue des graines de tournesol, agent structurant et film occlusif souple qui retient l''hydratation et stabilise les baumes.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6233-73d0-b60e-dd897a875eef', '__OWNER_ID__', 'LHA (Capryloyl Salicylic Acid)', 'capryloyl-salicylic-acid', 'Un dérivé de l’acide salicylique à chaîne grasse, offrant une exfoliation cellule par cellule d’une précision chirurgicale, sans aucune irritation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6237-7043-a5a3-c3d9ecb1d598', '__OWNER_ID__', 'Rétinal', 'retinal', 'Précurseur direct de l’acide rétinoïque, jusqu’à 11 fois plus rapide que le rétinol pour transformer la texture de la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-7c06-be3e-78c1b26ef983', '__OWNER_ID__', 'Soufre (Sulfur)', 'sulfur-hair', 'Élément minéral kératolytique et séborrhéostatique historique, actif sur Malassezia et les bactéries du cuir chevelu, utilisé en shampoings et lotions traitants.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6233-7aa2-9658-59fc7df2ef31', '__OWNER_ID__', 'Gluconolactone (PHA)', 'pha', 'PHA (polyhydroxy acid) dérivé de l''acide gluconique, naturellement présent dans les fruits, le miel et le vin. Exfoliant chimique de nouvelle génération — plus doux que les AHAs grâce à sa grande molécule, avec en bonus des propriétés humectantes, antioxydantes et chélatantes.', '## Mécanisme d''action
INSERT INTO public.ingredients VALUES ('019de0ab-6233-7cce-8553-43b46e2f8c48', '__OWNER_ID__', 'Acide Glycolique', 'glycolic-acid', 'AHA le plus petit, exfolie en surface pour lisser et éclaircir le teint.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6234-752b-815f-bf889024765f', '__OWNER_ID__', 'Acide Mandélique', 'mandelic-acid', 'Le plus doux des AHA. Exfolie en surface, purifie les pores et unifie le teint, idéal pour les peaux sensibles ou mates.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6241-77bc-b3ff-7e453f49f9a1', '__OWNER_ID__', 'Asiaticoside (Centella asiatica)', 'asiaticoside', 'Triterpène signature de Centella asiatica, puissant cicatrisant, stimulant la synthèse de collagène et apaisant pour peaux irritées, sensibles ou lésées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623e-7b85-a687-b29813999d93', '__OWNER_ID__', '3-O-Ethyl Ascorbic Acid', '3-o-ethyl-ascorbic-acid', 'Dérivé éthylé ultra-stable, bonne pénétration et activité proche de la pure.', '# 3-O-Ethyl Ascorbic Acid
INSERT INTO public.ingredients VALUES ('019de0ab-6234-7fcd-b384-42aab83d1e05', '__OWNER_ID__', 'Retinyl Palmitate', 'retinyl-palmitate', 'Ester de vitamine A le plus doux et stable, entrée élégante et progressive dans l’univers des rétinoïdes pour les peaux sensibles en quête d’éclat subtil et de texture affinée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6235-7103-a6d5-fac882a8a147', '__OWNER_ID__', 'Hydroxypinacolone Retinoate (HPR)', 'hydroxypinacolone-retinoate', 'Rétinoïde de nouvelle génération à action directe, alliant efficacité prouvée et tolérance exceptionnelle pour un renouvellement cutané harmonieux et sans compromis.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623e-7c5a-bb2a-ba95cd5e5900', '__OWNER_ID__', 'Ascorbyl Palmitate', 'ascorbyl-palmitate', 'Dérivé liposoluble basique, antioxydant dans les formules huileuses.', '# Ascorbyl Palmitate
INSERT INTO public.ingredients VALUES ('019de0ab-6235-7465-9670-86befaadad10', '__OWNER_ID__', 'Granactive Retinoid (HPR)', 'granactive-retinoid', 'Un ester d’acide rétinoïque direct qui offre les bénéfices de la vitamine A avec un risque d’irritation proche de zéro.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6235-75db-862e-a737c4eec25b', '__OWNER_ID__', 'Rétinyl Rétinoate', 'retinyl-retinoate', 'Une molécule hybride de nouvelle génération, plus puissante que le rétinol classique mais beaucoup mieux tolérée par la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6237-796e-a435-f4d5b7128094', '__OWNER_ID__', 'Palmitoyl Oligopeptide', 'palmitoyl-oligopeptide', 'Un peptide de signal anti-âge qui stimule la synthèse de collagène et d''élastine pour réduire les rides et raffermir le tissu cutané.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623e-7d20-8560-e82f2f69859f', '__OWNER_ID__', 'Thé Vert', 'green-tea', 'Puissant antioxydant naturel riche en polyphénols, idéal pour apaiser, protéger et purifier la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-7e69-8bad-3b06abcd2ce9', '__OWNER_ID__', 'Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine', 'bis-ethylhexyloxyphenol-methoxyphenyl-triazine', 'Filtre UV chimique organique large spectre breveté (Tinosorb® S / Bemotrizinol), photostable et efficace contre UVA/UVB, protège durablement contre le photo-vieillissement et les dommages solaires tout en stabilisant d''autres filtres comme l''avobenzone.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6238-7282-9892-11333efb90c6', '__OWNER_ID__', 'Acetyl Tetrapeptide-5', 'acetyl-tetrapeptide-5', 'Peptide spécifique (Eyeseryl) qui lutte contre l’oedème et la glycation pour réduire les poches sous les yeux en un temps record.', '
INSERT INTO public.ingredients VALUES ('019e9ab6-d079-7dea-a8ca-036a3dc5dd7c', '__OWNER_ID__', 'Copper Lysinate/Prolinate', 'copper-lysinate-prolinate', 'Sel de cuivre d''un mélange de lysine et proline (Neodermyl), actif anti-âge de la famille des copper peptides, stimule la synthèse de collagène.', '# Copper Lysinate/Prolinate
INSERT INTO public.ingredients VALUES ('019de0ab-6239-794e-a631-54de7fc1af79', '__OWNER_ID__', 'Acide Férulique', 'ferulic-acid', 'Un antioxydant végétal puissant qui neutralise les radicaux libres et booste l’efficacité des vitamines C et E.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623a-7a75-ab8e-56e36e7ef619', '__OWNER_ID__', 'Vitamine B12 (Cyanocobalamine)', 'cyanocobalamin', 'Vitamine essentielle reconnaissable à sa couleur rose naturelle, elle apaise les inflammations chroniques comme l’eczéma ou la rosacée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623b-710f-9b8f-7c1e7ce3cd52', '__OWNER_ID__', 'Tocopheryl Acetate', 'tocopheryl-acetate', 'Forme stabilisée de la vitamine E, utilisée pour protéger la peau du stress oxydatif et renforcer la barrière cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623b-724b-adeb-0896eef05eca', '__OWNER_ID__', 'Resvératrol', 'resveratrol', 'Polyphénol antioxydant puissant issu notamment du raisin, aux propriétés anti-âge, anti-inflammatoires et photoprotectrices. Sirotuines-activateur avec un recul clinique croissant en cosmétique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623b-742d-bbd6-78e5f2ac4027', '__OWNER_ID__', 'Pré-tocophéryl (Tocopheryl glucoside)', 'tocopheryl-glucoside', 'Précurseur photostable de la Vitamine E offrant une protection antioxydante continue et prolongée contre le stress oxydatif.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623b-7579-87ac-f756ec710f85', '__OWNER_ID__', 'Curcuma Longa Root Extract (Curcuma)', 'curcuma-longa-root-extract', 'Puissant antioxydant et anti-inflammatoire naturel qui booste l''éclat du teint et protège la peau du stress oxydatif.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623c-70c9-a7ae-79c3d3e7565a', '__OWNER_ID__', 'L-Carnosine (Beta-alanyl-L-histidine)', 'carnosine', 'Le bouclier anti-glycation par excellence : un dipeptide biomimétique protégeant le collagène du vieillissement prématuré et du stress oxydatif.', '# La Carnosine : Gardienne de l''Architecture Dermique
INSERT INTO public.ingredients VALUES ('019de0ab-623c-7ffe-9345-18eec32a8bb8', '__OWNER_ID__', 'Tocopherol (Vitamine E)', 'tocopherol', 'Vitamine E liposoluble naturelle, puissant antioxydant qui protège les lipides cutanés contre le stress oxydatif, renforce la barrière et apaise les peaux sensibles ou exposées aux agressions environnementales.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623d-7773-b055-07e33903830e', '__OWNER_ID__', 'Vitamine C', 'vitamin-c', 'Antioxydant puissant qui illumine et protège contre les radicaux libres.', '
INSERT INTO public.ingredients VALUES ('019de0ab-623e-75ec-a9ff-fe7550a08b26', '__OWNER_ID__', 'Ascorbyl Glucoside', 'ascorbyl-glucoside', 'Dérivé stable et doux, libère lentement la vitamine C pour un éclat progressif.', '# Ascorbyl Glucoside
INSERT INTO public.ingredients VALUES ('019de0ab-623f-7db9-ad32-4de6b977fb9a', '__OWNER_ID__', 'Bêta-Glucane (Beta-Glucan)', 'beta-glucan', 'Un polysaccharide naturel extrait de l’avoine ou de la levure, capable de stimuler les défenses immunitaires de la peau tout en offrant une hydratation 20% supérieure à l’acide hyaluronique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-7011-abc0-cd065054d7e7', '__OWNER_ID__', 'Bisabolol', 'bisabolol', 'Actif issu de la Camomille reconnu pour ses vertus calmantes puissantes, idéal pour les peaux sensibles ou irritées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-743d-bb9f-95a95f99d401', '__OWNER_ID__', 'Extrait de Concombre', 'cucumis-sativus-fruit-extract', 'Un extrait végétal riche en vitamines et minéraux, idéal pour apaiser les poches et hydrater les zones délicates.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6234-785f-8e9f-f19760c4c3c6', '__OWNER_ID__', 'Phytic Acid', 'phytic-acid', 'Acide phytique, antioxydant et chélateur de métaux, offrant une exfoliation très douce et protectrice.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6241-7638-9c46-0362e4f7867d', '__OWNER_ID__', 'Centella asiatica', 'centella-asiatica', 'Plante tropicale signature en dermocosmétique, riche en triterpènes (asiaticoside, madécassoside), réparatrice, apaisante et stimulante de collagène pour peaux sensibles, irritées ou lésées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-7811-8876-1372bb88fb50', '__OWNER_ID__', 'Sambucus Nigra Flower Extract', 'sambucus-nigra', 'Extrait de fleur de sureau noir reconnu pour ses propriétés adoucissantes, apaisantes et drainantes.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-78a9-b668-68ddb8dc664c', '__OWNER_ID__', 'Daucus Carota Sativa Root Extract', 'daucus-carota', 'Extrait de carotte riche en bêta-carotène et vitamines, qui apaise, régénère et apporte un effet "bonne mine" naturel.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-7940-a848-c9369c29b2e5', '__OWNER_ID__', 'Madecassoside', 'madecassoside', 'Une molécule pure issue de la Centella Asiatica, reconnue pour ses propriétés exceptionnelles dans la cicatrisation et la réduction de l’inflammation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624f-71a3-a0cf-6fa31f3b6685', '__OWNER_ID__', 'Sclerotium Gum', 'sclerotium-gum', 'Polysaccharide issu de la fermentation fongique, alternatif naturel au carbomer.', '# Sclerotium Gum
INSERT INTO public.ingredients VALUES ('019de0ab-6240-79f7-ac51-08b5859c3bc9', '__OWNER_ID__', 'Royal Jelly Extract', 'royal-jelly-extract', 'Un trésor de la ruche riche en nutriments essentiels qui booste la vitalité cellulaire et la synthèse de collagène.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-7a88-a5fa-fcf54d174071', '__OWNER_ID__', 'Propolis Extract', 'propolis-extract', 'Résine aromatique récoltée par les abeilles, riche en flavonoïdes, aux propriétés apaisantes, cicatrisantes et antibactériennes.', '# Propolis Extract
INSERT INTO public.ingredients VALUES ('019de0ab-6241-74d8-a4ba-a98ccefcbcbc', '__OWNER_ID__', 'Hydrolat de Rose de Damas (Rosa damascena Miller)', 'eau-de-rose', 'Hydrolat aromatique traditionnel aux propriétés légèrement apaisantes et tonifiantes. Apporte une dimension sensorielle mais peut être irritant chez les peaux très réactives ou rosacées.', '# L''Eau de Rose de Damas : Hydrolat Traditionnel à Usage Cosmétique
INSERT INTO public.ingredients VALUES ('019de0ab-6241-7ecc-85c6-2ccf89857206', '__OWNER_ID__', 'Eau de Heartleaf', 'heartleaf-water', 'Distillat aqueux (hydrolat) obtenu à partir des fleurs, feuilles et tiges de Heartleaf, offrant un apaisement immédiat et une base hydratante très douce.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6242-7187-ae16-7c29f55d5c01', '__OWNER_ID__', 'Extrait de Camomille', 'extrait-camomille', 'Extrait des fleurs de camomille (Matricaria chamomilla), reconnu pour ses puissantes propriétés calmantes, anti-inflammatoires et antioxydantes en soin de la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6242-72c0-8a6c-1f4d5a13abaf', '__OWNER_ID__', 'Extrait de Bardane (Burdock Root)', 'arctium-lappa-root-extract', 'Extrait de racine d''Arctium Lappa, reconnu pour ses vertus purifiantes, apaisantes et équilibrantes pour les peaux mixtes à grasses ou sujettes aux imperfections.', '
INSERT INTO public.ingredients VALUES ('019e073d-dbeb-7fed-8a77-50f02ea55926', '__OWNER_ID__', 'Acide Glycyrrhétinique (Glycyrrhetinic Acid)', 'glycyrrhetinic-acid', 'Triterpène extrait de la racine de réglisse (Glycyrrhiza glabra). Anti-inflammatoire topique : inhibe la 11-β-HSD et apaise rougeurs, irritations et eczéma. Très bonne tolérance, usage typique 0.5–2%.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6248-77b0-9e7c-658a20e14ac8', '__OWNER_ID__', 'Bentonite', 'bentonite', 'Argile montmorillonite puissante, reconnue pour son action purifiante intense sur les pores obstrués.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6242-7565-950a-8015ca3f172e', '__OWNER_ID__', 'Dipotassium Glycyrrhizate', 'dipotassium-glycyrrhizate', 'Un sel dérivé de la racine de réglisse, hautement efficace pour apaiser les peaux irritées, réduire les rougeurs et réguler l’inflammation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6248-771c-97f0-d7e4beff90ee', '__OWNER_ID__', 'Kaolin', 'kaolin', 'Argile blanche douce, absorbante et purifiante, adaptée même aux peaux sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6243-748b-a10e-16ecf4edef04', '__OWNER_ID__', 'Hexylresorcinol', 'hexylresorcinol', 'Actif de référence pour corriger l’hyperpigmentation, uniformiser le teint et protéger contre le stress oxydatif.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6243-7ec6-8589-199c61778306', '__OWNER_ID__', 'Acide kojique', 'kojic-acid', 'Produit par fermentation fongique (Aspergillus). Inhibe la tyrosinase pour réduire l''hyperpigmentation. Alternative plus douce à l''hydroquinone, mais instable et photosensibilisant. Max 1 % en UE (2024).', '## Origine
INSERT INTO public.ingredients VALUES ('019de0ab-6244-710b-a7f5-4212e2c855f8', '__OWNER_ID__', 'Acide tranexamique', 'tranexamic-acid', 'Dérivé synthétique de la lysine, développé comme antihémorragique dans les années 1960 par des chercheurs japonais. Reconverti en actif dépigmentant après observation fortuite dans les années 1970 d''une réduction du mélasma chez des patients traités par voie orale. Aujourd''hui considéré comme un actif phare en cosmétique, avec une efficacité comparable à l''hydroquinone et un bien meilleur profil de tolérance en topique (2–5 %). Tendance forte en 2025–2026 (recherches +107 % fin 2024).', '## Origine et historique
INSERT INTO public.ingredients VALUES ('019de0ab-6244-7f29-999a-4da108bf1f2d', '__OWNER_ID__', 'Glutathion', 'glutathion', 'Tripeptide antioxydant naturel (glutamate, cystéine, glycine). Inhibe la tyrosinase et recycle la vitamine C. Très instable (pH < 4, sensible à la chaleur/oxydation). Données cliniques encore faibles pour le blanchiment cutané en 2026 — plutôt un antioxydant secondaire qu''un actif anti-taches de premier plan.', '## Structure & rôle biologique
INSERT INTO public.ingredients VALUES ('019de0ab-6245-757f-879e-4681cb6e5269', '__OWNER_ID__', 'Zinc PCA', 'zinc-pca', 'Actif séborégulateur et antibactérien combinant zinc et PCA pour équilibrer les peaux grasses à imperfections, tout en hydratant sans assécher.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-7f62-9569-56412e7c5edc', '__OWNER_ID__', 'Caféine (Caffeine)', 'caffeine-hair', 'Méthylxanthine qui pénètre le follicule pileux, inhibe la phosphodiestérase et contre l''effet inhibiteur de la DHT sur la croissance capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6246-7288-b687-e9f9e3b926e8', '__OWNER_ID__', 'Copper Sulfate', 'copper-sulfate', 'Sulfate de cuivre aux propriétés antimicrobiennes, astringentes et séborégulatrices, utilisé en faible concentration dans les soins purifiants, anti-acné et assainissants pour peaux grasses à imperfections.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6246-74c5-84ec-60b36b157b30', '__OWNER_ID__', 'Piroctone Olamine', 'piroctone-olamine', 'Agent antifongique puissant ciblant Malassezia, efficace contre pellicules, démangeaisons et irritations du cuir chevelu, très bien toléré même par les peaux sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-73fd-8b72-03e6e8a006ae', '__OWNER_ID__', 'Avobenzone (Butyl Methoxydibenzoylmethane)', 'butyl-methoxydibenvoylmethane', 'Le filtre de référence pour l’absorption des UVA longs, protégeant les structures profondes de la peau contre le vieillissement actinique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-74c1-aa5c-4d39735cb87a', '__OWNER_ID__', 'Octocrylene', 'octocrylene', 'Un filtre UVB liquide qui joue un rôle crucial de stabilisateur pour les autres filtres solaires, tout en renforçant la résistance à l’eau des formules.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-758f-8666-48c691ef08eb', '__OWNER_ID__', 'Homosalate', 'homosalate', 'Un filtre organique liquide spécialisé dans l’absorption des rayons UVB, souvent utilisé pour ajuster la fluidité des protections solaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-764c-9820-b066082af431', '__OWNER_ID__', 'Ethylhexyl Salicylate (Octisalate)', 'ethylhexyl-salicylate', 'Un filtre UVB complémentaire qui agit également comme un solvant pour stabiliser et homogénéiser les mélanges de filtres solaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7fda-8883-b5649d58c733', '__OWNER_ID__', 'Hydroxyethylcellulose', 'hydroxyethylcellulose', 'Épaississant cellulosique d''origine naturelle, inerte et très bien toléré.', '# Hydroxyethylcellulose
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7227-b991-7d9560569f29', '__OWNER_ID__', 'Cetyl Alcohol', 'cetyl-alcohol', 'Alcool gras solide structurant les émulsions, émollient doux et non asséchant.', '# Cetyl Alcohol
INSERT INTO public.ingredients VALUES ('019de0ab-624f-72eb-a769-33a299244108', '__OWNER_ID__', 'Stearyl Alcohol', 'stearyl-alcohol', 'Alcool gras en C18 structurant les crèmes épaisses, émollient léger.', '# Stearyl Alcohol
INSERT INTO public.ingredients VALUES ('019de0ab-6249-76fb-86ae-bb85eb65d3d1', '__OWNER_ID__', 'Ethylhexyl Triazone', 'ethylhexyl-triazone', 'L’un des filtres UVB les plus puissants et les plus stables au monde, permettant d’atteindre des indices SPF élevés avec une excellente tolérance cutanée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-7794-affb-38351258a120', '__OWNER_ID__', 'Diethylamino Hydroxybenzoyl Hexyl Benzoate', 'diethylamino-hydroxybenzoyl-hexyl-benzoate', 'Filtre solaire organique de nouvelle génération, extrêmement stable, offrant une protection haute performance contre les rayons UVA responsables du photovieillissement.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-7b27-891c-2685ced0ba52', '__OWNER_ID__', 'Diethylhexyl Butamido Triazone (Uvasorb HEB)', 'diethylhexyl-butamido-triazone', 'Filtre UV organique à large spectre UVB/UVA, très photostable et résistant à l''eau, utilisé dans les formules solaires haute performance.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-7c26-ac64-afc822ba591d', '__OWNER_ID__', 'Oxydes de fer (Iron oxides)', 'oxide-de-fer', 'Pigments minéraux naturels assurant la coloration des soins et offrant une protection complémentaire contre la lumière bleue.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7ab2-91c7-de401b82a2c6', '__OWNER_ID__', 'Sodium Chloride', 'sodium-chloride', 'Sel de table. Ajuste la viscosité et la tonicité des formules aqueuses.', '# Sodium Chloride
INSERT INTO public.ingredients VALUES ('019de0ab-624a-70ce-92dd-97c748027ec3', '__OWNER_ID__', 'Ethylhexyl Methoxycinnamate (Octinoxate)', 'ethylhexyl-methoxycinnamate', 'Filtre UVB organique parmi les plus répandus au monde, liposoluble et efficace, bien que controversé pour son impact sur les coraux et son potentiel perturbateur endocrinien.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624a-719e-8173-47ac32108686', '__OWNER_ID__', 'Méthylène Bis-Benzotriazolyl Tétraméthylbutylphénol (Tinosorb M)', 'methylene-bis-benzotriazolyl-tetramethylbutylphenol', 'Filtre UV hybride (organique/minéral-like) à large spectre UVA/UVB, photostable, faible pénétration cutanée grâce à ses particules micronisées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624a-72c5-a0cf-36c1a8149a64', '__OWNER_ID__', 'Tris-Biphényl Triazine (Tinosorb A2B)', 'tris-biphenyl-triazine', 'Filtre UV large spectre sous forme nanoparticulaire (Tinosorb A2B), photostable, à faible pénétration cutanée, offrant une protection UVA/UVB sans voile blanc.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624a-752d-a176-a59d3ac8f78b', '__OWNER_ID__', 'Vitreoscilla Ferment', 'vitreoscilla-ferment', 'Un extrait biotechnologique issu d’une bactérie thermale, agissant comme un coach cellulaire pour renforcer les défenses immunitaires de la peau et apaiser les états inflammatoires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624a-7630-b7f0-e07e6b097e51', '__OWNER_ID__', 'Fructo-oligosaccharides (FOS)', 'fructooligosaccharides', 'Sucres complexes agissant comme des prébiotiques sélectifs pour nourrir la flore cutanée bénéfique et sceller l’hydratation au cœur de l’épiderme.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624a-78c2-a9f2-fbc90021d074', '__OWNER_ID__', 'Filtrat de Bave d’Escargot (Snail Mucin)', 'snail-secretion-filtrate', 'Une alliance biologique unique de mucopolysaccharides, d’allantoïne et d’acide glycolique pour une réparation cutanée profonde et une hydratation durable.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7097-b6a4-a8f7c0ce48ff', '__OWNER_ID__', 'Alpha-Glucan Oligosaccharide (BioEcolia®)', 'alpha-glucan-oligosaccharide', 'Prébiotique protecteur qui rééquilibre le microbiome cutané, renforce les défenses naturelles et préserve l''écosystème de la peau.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624f-76c0-a253-d5fc8bfb9452', '__OWNER_ID__', 'Phenyl Trimethicone', 'phenyl-trimethicone', 'Silicone non volatil apportant brillance et protection occlusive légère.', '# Phenyl Trimethicone
INSERT INTO public.ingredients VALUES ('019de0ab-624f-710f-bcf7-5c1ac6fa4e19', '__OWNER_ID__', 'Sodium Polyacrylate', 'sodium-polyacrylate', 'Super-absorbant polymérique utilisé pour les textures gel aériennes et légères.', '# Sodium Polyacrylate
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7669-b6a3-b36f2f3eedc2', '__OWNER_ID__', 'Galactomyces Ferment Filtrate (Pitera)', 'galactomyces-ferment-filtrate', 'Un ferment riche en nutriments, vitamines et acides aminés qui améliore la texture, l’éclat et la barrière cutanée.', '
INSERT INTO public.ingredients VALUES ('019e9ab6-d07e-785c-b6bf-d06dd59d6416', '__OWNER_ID__', 'Rahnella/Soy Protein Ferment', 'rahnella-soy-protein-ferment', 'Postbiotique fermenté de protéines de soja par Rahnella (Bio-Bustyl), actif fermeté et hydratation souvent associé au Palmitoyl Oligopeptide dans la même formule.', '# Rahnella/Soy Protein Ferment
INSERT INTO public.ingredients VALUES ('019de0ab-624b-7b31-a659-e39aa6d47134', '__OWNER_ID__', 'Adénosine (Adenosine)', 'adenosine', 'Nucléoside naturellement présent dans l''organisme, reconnu pour son action lissante, anti-rides et énergisante cellulaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624c-7191-928c-dd6b8c150f12', '__OWNER_ID__', 'Acide Madécassique (Madecassic Acid)', 'madecassic-acid', 'Une fraction purifiée de Centella Asiatica dédiée à la restructuration des tissus et à la réduction des micro-inflammations cutanées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624c-7269-9f7a-1e9539683271', '__OWNER_ID__', 'Panthenol (Provitamine B5)', 'panthenol', 'Provitamine B5 hydratante et réparatrice, convertie en acide pantothénique dans la peau, apaise, renforce la barrière cutanée et accélère la cicatrisation pour peaux sensibles, irritées ou lésées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624c-771b-8d5a-383da6642637', '__OWNER_ID__', 'Calcium Pantothenate (Provitamine B5 calcique)', 'calcium-pantothenate', 'Sel calcique de l''acide pantothénique (provitamine B5), apaisant, hydratant et réparateur — équivalent ionique du panthénol.', '# Calcium Pantothenate
INSERT INTO public.ingredients VALUES ('019e9ab6-d07f-7c3b-9995-70ae56e02254', '__OWNER_ID__', 'Methylsilanol Mannuronate', 'methylsilanol-mannuronate', 'Organosilicium topique (Algisium C) délivrant du silicium à la peau, soutient les fibres de collagène et d''élastine, améliore la fermeté et l''élasticité cutanée.', '# Methylsilanol Mannuronate
INSERT INTO public.ingredients VALUES ('019de0ab-624c-7b81-9a0d-d145dff65c4a', '__OWNER_ID__', 'Caféine', 'caffeine', 'Alcaloïde végétal réputé pour son action stimulante sur la microcirculation et ses propriétés lipolytiques (brûle-graisses).', '
INSERT INTO public.ingredients VALUES ('019de0ab-624c-7e5b-8336-62775efd53a8', '__OWNER_ID__', 'Escin (Aesculus hippocastanum)', 'escin', 'Saponine triterpénique d''exception issue du marron d''Inde. Veinotonique, anti-œdémateuse et anti-inflammatoire, elle intègre désormais des propriétés antivirales, anticancérigènes et une biodisponibilité cutanée prouvée pour les peaux fragiles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-7629-9e94-feaeb07644a8', '__OWNER_ID__', 'Sodium Cocoyl Isethionate (SCI)', 'sodium-cocoyl-isethionate', 'Surnommé "mousse de bébé", ce tensioactif solide issu de l’huile de coco offre une mousse riche et crémeuse sans effet desséchant.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-76ea-8aa2-81dce20e32c5', '__OWNER_ID__', 'Coco-Glucoside', 'coco-glucoside', 'Un tensioactif non-ionique ultra-doux issu de la noix de coco et du sucre, conçu pour nettoyer la peau sans altérer son précieux film hydrolipidique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-7845-9e14-863349949c6f', '__OWNER_ID__', 'Decyl Glucoside', 'decyl-glucoside', 'Tensioactif non ionique particulièrement doux, adapté aux peaux sensibles et aux formules nettoyantes délicates.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6255-7a82-a470-ac5898540f69', '__OWNER_ID__', 'Xylitol', 'xylitol-dental', 'Un sucre naturel qui combat les bactéries responsables des caries.', 'Le xylitol est un édulcorant naturel issu du bouleau qui ne peut pas être fermenté par les bactéries buccales. Il aide à réduire la formation de la plaque, favorise la salivation et neutralise l''acidité, créant un environnement défavorable aux caries.', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.649+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, 'Xylitol');
INSERT INTO public.ingredients VALUES ('019de0ab-624d-78e0-a2a5-860c3ac81712', '__OWNER_ID__', 'PEG-20 Glyceryl Triisostearate', 'peg-20-glyceryl-triisostearate', 'Émulsifiant très efficace utilisé principalement dans les huiles et baumes démaquillants pour permettre un rinçage parfait à l’eau.', '
INSERT INTO public.ingredients VALUES ('019e9ab6-d080-7da9-a180-d2a138b35344', '__OWNER_ID__', 'Capryloyl Glycine', 'capryloyl-glycine', 'Dérivé d''acide aminé (glycine + acide caprylique C8), actif antimicrobien doux et séborégulateur utilisé comme agent de conditionnement et conservation.', '# Capryloyl Glycine
INSERT INTO public.ingredients VALUES ('019de0ab-624d-7a4a-b862-560735dfbab1', '__OWNER_ID__', 'Biosaccharide Gum-1', 'biosaccharide-gum-1', 'Un sucre biotechnologique (Fucose) offrant un effet apaisant immédiat et une hydratation sensorielle unique, agissant comme un "S.O.S." pour les peaux stressées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624d-7ae2-b02c-4cf36dad6296', '__OWNER_ID__', 'Silica', 'silica', 'Minéral utilisé pour absorber l’excès de sébum, matifier la peau et améliorer la texture des formules.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7e1a-afda-45f52f3ddd49', '__OWNER_ID__', 'Carbomer', 'carbomer', 'Polymère acrylique inerte qui forme des gels transparents une fois neutralisé.', '# Carbomer
INSERT INTO public.ingredients VALUES ('019de0ab-624e-72dc-94ee-0a33b0fece14', '__OWNER_ID__', 'Amidon de Maïs (Zea Mays Starch)', 'zea-mays-starch', 'L''alternative végétale haute performance au talc : un agent matifiant naturel qui absorbe l''excès de sébum tout en apportant un fini velouté unique.', '# L''Amidon de Maïs : Le Maître de la Matité Végétale
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7e9b-999d-8f0eeb7243c3', '__OWNER_ID__', 'Xanthan Gum', 'xanthan-gum', 'Polysaccharide naturel issu de la fermentation, utilisé pour épaissir et texturer.', '# Xanthan Gum
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7f20-a51b-ac6d99b5a207', '__OWNER_ID__', 'Acrylates/C10-30 Alkyl Acrylate Crosspolymer', 'acrylates-c10-30-alkyl-acrylate-crosspolymer', 'Gélifiant polymère permettant des textures légères, non grasses, très tolérées.', '# Acrylates/C10-30 Alkyl Acrylate Crosspolymer
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7630-ab0a-c7d9ea54221a', '__OWNER_ID__', 'Biosaccharide Gum-4', 'biosaccharide-gum-4', 'Polysaccharide biotechnologique anti-pollution qui forme un film protecteur souple à la surface de la peau et limite l''adhésion des particules.', '# Biosaccharide Gum-4
INSERT INTO public.ingredients VALUES ('019e9ab6-d081-7fc1-a8cf-26667d4787ff', '__OWNER_ID__', 'Ammonium Acryloyldimethyltaurate/VP Copolymer', 'ammonium-acryloyldimethyltaurate-vp-copolymer', 'Gélifiant rhéologique synthétique (Aristoflex AVC) formant des gels aqueux clairs et stables, compatible électrolytes et pH large.', '# Ammonium Acryloyldimethyltaurate/VP Copolymer
INSERT INTO public.ingredients VALUES ('019de0ab-624e-76ca-8377-38f893569936', '__OWNER_ID__', 'Aqua (Water)', 'aqua', 'Solvant universel et phase aqueuse de base de la quasi-totalité des formules cosmétiques.', '# Aqua (Water)
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7750-b455-0d19b2ff0f7a', '__OWNER_ID__', 'Propanediol', 'propanediol', 'Solvant et véhicule d''origine végétale (maïs), alternatif naturel au propylène glycol.', '# Propanediol
INSERT INTO public.ingredients VALUES ('019de0ab-624e-77d3-8025-aff0785403e2', '__OWNER_ID__', 'Citric Acid', 'citric-acid', 'Acide organique naturel utilisé en traces pour ajuster le pH des formules.', '# Citric Acid
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7865-93d3-7da49558388d', '__OWNER_ID__', 'Sodium Hydroxide', 'sodium-hydroxide', 'Base forte utilisée pour neutraliser les acides et ajuster le pH dans les formules.', '# Sodium Hydroxide
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7900-845e-9de9c154addf', '__OWNER_ID__', 'Potassium Hydroxide', 'potassium-hydroxide', 'Base forte utilisée pour ajuster le pH, notamment dans les crèmes et savons.', '# Potassium Hydroxide
INSERT INTO public.ingredients VALUES ('019de0ab-624e-79af-ab73-fbd02c2f01ca', '__OWNER_ID__', 'Triethanolamine', 'triethanolamine', 'Base organique classique pour ajuster le pH des formules gélifiées au carbomer.', '# Triethanolamine (TEA)
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7aca-a241-a0bacbb8c31f', '__OWNER_ID__', 'Tromethamine', 'tromethamine', 'Base organique douce utilisée pour neutraliser les gélifiants et ajuster le pH.', '# Tromethamine (TRIS)
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7cf8-ad34-8d7d49bda04d', '__OWNER_ID__', 'Disodium EDTA', 'disodium-edta', 'Chélateur séquestrant les ions métalliques pour stabiliser les formules.', '# Disodium EDTA
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7376-8ab1-3bbc84f82a17', '__OWNER_ID__', 'Behenyl Alcohol', 'behenyl-alcohol', 'Alcool gras en C22 utilisé dans les crèmes riches et les soins capillaires.', '# Behenyl Alcohol
INSERT INTO public.ingredients VALUES ('019de0ab-624f-73fe-b2fd-eedbd9469949', '__OWNER_ID__', 'PEG-100 Stearate', 'peg-100-stearate', 'Émulsifiant non ionique classique pour émulsions H/E stables et douces.', '# PEG-100 Stearate
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7487-b42e-77cc7de945a4', '__OWNER_ID__', 'Ceteareth-20', 'ceteareth-20', 'Émulsifiant éthoxylé pour émulsions stables, souvent associé à l''alcool cétéarylique.', '# Ceteareth-20
INSERT INTO public.ingredients VALUES ('019de0ab-624f-750f-83fb-d6b0ce9dddbf', '__OWNER_ID__', 'Dimethiconol', 'dimethiconol', 'Silicone hydroxylé apportant lissage et protection de surface.', '# Dimethiconol
INSERT INTO public.ingredients VALUES ('019de0ab-624f-758f-8391-14003cf746d1', '__OWNER_ID__', 'Cyclopentasiloxane (D5)', 'cyclopentasiloxane', 'Silicone cyclique volatil vecteur d''actifs, texture ultra-légère.', '# Cyclopentasiloxane (D5)
INSERT INTO public.ingredients VALUES ('019de0ab-624f-761d-97f8-fdb8e1a01e92', '__OWNER_ID__', 'Cyclohexasiloxane (D6)', 'cyclohexasiloxane', 'Silicone cyclique volatil similaire au D5, vecteur léger.', '# Cyclohexasiloxane (D6)
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7753-a6ac-a98f133d4b9f', '__OWNER_ID__', 'Mineral Oil (Paraffinum Liquidum)', 'mineral-oil', 'Huile minérale occlusive inerte, protège la barrière cutanée en limitant la TEWL.', '# Mineral Oil (Paraffinum Liquidum)
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7868-8e66-0b64461c6ce9', '__OWNER_ID__', 'Isohexadecane', 'isohexadecane', 'Hydrocarbure isoparaffinique léger, véhicule non gras pour actifs lipophiles.', '# Isohexadecane
INSERT INTO public.ingredients VALUES ('019de0ab-624f-78f1-80b3-f0ed951e57ba', '__OWNER_ID__', 'Isododecane', 'isododecane', 'Solvant volatile léger utilisé dans les produits de maquillage et les fonds de teint.', '# Isododecane
INSERT INTO public.ingredients VALUES ('019de0ab-624f-796f-8648-49a025ac02b0', '__OWNER_ID__', 'Dicaprylyl Carbonate', 'dicaprylyl-carbonate', 'Émollient ester léger à toucher sec, alternative aux silicones pour textures fluides.', '# Dicaprylyl Carbonate
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7a02-a1db-5a8472574ad6', '__OWNER_ID__', 'Coco-Caprylate/Caprate', 'coco-caprylate-caprate', 'Ester naturel d''huile de coco, émollient léger à toucher sec et soyeux.', '# Coco-Caprylate/Caprate
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7be7-9e1d-317cd036c03d', '__OWNER_ID__', 'Glyceryl Stearate Citrate', 'glyceryl-stearate-citrate', 'Émulsifiant doux issu d''acide stéarique et d''acide citrique, biocompatible avec la barrière cutanée et adapté aux soins peaux sensibles.', '# Glyceryl Stearate Citrate
INSERT INTO public.ingredients VALUES ('019de0ab-624f-7c84-aad8-67434540cb48', '__OWNER_ID__', 'Sucrose Stearate', 'sucrose-stearate', 'Ester de sucre et d''acide stéarique, émulsifiant ultra-doux et biodégradable adapté aux soins clean beauty et peaux les plus réactives.', '# Sucrose Stearate
INSERT INTO public.ingredients VALUES ('019de0ab-6251-7497-ad9a-8d3da9bbaf2d', '__OWNER_ID__', 'o-Cymen-5-ol (Biosol)', 'o-cymen-5-ol', 'Conservateur doux antimicrobien à large spectre, alternative bien tolérée aux parabènes utilisée dans les soins peaux sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6251-7372-808c-3808dc32594d', '__OWNER_ID__', 'Eau Thermale Avène (Avène Thermal Spring Water)', 'avene-thermal-spring-water', 'Eau thermale unique d''Avène (Hérault), reconnue pour ses propriétés apaisantes et anti-irritantes exceptionnelles sur les peaux sensibles et réactives.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624e-7bad-9926-38b684d7155c', '__OWNER_ID__', 'Sodium Citrate', 'sodium-citrate', 'Sel de sodium de l''acide citrique utilisé comme tampon pour stabiliser le pH.', '# Sodium Citrate
INSERT INTO public.ingredients VALUES ('019de0ab-6251-7666-9991-218b2594bcd8', '__OWNER_ID__', 'Hydrolyzed Yeast Protein', 'hydrolyzed-yeast-protein', 'Hydrolysat de protéines de levure riche en bêta-glucanes et acides aminés, fortifiant et stimulant des défenses cutanées.', '# Hydrolyzed Yeast Protein
INSERT INTO public.ingredients VALUES ('019de0ab-6252-7b28-ba3f-f0a0407b2ef2', '__OWNER_ID__', 'Glycine', 'glycine-supplement', 'Acide aminé conditionnellement essentiel (synthèse endogène insuffisante), composant majeur du collagène et co-agoniste des récepteurs NMDA, avec des effets documentés sur le sommeil, le collagène et le métabolisme.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6254-7ec9-a0f9-88da5970ab5f', '__OWNER_ID__', 'Fluorure de Sodium (Sodium Fluoride)', 'sodium-fluoride', 'L''actif de référence pour la prévention des caries.', 'Le fluorure de sodium renforce l''émail des dents en le rendant plus résistant aux attaques acides des bactéries. Il favorise également la reminéralisation des zones de l''émail qui ont commencé à s''affaiblir, arrêtant ainsi le processus de formation des caries dès le début.', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.634+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, 'Sodium Fluoride');
INSERT INTO public.ingredients VALUES ('019de0ab-6255-708d-aec2-414356e44346', '__OWNER_ID__', 'Huile d''Arbre à Thé (Tea Tree Oil)', 'tea-tree-oil-dental', 'Une alternative naturelle aux antibactériens classiques.', 'L''huile de tea tree possède des propriétés antiseptiques et anti-inflammatoires naturelles. En hygiène buccale, elle aide à réduire la prolifération des bactéries responsables de la mauvaise haleine et aide à apaiser les gencives irritées.', 'actif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.634+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, 'Melaleuca Alternifolia Leaf Oil');
INSERT INTO public.ingredients VALUES ('019de0ab-6255-73e6-b438-8791d990b235', '__OWNER_ID__', 'Silice Hydratée (Hydrated Silica)', 'hydrated-silica', 'Un agent polissant doux utilisé pour éliminer la plaque.', 'La silice hydratée est un abrasif courant qui aide à nettoyer mécaniquement la surface des dents sans rayer l''émail. Elle est efficace pour éliminer les débris alimentaires et les taches de surface légères (café, thé), laissant les dents plus lisses.', 'abrasif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.634+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, 'Hydrated Silica');
INSERT INTO public.ingredients VALUES ('019de0ab-6255-747a-b800-34a00ef70fe7', '__OWNER_ID__', 'Carbonate de Calcium', 'calcium-carbonate-dental', 'Un minéral naturel qui nettoie et renforce les dents.', 'Le carbonate de calcium agit comme un agent de polissage doux. En plus de son action nettoyante, il aide à neutraliser les acides de la plaque et apporte une source de calcium qui peut contribuer à la santé globale des tissus dentaires.', 'abrasif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.635+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, 'Calcium Carbonate');
INSERT INTO public.ingredients VALUES ('019de0ab-6255-76f6-bcaa-2db8580c4546', '__OWNER_ID__', 'Glycérine (Glycerin)', 'glycerin-dental', 'Un agent humectant qui empêche le dentifrice de sécher.', 'La glycérine est utilisée pour maintenir la texture onctueuse du dentifrice. Elle aide également à préserver l''humidité de la formule et donne une sensation de douceur en bouche lors du brossage.', 'excipient', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.635+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, 'Glycerin');
INSERT INTO public.ingredients VALUES ('019de0ab-6255-778c-bc23-c318eab00be7', '__OWNER_ID__', 'Sorbitol', 'sorbitol-dental', 'Un agent de texture qui apporte une touche sucrée sans risque pour les dents.', 'Le sorbitol sert à la fois d''humectant pour garder le produit souple et d''édulcorant non cariogène. Contrairement au sucre, il n''est pas utilisé par les bactéries pour produire des acides, ce qui le rend idéal pour les produits d''hygiène buccale.', 'excipient', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.635+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, 'Sorbitol');
INSERT INTO public.ingredients VALUES ('019de0ab-6255-78a1-8acc-daa9cf2f8dab', '__OWNER_ID__', 'Gomme de Xanthane (Xanthan Gum)', 'xanthan-gum-dental', 'Un épaississant naturel pour une texture homogène.', 'La gomme de xanthane est un agent de texture qui permet de lier les ingrédients entre eux. Elle assure que le dentifrice reste homogène et facile à extraire du tube, tout en contribuant à une sensation agréable en bouche.', 'excipient', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.635+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, 'Xanthan Gum');
INSERT INTO public.ingredients VALUES ('019de0ab-6255-793e-bb3e-ee15061c3b2d', '__OWNER_ID__', 'Gomme de Cellulose (Cellulose Gum / CMC)', 'cellulose-gum-dental', 'Dérivé cellulosique carboxyméthylé très répandu comme épaississant et stabilisant dans les dentifrices, qui donne leur texture pâteuse caractéristique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6255-7c1f-a8f4-3a8912bbc3ed', '__OWNER_ID__', 'Laurylsulfate de Sodium (SLS)', 'sodium-lauryl-sulfate', 'Un agent moussant puissant présent dans de nombreux dentifrices.', 'Le SLS est responsable de la mousse lors du brossage, ce qui aide à répartir les actifs dans toute la bouche. Cependant, chez certaines personnes sensibles, il peut favoriser l''apparition d''aphtes ou causer une sécheresse buccale.', 'tensioactif', '2026-04-30 23:13:40.719796+00', '2026-06-10 12:32:55.636+00', 'dental', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, 'Sodium Lauryl Sulfate');
INSERT INTO public.ingredients VALUES ('019de0ab-6256-703c-b2ba-91548310d4b9', '__OWNER_ID__', 'Arginine', 'arginine-dental', 'Acide aminé basique qui obstrue les tubules dentinaires par dépôt de phosphate de calcium, réduisant la sensibilité dentinaire par occlusion physique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-71ce-9ac3-fa5656a4a528', '__OWNER_ID__', 'Chlorure de Cétylpyridinium (CPC)', 'cetylpyridinium-chloride', 'Tensioactif cationique quaternaire à large spectre antiseptique, utilisé en bain de bouche anti-gingivite comme alternative moins contraignante à la chlorhexidine.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-73e8-9dd7-9ae619bd3430', '__OWNER_ID__', 'Cocamidopropyl Bétaïne', 'cocamidopropyl-betaine-dental', 'Tensioactif amphotère dérivé de l''huile de coco, utilisé comme alternative ou complément au SLS pour une mousse plus douce sur les muqueuses buccales.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-7506-ad6d-d898bf55d1e3', '__OWNER_ID__', 'Sodium Lauryl Sulfate (SLS)', 'sls-hair', 'Tensioactif anionique puissant, agent moussant efficace mais potentiellement irritant pour le cuir chevelu et dénaturant pour les protéines kératiniques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-7b4e-8464-29ec67aef2bf', '__OWNER_ID__', 'Sodium Cocoyl Glutamate', 'sodium-cocoyl-glutamate', 'Tensioactif anionique dérivé de l''acide glutamique et du coco, très doux, certifiable naturel, adapté aux shampoings sans sulfates pour cheveux sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-7627-8f55-ebf39434c51c', '__OWNER_ID__', 'Sodium Laureth Sulfate (SLES)', 'sles-hair', 'Version éthoxylée du SLS, plus douce et moins irritante, tensioactif anionique de référence dans la majorité des shampoings du marché.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-76f7-a189-4baa0df981ba', '__OWNER_ID__', 'Ammonium Lauryl Sulfate', 'ammonium-lauryl-sulfate', 'Analogue ammonium du SLS, tensioactif anionique puissant produisant une mousse dense, légèrement plus doux que son homologue sodique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-79ef-9dda-71bd58365d94', '__OWNER_ID__', 'Disodium Laureth Sulfosuccinate', 'disodium-laureth-sulfosuccinate', 'Tensioactif anionique doux dérivé du succinate, très bien toléré sur cuir chevelu sensible et cheveux colorés, utilisé en co-tensioactif.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6256-7aa3-8a7f-70cf12516e7c', '__OWNER_ID__', 'Sodium Lauroyl Sarcosinate', 'sodium-lauroyl-sarcosinate', 'Tensioactif anionique acide aminé (sarcosinique), doux, naturel, avec un pH de formulation favorable au respect du microbiome du cuir chevelu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6257-7088-92d6-ca454d83b779', '__OWNER_ID__', 'Cocamidopropyl Betaine', 'cocamidopropyl-betaine', 'Co-tensioactif amphotère de référence dérivé du coco, adoucit les formules sulfatées, améliore la mousse et la douceur sensorielle tout en conditionnant légèrement la fibre.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6257-72b7-a3f5-1ce0db4c9e7f', '__OWNER_ID__', 'Coco-Betaine', 'coco-betaine', 'Bétaïne de coco sans liaison amide, tensioactif amphotère plus pur et moins susceptible aux impuretés allergisantes que la cocamidopropyl bétaïne.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6257-73ba-9f32-2b14e9922afd', '__OWNER_ID__', 'Sodium Cocoamphoacetate', 'sodium-cocoamphoacetate', 'Tensioactif amphotère dérivé des acides gras de coco et de l''acide acétique, très doux, adapté aux shampoings bébé et formules pour cuirs chevelus sensibles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-75fe-b4e9-f838f9630a4c', '__OWNER_ID__', 'Sorbitol', 'sorbitol-hair', 'Polyol sucre naturel hautement hygroscopique, doux et non fermentescible, humectant de la fibre et du cuir chevelu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-71a2-b239-2b238b8366f6', '__OWNER_ID__', 'Alcool Cétylique (Cetyl Alcohol)', 'cetyl-alcohol-hair', 'Alcool gras saturé C16 solide, épaississant et co-émulsifiant essentiel des après-shampooings, apporte corps, onctuosité et douceur sans alourdir.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6257-74dc-bd3c-c950f4afa526', '__OWNER_ID__', 'Disodium Cocoamphodiacetate', 'disodium-cocoamphodiacetate', 'Version di-acétate des amphotères coco, tensioactif très doux à double charge anionique, excellent co-tensioactif pour formules cuir chevelu sensible et anti-pelliculaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6257-75c4-9a0a-98cb3bc34e7c', '__OWNER_ID__', 'Lauryl Glucoside', 'lauryl-glucoside', 'Alkyl glucoside à chaîne C12 laurique, tensioactif non ionique naturel avec le meilleur équilibre détersivité/douceur de la famille APG.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6257-76fc-9036-d50247314c3d', '__OWNER_ID__', 'Caprylyl/Capryl Glucoside', 'caprylyl-capryl-glucoside', 'Mélange APG de courtes chaînes C8–C10, tensioactif non ionique très doux avec propriétés émulsifiantes et solubilisantes, idéal pour formules légères et bébé.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6257-77f0-98a8-bbe7d9ad53dd', '__OWNER_ID__', 'Polysorbate 20', 'polysorbate-20', 'Ester de sorbitan éthoxylé (laurate), solubilisant non ionique léger, principalement utilisé pour incorporer les huiles et parfums dans les formules aqueuses capillaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622c-7c0e-9699-f20f5a21ba2b', '__OWNER_ID__', 'L-Arginine (Arginine)', 'arginine', 'L''acide aminé activateur de microcirculation : un précurseur d''oxyde nitrique qui booste la régénération cellulaire et la synthèse du collagène.', '# L''Arginine : Le Carburant de la Régénération et de l''Éclat
INSERT INTO public.ingredients VALUES ('019de0ab-6257-7a68-a2b8-e3d8da24c235', '__OWNER_ID__', 'Polysorbate 60', 'polysorbate-60', 'Ester de sorbitan éthoxylé (stéarate), émulsifiant non ionique à HLB élevé, utilisé pour stabiliser les émulsions légères dans après-shampooings et traitements capillaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6257-7bb2-99a3-b1d3bdd5d0e2', '__OWNER_ID__', 'Polysorbate 80', 'polysorbate-80', 'Ester de sorbitan éthoxylé (oléate), émulsifiant non ionique polyvalent, solubilise huiles et silicones dans les formules aqueuses et améliore l''étalement des soins capillaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-790d-ae70-6f07761e7c98', '__OWNER_ID__', 'Beurre de Cacao (Theobroma Cacao Seed Butter)', 'cacao-butter-hair', 'Beurre solide extrait des fèves de cacao, riche en acides stéarique et palmitique, hautement occlusif avec une texture fondante au contact de la chaleur corporelle, il protège la fibre capillaire de la déshydratation et du casse.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6257-7d2c-a208-fd9312778ae3', '__OWNER_ID__', 'Behentrimonium Chloride', 'behentrimonium-chloride', 'Tensioactif cationique C22 à longue chaîne, conditionneur puissant qui se dépose substantivement sur la fibre kératinique chargée négativement, réduisant la friction et les nœuds.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6257-7f7b-b174-01a22080159e', '__OWNER_ID__', 'Cetrimonium Chloride', 'cetrimonium-chloride', 'Tensioactif cationique C16 palmitique, conditionneur léger à déposition modérée, utilisé pour le démêlage et la douceur dans les après-shampooings et leave-ins.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-728b-b1b4-1789b030e1b0', '__OWNER_ID__', 'Alcool Cétéarylique (Cetearyl Alcohol)', 'cetearyl-alcohol-hair', 'Mélange d''alcools gras C16–C18, co-émulsifiant et épaississant polyvalent, confère corps et texture crémeuse à la majorité des après-shampooings et masques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-7345-8eed-4c659d13ab9d', '__OWNER_ID__', 'Alcool Stéarylique (Stearyl Alcohol)', 'stearyl-alcohol-hair', 'Alcool gras saturé C18 à point de fusion élevé, épaississant robuste qui confère une texture dense et riche aux masques et après-shampooings intensifs.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-7487-8a57-fb6181e6d429', '__OWNER_ID__', 'Diméthicone (Dimethicone)', 'dimethicone-hair', 'Silicone linéaire polydiméthylsiloxane, forme un film occlusif sur la cuticule qui apporte brillance, lissage et protection mécanique, mais s''accumule sans shampoings sulfatés.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7685-b0c2-0a67480fb6b0', '__OWNER_ID__', 'Sodium PCA', 'sodium-pca-hair', 'Composant clé du facteur naturel d''hydratation (NMF), hygroscopique puissant identique à celui produit naturellement dans le cortex capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-75b6-a8fe-31ab0e89b797', '__OWNER_ID__', 'Amodiméthicone (Amodimethicone)', 'amodimethicone', 'Silicone aminofonctionnelle se déposant préférentiellement sur les zones endommagées de la fibre capillaire, conditionneur ciblé à haute substantivité.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-781f-93e9-d4f700c51ff8', '__OWNER_ID__', 'Polysilicone-15', 'polysilicone-15', 'Silicone polymère avec groupements UV-filtrants organiques, double fonction conditionneur et filtre UV solaire pour la protection de la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6232-794d-8624-d68abe07e06c', '__OWNER_ID__', 'Evening Primrose Oil (Oenothera Biennis Oil)', 'evening-primrose-oil', 'Huile d’onagre riche en acides gras essentiels (oméga-6), idéale pour nourrir les peaux sèches et apaiser les inflammations.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-744f-afa9-588adb9fe9d3', '__OWNER_ID__', 'PEG-40 Huile de Ricin Hydrogénée (PEG-40 Hydrogenated Castor Oil)', 'peg-40-hydrogenated-castor-oil', 'Agent solubilisant PEGylé de l''huile de ricin hydrogénée, incorpore les huiles essentielles, silicones et actifs lipophiles dans les phases aqueuses des shampoings et soins capillaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-7bed-b191-b2d1b7f07947', '__OWNER_ID__', 'Polyquaternium-7', 'polyquaternium-7', 'Polymère cationique acrylique (DADMAC/acrylamide), conditionneur léger très utilisé dans les shampoings pour son dépôt filmogène résistant à l''eau sans alourdir.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6258-7c9c-9587-4dda9ff8371a', '__OWNER_ID__', 'Polyquaternium-10', 'polyquaternium-10', 'Cellulose quaternisée (hydroxypropyl trimonium chlorure), conditionneur filmogène d''origine naturelle, apporte volume et corps sans alourdir les cheveux fins.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7a51-9411-e3aabcafa657', '__OWNER_ID__', 'Bétaïne (Betaine)', 'betaine-hair', 'Osmolyte naturel extrait de la betterave sucrière, humectant doux et non irritant, protège la fibre et le cuir chevelu du stress osmotique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7018-ba9c-901c47b66fc5', '__OWNER_ID__', 'Guar Hydroxypropyltrimonium Chloride', 'guar-hydroxypropyltrimonium-chloride', 'Gomme de guar quaternisée, conditionneur naturel cationique formant un film doux et substantif sur la fibre capillaire, adapté aux formules naturelles et CG-friendly.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7297-9e51-f68b3f0f9404', '__OWNER_ID__', 'Aqua (Water)', 'aqua-hair', 'Base universelle de toute formulation cosmétique, solvant principal des actifs hydrophiles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7331-bf1e-74c86e4e8a76', '__OWNER_ID__', 'Glycérine (Glycerin)', 'glycerin-hair', 'Humectant polyol de référence, attire et retient l''eau atmosphérique dans la fibre capillaire et sur le cuir chevelu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7400-97d3-3c5c1c9adc48', '__OWNER_ID__', 'Propylène Glycol (Propylene Glycol)', 'propylene-glycol-hair', 'Diol synthétique humectant et solvant, favorise la pénétration des actifs dans la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7555-84fb-d4fae142ac3b', '__OWNER_ID__', 'Pentylène Glycol (Pentylene Glycol)', 'pentylene-glycol-hair', 'Humectant diol C5 à double action : hydratation et renforcement du système conservateur, compatible formules naturelles.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-774b-b795-0e55756f506e', '__OWNER_ID__', 'Panthénol (Pro-Vitamine B5)', 'panthenol-hair', 'Pro-vitamine B5 qui pénètre le cortex capillaire, forme des liaisons hydrogène avec la kératine et améliore résistance, hydratation et brillance.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-77eb-b4ed-9d1510c05218', '__OWNER_ID__', 'Aloe Vera (Aloe Barbadensis Leaf Juice)', 'aloe-vera-hair', 'Jus de feuille d''aloe vera riche en acemannane, vitamines et minéraux — hydratant, apaisant le cuir chevelu et anti-inflammatoire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-78e3-be0a-eb1bed4c53ee', '__OWNER_ID__', 'Acide Hyaluronique (Hyaluronic Acid)', 'hyaluronic-acid-hair', 'Biopolymère capable de retenir jusqu''à 1 000× son poids en eau, hydrate la fibre capillaire en profondeur selon son poids moléculaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-79a4-acca-d86df1776bff', '__OWNER_ID__', 'Sodium Hyaluronate', 'sodium-hyaluronate-hair', 'Sel sodique de l''acide hyaluronique, plus stable en formule et mieux pénétrant dans la fibre capillaire que la forme acide.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622e-7d43-a3d9-84d664f2b509', '__OWNER_ID__', 'Acide Linoléique (Oméga-6)', 'linoleic-acid', 'Un acide gras essentiel que le corps ne sait pas produire, crucial pour la fluidité du sébum et la santé de la barrière protectrice.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6243-7b83-8da8-26d2493593a5', '__OWNER_ID__', 'Alpha-arbutine', 'alpha-arbutin', 'Dérivé glycosylé de l''hydroquinone, inhibiteur de la tyrosinase. Anti-taches et éclaircissant progressif, plus doux que l''hydroquinone. Préférer l''alpha sur la bêta, max 2 %.', '## Mécanisme d''action
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7fd0-b817-550dd3bc0a93', '__OWNER_ID__', 'Xylitol', 'xylitol-hair', 'Polyol sucre à cinq carbones, humectant osmotique direct et substrat énergétique cellulaire, composant du complexe Aquaxyl.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7b20-8354-62757aa170f9', '__OWNER_ID__', 'Fructose', 'fructose-hair', 'Monosaccharide naturel hygroscopique, humectant doux d''origine végétale apportant souplesse et brillance à la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6247-728b-813f-01dd33c5c17f', '__OWNER_ID__', 'Niacinamide', 'niacinamide', 'Dérivé amide de la vitamine B3 (nicotinamide). Ingrédient hydrosoluble, ultra-stable, "jack-of-all-trades" avec des centaines d''études. Agit sur la barrière cutanée, l''hyperpigmentation, les rougeurs, le sébum, les pores et les rides. Excellent support qui rend les autres actifs plus performants et tolérables. Sur la liste des médicaments essentiels de l''OMS.', '## Nature et origine
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7bc2-8961-376c35b30f82', '__OWNER_ID__', 'Tréhalose (Trehalose)', 'trehalose-hair', 'Disaccharide osmolyte produit par les organismes résistants à la dessiccation, stabilise les protéines kératiniques et protège la fibre capillaire du stress thermique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-7d42-8793-09204c86d218', '__OWNER_ID__', 'Allantoïne (Allantoin)', 'allantoin-hair', 'Métabolite purique apaisant et kératolytique doux, soulage les irritations du cuir chevelu et favorise le renouvellement cellulaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6240-7b1f-9005-ef8ad58843bf', '__OWNER_ID__', 'Ectoin (Ectoïne)', 'ectoin', 'Extrémolyte naturel puissant produit par des micro-organismes extrémophiles, Ectoin protège les cellules cutanées contre le stress environnemental, renforce la barrière, hydrate en profondeur, apaise les irritations et offre une défense anti-pollution et anti-UV exceptionnelle.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-77d4-be84-d3e15fc3396d', '__OWNER_ID__', 'Beurre de Karité (Butyrospermum Parkii Butter)', 'shea-butter-hair', 'Beurre végétal africain à fraction insaponifiable exceptionnellement élevée (~8–12%), profondément occlusif et anti-inflammatoire, indispensable dans les soins des cheveux secs, crépus ou bouclés.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6238-7aed-a96c-263057fcf5c6', '__OWNER_ID__', 'Acetyl Hexapeptide-8', 'argireline', 'Peptide de pointe surnommé "Botox en flacon", conçu pour détendre les rides d’expression.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-71fd-8f8e-60b59bb49400', '__OWNER_ID__', 'Céramide EOP (Ceramide EOP)', 'ceramide-eop-hair', 'Céramide ester-lié oméga-hydroxy phytosphingosine, lipide ultra-longue chaîne constituant la couche lipidique superficielle de la fibre capillaire, clé de la brillance et de la résistance à l''humidité.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-7097-adfd-2ced5880e523', '__OWNER_ID__', 'Huile d''Argan (Argania Spinosa Kernel Oil)', 'argan-oil-hair', 'Huile précieuse extraite des amandes de l''arganier marocain, riche en acide oléique et en vitamine E, reconnue pour son action réparatrice et anti-oxydante sur la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-71ab-84d9-5faccc50a7ca', '__OWNER_ID__', 'Huile de Coco (Cocos Nucifera Oil)', 'coconut-oil-hair', 'Huile à dominante laurique unique capable de pénétrer profondément dans le cortex capillaire, réduisant la perte de protéines lors du lavage et renforçant la fibre de l''intérieur.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-72e7-9cf0-7af336a6ce07', '__OWNER_ID__', 'Huile de Jojoba (Simmondsia Chinensis Seed Oil)', 'jojoba-oil-hair', 'Cire liquide biomimétique du sébum humain extraite des graines de jojoba, régulatrice du sébum, non comédogène et idéale pour équilibrer cuir chevelu gras et longueurs sèches.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-742d-9080-bb7ede77cd9c', '__OWNER_ID__', 'Huile d''Olive (Olea Europaea Fruit Oil)', 'olive-oil-hair', 'Huile méditerranéenne riche en acide oléique et en squalène, nourrissante en profondeur, elle améliore l''élasticité de la fibre et protège les cheveux secs ou colorés.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-7555-8101-8f3ad2e2ba2a', '__OWNER_ID__', 'Huile d''Avocat (Persea Gratissima Oil)', 'avocado-oil-hair', 'Huile dense extraite de la pulpe d''avocat, riche en acide oléique, vitamines A, D et E, et stérols végétaux — profondément nourrissante pour les cheveux très secs et les cuirs chevelus déshydratés.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6238-7cd5-bbd0-7c3467f729f3', '__OWNER_ID__', 'Copper Tripeptide-1 (GHK-Cu)', 'copper-peptides', 'Peptide cuivré régénérant qui booste collagène, élasticité et cicatrisation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-767b-9d7b-2a505765e255', '__OWNER_ID__', 'Huile de Ricin (Ricinus Communis Seed Oil)', 'castor-oil-hair', 'Huile viscosifiante unique à très haute teneur en acide ricinoléique hydroxylé, forme un film occlusif dense sur la fibre capillaire, stimule la microcirculation du cuir chevelu et épaissit les formules.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-7cef-ae96-645e24324ee3', '__OWNER_ID__', 'Huile de Rose Musquée (Rosa Canina Fruit Oil)', 'rosehip-oil-hair', 'Huile de gratte-cul exceptionnellement riche en acides linoléique et α-linolénique, réparatrice et régénérante pour cuir chevelu sec ou abîmé, avec une action antioxydante notable grâce aux caroténoïdes.', '
INSERT INTO public.ingredients VALUES ('019de0ab-622f-79e8-8527-adde5bbc515f', '__OWNER_ID__', 'Safflower Seed Oil', 'huile-carthame', 'L’huile la plus riche en acide linoléique, idéale pour apaiser les peaux réactives et traiter les rougeurs grâce à ses propriétés vasoconstrictrices.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-7fec-95b1-3b5ec04adfe9', '__OWNER_ID__', 'Soie Hydrolysée (Hydrolyzed Silk)', 'hydrolyzed-silk', 'Fibroïne de soie hydrolysée en petits peptides, confère une brillance exceptionnelle, une texture soyeuse et renforce la résistance à la casse.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-7855-afc0-fb70de1bf493', '__OWNER_ID__', 'Dioxyde de titane (Titanium Dioxide)', 'titanium-dioxide', 'Filtre minéral physique offrant une protection solaire large spectre UVB et UVA courts, opacifiant et apaisant, particulièrement adapté aux peaux sensibles et aux formulations minérales.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-73ef-b755-df33e13da160', '__OWNER_ID__', 'Huile de Ricin Hydrogénée (Hydrogenated Castor Oil)', 'hydrogenated-castor-oil-hair', 'Dérivé solide de l''huile de ricin obtenu par hydrogénation catalytique, utilisé comme épaississant de phase huileuse, agent de structuration des baumes et émulsifiant co-formulaire dans les soins capillaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-7e74-bb5f-5fd6c680cba3', '__OWNER_ID__', 'Kératine Hydrolysée (Hydrolyzed Keratin)', 'hydrolyzed-keratin', 'Protéine structurelle de la fibre capillaire hydrolysée en peptides, comble les zones de porosité et renforce la résistance mécanique du cheveu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625b-7f2d-b8bf-97b8bde8703a', '__OWNER_ID__', 'Protéine de Blé Hydrolysée (Hydrolyzed Wheat Protein)', 'hydrolyzed-wheat-protein', 'Protéine végétale hydrolysée du gluten de blé, riche en glutamine et proline, renforce la fibre capillaire et améliore l''élasticité sans alourdir.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6239-704f-85d1-7aaa234b755a', '__OWNER_ID__', 'Palmitoyl Tripeptide-1', 'palmitoyl-tripeptide-1', 'Peptide messager de haute précision qui ordonne à la peau de produire plus de collagène et de se réparer.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-70d1-b27f-4863223115a1', '__OWNER_ID__', 'Protéine de Soja Hydrolysée (Hydrolyzed Soy Protein)', 'hydrolyzed-soy-protein', 'Protéine végétale hydrolysée du soja, riche en acides aminés essentiels, renforce la fibre capillaire et améliore la rétention de couleur des cheveux colorés.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-71bd-8d79-babf8923fadc', '__OWNER_ID__', 'Collagène Hydrolysé (Hydrolyzed Collagen)', 'hydrolyzed-collagen-hair', 'Protéine de tissu conjonctif hydrolysée en peptides, apporte fermeté à la fibre capillaire, hydratation et renforcement de la cuticule.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-75c1-a49f-abdade75c047', '__OWNER_ID__', 'Acides Aminés de Soie (Silk Amino Acids)', 'silk-amino-acids', 'Acides aminés libres de la fibroïne de soie — sérine, glycine, alanine — pénètrent la fibre capillaire et apportent brillance, douceur et résistance à la casse.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-767c-8fb3-119fea56b69a', '__OWNER_ID__', 'Arginine', 'arginine-hair', 'Acide aminé cationique essentiel de la kératine, améliore l''hydratation de la fibre, renforce la résistance chimique et stimule la microcirculation du cuir chevelu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6239-72f4-8448-01dbd80d1fc2', '__OWNER_ID__', 'Palmitoyl Pentapeptide-4', 'palmitoyl-pentapeptide-4', 'Le célèbre Matrixyl original : un peptide messager qui relance la production de collagène pour une peau visiblement plus ferme et lisse.', '
INSERT INTO public.ingredients VALUES ('019e07d8-cc13-7ae6-b790-23b537759ef9', '__OWNER_ID__', 'Ammonium Polyacryloyldimethyl Taurate', 'ammonium-polyacryloyldimethyl-taurate', 'Synthetic polymer used as a gelling and thickening agent. Provides gel texture without heaviness.', '', 'excipient', '2026-05-08 13:48:29.075371+00', '2026-06-10 12:32:55.65+00', 'skincare', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL, 'Ammonium Polyacryloyldimethyl Taurate');
INSERT INTO public.ingredients VALUES ('019de0ab-625c-796e-975a-ff644303a185', '__OWNER_ID__', 'Proline', 'proline-hair', 'Acide aminé cyclique constitutif de la kératine et du collagène, contribue à l''élasticité et à la flexibilité de la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-79b9-b80f-8ba248f71721', '__OWNER_ID__', 'Oxyde de zinc (Zinc Oxide)', 'zinc-oxyde', 'Filtre minéral physique offrant une protection solaire large spectre UVA/UVB, apaisant et protecteur pour les peaux sensibles, irritées ou à imperfections.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7a09-9973-b6c2a9b9762b', '__OWNER_ID__', 'Thréonine (Threonine)', 'threonine-hair', 'Acide aminé essentiel hydroxylé, hydrate la fibre capillaire de l''intérieur, participe aux liaisons structurelles de la kératine et renforce la cuticule.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7ad2-9156-b2e3bcfb6b82', '__OWNER_ID__', 'Sérine (Serine)', 'serine-hair', 'Acide aminé hydroxylé majeur du NMF cutané et capillaire, puissant humectant naturel qui maintient l''hydratation de la fibre et du cuir chevelu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7b74-b0d0-dedbb4d76c0e', '__OWNER_ID__', 'Glycine', 'glycine-hair', 'Plus petit acide aminé naturel, composant structurel majeur de la kératine et de la soie, pénètre profondément la fibre et stabilise la structure protéique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6247-79a4-bc53-0eebbeb4b2dd', '__OWNER_ID__', 'Acide Salicylique', 'salicylic-acid', 'BHA liposoluble, pénètre les pores pour lutter contre l''acné et les points noirs.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7c2b-888a-3234017ff7d7', '__OWNER_ID__', 'Alanine', 'alanine-hair', 'Acide aminé aliphatique abondant dans la kératine, renforce la structure alpha-hélicoïdale de la fibre et contribue à sa résistance mécanique.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7cd1-ad72-250b3f80d060', '__OWNER_ID__', 'Valine', 'valine-hair', 'Acide aminé essentiel ramifié, composant des feuillets bêta de la kératine, améliore la compacité et la rigidité structurelle de la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7d9e-9303-759feae6ebdb', '__OWNER_ID__', 'Histidine', 'histidine-hair', 'Acide aminé essentiel à cycle imidazole, chélatant naturel des métaux lourds dans la fibre capillaire, protège la kératine contre les dommages oxydatifs.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6232-7360-b04e-5e46fb780ad5', '__OWNER_ID__', 'Céramide AP', 'ceramide-ap', 'Céramide alpha-hydroxylé. Renforce la cohésion de la barrière cutanée.', '# Céramide AP
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7e4f-b153-6ef651449fb2', '__OWNER_ID__', 'Phénylalanine (Phenylalanine)', 'phenylalanine-hair', 'Acide aminé essentiel aromatique, composant des domaines hydrophobes de la kératine, contribue à la compacité structurelle et à la résistance chimique de la fibre.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625c-7f9f-b80b-9ec7c2036d1b', '__OWNER_ID__', 'Céramide NP (Ceramide NP)', 'ceramide-np-hair', 'Céramide non-hydroxy phytosphingosine, constituant majeur du ciment intercellulaire de la cuticule capillaire, restaure la barrière lipidique et réduit la porosité.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7148-8515-680a3a734ae2', '__OWNER_ID__', 'Céramide AP (Ceramide AP)', 'ceramide-ap-hair', 'Céramide alpha-hydroxy phytosphingosine, variant hydroxylé qui renforce la cohésion lamellaire de la cuticule avec une affinité particulière pour les fibres chimiquement traitées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-72f4-bd0f-14efdba4eb1d', '__OWNER_ID__', 'Céramide NS (Ceramide NS)', 'ceramide-ns-hair', 'Céramide non-hydroxy sphingosine, constituant fondamental du ciment intercellulaire cuticulaire, renforce la barrière lipidique et améliore la résistance mécanique de la fibre.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7397-bcfc-0079d1635547', '__OWNER_ID__', 'Céramide AS (Ceramide AS)', 'ceramide-as-hair', 'Céramide alpha-hydroxy sphingosine, variante hydroxylée à base sphingosine offrant un profil complémentaire aux céramides NP et NS pour la restauration complète du ciment intercellulaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7466-b7fb-6705d22ab4f2', '__OWNER_ID__', 'Céramide 2', 'ceramide-2-hair', 'Ancienne nomenclature INCI correspondant au céramide NS, actif lipidique cuticule parmi les plus étudiés pour la réparation des fibres décolorées et chimiquement endommagées.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6249-72da-9784-6012c9f4cb9b', '__OWNER_ID__', 'Drometrizole Trisiloxane (Mexoryl XL)', 'drometrizole-trisiloxane', 'Un système filtrant lipophile breveté, offrant une protection à large spectre contre les UVA et UVB avec une photostabilité exceptionnelle.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-74fb-ad51-36678d39aac5', '__OWNER_ID__', 'Céramide 3', 'ceramide-3-hair', 'Ancienne nomenclature INCI correspondant au céramide NP, le plus représenté dans la cuticule capillaire saine et la référence formulatoire pour les soins lipidiques réparateurs.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7585-b618-0df457dedb94', '__OWNER_ID__', 'Phytosphingosine', 'phytosphingosine-hair', 'Base sphingoïde précurseur des céramides cuticulaires, dotée d''une activité antimicrobienne intrinsèque, apaise le cuir chevelu et participe à la biosynthèse des lipides de barrière.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-765f-822f-8d6531c511ed', '__OWNER_ID__', 'Cholestérol (Cholesterol)', 'cholesterol-hair', 'Lipide stéroïdien indispensable à l''organisation lamellaire du ciment intercellulaire cuticulaire, le cholestérol amplifie l''efficacité des céramides et réduit la porosité de la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-779c-a806-6662e28f0c9b', '__OWNER_ID__', 'Acide Linoléique (Linoleic Acid)', 'linoleic-acid-hair', 'Acide gras oméga-6 essentiel, composant clé du ciment intercellulaire cuticulaire et de la couche lipidique externe (18-MEA), essentiel pour la brillance et la résistance à l''humidité.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624c-75bd-8516-1ec88d841b12', '__OWNER_ID__', 'Allantoïne', 'allantoin', 'Actif apaisant de référence qui calme les irritations, adoucit la peau et accélère la régénération cellulaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7898-94b4-e3e5e2c2b58c', '__OWNER_ID__', 'Acide Oléique (Oleic Acid)', 'oleic-acid-hair', 'Acide gras monoinsaturé oméga-9 pénétrant, lubrifiant et émollient de la fibre capillaire, mais susceptible d''augmenter la porosité des cheveux très poreux si utilisé en excès.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7b91-806e-cd06f179c5ff', '__OWNER_ID__', 'Phospholipides (Phospholipids)', 'phospholipids-hair', 'Lipides membranaires amphiphiles aux propriétés émulsifiantes et restauratrices, ils reconstituent la bicouche lipidique du ciment intercellulaire cuticulaire et améliorent la pénétration des actifs.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7c96-bffa-0075a0bdd989', '__OWNER_ID__', 'Phosphatidylcholine', 'phosphatidylcholine-hair', 'Phospholipide majeur de la membrane cellulaire, principal actif de la lécithine, forme des liposomes vecteurs d''actifs et restaure la bicouche lipidique intercellulaire de la cuticule.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7dce-be0a-589dcd44d9ab', '__OWNER_ID__', 'Carbomer', 'carbomer-hair', 'Polymère acrylique réticulé qui forme des gels clairs à pH neutre-basique, agent épaississant et suspenseur de référence pour les gels coiffants et les shampoings.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7eac-99d2-2e6ba8ee1b78', '__OWNER_ID__', 'Acrylates Copolymer', 'acrylates-copolymer-hair', 'Copolymère acrylique tolèrant les électrolytes, épaississant stable dans les formules à forte concentration en sel ou en tensioactifs — utilisé dans les shampoings et après-shampooings modernes.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-70bc-b22e-28132a5c4470', '__OWNER_ID__', 'Gomme de Cellulose (Cellulose Gum)', 'cellulose-gum-hair', 'Carboxyméthylcellulose sodique dérivée du bois ou du coton, épaississant naturel substantif qui se dépose préférentiellement sur les cheveux abîmés pour un lissage et une protection durables.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-7163-9f31-ebffd3807341', '__OWNER_ID__', 'PEG-120 Methyl Glucose Dioleate', 'peg-120-methyl-glucose-dioleate', 'Épaississant tensioactif non ionique PEGylé du glucose, augmente efficacement la viscosité des shampoings riches en tensioactifs doux sans alourdir la formule.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-70bf-9b2d-25622d27800c', '__OWNER_ID__', 'Niacinamide', 'niacinamide-hair', 'Forme amide de la vitamine B3, améliore la microcirculation du cuir chevelu, renforce la barrière kératinique folliculaire et réduit l''inflammation associée à la miniaturisation pilaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-624f-77ec-b5dc-20e6c843108e', '__OWNER_ID__', 'Petrolatum', 'petrolatum', 'Occlusif de référence (vaseline), le plus efficace pour limiter la perte en eau.', '# Petrolatum (Vaseline)
INSERT INTO public.ingredients VALUES ('019de0ab-625e-722d-87d4-b693329470d0', '__OWNER_ID__', 'Alginate de Sodium (Sodium Alginate)', 'sodium-alginate-hair', 'Polysaccharide anionique extrait d''algues brunes, épaississant et agent filmogène naturel qui forme des gels en présence de calcium, certifiable Cosmos.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-73aa-b6f6-2f7fe6381d87', '__OWNER_ID__', 'Cétéaryl Glucoside (Cetearyl Glucoside)', 'cetearyl-glucoside', 'Émulsifiant et co-émulsifiant non ionique biosourcé, produit par estérification d''alcools gras cétéaryliques et de glucose, utilisé pour former les émulsions O/E des après-shampooings et masques.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-758d-a42f-72c35c0a855e', '__OWNER_ID__', 'Pyrithione de Zinc (Zinc Pyrithione)', 'zinc-pyrithione', 'Antifongique et antibactérien de référence contre Malassezia, réduit les squames et les démangeaisons du cuir chevelu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-766c-82e8-51dc8743e5db', '__OWNER_ID__', 'Sulfure de Sélénium (Selenium Sulfide)', 'selenium-sulfide', 'Actif antipelliculaire puissant à double mécanisme antifongique et cytostatique, réservé aux traitements médicamenteux OTC en raison de son profil réglementaire strict.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-7714-8e2c-5db947eee342', '__OWNER_ID__', 'Acide Salicylique (Salicylic Acid)', 'salicylic-acid-hair', 'Bêta-hydroxy acide kératolytique qui exfolie le cuir chevelu en dissolisant le ciment intercornéocytaire, libère les squames et améliore la pénétration des autres actifs antipelliculaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-79d3-b977-525796ddcf9e', '__OWNER_ID__', 'Climbazole', 'climbazole', 'Antifongique azolé très ciblé sur Malassezia, efficace à faible concentration et compatible avec les formules de rinçage comme les leave-ins antipelliculaires.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6230-71a2-8ed7-17ad0b9da7f2', '__OWNER_ID__', 'Prunus Amygdalus Dulcis Oil (Huile d''Amande Douce)', 'prunus-amygdalus-dulcis-oil', 'Huile onctueuse et apaisante, idéale pour nourrir les peaux fragiles et prévenir les vergetures.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6259-74b3-ba41-dc5ffe837de1', '__OWNER_ID__', 'Butylène Glycol (Butylene Glycol)', 'butylene-glycol-hair', 'Humectant diol doux C4, pénètre la fibre capillaire avec moins de risque irritant que le propylène glycol.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625a-78fa-88e4-2488bf2c8a41', '__OWNER_ID__', 'Huile de Tournesol (Helianthus Annuus Seed Oil)', 'sunflower-oil-hair', 'Huile légère à haute teneur en acide linoléique, vecteur d''actifs et emollient non occlusif, idéale comme huile de base en formulation capillaire pour son excellente biodisponibilité et sa légèreté sensorielle.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7a98-b18e-71dc33804f13', '__OWNER_ID__', 'Squalane', 'squalane-hair', 'Hydrocarbure lipidique léger biomimétique, émollient non occlusif qui pénètre la fibre sans la surcharger, apporte brillance et souplesse en reproduisant les lipides sébacés naturels.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625d-7f8a-9215-6ccd184c1a86', '__OWNER_ID__', 'Gomme de Xanthane (Xanthan Gum)', 'xanthan-gum-hair', 'Polysaccharide fermenté par Xanthomonas campestris, épaississant et stabilisant naturel rhéofluidifiant, compatible formules Cosmos et soins capillaires naturels.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625e-7a90-aabc-fb9486b6b954', '__OWNER_ID__', 'Huile d''Arbre à Thé (Tea Tree Oil)', 'tea-tree-oil-hair', 'Huile essentielle à large spectre antimicrobien extraite de Melaleuca alternifolia, reconnue pour ses propriétés antifongiques, antibactériennes et anti-inflammatoires sur le cuir chevelu.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-7a84-b055-119efac9915e', '__OWNER_ID__', 'Acide Phytique (Phytic Acid)', 'phytic-acid-hair', 'Hexaphosphate d''inositol d''origine végétale, chélateur biodégradable puissant des métaux lourds accumulés dans la fibre capillaire, compatible formules naturelles et Cosmos.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-7819-9daf-de28efd66ea3', '__OWNER_ID__', 'Tocophérol (Tocopherol / Vitamine E)', 'tocopherol-hair', 'Antioxydant liposoluble majeur, protège les lipides de la cuticule contre la peroxydation et nourrit le cuir chevelu en profondeur.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-71b5-b206-c34e88e0bba7', '__OWNER_ID__', 'Biotine (Biotin / Vitamine H)', 'biotin-hair', 'Coenzyme carboxylase essentielle au métabolisme des acides aminés et des acides gras constituant la kératine, active principalement en cas de carence avérée.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-799d-b39a-0273fd9b080e', '__OWNER_ID__', 'Disodium EDTA', 'disodium-edta-hair', 'Chélateur synthétique disel de l''EDTA, séquestre les ions calcaire et métaux lourds qui déstabilisent les formules et ternissent la fibre capillaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-7b8a-9be8-30cbb34f4676', '__OWNER_ID__', 'Gluconate de Sodium (Sodium Gluconate)', 'sodium-gluconate-hair', 'Sel sodique de l''acide gluconique, chélateur biodégradable d''origine naturelle, alternatif vert à l''EDTA pour la stabilisation des formules et la séquestration des ions calcaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-7db3-9018-08609bd161c2', '__OWNER_ID__', 'Glycol Distéarate (Glycol Distearate)', 'glycol-distearate', 'Diester du glycol et de l''acide stéarique, agent nacrant et opacifiant de référence qui cristallise dans la phase aqueuse pour créer l''aspect perlé des shampoings et après-shampooings.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-7ed9-a3be-219f5fd4de49', '__OWNER_ID__', 'Mica', 'mica-hair', 'Silicate d''aluminium et de potassium sous forme de fines plaquettes réfléchissantes, agent nacrant et scintillant d''origine minérale utilisé dans les soins capillaires et produits coiffants.', '
INSERT INTO public.ingredients VALUES ('019de0ab-625f-7fcd-9dc4-1ea9bc3ad749', '__OWNER_ID__', 'Dioxyde de Titane (Titanium Dioxide)', 'titanium-dioxide-hair', 'Oxyde minéral blanc d''origine naturelle ou synthétique, agent opacifiant puissant qui confère blancheur et opacité aux shampoings et soins capillaires, avec un secondaire effet protecteur UV.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-70e6-9165-562899d2b757', '__OWNER_ID__', 'Huile de Paraffine (Paraffinum Liquidum)', 'paraffinum-liquidum-hair', 'Huile minérale pétrolière légère, occlusif efficace qui scelle le film hydrique de la fibre capillaire et réduit la friction pour le démêlage — incontournable des formules afro et curl.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-7241-aa01-02dbffa4f6a8', '__OWNER_ID__', 'Vaseline (Petrolatum)', 'petrolatum-hair', 'Mélange semi-solide d''hydrocarbures pétroliers, occlusif ultime pour sceller l''humidité des pointes et des longueurs, base de nombreuses graisses capillaires afro et produits de styling.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-73e0-95ec-8beb537a4b3c', '__OWNER_ID__', 'Huile Minérale (Mineral Oil)', 'mineral-oil-hair', 'Mélange d''hydrocarbures pétroliers liquides de viscosité variable, émollient et occlusif de grande pureté utilisé comme phase huileuse dans les émulsions capillaires et les produits de glissant.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-76e8-91fd-2c9b6b9a0b77', '__OWNER_ID__', 'Cire Microcristalline (Cera Microcristallina)', 'cera-microcristallina-hair', 'Cire pétrolière à microcristaux très fins, plus flexible et plus lisse que les paraffines classiques, agent structurant premium pour les cires de coiffage, pomades et produits de fixation.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-7926-9d0e-3f6001d716d2', '__OWNER_ID__', 'Rétinyl Palmitate (Retinyl Palmitate / Vitamine A)', 'retinyl-palmitate-hair', 'Ester stable de la vitamine A, stimule le renouvellement cellulaire du cuir chevelu et renforce la gaine du follicule pileux.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-7b1d-aa93-767a9468fc60', '__OWNER_ID__', 'Extrait de Romarin (Rosmarinus Officinalis Extract)', 'romarin-extract-hair', 'Extrait botanique riche en acide rosmarinique et en diterpènes, stimule la microcirculation du cuir chevelu et protège la fibre du stress oxydatif.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-7c67-a5dd-ce03fe9cd837', '__OWNER_ID__', 'Kaolin (Argile Blanche)', 'kaolin-hair', 'Argile minérale douce à forte capacité d''adsorption, purifie le cuir chevelu en absorbant sébum et impuretés sans altérer la fibre.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6260-7ee1-aa81-424e9f124a5d', '__OWNER_ID__', 'Sel Marin (Sea Salt / Sodium Chloride)', 'sea-salt-hair', 'Chlorure de sodium d''origine marine, ajuste la viscosité des shampoings et des gels, exfolie le cuir chevelu et apporte du volume à la fibre.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6261-74c5-8d61-ab8003f009e2', '__OWNER_ID__', 'Hydroxypropyl Cyclodextrine (Hydroxypropyl Cyclodextrin)', 'hydroxypropyl-cyclodextrin', 'Oligosaccharide cyclique modifié capable d''encapsuler des molécules lipophiles, améliore la solubilité et la délivrance des actifs dans la fibre et élimine les odeurs par inclusion moléculaire.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6261-7867-8f9d-ebe890e368ea', '__OWNER_ID__', 'Extrait d''Açaï (Euterpe Oleracea Fruit Extract)', 'euterpe-oleracea-extract', 'Extrait de baie d''açaï amazonienne à très haute densité antioxydante (ORAC parmi les plus élevés), protège la kératine et les pigments de la fibre contre la dégradation oxydative.', '
INSERT INTO public.ingredients VALUES ('019de0ab-6261-795c-8d0f-91af9d0c2fb7', '__OWNER_ID__', 'Extrait de Grenade (Punica Granatum Extract)', 'punica-granatum-extract', 'Extrait polyphénolique de grenade issu des graines et de l''écorce, puissant antioxydant et stimulant de la kératinisation folliculaire grâce à ses ellagitanins.', '
