INSERT INTO public.products VALUES ('019e0384-44ac-7065-bf46-6119fea6082c', '__OWNER_ID__', 'Blackberry Complex Glow Wash Off Pack', 'Mary&May', 'mask', 'jar', 'Purified Water, Kaolin, Glycerin, Bentonite, 1,2-Hexanediol, Dipropylene Glycol, Western Raspberry Extract, Laminaria Digitata Extract, Nasturtium Leaf Extract, Camellia Sinensis Leaf Extract, Hydrogenated Lecithin, Butylene Glycol, Xanthan Gum, Sweet Almond Shell Powder, Allantoin, Fructooligosaccharides, Manicouagan Clay, Beta-Glucan, Canadian Colloidal Clay, Tocopherol, Saccharomyces Ferment Filtrate, Illite, Hydrolyzed Hyaluronic Acid, Montmorillonite, Parfum, Ethylhexylglycerin, CI 77499, CI 77491', 'Obtiens des résultats dignes d''un institut de beauté chez toi grâce au Blackberry Complex Glow Wash Off Pack MARY & MAY, un masque à l''argile de première qualité conçu pour purifier et éclaircir ta peau. Ce luxueux masque à rincer combine des argiles kaolin et bentonite riches en minéraux avec des ingrédients naturels comme l''extrait de mûre, riche en puissants antioxydants, pour détoxifier et nettoyer les pores en profondeur. Sa texture douce et crémeuse s''étale facilement sur la peau, absorbant l''excès de sébum et les impuretés tout en apportant de l''hydratation et des nutriments pour un teint lisse et éclatant. Parfait pour tous les types de peaux, ce masque laisse une sensation de fraîcheur, d''hydratation et d''éclat à ta peau après chaque utilisation. Recommandé pour : Sans risque pour l''acné fongique, peaux sensibles et sèches, tous types de peaux.', 125, 'g', 'mary-may-blackberry-complex-glow-wash-off-pack', 'https://korean-skincare.fr/products/mary-may-blackberry-complex-glow-wash-off-pack', 'https://aurore-cdn.b-cdn.net/products/mary-may-blackberry-complex-glow-wash-off-pack.webp', 'Après t''être lavé le visage, étale le masque délicatement et uniformément, en évitant le contour des yeux et de la bouche. Masse délicatement en fonction de l''état de ta peau. Après 10 à 15 minutes, lorsque le masque a séché, rince-le délicatement à l''eau tiède. Prélève une quantité suffisante de masque et applique-le en couche épaisse pour que l''hydratation et les principes actifs du masque à l''argile puissent être efficacement absorbés.', 2539, '2026-05-07 17:37:40.52384+00', '2026-05-12 22:55:39.356731+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
