INSERT INTO public.products VALUES ('019de0ab-64e1-7bd4-b535-ae4bb0eaa9b4', '__OWNER_ID__', 'Forever Eye Mask', 'Dieux', 'patch', 'pack', 'NONPOROUS SILICONE', 'Des patchs en silicone réutilisables à l"infini pour maximiser l''absorption de vos soins contour des yeux.', 0, 'ct', 'forever-eye-mask', 'https://www.skinsafeproducts.com/dieux-skin-forever-eye-mask', 'https://cdn1.skinsafeproducts.com/photo/32D51E60FA5D02/large_1697912048.png', 'Composé de silicone non poreux, convient à tous les types de peaux pour un usage durable.', 0, '2026-04-30 23:13:40.719796+00', '2026-04-30 23:13:40.719796+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-653f-7af4-ba7a-382ea977f72a', '__OWNER_ID__', 'Spot Cover Patch', 'SKIN1004', 'patch', 'pack', 'HYDROCOLLOID', 'Patchs hydrocolloïdes couvrants pour imperfections : protègent, absorbent et camouflent.', 22, 'patchs', 'skin1004-spot-cover-patch', 'https://www.skin1004.com', 'https://aurore-cdn.b-cdn.net/products/skin1004-spot-cover-patch.webp', 'Invisibles sous maquillage, usage quotidien.', 266, '2026-04-30 23:13:40.719796+00', '2026-04-30 23:13:40.719796+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64f2-7eb6-a3fb-fce5d54e6888', '__OWNER_ID__', 'REMEDY for pimples — patches 36ct', 'Remedy Science', 'patch', 'pack', 'Hydrocolloid', 'Near-invisible hydrocolloid pimple patches that absorb fluid from blemishes while protecting skin to expedite healing, prevent picking, and promote clearer-looking skin.', 36, 'g', 'remedy-pimple-patches', 'https://remedyskin.com/products/remedy-for-pimples-patches-36ct', 'https://aurore-cdn.b-cdn.net/products/remedy-pimple-patches.webp', 'Hero: Hydrocolloid (gel-forming agents). Produit pour boutons actifs et suintants.', 1095, '2026-04-30 23:13:40.719796+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c0b-7f7e-bc34-dbc8feb3db35', '__OWNER_ID__', 'Clear Fit Master Patch', 'COSRX', 'patch', 'pack', 'Cellulose Gum, Styrene Isoprene Styrene Block Copolymer, Polyisobutene, Petroleum Resin, Polyurethane Film, Liquid Paraffin, Tetrakis Methane', 'Le Clear Fit Master Patch COSRX est un patch hydrocolloïde fin et transparent contre l''acné et les boutons. Il élimine efficacement les impuretés tout en créant une barrière protectrice contre les facteurs d''irritation externes. Ce patch ultrafin te donnera un aspect naturel en couvrant tes imperfections pendant la journée. Semblable à la texture d''un masque tissu hydrogel, il adhère parfaitement à la peau, isole l''acné pour la protéger des bactéries et des saletés (qui en sont la cause) et maintient l''hydratation à l''intérieur. Recommandé pour : Peaux grasses, à tendance acnéique. Peut être utilisé pour : Tous types de peaux.', 18, 'pcs', 'cosrx-clear-fit-master-patch', 'https://korean-skincare.fr/products/cosrx-clear-fit-master-patch', 'https://aurore-cdn.b-cdn.net/products/cosrx-clear-fit-master-patch.webp', 'Lave-toi soigneusement le visage avec un nettoyant. Colle le Clear Fit Master Patch COSRX sur ta peau sèche avant de procéder à ta routine beauté. Au bout de 8 à 10 heures, le Clear Fit Master Patch COSRX deviendra blanc après avoir absorbé le pus et les impuretés. Lorsqu''il devient blanc, enlève-le délicatement. Remplace-le ensuite par un nouveau.', 475, '2026-05-07 17:37:38.315899+00', '2026-05-11 15:40:35.458594+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44d2-7b54-b306-400612c2471a', '__OWNER_ID__', 'Clear Spot Patch', 'SOME BY MI', 'patch', 'pack', NULL, 'Les Clear Spot Patch SOME BY MI sont des patchs hydrocolloïdes imperméables et respirants qui atténuent les boutons en absorbant le pus et en protégeant les plaies contre les infections bactériennes. Ces patchs contre les boutons conviennent à un usage de jour car ils se fondent parfaitement dans la peau et sous le maquillage. Disponible en 10 mm et 12 mm pour convenir aux petites et grandes imperfections. Recommandé pour : Peaux grasses, à tendance acnéique. Peut être utilisé pour : Tous types de peaux.', 18, 'pcs', 'some-by-mi-clear-spot-patch', 'https://korean-skincare.fr/products/some-by-mi-clear-spot-patch', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-clear-spot-patch.webp', 'Assure-toi que la zone à traiter est propre et sèche. Décolle un patch de la feuille et applique-le directement sur le bouton ou l''imperfection ciblé. Laisse le patch en place pendant plusieurs heures ou toute la nuit pour lui permettre d''absorber les impuretés et de favoriser la guérison.', 375, '2026-05-07 17:37:40.562608+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
