INSERT INTO public.products VALUES ('019e0384-4677-79a8-be36-60ef5bd5847e', '__OWNER_ID__', 'Theracne 365 Niacinamide 5% Blemish Body Mist', 'AESTURA', 'mist', 'spray', 'Purified Water, Butylene Glycol, Niacinamide 5%, Glycerin, 1,2-Hexanediol, Lactobacillus Fermentation Extract, Tromethamine, Salicylic Acid, Propanediol, Allantoin, Gluconolactone, Lactic Acid, Ethylhexylglycerin, Polyglyceryl-10 Laurate, Citric Acid, Glycolic Acid, Madecassoside, Phytosphingosine, Zinc Chloride', 'La Theracne 365 Niacinamide 5% Blemish Body Mist AESTURA est un traitement corporel ciblé conçu pour réduire les imperfections, contrôler l’excès de sébum et améliorer le teint irrégulier du dos, de la poitrine et d’autres zones sujettes aux éruptions. Formulé avec 5 % de niacinamide, ce spray léger aide à éclaircir les marques post-acné tout en équilibrant la production de sébum pour prévenir les futures imperfections. Enrichi en ingrédients apaisants et renforçant la barrière cutanée, ce spray corporel non collant calme les rougeurs et maintient la peau confortablement hydratée sans obstruer les pores. Avec une utilisation régulière, la Theracne 365 Niacinamide 5% Blemish Body Mist AESTURA contribue à obtenir une peau du corps plus nette, lisse et d’apparence plus uniforme. Recommandé pour : Acné corporelle, marques post-acné.', 200, 'ml', 'aestura-theracne-365-niacinamide-5-blemish-body-mist', 'https://korean-skincare.fr/products/aestura-theracne-365-niacinamide-5-blemish-body-mist', 'https://aurore-cdn.b-cdn.net/products/aestura-theracne-365-niacinamide-5-blemish-body-mist.webp', 'Vaporise uniformément sur peau propre et sèche des zones corporelles concernées. Laisse pénétrer complètement avant de t’habiller. Utilise quotidiennement, matin et soir.', 2795, '2026-05-07 17:37:40.983444+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
