INSERT INTO public.products VALUES ('019e0384-424e-7153-a88d-1f92133b8b9d', '__OWNER_ID__', '1/3 Cotton Pad', 'Pyunkang Yul', 'exfoliant', 'pack', NULL, 'Les Cotton Pads 1/3 Pyunkang Yul sont indispensables pour faire durer tes toniques et tes essences plus longtemps. Grâce à ces cotons, tu n''auras besoin que d''un tiers de la quantité de produit liquide que tu utiliserais normalement. Doux et souples, ces cotons sont conçus pour faire pénétrer les toniques ou les essences dans la peau avec plus d''efficacité que les disques de coton traditionnels. Ils fonctionnent en absorbant le produit liquide, puis en le libérant lorsqu''ils sont appliqués contre la peau.', 160, 'pcs', 'pyunkang-yul-1-3-cotton-pad', 'https://korean-skincare.fr/products/pyunkang-yul-1-3-cotton-pad', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-1-3-cotton-pad.webp', NULL, 449, '2026-05-07 17:37:39.917993+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
