INSERT INTO public.products VALUES ('019e0384-42b6-7169-8b6d-8d9a769b35a5', '__OWNER_ID__', 'Basic Line Gift Set', 'Pyunkang Yul', 'moisturizer', 'jar', NULL, 'Ce coffret de soins élégant comprend certains des produits best-sellers de Pyunkang Yul, notamment l''Essence Toner, le Moisture Serum, et la Nutrition Cream, tous en format standard. L''Essence Toner possède une formule hydratante avec des acides aminés infusés et de l''extrait de racine d''astragale pour affiner la texture de la peau. Le Moisture Serum utilise des huiles nourrissantes et de la glycérine pour aider la peau à retenir l''hydratation en renforçant son ratio huile/eau. La Nutrition Cream est infusée d''extrait d''asclépiade de Mongolie, de beurre de karité et de cire d''abeille pour nourrir la peau. Essence Toner (200ml) Moisture Serum (100ml) Nutrition Cream (100ml)', NULL, NULL, 'pyunkang-yul-basic-line-gift-set', 'https://korean-skincare.fr/products/pyunkang-yul-basic-line-gift-set', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-basic-line-gift-set.webp', NULL, 4698, '2026-05-07 17:37:40.021893+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
