INSERT INTO public.products VALUES ('019de0ab-64f4-7c38-869b-4412c1ef28a0', '__OWNER_ID__', 'Propolis Light Cream', 'COSRX', 'moisturizer', 'jar', '1,2-Hexanediol, Allantoin, ARGININE, Cera Alba, Butylene Glycol, Caprylic/Capric Triglyceride, Carbomer, CASSIA OBTUSIFOLIA SEED EXTRACT, Cetearyl Alcohol, CETEARYL OLIVATE, Glycerin, Helianthus Annuus Seed Oil, HONEY EXTRACT, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, PROPOLIS EXTRACT, ROYAL JELLY EXTRACT, Sorbitan Olivate, XANTHAN GUM', 'Crème légère au propolis, miel et royal jelly extract pour nourrir et protéger sans lourdeur.', 65, 'ml', 'cosrx-propolis-light-cream', 'https://www.skinsafeproducts.com/cosrx-propolis-light-cream-2-19-fl-oz-65-ml', 'https://aurore-cdn.b-cdn.net/products/cosrx-propolis-light-cream.webp', 'Malgré le nom ''light'', relativement nourrissante. Idéale peaux normales à sèches.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:06.875+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-429a-793d-879e-52f3fd8e8f20', '__OWNER_ID__', 'Moisture Serum', 'Pyunkang Yul', 'serum', 'dropper', 'Astragalus Membranaceus Root Extract, Butylene Glycol, Olea Europaea Fruit Oil, Caprylic/Capric Trigtyceride, 1,2-Hexanediol, Stearic Acid, Polysorbate 60, Cetearyl Alcohol, Glyceryl Stearate, Sorbitan Sesquioleate, Glyceryl Caprylate, Hydroxyethylcellulose, Carbomer, Arginine, Dimethicone', 'Ce sérum est formulé pour aider la peau à retrouver son ratio optimal d''hydratation et d''huile, pour un teint sain et équilibré. Son secret réside dans une combinaison optimale de ses ingrédients phares, notamment l''extrait de racine de coptis japonica et l''huile d''olive. Le Moisture Serum Pyunkang Yul calme et rafraîchit tout en hydratant en profondeur les peaux irritées, sensibles, grasses mais aussi déshydratées. Sa texture légère, semblable à celle d''une lotion, s''étale facilement et s''absorbe rapidement. Recommandé pour : Peau sèche, tous types de peau.', 100, 'ml', 'pyunkang-yul-moisture-serum', 'https://korean-skincare.fr/products/pyunkang-yul-moisture-serum', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-moisture-serum.webp', 'Prélève une quantité adéquate de produit à l''aide du compte-gouttes. Masse délicatement ta peau en suivant son grain. Renouvelle l''application sur le contour des yeux secs.', 2312, '2026-05-07 17:37:39.994413+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
