INSERT INTO public.products VALUES ('019e0384-434a-7f16-b97d-fe53b99bdd3a', '__OWNER_ID__', 'Silicon Mask Brush', 'I''m From', 'mask', 'pack', NULL, 'La Silicon Mask Brush I''m From est un outil parfait à combiner avec n''importe quel masque à rincer. La surface douce mais large de cette brosse peut contenir une grande quantité de produit et aider à l''étaler uniformément sur ton visage. Elle peut également être utilisée pour retirer le masque une fois l''application terminée. Il suffit de pousser la brosse contre ton visage en l''inclinant et de la laisser faire le travail.', 1, 'pcs', 'im-from-silicon-mask-brush', 'https://korean-skincare.fr/products/im-from-silicon-mask-brush', 'https://aurore-cdn.b-cdn.net/products/im-from-silicon-mask-brush.webp', NULL, 595, '2026-05-07 17:37:40.170786+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
