INSERT INTO public.products VALUES ('019de0ab-64d8-7a98-9b35-e56e1118e69b', '__OWNER_ID__', 'Biology AC GEL Moussant Purifiant BIO', 'A-Derma', 'cleanser', 'bottle', 'Aqua, DISODIUM COCO-GLUCOSIDE CITRATE, Decyl Glucoside, Glycerin, Pentylene Glycol, SODIUM COCOAMPHOACETATE, GARCINIA MANGOSTANA PEEL EXTRACT, AVENA SATIVA (OAT) FLOWER/LEAF/STEM JUICE (AVENA SATIVA FLOWER/LEAF/STEM JUICE)*, TARAXACUM OFFICINALE (DANDELION) RHIZOME/ROOT EXTRACT (TARAXACUM OFFICINALE RHIZOME/ROOT EXTRACT), Aloe Barbadensis Leaf Juice, Citric Acid, Parfum, Maltodextrin, Polyglyceryl-4 Caprate, POLYGLYCERYL-6 CAPRYLATE, Sodium Chloride, XANTHAN GUM', '', 200, 'ml', 'aderma-biology-ac-gel-moussant-purifiant-bio', 'https://www.pharmashopdiscount.com/fr/beaute/aderma/aderma-biology-ac-gel-moussant-purifiant-bio-200ml.html', 'https://aurore-cdn.b-cdn.net/products/aderma-biology-ac-gel-moussant-purifiant-bio.webp', '', 923, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:06.881+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4570-72a0-90ce-d65a2e31d8c0', '__OWNER_ID__', 'PDRN Hyaluronic Acid Capsule 100 Serum', 'Anua', 'serum', 'dropper', 'Aqua, Butylene Glycol, Propanediol, Glycerin, Hydrolyzed Hyaluronic Acid, 1,2-Hexanediol, Niacinamide, Glyceryl Oleate, Lauryl Glucoside, Myristyl Glucoside, Polyglyceryl-6 Laurate, Hydrogenated Lecithin, Hydrolyzed Collagen, Sodium Hyaluronate, Coptis Japonica Root Extract, Adenosine, Melia Azadirachta Leaf Extract, Melia Azadirachta Flower Extract, Coccinia Indica Fruit Extract, Glutathione, Sodium Dna, Solanum Melongena Fruit Extract, Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Potassium Hyaluronate, Sodium Hyaluronate Crosspolymer, Ocimum Sanctum Leaf Extract, Citric Acid, Curcuma Longa Root Extract, Corallina Officinalis Extract, Sodium Citrate, Pentylene Glycol, Sodium Acetylated Hyaluronate', 'Le sérum Anua PDRN Hyaluronic Acid Capsule 100 est un sérum facial apaisant et profondément hydratant conçu pour calmer les peaux sensibles, retenir l''humidité et améliorer la santé générale de la peau. Grâce au PDRN (ADN de saumon), à l''acide hyaluronique multicouche à 3 % et au collagène de faible poids moléculaire, cette formule avancée améliore la texture, l''élasticité et l''éclat naturel de la peau. Grâce à la technologie exclusive des capsules intelligentes à faible poids moléculaire d''ANUA, 100 % de ses principaux ingrédients actifs pénètrent profondément dans la peau pour une efficacité maximale. La texture aqueuse et légère de la goutte de sérum permet une absorption rapide sans laisser de résidu collant. La formule couleur émeraude, sans parfum et non comédogène, peut être utilisée comme sérum hydratant quotidien, superposée comme masque de nuit ou mélangée à un fond de teint pour un fini rosé et éclatant. Parfait pour celles qui cherchent à lutter contre le vieillissement, à stimuler l''hydratation de la peau et à obtenir un teint lisse et rafraîchi. Recommandé pour : Tous les types de peau.', 30, 'ml', 'anua-pdrn-hyaluronic-acid-capsule-100-serum', 'https://korean-skincare.fr/products/anua-pdrn-hyaluronic-acid-capsule-100-serum', 'https://aurore-cdn.b-cdn.net/products/anua-pdrn-hyaluronic-acid-capsule-100-serum.webp', 'Après avoir utilisé un tonique, applique une quantité appropriée de sérum sur ta peau. Tapote délicatement ta peau pour faciliter la pénétration du sérum. Lorsque le sérum est utilisé pendant la journée, assurez-toi de le faire suivre d''un écran solaire FPS 30 ou plus.', 1976, '2026-05-07 17:37:40.720004+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6565-721a-b8c9-d1963a2473dc', '__OWNER_ID__', 'La Rosée Mon Petit La Rosée Dentifrice à la Fraise Bio 50ml', 'La Rosée', 'toothpaste', 'tube', 'Sorbitol, Aqua, hydrated silicia, Glycerin, perlite, xanthan gum, fragaria vesca (strawberry) fruit extract, hydrolyzed gardenia florida extract, Sodium Fluoride, arome (flavor), stevia rebaudiana extract, Sodium Chloride, Sodium Benzoate, Citric Acid, Disodium Cocoyl Glutamate, Maltodextrin, Potassium Sorbate, Sodium Hydroxide', '', 0, '', 'la-rosee-mon-petit-la-rosee-dentifrice-a-la-fraise-bio-50ml-235184', 'https://www.atida.fr/la-rosee-mon-petit-la-rosee-dentifrice-a-la-fraise-bio-50ml.html', 'https://aurore-cdn.b-cdn.net/products/la-rosee-mon-petit-la-rosee-dentifrice-a-la-fraise-bio-50ml-235184.webp', '', 463, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:06.885+00', 'dental', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-446e-7d4d-b0ee-5ffbc1ad7cb3', '__OWNER_ID__', '6 Peptide Complex Serum', 'Mary&May', 'serum', 'dropper', 'Purified Water, Glycereth-26, 1,2-Hexanediol, Butylene Glycol, Glycerin, Arginine, Carbomer, Ethylhexylglycerin, Polyglyceryl-10 Laurate, Adenosine, Caprylyl Glycol, Copper Tripeptide-1, Hexapeptide-11, Hexapeptide-9, Palmitoyl Pentapeptide-4, Palmitoyl Tripeptide-1, Tripeptide-1, Tocopherol', 'Le 6 Peptide Complex Serum Mary&May est un soin raffermissant et anti-âge conçu pour améliorer l’élasticité de la peau, lisser les fines lignes et soutenir le renouvellement cutané global. Formulé avec un mélange de six types de peptides, ce sérum léger aide à stimuler la production de collagène tout en renforçant la barrière cutanée. Sa texture rapidement absorbée et non collante apporte un soin ciblé sans lourdeur, ce qui le rend idéal pour un usage quotidien. Avec une utilisation continue, le 6 Peptide Complex Serum Mary&May aide à améliorer la fermeté de la peau, affiner la texture et renforcer un aspect jeune et lifté. Il laisse la peau plus lisse, plus résistante et visiblement revitalisée. Recommandé pour : Perte d’élasticité, ridules, peaux ternes, et routines anti-âge.', 30, 'ml', 'mary-may-6-peptide-complex-serum', 'https://korean-skincare.fr/products/mary-may-6-peptide-complex-serum', 'https://aurore-cdn.b-cdn.net/products/mary-may-6-peptide-complex-serum.webp', 'Prélève une quantité suffisante de produit à l''aide du compte-gouttes. Fais pénétrer le produit en massant délicatement ta peau en suivant son grain. Applique à nouveau sur le contour des yeux secs.', 1660, '2026-05-07 17:37:40.462719+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-447b-7184-8642-4d617208a7b0', '__OWNER_ID__', 'Hyaluronics Serum', 'Mary&May', 'serum', 'dropper', 'Purified Water, Butylene Glycol, 1,2-Hexanediol, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Sodium Hyaluronate, Hydrolyzed Sodium Hyaluronate, Ethylhexylglycerin, Pentylene Glycol', 'Le Hyaluronics Serum Mary&May est un sérum formulé avec une petite structure moléculaire d’acide hyaluronique qui pénètre la peau entre les cellules et hydrate de l’intérieur. Formulé avec un mélange d’acides hyaluroniques multi-moléculaires, ce sérum léger pénètre différentes couches de la peau pour offrir une hydratation immédiate et longue durée. Sa texture rapidement absorbée et non collante le rend parfait pour être superposé dans n’importe quelle routine de soins. Conçu pour rétablir l’équilibre hydrique et renforcer la barrière cutanée, le Hyaluronics Serum Mary&May aide à lisser les fines lignes de déshydratation et à améliorer la texture générale de la peau. Avec une utilisation régulière, il laisse la peau douce, souple et visiblement rafraîchie. Recommandé pour : Peaux déshydratées, tiraillements, fines lignes de déshydratation, boost quotidien d’hydratation.', 80, 'ml', 'mary-may-multi-hyaluronics-serum', 'https://korean-skincare.fr/products/mary-may-multi-hyaluronics-serum', 'https://aurore-cdn.b-cdn.net/products/mary-may-multi-hyaluronics-serum.webp', 'Prélève une quantité adéquate de produit à l''aide du compte-gouttes. Masse délicatement ta peau en suivant son grain. Renouvelle l''application sur le contour des yeux secs.', 1445, '2026-05-07 17:37:40.47503+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
