INSERT INTO public.products VALUES ('019e0384-44f9-7930-a89b-192b6943acc0', '__OWNER_ID__', 'Yuja Niacin Anti Blemish Starter Kit', 'SOME BY MI', 'moisturizer', 'jar', 'Yuja Niacin Brightening All-In-One Cleanser (30ml) : Yuja Niacin Brightening Toner (30ml) : Yuja Niacin Anti Blemish Serum (10ml) : Yuja Niacin Anit Blemish Cream (20g) :', 'Le Yuja Niacin Anti Blemish Starter Kit SOME BY MI est composé de quatre versions en petit format des produits best-sellers de SOME BY MI. Comprend : Yuja Niacin Brightening All-In-One Cleanser (30ml) Yuja Niacin Brightening Toner (30ml) Yuja Niacin Anti Blemish Serum (10ml) Yuja Niacin Anit Blemish Cream (20g) Recommandé pour :', NULL, NULL, 'some-by-mi-yuja-niacin-anti-blemish-starter-kit', 'https://korean-skincare.fr/products/some-by-mi-yuja-niacin-anti-blemish-starter-kit', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-yuja-niacin-anti-blemish-starter-kit.webp', 'Étape 1 : Yuja Niacin Brightening All-In-One Cleanser Étape 2 : Yuja Niacin Brightening Toner Étape 3 : Yuja Niacin Anti Blemish Serum Étape 4 : Yuja Niacin Anit Blemish Cream', 1995, '2026-05-07 17:37:40.601452+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
