INSERT INTO public.products VALUES ('019e0384-45fc-76c0-b02d-1bd3526e3e8f', '__OWNER_ID__', 'Age-R Booster Pro', 'Medicube', 'moisturizer', 'jar', NULL, 'Donne un coup de boost à ta routine beauté avec l''Age-R Booster Pro Medicube, un appareil de beauté high-tech 6 en 1 conçu pour t''aider à retrouver une peau lisse, radieuse et éclatante de santé, le tout dans le confort de ta maison. Combinant des technologies avancées (électroporation, microcourant, EMS, aiguilles électriques, thérapie LED et vibrations soniques), cet appareil de niveau professionnel améliore l''absorption des produits, booste l''éclat de la peau, favorise son élasticité, soigne les pores et redessine les contours du visage. Avec quatre modes faciles à utiliser et ne nécessitant aucun gel conducteur, il s''utilise en toute simplicité avec tes produits de soin habituels. Équipé d''un capteur intelligent qui s''active uniquement au contact de la peau, Booster Pro offre des soins sûrs et efficaces adaptés à tes besoins. Recommandé pour : Tous types de peaux.', NULL, NULL, 'medicube-age-r-booster-pro', 'https://korean-skincare.fr/products/medicube-age-r-booster-pro', 'https://aurore-cdn.b-cdn.net/products/medicube-age-r-booster-pro.webp', 'Allume l''appareil en appuyant sur le bouton pendant plus de 2 secondes. Appuie brièvement sur le bouton Mode pour changer de mode. Modifie le niveau en appuyant brièvement sur le bouton d''alimentation. 1. Mode Air Shot Pour avoir une peau de verre, il faut d''abord lisser le grain de peau. Exfolie délicatement ta peau avec le mode Air Shot. Brosse l''appareil sur ta peau sèche 2 à 3 fois par semaine. (5 minutes par utilisation) Utilise-le sur peau sèche en balayant la tête de l''appareil de l''intérieur vers l''extérieur. 2. Mode Booster Peu importe les soins que tu utilises, le mode Booster améliore leur absorption et te confère une peau éclatante de santé. Fais pénétrer tes soins 1 à 3 fois avec le mode Booster (5 à 10 minutes par utilisation). Utilise-le après avoir appliqué tes soins et règle-le sur le niveau 1 lors de la première utilisation. Fais-le rouler sur ta peau en mouvements circulaires, de l''intérieur vers l''extérieur. Conseil : lorsqu''il est utilisé avec un sérum puissant, le mode Booster peut renforcer ses effets. 3. Mode MC Pour booster la fermeté de ta peau, fais pénétrer ta crème avec le mode MC. Utilise-le 1 à 3 fois par jour, en effectuant des mouvements ascendants et en collant la tête contre ta peau (5 à 10 minutes par utilisation). Utilise-le après avoir appliqué ton soin, en tirant vers le haut, de l''intérieur vers l''extérieur. Conseils : Utilise-le surtout sur le contour des yeux, de la bouche et des sillons nasogéniens. Utilisé avec une crème, le mode MC améliore le volume de la peau. 4. Mode Derma Shot Utilise le mode Derma Shot pour redessiner et raffermir ta peau, en accentuant tes pommettes et ta mâchoire. Utilise-le 1 à 3 fois par jour, en restant 1 à 2 secondes sur la zone souhaitée. (5 à 10 minutes par utilisation) Effectue lentement des mouvements circulaires ou masse vers l''extérieur pour détendre tes muscles. Conseil : Utilisé avec une crème, le mode Derma Shot améliore l''élasticité de ta peau.', 17945, '2026-05-07 17:37:40.860161+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
