INSERT INTO public.products VALUES ('019e0384-4721-782c-a650-daa8b837bfb3', '__OWNER_ID__', 'Master Serum', 'MIXSOON', 'serum', 'dropper', 'Centella Asiatica Extract, Fermented Bifida Extract, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Panthenol', 'Le Master Serum MIXSOON est un sérum hydratant qui apaise la peau et renforce sa barrière cutanée. Il combine de puissants ingrédients naturels et des probiotiques qui préviennent les dommages cutanés et fournissent une source de protéines riche nécessaires pour aider à revitaliser la peau qui a perdu son éclat.', 60, 'ml', 'mixsoon-master-serum', 'https://korean-skincare.fr/products/mixsoon-master-serum', 'https://aurore-cdn.b-cdn.net/products/mixsoon-master-serum.webp', 'Après avoir nettoyé ta peau, prépare-la avec un tonique. Distribue une quantité appropriée de sérum et applique-le sur ton visage de façon uniforme.', 3757, '2026-05-07 17:37:41.153376+00', '2026-05-11 15:40:35.656868+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-472a-76aa-8c07-145dcfe65381', '__OWNER_ID__', 'Collagen Powder', 'MIXSOON', 'moisturizer', 'jar', 'Collagène Hydrolysé', 'Améliore ta routine beauté avec la Collagen Powder MIXSOON, du collagène en poudre 100 % pur à bas poids moléculaire, conçu pour renforcer l''élasticité et l''hydratation de la peau. Cette poudre polyvalente se mélange facilement à tes sérums ou essences préférés, offrant un moyen rapide et efficace de nourrir et de raffermir les peaux irrégulières. La texture fine de la poudre se fond parfaitement dans ton soin, apportant une hydratation profonde et améliorant l''élasticité de la peau pour une apparence plus rebondie et plus jeune. Parfaite pour un usage quotidien, il est recommandé de l''associer à un sérum à base d''acide hyaluronique pour des résultats optimaux, laissant ta peau éclatante et revitalisée. Recommandé pour : Sans risque pour l''acné fongique, peaux sensibles, tous types de peaux.', 3, 'g', 'mixsoon-collagen-powder', 'https://korean-skincare.fr/products/mixsoon-collagen-powder', 'https://aurore-cdn.b-cdn.net/products/mixsoon-collagen-powder.webp', 'La Collagen Powder Mixsoon est conçue pour renforcer les effets de tes soins quotidiens lorsqu''elle est utilisée en synergie avec d''autres produits. Mélange et fais fondre une pincée de collagène en poudre avec ton essence ou ton sérum préféré sur tes mains, et applique le soin pour booster l''élasticité de ta peau.', 1187, '2026-05-07 17:37:41.162361+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4730-7270-93d5-005e4f1e8116', '__OWNER_ID__', 'Vitamin C Powder', 'MIXSOON', 'moisturizer', 'jar', '100% Vitamine en Poudre', 'Retrouve une peau radieuse et éclatante grâce à la Vitamine C Powder MIXSOON, composée à 100 % d''acide L-ascorbique non dilué pour un effet illuminant puissant. Cette poudre polyvalente se dissout sans effort et peut être mélangée à tes produits de soin de la peau ou du corps préférés. Que tu la mélanges à une lotion pour un traitement éclaircissant du corps ou à une crème pour nourrir tes mains, cette Vitamine C Powder offre des possibilités de personnalisation infinies. Elle renforce la barrière cutanée, retient l''hydratation et revitalise les peaux ternes, pour un teint sain et lumineux. Recommandé pour : Tous types de peaux.', 8, 'g', 'mixsoon-vitamin-c-powder', 'https://korean-skincare.fr/products/mixsoon-vitamin-c-powder', 'https://aurore-cdn.b-cdn.net/products/mixsoon-vitamin-c-powder.webp', 'La Mixsoon Vitamine C Poudre est conçue pour renforcer les effets de tes soins quotidiens lorsqu''elle est utilisée en synergie avec d''autres produits. Mélange et fais fondre une pincée de Vitamine C Powder avec ton essence ou ton sérum préféré dans tes mains, et applique le soin pour booster l''élasticité de ta peau.', 1108, '2026-05-07 17:37:41.168074+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
