INSERT INTO public.products VALUES ('019de0ab-64d3-7d84-a9bf-bc9e57f2f080', '__OWNER_ID__', 'Mild Acidic pH Sheet Mask, Heartleaf Fit', 'Abib', 'mask', 'pack', '1,2-Hexanediol, Allantoin, Althaea Rosea Flower Extract, ASIATIC ACID, ASIATICOSIDE, Butylene Glycol, Caffeine, Camellia Sinensis Leaf Extract, Carbomer, Centella Asiatica Extract, Chamomilla Recutita (Matricaria) Flower Extract, Disodium EDTA, Ethylhexylglycerin, Glycerin, Glycyrrhiza Glabra Root Extract, Houttuynia Cordata Extract, Hydroxyethyl Urea, MADECASSIC ACID, Madecassoside, Methylpropanediol, POLYGLYCERYL-10 LAURATE, POLYGLYCERYL-10 MYRISTATE, POLYGONUM CUSPIDATUM ROOT EXTRACT, Portulaca Oleracea Extract, Rosmarinus Officinalis Leaf Extract, SCUTELLARIA BAICALENSIS ROOT EXTRACT, Tromethamine, Aqua, XANTHAN GUM', 'Masque en tissu au pH physiologique pour apaiser instantanément les peaux stressées.', 30, 'ml', 'abib-mild-acidic-ph-sheet-mask-heartleaf-fit', 'https://www.skinsafeproducts.com/abib-mild-acidic-ph-sheet-mask-heartleaf-fit-1-01-fl-oz-30-ml-10-count', 'https://cdn1.skinsafeproducts.com/photo/04DF67A7C86692/large_1718963038.png?1718963038', 'Houttuynia Cordata + Centella Asiatica. Idéal pour restaurer l''équilibre des peaux sensibles.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:06.848+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-45ff-7114-b581-b2aee58aaec6', '__OWNER_ID__', 'Age-R Booster Pro Mini', 'Medicube', 'moisturizer', 'jar', NULL, 'Obtiens un effet glass skin à tout moment et partout avec l''Age-R Booster Pro Mini Medicube, un appareil de soin puissant mais portable, conçu pour apaiser en profondeur les peaux sensibles et booster la radiance. Cliniquement prouvé pour améliorer l’absorption des produits, ce petit appareil utilise la technologie d’électroporation pour délivrer les ingrédients actifs en profondeur, pour un teint, une texture et une clarté visiblement améliorés. Avec deux modes LED : rouge pour le soin ciblé et l’éclat, bleu pour calmer et contrôler le sébum, il est idéal pour la récupération après traitement intensif ou pour un boost quotidien d’éclat. Jusqu’à 2,7 millions de micro-impulsions par utilisation, pour des résultats comme l’amélioration du teint et la réduction de la profondeur des pores. Recommandé pour : Tous types de peaux.', NULL, NULL, 'medicube-age-r-booster-pro-mini', 'https://korean-skincare.fr/products/medicube-age-r-booster-pro-mini', 'https://aurore-cdn.b-cdn.net/products/medicube-age-r-booster-pro-mini.webp', 's : Allume l’appareil en maintenant le bouton power enfoncé, puis choisis un niveau en appuyant brièvement sur le bouton. Double-clique brièvement sur le bouton power pour sélectionner le mode LED rouge ou bleu. Renforce l’absorption des soins ou des masques une à trois fois par jour, pendant cinq à dix minutes à chaque fois, en maintenant la tête de l’appareil bien en contact avec la peau. Ne reste jamais au même endroit et garde l’appareil en mouvement. Précautions : Évite la zone des yeux et la pomme d’Adam. Avant utilisation, retire tous les accessoires et bijoux métalliques. Commence doucement au réglage le plus bas et ajuste le niveau progressivement pendant l’utilisation.', 10795, '2026-05-07 17:37:40.862839+00', '2026-05-07 17:45:48.972987+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
