INSERT INTO public.products VALUES ('019e0384-474f-7646-885d-25727aa261c8', '__OWNER_ID__', 'Melting Collagen Cheek Film', 'MIXSOON', 'moisturizer', 'jar', 'Collagène, Collagène Hydrolysé, Glutathione, Hyaluronic Acid', 'Repulpe et chouchoute tes joues avec le Melting Collagen Cheek Film MIXSOON, un soin revitalisant qui fond sur la peau et cible les ridules en les hydratant en profondeur. Avec un mélange puissant de 74 % de collagène, 19 % de collagène hydrolysé, de glutathion et d''acide hyaluronique, ce film innovant utilise la technologie d''électrofilage pour faire pénétrer les ingrédients actifs en profondeur dans la peau. Recommandé pour : Peaux sensibles, tous types de peaux.', NULL, NULL, 'mixsoon-melting-collagen-cheek-film', 'https://korean-skincare.fr/products/mixsoon-melting-collagen-cheek-film', 'https://aurore-cdn.b-cdn.net/products/mixsoon-melting-collagen-cheek-film.webp', 'Retire le film protecteur rose avec des mains propres et sèches. Applique le collagène sur tes joues. Retire le film maillé. Laisse le produit se dissoudre dans ta peau. Astuce : vaporise légèrement la zone d''application pour faciliter l''absorption.', 3856, '2026-05-07 17:37:41.199249+00', '2026-06-14 15:14:07.052+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6502-7534-a247-83bf39800dc2', '__OWNER_ID__', 'Crème Apaisante - Acide hyaluronique & Centella asiatica', 'Sephora Collection', 'moisturizer', 'jar', 'Aqua, C15-19 Alkane, Dicaprylyl Ether, Boron Nitride, Pentylene Glycol, Glycerin, POLYGLYCERYL-3 DISTEARATE, Butyrospermum Parkii Butter, SODIUM ACRYLATES COPOLYMER, Glyceryl Stearate, TRIBEHENIN, OLUS OIL (VEGETABLE OIL), POTASSIUM CETYL PHOSPHATE, Propanediol, Cetearyl Alcohol, Lecithin, Centella Asiatica Extract, CI 77288 (CHROMIUM OXIDE GREENS), GLYCERYL STEARATE CITRATE, Citric Acid, Sodium Hyaluronate, Sodium Phytate, o-Cymen-5-ol, SODIUM DEHYDROACETATE, Tocopherol', 'Crème hydratante et apaisante avec acide hyaluronique pour l’hydratation et Centella asiatica pour calmer les rougeurs et irritations. Contient un pigment vert correcteur pour un effet immédiat sur les rougeurs.', 50, 'ml', 'sephora-collection-creme-apaisante-centella-hyaluronique', 'https://www.sephora.fr', NULL, 'Texture crème confortable, adaptée aux peaux sensibles/irritées. Sans parfum fort.', 1700, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.053+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c05-7aa1-a6a1-d0d21f6c2489', '__OWNER_ID__', 'The Retinol 0.5 Oil', 'COSRX', 'oil', 'dropper', 'Squalane, Glycine Soja Oil, Di-C12-13 Alkyl Malate, Retinol, Caprylic/Capric Triglyceride, BHT, Tocotrienols, Tocopherol, Elaeis Guineensis (Palm) Oil, Hydroxymethoxyphenyl Decanone, Aqua, Caprylic/Capric Triglyceride, Propanediol, Glycerin, Tocopheryl Acetate, Cetearyl Alcohol, Trehalose, Panthenol, Butyrospermum Parkii Butter, Glycine Soja Oil, Ammonium Acryloyldimethyltaurate/VP Copolymer, Dimethicone, Glyceryl Polymethacrylate, Helianthus Annuus Seed Oil, Polyglyceryl-10 Stearate, Hydrogenated Lecithin, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Carbomer, Tromethamine, Glyceryl Stearate, Polysilicone-11, Sodium Sulfite, Tocopherol, Daucus Carota Sativa Root Extract, Retinol, Allantoin, Glyceryl Caprylate, Oryza Sativa (Rice) Bran Wax, Tocotrienols, Stearic Acid, Polyglyceryl-3 Methylglucose Distearate, Palmitic Acid, Disodium EDTA, Ethylhexylglycerin, Adenosine, Sorbitan Isostearate, Elaeis Guineensis (Palm) Oil, BHT, Beta-Carotene, Myristic Acid, Lauric Acid, Ascorbic Acid, Limnanthes Alba Seed Oil, 3-O-Ethyl Ascorbic Acid, Glutathione, Sodium Hyaluronate, 1,2-Hexanediol, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hyaluronic Acid, Sodium Acetylated Hyaluronate', 'La Retinol 0,5 Oil COSRX est un produit de soin qui contient 0,5 % de rétinol, un dérivé de la vitamine A connu pour ses bienfaits anti-âge et de rajeunissement de la peau. Cette huile est conçue pour cibler les ridules, les rides, le teint inégal et la texture de la peau. Cette formule est enrichie d''un mélange d''huiles naturelles telles que l''huile de soja et de palme, qui agissent ensemble pour hydrater la peau en profondeur et améliorer son élasticité. La Retinol 0,5 Oil convient à tous les types de peau, y compris les peaux sensibles. Il est recommandé de commencer en l''utilisant une ou deux fois par semaine, puis d''augmenter progressivement jusqu''à une utilisation quotidienne selon la tolérance. Utilise toujours une crème solaire à large spectre pendant la journée lorsque tu utilises des produits à base de rétinol, car ils peuvent augmenter la sensibilité de la peau au soleil. La Retinol 0,5 Oil COSRX est un excellent complément à toute routine beauté anti-âge, car elle nourrit, hydrate et protège la peau tout en travaillant à l''amélioration de sa texture et de son apparence.', 26, 'ml', 'cosrx-the-retinol-0-5-oil', 'https://korean-skincare.fr/products/cosrx-the-retinol-0-5-oil', 'https://aurore-cdn.b-cdn.net/products/cosrx-the-retinol-0-5-oil.webp', 'Pendant ta routine du soir, applique 1 à 2 gouttes de produit sur ta main et tapote du bout des doigts, de l''intérieur vers l''extérieur, et laisse pénétrer le produit. Limite l''utilisation initiale à trois fois par semaine ; augmente progressivement la fréquence jusqu''à un soir sur deux, utilise selon ta tolérance. *Laisse-toi une "période d''adaptation" lors de l''utilisation du rétinol*. *SEMAINE 1~2 - Mode d''emploi : après le nettoyage, à l''étape du sérum, applique 2-3 gouttes de produit sur les zones concernées (par exemple, sous les yeux, autour de la bouche, sur le front et le cou). *SEMAINE 3 ~ - Fréquence : peut être appliqué tous les soirs. - Mode d''emploi : Après le nettoyage, lors de l''étape du sérum, étale le produit sur l''ensemble de ton visage. * La phase de "développement de la tolérance" peut être raccourcie ou prolongée en fonction des différences individuelles.', 1995, '2026-05-07 17:37:38.309615+00', '2026-06-14 15:14:07.053+00', 'skincare', '[]', 'huile', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
