INSERT INTO public.products VALUES ('019e0384-3c35-76f2-b5f3-e781dc6b283a', '__OWNER_ID__', 'Propolis Nourishing Magnet Sheet Mask', 'COSRX', 'mask', 'pack', 'Aqua, Dipropylene Glycol, Glycerin, Glycereth-26, Alcohol, Butylene Glycol, Trehalose, Panthenol, Xanthan Gum, Paeonia Suffruticosa Root Extract, Centella Asiatica Extract, 1,2-Hexanediol, Polyglyceryl-10 Laurate, Chamomilla Recutita (Matricaria) Flower Extract, Glyceryl Caprylate, Ethylhexylglycerin, Disodium EDTA, Pimpinella Anisum (Anise) Fruit Extract, Pantolactone, Royal Jelly Extract, Diethylhexyl Sodium Sulfosuccinate, Vanilla Planifolia Fruit Extract, Camellia Sinensis Leaf Extract, Honey Extract, Rosa Centifolia Flower Extract, Pyrus Communis Fruit Extract, Propolis Extract, Cocos Nucifera Oil, Rose Extract, Fragaria Chiloensis Fruit Extract', 'Le Propolis Nourishing Magnet Sheet Mask COSRX enrichi de propolis, de gelée royale et d''extrait de miel nourrit la peau et l''hydrate durablement. La propolis riche en nutriments aide à calmer et à revigorer les peaux irritées. Le matériau du masque tissu épouse étroitement les formes du visage afin de diffuser efficacement les ingrédients actifs pour un éclat sain et naturel. Recommandé pour : Tous types de peaux.', 1, 'pcs', 'cosrx-propolis-nourishing-magnet-sheet-mask', 'https://korean-skincare.fr/products/cosrx-propolis-nourishing-magnet-sheet-mask', 'https://aurore-cdn.b-cdn.net/products/cosrx-propolis-nourishing-magnet-sheet-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 395, '2026-05-07 17:37:38.357331+00', '2026-06-14 15:14:07.059+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
