INSERT INTO public.products VALUES ('019e0384-3c2c-7804-bd3e-357b1fc6c421', '__OWNER_ID__', 'Peptide-132 Ultra Perfect Hair Bonding Shampoo', 'COSRX', 'shampoo', 'jar', 'Water/​Aqua/​Eau, Sodium C14-16 Olefin Sulfonate, Glycerin, Disodium Laureth Sulfosuccinate, Cocamidopropyl Betaine, Caprylyl/Capryl Glucoside, Lauryl Hydroxysultaine, Disodium Cocoyl Glutamate, Sodium Cocoyl Alaninate, Lauryl Betaine, Sodium Chloride, Niacinamide, Cetyl Alcohol, Polyquaternium-10, Citric Acid, Sodium Salicylate, PVP, Parfum, Caprylyl Glycol, Trihydroxystearin, Caprylic/Capric Triglyceride, Polyquaternium-6, Sodium Citrate, PPG-3 Caprylyl Ether, C10-18 Triglycerides, Vitis Vinifera Seed Oil, Dicaprylyl Ether, Sodium Metaphosphate, Ethylhexylglycerin, Piroctone Olamine, Anthemis Nobilis Flower Water, Glyceryl Stearate, Guar Hydroxypropyltrimonium Chloride, Sodium Benzoate, Macadamia Ternifolia Seed Oil, Dehydroacetic Acid, Hexyl Cinnamal, Propanediol, Zinc PCA, 1,2-Hexanediol, Biotin, Tripeptide-1, Tripeptide-3, Tripeptide-2, Tocopherol, Sodium Hyaluronate, Laminaria Japonica Extract, Avena Sativa (Oat) Peptide, Arginine, Serine, Glutamic Acid, Threonine, Leucine, Proline, Aspartic Acid, Isoleucine, Glycine, Soluble Collagen, Hydrolyzed Hyaluronic Acid, Phenylalanine, Alanine, Tyrosine, Lysine, Sodium Hyaluronate Crosspolymer, Histidine, Hyaluronic Acid, Caffeine, Panthenol, Alcohol Denat, PEG-150 Pentaerythrityl Tetrastearate, Hydrogenated Lecithin, Butylene Glycol, Cetearyl Alcohol, Valine, PPG-2 Hydroxyethyl Cocamide, Stearic Acid, Sodium Acetylated Hyaluronate, Ceramide NP, Phytosphingosine, Cholesterol, Hydrolyzed Vegetable Protein, Methionine, Ceramide NS, Cystine, Ceramide AP, Ceramide EOP, Tryptophan, Ceramide AS', 'Transforme tes cheveux avec le Peptide-132 Ultra Perfect Hair Bonding Shampoo COSRX, une innovation K-beauty qui nettoie en douceur tout en réparant les cheveux abîmés grâce à la technologie brevetée PEPTIDE-132™. Enrichi en ingrédients apaisants comme le piroctone olamine, le zinc PCA et la caféine, ce shampooing combat les pellicules, l’excès de sébum et les irritations, laissant le cuir chevelu rafraîchi et les cheveux revitalisés avec une texture lisse et saine. Cette formule innovante combine réparation des liens capillaires et soin du cuir chevelu, avec de la protéine végétale hydrolysée, du collagène et 18 acides aminés pour renforcer et nourrir tous les types de cheveux, de légèrement secs à gravement abîmés chimiquement. Sa mousse riche et son pH légèrement acide assurent une barrière cutanée saine, offrant des résultats dignes d’un salon pour des cheveux éclatants et faciles à coiffer à chaque lavage. Recommandé pour : Tous types de cheveux, y compris secs, abîmés, gras, sujets aux pellicules, colorés ou traités chimiquement. Comment l’utiliser : Distribue le shampooing : Applique une petite quantité du Peptide-132 Ultra Perfect Hair Bonding Shampoo COSRX sur cheveux et cuir chevelu humides. Masse délicatement : Fais mousser en insistant sur le cuir chevelu et les racines pour nettoyer et réparer. Laisse agir brièvement : Laisse poser 1 à 2 minutes pour maximiser la réparation des liens et apaiser le cuir chevelu. Rince soigneusement : Rince à l’eau tiède ; poursuis avec du Peptide-132 Treatment ou Oil COSRX pour de meilleurs résultats.', 200, 'ml', 'cosrx-peptide-132-ultra-perfect-hair-bonding-shampoo', 'https://korean-skincare.fr/products/cosrx-peptide-132-ultra-perfect-hair-bonding-shampoo', 'https://aurore-cdn.b-cdn.net/products/cosrx-peptide-132-ultra-perfect-hair-bonding-shampoo.webp', NULL, 2095, '2026-05-07 17:37:38.348329+00', '2026-06-14 15:14:07.06+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
