INSERT INTO public.products VALUES ('019e0384-3d77-7785-9100-3af8810446b3', '__OWNER_ID__', 'All-Around Safe Block Waterproof Sun Milk SPF50+ PA++++', 'MISSHA', 'moisturizer', 'jar', 'Aqua, Cyclopentasiloxane, Homosalate, Silica, Ethylhexyl Salicylate, Titanium Dioxide, Butylene Glycol, Lauryl PEG-10 Tris(Trimethylsiloxy)Silylethyl Dimethicone, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Glycerin, C12-15 Alkyl Benzoate, Alcohol Denat, Helichrysum Arenarium Extract, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Isopropyl Palmitate, Dimethicone, PEG-10 Dimethicone, Magnesium Sulfate, Aluminum Hydroxide, Dimethicone/​Vinyl Dimethicone Crosspolymer, Stearic Acid, Parfum, Triethoxycaprylylsilane, Phenoxyethanol, Quaternium-18 Bentonite, Silica Dimethyl Silylate, Sodium Benzoate, Acrylates/​Dimethicone Copolymer, Tocopheryl Acetate, Disodium EDTA, Potassium Sorbate, Caprylyl Glycol, VP/​Hexadecene Copolymer, Psidium Guajava Leaf Extract, Cinchona Succirubra Bark Extract, Abronia Villosa Leaf Extract, Aloe Barbadensis Leaf Extract, Eucalyptus Globulus Leaf Extract, Rhodiola Rosea Root Extract', 'L''All-Around Safe Block Waterproof Sun Milk SPF50+ PA++++ Missha est une crème hydratante, non grasse et non collante qui offre une protection complète contre les rayons UVA/UVB nocifs et qui apaise les peaux irritées par le soleil. Avec sa texture hydratante légère, la crème solaire All-round Safe Block s''applique en douceur et donne un fini satiné sans laisser de traces blanches. Ses ingrédients, notamment les extraits de fleur d''abricot, de fleur de lotus, de fleur de chrysanthème et de fleur de camélia, fournissent toute l''hydratation et la nutrition dont la peau a besoin. Cette formule contient également de l''extrait de thanaka qui procure un effet rafraîchissant.', 70, 'ml', 'missha-all-around-safe-block-waterproof-sun-milk-spf50-pa', 'https://korean-skincare.fr/products/missha-all-around-safe-block-waterproof-sun-milk-spf50-pa', 'https://aurore-cdn.b-cdn.net/products/missha-all-around-safe-block-waterproof-sun-milk-spf50-pa.webp', 'Secoue 4-5 fois avant utilisation. Applique une quantité suffisante de produit sur ton visage en toute dernière étape de ta routine beauté. Tapote délicatement jusqu''à absorption complète. Applique de façon égale sur le cou, les bras et les jambes et toutes les zones du corps exposées au soleil. Renouvelle l''application au besoin pour une protection solaire parfaite tout au long de la journée.', 1369, '2026-05-07 17:37:38.679277+00', '2026-06-14 15:14:07.062+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
