INSERT INTO public.products VALUES ('019de0ab-6502-7e82-b61c-bab9d0f49063', '__OWNER_ID__', 'Sérum Concentré Vitamine C 10% & Astaxanthine', 'Aroma-Zone', 'serum', 'dropper', 'Aqua, Ascorbyl Glucoside, Glycerin, SALIX NIGRA BARK EXTRACT, Sodium Hydroxide, SODIUM LEVULINATE, Haematococcus Pluvialis Extract, Sodium Hyaluronate, Simmondsia Chinensis Seed Oil, ASTRAGALUS GUMMIFER GUM, LEVULINIC ACID, SODIUM ANISATE, PHYTIC ACID, POLYPEPSILON-LYSINE, Tocopherol, Helianthus Annuus Seed Oil', 'Sérum antioxydant puissant avec 10% d’ascorbyl glucoside et astaxanthine pour protéger contre le photo-vieillissement, stimuler le collagène, éclaircir et réduire les taches.', 30, 'ml', 'aroma-zone-serum-vitamine-c-10-astaxanthine', 'https://www.aroma-zone.com', NULL, 'Formule clean, vegan, avec hyaluronate de sodium et huile de jojoba. Convient aux peaux matures ou exposées.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.083+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4647-7d5b-aec0-db0d8e57eee7', '__OWNER_ID__', 'Zero Pore Blackhead Deep Cleansing Oil', 'Medicube', 'cleanser', 'tube', 'Glycine Soja Oil, Sorbeth-30 Tetraoleate, Parfum, Vitis Vinifera Seed Oil, Olea Europaea Fruit Oil, Melia Azadirachta Leaf Extract, Melia Azadirachta Flower Extract, Simmondsia Chinensis Seed Oil, Ricinus Communis Seed Oil, Macadamia Integrifolia Seed Oil, Corylus Avellana (Hazelnut) Seed Oil, Argania Spinosa Kernel Oil, Oryza Sativa (Rice) Bran Oil, Camellia Japonica Seed Oil, Helianthus Annuus Seed Oil, Coccinia Indica Fruit Extract, Aloe Barbadensis Flower Extract, Solanum Melongena Fruit Extract, Ocimum Sanctum Leaf Extract, Corallina Officinalis Extract, Curcuma Longa Root Extract, Aqua, Butylene Glycol, Capryloyl Salicylic Acid, Allantoin, Niacinamide, Guaiazulene, Asiaticoside, Asiatic Acid, Madecassic Acid, Tocopherol, 1,2-Hexanediol, Pentylene Glycol, Salix Alba Bark Extract, Chamaecyparis Obtusa Leaf Extract, Origanum Vulgare Leaf Extract, Sodium Hyaluronate, Pinus Densiflora Leaf Extract, Madecassoside, Scutellaria Baicalensis Root Extract, Cinnamomum Cassia Bark Extract, Portulaca Oleracea Extract, Lactobacillus/​Soybean Ferment Extract, Decyl Glucoside, Pueraria Lobata Root Extract, Pinus Palustris Leaf Extract, Ulmus Davidiana Root Extract, Oenothera Biennis Flower Extract, Caprylyl Glycol, Ethylhexylglycerin', 'La Zero Pore Blackhead Deep Cleansing Oil Medicube est un nettoyant puissant à utiliser en première étape, qui dissout les points noirs, l’excès de sébum et le maquillage longue tenue sans dessécher la peau. Formulée avec un mélange d’huiles léger et non comédogène, elle pénètre en profondeur dans les pores pour dissoudre les impuretés et déboucher les zones congestionnées, notamment la zone T. Idéale pour les peaux grasses et sujettes aux points noirs, elle aide à affiner les pores tout en laissant la peau fraîche, propre et hydratée. Enrichi en ingrédients apaisants comme l’extrait de Centella Asiatica et des huiles d’origine végétale, ce nettoyant huileux contribue également à calmer les inflammations et à soutenir une barrière cutanée saine. Une utilisation régulière du Zero Pore Blackhead Deep Cleansing Oil Medicube aide à réduire l’apparence des points noirs et des pores pour un teint visiblement plus lisse et clair, sans sensation de tiraillement ni résidu. Recommandé pour : Tous types de peaux, en particulier les peaux mixtes, grasses et sensibles.', 205, 'ml', 'medicube-zero-pore-blackhead-deep-cleansing-oil-1', 'https://korean-skincare.fr/products/medicube-zero-pore-blackhead-deep-cleansing-oil-1', 'https://aurore-cdn.b-cdn.net/products/medicube-zero-pore-blackhead-deep-cleansing-oil-1.webp', 'Applique une quantité appropriée sur peau humide, masse doucement en mouvements circulaires et rince abondamment à l’eau tiède. Utilise matin et soir pour de meilleurs résultats.', 1895, '2026-05-07 17:37:40.935725+00', '2026-06-14 15:14:07.083+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6503-7118-a135-b545e85418b9', '__OWNER_ID__', 'Baume Hydratant', 'CeraVe', 'moisturizer', 'pump', 'Aqua, Glycerin, Cetearyl Alcohol, Caprylic/Capric Triglyceride, Cetyl Alcohol, Dimethicone, Phenoxyethanol, Petrolatum, BEHENTRIMONIUM METHOSULFATE, POLYGLYCERYL-3 DIISOSTEARATE, SODIUM LAUROYL LACTYLATE, Ethylhexylglycerin, Potassium Phosphate, Disodium EDTA, DIPOTASSIUM PHOSPHATE, Ceramide NP, Ceramide AP, Phytosphingosine, Cholesterol, XANTHAN GUM, Carbomer, Sodium Hyaluronate, Tocopherol, Ceramide EOP', 'Baume hydratant très riche et réparateur pour peaux sèches à très sèches. Hydratation 48h, restaure la barrière cutanée, texture non grasse pour un habillage rapide.', 454, 'g', 'cerave-baume-hydratant', 'https://www.cerave.fr', 'https://aurore-cdn.b-cdn.net/products/cerave-baume-hydratant.webp', '4.7 ★. 3 céramides essentiels + HA. Technologie MVE. +10% de céramides après 4 semaines. Sans parfum. Convient visage/corps, toute la famille.', 1800, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.083+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6503-71a7-ae42-888d16b337e2', '__OWNER_ID__', 'Crème Hydratante', 'CeraVe', 'moisturizer', 'pump', 'Aqua, Glycerin, Cetearyl Alcohol, Caprylic/Capric Triglyceride, Cetyl Alcohol, Ceteareth-20, Petrolatum, Potassium Phosphate, Ceramide NP, Ceramide AP, Ceramide EOP, Carbomer, Dimethicone, BEHENTRIMONIUM METHOSULFATE, SODIUM LAUROYL LACTYLATE, Sodium Hyaluronate, Cholesterol, Phenoxyethanol, Disodium EDTA, DIPOTASSIUM PHOSPHATE, Tocopherol, Phytosphingosine, XANTHAN GUM, Ethylhexylglycerin', 'Crème hydratant quotidienne pour peaux normales à sèches. Texture plus fluide que le baume, confort immédiat, restaure la barrière, hydratation 24h.', 340, 'g', 'cerave-creme-hydratante', 'https://www.cerave.fr', 'https://aurore-cdn.b-cdn.net/products/cerave-creme-hydratante.webp', '4.6 ★. 3 céramides essentiels + HA. Technologie MVE. Sans parfum. Excellent rapport qualité-prix. Convient visage/corps, toute la famille.', 1500, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.084+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c74-7933-aa30-46e87c485bbe', '__OWNER_ID__', 'Ginseng Moist Sun Serum SPF 50+ PA++++', 'Beauty of Joseon', 'serum', 'dropper', 'Aqua, Panax Ginseng Root Extract, Dibutyl Adipate, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Alcohol, Acrylates Copolymer, Butyloctyl Salicylate, C12-15 Alkyl Benzoate, Ethylhexyl Triazone, Niacinamide, Phenethyl Benzoate, Panax Ginseng Berry Extract, Panax Ginseng Extract, Panax Ginseng Leaf/​Stem Extract, Silica, Methylpropanediol, Olea Europaea Fruit Oil, Amyris Balsamifera Bark Oil, Angelica Archangelica Root Oil, Citrus Aurantium Amara (Bitter Orange) Leaf/​Twig Oil, Ferula Galbaniflua (Galbanum) Resin Oil, Jasminum Officinale Oil, Panax Ginseng Root Extract, Isoamyl p-Methoxycinnamate, Polysilicone-15, Polymethylsilsesquioxane, 1,2-Hexanediol, Dibutyl Lauroyl Glutamide, Pentylene Glycol, Dibutyl Ethylhexanoyl Glutamide, Ammonium Acryloyldimethyltaurate/VP Copolymer, Sodium Acrylates Crosspolymer-2, Sodium Polyacryloyldimethyl Taurate, C30-45 Alkyldimethylsilyl Polypropylsilsesquioxane, Hydroxyacetophenone, Adenosine, Glycerin, Butylene Glycol, Ethyl Hexanediol, Tocopherol, Ethylhexylglycerin, Xanthan Gum, Disodium EDTA', 'Le Ginseng Moist Sun Serum SPF 50+ PA++++ Beauty Of Joseon est une innovation remarquable en matière de soins de la peau, qui combine les avantages d''une protection solaire supérieure, d''un soin nourrissant et d''une cure de jouvence. Ce sérum est conçu pour améliorer ta routine beauté et faire en sorte que ta peau reste protégée, radieuse et pleine de jeunesse. Avec son exceptionnel SPF 50+ PA++++, ce sérum agit comme une formidable défense contre les effets néfastes des rayons UV nocifs. Il forme une barrière invisible sur ta peau, la protégeant des coups de soleil, du vieillissement prématuré et de l''apparition de taches brunes. Dis adieu aux préoccupations concernant les dommages cutanés causés par le soleil et profite en toute confiance d''une peau nourrie et protégée. Ce sérum se distingue par son infusion de 30 % d''extrait de ginseng, un ingrédient puissant réputé pour ses propriétés revitalisantes. Le ginseng est connu pour améliorer l''élasticité et la fermeté de la peau, ce qui aide à réduire l''apparence des rides et des ridules. En stimulant la production de collagène, ce sérum favorise un teint plus lisse et plus souple qui respire la jeunesse et l''éclat. Libère la puissance du ginseng et accède à un nouveau degré de vitalité pour ta peau. Pour rehausser davantage la beauté naturelle de ta peau, ce sérum est enrichi de 2 % de niacinamide, un ingrédient puissant réputé pour ses effets éclaircissants. Le niacinamide aide à unifier le teint, à estomper les taches brunes et à améliorer la texture générale de la peau. Profite d''un teint lumineux et éclatant qui respire la santé et la vitalité, pour te permettre de briller de l''intérieur.', 50, 'ml', 'beauty-of-joseon-ginseng-moist-sun-serum-spf-50-pa', 'https://korean-skincare.fr/products/beauty-of-joseon-ginseng-moist-sun-serum-spf-50-pa', 'https://aurore-cdn.b-cdn.net/products/beauty-of-joseon-ginseng-moist-sun-serum-spf-50-pa.webp', 'Lors de la dernière étape de ta routine beauté, répartis uniformément une quantité généreuse de produit sur les zones vulnérables à l''exposition au soleil.', 1425, '2026-05-07 17:37:38.42038+00', '2026-06-14 15:14:07.084+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
