INSERT INTO public.products VALUES ('019e0384-3d58-77c3-bed4-7508a4f8a952', '__OWNER_ID__', 'All-Around Safe Block Aqua Sun SPF50+ PA++++', 'MISSHA', 'moisturizer', 'jar', 'Aqua, Ethylhexyl Methoxycinnamate, Alcohol Denat, Octocrylene, Ethylhexyl Salicylate, Dipropylene Glycol, Avobenzone, Methyl Methacrylate Crosspolymer, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Cyclopentasiloxane, Acrylates/​Dimethicone Copolymer, Vp/​Hexadecene Copolymer, Aqua, Mesembryanthemum Crystallinum Extract, Limonia Acidissima Extract, Rosa Davurica Bud Extract, Bis-Peg/​Ppg-20/​5 Peg/​Ppg-20/​5 Dimethicone, Methoxy Peg/​Ppg-25/​4 Dimethicone, Dimethicone, Caprylic/Capric Triglyceride, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Sodium Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Isohexadecane, Sodium Hydroxide, Polysorbate 80, BHT, Disodium EDTA, Caprylyl Glycol, Ethylhexylglycerin, 1,2-Hexanediol, Parfum', 'L''All-Around Safe Block Aqua Sun Gel Missha possède une formule à base de gel d''eau qui pénètre rapidement dans la peau pour offrir une hydratation et un rafraîchissement intenses. Des filtres UVA et UVB améliorés garantissent une protection exceptionnelle contre les rayons UV. De l''eau glaciaire et de l''extrait de ficoïde glaciale sont associés pour créer une base de gel d''eau légère qui hydrate, rafraîchit et pénètre rapidement dans la peau. Les extraits de rose Antozone et de thanaka viennent en renfort pour apaiser la peau. La rose Antozone protège la peau des facteurs de stress environnementaux, tandis que l''extrait de thanaka procure un effet rafraîchissant. Waterproof.', 50, 'ml', 'missha-all-around-safe-block-aqua-sun-gel-spf50-pa', 'https://korean-skincare.fr/products/missha-all-around-safe-block-aqua-sun-gel-spf50-pa', 'https://aurore-cdn.b-cdn.net/products/missha-all-around-safe-block-aqua-sun-gel-spf50-pa.webp', 'Applique sur les zones exposées du visage/corps 30 minutes avant de sortir au soleil. Renouvelle l''application toutes les deux heures pour une protection solaire parfaite pendant la journée.', 1080, '2026-05-07 17:37:38.64835+00', '2026-06-14 15:14:07.104+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
