INSERT INTO public.products VALUES ('019e0384-3e2e-71b6-942c-2fa981c707a8', '__OWNER_ID__', 'Bee Pollen Renew Ampouler', 'MISSHA', 'serum', 'dropper', 'Pollen Extract, Glycerin, Aqua, Propanediol, Butylene Glycol, Glycereth-26, Methyl Trimethicone, Dipropylene Glycol, Niacinamide, C14-22 Alcohols, Dimethicone, Octyldodecanol, Panthenol, 1,2-Hexanediol, Glyceryl Stearate, Hydroxyethyl Urea, Chondrus Crispus Extract, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Choleth-24, C12-20 Alkyl Glucoside, Saccharum Officinarum Extract, Diphenyl Dimethicone, Triethylhexanoin, Sodium Polyacrylate, Hydrogenated Lecithin, Carbomer, Glyceryl Acrylate/​Acrylic Acid Copolymer, Caprylic/Capric Triglyceride, Caprylyl Glycol, Tromethamine, Adenosine, Polysorbate 60, Sorbitan Isostearate, Helianthus Annuus Seed Oil, Citric Acid, Disodium EDTA, Lavandula Angustifolia Oil, Ceramide NP, Maltodextrin, Theobroma Cacao Seed Extract, Royal Jelly Extract, Pelargonium Graveolens Oil, Anthemis Nobilis Flower Oil, Cananga Odorata Flower Oil, Citrus Aurantium Bergamia (Bergamot) Fruit Oil, Honey Extract, Rosa Damascena Flower Oil, Leontopodium Alpinum Callus Culture Extract, Aspalathus Linearis Leaf Extract, Anthemis Nobilis Flower Extract, Propolis Extract, Butyrospermum Parkii Butter, Chrysanthemum Boreale Flower Extract, Ethylhexylglycerin, Sodium Hyaluronate, Phenethyl Alcohol, Maltodextrin, Hydrolyzed Royal Jelly Protein', 'Le Bee Pollen Renew Ampouler Missha est un sérum qui renforce la barrière protectrice de la peau et l''énergise grâce au potentiel du pollen d''abeille. Contenant 42% de pollen, ce sérum concentré est une grande source de vitamines et de minéraux pour nourrir la peau. Il aide à réduire l''apparence des rides et combat les dommages causés par les oxydants.', 40, 'ml', 'bee-pollen-renew-ampouler', 'https://korean-skincare.fr/products/bee-pollen-renew-ampouler', 'https://aurore-cdn.b-cdn.net/products/bee-pollen-renew-ampouler.webp', 'Applique 2 à 3 gouttes sur une peau nettoyée. Tamponne le sérum dans la peau jusqu''à ce qu''il soit complètement absorbé.', 2836, '2026-05-07 17:37:38.861899+00', '2026-06-14 15:14:07.12+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
