INSERT INTO public.products VALUES ('019e0384-409d-7b75-b0c4-98124fcfe55b', '__OWNER_ID__', 'Madagascar Centella Tone Brightening Tone-Up Sunscreen', 'SKIN1004', 'moisturizer', 'jar', 'Aqua, Dibutyl Adipate, Titanium Dioxide, Propanediol, Caprylic/Capric Triglyceride, Centella Asiatica Extract, C12-15 Alkyl Benzoate, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Ethylhexyl Triazone, Niacinamide, Caprylyl Methicone, Diethylhexyl Butamido Triazone, 1,2-Hexanediol, Pentylene Glycol, Corchorus Olitorius Leaf Extract, Hordeum Vulgare Sprout Extract, Nymphaea Alba Flower Extract, Sodium Hyaluronate, Coco-Caprylate/Caprate, Glycerin, Polyhydroxystearic Acid, Dimethicone/​Vinyl Dimethicone Crosspolymer, Vp/​Eicosene Copolymer, Dimethiconol, Trisiloxane, Stearic Acid, Alumina, Sodium Polyacryloyldimethyl Taurate, Polyacrylate Crosspolymer-6, Hydroxypropyl Methylcellulose Stearoxy Ether, Dicaprylyl Carbonate, Ethylhexylglycerin, Xanthan Gum, Triethoxycaprylylsilane, Adenosine, Sodium Polyacrylate, Madecassoside, Pvm/​Ma Copolymer, Polyether-1, T-Butyl Alcohol, Tranexamic Acid, Dipropylene Glycol, Sodium Palmitoyl Proline, Butylene Glycol, CI 77492, CI 77491', 'La Madagascar Centella Tone Brightening Tone-Up Sunscreen SKIN1004 est une crème solaire à usage quotidien qui offre une excellente protection contre les rayons UVA et UVB, tout en aidant à éclaircir et à unifier le teint. Elle est spécialement formulée avec de l''extrait de Centella Asiatica de Madagascar et du niacinamide, qui sont connus pour apaiser et calmer les peaux irritées, tout en apportant un effet éclaircissant. Cette crème solaire légère possède un effet correcteur qui aide à camoufler toute rougeur ou irrégularité du teint, te laissant avec une peau radieuse et d''apparence naturelle. Sa formule non grasse est facilement absorbée par la peau, et elle ne laisse pas de traces blanches ni de résidus collants. La Madagascar Centella Tone Brightening Tone-Up Sunscreen SKIN1004 est parfaite pour tous les types de peau, en particulier pour les peaux sensibles. Elle est exempte de produits chimiques nocifs comme les parabènes, les sulfates et les parfums artificiels, ce qui en fait un choix sûr et efficace pour un usage quotidien.', 50, 'ml', 'skin1004-madagascar-centella-tone-brightening-tone-up-sunscreen', 'https://korean-skincare.fr/products/skin1004-madagascar-centella-tone-brightening-tone-up-sunscreen', 'https://aurore-cdn.b-cdn.net/products/skin1004-madagascar-centella-tone-brightening-tone-up-sunscreen.webp', 'Applique une quantité appropriée sur ta peau, en évitant le contour des yeux, lors de la dernière étape de ta routine beauté.', 1211, '2026-05-07 17:37:39.485568+00', '2026-06-14 15:14:07.132+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
