INSERT INTO public.products VALUES ('019e0384-40b1-7445-b61f-7fb91689b3a2', '__OWNER_ID__', 'Madagascar Centella Air-Fit Suncream Light SPF30 PA++++', 'SKIN1004', 'moisturizer', 'jar', 'Aqua, Zinc Oxide, Propanediol, Dicaprylyl Carbonate, Butylene Glycol, Caprylic/Capric Triglyceride, Benzotriazolyl Dodecyl P-Cresol, Centella Asiatica Extract, Polyglyceryl-3 Distearate, Niacinamide, Caprylyl Methicone, C12-15 Alkyl Benzoate, 1,2-Hexanediol, Pentylene Glycol, Cetearyl Alcohol, Portulaca Oleracea Extract, Houttuynia Cordata Extract, Polyhydroxystearic Acid, Glyceryl Stearate, Hydrolyzed Jojoba Esters, Sodium Polyacryloyldimethyl Taurate, Triethoxycaprylylsilane, Glyceryl Stearate Citrate, Polyacrylate Crosspolymer-6, Methylpropanediol, Ethylhexylglycerin, Xanthan Gum, Adenosine, Polyether-1, T-Butyl Alcohol, Biosaccharide Gum-1, Madecassic Acid, Asiaticoside, Asiatic Acid', 'Le Madagascar Centella Air-Fit Suncream Light SPF30 PA++++ SKIN1004 est une crème solaire physique non-nano qui bloque les rayons UV, tout en éclaircissant simultanément la peau. Légère et agréable à porter, cette essentielle de l’été est infusée d’extrait de Centella Asiatica et de niacinamide pour aider à apaiser et à affiner l’apparence de la peau. Elle contribue également à préserver une peau lisse et éclatante de santé, sans fini gras ni trace blanche.', 50, 'ml', 'skin-1004-madagascar-centella-air-fit-suncream-light-spf30-pa', 'https://korean-skincare.fr/products/skin-1004-madagascar-centella-air-fit-suncream-light-spf30-pa', 'https://aurore-cdn.b-cdn.net/products/skin-1004-madagascar-centella-air-fit-suncream-light-spf30-pa.webp', 'Lors de la dernière étape de ta routine de soins de la peau, applique uniformément sur les zones exposées aux rayons UV. Renouvelle l''application toutes les deux heures pour une protection solaire optimale.', 1223, '2026-05-07 17:37:39.505083+00', '2026-06-14 15:14:07.133+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
