INSERT INTO public.products VALUES ('019de0ab-6514-7b7b-8a96-c77ddb86690b', '__OWNER_ID__', 'Roséliane Soin Anti-Rougeurs', 'Uriage', 'moisturizer', 'pump', 'Aqua, Squalane, Dicaprylyl Ether, Butyrospermum Parkii Butter, DIGLYCERIN, Propanediol, Cetyl Alcohol, PENTAERYTHRITYL DISTEARATE, 1,2-Hexanediol, STEARETH-2, STEARETH-21, Dimethicone, Glyceryl Stearate, PEG-100 Stearate, SODIUM POLYACRYLATE, Parfum, Titanium Dioxide, Chlorphenesin, CI 77019, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Tocopheryl Acetate, XANTHAN GUM, o-Cymen-5-ol, Maltodextrin, ASIATICOSIDE, ASPARAGOPSIS ARMATA EXTRACT, Panax Ginseng Root Extract, POLYGLYCERYL-10 STEARATE, Sodium Benzoate, Potassium Sorbate, ASCOPHYLLUM NODOSUM EXTRACT, TRIETHYL CITRATE, POLYGLYCERYL-6 BEHENATE, CI 77491, Silica, BEHENIC ACID, Ceramide NP, Cetearyl Alcohol, Cholesterol, Lactic Acid, Ceramide NS, Tocopherol, Ceramide EOP, Ceramide AP, SODIUM CETEARYL SULFATE, Sodium Hydroxide, Glycerin', 'Soin anti-rougeurs qui atténue les rougeurs et prévient leur réapparition. Texture légère aux nacres vertes neutralisantes.', 40, 'ml', 'uriage-roseliane-soin-anti-rougeurs-creme', 'https://www.uriage.fr/produits/roseliane-creme-anti-rougeurs', 'https://aurore-cdn.b-cdn.net/products/uriage-roseliane-soin-anti-rougeurs-creme.webp', 'Formulé avec de l"algue rouge (Asparagopsis Armata) et des céramides. Complexes brevetés TLR2-Regul + SK5R. N°1 anti-rougeurs en pharmacie.', 1300, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.136+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-40d6-7748-924c-6e7738fa1478', '__OWNER_ID__', 'Mummy Pack', 'SKIN1004', 'moisturizer', 'jar', 'Albumen, Zea Mays Starch, Silica, Charcoal Powder, Allantoin, Aloe Barbadensis Leaf Powder, Panthenol, Aqua, Butylene Glycol, 1,2-Hexanediol, Niacinamide, Tuber Melanosporum Extract, Glycine Soja (Soybean) Seed Extract, Sesamum Indicum (Sesame) Seed Extract, Vaccinium Angustifolium Fruit Extract, Vaccinium Macrocarpon (Cranberry) Fruit Extract, Euterpe Oleracea Fruit Extract, Vaccinium Myrtillus Fruit Extract, Ribes Nigrum (Black Currant) Fruit Extract, Sambucus Nigra Fruit Extract, Lycium Chinense Fruit Extract, Fragaria Chiloensis Fruit Extract, Adenosine, Allantoin, Panthenol, Glycerin, Sodium PCA, Disodium EDTA', 'Le Mummy Pack SKIN1004, le populaire masque antirides et liftant, est de retour avec un nouvel emballage et une formule améliorée. Infusé d’extrait de truffe et de poudre de charbon, il aide à rafraîchir et revitaliser l’apparence de la peau, tandis que la poudre d’albumine contribue à affiner l’apparence des pores. Ce masque procure une sensation revitalisante et raffermissante, laissant la peau visiblement plus lisse et plus uniforme après utilisation.', NULL, NULL, 'skin1004-mummy-pack', 'https://korean-skincare.fr/products/skin1004-mummy-pack', 'https://aurore-cdn.b-cdn.net/products/skin1004-mummy-pack.webp', 'Verse l''activateur dans la poudre et mélange-les à l''aide du pinceau inclus. Applique une couche uniforme sur ton visage en effectuant des mouvements vers le haut et vers l''extérieur. Évite le contour des yeux et des lèvres. Laisse agir pendant 10 à 15 minutes et rince à l''eau tiède.', 2149, '2026-05-07 17:37:39.542296+00', '2026-06-14 15:14:07.137+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
