INSERT INTO public.products VALUES ('019de0ab-6515-7304-8d4f-b2ac48d1ef8d', '__OWNER_ID__', 'Uriage Xemose C8+ Huile lavante anti-grattage 1L', 'Uriage', 'body-wash', 'jar', 'AQUA (WATER, Aqua, Sorbitol, Glycerin, Sodium Laureth Sulfate, Coco-Glucoside, SODIUM COCOAMPHOACETATE, SODIUM METHYL COCOYL TAURATE, Caprylyl Glycol, Citric Acid, Sodium Benzoate, Glyceryl Oleate, POLYQUATERNIUM-10, PEG-75 SHEA BUTTER GLYCERIDES, SAFFLOWER OIL/PALM OIL AMINOPROPANEDIOL ESTERS, POLYGLYCERYL-10 STEARATE, Tocopherol, TRIETHYL CITRATE, POLYGLYCERYL-6 BEHENATE, HYDROGENATED VEGETABLE GLYCERIDES CITRATE, BEHENIC ACID, Ceramide NP, Cetearyl Alcohol, Cholesterol, Glyceryl Stearate, Lactic Acid, Ceramide NS, Ceramide EOP, Ceramide AP, SODIUM CETEARYL SULFATE', '', 1, 'l', 'uriage-xemose-c8-huile-lavante-anti-grattage-1l-253345', 'https://www.atida.fr/uriage-xemose-huile-nettoyante-apaisante-1l.html', 'https://aurore-cdn.b-cdn.net/products/uriage-xemose-c8-huile-lavante-anti-grattage-1l-253345.webp', '', 1849, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.138+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-460e-7de8-b726-d9187921601c', '__OWNER_ID__', 'Deep Vita A Retinol Serum', 'Medicube', 'serum', 'dropper', 'Aqua, Dipropylene Glycol, Butylene Glycol, Glycerin, Propanediol, 1,2-Hexanediol, Niacinamide, Coco-Caprylate/Caprate, Squalane, Polyglyceryl-3 Distearate, Dimethyl Isosorbide, Pentylene Glycol, Panthenol, 4-T-Butylcyclohexanol, Parfum, Hydrogenated Lecithin, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Sucrose Palmitate, Caprylic/Capric Triglyceride, Hydroxypinacolone Retinoate, Diethylhexyl Syringylidenemalonate, Tromethamine, Ethylhexylglycerin, Glyceryl Stearate Citrate, Allantoin, Biosaccharide Gum-1, Dipotassium Glycyrrhizate, Xanthan Gum, Macadamia Integrifolia Seed Oil, Olea Europaea Fruit Oil, Simmondsia Chinensis Seed Oil, Vitis Vinifera Seed Oil, Adenosine, Macadamia Ternifolia Seed Oil, Retinal, Sodium Hyaluronate, Disodium EDTA, Retinol, Bakuchiol, Retinyl Palmitate, Brassica Campestris (Rapeseed) Sterols, Linoleic Acid, Cholesterol, Polyglyceryl-10 Laurate, Ceramide NP, PPG-13-Decyltetradeceth-24, Retinyl Linoleate, Phytosteryl/​Behenyl/​Octyldodecyl Lauroyl Glutamate, Beta-Glucan, Aluminum/​Magnesium Hydroxide Stearate, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Potassium Cetyl Phosphate, Polyglyceryl-3 Methylglucose Distearate, Silica, Isopropyl Lauroyl Sarcosinate, Tocopherol, Hydrolyzed Collagen, Retinyl Retinoate, Chitosan, Centella Asiatica Extract/​Centella Asiatica Leaf Extract, Centella Asiatica Root Extract, Tris(Tetramethy Lhydroxypiperidinol) Citrate, Benzotriazolyl Dodecyl P-Cresol', 'Le Deep Vita A Retinol Serum est une solution anti-âge puissante conçue pour améliorer la texture de la peau, réduire les ridules et favoriser un teint radieux et jeune. Enrichi en rétinol stabilisé et en vitamines nourrissantes, il soutient le renouvellement cutané tout en minimisant les irritations, le rendant adapté même aux peaux sensibles. Léger et rapidement absorbé, il laisse la peau lisse et revitalisée. Recommandé pour : Hyperpigmentation, tous types de peaux.', 30, 'ml', 'medicube-deep-vita-a-retinol-serum', 'https://korean-skincare.fr/products/medicube-deep-vita-a-retinol-serum', 'https://aurore-cdn.b-cdn.net/products/medicube-deep-vita-a-retinol-serum.webp', 'Applique 2 à 3 gouttes sur une peau propre et sèche le soir. Étale doucement sur tout le visage, en évitant le contour des yeux et des lèvres. Poursuis avec ta crème hydratante. Commence par 2 à 3 soirs par semaine, en augmentant progressivement la fréquence. Utilise toujours un écran solaire le jour, car le rétinol augmente la sensibilité au soleil.', 2495, '2026-05-07 17:37:40.878729+00', '2026-06-14 15:14:07.139+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6515-79c1-b393-22ea9ed85ad4', '__OWNER_ID__', 'P20 Urban Shield Crème Solaire IP50+', 'Riemann P20', 'sunscreen', 'pump', 'Aqua, NEOPENTYL GLYCOL DIHEPTANOATE, Ethylhexyl Methoxycinnamate, Homosalate, Ethylhexyl Salicylate, Diethylamino Hydroxybenzoyl Hexyl Benzoate, GLYCERYL STEARATE CITRATE, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, ISOPENTYLDIOL, Methyl Methacrylate Crosspolymer, SYNTHETIC FLUORPHLOGOPITE, TAPIOCA STARCH/TRITICUM VULGARE (WHEAT) STARCH, POTASSIUM CETYL PHOSPHATE, Cetyl Alcohol, Propanediol, Caprylyl Glycol, SODIUM POLYACRYLATE, Benzyl Alcohol, Pentylene Glycol, POLYACRYLATE CROSSPOLYMER-11, SPINACIA OLERACEA LEAF EXTRACT, Carnosine, ARISTOTELIA CHILENSIS FRUIT EXTRACT, Ethylhexylglycerin, TARAXACUM OFFICINALE RHIZOME/ROOT EXTRACT, Disodium EDTA, Caprylhydroxamic Acid, Glycerin, Sodium Hydroxide, TEPHROSIA PURPUREA SEED EXTRACT, Tin Oxide, BHT, Sodium Benzoate, Potassium Sorbate, AMMONIUM C6-16 PERFLUOROALKYLETHYL PHOSPHATE, Titanium Dioxide, CI 77491', 'Crème SPF50+ anti-pollution urbaine. Protection large spectre + antioxydants, texture légère.', 50, 'g', 'riemann-p20-urban-shield-creme-solaire-ip50-plus', 'https://www.p20.com', NULL, 'Filtres chimiques + extraits végétaux (épinard, myrtille, pissenlit). Idéal ville/exposition quotidienne.', 2569, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.145+00', 'solaire', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4627-7e9d-9ec2-6e3843fe063f', '__OWNER_ID__', 'PDRN Pink Hyaluronic Moisturizing Cream', 'Medicube', 'moisturizer', 'jar', 'Aqua, Disodium EDTA, Betaine, Niacinamide, Adenosine, Citric Acid, Panthenol, Glycereth-26, Glycerin, Glyceryl Acrylate/​Acrylic Acid Copolymer, Butylene Glycol, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Sorbitan Isostearate, Cetearyl Olivate, Sorbitan Olivate, Caprylic/Capric Triglyceride, Limnanthes Alba Seed Oil, Hydrogenated Polydecene, Isononyl Isononanoate, Hydrogenated Lecithin, Cetearyl Alcohol, Stearic Acid, Ceramide EOP, Ceramide NS, Ceramide NP, Ceramide AS, Ceramide AP, Phytosphingosine, Cholesterol, Cyclopentasiloxane, Sodium Dna, Ethylhexyl Olivate, Sodium Acrylates Copolymer, Polyglyceryl-4 Oleate, 1,2-Hexanediol, Copper Tripeptide-1, Acetyl Hexapeptide-8, Palmitoyl Pentapeptide-4, Palmitoyl Tripeptide-1, Palmitoyl Tetrapeptide-7, Sodium Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Sodium Acetylated Hyaluronate, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hydrolyzed Sodium Hyaluronate, Potassium Hyaluronate, Fucus Vesiculosus Extract, Prunella Vulgaris Extract, Momordica Charantia Fruit Extract, Hibiscus Esculentus Fruit Extract, Morinda Citrifolia Fruit Extract, Centella Asiatica Leaf Extract, Ethylhexylglycerin, Parfum, Cyanocobalamin, Sodium Polyacryloyldimethyl Taurate', 'La PDRN Pink Hyaluronic Moisturizing Cream Medicube est une crème hydratante intensément nourrissante et régénérante conçue pour repulper, lisser et restaurer l’hydratation des peaux sèches ou fatiguées. Formulée avec du PDRN (Polydeoxyribonucleotide) pour soutenir la régénération de la peau et 8 types d’acide hyaluronique, cette crème recharge profondément l’hydratation à chaque couche de la peau tout en aidant à améliorer l’élasticité et affiner la texture. Sa texture soyeuse et onctueuse fond sur la peau sans effet gras, laissant la peau douce, souple et lumineuse. Parfaite pour tous types de peaux, en particulier les peaux déshydratées, ternes ou matures, cette crème offre une hydratation longue durée tout en renforçant la barrière cutanée. Une utilisation régulière de la PDRN Pink Hyaluronic Moisturizing Cream Medicube aide à réduire l’apparence des ridules et donne à la peau un aspect plus lisse, rebondi et éclatant. Recommandé pour : Tous types de peaux.', 50, 'ml', 'medicube-pdrn-pink-hyaluronic-moisturizing-cream', 'https://korean-skincare.fr/products/medicube-pdrn-pink-hyaluronic-moisturizing-cream', 'https://aurore-cdn.b-cdn.net/products/medicube-pdrn-pink-hyaluronic-moisturizing-cream.webp', 'Applique une quantité modérée sur ton visage, en évitant les zones de la bouche et des yeux. Tapote délicatement pour favoriser l’absorption.', 1995, '2026-05-07 17:37:40.903712+00', '2026-06-14 15:14:07.14+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
