INSERT INTO public.products VALUES ('019de0ab-6515-7912-889b-82b5265cc49c', '__OWNER_ID__', 'P20 Sensitive Face Crème Solaire IP50+', 'Riemann P20', 'sunscreen', 'pump', 'Aqua, Diethylamino Hydroxybenzoyl Hexyl Benzoate, DIBUTYL ADIPATE, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Dicaprylyl Carbonate, Tris-Biphenyl Triazine, Glycerin, PHENOXYETHYL CAPRYLATE, CAPRYLYL CAPRYLATE/CAPRATE, CANOLA OIL, Silica, POTASSIUM CETYL PHOSPHATE, Panthenol, Trehalose, Cetearyl Alcohol, Ethylhexyl Triazone, VP/EICOSENE COPOLYMER, Phenoxyethanol, Squalane, Glyceryl Stearate, SODIUM OLIVOYL GLUTAMATE, SORBITAN CAPRYLATE, Tocopheryl Acetate, Decyl Glucoside, Benzoic Acid, Caprylyl Glycol, Propanediol, Acacia Senegal Gum, XANTHAN GUM, Sodium Phytate, TOCOPHEROLS, Dehydroacetic Acid, Ascorbyl Palmitate, Ethylhexylglycerin, Butylene Glycol, DISODIUM PHOSPHATE, Citric Acid, Biosaccharide Gum-1, Potassium Sorbate, Sodium Benzoate, Glyceryl Caprylate, SODIUM LEVULINATE, SODIUM ANISATE, Sodium Hydroxide', 'Crème SPF50+ sensitive pour visage. Protection très haute, résistante à l''eau, sans parfum.', 50, 'g', 'riemann-p20-sensitive-face-creme-solaire-ip50-plus', 'https://www.p20.com', NULL, 'Filtres chimiques + panthénol + tréhalose. Texture crème légère, peaux sensibles/irritées.', 2549, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.144+00', 'solaire', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6515-7a61-ad0f-387ada3d10b1', '__OWNER_ID__', 'P20 Sensitive Skin Crème Solaire IP50+', 'Riemann P20', 'sunscreen', 'pump', 'Aqua, Diethylamino Hydroxybenzoyl Hexyl Benzoate, DIBUTYL ADIPATE, Dicaprylyl Carbonate, Ethylhexyl Triazone, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Glycerin, PHENOXYETHYL CAPRYLATE, Dicaprylyl Ether, Tris-Biphenyl Triazine, POTASSIUM CETYL PHOSPHATE, Cetearyl Alcohol, Silica, VP/ACRYLATES/LAURYL METHACRYLATE COPOLYMER, Phenoxyethanol, Diethylhexyl Butamido Triazone, SORBITAN CAPRYLATE, Glyceryl Stearate, SODIUM OLIVOYL GLUTAMATE, CANOLA OIL, ACRYLATES/C12-22 ALKYL METHACRYLATE COPOLYMER, Benzoic Acid, Decyl Glucoside, Propanediol, Acacia Senegal Gum, XANTHAN GUM, Caprylyl Glycol, Sodium Phytate, Pentylene Glycol, Dehydroacetic Acid, Sodium Hydroxide, Ethylhexylglycerin, DISODIUM PHOSPHATE, Butylene Glycol, Sodium Benzoate, Potassium Sorbate, Tocopherol, Citric Acid', 'Crème SPF50+ sensitive corps/visage. Très haute protection, résistante eau, sans parfum.', 200, 'ml', 'riemann-p20-sensitive-skin-creme-solaire-ip50-plus', 'https://www.p20.com', NULL, 'Filtres chimiques + panthénol + squalane. Texture crème légère, peaux très sensibles/irritées.', 4145, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.146+00', 'solaire', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-7225-a1b8-2f1c6e94b2c9', '__OWNER_ID__', 'Bakuchiol Firming Cream', 'Theramid', 'moisturizer', 'jar', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, TRIBEHENIN PEG-20 ESTERS, Dimethicone, Squalane, Propanediol, COCO-CAPRYLATE, C10-18 TRIGLYCERIDES, TRICAPRYLIN, Bakuchiol, Cetearyl Alcohol, Ceramide NS, Hydrolyzed Hyaluronic Acid, Palmitoyl Tripeptide-1, Palmitoyl Tetrapeptide-7, CENTELLA ASIATICA CALLUS CONDITIONED MEDIA, Lactococcus Ferment Lysate, DIMETHICONE/VINYL DIMETHICONE CROSSPOLYMER, XANTHAN GUM, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Butylene Glycol, Carbomer, Sodium Lactate, Lactic Acid, Polysorbate 20, Tocopherol, Caprylyl Glycol, Citric Acid, Sodium Chloride, Sodium Benzoate, Tocopheryl Acetate, Ethylhexylglycerin, Phenoxyethanol', 'Crème visage raffermissante avec 1% de bakuchiol, l''alternative végétale et anti-âge au rétinol. Réduit visiblement les rides et ridules, améliore le teint et la texture sans irritation ni sensibilité.', 50, 'ml', 'theramid-bakuchiol-firming-cream', 'https://nichebeautylab.com', 'https://aurore-cdn.b-cdn.net/products/theramid-bakuchiol-firming-cream.webp', 'Convient à tous les types de peau, même les sensibles. Utilisation jour et nuit. pH: 5-5.3. Complexe de peptides anti-âge pour combattre la perte de fermeté.', 1695, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.147+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-72c1-984a-3127812aceb2', '__OWNER_ID__', 'Time Reverse Beauty Sleep Mask', 'Theramid', 'mask', 'jar', 'Aqua, Glycerin, Niacinamide, Propanediol, COMPLEXE ACE, Hyaluronic Acid, Retinol, Butylene Glycol, Cetyl Alcohol, Cetearyl Alcohol, Sodium PCA, XANTHAN GUM, Carbomer, Dimethicone, Sodium Benzoate, Tocopherol, Caprylyl Glycol, Ethylhexylglycerin, Phenoxyethanol', 'Masque de nuit anti-âge slow-aging sans rinçage. Recharge la peau avec des antioxydants et combat les rides pendant le sommeil. Format pratique et efficace pour oublier vos rides en dormant.', 75, 'ml', 'theramid-time-reverse-beauty-sleep-mask', 'https://nichebeautylab.com', 'https://aurore-cdn.b-cdn.net/products/theramid-time-reverse-beauty-sleep-mask.webp', 'Usage exclusif le soir, sans rinçage. pH: 5.5-6. Contient 5% de niacinamide, complexe ACE (3%) et acide hyaluronique encapsulé (1%). Retinol 0,2% pour action anti-âge renforcée.', 1695, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.148+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-735f-a823-d1a209923504', '__OWNER_ID__', 'Retinal Age Reverse Cream', 'Theramid', 'moisturizer', 'jar', 'Aqua, Glycerin, C10-18 TRIGLYCERIDES, Coco-Caprylate/Caprate, COCO-CAPRYLATE, Propanediol, Cetyl Alcohol, Oryza Sativa Starch, Bakuchiol, Glyceryl Stearate, Retinal, Hyaluronic Acid, PALMITOYL TRIPEPTIDE-38, Palmitoyl Tripeptide-1, Palmitoyl Tetrapeptide-7, Mannitol, XANTHAN GUM, PEG-75 STEARATE, HYDROXYPROPYL STARCH PHOSPHATE, Lecithin, CETETH-20, STEARETH-20, Butylene Glycol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Cholesterol, Hydrogenated Lecithin, Decyl Glucoside, Carbomer, Citric Acid, Sodium Lactate, Hydroxypropyl Cyclodextrin, Polysorbate 20, Tocopherol, Caprylyl Glycol, Sodium Chloride, Sodium Benzoate, Potassium Sorbate, Ethylhexylglycerin, Phenoxyethanol', 'Crème anti-âge innovante avec rétinal pur encapsulé, la forme la plus puissante de vitamine A. Déclenche la régénération cellulaire et la production de collagène pour éliminer rides et signes visibles du vieillissement.', 50, 'ml', 'theramid-retinal-age-reverse-cream', 'https://nichebeautylab.com', 'https://aurore-cdn.b-cdn.net/products/theramid-retinal-age-reverse-cream.webp', 'Contient 4 actifs anti-âge: rétinal pur (0,03%), complexe acide hyaluronique (3%), peptides (2%), bakuchiol (1%). pH: 5.3-5.8. Résultats visibles dès les premières applications.', 1895, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.148+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-74c3-9d07-7c813d0fba88', '__OWNER_ID__', 'Proteo Repair Cream', 'Theramid', 'moisturizer', 'jar', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, Butyrospermum Parkii Butter, NEOPENTYL GLYCOL DIHEPTANOATE, Propanediol, Cetyl Alcohol, Glyceryl Stearate, Limnanthes Alba Seed Oil, HYDROGENATED SOYBEAN OIL, Dimethicone, Carnosine, Cetearyl Alcohol, COLLAGEN AMINO ACIDS, SOLUBLE PROTEOGLYCAN, ARGININE/LYSINE POLYPEPTIDE, Betaine, NICOTIANA BENTHAMIANA HEXAPEPTIDE-40 SH-POLYPEPTIDE-47, PCA, SERINE, ALANINE, GLYCINE, Glutamic Acid, LYSINE HCL, THREONINE, ARGININE, PROLINE, Tocopherol, Sodium PCA, Camellia Sinensis Leaf Water, ANTHEMIS NOBILIS FLOWER WATER, Butylene Glycol, Pentylene Glycol, Caprylyl Glycol, Microcrystalline Wax, Carbomer, Glycine Soja Oil, PEG-75 STEARATE, CETETH-20, STEARETH-20, Squalene, Beta-Sitosterol, Citric Acid, Disodium EDTA, Sodium Lactate, Sodium Benzoate, Ethylhexylglycerin, Phenoxyethanol', 'Crème anti-âge intensive raffermissante enrichie en fragments de collagène hautement pénétrants. Hydrate, raffermit et revitalise la peau en restaurant fermeté et élasticité tout en réduisant rides et relâchement cutané.', 60, 'ml', 'theramid-proteo-repair-cream', 'https://nichebeautylab.com', NULL, 'Fragments de collagène plus petits que le collagène conventionnel pour meilleure pénétration. Contient carnosine (peptide anti-glycation), acides aminés et protéoglycanes. pH: 5.5-6. Texture riche à absorption rapide.', 1695, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.149+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-7643-9c98-4b561bdaeb5f', '__OWNER_ID__', 'Pure Glycerin Face Serum', 'Theramid', 'serum', 'bottle', 'Aqua, Glycerin, Propanediol, Dimethicone, Betaine, PROLINE, THREONINE, GLYCINE, ARGININE, SERINE, ALANINE, LYSINE HCL, PCA, Sodium PCA, Glutamic Acid, DIMETHICONE/VINYL DIMETHICONE CROSSPOLYMER, Sodium Lactate, Sodium Phytate, Carbomer, HYDROGENATED POLYDECENE, TRIDECETH-6, SODIUM POLYACRYLATE, Tocopherol, Ethylhexylglycerin, Phenoxyethanol', 'Sérum hydratant pour le visage idéal pour les peaux sèches et déshydratées. Formulé avec 15% de glycérine, hydrate et nourrit la peau en profondeur tout en maintenant les niveaux d''hydratation nécessaires.', 50, 'ml', 'theramid-pure-glycerin-face-serum', 'https://nichebeautylab.com', NULL, 'Glycérine empêche la perte d''eau transépidermique. Enrichi de complexe d''acides aminés pour stimuler production de collagène et lisser rides. pH: 5-5.5. Maintient peau hydratée, souple et ferme.', 1495, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.149+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-7dc1-bbc5-5bb24fc8dc7e', '__OWNER_ID__', 'Flawless Brightly 10% Azelaic Acid Serum', 'Sonya Driver', 'serum', 'pump', 'Aqua, Azelaic Acid, Caprylic/Capric Triglyceride, Niacinamide, Dicaprylyl Carbonate, Ascorbyl Glucoside, Cetearyl Alcohol, Glycerin, Glyceryl Stearate SE, CETEARYL OLIVATE, Bakuchiol, Sorbitan Olivate, Benzyl Alcohol, XANTHAN GUM, Phenoxyethanol, Sodium Hydroxide, Disodium EDTA, Dehydroacetic Acid', 'Sérum 10% azélaïque + niacinamide + vitamine C + bakuchiol. Éclaircissant tout-en-un pour teint terne.', 30, 'ml', 'dr-sam-flawless-brightly-10-azelaic-acid-serum', 'https://drsambunting.com', NULL, 'Texture émulsion confortable, vegan/cruelty-free. Redondance niacinamide/vit C dans une routine, prix élevé pour formule basique.', 6000, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.149+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-7e69-81ef-c398eab3fc8c', '__OWNER_ID__', 'Azelaic Acid Balancing Serum', 'Q+A', 'serum', 'bottle', 'Aqua, Aloe Barbadensis Leaf Juice, Propylene Glycol, Azelaic Acid, Betaine, Zinc PCA, Biosaccharide Gum-1, Glycerin, TRITICUM SPELTA SEED EXTRACT, TRITICUM TURANICUM SEED EXTRACT, ERAGROSTIS TEF SEED EXTRACT, CHENOPODIUM QUINOA SEED EXTRACT, XANTHAN GUM, SODIUM LEVULINATE, Glyceryl Caprylate, SODIUM ANISATE, Caprylyl Glycol, SODIUM GLUCONATE, Benzyl Alcohol, Dehydroacetic Acid, Sodium Benzoate, Phenoxyethanol, Sodium Hydroxide, Citric Acid', 'Sérum équilibrant à l''acide azélaïque enrichi en Zinc PCA pour minimiser les pores et en antioxydants pour une peau plus lisse et fraîche. Idéal pour les peaux à tendance acnéique.', 30, 'ml', 'qa-azelaic-acid-balancing-serum', 'https://www.qandskincare.com', NULL, 'Formule avec jus d''aloe vera et extraits de graines de céréales (épeautre, khorasan, teff, quinoa) pour un soin nourrissant et antioxydant.', 900, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.15+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-7f9f-9fe7-c01817ae10b3', '__OWNER_ID__', 'AZ Azelaic Acid 10 Serum', 'Cos De BAHA', 'serum', 'bottle', 'Aloe Barbadensis Leaf Extract, Propylene Glycol, Azelaic Acid, Polysorbate 20, 1,2-Hexanediol, Propanediol, Panthenol, Niacinamide, Sodium Hyaluronate, Camellia Sinensis Leaf Extract, MOMORDICA CHARANTIA FRUIT EXTRACT, Sambucus Nigra Flower Extract, LEONTOPODIUM ALPINUM EXTRACT', 'Sérum à l''acide azélaïque 10% avec base à l''aloe vera. Estompe les cicatrices d''acné, améliore l''hyperpigmentation et traite la rosacée. Enrichi en niacinamide et extraits botaniques certifiés bio pour un teint plus lumineux et unifié.', 30, 'ml', 'cos-de-baha-azelaic-acid-10-serum', 'https://www.yesstyle.com/fr/cos-de-baha', 'https://aurore-cdn.b-cdn.net/products/cos-de-baha-azelaic-acid-10-serum.webp', 'Base à l''extrait de feuille d''Aloe Barbadensis en tête de liste INCI. Extraits bio certifiés : thé vert, Momordica Charantia, fleurs de sureau, Leontopodium Alpinum (edelweiss).', 572, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.15+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6517-7877-9dc2-4a68776d8a06', '__OWNER_ID__', 'Hydrance BOOST Sérum', 'Avène', 'serum', 'dropper', 'Aqua, Propanediol, Glycerin, Pentylene Glycol, DIGLYCERIN, 1,2-Hexanediol, Niacinamide, Sodium Hyaluronate, Betaine, Citric Acid, Parfum, PCA, Polyglyceryl-4 Caprate, SCLEROTIUM GUM, Sodium Citrate, Sodium Hydroxide, Aqua', 'Véritable booster intense d’hydratation du visage qui rétablit l’équilibre des peaux sensibles déshydratées pendant 48H.', 30, 'ml', 'avene-hydrance-boost-serum-hydratant', 'https://www.eau-thermale-avene.fr', 'https://aurore-cdn.b-cdn.net/products/avene-hydrance-boost-serum-hydratant.webp', '96% d’ingrédients d’origine naturelle. Enrichi en Acide Hyaluronique et Vitamine B3 (Niacinamide). Texture gel d’eau ultra-légère et fraîche.', 2340, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.15+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6517-702d-a7c4-2f9c14c105d1', '__OWNER_ID__', 'AZ20 Cream', 'Cos De BAHA', 'moisturizer', 'jar', 'Aqua, Azelaic Acid, Propylene Glycol, Sodium Hydroxide, Caprylic/Capric Triglyceride, 1,2-Hexanediol, Cetearyl Alcohol, Glyceryl Stearate, Dimethicone, CETEARYL OLIVATE, Sorbitan Olivate, Betaine, DIMETHYL SULFONE, Panthenol, Allantoin, Dipotassium Glycyrrhizate, Centella Asiatica Extract, Madecassoside, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Tocopherol, Ceramide NP, Polysorbate 60, Camellia Sinensis Leaf Extract, Sambucus Nigra Flower Extract, MOMORDICA CHARANTIA FRUIT EXTRACT, LEONTOPODIUM ALPINUM EXTRACT', 'Crème émulsion à l''acide azélaïque 20% enrichie en vitamine B5, acide hyaluronique et céramide NP. Illumine le teint, hydrate et apaise. Enrichie en madecassoside et extrait de centella asiatica.', 50, 'ml', 'cos-de-baha-az20-cream', 'https://www.yesstyle.com/fr/cos-de-baha', NULL, 'Base de la formule : eau + acide azélaïque haut sur liste INCI. Contient Dimethyl Sulfone (MSM), actif anti-inflammatoire. Extraits bio : thé vert, sureau, Momordica Charantia, edelweiss.', 1013, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.151+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
