INSERT INTO public.products VALUES ('019e0384-4760-73d3-8197-a7c79f0ce3d4', '__OWNER_ID__', 'Natural Bean Lip Mask Balm', 'MIXSOON', 'lip-care', 'tube', 'Hydrogenated Polyisobutene, Polyisobutene, Bis-Behenyl/​Isostearyl/​Phytosteryl Dimer Dilinoleyl Dimer Dilinoleate, Diisostearyl Malate, Synthetic Wax, Ethylene/​Propylene/​Styrene Copolymer, Sucrose Tetrastearate Triacetate, Euphorbia Cerifera Cera, Tribehenin, Trihydroxystearin, Butyrospermum Parkii Butter, Polyglyceryl-2 Diisostearate, Polyglyceryl-2 Triisostearate, Dehydroacetic Acid, Simmondsia Chinensis Seed Oil, Butylene/​Ethylene/​Styrene Copolymer, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Water/​Aqua, Propanediol, Glycerin, Lactobacillus/​Pear Juice Ferment Filtrate, Lactobacillus/​Punica Granatum Fruit Ferment Extract, Lactobacillus/​Soybean Ferment Extract, Saccharomyces/​Barley Seed Ferment Filtrate', 'Prends soin de tes lèvres avec le Natural Bean Lip Mask Balm MIXSOON, un soin 2-en-1 qui combine la nutrition intense d’un masque de nuit avec l’hydratation et la brillance d’un baume quotidien. Infusé de beurre de karité hydratant, d’huile de graines de jojoba et d’un mélange unique d’extraits végétaux fermentés de soja, d’orge, de grenade et de poire, il hydrate en profondeur, adoucit les lèvres sèches et gercées et leur apporte un éclat naturel avec une finition lisse et brillante. Testée dermatologiquement et sans parfums ni colorants artificiels, cette formule douce convient même aux lèvres sensibles. Que tu l’utilises tout au long de la journée ou comme traitement de nuit, elle retient l’hydratation et laisse tes lèvres souples, protégées et visiblement revitalisées. Recommandé pour : Lèvres sèches et gercées.', 11, 'g', 'mixsoon-natural-bean-lip-mask-balm', 'https://korean-skincare.fr/products/mixsoon-natural-bean-lip-mask-balm', 'https://aurore-cdn.b-cdn.net/products/mixsoon-natural-bean-lip-mask-balm.webp', 'Applique une quantité appropriée sur tes lèvres dès qu’elles se sentent sèches.', 1266, '2026-05-07 17:37:41.216163+00', '2026-06-14 15:14:07.156+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
