INSERT INTO public.products VALUES ('019e0384-3d7c-75cb-ab4f-05f7a98d9af9', '__OWNER_ID__', 'All Around Safe Block Soft Finish Sun Milk SPF 50+ PA+++', 'MISSHA', 'moisturizer', 'jar', 'Cyclopentasiloxane, Silica, Dipropylene Glycol, Ethylhexyl Salicylate, Caprylyl Methicone, Titanium Dioxide, C12-15 Alkyl Benzoate, Acrylates/​Dimethicone Copolymer, Limonia Acidissima Extract, Rosa Davurica Bud Extract, Abronia Villosa Leaf Extract, Psidium Guajava Leaf Extract, Biosaccharide Gum-4, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Magnesium Sulfate, Dimethicone/​Vinyl Dimethicone Crosspolymer, Dimethicone, Quaternium-18 Bentonite, Aluminum Hydroxide, Stearic Acid, Hydrogen Dimethicone, Aqua, Sodium Benzoate, Tocopheryl Acetate, Potassium Sorbate, Polyhydroxystearic Acid, Isopropyl Myristate, Isostearic Acid, Lecithin, Ethylhexyl Palmitate, Phenoxyethanol, Parfum, Helichrysum Arenarium Extract, VP/​Hexadecene Copolymer, Helichrysum Italicum (Everlasting) Extract, Cinchona Succirubra (Quinine) Bark Extract, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Alcohol, Caprylyl Glycol, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Ethylhexyl Methoxycinnamate, Isopropyl Palmitate, Aloe Barbadensis Leaf Extract, Ethylhexyl Methoxycinnamate, Zinc Oxide, Alcohol Denat, Rhodiola Rosea Root Extract, Isopropyl Palmitate, Lauryl PEG-10 Tris[Trimethylsiloxy]Silylethyl Dimethicone, Glycerin, Polyglyceryl-3 Polyricinoleate, Polyglyceryl-3 Polyricinoleate, Benzyl Salicylate, Disodium EDTA, CI 77492, Aloe Barbadensis Leaf Extract, CI 77491, Red Iron Oxide (Ci 77491), Silica Dimethyl Silylate, Hexyl Cinnamal, VP/​Hexadecene Copolymer, Lauryl PEG-10 Tris(Trimethylsiloxy)silylethyl Dimethicone, Silica Dimethyl Silylate, Butylene Glycol, Yellow Iron Oxide (Ci 77492), Rhodiola Rosea (Rhodiola Rosea) Root Extract, Disodium EDTA, Zinc Oxide, Cinchona Succirubra Bark Extract', 'L''All Around Safe Block Soft Finish Sun Milk Missha est un écran anti-UV double protection, imperméable à l''eau et à la sueur, qui illumine et unifie le teint tout au long de la journée. Il laisse un fini lisse et non gras.', 70, 'ml', 'missha-all-around-safe-block-soft-finish-sun-milk', 'https://korean-skincare.fr/products/missha-all-around-safe-block-soft-finish-sun-milk', 'https://aurore-cdn.b-cdn.net/products/missha-all-around-safe-block-soft-finish-sun-milk.webp', 'Agite le produit 4 à 5 fois avant de l''utiliser. Applique la quantité de crème appropriée sur le visage lors de la dernière étape de ta routine beauté. Tapote légèrement jusqu''à absorption complète. Applique uniformément sur le cou, les bras et les jambes et les zones exposées au soleil. Renouvelle l''application si nécessaire en cas d''exposition prolongée au soleil.', 1696, '2026-05-07 17:37:38.684273+00', '2026-06-14 15:14:07.178+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
