INSERT INTO public.products VALUES ('019de0ab-6524-75fb-9633-a60015891ab6', '__OWNER_ID__', 'Crème solaire teintée SPF50', 'Laboratoires de Biarritz', 'sunscreen', 'tube', 'Caprylic/Capric Triglyceride, Zinc Oxide, COCONUT ALKANES, Titanium Dioxide, Aqua, ORYZA SATIVA POWDER, Polyglyceryl-2 Dipolyhydroxystearate, PRUNUS DOMESTICA SEED OIL, POLYGLYCERYL-3 DIISOSTEARATE, Glycerin, Sorbitan Olivate, CI 77492, Octyldodecanol, Alumina, Coco-Caprylate/Caprate, Stearic Acid, Magnesium Sulfate, GELIDIUM SESQUIPEDALE EXTRACT, Aloe Barbadensis Leaf Juice, GLYCERYL CAPRATE, Propanediol, CI 77491, Tocopherol, CI 77499, Polyglyceryl-4 Caprate, Jojoba Esters, Trihydroxystearin', 'Crème solaire teintée bio SPF50 — soin perfecteur haute performance. Protège des UVA/UVB et lumière bleue (Alga-Gorria® + filtres minéraux). Prévient les taches pigmentaires, unifie le teint, fini mat naturel.', 50, 'ml', 'lab-biarritz-creme-solaire-teinte-spf50', 'https://www.laboratoires-biarritz.com', 'https://aurore-cdn.b-cdn.net/products/lab-biarritz-creme-solaire-teinte-spf50.webp', '100% naturel. 20,9% bio. Certifiée bio ECOCERT. Texture légère, sans parfum, non comédogène, résistante à l''eau. Pour peaux claires, fragiles et sensibles. Femme enceinte/allaitante. Disponible en 3 teintes (Ivoire, Beige, Dorée) — mixables.', 2400, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.184+00', 'solaire', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
