INSERT INTO public.products VALUES ('019de0ab-6516-73f6-906c-3eb041e90515', '__OWNER_ID__', 'Niacinamide Glow Cream', 'Theramid', 'moisturizer', 'jar', 'Aqua, Glycerin, Niacinamide, Propanediol, TRIHEPTANOIN, Dimethicone, Betaine, ETHYL MACADAMIATE, ISOSORBIDE DICAPRYLATE, Sodium PCA, Ceramide NS, PCA, Lactococcus Ferment Lysate, Lysine, SERINE, ALANINE, GLYCINE, LYSINE HCL, THREONINE, ARGININE, PROLINE, Glutamic Acid, Gluconolactone, Palmitoyl Tripeptide-1, Palmitoyl Tetrapeptide-7, MAGNESIUM CHLORIDE, Potassium Chloride, MANGANESE CHLORIDE, ALUMINUM CHLORIDE, COPPER SULFATE, Tocopherol, Phenethyl Alcohol, Caprylyl Glycol, ZINC CHLORIDE, MALIC ACID, CALCIUM GLUCONATE, SODIUM POLYACRYLATE, Carbomer, DIMETHICONE/VINYL DIMETHICONE CROSSPOLYMER, HYDROGENATED POLYDECENE, Butylene Glycol, Sodium Lactate, TRIDECETH-6, Sodium Phytate, Lactic Acid, Sodium Chloride, Polysorbate 20, Sodium Benzoate, Ethylhexylglycerin, Phenoxyethanol', 'Gel-crème légère et puissante formulée avec 5% de niacinamide pour hydrater, illuminer et uniformiser le teint. Restaure l''éclat, réduit visiblement les imperfections et améliore l''aspect général du visage dès la première application.', 50, 'ml', 'theramid-niacinamide-glow-cream', 'https://nichebeautylab.com', 'https://aurore-cdn.b-cdn.net/products/theramid-niacinamide-glow-cream.webp', 'Texture gel-crème légère, idéale tous types de peaux. Complétée par complexe d''acides aminés et céramides pour renforcer la barrière cutanée. pH: 5-5.3. Usage quotidien matin et soir.', 1595, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.441+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
