INSERT INTO public.products VALUES ('019de0ab-6516-7787-a130-2aff38039dd5', '__OWNER_ID__', 'Ceramide Repair Moisturizer', 'Theramid', 'serum', 'bottle', 'Aqua, Glycerin, Propanediol, Caprylic/Capric Triglyceride, Polysorbate 80, Prunus Amygdalus Dulcis Oil, Hyaluronic Acid, Ceramide NP, Ceramide NS, Ceramide EOP, Ceramide NS, Ceramide AS, Ceramide AP, Ectoin, Madecassoside, Ethylhexylglycerin, Helianthus Annuus Seed Oil, Squalane, Hydrogenated Lecithin, Hydrogenated Lecithin, Lecithin, Mannitol, SUCROSE DISTEARATE, Cholesterol, XANTHAN GUM, Carbomer, Cetearyl Alcohol, Tocopherol, Glyceryl Stearate, Decyl Glucoside, Pentylene Glycol, Propylene Glycol, Polysorbate 20, SORBITAN OLEATE, Sodium Chloride, Triethanolamine, Sodium Benzoate, Potassium Sorbate, Phenoxyethanol', 'Sérum ultra-hydratant avec céramides d''origine végétale qui aident à rétablir l''hydratation naturelle et réparer le film hydrolipidique. Nanovésicules d''acide hyaluronique hautement concentré pour hydratation interne et stimulation de collagène.', 30, 'ml', 'theramid-ceramide-repair-moisturizer', 'https://nichebeautylab.com', 'https://aurore-cdn.b-cdn.net/products/theramid-ceramide-repair-moisturizer.webp', 'Contient 3% acide hyaluronique encapsulé, 1% complexe céramides, 0,5% ectoine, 0,1% madécassoside. pH: 5.3-5.8. Peut être dernière étape ou associée à crème jour/nuit.', 1795, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.443+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-781d-b182-b80ceb7b7cc4', '__OWNER_ID__', 'Zitcalm Cream', 'Theramid', 'moisturizer', 'jar', 'Aqua, Coco-Caprylate/Caprate, ETHYL MACADAMIATE, Glycerin, C10-18 TRIGLYCERIDES, Propanediol, POLYGLYCERYL-6 DISTEARATE, Bisabolol, Allantoin, Glycereth-26, CANDELILLA/JOJOBA/RICE BRAN POLYGLYCERYL-3 ESTERS, SCLEROTIUM GUM, ISOSORBIDE DICAPRYLATE, ZINC HYDROLYZED HYALURONATE, LINOLEIC ACID, LINOLENIC ACID, Squalene, MORINDA CITRIFOLIA CALLUS CULTURE LYSATE, POTASSIUM CETYL PHOSPHATE, Helianthus Annuus Seed Oil, Tocopherol, Citric Acid, Beta-Sitosterol, PHOSPHORIC ACID, MALIC ACID, Ethylhexylglycerin, Phenoxyethanol', 'Crème hydratante et réparatrice spécialement conçue pour atténuer les effets des traitements anti-acnéiques agressifs qui dessèchent. Restaure la barrière protectrice et redonne du confort à la peau apaisée.', 50, 'ml', 'theramid-zitcalm-cream', 'https://nichebeautylab.com', 'https://aurore-cdn.b-cdn.net/products/theramid-zitcalm-cream.webp', 'Apaise, réduit et prévient rougeurs et sécheresse. Contient vitamine F, bisabolol et allantoïne. Texture crémeuse non grasse, pénétration rapide. Pour peaux sèches sensibilisées par traitements anti-acnéiques.', 1495, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.443+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-78c6-9b3e-013378fe371b', '__OWNER_ID__', 'Zitcontrol', 'Theramid', 'moisturizer', 'jar', 'Aqua, Niacinamide, Coco-Caprylate/Caprate, Glycerin, Salicylic Acid, Zinc PCA, MORINDA CITRIFOLIA CALLUS CULTURE LYSATE, DAUCUS CAROTA SATIVA ROOT CELL CULTURE LYSATE, Ceramide NP, Ethylhexylglycerin, Hydrogenated Lecithin, Lecithin, DIMYRISTOYL PHOSPHATIDYLCHOLINE, Mannitol, Lecithin, STEARAMINE, Cholesterol, XANTHAN GUM, SODIUM ACRYLATES COPOLYMER, SODIUM ACRYLATES CROSSPOLYMER-2, OLIVE OIL POLYGLYCERYL-6 ESTERS, SORBITAN OLEATE, Tocopherol, LAURYL GLUCOSIDE, Decyl Glucoside, Sodium Chloride, Citric Acid, Sodium Benzoate, Potassium Sorbate, Phenoxyethanol', 'Crème légère exclusive pour lutter contre l''acné avec acide salicylique, Zinc PCA, niacinamide et Quora Noni. Aide à contrôler les boutons, les réduire et empêcher leur réapparition grâce à Nichosome®.', 40, 'ml', 'theramid-zitcontrol', 'https://nichebeautylab.com', 'https://aurore-cdn.b-cdn.net/products/theramid-zitcontrol.webp', 'Système Nichosome® de libération progressive pour efficacité 12× supérieure sans irritation. Contient 5% niacinamide, 3% Quora Noni, 5% acide salicylique liposomé, 3% Zinc PCA. Pour acné active ou prévention.', 1795, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.443+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-7a97-8a14-33c1ad6457de', '__OWNER_ID__', 'Ascorbic C15', 'Theramid', 'serum', 'bottle', 'Aqua, DIMETHYL ISOSORBIDE, Ascorbic Acid, Propylene Glycol, Glutathione, Propanediol, Ethoxydiglycol, ARGININE FERULATE, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Camellia Sinensis Leaf Water, Ferulic Acid, Tocopherol, Caprylyl Glycol, Citric Acid, Sodium Phytate, Sodium Benzoate, Ethylhexylglycerin, Phenoxyethanol', 'Sérum antioxydant formulé avec 15% de vitamine C pure (acide L-ascorbique), l''un des plus efficaces pour traiter le vieillissement cutané. Réduit taches brunes, améliore l''éclat et adoucit les rides d''expression.', 30, 'ml', 'theramid-ascorbic-c15', 'https://nichebeautylab.com', 'https://aurore-cdn.b-cdn.net/products/theramid-ascorbic-c15.webp', 'Contient 5% glutathion (antioxydant puissant) et 1% extrait thé vert. pH: 3.0-3.2. Très instable, PAO 3 mois. Conserver au frais (<5°C). Non recommandé peaux sensibles. Odeur perceptible normale.', 995, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.443+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6516-7b24-9dc1-d26a2fb615f5', '__OWNER_ID__', 'Zi-K® Cica Repairing Gel', 'Theramid', 'moisturizer', 'jar', 'Aqua, Propanediol, NEOPENTYL GLYCOL DIHEPTANOATE, Dimethicone, Panthenol, CAPRYLYL METHICONE, CETYL PEG/PPG 10/1 DIMETHICONE, Glycerin, PEG/PPG-18/18 DIMETHICONE, Isododecane, Caprylyl Glycol, Madecassoside, ASIATICOSIDE, MADECCASSIC ACID, ASIATIC ACID, Centella Asiatica Extract, CENTELLA ASIATICA CALLUS CONDITIONED MEDIA, Alpha-Glucan Oligosaccharide, POLYMNIA SONCHIFOLIA ROOT JUICE, COPPER GLUCONATE, MAGNESIUM ASPARTATE, ZINC GLUCONATE, Glyceryl Caprylate, Pentylene Glycol, Dimethiconol, PHENYLPROPANOL, Mannitol, Lecithin, UBIQUINONE, POLYGLYCERYL-10 LAURATE, Cetyl Alcohol, Citric Acid, Sodium Phytate, Potassium Sorbate, Sodium Benzoate, Phenoxyethanol', 'Gel réparateur léger qui répare, apaise et protège les peaux abîmées ou irritées. Puissante combinaison de Centella Asiatica, madécassoside, T.E.CA, panthénol et madécasome pour hydratation et réparation cutanée.', 100, 'ml', 'theramid-zi-k-cica-repairing-gel', 'https://nichebeautylab.com', 'https://aurore-cdn.b-cdn.net/products/theramid-zi-k-cica-repairing-gel.webp', 'Texture légère gel idéale peaux normales à sèches. Hydrate, apaise, renforce et protège barrière cutanée. Soulage irritation, démangeaison, tiraillement. Favorise régénération et synthèse collagène.', 1495, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.444+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
