INSERT INTO public.products VALUES ('019de0ab-6524-71c9-84d3-b32e87d78533', '__OWNER_ID__', 'Sérum repulpant', 'Laboratoires de Biarritz', 'serum', 'dropper', 'Aqua, Glycerin, Squalane, OLUS OIL, XYLITYLGLUCOSIDE, GLYCERYL STEARATE CITRATE, Ectoin, HYDROLYZED GLYCOSAMINOGLYCANS, GELIDIUM SESQUIPEDALE EXTRACT, Aloe Barbadensis Leaf Juice, ANHYDROXYLITOL, Xylitol, Sodium Hyaluronate, ALTEROMONAS FERMENT EXTRACT, SODIUM LEVULINATE, POLYGLYCERYL-3 STEARATE, Glyceryl Caprylate, Propanediol, Parfum, LINOLEIC ACID, Hydrogenated Lecithin, Biosaccharide Gum-1, SODIUM ANISATE, Tocopherol, Polyglyceryl-4 Caprate, LYSOLECITHIN, SCLEROTIUM GUM, Citric Acid, Sodium Phytate, Oleic Acid, Pullulan, XANTHAN GUM, Palmitic Acid, Phenethyl Alcohol, Stearic Acid, Silica, LINOLENIC ACID', 'Sérum hydratant intense 24h avec Alga-Gorria® breveté. Protège contre les agressions quotidiennes (lumière bleue, pollution, stress). Repulpe la peau, booste l''action des soins hydratants appliqués en complément.', 50, 'ml', 'lab-biarritz-serum-repulpant', 'https://www.laboratoires-biarritz.com', 'https://aurore-cdn.b-cdn.net/products/lab-biarritz-serum-repulpant.webp', '100% naturel. 43,8% bio. Certifié bio. Pour visage et cou. Vegan. Actifs : acide hyaluronique, Ectoin (acide aminé, anti-pollution/lumière bleue), exopolysaccharide (tenseur), polysaccharide Pullulan (hydratant restructurant), Alteromonas Ferment Extract.', 2700, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.47+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6524-72a2-8194-1ad251280079', '__OWNER_ID__', 'Crème de nuit anti-taches', 'Laboratoires de Biarritz', 'moisturizer', 'jar', 'Aqua, Caprylic/Capric Triglyceride, Gluconolactone, Glycerin, Butyrospermum Parkii Butter, Coco-Caprylate/Caprate, Behenyl Alcohol, Helianthus Annuus Seed Oil, Microcrystalline Cellulose, C12-16 Alcohols, Aloe Barbadensis Leaf Juice, CYSTOSEIRA ABIES-MARINA EXTRACT, CYSTOSEIRA TAMARISCIFOLIA EXTRACT, PALMARIA PALMATA EXTRACT, Palmitic Acid, Hydrogenated Lecithin, Parfum, Citric Acid, XANTHAN GUM, Sodium Hydroxide, SODIUM LEVULINATE, Sodium Citrate, Maltodextrin, Tocopherol, SODIUM ANISATE, Pentylene Glycol', 'Crème de nuit anti-taches avec trio d''algues exclusif dont Alga-Biotic® (brevet déposé Lab. Biarritz). Corrige les taches pigmentaires, stimule le renouvellement cellulaire (PHA exfoliant doux), action anti-récidive prouvée.', 50, 'ml', 'lab-biarritz-creme-nuit-anti-taches', 'https://www.laboratoires-biarritz.com', 'https://aurore-cdn.b-cdn.net/products/lab-biarritz-creme-nuit-anti-taches.webp', '100% naturel. 21,9% bio. Certifiée bio. Texture onctueuse, parfum doux naturel. Vegan. Dès 28 nuits : taches visiblement estompées. Actifs : Alga-Biotic (module mélanogenèse + action prébiotique microbiome), Algue Iridescente (bloque chaîne pigmentaire), Algue Rouge (rééducation mélanocytes), PHA. Sur visage, cou, décolleté, mains.', 2900, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.47+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6518-7af2-8983-857395f7b30f', '__OWNER_ID__', 'Xeracalm A.D Baume Relipidant', 'Avène', 'balm', 'pump', 'Aqua, Paraffinum Liquidum, Glycerin, Caprylic/Capric Triglyceride, PEG-12, Oenothera Biennis Oil, Glyceryl Stearate, MYRETH-3 MYRISTATE, PEG-100 Stearate, POLYACRYLATE-13, AQUAPHILUS DOLOMIAE EXTRACT, ARGININE, Citric Acid, EVENING PRIMROSE OIL/PALM OIL AMINOPROPANEDIOL ESTERS, GLYCINE, Polyisobutene, Polysorbate 20, Sorbitan Isostearate, Tocopherol, Aqua', 'Baume relipidant très riche pour peaux très sèches à tendance atopique, dès la naissance.', 400, 'ml', 'avene-xeracalm-ad-baume-relipidant', 'https://www.eau-thermale-avene.fr', 'https://aurore-cdn.b-cdn.net/products/avene-xeracalm-ad-baume-relipidant.webp', 'Texture baume très riche. I-modulia® + Cer-Omega apaisent démangeaisons et relipident durablement.', 1800, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.47+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6524-7345-9d95-186a141b08dc', '__OWNER_ID__', 'La crème de Biarritz visage', 'Laboratoires de Biarritz', 'moisturizer', 'jar', 'Aqua, Glycerin, Butyrospermum Parkii Butter, OLUS OIL, Simmondsia Chinensis Seed Oil, Squalane, CETEARYL OLIVATE, COCONUT ALKANES, Sorbitan Olivate, Lauroyl Lysine, MYRISTYL MYRISTATE, Hydrogenated Castor Oil, XYLITYLGLUCOSIDE, GELIDIUM SESQUIPEDALE EXTRACT, Aloe Barbadensis Leaf Juice, Sodium Hyaluronate, ANHYDROXYLITOL, Xylitol, Parfum, LINOLEIC ACID, Oleic Acid, Palmitic Acid, Stearic Acid, LINOLENIC ACID, SODIUM LEVULINATE, Propanediol, Tocopherol, Coco-Caprylate/Caprate, XANTHAN GUM, SODIUM ANISATE, Polyglyceryl-4 Caprate, Citric Acid, ETHYL LAUROYL ARGINATE HCL, Sodium Phytate, VANILLIN, BETA-CARYOPHYLLENE', 'Crème hydratante 24h Ocean Therapy pour visage, cou et décolleté. Acide hyaluronique (biofermentation) + Alga-Gorria® breveté. Hydratation en surface et profondeur, repulpe, illumine, prévient les premières rides.', 50, 'ml', 'lab-biarritz-creme-visage', 'https://www.laboratoires-biarritz.com', 'https://aurore-cdn.b-cdn.net/products/lab-biarritz-creme-visage.webp', '100% naturel. 26,8% bio. Certifiée bio ECOCERT. Texture riche et fondante légère, parfum frais naturel. Pour tous types de peau. Vegan. Disponible en 2 formats (15 ml et 50 ml).', 1900, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.47+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6524-73f0-8f61-4e3cb9d2d2bb', '__OWNER_ID__', 'Crème de nuit régénérante', 'Laboratoires de Biarritz', 'moisturizer', 'jar', 'Aqua, Glycerin, Butyrospermum Parkii Butter, OLUS OIL, Squalane, Cetearyl Alcohol, Hydrogenated Castor Oil, Myristyl Alcohol, XYLITYLGLUCOSIDE, CETEARYL GLUCOSIDE, GELIDIUM SESQUIPEDALE EXTRACT, Aloe Barbadensis Leaf Juice, ANHYDROXYLITOL, Xylitol, Sodium Hyaluronate, Bisabolol, Parfum, LINOLEIC ACID, SODIUM LEVULINATE, MYRISTYL GLUCOSIDE, Propanediol, XANTHAN GUM, Glyceryl Caprylate, SODIUM ANISATE, Tocopherol, Polyglyceryl-4 Caprate, Oleic Acid, Citric Acid, Palmitic Acid, Stearic Acid, Phenethyl Alcohol, Saccharide Isomerate, LINOLENIC ACID', 'Crème de nuit hydratante intense 24h avec Alga-Gorria® (antioxydant breveté algue rouge basque). Booste l''hydratation nocturne, régénère et protège contre le vieillissement cutané. Effet peau neuve, traits défatigués.', 50, 'ml', 'lab-biarritz-creme-nuit-regenerante', 'https://www.laboratoires-biarritz.com', 'https://aurore-cdn.b-cdn.net/products/lab-biarritz-creme-nuit-regenerante.webp', '100% naturel. 25% bio. Certifiée bio ECOCERT. Texture douce enveloppante, parfum naturel léger. Pour tous types de peau. Vegan. Actifs : acide hyaluronique, exopolysaccharide (stimule la physiologie nocturne), dérivés de sucres naturels, aloe vera bio.', 2400, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.47+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6524-749b-a42b-d0d7856c4cfe', '__OWNER_ID__', 'CICA REPA Crème réparatrice', 'Laboratoires de Biarritz', 'moisturizer', 'tube', 'Aqua, Glycerin, Borago Officinalis Seed Oil, Simmondsia Chinensis Seed Oil, Squalane, Propanediol, PRUNUS DOMESTICA SEED OIL, C12-16 Alcohols, Pentylene Glycol, GELIDIUM SESQUIPEDALE EXTRACT, Aloe Barbadensis Leaf Juice, Ceramide NP, Sodium Hyaluronate, Palmitic Acid, Hydrogenated Lecithin, TRIOLEIN, SODIUM LEVULINATE, XANTHAN GUM, Tocopherol, SODIUM ANISATE, Citric Acid, GLYCERYL DIOLEATE, Sodium Phytate', 'Crème réparatrice et apaisante CICA REPA pour épidermes irrités, abîmés, réactifs (toute la famille dès nourrisson). Actif breveté Alga-Sendatu® (algue rouge basque) : favorise la réparation des couches superficielles et restaure la fonction barrière.', 100, 'ml', 'lab-biarritz-cica-repa-creme-reparatrice', 'https://www.laboratoires-biarritz.com', 'https://aurore-cdn.b-cdn.net/products/lab-biarritz-cica-repa-creme-reparatrice.webp', '100% naturel. 57,8% bio. Certifiée bio. Effet seconde peau, fini non gras, sans parfum, sans alcool, hypoallergénique. Indiquée pour : irritations, rougeurs, égratignures, post-épilation, post-rasage, brûlures superficielles, coups de soleil, post-actes dermatologiques. Sur visage, corps et muqueuses externes. Sur lésions sèches non suintantes.', 1900, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.471+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6524-7549-98ad-0f800219e0dd', '__OWNER_ID__', 'Crème solaire visage SPF50', 'Laboratoires de Biarritz', 'sunscreen', 'tube', 'Caprylic/Capric Triglyceride, COCONUT ALKANES, Zinc Oxide, Titanium Dioxide, Aqua, ORYZA SATIVA POWDER, Polyglyceryl-2 Dipolyhydroxystearate, PRUNUS DOMESTICA SEED OIL, Sorbitan Olivate, POLYGLYCERYL-3 DIISOSTEARATE, Glycerin, Helianthus Annuus Seed Oil, Coco-Caprylate/Caprate, Alumina, Stearic Acid, Glyceryl Caprylate, Magnesium Sulfate, GELIDIUM SESQUIPEDALE EXTRACT, Aloe Barbadensis Leaf Juice, Propanediol, Tocopherol, Sodium Benzoate, Polyglyceryl-4 Caprate, Potassium Sorbate', 'Crème solaire bio visage SPF50 protectrice et hydratante. Écrans minéraux + Alga-Gorria® (extrait antioxydant breveté d''algue rouge basque) pour protéger des UVA/UVB, prévenir les taches pigmentaires et le vieillissement cutané.', 50, 'ml', 'lab-biarritz-creme-solaire-visage-spf50', 'https://www.laboratoires-biarritz.com', 'https://aurore-cdn.b-cdn.net/products/lab-biarritz-creme-solaire-visage-spf50.webp', '99,6% naturel. 20,8% bio. Certifiée ECOCERT. Texture légère, sans parfum, résistante à l''eau. Enrichie en aloe vera bio, huiles de prunes et tournesol bio. Pour peaux claires, fragiles et sensibles. Utilisable femme enceinte/allaitante. Non-toxique pour l''environnement marin.', 2000, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.471+00', 'solaire', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6536-7059-b3f3-d70fc444b372', '__OWNER_ID__', 'Huile Démaquillante Précieuse', 'L''Occitane', 'cleanser', 'bottle', 'Helianthus Annuus Seed Oil, PEG-40 SORBITAN PEROLEATE, ISOPROPYL ISOSTEARATE, Caprylic/Capric Triglyceride, Coco-Caprylate/Caprate, Ricinus Communis Seed Oil, C13-15 ALKANE, HELICHRYSUM ITALICUM EXTRACT, HELICHRYSUM ITALICUM FLOWER OIL, Prunus Armeniaca Kernel Oil, HIPPOPHAE RHAMNOIDES FRUIT OIL, Tocopherol, Parfum', 'Huile démaquillante légère qui élimine le maquillage, même waterproof, et nettoie efficacement la peau en éliminant les impuretés et excès de sébum. La peau est +20% plus douce et 82% des utilisateurs trouvent leurs pores moins visibles.', 200, 'ml', 'loccitane-immortelle-huile-demaquillante-200ml', 'https://fr.loccitane.com/huile-demaquillante-precieuse-27HD200I23.html', 'https://aurore-cdn.b-cdn.net/products/loccitane-immortelle-huile-demaquillante-200ml.webp', 'Enrichie en huile de ricin et huile essentielle d''Immortelle bio de Corse. 97% des utilisateurs trouvent le produit efficace et doux. Formule testée sous contrôle dermatologique, adaptée à tous types de peau.', 2900, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.472+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64ea-7ee7-9de9-ffdfa3da03d1', '__OWNER_ID__', 'Ducray Dexyane Baume Émollient Anti-Grattage 400ml', 'Ducray', 'balm', 'jar', 'WATER (AQUA).CAPRYLIC/CAPRIC TRIGLYCERIDE, Carthamus Tinctorius Seed Oil, Paraffinum Liquidum, Glycerin, Cetearyl Alcohol, Glyceryl Stearate, PEG-100 Stearate, 10-HYDROXYDECENOIC ACID, Cera Alba, Benzoic Acid, Caprylyl Glycol, CETEARYL GLUCOSIDE, Glyceryl Stearate, Glycyrrhetinic Acid, ISOLEUCINE, POLYACRYLATE-13, Polyisobutene, Polysorbate 20, Sodium Hydroxide, Sorbitan Isostearate, TOCOPHERYL ACETATEFabriqué en FranceIsoleucine : Actif qui limite l''adhésion de Staphylococcus Aureus et Malassezia FurfurAcide β-glycyrrhétinique : Actif connu pour ses propriétés apaisantesIl est recommandé au consommateur de vérifier systématiquement la composition du produit avant son achat', '', 400, 'ml', 'ducray-dexyane-baume-emollient-anti-grattage-400ml-302033', 'https://www.atida.fr/ducray-dexyane-baume-400ml.html', 'https://aurore-cdn.b-cdn.net/products/ducray-dexyane-baume-emollient-anti-grattage-400ml-302033.webp', '', 1999, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.477+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6536-723b-b550-f87efe094d11', '__OWNER_ID__', 'Triphase Essence Immortelle Reset', 'L''Occitane', 'essence', 'bottle', 'Aqua, C15-19 Alkane, Ricinus Communis Seed Oil, Pentylene Glycol, Helianthus Annuus Seed Oil, Glycerin, Sodium Chloride, BETA VULGARIS (BEET) ROOT EXTRACT, YEAST EXTRACT, CICHORIUM INTYBUS (CHICORY) ROOT EXTRACT, HELICHRYSUM ITALICUM EXTRACT, ALKANNA TINCTORIA ROOT EXTRACT, HELICHRYSUM ITALICUM FLOWER OIL, Fructooligosaccharides, Bisabolol, Adenosine, Fructose, LEVULINIC ACID, SODIUM LEVULINATE, SODIUM GLUCONATE, Tocopherol, BENZOTRIAZOLYL DODECYL P-CRESOL, XANTHAN GUM, Sodium Hydroxide, POTASSIUM LACTATE, Alcohol, Caprylyl Glycol, 1,2-Hexanediol, Lactic Acid, TRIS(TETRAMETHYLHYDROXYPIPERIDINOL) CITRATE, Parfum, CI 60725/VIOLET 2, CI 19140, CI 17200', 'Essence triphase jour & nuit qui aide à équilibrer la peau et renforcer sa barrière pour un teint éclatant, apaisé et résilient. Réduit immédiatement la sensation d''inconfort de 54% et améliore visiblement l''éclat de 16%.', 150, 'ml', 'loccitane-immortelle-triphase-essence-reset-150ml', 'https://fr.loccitane.com/triphase-essence-immortelle-reset-27ER150I25.html', 'https://aurore-cdn.b-cdn.net/products/loccitane-immortelle-triphase-essence-reset-150ml.webp', 'Formule enrichie en extrait de betterave, extrait de chicorée, fructooligosaccharides et Immortelle bio. Dès 7 jours : barrière cutanée équilibrée, teint homogène +10%. Dès 28 jours : signes de fatigue réduits -10%, grain de peau affiné +9%.', 7900, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.472+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6536-72e9-9041-953762298998', '__OWNER_ID__', 'Sérum Pro-Fermeté Immortelle Divine', 'L''Occitane', 'serum', 'pump', 'Aqua, Glycerin, Pentylene Glycol, Dicaprylyl Carbonate, C14-22 Alcohols, Oenothera Biennis Oil, Boron Nitride, HELICHRYSUM ITALICUM FLOWER/STEM EXTRACT, HELICHRYSUM ITALICUM EXTRACT, GLEDITSIA TRIACANTHOS SEED EXTRACT, Helianthus Annuus Seed Oil, ECHIUM PLANTAGINEUM SEED OIL, CAMELINA SATIVA SEED OIL, Borago Officinalis Seed Oil, HELICHRYSUM ITALICUM FLOWER OIL, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, GLYCERYL STEARATE CITRATE, C12-20 ALKYL GLUCOSIDE, Sodium Acetylated Hyaluronate, Ethylhexylglycerin, XANTHAN GUM, Caprylic/Capric Triglyceride, Ascorbyl Glucoside, Sorbitan Isostearate, Polysorbate 60, Adenosine, Trisodium Ethylenediamine Disuccinate, Tocopherol, ZINC GLUCONATE, MAGNESIUM ASPARTATE, COPPER GLUCONATE, Glyceryl Caprylate, Sodium Hydroxide, Citric Acid, Sodium Benzoate, Potassium Sorbate, Parfum', 'Sérum visage qui agit sur les rides et la fermeté de la peau. Lisse les 5 types de rides du visage et raffermit progressivement la peau dès 14 jours. +17% peau visiblement lissée immédiatement, +73% aspect lissé et fermeté après 56 jours.', 30, 'ml', 'loccitane-immortelle-serum-pro-fermete-30ml', 'https://fr.loccitane.com/serum-pro-fermete-immortelle-divine-27DS030I24.html', 'https://aurore-cdn.b-cdn.net/products/loccitane-immortelle-serum-pro-fermete-30ml.webp', 'Formule enrichie en super extrait d''Immortelle (alternative naturelle au rétinol), extrait de Gleditsia tenseur et acide hyaluronique acétylé. 96% d''ingrédients d''origine naturelle. Nouvelle texture crème, pénétration rapide sans effet collant.', 9900, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.472+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6536-738e-9414-ca0d371334dd', '__OWNER_ID__', 'Sérum Visage Reset Nuit', 'L''Occitane', 'serum', 'pump', 'Aqua, Glycerin, Propanediol, Coco-Caprylate/Caprate, Butylene Glycol, Pentylene Glycol, DEXTRIN PALMITATE, Limnanthes Alba Seed Oil, 1,2-Hexanediol, ACMELLA OLERACEA EXTRACT, HELICHRYSUM ITALICUM EXTRACT, HELICHRYSUM ITALICUM FLOWER OIL, Gardenia Florida Fruit Extract, Helianthus Annuus Seed Oil, Adenosine, Betaine, Caprylyl Glycol, Carbomer, Fructose, Trisodium Ethylenediamine Disuccinate, Sodium Hydroxide, Cellulose Gum, AMODIMETHICONE, Tocopherol, Maltodextrin, Parfum, CI 40800/BETA-CAROTENE', 'Sérum de nuit qui réveille l''éclat. Une peau revitalisée, reposée et lumineuse en 1 nuit. L''extrait de gardénia aide la peau à se rétablir, l''extrait d''Acmella Oleracea lisse instantanément et l''Immortelle protège contre le stress oxydant.', 50, 'ml', 'loccitane-immortelle-serum-reset-nuit-50ml', 'https://fr.loccitane.com/serum-visage-reset-nuit.html', 'https://aurore-cdn.b-cdn.net/products/loccitane-immortelle-serum-reset-nuit-50ml.webp', 'Formule enrichie en extrait pro-sève d''Immortelle (technologie Bio-inspiration végétale), extrait de gardénia et extrait d''Acmella Oleracea. Huiles encapsulées pour une sensorialité unique. Appliquer le soir après nettoyage.', 9500, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.473+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6536-74df-9e44-4814a84d9dfd', '__OWNER_ID__', 'Crème Jeunesse Immortelle Divine', 'L''Occitane', 'moisturizer', 'jar', 'Aqua, C12-15 ALKYL BENZOATE, Caprylic/Capric Triglyceride, Glycerin, Oenothera Biennis Oil, Pentylene Glycol, Cetearyl Alcohol, Dimethicone, Tapioca Starch, Ascorbyl Glucoside, Glyceryl Stearate, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, CAMELINA SATIVA SEED OIL, Cetyl Alcohol, BELLIS PERENNIS (DAISY) FLOWER EXTRACT, LANSIUM DOMESTICUM LEAF EXTRACT, HELICHRYSUM ITALICUM EXTRACT, HELICHRYSUM ITALICUM FLOWER/STEM EXTRACT, ECHIUM PLANTAGINEUM SEED OIL, HELICHRYSUM ITALICUM FLOWER OIL, MYRTUS COMMUNIS OIL, Borago Officinalis Seed Oil, Helianthus Annuus Seed Oil, Adenosine, Sodium Hyaluronate, PEG-100 Stearate, SUCROSE PALMITATE, CETEARYL GLUCOSIDE, Tocopheryl Acetate, Sodium Citrate, Sodium Hydroxide, Maltodextrin, Ethylhexylglycerin, GLYCERYL LINOLEATE, Stearic Acid, Palmitic Acid, Disodium EDTA, Sorbitan Isostearate, Polysorbate 60, ZINC GLUCONATE, MAGNESIUM ASPARTATE, Citric Acid, COPPER GLUCONATE, Tocopherol, Potassium Phosphate, Potassium Chloride, DISODIUM PHOSPHATE, Sodium Chloride, Potassium Sorbate, Sodium Benzoate, Chlorphenesin, Parfum', 'Soin anti-âge global enrichi en extrait d''Immortelle bio de Corse, alternative naturelle au Rétinol. Aide à combattre les 7 signes visibles de l''âge. -19% de rides après 28 jours, 85% des utilisateurs trouvent leurs taches brunes moins visibles.', 50, 'ml', 'loccitane-immortelle-creme-jeunesse-50ml', 'https://fr.loccitane.com/creme-jeunesse-immortelle-divine-27DC050I23.html', 'https://aurore-cdn.b-cdn.net/products/loccitane-immortelle-creme-jeunesse-50ml.webp', 'Reformulée avec extrait de pâquerette et extrait de Lansium pour l''uniformité du teint. Texture cachemire. 100% des femmes déclarent la crème enveloppe d''un voile de douceur. Packaging en verre composé à 40% de verre recyclé.', 9500, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.473+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6536-75b3-a95b-c824f67927d2', '__OWNER_ID__', 'Crème Visage Précieuse', 'L''Occitane', 'moisturizer', 'jar', 'Aqua, Glycerin, Cetearyl Alcohol, Dicaprylyl Ether, Cetyl Alcohol, Cetyl Palmitate, OCTYLDODECYL MYRISTATE, Butyrospermum Parkii Butter, Tapioca Starch, Myristyl Alcohol, Methylpropanediol, Dimethicone, HELICHRYSUM ITALICUM FLOWER OIL, HELICHRYSUM ITALICUM EXTRACT, LENS ESCULENTA (LENTIL) FRUIT EXTRACT, Helianthus Annuus Seed Oil, Adenosine, Hyaluronic Acid, SILANETRIOL, CETEARYL GLUCOSIDE, MYRISTYL GLUCOSIDE, Carbomer, Caprylyl Glycol, Pentylene Glycol, Ethylhexylglycerin, XANTHAN GUM, Sodium Hydroxide, Tocopherol, Citric Acid, Chlorphenesin, Sodium Benzoate, Potassium Sorbate, Parfum', 'Crème visage qui repulpe la peau et agit contre les premiers signes de l''âge. Nourrit et hydrate 24h, -39% de ridules, -14% d''apparence des pores. Pour une peau lissée, rebondie et éclatante.', 50, 'ml', 'loccitane-immortelle-creme-visage-precieuse-50ml', 'https://fr.loccitane.com/creme-visage-precieuse-27CP050I22.html', 'https://aurore-cdn.b-cdn.net/products/loccitane-immortelle-creme-visage-precieuse-50ml.webp', 'Enrichie en huile essentielle d''Immortelle, super extrait aqueux d''Immortelle et extrait de lentille. 95% d''ingrédients d''origine naturelle. Adaptée aux peaux normales à sèches. Existe aussi en texture émulsion plus légère.', 6400, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.473+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6536-764f-a8bf-88ecba78c1f9', '__OWNER_ID__', 'Baume Regard Immortelle Divine', 'L''Occitane', 'eye-cream', 'jar', 'Aqua, Butyrospermum Parkii Butter, Coco-Caprylate/Caprate, Glycerin, ROSA CENTIFOLIA FLOWER WATER, Cetearyl Alcohol, Silica, Oenothera Biennis Oil, Glyceryl Stearate, PEG-100 Stearate, CAMELINA SATIVA SEED OIL, HELICHRYSUM ITALICUM FLOWER OIL, HELICHRYSUM ITALICUM FLOWER/STEM EXTRACT, HELICHRYSUM ITALICUM EXTRACT, ECHIUM PLANTAGINEUM SEED OIL, Borago Officinalis Seed Oil, MYRTUS COMMUNIS OIL, Helianthus Annuus Seed Oil, Adenosine, Hyaluronic Acid, Escin, Methyl Methacrylate Crosspolymer, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, CETEARETH-33, Caprylyl Glycol, Ethylhexylglycerin, Tocopherol, XANTHAN GUM, Disodium EDTA, Sorbitan Isostearate, Polysorbate 60, Caprylic/Capric Triglyceride, SUCROSE PALMITATE, Sodium Hydroxide, GLYCERYL LINOLEATE, Citric Acid, Sodium Benzoate, Phenoxyethanol, Potassium Sorbate', 'Baume contour des yeux qui lisse et comble visiblement les rides et ridules, réduit les poches et les cernes pour révéler la jeunesse du regard sous tous les angles. Recommandé par 9 femmes sur 10. 3 brevets déposés en France.', 15, 'ml', 'loccitane-immortelle-baume-regard-15ml', 'https://fr.loccitane.com/baume-regard-immortelle-divine.html', 'https://aurore-cdn.b-cdn.net/products/loccitane-immortelle-baume-regard-15ml.webp', 'Enrichi en beurre de karité et 4 extraits d''Immortelle bio de Corse (HE, extrait aqueux, extrait huileux, super extrait). Texture riche et fondante. Agit sur rides, poches, cernes, fermeté, uniformité et éclat après 28 applications.', 6900, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.474+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6536-76f5-b0e8-f63e93993a5c', '__OWNER_ID__', 'Contour Yeux et Lèvres Immortelle Divine', 'L''Occitane', 'eye-cream', 'tube', 'Aqua, ROSA CENTIFOLIA FLOWER WATER, Glycerin, Caprylic/Capric Triglyceride, Butylene Glycol, Silica, Propanediol, POLYGLYCERYL-6 DISTEARATE, Oenothera Biennis Oil, Butyrospermum Parkii Butter, HELICHRYSUM ITALICUM FLOWER OIL, HELICHRYSUM ITALICUM FLOWER/STEM EXTRACT, HELICHRYSUM ITALICUM EXTRACT, CAMELINA SATIVA SEED OIL, Borago Officinalis Seed Oil, ACMELLA OLERACEA EXTRACT, ECHIUM PLANTAGINEUM SEED OIL, IRIS FLORENTINA ROOT EXTRACT, Helianthus Annuus Seed Oil, MYRTUS COMMUNIS OIL, Adenosine, Escin, Jojoba Esters, SODIUM POLYACRYLATE, Methyl Methacrylate Crosspolymer, POLYGLYCERYL-3 BEESWAX, Cetyl Alcohol, Tocopheryl Acetate, SODIUM STEAROYL GLUTAMATE, Ethylhexylglycerin, SUCROSE PALMITATE, Disodium EDTA, GLYCERYL LINOLEATE, Sodium Benzoate, Citric Acid, Tocopherol, Chlorphenesin, Potassium Sorbate, Limonene', 'Soin double-action contour des yeux et des lèvres qui hydrate et lutte contre les signes visibles de l''âge et le relâchement de la peau. Enrichi en super extrait d''Immortelle bio de Corse, alternative naturelle au Rétinol.', 15, 'ml', 'loccitane-immortelle-contour-yeux-levres-15ml', 'https://fr.loccitane.com/contour-yeux-levres-immortelle-divine.html', 'https://aurore-cdn.b-cdn.net/products/loccitane-immortelle-contour-yeux-levres-15ml.webp', 'Contient 4 extraits d''Immortelle, huile végétale d''onagre (riche en oméga-6), extrait d''Acmella Oleracea lissant et escin pour les poches. Actifs pour le contour des yeux et des lèvres en un seul soin.', 6400, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.474+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
