INSERT INTO public.products VALUES ('019de0ab-6536-77a6-979d-b1141db597ec', '__OWNER_ID__', 'Crème Cou Lissante Immortelle Divine', 'L''Occitane', 'moisturizer', 'tube', 'Aqua, Glycerin, Butyrospermum Parkii Butter, Tapioca Starch, Coco-Caprylate/Caprate, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Avena Sativa Kernel Extract, HELICHRYSUM ITALICUM FLOWER/STEM EXTRACT, HELICHRYSUM ITALICUM FLOWER OIL, Helianthus Annuus Seed Oil, MYRTUS COMMUNIS OIL, Hyaluronic Acid, Palmitoyl Tripeptide-1, Palmitoyl Tetrapeptide-7, Butylene Glycol, Caprylyl Glycol, ARACHIDYL ALCOHOL, XANTHAN GUM, Ethylhexylglycerin, Behenyl Alcohol, SODIUM GLUCONATE, Polysorbate 60, Sorbitan Isostearate, ARACHIDYL GLUCOSIDE, Caprylic/Capric Triglyceride, Sodium Lactate, Carbomer, Tocopherol, Pentylene Glycol, MAGNESIUM ASPARTATE, ZINC GLUCONATE, Sodium Hydroxide, Polysorbate 20, COPPER GLUCONATE, Chlorphenesin, Sodium Benzoate, Parfum', 'Crème cou spécialisée qui nourrit la peau, améliore l''élasticité et la fermeté, et réduit visiblement l''apparence des plis du cou. Un aspect plus lisse, une sensation plus ferme, une confiance renforcée.', 50, 'ml', 'loccitane-immortelle-creme-cou-lissante-50ml', 'https://fr.loccitane.com/creme-cou-lissante-immortelle-divine.html', 'https://aurore-cdn.b-cdn.net/products/loccitane-immortelle-creme-cou-lissante-50ml.webp', 'Formule avec peptides de matrikines (palmitoyl tripeptide-1 et tétrapeptide-7) pour le lissage et la fermeté. Enrichie en acide hyaluronique, extrait d''avoine et Immortelle bio de Corse.', 6900, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.474+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
