INSERT INTO public.products VALUES ('019e0384-4332-7c51-b5eb-2f4f100dad90', '__OWNER_ID__', 'Black Bamboo Daily Smoothing Body Oil', 'Haruharu Wonder', 'oil', 'dropper', 'Aqua, Glycerin, Helianthus Annuus Seed Oil, Caprylic/Capric Triglyceride, Hydrogenated Polyisobutene, Phosphate De Cétyle De Potassium, Malate De Diisostéaryle, Urée, Tétraisostéarate De Pentaérythrityle, 1,2-Hexanediol, Butylene Glycol, Parfum, Hydroxyacetophenone, Stearyl Alcohol, Cetyl Alcohol, Glyceryl Stearate, Huile D’Amande Douce (Prunus Amygdalus Dulcis), Squalane, Argania Spinosa Kernel Oil, Copolymère D’Acrylates/C10-30 Alkyl Acrylate Réticulé, Gomme Xanthane, Huile De Graines De Calophyllum Inophyllum, Bambusa Vulgaris Water, Stearic Acid, Ethylhexylglycerin, Palmitic Acid, Extrait D’Écorce De Jeunes Pousses De Phyllostachys Pubescens, Disodium EDTA, Tromethamine, Extrait De Feuille De Phyllostachys Nigra, Aspergillus Ferment, Mandelic Acid, Myristyl Alcohol, Arachidic Acid, Alcool Laurique, Myristic Acid, Oleic Acid, Citronellol, Geraniol, Limonene, Citral, Linalool', 'Cette Black Bamboo Daily Smoothing Body Oil Haruharu Wonder est une huile pour le corps légère à la texture « huile lactée » qui combine nutrition, hydratation, exfoliation douce et soin de la barrière cutanée. Elle offre une peau douce, lisse et lumineuse, sans le fini gras des huiles corporelles traditionnelles. Sa formule associe de l’eau de bambou, reconnue pour ses propriétés hydratantes et antioxydantes, à de l’urée et de l’acide mandélique pour une exfoliation douce qui aide à lisser les zones rugueuses ou granuleuses. Elle est également enrichie d’un mélange d’huiles nourrissantes, dont l’huile d’amande douce, l’huile d’argan, l’huile de tamanu et le squalane, afin de sceller l’hydratation et de renforcer la barrière cutanée. Résultat : une peau plus douce, intensément hydratée, visiblement plus lisse et éclatante, idéale pour les zones sèches, squameuses ou irrégulières comme les bras, les jambes, les genoux et les coudes. Recommandé pour : Peaux sensibles, peaux sèches, tous types de peaux.', 200, 'ml', 'haruharu-wonder-black-bamboo-daily-smoothing-body-oil', 'https://korean-skincare.fr/products/haruharu-wonder-black-bamboo-daily-smoothing-body-oil', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-bamboo-daily-smoothing-body-oil.webp', 'Juste après la douche, applique une quantité modérée sur peau encore humide et masse délicatement jusqu’à absorption complète. Sur les zones très sèches ou rugueuses (genoux, coudes, jambes, bras), tu peux aussi l’appliquer sur peau sèche et masser davantage pour favoriser la pénétration. Pour de meilleurs résultats, utilise-la quotidiennement, matin ou soir, dans ta routine de soin du corps.', 1995, '2026-05-07 17:37:40.146644+00', '2026-06-14 15:14:07.475+00', 'skincare', '[]', 'huile', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
