INSERT INTO public.products VALUES ('019de0ab-6502-7d45-9732-5e5a6a4a94e4', '__OWNER_ID__', 'Baume Multi-Usages', 'Même', 'balm', 'jar', 'Prunus Amygdalus Dulcis Oil, POLYGLYCERYL-3 DIISOSTEARATE, Butyrospermum Parkii Butter, Cera Alba, Dicaprylyl Carbonate, Jojoba Esters, POLYGLYCERYL-4 ISOSTEARATE, Coco-Caprylate/Caprate, Helianthus Annuus Seed Wax, ACACIA DECURRENS FLOWER WAX, STEVIOSIDE, POLYGLYCERIN-3, POLYGLYCERYL-3 POLYRICINOLEATE, Sorbitan Isostearate, Glyceryl Oleate, STEARALKONIUM HECTORITE, DISTEARDIMONIUM HECTORITE, PROPYLENE CARBONATE, Tocopheryl Acetate, Tocopherol, Ascorbyl Palmitate, Citric Acid', 'Baume réparateur effet pansement pour zones sèches, sensibles et cicatrices. Adapté aux traitements anticancéreux.', 40, 'ml', 'meme-baume-multi-usage', 'https://www.meme-cosmetics.com', 'https://aurore-cdn.b-cdn.net/products/meme-baume-multi-usage.webp', '98% origine naturelle. Amande douce + karité + cire de mimosa + cire d''abeilles. Dès 3 ans. Femmes enceintes/allaitantes OK.', 1600, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.476+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64e1-7751-b76a-fc1f5d543d42', '__OWNER_ID__', 'Rescue Balm All-Purpose Skin Salve & Lip Balm', 'Air Repair', 'balm', 'jar', 'AFRICAN SHEA BUTTER, Cera Alba, BORAGO OFFICINALIS (BORAGE) OIL, Pelargonium Graveolens Oil, HELIANTHUS ANNUUS (SUNFLOWER) OIL, Lanolin, LAVANDIN (LAVANDULA HYBRIDA) ESSENTIAL OIL, Limnanthes Alba Seed Oil, Prunus Amygdalus Dulcis Oil, RICINUS COMMUNIS (CASTOR) OIL, Simmondsia Chinensis Seed Oil, Tocopherol', 'Baume multi-usage lèvres et corps à la Cire d"Abeille et au Karité qui protège, nourrit et répare les zones sèches, irritées ou gercées.', 0, 'g', 'air-repair-rescue-balm', 'https://www.skinsafeproducts.com/air-repair-skincare-rescue-balm-all-purpose-skin-salve-lip-balm', 'https://aurore-cdn.b-cdn.net/products/air-repair-rescue-balm.webp', 'Contient des huiles essentielles (géranium, lavandin). Cire d"Abeille + Karité + Jojoba — Idéal pour lèvres gercées, coudes et zones à peau sèche.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.476+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6520-72b8-a7a9-580c9d033009', '__OWNER_ID__', 'Urelia 50 Baume Hydratant Kératolytique', 'Isispharma', 'balm', 'tube', 'Urea, Aqua, Paraffinum Liquidum, Glycerin, Cyclopentasiloxane, Glycolic Acid, Butyrospermum Parkii Butter, Dicaprylyl Ether, Cyclohexasiloxane, POLYGLYCERYL-4 ISOSTEARATE, CETYL PEG/PPG-10/1 DIMETHICONE, HEXYL LAURATE, BEHENOXY DIMETHICONE, Pentylene Glycol, Dimethicone, Sodium Chloride, PSEUDOALTEROMONAS FERMENT EXTRACT, Lactic Acid, Chlorphenesin, XANTHAN GUM, Caprylyl Glycol, Ethylhexylglycerin, ALANINE, PROLINE, SERINE, Sodium Phosphate, Sodium Hydroxide, Tocopherol, Glycine Soja Oil, PENTAERYTHRITYL TETRADI-T-BUTYL HYDROXYHYDROCINNAMATE, Citric Acid', 'Baume onctueux ultra-concentré en urée pour le traitement des plaques épaissies et des zones hyperkératosiques. Texture confortable respectant les peaux fragilisées. Action combinée exfoliante et réparatrice.', 40, 'ml', 'isispharma-urelia-50-baume-keratolytique', 'https://pharmacie-citypharma.fr/fr/isispharma-urelia-50-baume-hydratant-keratolytique-40ml', 'https://aurore-cdn.b-cdn.net/products/isispharma-urelia-50-baume-keratolytique.webp', '50% d''urée + acides glycolique et lactique. Contient un extrait fermenté marin (Pseudoalteromonas) aux propriétés régénérantes. Formule non parfumée, tolérance optimale. Association recommandée avec Urelia Gel.', 1389, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.476+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
