INSERT INTO public.products VALUES ('019e0384-3d86-709e-9fc3-c070febb47fb', '__OWNER_ID__', 'Glow Skin Balm', 'MISSHA', 'balm', 'jar', 'Rosa Damascena Flower Water, Butylene Glycol, Hydrogenated Poly(C6-14 Olefin), Squalane, Glycerin, Caprylic/​Capric/​Myristic/​Stearic Triglyceride, Butyrospermum Parkii Butter, Cetearyl Alcohol, Niacinamide, Macadamia Ternifolia Seed Oil, Glyceryl Stearate, Phytosteryl/​Isostearyl/​Cetyl/​Stearyl/​Behenyl Dimer Dilinoleate, Cyclopentasiloxane, Synthetic Beeswax, PEG-40 Stearate, 1,2-Hexanediol, Nelumbium Speciosum Flower Extract, Prunus Mume Fruit Extract, Citrus Aurantium Dulcis Peel Oil, Citrus Reticulata Peel Oil, Eclipta Prostrata Extract, Hippophae Rhamnoides Oil, Cananga Odorata Flower Oil, Citrus Aurantium Amara Peel Oil, Hydrolyzed Hibiscus Esculentus Extract, Lupinus Albus Seed Extract, Moringa Oleifera Seed Extract, Citrus Reticulata (Tangerine) Leaf Oil, Melia Azadirachta Leaf Extract, Helianthus Annuus (Sunflower) Seed Oil Unsaponifiables, Simmondsia Chinensis Seed Oil, Sodium Hyaluronate, Moringa Oleifera Seed Oil, Xylitol, Hydrolyzed Collagen, Aqua, Cyclohexasiloxane, PEG-100 Stearate, Caprylic/Capric Triglyceride, Dimethicone, PEG-30 Dipolyhydroxystearate, Caprylyl Glycol, Polyacrylamide, C13-14 Isoparaffin, Sodium Polyacrylate, Copernicia Cerifera (Carnauba) Wax, Tocopheryl Acetate, Ethylhexyl Cocoate, Ethylhexylglycerin, Polyglyceryl-6 Stearate, Laureth-7, PPG-3 Benzyl Ether Myristate, Polysorbate 20, Polyglyceryl-6 Behenate, Tocopherol, Xylitylglucoside, Anhydroxylitol, Hydrogenated Lecithin, Glucose, Glycine, Serine, Glutamic Acid, Ceramide NP, Aspartic Acid, Leucine, Alanine, Lysine, Arginine, Tyrosine, Phenylalanine, Proline, Threonine, Valine, Isoleucine, Histidine, Cysteine, Methionine, Disodium EDTA', 'Le Glow Skin Balm Missha est un baume matinal 4 en 1. C''est à la fois un hydratant, un masque pour le matin, une base de maquillage et un baume glow. Formulé avec 53 % d''extrait de rose de Damas pour hydrater et revitaliser la peau, il possède un magnifique mais subtil parfum de rose et te procure un éclat pulpeux et rosé.', 50, 'ml', 'missha-glow-skin-balm', 'https://korean-skincare.fr/products/missha-glow-skin-balm', 'https://aurore-cdn.b-cdn.net/products/missha-glow-skin-balm.webp', 'Prélève une quantité modérée de crème à l''aide d''une spatule propre. Applique-la sur l''ensemble du visage et masse délicatement pour une meilleure absorption.', 1995, '2026-05-07 17:37:38.693865+00', '2026-06-14 15:14:07.486+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3e11-797a-8a72-8c3854d2eed5', '__OWNER_ID__', 'Super Aqua Ultra Hyalron Balm Cream Original', 'MISSHA', 'balm', 'jar', 'Aqua, Butylene Glycol, Aqua, Glycerin, Caprylic/Capric Triglyceride, 1,2-Hexanediol, Behenyl Alcohol, Caprylyl Methicone, Niacinamide, Cetearyl Alcohol, Pentylene Glycol, Trehalose, Sucrose Polystearate, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, C12-16 Alcohols, Polymethylsilsesquioxane, Tromethamine, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Palmitic Acid, Hydroxyacetophenone, Hydrogenated Lecithin, Hydrogenated Polyisobutene, Citrus Aurantium Bergamia Fruit Oil, Ethylhexylglycerin, Adenosine, Lavandula Angustifolia Oil, Disodium EDTA, Citrus Aurantium Dulcis Peel Oil, Sorbitan Isostearate, Hydrolyzed Hibiscus Esculentus Extract, Lupinus Albus Seed Extract, Moringa Oleifera Seed Extract, Pinus Sylvestris Leaf Oil, Propanediol, Sodium Hyaluronate, Glyceryl Glucoside, Benzyl Glycol, Xylitylglucoside, Anhydroxylitol, Hydrolyzed Glycosaminoglycans, Xylitol, Hydroxypropyltrimonium Hyaluronate, Sodium Hyaluronate Crosspolymer, Sucrose Palmitate, Glucose, Hydrolyzed Hyaluronic Acid, Ceramide NP, Macadamia Ternifolia Seed Oil, Olea Europaea Fruit Oil, Simmondsia Chinensis Seed Oil, Vitis Vinifera Seed Oil, Sodium Acetylated Hyaluronate, Glyceryl Caprylate, Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Potassium Hyaluronate, Linalool, Limonene', 'Le Super Aqua Ultra Hyalron Balm Cream Original MISSHA est un baume-crème riche et profondément hydratant qui apporte une hydratation intensive et un confort longue durée aux peaux sèches. Enrichie d’un complexe de 10 types d’acide hyaluronique, cette formule agit sur plusieurs couches de ta peau pour retenir l’eau, lisser la texture rugueuse et restaurer un éclat sain. Parfaite pour les peaux sèches ou déshydratées, cette crème type baume crée une barrière protectrice sans sensation de lourdeur ni de gras. Le Super Aqua Ultra Hyalron Balm Cream Original MISSHA laisse ta peau douce, souple et profondément nourrie toute la journée. Recommandé pour : Peaux sèches.', 70, 'ml', 'missha-super-aqua-ultra-hyalron-balm-cream-original', 'https://korean-skincare.fr/products/missha-super-aqua-ultra-hyalron-balm-cream-original', 'https://aurore-cdn.b-cdn.net/products/missha-super-aqua-ultra-hyalron-balm-cream-original.webp', 'Comme dernière étape de ta routine beauté, applique une quantité modérée de produit uniformément sur ton visage et ton cou. Tapote doucement jusqu’à absorption complète. Utilise matin et soir pour de meilleurs résultats.', 2395, '2026-05-07 17:37:38.833413+00', '2026-06-14 15:14:07.486+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64d9-773b-9d29-df3b2def2aa1', '__OWNER_ID__', 'Epitheliale AH Baume Patch Réparateur', 'A-Derma', 'patch', 'tube', 'Caprylic/Capric Triglyceride, Glycerin, HYDROGENATED VEGETABLE OIL, Aqua, Simmondsia Chinensis Seed Oil, Butyrospermum Parkii Butter, SUCROSE LAURATE, Avena Sativa Leaf/Stem Extract, Citric Acid, Helianthus Annuus Seed Oil, Sodium Citrate, Sodium Hyaluronate, Theobroma Grandiflorum Seed Butter, Tocopherol, UNCARIA TOMENTOSA EXTRACT', '', 50, 'g', 'aderma-epitheliale-ah-baume-patch-reparateur', 'https://www.pharmashopdiscount.com/fr/beaute/aderma/aderma-epitheliale-ah-baume-patch-reparateur-50g.html', 'https://aurore-cdn.b-cdn.net/products/aderma-epitheliale-ah-baume-patch-reparateur.webp', '', 1215, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.486+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4290-7e06-af2a-7a459130abfa', '__OWNER_ID__', 'Calming Moisture Repair Balm', 'Pyunkang Yul', 'balm', 'jar', 'Aqua, Propanediol, Squalane, Cetearyl Alcohol, Glycerin, Panthenol, Betaine, Trehalose, Lonicera Japonica Flower Extract, Melaleuca Alternifolia Leaf Extract, Camellia Japonica Flower Extract, Salvia Officinalis Leaf Extract, Helianthus Annuus Seed Oil, Butyrospermum Parkii Butter, Centella Asiatica Extract, Sodium Hyaluronate, Sodium Acetylated Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Acetyl Hexapeptide-8, Palmitoyl Tripeptide-5, Stéarate de Polyglycéryle-2, Glyceryl Stearate, Copolymère d''Acryloyldiméthyltaurate d''Ammonium/Beheneth-25 Méthacrylate, Glucoside de Cétéaryle, Stearyl Alcohol, Sorbitan Olivate, Stearic Acid, Arachidic Acid, Myristic Acid, Oleic Acid, Palmitic Acid, Polydécène Hydrogéné, Taurate de Polyacryloyldiméthyl Taurate de Sodium, Tridéceth-10, Dipropylene Glycol, Myristate de Polyglycéryle-10, Cetyl Ethylhexanoate, Ethylhexyl Palmitate, Caprylic/Capric Triglyceride, Ethylhexylglycerin, Tocopherol, Butylene Glycol, Caprylyl Glycol, Hydroxyacetophenone, Pentylene Glycol, Disodium EDTA, 1,2-Hexanediol', 'Le Calming Moisture Repair Balm Pyunkang Yul est un baume concentré pour soulager et réparer les peaux sensibles et irritées, les laissant apaisées et protégées. Il est infusé d''extraits apaisants pour la peau dérivés de la Centella Asiatica, de l''arbre à thé et de la fleur de chèvrefeuille. Il est également enrichi d''acétyl hexapeptide-8 et de palmitoyl tripeptide-5 pour régénérer la peau agressée et fatiguée.', 30, 'ml', 'pyunkang-yul-calming-moisture-repair-balm', 'https://korean-skincare.fr/products/pyunkang-yul-calming-moisture-repair-balm', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-calming-moisture-repair-balm.webp', 'Après avoir nettoyé ton visage et appliqué un tonique. Applique une quantité appropriée de la crème. Évite la zone du contour des yeux. Masse délicatement sur ta peau.', 1464, '2026-05-07 17:37:39.984678+00', '2026-06-14 15:14:07.487+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42d4-765d-af26-a3ddf35f1701', '__OWNER_ID__', 'Deep Nourishing Multi Balm', 'Pyunkang Yul', 'balm', 'jar', 'Polyglycéryl-2 Triisostéarate, Octyldodecanol, Malate de Diisostéaryle, Butyrospermum Parkii Butter, Euphorbia Cerifera Cera, Huile de Coco Hydrogénée, Bis-Diglycéryl Polyacyladipate-2, Dimère Dilinoléate de Phytostéryl/Isostéaryle/Cétyle/Stéaryle/Béhényle, 1,2-Hexanediol, Polymère Croisé de Vinyl Diméthicone/Méthicone Silsesquioxane, Copolymère de VP/Hexadécène, Microcrystalline Wax, Tocopheryl Acetate, Bisabolol, Helianthus Annuus Seed Oil, Prunus Amygdalus Dulcis Oil, Parfum, Aqua, Butylene Glycol, Ethylhexylglycerin, Rosa Canina Fruit Oil, Persea Gratissima Oil, Macadamia Ternifolia Seed Oil, Adenosine, Caprylic/Capric Triglyceride, Hexyl Cinnamal, Extrait de Perle, Houttuynia Cordata Extract, Extrait de Graine de Phaseolus Radiatus, Linalool, Propylene Glycol, Centella Asiatica Extract, Extrait de Mentha Piperita, Extrait de Rosmarinus Officinalis, Extrait de Salvia Officinalis, Extrait de Chamomilla Recutita, Hydroxycitronellal, Glycerin, Extrait de Miel, Hydrogenated Lecithin, Geraniol, Alpha-Isomethyl Ionone, Limonene, Sodium Hyaluronate, Collagène Hydrolysé, Ceramide NP, Phenoxyethanol', 'Améliore ta routine beauté avec le Deep Nourishing Multi Balm Pyunkang Yul, un baume en stick polyvalent conçu pour nourrir, revitaliser et protéger ta peau. Infusé d''ingrédients respectueux de la peau comme le céramide NP pour réparer la barrière cutanée, des huiles botaniques pour une hydratation en profondeur et un collagène de faible poids moléculaire pour raffermir et repulper, ce baume offre des soins complets dans un format pratique à emporter. Sa formule non collante offre un éclat radieux et sain tout en éclaircissant la peau et atténuant les rides. Parfait pour les styles de vie actifs, ce stick mince et hydratant fournit un soin instantané peu importe où tu te trouves, assurant que ta peau reste douce, lisse et lumineuse tout au long de la journée. Recommandé pour : Peaux sèches, peaux normales à sèches.', 8, 'g', 'pyunkang-yul-deep-nourishing-multi-balm', 'https://korean-skincare.fr/products/pyunkang-yul-deep-nourishing-multi-balm', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-deep-nourishing-multi-balm.webp', 'Applique sur les zones présentant des rides comme le contour des yeux, les rides du sourire et le front. Applique sur ta peau avant le maquillage pour faciliter son application. Peut également être appliqué sur la peau sèche du corps, comme le cou et les coudes.', 1855, '2026-05-07 17:37:40.052246+00', '2026-06-14 15:14:07.487+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4740-7157-ba85-1124a8a6a917', '__OWNER_ID__', 'Vegan Plumping Glow Balm', 'MIXSOON', 'balm', 'jar', 'Hydrogenated Polyisobutene, Dimer Dilinoléate de Phytostéryl/Isostearyl/Cétyl/Stéaryle/Béhényl, Malate de Diisostéaryle, Octyldodecanol, Microcrystalline Wax, Caprylic/Capric Triglyceride, Synthetic Wax, Polyethylene, Butyrospermum Parkii Butter, Acétal de Glycérine de Menthone, Copolymère d’Éthylène/Propylène, Ethylhexyl Palmitate, Tribehenin, Éther de Vanillyl Butyle, Tocopheryl Acetate, Persea Gratissima Fruit Extract, Triisostéarate de Polyglycéryl-2, Sorbitan Isostearate, Sesquioleate de Sorbitane, Huile de Graine de Camellia Oleifera, Lactic Acid, Tripeptide-1 Palmitoylé, BHT, Tocopherol, Rouge 27, Rouge 28 Lake, Jaune 5 Lake', 'Affiche des lèvres naturellement plus pulpeuses et irrésistiblement douces grâce au Vegan Plumping Glow Balm MIXSOON, un baume teinté qui donne une teinte rose pomme juteuse avec un fini radieux et satiné. Enrichi en vanillyl butyl éther pour un effet repulpant délicat et une sensation rafraîchissante, ce baume embellit ta bouche sans irritation. Le beurre de karité nourrissant, l''huile de graines de camélia et l''extrait d''avocat hydratent en profondeur et revitalisent les lèvres, les laissant lisses et souples toute la journée. Recommandé pour : Lèvres sèches et gercées.', 3, 'g', 'mixsoon-vegan-plumping-glow-balm', 'https://korean-skincare.fr/products/mixsoon-vegan-plumping-glow-balm', 'https://aurore-cdn.b-cdn.net/products/mixsoon-vegan-plumping-glow-balm.webp', 'Applique une quantité appropriée de produit sur tes lèvres dès qu''elles sont sèches.', 1695, '2026-05-07 17:37:41.184035+00', '2026-06-14 15:14:07.488+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-477c-75d2-b7c4-53c1132aee00', '__OWNER_ID__', 'Cica Care Balm', 'Rovectin', 'balm', 'jar', 'Aqua, Caprylic/Capric Triglyceride, Propanediol, Glycerin, Stéarate De Sorbitane, Stearyl Alcohol, Cetyl Alcohol, 1,2-Hexanediol, Diméthicone Vinylique, Glyceryl Stearate, Trehalose, Centella Asiatica Extract, Hydrogenated Lecithin, Arginine, Lavandula Hybrida Oil, Madecassoside, Lavandula Angustifolia Oil, Copolymère D’Acrylate D’Hydroxyéthyle/ De Tauraate De Sodium Acryloyldiméthyl, Laurate De Sorbitane, Calamine, Cire D''Abeille Synthétique, Glutamate De Phytostéryl/Octyldodécyle Lauryl, Behenyl Alcohol, Carbomer, Stéarate De Glycol SE, Betaine, Cetearyl Alcohol, Stearic Acid, Copolymère D’Acrylate De Glycéryle/Acide Acrylique, Gomme Xanthane, Protéase, Disodium EDTA', 'Ce baume apaisant et revitalisant cible les peaux les plus sensibles et irritées qui ont été endommagées par des agressions du quotidien, notamment les éruptions hormonales, l''âge et la rosacée. Testé sur peaux sensibles, notre Cica Care Balm guérit et hydrate en douceur les couches les plus profondes de la peau tout en réduisant l''apparence des taches et des cicatrices.', 40, 'ml', 'cica-care-balm', 'https://korean-skincare.fr/products/cica-care-balm', 'https://aurore-cdn.b-cdn.net/products/cica-care-balm.webp', 'Distribue une quantité modérée de crème. Applique-la sur l''ensemble de ton visage et masse délicatement pour une meilleure absorption.', 2995, '2026-05-07 17:37:41.244219+00', '2026-06-14 15:14:07.488+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64d3-7756-9463-4e5da4763301', '__OWNER_ID__', 'Jericho Rose Jelly Collagen Eye Patch', 'Abib', 'patch', 'pack', '1,2-Hexanediol, Adenosine, Allantoin, ANASTATICA HIEROCHUNTICA EXTRACT, Betaine, Butyrospermum Parkii Butter, Caffeine, CALCIUM CHLORIDE, Caprylyl Glycol, Cellulose Gum, Ceramide NP, CERATONIA SILIQUA (CAROB) GUM, CHONDRUS CRISPUS, CHONDRUS CRISPUS POWDER, COLLAGEN EXTRACT, CYAMOPSIS TETRAGONOLOBA (GUAR) GUM, Dipotassium Glycyrrhizate, Ethylhexylglycerin, Glycerin, Hydroxyacetophenone, Niacinamide, PALMITOYL TRIPEPTIDE-5, Panthenol, POLYGLYCERYL-10 LAURATE, POLYGLYCERYL-3 METHYLGLUCOSE DISTEARATE, Potassium Chloride, Propanediol, Ricinus Communis Seed Oil, Sodium Hyaluronate, Sucrose, Trehalose, Aqua', 'Patchs hydrogel raffermissants pour revitaliser et hydrater intensément le contour des yeux.', 90, 'g', 'abib-jericho-rose-jelly-collagen-eye-patch', 'https://www.skinsafeproducts.com/abib-jericho-rose-jelly-collagen-eye-patch-3-17-oz-90-g-30-pairs-pack-of-2', 'https://aurore-cdn.b-cdn.net/products/abib-jericho-rose-jelly-collagen-eye-patch.webp', 'Rose de Jéricho + Collagène + Niacinamide. Idéal pour les regards fatigués et ridules.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.488+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64e1-7491-8333-e236b89b491d', '__OWNER_ID__', 'Under Eye Patches, Hyaluronic Acid & Niacinamide', 'Repair Beauty', 'patch', 'pack', '1,2-Hexanediol, Ascorbic Acid, Betaine, Biotin, Butylene Glycol, Caprylhydroxamic Acid, Caprylyl Glycol, Carbomer, CARNITINE HCL, Dipotassium Glycyrrhizate, Dipropylene Glycol, Disodium EDTA, Ethylhexylglycerin, FOLIC ACID, Parfum, Glycerin, Niacinamide, PANTOTHENIC ACID, POLYGLYCERYL-10 LAURATE, Propanediol, Propylene Glycol, Retinyl Palmitate, RIBOFLAVIN, Sodium Hyaluronate, THIAMINE HCL, Tocopherol, Tromethamine, Aqua, XANTHAN GUM', 'Patchs sous-yeux hydrogel à l"Acide Hyaluronique et à la Niacinamide qui atténuent les cernes, dégonflent les poches et repulpent le contour du regard.', 5, 'ct', 'repair-beauty-under-eye-patches-ha-niacinamide', 'https://www.skinsafeproducts.com/repair-beauty-under-eye-patches-hyaluronic-acid-niacinamide-0-85-oz-25-g-5-pairs', 'https://aurore-cdn.b-cdn.net/products/repair-beauty-under-eye-patches-ha-niacinamide.webp', 'Contient du parfum. Acide Hyaluronique + Niacinamide + Glycyrrhizinate de Dipotassium — Idéal pour peaux avec poches, cernes et regard fatigué.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.488+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64e6-7677-8b78-9980321a17c4', '__OWNER_ID__', 'Super Cica Pads', 'Medicube', 'patch', 'jar', 'Aqua, Glycerin, Butylene Glycol, Propanediol, Pentylene Glycol, Methylpropanediol, Dipropylene Glycol, Centella Asiatica Extract, CENTELLA ASIATICA LEAF EXTRACT, CENTELLA ASIATICA ROOT EXTRACT, ASIATIC ACID, ASIATICOSIDE, MADECASSIC ACID, Madecassoside, Hyaluronic Acid, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Salicylic Acid, Panthenol, Ectoin, GLYCERETH-25 PCA ISOSTEARATE, Glycereth-26, Biosaccharide Gum-1, BLETILLA STRIATA ROOT EXTRACT, Bacillus Ferment, ECHINACEA PURPUREA EXTRACT, Houttuynia Cordata Extract, PERILLA OCYMOIDES LEAF EXTRACT, MELIA AZADIRACHTA FLOWER EXTRACT, Melia Azadirachta Leaf Extract, POLYGLYCERYL-10 OLEATE, Ammonium Polyacryloyldimethyl Taurate, HYDROXYETHYLCELLULOSE, Tromethamine, Hydroxyacetophenone, ETHYL HEXYLGLYCERIN, 12-HEXANEDIOL, Disodium EDTA', 'Pads exfoliants et apaisants à la Centella Asiatica pour apaiser les peaux sensibles et irritées.', 70, 'ct', 'medicube-super-cica-pads', 'https://www.skinsafeproducts.com/medicube-super-cica-pads-5-29-oz-150-g-70-count', 'https://aurore-cdn.b-cdn.net/products/medicube-super-cica-pads.webp', 'Centella Asiatica + Acide Hyaluronique + Ectoin + Acide Salicylique. Idéal pour peaux réactives et sensibles.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.489+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
