INSERT INTO public.products VALUES ('019de0ab-64e1-7392-a914-f931f4861020', '__OWNER_ID__', 'Dermatological Moisturizing Lotion', 'Skin Repair Rx', 'body-lotion', 'bottle', 'Acetylated Lanolin Alcohol, Allantoin, Aloe Barbadensis Leaf Juice, Aqua, ASCORBYL METHYLSILANOL PECTINATE, Butyrospermum Parkii Butter, CETYL ACETATE, EMU OIL, Glyceryl Stearate, GLYCOL STEARATE, Isopropyl Palmitate, PHYTIC ACID, SODIUM DEHYDROACETIC ACID, Sodium Hydroxide, Sodium PCA, Sodium Phytate, Stearic Acid, Tocopheryl Acetate, VEGETABLE GLYCERIN', 'Lotion hydratante dermatologique au Beurre de Karité et à l"huile d''Emu qui apaise, nourrit et restaure le confort des peaux sèches et irritées.', 251, 'ml', 'skin-repair-rx-dermatological-moisturizing-lotion', 'https://www.skinsafeproducts.com/skin-repair-rx-dermatological-moisturizing-lotion-8-5-fl-oz-251-ml', 'https://aurore-cdn.b-cdn.net/products/skin-repair-rx-dermatological-moisturizing-lotion.webp', 'Beurre de Karité + Huile d"Emu + Allantoin + Vitamine C — Idéal pour peaux sèches à très sèches et irritées.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.509+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64e7-73b9-b1b0-b9df2c3fc69b', '__OWNER_ID__', 'Zero Pore Pad (Pore Cleansing)', 'Medicube', 'patch', 'jar', 'Aqua, Glycerin, Butylene Glycol, Propanediol, Methylpropanediol, Pentylene Glycol, Glycereth-26, Hyaluronic Acid, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Sodium Acetylated Hyaluronate, Sodium Hyaluronate Crosspolymer, Hydroxypropyltrimonium Hyaluronate, Gluconolactone, Madecassoside, SACCHARIDE HYDROLYSATE, Panthenol, Camellia Sinensis Leaf Extract, CASTANEA CRENATA (CHESTNUT) SHELL EXTRACT, Centella Asiatica Extract, CYNANCHUM ATRATUM EXTRACT, Cucumis Melo Fruit Extract, DIOSPYROS KAKI FRUIT EXTRACT, HEDERA HELIX (IVY) LEAF/STEM EXTRACT, Houttuynia Cordata Extract, IRIS FLORENTINA ROOT EXTRACT, Oenothera Biennis Flower Extract, Pinus Palustris Leaf Extract, Pueraria Lobata Root Extract, Pyrus Communis Fruit Extract, SALVIA HISPANICA SEED EXTRACT, Ulmus Davidiana Root Extract, Vitis Vinifera Fruit Extract, Rosa Damascena Flower Water, Tromethamine, Ethylhexylglycerin, 1,2-Hexanediol, Disodium EDTA', 'Pads à la Gluconolactone et à la Madecassoside pour purifier, hydrater et refiner le grain de peau en douceur.', 70, 'ct', 'medicube-zero-pore-pad-pore-cleansing', 'https://www.skinsafeproducts.com/medicube-zero-pore-pad-5-46-oz-155g-count-70', 'https://aurore-cdn.b-cdn.net/products/medicube-zero-pore-pad-pore-cleansing.webp', 'Gluconolactone (PHA) + Madecassoside + Acide Hyaluronique multi-poids + Eau de Rose. Idéal pour peaux sensibles cherchant exfoliation douce et hydratation.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.489+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6587-7cd0-8fec-38ca746b53b4', '__OWNER_ID__', 'Age Specific Intensif Patch Lift Regard 360 Bio', 'Patyka', 'patch', 'pack', 'Aqua, HORDEUM VULGARE STEM WATER*, Glycerin, Carraghenane, Propanediol, AMORPHOPHALLUS KONJAC ROOT EXTRACT, GLUCOSE**, Phenethyl Alcohol, SODIUM LEVULINATE, p-Anisic Acid, LEVULINIC ACID, ACMELLA OLERACEA EXTRACT, Avena Sativa Kernel Extract, GLYCOGEN, Sodium Hyaluronate, Sodium Hydroxide, GENTIANA LUTEA ROOT EXTRACT*, Maltodextrin, HYDROLYZED GARDENIA FLORIDA EXTRACT, SODIUM BENZOATE [L7Y240104], Aqua, BARLEY STEM WATER, GREEN MIMOSA, JOJOBA AND SUNFLOWER WAXES, POLYGLYCERYL-3 ESTERS, CARRAGEENAN GUM, 1,3-PROPANEDIOL, KONJAC ROOT EXTRACT, GLUCOSE, Phenethyl Alcohol, SODIUM LEVULINATE, p-Anisic Acid, LEVULINIC ACID, MAFANE OR PARA CRESS EXTRACT, OAT KERNEL EXTRACT, GLYCOGEN, Sodium Acetylated Hyaluronate, Sodium Hydroxide, GENTIAN ROOT EXTRACT, ALOE LEAF EXTRACT AND MALTODEXTRIN, HYDROLYZED CAPE JASMINE EXTRACT, SODIUM BENZOATE. *INGREDIENTS FROM ORGANIC FARMING', 'PATYKA AGE SPECIFIC INTENSIF PATCH LIFT REGARD 360 BIo en vente en ligne, sur le site de votre parapharmacie à prix discount, est le soin idéal pour revitaliser le contour de vos yeux.
INSERT INTO public.products VALUES ('019e0384-3c03-7a36-8e32-f29320272edb', '__OWNER_ID__', 'Master Patch Intensive', 'COSRX', 'patch', 'pack', 'Cellulose Gum, Hydrogenated Poly(C6-14 Olefin), Polyisobutene, Copolymère Styrène/Isoprène, Salicylic Acid, Melaleuca Alternifolia Leaf Oil', 'Le Master Patch Intensive COSRX est exactement comme le patch anti-boutons original, mais encore mieux. Le Master Patch Intensive se fond parfaitement avec n''importe quel teint de peau pour une apparence discrète. Il s''agit d''un traitement ponctuel confortable pour traiter tes éruptions cutanées imprévues. Les patchs hydrocolloïdes contre l''acné absorbent efficacement le pus des boutons et les protègent contre toute nouvelle infection due à des bactéries extérieures et autres. Le patch se présente sous une forme ronde et plate, et peut être porté sous le maquillage.', 36, 'pcs', 'cosrx-master-patch-intensive', 'https://korean-skincare.fr/products/cosrx-master-patch-intensive', 'https://aurore-cdn.b-cdn.net/products/cosrx-master-patch-intensive.webp', 'Lave-toi soigneusement le visage avec un produit nettoyant. Colle le patch sur ta peau sèche avant de procéder à tes soins. Au bout de 8 à 10 heures, le patch deviendra blanc après avoir absorbé le pus et les impuretés. Lorsqu''il devient blanc, enlève-le délicatement. Remplace-le ensuite par un nouveau.', 1069, '2026-05-07 17:37:38.307583+00', '2026-06-14 15:14:07.49+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c2a-737d-bf3c-eae2cf053e4d', '__OWNER_ID__', 'Master Patch Basic', 'COSRX', 'patch', 'pack', 'Cellulose Gum, Hydrogenated Poly(C6-14 Olefin), Polyisobutene, Copolymère Styrène/Isoprène', 'Le Master Patch Basic COSRX est exactement comme le patch anti-boutons original, mais encore mieux. Il s''agit d''un traitement ponctuel confortable pour traiter tes éruptions cutanées imprévues. Les patchs hydrocolloïdes contre l''acné absorbent efficacement le pus des boutons et les protègent contre toute nouvelle infection due à des bactéries extérieures et autres. Le patch se présente sous une forme ronde et plate, et peut être porté sous le maquillage.', 90, 'pcs', 'cosrx-master-patch-basic', 'https://korean-skincare.fr/products/cosrx-master-patch-basic', 'https://aurore-cdn.b-cdn.net/products/cosrx-master-patch-basic.webp', 'Lave-toi soigneusement le visage avec un produit nettoyant. Colle le patch sur ta peau sèche avant de procéder à tes soins. Au bout de 8 à 10 heures, le patch deviendra blanc après avoir absorbé le pus et les impuretés. Lorsqu''il devient blanc, enlève-le délicatement. Remplace-le ensuite par un nouveau.', 1782, '2026-05-07 17:37:38.346047+00', '2026-06-14 15:14:07.49+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c44-7436-a958-85e98a67e352', '__OWNER_ID__', 'Master Patch X-Large', 'COSRX', 'patch', 'pack', 'Cellulose Gum, Hydrogenated Poly(C6-14 Olefin), Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Polyisobutene, Copolymère Styrène/Isoprène, Niacinamide', 'Le Master Patch X-Large COSRX est un patch hydrocolloïde confortable pour résoudre les problèmes de pores huileux sur une surface large. Il s''agit d''un traitement ponctuel confortable pour traiter tes éruptions cutanées imprévues. Les patchs hydrocolloïdes contre l''acné absorbent efficacement le pus des boutons et les protègent contre toute nouvelle infection due à des bactéries extérieures et autres.', 10, 'pcs', 'cosrx-master-patch-x-large', 'https://korean-skincare.fr/products/cosrx-master-patch-x-large', 'https://aurore-cdn.b-cdn.net/products/cosrx-master-patch-x-large.webp', 'Lave-toi soigneusement le visage avec un produit nettoyant. Colle le patch sur ta peau sèche avant de procéder à tes soins. Au bout de 8 à 10 heures, le patch deviendra blanc après avoir absorbé le pus et les impuretés. Lorsqu''il devient blanc, enlève-le délicatement. Remplace-le ensuite par un nouveau.', 1585, '2026-05-07 17:37:38.37215+00', '2026-06-14 15:14:07.49+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c0e-724c-aa31-b2dd97b7e7ca', '__OWNER_ID__', 'AC Collection Acne Patch', 'COSRX', 'patch', 'pack', 'Cellulose Gum, Polyisobutene, Rosin, Polyisobutene, Paraffinum Liquidum, Centella Asiatica Extract, Polyurethane Film', 'AC Collection Acne Patch COSRX est un patch hydrocolloïde ovale très adhésif qui aide à traiter et à réduire l''apparence de l''acné. Le bord de chaque patch est biseauté pour assurer une adhésion solide et rapide aux zones courbées du visage, comme la mâchoire, le front et même le corps. Chaque patch est également conçu pour calmer et apaiser la peau grâce à la présence de Centella Asiatica.', 26, 'pcs', 'cosrx-ac-collection-acne-patch', 'https://korean-skincare.fr/products/cosrx-ac-collection-acne-patch', 'https://aurore-cdn.b-cdn.net/products/cosrx-ac-collection-acne-patch.webp', 'Nettoie la zone autour du bouton à traiter. Utilise le patch après avoir exfolié ta peau ou avant l''étape du tonique. Choisis un patch de taille supérieure à celle de l''imperfection à traiter. Place le patch sur une peau sèche.', 474, '2026-05-07 17:37:38.31809+00', '2026-06-14 15:14:07.49+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3df4-797b-948a-b4b71137903c', '__OWNER_ID__', 'Speedy Solution Anti Trouble Patch Set', 'MISSHA', 'patch', 'pack', 'Acrylates Copolymer, Alcohol Denat, Vinyl Caprolactam/VP/Dimethylaminoethyl Methacrylate Copolymer, Melaleuca Alternifolia Leaf Oil, PVP, Aqua, Alcohol, Butylene Glycol, Vitis Vinifera Seed Extract, Salicylic Acid, Allantoin, Polysorbate 80, Methylparaben, Sodium Hyaluronate, Phytosphingosine', 'Le Speedy Solution Anti Trouble Patch Set MISSHA est un ensemble de soins ciblés pour les imperfections, conçu pour apaiser et protéger les boutons tout en favorisant une peau plus pure. Ces patchs hydrocolloïdes adhèrent à la peau pour absorber les impuretés et créer une barrière qui aide à prévenir le grattage et les irritations supplémentaires. Chaque patch agit comme un bouclier contre les bactéries nocives, minimisant le risque d’apparition de nouvelles imperfections et gardant ta peau protégée et nourrie toute la journée et la nuit. Recommandé pour : Tous types de peaux, en particulier les peaux sujettes aux imperfections ou aux poussées d’acné.', NULL, NULL, 'missha-speedy-solution-anti-trouble-patch-set', 'https://korean-skincare.fr/products/missha-speedy-solution-anti-trouble-patch-set', 'https://aurore-cdn.b-cdn.net/products/missha-speedy-solution-anti-trouble-patch-set.webp', 'Nettoie et sèche la zone concernée. Applique un patch directement sur l’imperfection. Porte-le pendant plusieurs heures ou toute la nuit, puis retire doucement et jette-le. Remplace-le au besoin jusqu’à amélioration de l’imperfection.', 395, '2026-05-07 17:37:38.804364+00', '2026-06-14 15:14:07.491+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-410f-7883-9407-8e53fdd9da4a', '__OWNER_ID__', 'Wonder Releaf Centella Spot Patch', 'Purito Seoul', 'patch', 'pack', 'Cellulose Gum, Glyceryl Rosinate, Polyisobutene, Styrene/Isoprene Copolymer, Centella Asiatica Extract, Madecassic Acid, Asiaticoside, Asiatic Acid, Aqua, Butylene Glycol, 1,2-Hexanediol', 'Le patch Purito SEOUL Wonder Releaf Centella Spot est un patch mince et respirant conçu pour traiter et apaiser efficacement les imperfections de la peau. Grâce à un mélange de Centella Asiatica coréenne résistante, ce patch offre un effet apaisant puissant et naturel, calmant les zones irritées tout en gardant la peau propre et claire. Il adhère discrètement à la peau grâce à son design fin et discret qui offre une couverture d''apparence naturelle, ce qui permet de le porter confortablement pendant la journée ou la nuit. Recommandé pour : Tous les types de peau, sans danger pour l''acné fongique.', 51, 'pcs', 'purito-wonder-releaf-centella-spot-patch', 'https://korean-skincare.fr/products/purito-wonder-releaf-centella-spot-patch', 'https://aurore-cdn.b-cdn.net/products/purito-wonder-releaf-centella-spot-patch.webp', 'Sur une peau nettoyée et sèche, appliquer un patch plus grand que la zone à problème. Attendre 4 à 8 heures ou jusqu''à ce que le patch devienne blanc avant de le retirer et de le remplacer si nécessaire. Il peut être utilisé pendant la journée ou la nuit.', 831, '2026-05-07 17:37:39.599346+00', '2026-06-14 15:14:07.491+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-653c-7b1b-b7bc-4144cb69b2dc', '__OWNER_ID__', 'Topialyse Crème', 'SVR', 'body-lotion', 'tube', 'Aqua, Butyrospermum Parkii Butter, ORBIGNYA OLEIFERA SEED OIL, Glycerin, C10-18 TRIGLYCERIDES, Cocos Nucifera Oil, Pentylene Glycol, GLYCERYL STEARATE CITRATE, Glyceryl Stearate SE, Borago Officinalis Seed Oil, GLYCERYL GLUCOSIDE, Glycine Soja Oil, SODIUM STEAROYL GLUTAMATE, Alpha-Glucan Oligosaccharide, Tocopherol, 1,2-Hexanediol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Caprylyl Glycol, Citric Acid, Sodium Hydroxide, Parfum', 'Crème nourrissante et apaisante pour peaux sèches et sensibles. Hydratation 48h, élimine les sensations de tiraillements, texture velours non grasse.
INSERT INTO public.products VALUES ('019de0ab-64d7-7bb7-869c-33badf88472a', '__OWNER_ID__', 'Exomega Control Spray Emollient ANTI Grattage', 'A-Derma', 'body-lotion', 'spray', 'Aqua, Caprylic/Capric Triglyceride, Glycerin, Polyglyceryl-2 Dipolyhydroxystearate, Butyrospermum Parkii Butter, Niacinamide, 10-HYDROXYDECENOIC ACID, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Avena Sativa Leaf/Stem Extract, Benzoic Acid, Caprylyl Glycol, Cetearyl Alcohol, CETEARYL GLUCOSIDE, LAURYL GLUCOSIDE, NITROGEN, Oenothera Biennis Oil, Sodium Citrate, Sodium Hydroxide, SODIUM LAURYL GLUCOSE CARBOXYLATE, Sorbic Acid, Tocopherol, Tocopheryl Acetate, XANTHAN GUM', '', 200, 'ml', 'aderma-exomega-control-spray-emollient-anti-grattage', 'https://www.pharmashopdiscount.com/fr/beaute/aderma/aderma-exomega-control-spray-emollient-anti-grattage-200ml.html', 'https://aurore-cdn.b-cdn.net/products/aderma-exomega-control-spray-emollient-anti-grattage.webp', '', 1818, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.491+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-41b3-759b-8d62-65feba773e43', '__OWNER_ID__', 'Onion Newpair Spot Patch Skin Fit', 'ISNTREE', 'patch', 'pack', 'Polyisobutene, Cellulose Gum, Aqua, Butylene Glycol, Niacinamide, 1,2-Hexanediol, Extrait de bulbe d''Allium Cepa', 'L''Onion Newpair Spot Patch Skin Fit Isntree est le nec plus ultra en matière de traitement anti-acné. Ces patchs hydrocolloïdes, dotés d''un bord biseauté pour se fondre parfaitement dans la peau, sont imperméables mais respirants, créant un environnement optimal pour la guérison de l''acné. Leur conception ultra-mince et transparente assure un placement discret et confortable. Formulés avec de l''extrait d''oignon Muan et de la niacinamide, ces patchs n''absorbent pas seulement le pus, mais offrent également des avantages anti-inflammatoires, accélérant ainsi le processus de guérison. Adaptés aux peaux à tendance acnéique, ces patchs ont subi des tests d''irritation cutanée, offrant une solution fiable à ceux qui recherchent un soin efficace et discret contre les imperfections.', 15, 'pcs', 'isntree-onion-newpair-spot-patch-skin-fit', 'https://korean-skincare.fr/products/isntree-onion-newpair-spot-patch-skin-fit', 'https://aurore-cdn.b-cdn.net/products/isntree-onion-newpair-spot-patch-skin-fit.webp', 'Lave-toi soigneusement le visage avec un nettoyant. Colle le patch sur la peau sèche avant de procéder à ta routine beauté. Au bout de 8 à 10 heures, le patch deviendra blanc après avoir absorbé le pus et les impuretés. Quand il devient blanc, enlève-le délicatement.', 395, '2026-05-07 17:37:39.763173+00', '2026-06-14 15:14:07.492+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6503-794d-aedf-f83659dd5e22', '__OWNER_ID__', 'Lait Corps Sublimateur 10% AHA', 'Paula''s Choice', 'body-lotion', 'pump', 'Aqua, Glycolic Acid, Cyclopentasiloxane, Dimethicone, Glycerin, Glyceryl Stearate, Cetyl Alcohol, Butyrospermum Parkii Butter, Stearic Acid, Sodium Hydroxide, PEG-100 Stearate, XANTHAN GUM, Ascorbyl Tetraisopalmitate, Tocopheryl Acetate, Disodium EDTA, Butylene Glycol, Allantoin, Chamomilla Recutita (Matricaria) Flower Extract, Vitis Vinifera Seed Oil, CAMELLIA OLEIFERA LEAF EXTRACT, EPILOBIUM ANGUSTIFOLIUM EXTRACT, Methylparaben, BUTYLPARABEN, ETHYLPARABEN, Propylparaben, Phenoxyethanol, Sodium Benzoate', 'Lait corps exfoliant au glycolic acid (10% AHA) qui élimine les cellules mortes, lisse la peau et améliore l''apparence de la kératose pilaire, des taches et de la peau sèche.', 210, 'ml', 'paula-choice-lait-corps-10-aha', 'https://www.paulaschoice.com', NULL, '10% acide glycolique (AHA) pour exfoliation chimique. Contient beurre de karité, antioxydants (vitamine C, vitamine E, thé vert) et agents apaisants (allantoïne, camomille).', 3120, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.513+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-423e-72c3-93a7-8f7168b24e52', '__OWNER_ID__', 'ACNE Spot Patch Super Thin', 'Pyunkang Yul', 'patch', 'pack', 'Polyisobutene, Polyuréthane-9, Polyisoprène, Cellulose Gum', 'L''ACNE Spot Patch Super Thin Pyunkang Yul est un patch hydrocolloïde qui aide à traiter l''acné ou les imperfections en formant une pellicule d''apparence naturelle et imperceptible. Ces patchs protègent les zones touchées par l''acné et aident à guérir rapidement les imperfections tout en minimisant les cicatrices et en maintenant l''hydratation de la peau. Contrairement à la plupart des patchs anti-imperfections, ces patchs ultrafins résistent à la sueur et à l''eau. Recommandé pour : Peaux à tendance grasse et acnéique. Peut être utilisé pour : Tous types de peau. Conseils d''application : Nettoie ton visage avec un nettoyant. Place le patch sur ta peau sèche avant de continuer ta routine beauté. Au bout de 8 à 10 heures, le patch devient blanc après avoir absorbé le pus et les impuretés. Lorsqu''il devient blanc, retire-le délicatement. Remplace-le ensuite par un nouveau patch.', 15, 'pcs', 'pyunkang-yul-acne-spot-patch-super-thin', 'https://korean-skincare.fr/products/pyunkang-yul-acne-spot-patch-super-thin', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-acne-spot-patch-super-thin.webp', NULL, 279, '2026-05-07 17:37:39.902051+00', '2026-06-14 15:14:07.492+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42a1-7bc0-b1de-4dd5eb3ec568', '__OWNER_ID__', 'Clear Spot Patch', 'Pyunkang Yul', 'patch', 'pack', 'Ruban adhésif hydrocolloïde', 'Voici notre Clear Spot Patch, une solution discrète et efficace pour le traitement ciblé des imperfections. Infusé de puissants ingrédients anti-acné, ce patch transparent crée une barrière protectrice tout en diffusant des ingrédients actifs en profondeur dans la peau. Il absorbe l''excès de sébum, réduit l''inflammation et accélère la guérison, minimisant ainsi l''apparence des imperfections. Dis adieu aux boutons indésirables et bonjour à une peau claire et radieuse grâce à nos Clear Spot Patch.', 18, 'pcs', 'pyunkang-yul-clear-spot-patch', 'https://korean-skincare.fr/products/pyunkang-yul-clear-spot-patch', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-clear-spot-patch.webp', 'Après avoir nettoyé la zone à problèmes, applique le patch sur ta peau. Appuie sur la zone pendant 2 à 3 secondes. Retire le patch une fois qu''il est devenu blanc.', 495, '2026-05-07 17:37:40.001595+00', '2026-06-14 15:14:07.492+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42e0-7efc-9f13-9374360056c6', '__OWNER_ID__', 'Calming Clear Spot Patch (Intensive Care + Slim Care)', 'Pyunkang Yul', 'patch', 'pack', 'Cellulose Gum, Hydrogenated Poly(C6-14 Olefin), Polyisobutene, Copolymère de Styrène/Isoprène, Salicylic Acid, Melaleuca Alternifolia Leaf Oil, Houttuynia Cordata Extract, Niacinamide, Extrait Titré de Centella', 'Combats efficacement les imperfections avec le Calming Clear Spot Patch Pyunkang Yul, une solution anti-acné à double usage conçue pour un traitement intensif et une protection discrète. Ces patchs hydrocolloïdes sont infusés d''acide salicylique pour un traitement anti-acné ciblé, tandis que les extraits de cica et de Houttuynia Cordata apaisent et calment la peau irritée. Chaque emballage comprend des patchs Intensive Care (0,2 mm d''épaisseur) pour les imperfections plus importantes et des patchs Slim Care (0,1 mm d''épaisseur) pour une protection presque invisible des boutons. Avec des bords biseautés pour une adhérence parfaite, ces patchs protègent contre les facteurs d''irritation externes tout en absorbant les impuretés, ce qui aide à guérir les imperfections rapidement et efficacement. Recommandé pour : Peaux à tendance acnéique, tous types de peaux.', 124, 'pcs', 'pyunkang-yul-calming-clear-spot-patch-intensive-care-slim-care', 'https://korean-skincare.fr/products/pyunkang-yul-calming-clear-spot-patch-intensive-care-slim-care', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-calming-clear-spot-patch-intensive-care-slim-care.webp', 'Applique sur peau propre et appuie pendant 2 à 3 secondes pour favoriser une meilleure adhérence. Retire le patch lorsqu''il devient blanc après absorption du pus.', 1495, '2026-05-07 17:37:40.06477+00', '2026-06-14 15:14:07.492+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44fd-7e29-8adc-994aae733570', '__OWNER_ID__', 'Micro Pin Spot Patch', 'SOME BY MI', 'patch', 'pack', 'Trehalose, Cellulose Gum, Hydrolyzed Hyaluronic Acid, Glycerin, Sodium Hyaluronate, Niacinamide, Melaleuca Alternifolia Leaf Water, Madecassoside, Aqua, Salicylic Acid, Butylene Glycol, Polyglycéryl-10 laurate, 1,2-Hexanediol, Éthyl hexanediol, Centella Asiatica Extract, Asiaticoside, Acide asiatique, Acide madécassique, Extrait d''Artemisia Vulgaris', 'Le Micro Pin Spot Patch SOME BY MI est conçu comme un soin ciblé contre l''acné, utilisant des micro-aiguilles enduites d''acide hyaluronique et de Truecica™ pour apporter des bienfaits apaisants et hydratants directement sur les peaux à problèmes. Formulé avec de l''acide salicylique et du niacinamide, ce patch s''attaque efficacement à l''acné en contrôlant la production de sébum et en réduisant les traces d''imperfections, pour aider à retrouver un teint lisse et clair. Idéal pour les peaux à tendance acnéique, ce patch associe le pouvoir hydratant de l''acide hyaluronique et du Truecica™ aux propriétés purifiantes de l''acide salicylique et du niacinamide pour un soin complet de la peau. Recommandé pour : Peau à tendance acnéique, tous types de peaux.', 9, 'pcs', 'some-by-mi-micro-pin-spot-patch', 'https://korean-skincare.fr/products/some-by-mi-micro-pin-spot-patch', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-micro-pin-spot-patch.webp', 'Assure-toi que la zone à traiter soit propre et sèche. Décolle un patch anti-bouton de la feuille et applique-le directement sur le bouton ou l''imperfection ciblée. Appuie fermement pendant au moins 3 secondes. Après avoir porté le patch pendant plus de 4 heures, retire-le délicatement.', 1072, '2026-05-07 17:37:40.605726+00', '2026-06-14 15:14:07.506+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-45b2-78af-8de3-c3a50ff08f24', '__OWNER_ID__', 'Triple Acid Spot Care Microdart Patch', 'Anua', 'patch', 'pack', 'Sodium Hyaluronate, Lactate de Zinc, Acide Succinique, Centella Asiatica Extract, Gluconolactone, Pentylene Glycol, Lactic Acid, Glycolic Acid, Madecassoside, Butylene Glycol, Glycolate de Sodium, Sodium Lactate, Salicylic Acid, 1,2-Hexanediol, Salicylate de Sodium', 'Le Triple Acid Spot Care Microdart Patch Anua est un patch anti-imperfections ciblé de nouvelle génération, conçu pour traiter les boutons rapidement et efficacement grâce à la technologie des micro-aiguilles. Chaque patch contient des micro-aiguilles ultra-fins et solubles, imprégnés d’un Complexe Triple Acide, afin de réduire l’apparence des imperfections actives, désobstruer les pores et améliorer la texture globale de la peau. Contrairement aux patchs hydrocolloïdes classiques qui agissent uniquement en surface, les micro-aiguilles délivrent les actifs directement au cœur de la zone concernée pour un soin plus intensif. Le patch adhère confortablement à la peau, aide à protéger l’imperfection des bactéries et du grattage, et favorise un apaisement visible plus rapide, ce qui le rend idéal pour les boutons profonds, tenaces ou sous-cutanés. Recommandé pour : Sans risque pour l''acné fongique, peaux à tendance acnéique, tous types de peaux.', 12, 'pcs', 'anua-triple-acid-spot-care-microdart-patch', 'https://korean-skincare.fr/products/anua-triple-acid-spot-care-microdart-patch', 'https://aurore-cdn.b-cdn.net/products/anua-triple-acid-spot-care-microdart-patch.webp', 'Nettoie et sèche parfaitement la zone ciblée. Applique le patch directement sur l’imperfection et appuie fermement pendant quelques secondes. Laisse poser pendant 4 à 8 heures (ou toute la nuit). Retire délicatement et poursuis ta routine de soin habituelle.', 1095, '2026-05-07 17:37:40.786358+00', '2026-06-14 15:14:07.506+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-45c1-789c-94cd-2757c55468fd', '__OWNER_ID__', 'Ultra Thin Spot Cover Patch', 'Anua', 'patch', 'pack', 'Polyisobutene, Cellulose Gum, Aqua, Glycerin, Caprylic/Capric Triglyceride, Butylene Glycol, 1,2-Hexanediol, Hydrogenated Lecithin, Aloe Barbadensis Leaf Extract, Centella Asiatica Extract, Ceramide NP, Cholesterol, Madecassoside', 'Dissimule et traite tes imperfections sans effort avec les Ultra Thin Spot Cover Patches Anua. Ces patchs ultra-fins et homogènes constituent une barrière protectrice contre les bactéries et les polluants environnementaux tout en absorbant l''excès de sébum et les fluides pour un traitement efficace des imperfections. Infusés de céramides NP pour soutenir la barrière cutanée et d''extrait de centella pour apaiser les irritations et favoriser la cicatrisation, ils offrent un soin à la fois délicat et puissant pour les peaux à tendance acnéique. Avec 75 patchs en deux tailles polyvalentes, ils sont parfaits pour un traitement discret et ciblé qui calme et restaure ta peau. Recommandé pour : Sans risque pour l''acné fongique, peaux sensibles, tous types de peaux.', 75, 'pcs', 'anua-ultra-thin-spot-cover-patch', 'https://korean-skincare.fr/products/anua-ultra-thin-spot-cover-patch', 'https://aurore-cdn.b-cdn.net/products/anua-ultra-thin-spot-cover-patch.webp', 'Nettoie délicatement la zone où le patch sera appliqué et laisse-la sécher complètement. Décolle le patch de la taille appropriée et applique-le au centre de la tache. Remplace le patch lorsqu''il devient blanc à cause des résidus de l''imperfection.', 1595, '2026-05-07 17:37:40.801391+00', '2026-06-14 15:14:07.506+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64db-7081-9a99-3da589cba7cf', '__OWNER_ID__', 'Les Indispensables Lait Corps Hydratation 72h', 'A-Derma', 'body-lotion', 'pump', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, Isopropyl Palmitate, Propylene Glycol, C14-22 Alcohols, Dimethicone, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, AVENA SATIVA (OAT) SPROUT OIL, Benzoic Acid, C12-20 ALKYL GLUCOSIDE, C20-22 ALCOHOLS, C20-22 ALKYL PHOSPHATE, Caprylyl Glycol, Parfum, Polysorbate 60, Sodium Hyaluronate, Sodium Hydroxide, Sorbitan Isostearate, Squalane, Tocopheryl Acetate, XANTHAN GUM', 'Lait corps hydratation longue durée pour peaux fragiles, enrichi en acide hyaluronique.', 400, 'ml', 'aderma-lait-corps-72h', NULL, 'https://aurore-cdn.b-cdn.net/products/aderma-lait-corps-72h.webp', '92% origine naturelle. Convient dès 2 ans. Vegan. Délicatement parfumé.', 1119, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.507+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64db-72ca-b448-adaa38eac041', '__OWNER_ID__', 'Exomega Control Lait Émollient Anti-Grattage', 'A-Derma', 'body-lotion', 'pump', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, Glyceryl Stearate, Niacinamide, PEG-100 Stearate, 10-HYDROXYDECENOIC ACID, Avena Sativa Leaf/Stem Extract, Benzoic Acid, Caprylyl Glycol, Carbomer, Cetearyl Alcohol, CETEARYL GLUCOSIDE, Oenothera Biennis Oil, POLYACRYLATE-13, Polyisobutene, Polysorbate 20, Sodium Hydroxide, Sorbitan Isostearate, Tocopherol, Tocopheryl Acetate', 'Soin triple apaisement pour peaux sèches à tendance atopique, réduit les démangeaisons.', 400, 'ml', 'aderma-lait-emollient', NULL, 'https://aurore-cdn.b-cdn.net/products/aderma-lait-emollient.webp', '95% origine naturelle. Sans parfum. Dès la naissance. 1 application/jour.', 1908, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.507+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64d6-7bfb-8209-3b7c162df6c8', '__OWNER_ID__', 'Exomega Control LAIT Emollient Anti-grattage', 'A-Derma', 'body-lotion', 'bottle', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, Glyceryl Stearate, Niacinamide, PEG-100 Stearate, 10-HYDROXYDECENOIC ACID, Avena Sativa Leaf/Stem Extract, Benzoic Acid, Caprylyl Glycol, Carbomer, Cetearyl Alcohol, CETEARYL GLUCOSIDE, Oenothera Biennis Oil, POLYACRYLATE-13, Polyisobutene, Polysorbate 20, Sodium Hydroxide, Sorbitan Isostearate, Tocopherol, Tocopheryl Acetate', '', 400, 'ml', 'a-derma-exomega-control-lait-emollient-anti-grattage', 'https://www.pharmashopdiscount.com/fr/beaute/aderma/a-derma-exomega-control-lait-emollient-anti-grattage-400ml.html', 'https://aurore-cdn.b-cdn.net/products/a-derma-exomega-control-lait-emollient-anti-grattage.webp', '', 1954, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.507+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64fd-7631-b457-fdfd0e7c242f', '__OWNER_ID__', 'UreaRepair PLUS Lotion 10%', 'Eucerin', 'body-lotion', 'pump', 'Aqua, Urea, Glycerin, ISOPROPYL STEARATE, Dicaprylyl Ether, GLYCERYL GLUCOSIDE, Sodium Lactate, Butyrospermum Parkii Butter, Tapioca Starch, POLYGLYCERYL-4 DIISOSTEARATE/POLYHYDROXYSTEARATE/SEBACATE, CARNITINE, Cetearyl Alcohol, Ceramide NP, ARGININE HCL, Sodium PCA, HISTIDINE, ALANINE, CITRULLINE, Lysine, SERINE, Lactic Acid, Sodium Chloride, Mannitol, Sucrose, Glutamic Acid, THREONINE, GLYCOGEN, 1,2-Hexanediol, Phenoxyethanol, Potassium Sorbate, ARGININE, PCA', 'Lotion corporelle riche en urée (10%) pour peaux très sèches, rugueuses et squameuses. Apaise immédiatement, lisse en profondeur et hydrate 48h.', 400, 'ml', 'eucerin-urearepair-plus-lotion-10', 'https://int.eucerin.com', 'https://aurore-cdn.b-cdn.net/products/eucerin-urearepair-plus-lotion-10.webp', '4.6 ★. 10% urée (exfoliation + hydratation). Céramides + NMF. Effet lissant visible rapidement. Sans parfum. Convient aux diabétiques et au psoriasis léger.', 2250, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.508+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64fd-777b-a907-0de9e680d861', '__OWNER_ID__', 'AtopiControl Baume', 'Eucerin', 'body-lotion', 'pump', 'Aqua, Glycerin, Panthenol, Caprylic/Capric Triglyceride, Dicaprylyl Ether, Olea Europaea Fruit Oil, Ricinus Communis Seed Oil, POLYGLYCERYL-3 POLYRICINOLEATE, GLYCERYL GLUCOSIDE, Oenothera Biennis Oil, Borago Officinalis Seed Oil, Ceramide NP, Glycyrrhiza Inflata Root Extract, DECYLENE GLYCOL, Glycine Soja Oil, Tocopherol, Ascorbyl Palmitate, Magnesium Sulfate, Sodium Citrate, Citric Acid', 'Baume relipidant intensif pour peau atopique (eczéma). Apaise immédiatement les démangeaisons, renforce la barrière et espace les poussées inflammatoires.', 400, 'ml', 'eucerin-atopicontrol-baume', 'https://int.eucerin.com', 'https://aurore-cdn.b-cdn.net/products/eucerin-atopicontrol-baume.webp', '4.8 ★. Licochalcone A (anti-inflammatoire) + Céramides + Oméga-6. Sans parfum ni conservateurs. Convient aux bébés dès 3 mois. Texture riche non collante.', 2600, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.508+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6503-7b6a-a597-dd5f5fc9d832', '__OWNER_ID__', 'UR-10 Crème Lissante Anti-Rugosités', 'Topicrem', 'body-lotion', 'pump', 'Aqua, Paraffinum Liquidum, Urea, Cera Alba, CETEARYL ETHYLHEXANOATE, ISOPROPYL ISOSTEARATE, Palmitic Acid, Stearic Acid, Isopropyl Myristate, Phenoxyethanol, Glyceryl Stearate, PEG-100 Stearate, Carbomer, Chlorphenesin, Sodium Hydroxide, Parfum', 'Crème corps lissante anti-rugosités pour les "peaux de croco". Concentration modérée en urée (10%) associée à la cire d''abeille pour rétablir l''hydratation, restaurer le film protecteur et nourrir intensément les peaux extra-sèches.', 500, 'ml', 'topicrem-ur-10-creme-lissante-500ml', 'https://pharmacie-citypharma.fr/fr/topicrem-ur10-creme-lissante-a-rugosites-500ml', 'https://aurore-cdn.b-cdn.net/products/topicrem-ur-10-creme-lissante-500ml.webp', '10% d''urée - concentration adaptée pour un usage corporel régulier. Texture épaisse et nourrissante. Contient parfum. Ne pas appliquer sur le visage, les lésions ou les enfants <3 ans.', 1678, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.508+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6503-7fbb-b089-431e5d76a4ad', '__OWNER_ID__', 'Ureadin Ultra 20 Crème Ultra-Hydratante', 'ISDIN', 'body-lotion', 'tube', 'Aqua, Urea, Isopropyl Myristate, Paraffinum Liquidum, Glyceryl Stearate, PEG-40 Stearate, Sorbitol, CETEARYL ETHYLHEXANOATE, Cetyl Alcohol, Dimethicone, GLYCINE, Phenoxyethanol, Persea Gratissima Oil, Carbomer, Allantoin, Palmitic Acid, Stearic Acid, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Disodium EDTA, Ethylhexylglycerin, Parfum, Sodium Hydroxide, Limonene, Hexyl Cinnamal, Lactic Acid, Alpha-Isomethyl Ionone, Linalool, Benzyl Salicylate, Eugenol, Citral, Hydroxycitronellal, Coumarin', 'Crème réparatrice réduisant les aspérités et rugosités grâce à l''action exfoliante de l''Urée ISDIN 20%. Hydrate intensément et restaure la barrière cutanée. Texture onctueuse non grasse à absorption rapide.', 100, 'ml', 'isdin-ureadin-ultra-20-creme', 'https://www.isdin.com/fr/ureadin-ultra-20', 'https://aurore-cdn.b-cdn.net/products/isdin-ureadin-ultra-20-creme.webp', 'Urée ISDIN 20% - concentration optimale pour l''entretien des peaux très sèches. Enrichie en huile d''avocat et Allantoïne. Système de défense cutanée renforcé. Parfum subtil présent.', 1600, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.509+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6504-7068-a4f8-adbbd09d8612', '__OWNER_ID__', 'Ureadin Ultra 30 Crème Émolliente', 'ISDIN', 'body-lotion', 'tube', 'Aqua, Urea, Paraffinum Liquidum, Isopropyl Palmitate, Glyceryl Stearate, PEG-100 Stearate, CETEARYL ETHYLHEXANOATE, Cetyl Alcohol, Dimethicone, ARGININE, Phenoxyethanol, Lactic Acid, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Allantoin, Palmitic Acid, Parfum, Stearic Acid, Disodium EDTA, Ethylhexylglycerin, Limonene, Hexyl Cinnamal, Alpha-Isomethyl Ionone, Linalool, Benzyl Salicylate, Eugenol, Citral, Hydroxycitronellal, Coumarin, Geraniol', 'Crème émolliente intensive pour zones épaissies et durillons. Exfolie et réduit les épaississements tout en hydratant profondément. Restaure la barrière cutanée grâce à l''Urée ISDIN 30%. Texture non grasse rapide.', 100, 'ml', 'isdin-ureadin-ultra-30-creme-emolliente', 'https://www.isdin.com/fr/ureadin-ultra-30', 'https://aurore-cdn.b-cdn.net/products/isdin-ureadin-ultra-30-creme-emolliente.webp', 'Urée ISDIN 30% - concentration élevée pour traitement localisé des hyperkératoses. Contient Arginine et Acide Lactique pour synergie kératolytique. Parfum présent (allergènes potentiels listés).', 1600, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.509+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6504-710e-a3fc-ef9f68d7bcdf', '__OWNER_ID__', 'Ureadin Ultra 10 Lotion Plus', 'ISDIN', 'body-lotion', 'bottle', 'Aqua, Urea, CETEARYL ETHYLHEXANOATE, Panthenol, Glyceryl Stearate, PEG-40 Stearate, Glycerin, Dimethicone, Persea Gratissima Oil, SHOREA STENOPTERA SEED BUTTER, Phenoxyethanol, Cetyl Alcohol, Octyldodecanol, Carbomer, Palmitic Acid, Stearic Acid, Disodium EDTA, Ethylhexylglycerin, Parfum, Sodium Hydroxide, BHT, Lactic Acid, Limonene, Hexyl Cinnamal, Alpha-Isomethyl Ionone, Linalool, Benzyl Salicylate, Eugenol, Citral, Hydroxycitronellal, Coumarin', 'Lotion corporelle hydratante intense pour soin quotidien des peaux très sèches qui desquament. Hydratation maximale soulageant les démangeaisons. Texture légère non grasse favorisant la restauration de la barrière cutanée.', 400, 'ml', 'isdin-ureadin-ultra-10-lotion-plus', 'https://www.isdin.com/fr/ureadin-ultra-10-lotion-plus', 'https://aurore-cdn.b-cdn.net/products/isdin-ureadin-ultra-10-lotion-plus.webp', 'Urée ISDIN 10% + Dexpanthénol (Provitamine B5). Concentration modérée adaptée pour usage quotidien corps entier. Adjuvant traitement xérose et peau sénile. Parfum présent avec allergènes.', 1600, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.51+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64fd-781b-a960-184f438e0b62', '__OWNER_ID__', 'UreaRepair 30 Crème Corps', 'Eucerin', 'body-lotion', 'tube', 'Aqua, Urea, Octyldodecanol, Caprylic/Capric Triglyceride, Sodium Lactate, DECYL OLEATE, Polyglyceryl-2 Dipolyhydroxystearate, ARGININE HCL, Chondrus Crispus Extract, Ceramide NP, Cholesterol, Helianthus Annuus Seed Oil, ALANINE, CARNITINE, GLYCINE, Lactic Acid, Sodium PCA, Sodium Chloride, DECYLENE GLYCOL, Pentylene Glycol', 'Crème intensive pour zones cutanées extrêmement sèches, rugueuses et squameuses (coudes, genoux, mains, pieds). Exfolie en douceur grâce à l''urée 30%, répare la barrière cutanée avec des céramides et hydrate avec les NMF.', 75, 'ml', 'eucerin-urearepair-30-creme-corps', 'https://www.eucerin.fr/produits/urearepair/urearepair-plus-creme-30-uree', 'https://aurore-cdn.b-cdn.net/products/eucerin-urearepair-30-creme-corps.webp', 'Formule Eucerin complète: 30% Urée + Céramide NP + NMF (PCA, Lactate, etc.). Sans parfum. Convient aux affections hyperkératosiques et plaques psoriasiques en complément de traitements desséchants. Résultats visibles dès 1 semaine.', 1010, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.51+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64e5-7fe3-a565-5c04009690da', '__OWNER_ID__', 'Aloe Fresh Type Soothing Gel', 'IsNtree', 'body-lotion', 'tube', '1,2-Hexanediol, Allantoin, Aloe Barbadensis Leaf Extract, ARGININE, Betaine, Carbomer, Dipotassium Glycyrrhizate, ETHYHEXYLGLYCERIN, Glycerin, Panthenol, Propanediol, Sodium Hyaluronate', 'Un gel apaisant ultra-frais conçu pour calmer instantanément les irritations et hydrater le corps sans fini collant.', 300, 'ml', 'isntree-aloe-fresh-type-soothing-gel', 'https://www.skinsafeproducts.com/isntree-aloe-fresh-type-soothing-gel-10-14-fl-oz-300-ml', 'https://aurore-cdn.b-cdn.net/products/isntree-aloe-fresh-type-soothing-gel.webp', 'Enrichi en extrait d''Aloe Vera et Panthénol, il convient parfaitement à toutes les peaux échauffées ou déshydratées.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.51+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64ea-7455-9481-dd6417e4e259', '__OWNER_ID__', 'Ducray Ictyane Lait Hydratant 400ml', 'Ducray', 'body-lotion', 'pump', 'Aqua, Glycerin, Carthamus Tinctorius Seed Oil, Cocos Nucifera Oil, Cocos Nucifera Oil, Paraffinum Liquidum, triethylhexanoin, sorbitan stearate, Cyclopentasiloxane, Hydrogenated Starch Hydrolysate, Cyclohexasiloxane, Trehalose, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Alpha-Isomethyl Ionone, Benzoic Acid, Benzyl Salicylate, Caprylyl Glycol, Cetearyl Alcohol, Citronellol, disodium phosphate, fragrance (parfum) geraniol, Hydroxycitronellal, hydroxyisohexyl 3-cyclohexene, carboxaldeyde, Limonene, Linalool, Potassium Phosphate, sodium cetearyl sulfate, Sodium Hydroxide, sucrose cocoate, xanthan gum', '', 400, 'ml', 'ducray-ictyane-lait-hydratant-400ml-232612', 'https://www.atida.fr/ducray-ictyane-lait-hydratant-400ml.html', 'https://aurore-cdn.b-cdn.net/products/ducray-ictyane-lait-hydratant-400ml-232612.webp', '', 1611, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.51+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6503-7a27-9e27-4cf836b37e3a', '__OWNER_ID__', 'Blemish Control Body Lotion', 'BYOMA', 'body-lotion', 'pump', 'Aqua, Cetearyl Alcohol, Caprylic/Capric Triglyceride, Glycerin, Hamamelis Virginiana Water, Glyceryl Stearate SE, Glycine Soja Oil, ETHYL LINOLEATE, Carthamus Tinctorius Seed Oil, Phenoxyethanol, Ammonium Polyacryloyldimethyl Taurate, Salicylic Acid, Sodium Hydroxide, Ethylhexylglycerin, Tocopherol, Phytosphingosine, Ceramide NP, Bakuchiol, Propanediol, RUTIN, HYDROXYCINNAMIC ACID', 'Lotion corporelle légère anti-imperfections avec acide salicylique pour désobstruer les pores, réduire les rougeurs et lisser la texture de la peau.', 300, 'ml', 'byoma-blemish-control-body-lotion', 'https://www.byoma.com', NULL, 'Contient BHA (salicylic acid), céramide NP et phytosphingosine pour soutenir la barrière cutanée, bakuchiol et antioxydants (vitamine E, rutin). Huiles nourrissantes de carthame et soja.', 2000, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.516+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64ef-7b76-8576-f74d3d63a6be', '__OWNER_ID__', 'AHA BHA PHA Miracle Calming Body Lotion', 'Some By Mi', 'body-lotion', 'bottle', '1,2-Hexanediol, Adenosine, Ammonium Acryloyldimethyltaurate/VP Copolymer, ARTEMISIA CAPILLARIS EXTRACT, ASIATIC ACID, ASIATICOSIDE, Betaine, Butylene Glycol, C13-15 ALKANE, Caprylic/Capric Triglyceride, Capryloyl Salicylic Acid, Carbomer, Centella Asiatica Extract, Chamaecyparis Obtusa Water, Citric Acid, Ethylhexylglycerin, EUCALYPTUS GLOBULUS LEAF EXTRACT, Gluconolactone, Glycerin, Hippophae Rhamnoides Fruit Extract, Houttuynia Cordata Extract, Limonene, MADECASSIC ACID, Madecassoside, Melaleuca Alternifolia Leaf Extract, Methylpropanediol, Niacinamide, POLYGLYCERYL-3 METHYLGLUCOSE DISTEARATE, Portulaca Oleracea Extract, ROSA CANINA FRUIT EXTRACT, Rosmarinus Officinalis Leaf Extract, Rosmarinus Officinalis Leaf Oil, Salicylic Acid, Tocopherol, Tromethamine, Aqua', 'Lotion corps exfoliante et apaisante à triple acide qui lisse, unifie et calme la peau du corps.', 200, 'ml', 'some-by-mi-aha-bha-pha-miracle-calming-body-lotion', 'https://www.skinsafeproducts.com/some-by-mi-aha-bha-pha-miracle-calming-body-lotion-6-76-fl-oz-200-ml', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-aha-bha-pha-miracle-calming-body-lotion.webp', 'Cocktail d''AHA (Acide Gluconique), BHA (Acide Salicylique) et PHA (Capryloyl Salicylique) renforcé par la Niacinamide — recommandé pour les peaux à kératose pilaire ou rugosités.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.511+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6503-789b-9315-f509deb9ebf8', '__OWNER_ID__', 'Daily Nourish Lotion 12% AHA', 'AmLactin', 'body-lotion', 'pump', 'Aqua, AMMONIUM LACTATE, Paraffinum Liquidum, Glycerin, Cetearyl Alcohol, Dimethicone, Glyceryl Stearate SE, STEARETH-2, Stearyl Alcohol, XANTHAN GUM, Phenoxyethanol, Ethylhexylglycerin', 'Lotion exfoliante hydratante au lactate d''ammonium (12% AHA) pour peaux sèches, rugueuses ou kératose pilaire. Exfolie en douceur et améliore la texture.', 225, 'ml', 'amlactin-dayli-nourish-12-aha', 'https://www.amlactin.com', NULL, '12% acide lactique sous forme ammonium lactate. Exfolie + hydrate (AHA humectant). Sans parfum, sans parabènes, sans phtalates. Texture légère non grasse.', 1600, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.511+00', 'bodycare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
