INSERT INTO public.products VALUES ('019de0ab-64d6-771b-b069-e37c6c496d96', '__OWNER_ID__', 'Niacin Essence Toner Peach 77', 'Anua', 'toner', 'pump', '1,2-Hexanediol, 2,3-BUTANEDIOL, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Adenosine, ALANINE, Allantoin, Alpha-Arbutin, ARGININE, Ascorbic Acid, Ascorbyl Glucoside, ASPARTIC ACID, Bacillus Ferment, BETAINE SALICYLATE, Bifida Ferment Lysate, Butylene Glycol, Caprylic/Capric Triglyceride, Ceramide NP, Cyanocobalamin, CYSTEINE, DIPHENYL DIMETHICONE, Dipotassium Glycyrrhizate, Dipropylene Glycol, Ethylhexylglycerin, Parfum, Galactomyces Ferment Filtrate, Glutamic Acid, Glycerin, GLYCINE, HISTIDINE, Hydrogenated Lecithin, HYDROLYZED VEGETABLE PROTEIN, ISOLEUCINE, Lactobacillus Ferment, LEUCINE, Lysine, Maltodextrin, METHIONINE, Methylpropanediol, Niacinamide, Panthenol, PHELLINUS LINTEUS EXTRACT, PHENYLALANINE, Polyglutamic Acid, POLYGLYCERYL-10 LAURATE, POLYGLYCERYL-10 STEARATE, PROLINE, Propanediol, PRUNUS PERSICA (PEACH) FLOWER EXTRACT, Prunus Persica Fruit Extract, PYRUS MALUS (APPLE) JUICE, SERINE, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, SODIUM POLYACRYLATE, SODIUM STEAROYL GLUTAMATE, Squalane, STREPTOCOCCUS THERMOPHILUS FERMENT, THREONINE, Tocopherol, TRIETHYLHEXANOIN, Tromethamine, TYROSINE, VALINE, Aqua, XANTHAN GUM, XYLOSE', 'Essence-tonique à la pêche 77% + niacinamide + 20 acides aminés. Illumine le teint et booste la régénération cellulaire.', 250, 'ml', 'anua-niacin-essence-toner-peach-77', 'https://www.skinsafeproducts.com/anua-niacin-essence-toner-peach-77-8-45-fl-oz-250-ml', 'https://aurore-cdn.b-cdn.net/products/anua-niacin-essence-toner-peach-77.webp', 'Galactomyces + bifida ferment + ascorbyl glucoside + céramide NP. Contient fragrance. Compatible peaux non réactives.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.566+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
