INSERT INTO public.products VALUES ('019de0ab-64ee-7733-8609-b23d0abcc118', '__OWNER_ID__', 'Bifida Toner Pad', 'Mixsoon', 'toner', 'bottle', '1,2-Hexanediol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Adenosine, Allantoin, Bifida Ferment Lysate, Butylene Glycol, Cellulose Gum, Ceramide NP, CETEARYL GLUCOSIDE, DIPHENYL DIMETHICONE, Dipropylene Glycol, Disodium EDTA, Ethylhexylglycerin, Glycerin, Hydrogenated Lecithin, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Lactobacillus Ferment Lysate, Limnanthes Alba Seed Oil, METHYL GLUCOSE SESQUISTEARATE, Microcrystalline Cellulose, Panthenol, Pentylene Glycol, POLYGLYCERYL-10 MYRISTATE, POLYGLYCERYL-3 METHYLGLUCOSE DISTEARATE, Potassium Hyaluronate, Saccharomyces Ferment Filtrate, Sodium Acetylated Hyaluronate, Sodium Ascorbyl Phosphate, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, STREPTOCOCCUS THERMOPHILUS FERMENT, Tocopherol, TRIETHYLHEXANOIN, Aqua', 'Pads toniques riches en Bifida Ferment Lysate et en formes multiples d''Acide Hyaluronique pour raffermir et régénérer la barrière cutanée.', 280, 'ml', 'mixsoon-bifida-toner-pad', 'https://www.skinsafeproducts.com/mixsoon-bifida-toner-pad-9-45-fl-oz-280-ml-120-count', 'https://aurore-cdn.b-cdn.net/products/mixsoon-bifida-toner-pad.webp', 'Actifs clés : Bifida Ferment Lysate, 5 formes d''Hyaluronate, Ceramide NP, Sodium Ascorbyl Phosphate. Idéal pour peaux matures et sensibles.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.566+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64ed-7799-ad30-40379628f774', '__OWNER_ID__', 'Soybean Nourishing Toner', 'Round Lab', 'toner', 'bottle', '1,2-Hexanediol, Adenosine, Butylene Glycol, Caprylic/Capric Triglyceride, Caprylyl Glycol, Carbomer, Ceramide NP, Chondrus Crispus Extract, Maltodextrin, DIPHENYL DIMETHICONE, Dipotassium Glycyrrhizate, Dipropylene Glycol, Disodium EDTA, Ethylhexylglycerin, Glycerin, GLYCINE MAX (SOYBEAN) SEED EXTRACT, Hydrogenated Lecithin, Panthenol, Pentylene Glycol, Propanediol, Saccharum Officinarum Extract, Sodium Hyaluronate, Theobroma Cacao Seed Extract, Tocopherol, TRIETHYLHEXANOIN, Tromethamine, Aqua', 'Un tonique lacté et riche qui nourrit intensément les peaux sèches en manque de vitalité.', 300, 'ml', 'round-lab-soybean-nourishing-toner', 'https://www.skinsafeproducts.com/round-lab-soybean-nourishing-toner-10-14-fl-oz-300-ml', 'https://aurore-cdn.b-cdn.net/products/round-lab-soybean-nourishing-toner.webp', 'Extrait de Soja noir et Céramides, idéal pour renforcer la barrière lipidique des peaux matures.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.567+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c5d-7211-8537-0fba067bcab3', '__OWNER_ID__', '5 PDRN B5 Vital Soothing Toner', 'COSRX', 'toner', 'pump', 'Aqua, Butylene Glycol, Glycerin, Niacinamide, Pentylene Glycol, 2,3-Butanediol, 1,2-Hexanediol, Betaine, Diethoxyethyl Succinate, Sodium DNA, Carbomer, Arginine, Panthenol, Ethylhexylglycerin, Adenosine, Hydrolyzed Corn Starch, Disodium EDTA, Allantoin, Sucrose, Lactobacillus Ferment, Pantothenic Acid, Alpha-Arbutin, Hydrolyzed Collagen, Centella Asiatica Extract, Propanediol, Tocopherol, Sodium Phytate, Sodium Hyaluronate, Hydrolyzed DNA, Caprylyl Glycol, Hydroxypropyltrimonium Hyaluronate, Acetyl Hexapeptide-8, Hydrolyzed Hyaluronic Acid, Sodium Acetylated Hyaluronate, Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Potassium Hyaluronate', 'Le 5 PDRN B5 Vital Soothing Toner COSRX est un tonique hydratant et réparateur conçu pour apaiser les irritations, renforcer la barrière cutanée et rétablir l’hydratation. Formulé avec cinq types de PDRN (polydeoxyribonucléotide) et de la provitamine B5 (panthénol), ce tonique aide à calmer les rougeurs, soutenir la régénération de la peau et améliorer sa résistance globale. Avec sa texture légère et à absorption rapide, il convient à tous les types de peaux, y compris les peaux sensibles ou fragilisées. Le 5 PDRN B5 Vital Soothing Toner COSRX est la première étape idéale après le nettoyage, apportant confort, hydratation et soin de la barrière cutanée en une seule couche rafraîchissante. Recommandé pour : Tous types de peaux.', 280, 'ml', 'cosrx-5-pdrn-b5-vital-soothing-toner', 'https://korean-skincare.fr/products/cosrx-5-pdrn-b5-vital-soothing-toner', 'https://aurore-cdn.b-cdn.net/products/cosrx-5-pdrn-b5-vital-soothing-toner.webp', 'Après le nettoyage, applique une quantité appropriée de produit sur un coton ou directement dans tes mains. Passe délicatement sur ta peau ou tapote jusqu’à absorption complète. Utilise matin et soir.', 2195, '2026-05-07 17:37:38.397031+00', '2026-06-14 15:14:07.567+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3dd1-7e39-bc90-2ca151d4b39c', '__OWNER_ID__', 'Damaged Hair Therapy Mist', 'MISSHA', 'mist', 'spray', 'Cyclopentasiloxane, Cyclotétrasiloxane, Dimethiconol, Cyclohexasiloxane, Tocopheryl Acetate, Huile de Noix de Coco (Cocos Nucifera), Moringa Oleifera Seed Oil, Simmondsia Chinensis Seed Oil, Ceramide NP, Phytosphingosine, Hydrogenated Lecithin, Protéine Hydrolysée de Miel, Argania Spinosa Kernel Oil, Biotin, Glycerin, Aqua, Phenoxyethanol, Parfum', 'La Damaged Hair Therapy Mist MISSHA est une brume capillaire enrichie en protéine H (protéine de miel) et en vitamine H (biotine) pour fournir un riche apport en nutriments et un soin éclatant aux cheveux abîmés, à tout moment et en tout lieu.', 200, 'ml', 'missha-damaged-hair-therapy-mist', 'https://korean-skincare.fr/products/missha-damaged-hair-therapy-mist', 'https://aurore-cdn.b-cdn.net/products/missha-damaged-hair-therapy-mist.webp', 'Agite bien le produit avant de l''utiliser. Vaporise sur tes cheveux à une distance de 5 à 10 cm et laisse absorber.', 1289, '2026-05-07 17:37:38.76976+00', '2026-06-14 15:14:07.567+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c33-7491-a922-ce8d670bcc65', '__OWNER_ID__', 'One Step Original Clear Pad', 'COSRX', 'toner', 'pack', 'Eau de Salix Alba (écorce de saule), Butylene Glycol, Glycerin, Betaine Salicylate, 1,2-Hexanediol, Arginine, Huile de Ricin Hydrogénée PEG-60, Panthenol, Allantoin, Éthyl Hexanediol, Huile de Zeste d''Orange Citrus Aurantium Dulcis, Melaleuca Alternifolia Leaf Oil, Sodium Hydroxide, Sodium Hyaluronate', 'Les One Step Original Clear Pads COSRX (anciennement connus sous le nom de One Step Pimple Clear Pads COSRX) sont des compresses très réputées imbibées de salicylate de bétaïne, un ingrédient BHA naturel, et d''eau d''écorce de saule qui exfolient la peau sans l''assécher ni la sensibiliser. Ces compresses éliminent complètement l''excès de sébum, éliminent les cellules mortes qui causent l''acné et démaquillent la peau. L''utilisation de ces compresses permet d''éclaircir le teint, de purifier sans irriter, de réduire les boutons et de contrôler les éruptions cutanées. Exfoliation, contrôle du sébum et hydratation - le nec plus ultra des compresses tout-en-un ! Elles peuvent également être utilisées pour traiter les imperfections sur la poitrine et le dos.', 70, 'pcs', 'cosrx-one-step-original-clear-pad', 'https://korean-skincare.fr/products/cosrx-one-step-original-clear-pad', 'https://aurore-cdn.b-cdn.net/products/cosrx-one-step-original-clear-pad.webp', 'Utilise une compresse lors de l''étape du tonique, après le nettoyage, une ou deux fois par jour. Passe délicatement la compresse sur ta peau. Tapote et fais pénétrer le reste de l''essence apaisante sur ta peau Procède à ta routine beauté habituelle sans rincer. Replace le couvercle hermétiquement pour t''assurer que les compresses restent humides et propres.', 2036, '2026-05-07 17:37:38.355178+00', '2026-06-14 15:14:07.567+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c8f-72a1-8e70-64d19f41bff5', '__OWNER_ID__', 'Water Bank Blue Hyaluronic Essence Toner', 'LANEIGE', 'toner', 'pump', 'Aqua, Glycerin, Dimethicone, Butylene Glycol, Tétraéthylhexanoate de Pentaérythrityl, Dipropylene Glycol, Méthyl Triméthicone, Polyméthacrylate de Glycéryle, Phényl Triméthicone, Pca Diméthicone, Méthicone Caprylique, Hydrogenated Polyisobutene, Niacinamide, Polysilicone-11, 1,2-Hexanediol, Polysorbate 20, Cetyl Alcohol, Propanediol, Caffeine, Stéarate de Glycéryle Citrate, Polyacrylate-13, Glyceryl Stearate, Alcools C14-22, Dimethiconol, Copolymère Ammonium Acryloyldiméthyltaurate/VP, Stearic Acid, Extrait de Fruit de Malpighia Emarginata, Copolymère Ammonium Acryloyldiméthyltaurate/Beheneth-25 Méthacrylate, Polyisobutene, Palmitic Acid, Euterpe Oleracea Fruit Extract, Hydrogenated Lecithin, Cocos Nucifera Oil, Glyceryl Caprylate, Alcool Arachidylique, Glucoside Alkylique C12-20, Distéarate de Polyglycéryl-3 Méthylglucose, Ethylhexylglycerin, Parfum, Sodium Hyaluronate, Behenyl Alcohol, Glucoside Arachidylique, Sorbitan Isostearate, Disodium EDTA, Hydrolyzed Hyaluronic Acid, Beta-Glucan, Silicate de Sodium et de Magnésium, Glucose, Myristic Acid, Lauric Acid, Glutathione, Tocopherol, Undaria Pinnatifida Extract', 'Le Water Bank Blue Hyaluronic Essence Toner Laneige est un produit luxueux, doté d''une texture satinéeet d''une formule innovante à base d''acide hyaluronique de faible poids moléculaire pour une meilleure pénétration dans la peau et une restauration rapide de l''hydratation. Enrichi de 81,1 % de complexe Beta Pro-Nol, comprenant des probiotiques et du panthénol, ce tonique permet non seulement de rétablir l''hydratation, mais aussi de renforcer la capacité de la peau à absorber les produits de soins suivants, optimisant ainsi les résultats obtenus. Le tonique essence, mélangeant les avantages de l''essence et du tonique, se targue d''une texture légèrement visqueuse et hydratante, rafraîchissante et souple sur la peau, contribuant à la reconstruction de la barrière cutanée. Grâce à l''acide hyaluronique bleu de taille microscopique, 1/2000 de la taille originale, il améliore de 300 % les barrières cutanées endommagées. Ce tonique hydratant est une solution puissante pour favoriser une peau douce et souple, réduire la desquamation et soulager la sécheresse et l''irritation, laissant ta peau revitalisée et apaisée. Recommandé pour : Tous types de peaux.', 160, 'ml', 'laneige-water-bank-blue-hyaluronic-essence-toner', 'https://korean-skincare.fr/products/laneige-water-bank-blue-hyaluronic-essence-toner', 'https://aurore-cdn.b-cdn.net/products/laneige-water-bank-blue-hyaluronic-essence-toner.webp', 'Applique une quantité modérée de produit sur ta peau, en évitant le contour des yeux et de la bouche. Tapote légèrement pour une meilleure absorption.', 2695, '2026-05-07 17:37:38.447087+00', '2026-06-14 15:14:07.567+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3d3b-7126-ba93-abbc6286cfdb', '__OWNER_ID__', 'Moistfull Collagen Toner', 'ETUDE', 'toner', 'pump', 'Aqua, Collagène Hydrolysé, Glycerin, Propanediol, Alcohol Denat, Betaine, 1,2-Hexanediol, Butylene Glycol, Polyméthacrylate de Glyceryle, PPG-13-Décyltétradéceth-24, Gomme Xanthane, Gomme Cellulosique, Ethylhexylglycerin, Disodium EDTA, Parfum, Beta-Glucan, Protéine de Lupin Hydrolysée, Tocopherol', 'Le Moistfull Collagen Facial Toner ETUDE HOUSE est un tonique hydratant doux qui maintient la peau hydratée et équilibrée. Ses fines particules d''eau riche en super collagène aident à rééquilibrer le pH de la peau tout en favorisant son élasticité et sa fermeté pour la garder rebondie et éclatante.', 200, 'ml', 'etude-house-moistfull-collagen-toner', 'https://korean-skincare.fr/products/etude-house-moistfull-collagen-toner', 'https://aurore-cdn.b-cdn.net/products/etude-house-moistfull-collagen-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 2195, '2026-05-07 17:37:38.618951+00', '2026-06-14 15:14:07.568+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3dab-728f-b549-5818b19723c3', '__OWNER_ID__', 'Vita C Plus Brightening Toner', 'MISSHA', 'toner', 'pump', 'Aqua, Glycerin, Butylene Glycol, Niacinamide, Pentylene Glycol, Betaine, Trehalose, 1,2-Hexanediol, Glycyrrhiza Uralensis Root Extract, Lysat de Fermentation de Bifida, Panthenol, Eau de Hippophae Rhamnoides, C12-14 Pareth-12, Tranexamic Acid, 3-O-Ethyl Ascorbic Acid, Extrait de Chlorella Vulgaris, Glucose, Curcuma Longa Root Extract, Fermentation de Lactobacillus, Fructooligosaccharides, Fructose, Ethylhexylglycerin, Adenosine, Extrait de Fleur de Melia Azadirachta, Carbomer, Tromethamine, Allantoin, Melia Azadirachta Leaf Extract, Disodium EDTA, Sodium Hyaluronate, Extrait de Graine de Glycine Soja (Soja), Huile de Zeste d''Orange Citrus Aurantium Dulcis, Ocimum Sanctum Leaf Extract, Ascorbic Acid, Huile de Zeste de Pamplemousse Citrus Grandis, Extrait de Corallina Officinalis, Eucalyptus Globulus Leaf Oil, Lavandula Angustifolia Oil, Octanediol, Collagène Hydrolysé, Lactobionic Acid, Glucoside de Glycéryle, Caprylic/Capric Triglyceride, Cyanocobalamin, PVP, Hydrogenated Lecithin, Tocopherol, Ceramide NP, Palmitoyl Tripeptide-5, Caprylyl Glycol, Hyaluronic Acid, Acide Hexapeptide-8, Fullerenes, Arbutine, Dipropylene Glycol, Hydrolyzed Hyaluronic Acid, Laurdimonium Hydroxypropyl Hydrolysé de Protéine de Blé, Phytostérols, Ascorbyl Glucoside', 'Le Vita C Plus Brightening Toner Missha est un tonique formulé avec de la vitamine C (pureté 99%) et du PHA (acide polyhydroxylé) qui aide à éliminer les cellules mortes de la peau pour un teint plus lisse et translucide. Avec un effet anti-rides et une action éclaircissante, il permet d''améliorer le teint.', 200, 'ml', 'missha-vita-c-plus-brightening-toner', 'https://korean-skincare.fr/products/missha-vita-c-plus-brightening-toner', 'https://aurore-cdn.b-cdn.net/products/missha-vita-c-plus-brightening-toner.webp', 'Après le nettoyage, verse le tonique dans tes mains et tapote sur ton visage et ton cou jusqu''à ce qu''il soit complètement absorbé. Fais suivre d''un sérum et d''une crème hydratante.', 2795, '2026-05-07 17:37:38.730943+00', '2026-06-14 15:14:07.568+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3d0a-7a16-b30b-1b200da9eab4', '__OWNER_ID__', 'SoonJung pH 5.5 Relief Toner', 'ETUDE', 'toner', 'pump', 'Aqua, Propanediol, Glycerin, Betaine, Panthenol, 1,2-Hexanediol, Polyglycérine-3, Ethylhexylglycerin, Disodium EDTA, Carbomer, Madecassoside, Butylene Glycol, Extrait de Racine de Scutellaria Baicalensis, Tocopherol, Camellia Sinensis Leaf Extract', 'Le SoonJung pH 5.5 Relief Toner Etude House est un tonique apaisant et hydratant qui maintient la peau calme et fraîche tout au long de la journée. Formulé avec 97 % d''ingrédients d''origine naturelle, ce tonique limpide et semblable à de l''eau utilise le madécassoside et le panthénol pour hydrater en profondeur et guérir la peau endommagée ou inflammée. Avec sa formule hypoallergénique simple et exempte d''irritants potentiels comme des parfums synthétiques, des huiles minérales ou des parabènes, ce tonique est parfait pour tous les types de peau, en particulier les peaux sensibles. Recommandé pour : Peaux sensibles. Peut être utilisé pour : Tous types de peaux.', 350, 'ml', 'etude-house-soon-jung-ph-5-5-relief-toner', 'https://korean-skincare.fr/products/etude-house-soon-jung-ph-5-5-relief-toner', 'https://aurore-cdn.b-cdn.net/products/etude-house-soon-jung-ph-5-5-relief-toner.webp', 'Après avoir nettoyé ton visage, applique une quantité appropriée de produit sur une compresse en coton ou dans tes mains. Tapote délicatement le tonique sur ton visage, en insistant sur les zones qui ont besoin d''être apaisées et hydratées. Laisse le tonique pénétrer complètement dans ta peau et poursuis avec ta routine beauté habituelle. Utilise-le quotidiennement pour un teint équilibré et hydraté.', 2595, '2026-05-07 17:37:38.570447+00', '2026-06-14 15:14:07.568+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3e9d-71a8-a1dd-51f7a539e38b', '__OWNER_ID__', 'Ceramidin Skin Barrier Serum Toner', 'Dr.Jart+', 'toner', 'bar', 'Aqua, Dipropylene Glycol, Betaine, Propanediol, Alcohol Denat, Tréhalose Glycosylé, Glycerin, 1,2-Hexanediol, Panthenol, Pentylene Glycol, Érythritol, Hydrolysat De Fécule Hydrogéné, Triéthylhexanoïne, Diphényl Diméthicone, Myristate De Polyglycéryle-10, Ceramide NP, Distearate De Saccharose, Ethylhexylglycerin, Sodium Hyaluronate, Theobroma Cacao Seed Extract, Pelargonium Graveolens Oil, Olea Europaea Fruit Oil, Huile De Fruit De Citrus Aurantium Bergamia, Pareth-12 C12-14, Hydrogenated Lecithin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Tromethamine, Carbomer, Polyméthacrylate De Glycéryle, Glyceryl Stearate, Dextrin, Salvia Officinalis Oil, Citronellol, Disodium EDTA, Jaune 5 CI 19140', 'Le Ceramidin Skin Barrier Serum Toner DR. JART+ est un puissant tonique infusé de céramides pour renforcer et protéger la barrière cutanée contre la perte chronique d''eau. Ce produit est une véritable bouée de sauvetage pour ta peau et lui fournit un boost d''hydratation pour passer d''une peau rêche et déshydratée à une peau hydratée et éclatante de santé. Recommandé pour : Peaux sèches, tous types de peaux.', 150, 'ml', 'dr-jart-ceramidin-skin-barried-serum-toner', 'https://korean-skincare.fr/products/dr-jart-ceramidin-skin-barried-serum-toner', 'https://aurore-cdn.b-cdn.net/products/dr-jart-ceramidin-skin-barried-serum-toner.webp', 'Applique le produit après avoir nettoyé ton visage et appliqué un tonique, et fais suivre d''une crème hydratante. Masse délicatement l''ensemble de ton visage et tapote pour une meilleure absorption.', 3495, '2026-05-07 17:37:38.972967+00', '2026-06-14 15:14:07.569+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3f6c-7261-ac50-c735fbf1f484', '__OWNER_ID__', 'Pantothenic Water Parsley Clear Pad', 'SKINFOOD', 'toner', 'pack', 'Aqua, Butylene Glycol, Glycerin, 1,2-Hexanediol, Dipropylene Glycol, Panthenol, PPG-13-Decyltetradeceth-24, Betaine, Ethylhexylglycerin, Allantoin, Propanediol, Diphenyldiméthicone, Triéthylhexanoïne, Capryloyl Salicylic Acid, Sodium Citrate, Citrus Junos Fruit Extract, Dipotassium Glycyrrhizate, Sodium Phytate, Centella Asiatica Extract, Polyglyceryl-10 Oléate, Hydrogenated Lecithin, Ficus Carica Fruit Extract, Sodium Hyaluronate, Phospholipides, Salvia Officinalis Leaf Extract, Extrait de Chamomilla Recutita, Eucalyptus Globulus Leaf Oil, Ferment de Racine de Radis/Leuconostoc, Huile de Fruit de Citrus Aurantium Bergamia, Helianthus Annuus Seed Oil, Acide Pantothénique, Salvia Sclarea Oil, Sucrose, Caprylyl Glycol', 'Les Pantothenic Water Parsley Clear Pads SKINFOOD sont des compresses toniques exfoliantes douces infusées à l’extrait de persil aquatique (tige et feuille) et à l’acide pantothénique (vitamine B5) pour apaiser les peaux sensibles et aider à réguler l’équilibre huile-eau. Les compresses sont imbibées d’une solution contenant du LHA (acide capryloyl salicylique) pour une exfoliation légère, ainsi que des extraits botaniques comme la centella, la sauge, la camomille, la figue et autres pour calmer les irritations. La texture est légère, rafraîchissante, et laisse la peau propre, équilibrée et hydratée sans sensation de tiraillement. Recommandé pour : Tous types de peaux.', 60, 'pcs', 'skinfood-pantothenic-water-parsley-clear-pad', 'https://korean-skincare.fr/products/skinfood-pantothenic-water-parsley-clear-pad', 'https://aurore-cdn.b-cdn.net/products/skinfood-pantothenic-water-parsley-clear-pad.webp', 'Après le nettoyage, prends une compresse et fais-la glisser délicatement sur l’ensemble de ton visage, en évitant le contour des yeux. Utilise le côté en relief de la compresse sur les zones nécessitant une exfoliation (comme la zone T), et le côté plus lisse pour calmer et tonifier. Tapote l’essence restante sur ta peau. Utilise 2 à 3 fois par semaine ou plus si ta peau le tolère bien.', 2495, '2026-05-07 17:37:39.180052+00', '2026-06-14 15:14:07.569+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3eb5-732d-94ab-d16c07321c0e', '__OWNER_ID__', 'Ctrl-A Teatreement Toner', 'Dr.Jart+', 'toner', 'pump', 'Extrait de Fleur d''Anthemis Nobilis, Camellia Sinensis Leaf Extract, Rhizome/Racine de Glycyrrhiza Glabra (Réglisse), Extrait d''Hamamélis de Virginie (Hamamelis Virginiana), Sodium Citrate, Extrait d''Écorce de Cinnamomum Zeylanicum, Extrait d''Écorce de Pinus Pinaster, Melaleuca Alternifolia Leaf Oil, Ethylhexylglycerin, Citric Acid, Disodium EDTA, Hydrogenated Lecithin, Glycine Capryloyle, Hexylene Glycol, Octylododéceth-16, Allantoin, Sarcosine, Ceramide NP, Camphre, Carthamus Tinctorius Seed Oil, 1,2-Hexanediol, Silica, Stérols de Glycine Soja (Soja), Acide Linoléique, Phospholipides, 4-Terpineol, Polymère Croisé de Méthacrylate de Méthyle, Salicylic Acid', 'Le Ctrl-A Teatreement Toner Dr.Jart+ est un tonique purifiant qui élimine l''excès de sébum et rééquilibre les peaux grasses et mixtes tout en apportant une hydratation rapide après le nettoyage. Ce tonique purifiant t''aide à obtenir la peau de tes rêves en éliminant l''excès de sébum et en ciblant les zones à problèmes sans perturber la barrière cutanée, ce qui te laisse avec un teint frais et mat. Ce produit apaise la peau, réduit les rougeurs et hydrate instantanément.', 120, 'ml', 'dr-jart-ctrl-a-teatreement-toner', 'https://korean-skincare.fr/products/dr-jart-ctrl-a-teatreement-toner', 'https://aurore-cdn.b-cdn.net/products/dr-jart-ctrl-a-teatreement-toner.webp', 'Applique le produit après avoir nettoyé ton visage et utilisé un tonique, et fais suivre d''une crème hydratante. Masse délicatement l''ensemble de ton visage et tamponne pour une meilleure absorption.', 2050, '2026-05-07 17:37:38.997067+00', '2026-06-14 15:14:07.569+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3ecf-7ba0-afb0-823ebba9b3a3', '__OWNER_ID__', 'Dear Hydration Facial Mist', 'BANILA CO', 'mist', 'spray', 'Aqua, Glycerin, Butylene Glycol, Alcohol Denat, Dimethicone, Phenoxyethanol, Oléate de Polyglycéryle-2, Huile de Ricin Hydrogénée PEG-60, Cyclopentasiloxane, Octyldodéceth-16, Eau de Fleur de Nelumbo Nucifera, Hydrogenated Lecithin, Parfum, Crosspolymère de Diméthicone/Vinyl Diméthicone, Stéarate de Polyglycéryle-10, Distéarate de Saccharose, Propylene Glycol, Ethylhexylglycerin, Sodium Citrate, Disodium EDTA, 1,2-Hexanediol, Allantoin, Citric Acid, Dipotassium Glycyrrhizate, Ocimum Sanctum Leaf Extract, Melia Azadirachta Leaf Extract, Extrait de Mentha Arvensis, Jus de Bambusa Arundinacea, Extrait de Bourgeon de Pin Sylvestre, Extrait de Levure', 'La Co Dear Hydration Facial Mist Banila est une brume rafraîchissante pour le visage qui la recharge en hydratation et contient des particules d''hydratation superfines bourrées de minéraux pour calmer et désaltérer la peau. Cette brume pour le visage rafraîchit les peaux échauffées et hydrate instantanément les peaux sèches. Parfaite pour préparer la peau au maquillage ou pour donner un coup de pouce à la peau déshydratée tout au long de la journée.', 120, 'ml', 'dear-hydration-facial-mist', 'https://korean-skincare.fr/products/dear-hydration-facial-mist', 'https://aurore-cdn.b-cdn.net/products/dear-hydration-facial-mist.webp', 'Vaporise sur le visage à une distance de 20 à 30 cm n''importe où et n''importe quand tu ressens un besoin d''hydratation. Peut être utilisé par-dessus du maquillage, sur tes cheveux ou même sur ton corps.', 1095, '2026-05-07 17:37:39.023501+00', '2026-06-14 15:14:07.569+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4047-7d15-8425-44b70c62aec9', '__OWNER_ID__', 'Balanceful Cica Toner Pad', 'Torriden', 'toner', 'pack', 'Aqua, Téréphtalate de Polybutylène, Téréphtalate de Polyéthylène, Diglycérine, Copolymère d''Acrylates, Copolymère Éthylène/VA, Glycerin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, 1,2-Hexanediol, Tromethamine, Ethylhexylglycerin, Fluorphlogopite Synthétique, Polyuréthane-11, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Disodium EDTA, Silica, Sulfate de Baryum, Sorbitan Isostearate, Polysorbate 60, Oxyde d''Étain, Titanium Dioxide, Lac Rouge 30, CI 77000, Parfum, Limonene, Citral, Geraniol, Linalool', 'Les Balanceful Cica Toner Pad Torriden sont conçues avec expertise pour exfolier les cellules mortes de la peau et débarrasser les pores de l''accumulation de sébum, favorisant ainsi un teint clair et sain. Infusés de LHA et de PHA, ces compresses de coton certifiées vegan offrent une expérience de nettoyage à la fois douce et efficace, particulièrement adaptée aux peaux sensibles. La formule comprend un complexe 5D Cica unique contenant cinq variétés d''extrait de Centella Asiatica, pour apaiser les irritations et hydrater la peau en profondeur. Grâce à leur texture en relief, ces compresses assurent une application minutieuse de la formule subacide du produit, ce qui permet de maintenir l''équilibre optimal du pH de ta peau tout en offrant un fini lisse et rafraîchi. Recommandé pour : Peaux sensibles, soin des pores, tous types de peaux.', 60, 'pcs', 'torriden-balanceful-cica-toner-pad', 'https://korean-skincare.fr/products/torriden-balanceful-cica-toner-pad', 'https://aurore-cdn.b-cdn.net/products/torriden-balanceful-cica-toner-pad.webp', 'Après avoir nettoyé ton visage, passe délicatement la compresse sur tout le visage avec son côté en relief, en évitant le contour de la bouche et des yeux. Passe à nouveau la compresse sur ta la peau avec le côté doux pour finir l''application. Il est également possible d''utiliser les compresses comme un masque tissu apaisant en les plaçant sur les zones irritées.', 2395, '2026-05-07 17:37:39.399665+00', '2026-06-14 15:14:07.569+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3f34-76bd-bcc6-4c7bdbf4b20f', '__OWNER_ID__', 'Royal Honey Propolis Enrich Toner', 'SKINFOOD', 'toner', 'pump', 'Aqua, Extrait de Propolis, Extrait de Gelée Royale, Extrait de Miel, Propanediol, Triéthylhexanoïne, Dipropylene Glycol, Caprylic/Capric Triglyceride, Hydrogenated Poly(C6-14 Olefin), Glyceryl Stearate, Triméthicone de Phényl Diphénylsiloxy, Stéarate de Polyglycéryl-6, Carbomer, Butylene Glycol, Triméthicone de Phényl, Cetyl Alcohol, Glycerin, Béhenate de Polyglycéryl-6, Huile de Zeste de Mandarine (Citrus Tangerina), Lactobacillus Ferment, Saccharomyces Ferment Filtrate, Huile de Fruit de Bergamote (Citrus Aurantium Bergamia), Cellulose Gum, Huile de Fleur de Géranium (Pelargonium Graveolens), Boswellia Carterii Oil, Alcohol Denat, Lavandula Angustifolia Oil, Hydrogenated Lecithin, Ceramide NP, Arginine, Citrus Limon Peel Oil, Rosmarinus Officinalis Leaf Oil, Huile de Feuille d''Eucalyptus (Eucalyptus Globulus), Cananga Odorata Flower Oil, Cinnamomum Zeylanicum Bark Oil, Disodium EDTA, Cholesterol, Oleic Acid, 1,2-Hexanediol, Ethylhexylglycerin', 'Le Royal Honey Propolis Enrich Toner SKINFOOD est un tonique hydratant enrichi qui pénètre en douceur pour désaltérer la peau profondément et en toute transparence grâce à l''hydratation adhésive de la propolis pure.', 160, 'ml', 'skinfood-royal-honey-propolis-enrich-toner', 'https://korean-skincare.fr/products/skinfood-royal-honey-propolis-enrich-toner', 'https://aurore-cdn.b-cdn.net/products/skinfood-royal-honey-propolis-enrich-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 2395, '2026-05-07 17:37:39.124277+00', '2026-06-14 15:14:07.57+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3f7d-781b-b444-24d69e0a8493', '__OWNER_ID__', 'Potato Madecassoside Soothing Pad', 'SKINFOOD', 'toner', 'pack', 'Aqua, Butylene Glycol, Glycerin, Niacinamide, 1,2-Hexanediol, Hydroxyacetophenone, PPG-13-Decyltetradécéth-24, Betaine, Allantoin, Sodium Citrate, Dipotassium Glycyrrhizate, Extrait De Pulpe De Pomme De Terre (Solanum Tuberosum), Beta-Glucan, Citric Acid, Sodium Phytate, Sodium Hyaluronate, Copolymère D’acryloyldiméthyltaurate/VP, Helianthus Annuus Seed Oil, Madecassoside, Phosphate De Sodium Ascorbyl, Copolymère D’acrylate/Glycéryl, Pogostemon Cablin Oil, Dipropylene Glycol, Gomme De Sclérotium, Copolymère PVM/MA, Huile De Sauge Officinale, Hydrogenated Lecithin, Polyglyceryl-10 Laurate, Centella Asiatica Extract, Asiaticoside, Acide Madecassique, Acide Asiatique, Lavandula Angustifolia Oil, Caffeine, Huile De Sauge Sclarée, Rosmarinus Officinalis Leaf Oil, Caprylyl Glycol', 'Les Potato Madecassoside Soothing Pads SKINFOOD sont un tonique sous forme de compresses vegan conçu pour apaiser et prendre soin des peaux irritées ou sensibles. Infusé avec du madecassoside, un composé dérivé de la Centella Asiatica, et de l’extrait de pulpe de pomme de terre, ce produit aide à améliorer la pigmentation de la peau et soutient la barrière cutanée endommagée. Idéal pour ceux qui souhaitent renforcer l’éclat de la peau et traiter les problèmes d’hyperpigmentation. Recommandé pour : Tous types de peaux, y compris les peaux sensibles et sèches.', 60, 'pcs', 'skinfood-potato-madecassoside-soothing-pad', 'https://korean-skincare.fr/products/skinfood-potato-madecassoside-soothing-pad', 'https://aurore-cdn.b-cdn.net/products/skinfood-potato-madecassoside-soothing-pad.webp', 'Après le nettoyage : Commence avec un visage propre et sec. Application : Passe doucement la compresse sur ton visage, en insistant sur les zones nécessitant un effet apaisant. Tu peux également placer la compresse sur des zones spécifiques pour un soin ciblé. Astuce : Option masque : Pour des bienfaits accrus, laisse la compresse sur ta peau pendant 5 à 10 minutes comme un masque, puis retire-la et tapote légèrement l’essence restante sur ta peau.', 2495, '2026-05-07 17:37:39.19732+00', '2026-06-14 15:14:07.57+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-45e0-7653-bcb2-3e27b50c1d04', '__OWNER_ID__', 'No.4 Pore Zero Peeled Egg Toner Pad', 'Numbuzin', 'toner', 'pack', 'Aqua, Methylpropanediol, Éthanolamine, Butylene Glycol, 1,2-Hexanediol, Glycerin, Panthenol, Betaine, Trehalose, Glycereth-26, Laurate de Polyglyceryl-10, Copolymère d''Acryloyldiméthyltaurate/VP d''Ammonium, Gluconolactone, Sodium Citrate, Sodium Hyaluronate, Allantoin, Disodium EDTA, Capryloyl Salicylic Acid, Pinus Palustris Leaf Extract, Ulmus Davidiana Root Extract, Oenothera Biennis Flower Extract, Pueraria Lobata Root Extract, Parfum', 'Découvre le pouvoir de transformation des No. 4 Pore Zero Peeled Egg Toner Pads Numbuzin, ta solution ultime pour obtenir un effet glass skin sans effort. Ces compresses toniques pratiques en une seule étape sont infusées d''une formule puissante conçue pour purifier les pores et éliminer l''excès de sébum, dévoilant ainsi une peau claire et radieuse. Enrichies d''extrait d''onagre, d''extrait d''arrowroot, d''extrait de pin des marais et d''extrait de racine d''Ulmus Davidiana, ces compresses contrôlent efficacement la production de sébum et resserrent les pores, laissant ton teint raffiné et lisse. Les compresses comportent une face en relief qui exfolie en douceur les cellules mortes de la peau et l''excès de sébum, tandis que la face opposée reconstitue l''hydratation pour un fini équilibré. Avec un apport supplémentaire de 2 % de niacinamide, ces compresses aident à diminuer l''apparence de la pigmentation de la peau, garantissant un teint rajeuni, apaisé et hydraté qui dure. Recommandé pour : Soin des pores, peaux sensibles, tous types de peaux.', 190, 'ml', 'numbuzin-no-4-pore-zero-peeled-egg-toner-pad1-1', 'https://korean-skincare.fr/products/numbuzin-no-4-pore-zero-peeled-egg-toner-pad1-1', 'https://aurore-cdn.b-cdn.net/products/numbuzin-no-4-pore-zero-peeled-egg-toner-pad1-1.webp', 'Après t''être lavé le visage, passe une compresse tonique de l''intérieur vers l''extérieur le long de ton grain de peau, en évitant le contour des yeux et de la bouche. Tu peux aussi poser la compresse sur ton visage pendant 10 minutes maximum.', 2052, '2026-05-07 17:37:40.832312+00', '2026-06-14 15:14:07.57+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3f94-7662-a7b3-842fc6043a59', '__OWNER_ID__', 'Carrot Carotene Soothing Toner', 'SKINFOOD', 'toner', 'pump', 'Aqua, Glycerin, Butylene Glycol, 1,2-Hexanediol, PPG-13-Decyltetradécéth-24, Ethylhexylglycerin, Sodium Citrate, Daucus Carota Sativa Root Extract, Sodium Hyaluronate, Citric Acid, Sodium Phytate, Beta-Glucan, Allantoin, Hydroxyéthylcellulose, Maltodextrin, Hydrolysat de Saccharides, Huile de Graine de Carotte (Daucus Carota Sativa), Camellia Sinensis Leaf Extract, Centella Asiatica Extract, Huile de Fruit d’Olive (Olea Europaea), Pogostemon Cablin Oil, Extrait de Fruit de Momordica Charantia, Lavandula Hybrida Oil, Extrait de Brocoli (Brassica Oleracea Italica), Huile de Sauge Officinale, Extrait de Chou (Brassica Oleracea Capitata), Huile d’Artemisia Vulgaris, Huile de Zeste d’Orange Douce (Citrus Aurantium Dulcis), Undaria Pinnatifida Extract, Caprylyl Glycol', 'Le Carrot Carotene Soothing Toner SKINFOOD est un tonique léger et apaisant formulé avec 18 % d’extrait de carotte et de l’huile de graine de carotte riche en bêta-carotène. Il offre une protection antioxydante et une hydratation grâce à des humectants comme la glycérine et l’hyaluronate de sodium, et utilise plusieurs extraits botaniques tels que thé vert, la Centella Asiatica, le brocoli, le rosier muscat, la sauge et l''olive pour apaiser et revitaliser la peau irritée ou terne. Sa texture aqueuse pénètre rapidement et prépare la peau à recevoir des sérums ou des crèmes hydratantes. Recommandé pour : Peaux sèches et sensibles.', 300, 'ml', 'skinfood-carrot-carotene-soothing-toner', 'https://korean-skincare.fr/products/skinfood-carrot-carotene-soothing-toner', 'https://aurore-cdn.b-cdn.net/products/skinfood-carrot-carotene-soothing-toner.webp', 'Après le nettoyage, verse une quantité modérée de produit dans tes paumes ou sur un coton. Tapote ou presse sur ta peau jusqu’à absorption complète. À utiliser le matin et/ou le soir dans le cadre de ta routine de soins.', 2095, '2026-05-07 17:37:39.220216+00', '2026-06-14 15:14:07.57+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-40a2-78df-9a8b-edac0612fec9', '__OWNER_ID__', 'Madagascar Centella Hyalu-Cica Cloudy Mist', 'SKIN1004', 'mist', 'spray', 'Camellia Sinensis Leaf Water, Aqua, 1,2-Hexanediol, Isopentydioldiol, Extrait de Cordyceps Militaris, Centella Asiatica Leaf Water, Butylene Glycol, Methylpropanediol, Glycerin, Betaine, Xylitol, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Oléate de Polyglycéryl-10, Myristate de Polyglycéryl-10, Pentylene Glycol, Hibiscus Esculentus Fruit Extract, Dioleate de Polyglycéryl-6, Extrait de Fruit de Pyrus Communis Poire, Adenosine, Rosa Damascena Flower Water, Laurate de Polyglycéryl-4, Ethylhexylglycerin, Extrait de Fruit de Cucumis Melo Melon, Citric Acid, Extrait de Racine d’Iris Florentina, Sodium Phytate, Extrait de Feuille/Tige de Hedera Helix Lierre, Polyglutamic Acid, Galactomyces Ferment Filtrate, Artemisia Princeps Leaf Extract, Caprylic/Capric Triglyceride, Hydrogenated Lecithin, Ceramide NP', 'La Madagascar Centella Hyalu-Cica Cloudy Mist est une brume visage rafraîchissante conçue pour hydrater et apaiser la peau. Enrichie en Centella Asiatica et en acide hyaluronique, cette fine brume diffuse une hydratation légère qui laisse le teint frais, lumineux et revitalisé. Formulée avec 40 % d’extrait de thé vert, naturellement riche en vitamines, acides aminés et polyphénols, elle aide à améliorer l’élasticité de la peau et favorise un aspect lisse et sain. L’ajout d’adénosine et de Ceramide Biome contribue à maintenir une hydratation équilibrée et soutient la fonction naturelle de la peau. À utiliser après le nettoyage ou tout au long de la journée pour un coup de fraîcheur et d’hydratation instantané. Recommandé pour : Tous types de peaux.', 120, 'ml', 'skin1004-madagascar-centella-hyalu-cica-cloudy-mist', 'https://korean-skincare.fr/products/skin1004-madagascar-centella-hyalu-cica-cloudy-mist', 'https://aurore-cdn.b-cdn.net/products/skin1004-madagascar-centella-hyalu-cica-cloudy-mist.webp', 'Tenir le produit à la verticale et ne pas agiter. Fermer les yeux et vaporiser la quantité souhaitée à une distance de 20 à 30 cm du visage. Tapoter délicatement pour faciliter l''absorption.', 1610, '2026-05-07 17:37:39.490399+00', '2026-06-14 15:14:07.571+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64ff-7ed2-8f0d-40713718d19c', '__OWNER_ID__', 'Niacinamide 5% Face & Body Emulsion', 'The Ordinary', 'body-lotion', 'pump', 'Aqua, ETHYL MACADAMIATE, Niacinamide, Propanediol, Glycerin, SPHINGOMONAS FERMENT EXTRACT, Pentylene Glycol, ETHYLHEXYL OLIVATE, POLYGLYCERYL-4 OLEATE, SODIUM ACRYLATES COPOLYMER, ISOCETETH-20, Sodium Citrate, Citric Acid, MALIC ACID, Trisodium Ethylenediamine Disuccinate, Tocopherol, Ethylhexylglycerin, Phenoxyethanol, Chlorphenesin', 'Émulsion légère visage et corps à 5% niacinamide pour unifier le teint, atténuer les taches brunes et hydrater toute la surface cutanée.', 100, 'ml', 'the-ordinary-niacinamide-5-face-body-emulsion', 'https://theordinary.com', 'https://aurore-cdn.b-cdn.net/products/the-ordinary-niacinamide-5-face-body-emulsion.webp', 'Usage visage ET corps. Texture émulsion légère non grasse, bonne tolérance. Adapté teint inégal corps et hyperpigmentation.', 1400, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.571+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-401b-7bc4-955d-2148e2779d24', '__OWNER_ID__', 'DIVE-IN Low Molecular Hyaluronic Acid Toner', 'Torriden', 'toner', 'pump', 'Aqua, Butylene Glycol, Dipropylene Glycol, 1,2-Hexanediol, Glycerin, Betaine, Allantoin, Panthenol, Portulaca Oleracea Extract, Trehalose, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hydrolyzed Sodium Hyaluronate, Sodium Acetylated Hyaluronate, 2,3-Butanediol, Pentylene Glycol, Extrait de Malachite, Disodium EDTA, Ethylhexylglycerin', 'Le DIVE-IN Low Molecular Hyaluronic Acid Toner Torriden est un tonique méticuleusement conçu pour t''accompagner au quotidien vers une peau radieuse et profondément hydratée. Gorgé d''acide hyaluronique puissant à faible molécule, il fournit non seulement une hydratation immédiate, mais aide également la peau à conserver son hydratation tout au long de la journée. L''acide hyaluronique 5D-Complex contenu dans ce tonique opère sa magie en nourrissant et en revitalisant instantanément ta peau, la laissant avec un fini frais et lisse tout simplement irrésistible. Sa formule hypoallergénique fait en sorte que même les types de peau les plus sensibles puissent se délecter de son hydratation rafraîchissante. Dévoile un éclat naturel avec le tonique DIVE-IN de Torriden, une étape essentielle de ta routine beauté quotidienne. Ce tonique va au-delà de l''hydratation de surface, grâce à ses ingrédients soigneusement sélectionnés comme l''allantoïne et l''extrait de Portulaca Oleracea, qui exfolient ta peau en douceur tout en lui apportant un confort apaisant. Sa texture aqueuse, associée à une couleur naturelle bleu pastel dérivée de l''extrait de malachite, assure une absorption rapide, laissant à ta peau une sensation de fraîcheur et de revitalisation. Dis adieu à la peau terne et desséchée en te plongeant dans les bienfaits hydratants de ce tonique. Améliore ta routine beauté avec cette lotion tonique de Torriden et offre à ta peau épanouie un regain de vitalité. Recommandé pour : Peaux sensibles, peaux sujettes à l''acné fongique, tous types de peaux.', 300, 'ml', 'torriden-dive-in-low-molecular-hyaluronic-acid-toner', 'https://korean-skincare.fr/products/torriden-dive-in-low-molecular-hyaluronic-acid-toner', 'https://aurore-cdn.b-cdn.net/products/torriden-dive-in-low-molecular-hyaluronic-acid-toner.webp', 'Distribue une quantité appropriée de produit sur un disque de coton et passe-le sur l''ensemble de ton visage pour affiner ta peau. Tu peux aussi appliquer une quantité modérée sur tes mains, puis sur ton visage, et tapoter légèrement pour une meilleure absorption.', 2495, '2026-05-07 17:37:39.35562+00', '2026-06-14 15:14:07.571+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-41a2-71bc-923c-e2e42f6ce5a9', '__OWNER_ID__', 'Hyaluronic Acid Toner Plus', 'ISNTREE', 'toner', 'pump', 'Aqua, Propanediol, 1,2-Hexanediol, Sodium Hyaluronate, Trehalose, Sodium PCA, Biosaccharide Gum-1, Glycerin, Hyaluronic Acid, Camellia Sinensis Leaf Extract, Glycyrrhiza Glabra Root Extract, Chamomilla Recutita (Matricaria) Flower Extract, Rosmarinus Officinalis Leaf Extract, Extrait de Racine de Polygonum Cuspidatum, Centella Asiatica Extract, Aloe Barbadensis Leaf Extract, Extrait de Racine d''Althaea Rosea, Jus de Bouleau (Betula Alba), Portulaca Oleracea Extract, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Beta-Glucan, Betaine, Panthenol, Cellulose Gum, Pentylene Glycol, Caprylyl Glycol, Butylene Glycol, Ethylhexylglycerin, Extrait de Racine de Scutellaria Baicalensis', 'Le Hyaluronic Acid Toner Plus ISNTREE est un tonique qui renforce l''hydratation en profondeur et aide les produits de soin suivants à mieux pénétrer dans la peau. Formulé avec cinq types d''acide hyaluronique, sept types d''extraits botaniques, et des ingrédients phyto-oglio brevetés, ce tonique aide à une rétention rapide et efficace de l''hydratation.', 200, 'ml', 'isntree-hyaluronic-acid-toner-plus', 'https://korean-skincare.fr/products/isntree-hyaluronic-acid-toner-plus', 'https://aurore-cdn.b-cdn.net/products/isntree-hyaluronic-acid-toner-plus.webp', 'Applique quelques gouttes de tonique dans tes mains avec un disque de coton. Tapote délicatement sur l''ensemble de ton visage et de ton cou nettoyés pour un résultat optimal. Fais suivre d''un sérum et d''une crème hydratante.', 1660, '2026-05-07 17:37:39.745931+00', '2026-06-14 15:14:07.571+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-424b-7f2a-a2ae-3eae1100b8f3', '__OWNER_ID__', 'Mist Toner', 'Pyunkang Yul', 'mist', 'spray', 'Coptis Chinensis Root Extract, 1,2-Hexanediol, Butylene Glycol, Glycerin, Sodium Hyaluronate', 'Le Mist Toner Pyunkang Yul procure des effets rafraîchissant apaisant instantanés à la peau. C''est une brume tonique hydratante et pratique composée à 91,9 % d''extrait de racine d''épine-vinette, un puissant antioxydant connu pour ses propriétés anti-inflammatoires, énergisantes et nourrissantes. La brume tonique Pyunkang Yul pénètre rapidement dans ta peau pour l''hydrater et la rafraîchir. Elle est idéale pour être utilisée comme tonique dans ta routine beauté ou comme brume à n''importe quel moment de la journée (elle est parfaite pour être appliquée par-dessus le maquillage).', 200, 'ml', 'pyunkang-yul-mist-toner', 'https://korean-skincare.fr/products/pyunkang-yul-mist-toner', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-mist-toner.webp', 'Après le nettoyage, tiens le flacon à une distance de 18 à 20 centimètres et vaporise. Fais suivre d''un sérum et d''une crème hydratante. Utilise la brume pour rafraîchir ta peau tout au long de la journée.', 1464, '2026-05-07 17:37:39.915841+00', '2026-06-14 15:14:07.572+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-40aa-71a0-9dc9-5ae3d00d83d0', '__OWNER_ID__', 'Madagascar Centella Hyalu-Cica Brightening Toner', 'SKIN1004', 'toner', 'pump', 'Centella Asiatica Leaf Water, Butylene Glycol, Glycerin, 1,2-Hexanediol, Niacinamide, Aqua, Betaine, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Hibiscus Esculentus Fruit Extract, Xylitol, Polyglyceryl-10 Oléate, Polyglyceryl-10 Myristate, Polyglyceryl-6 Dioleate, Pyrus Communis Fruit Extract, Pentylene Glycol, Polyglyceryl-4 Laurate, Ethylhexylglycerin, Rosa Damascena Flower Water, Adenosine, Cucumis Melo Fruit Extract, Extrait De Racine D''Iris Florentina, Extrait De Feuille/Tige De Hedera Helix, Sodium Phytate, Methylpropanediol, Gomme Xanthane, Citric Acid, Artemisia Princeps Leaf Extract, Caprylic/Capric Triglyceride, Polyglutamic Acid, Hydrogenated Lecithin, Ceramide NP, Capryloyl Salicylic Acid', 'Le Madagascar Centella Hyalu-Cica Brightening Toner SKIN1004 est un tonique rafraîchissant aux multiples bienfaits qui hydrate, éclaircit et lisse la peau. Infusé de Centella Asiatica et d''acide hyaluronique, il hydrate en profondeur tandis que les AHA et LHA exfolient en douceur pour un teint plus clair et plus éclatant. Il aide également à améliorer la texture de la peau, pour une apparence plus douce, équilibrée et revitalisée. Recommandé pour : Tous types de peaux.', 210, 'ml', 'madagascar-centella-hyalu-cica-brightening-toner', 'https://korean-skincare.fr/products/madagascar-centella-hyalu-cica-brightening-toner', 'https://aurore-cdn.b-cdn.net/products/madagascar-centella-hyalu-cica-brightening-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 1402, '2026-05-07 17:37:39.497921+00', '2026-06-14 15:14:07.572+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4133-7ca5-8890-94f2929af006', '__OWNER_ID__', 'Wonder Releaf Centella Toner Unscented', 'Purito Seoul', 'toner', 'pump', 'Aqua, Butylene Glycol, Pentylene Glycol, Dipropylene Glycol, 1,2-Hexanediol, Centella Asiatica Extract, Sodium Hyaluronate, Panthenol, Madecassoside, Asiaticoside, Acide Madécassique, Acide Asiatique, Trehalose, Carbomer, Allantoin, Arginine, Ethylhexylglycerin, Disodium EDTA, Portulaca Oleracea Extract', 'Découvre le Wonder Releaf Centella Toner Unscented Purito SEOUL, anciennement connu sous le nom de Centella Unscented Toner, désormais repackagé pour offrir des bienfaits de soin renforcés. Infusé de cica, de panthénol et de sodium hyaluronate, ce tonique sans parfum est spécialement conçu pour apaiser les irritations, retenir l’hydratation et renforcer la barrière cutanée. Cliniquement testé et doux pour les peaux sensibles, il procure un soulagement rapide des rougeurs et irritations dès la première application, apportant confort et apaisement immédiats. Conçu pour préserver l’hydratation et maintenir l’équilibre huile-eau de la peau, il vivifie l’épiderme avec une vague de fraîcheur hydratante, laissant un fini lumineux et éclatant. Recommandé pour : Peaux sujettes à l’acné fongique, peaux sensibles, tous types de peaux.', 200, 'ml', 'purito-wonder-releaf-centella-toner-unscented', 'https://korean-skincare.fr/products/purito-wonder-releaf-centella-toner-unscented', 'https://aurore-cdn.b-cdn.net/products/purito-wonder-releaf-centella-toner-unscented.webp', 'Applique une quantité appropriée dans ta main ou sur un coton. Fais pénétrer en suivant délicatement les lignes de ton visage, en évitant le contour des yeux et de la bouche. Tapote délicatement pour favoriser l’absorption.', 2248, '2026-05-07 17:37:39.635638+00', '2026-06-14 15:14:07.572+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4173-70e6-bc45-4d213195fa75', '__OWNER_ID__', 'Wonder Releaf Centella Toner', 'Purito Seoul', 'toner', 'pump', 'Aqua, Butylene Glycol, Pentylene Glycol, Dipropylene Glycol, 1,2-Hexanediol, Centella Asiatica Extract, Panthenol, Sodium Hyaluronate, Trehalose, Laurate de Polyglyceryl-10, Myristate de Polyglyceryl-10, Glycerin, Carbomer, Allantoin, Arginine, Ethylhexylglycerin, Disodium EDTA, Portulaca Oleracea Extract, Huile de Fruit de Citrus Aurantium Bergamia, Pelargonium Graveolens Oil, Cananga Odorata Flower Oil, Huile de Fleur de Rose, Citronellol, Limonene, Linalool', 'Découvre le nouveau packaging du Wonder Releaf Centella Toner Purito SEOUL, anciennement connu sous le nom de Centella Green Level Calming Toner. Enrichi en cica, panthénol et sodium hyaluronate, cette formule vegan et cliniquement testée est spécialement conçue pour les peaux hypersensibles. Dès la première application, il soulage rapidement irritations et rougeurs, apportant un confort immédiat et un effet apaisant. Conçu pour préserver l’hydratation et maintenir l’équilibre huile-eau de la peau, il procure une vague de fraîcheur vivifiante qui redynamise l’épiderme. Formulé avec de la Centella Asiatica pour un apaisement rapide, du sodium hyaluronate pour retenir l’hydratation et du panthénol pour renforcer la barrière cutanée, ce tonique laisse un fini lumineux et éclatant. Recommandé pour : Peaux sèches, tous types de peaux.', 200, 'ml', 'purito-soule-wonder-releaf-centella-toner', 'https://korean-skincare.fr/products/purito-soule-wonder-releaf-centella-toner', 'https://aurore-cdn.b-cdn.net/products/purito-soule-wonder-releaf-centella-toner.webp', 'Applique une quantité appropriée sur un coton ou dans ta main. Fais pénétrer en suivant délicatement les lignes de ton visage. Tapote délicatement pour favoriser l’absorption.', 2150, '2026-05-07 17:37:39.698926+00', '2026-06-14 15:14:07.572+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-41cf-7cda-9731-5062c12201e6', '__OWNER_ID__', 'Hyaluronic Acid Water Mist', 'ISNTREE', 'mist', 'spray', 'Aqua, Propanediol, 1,2-Hexanediol, Caprylic/Capric Triglyceride, Laurate de Polyglycéryl-10, Sesquioleate de Sorbitan, Sodium Hyaluronate, Ethylhexylglycerin, Pentylene Glycol, Trehalose, Centella Asiatica Extract, Betaine, Beta-Glucan, Sodium PCA, Extrait de Jus de Vitis Vinifera, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Xylitylglucoside, Anhydroxylitol, Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Pelargonium Graveolens Oil, Allantoin, Xylitol', 'La Hyaluronic Acid Water Mist Isntree est une brume tonique qui utilise de l''acide hyaluronique de poids moléculaire multiple, pénétrant chaque facette de ta peau comme une symphonie d''hydratation. Conçue avec précision, sa liste d''ingrédients témoigne d''un soin cosmétique à la pointe de la technologie. Le hyaluronate de sodium, l''ingrédient vedette, possède des capacités remarquables de rétention de l''hydratation, assurant la souplesse et l`éclat de la peau. L''extrait de Centella Asiatica apaise, tandis que l''acide hyaluronique hydrolysé, l''hyaluronate de sodium hydrolysé et le crosspolymère d''hyaluronate de sodium travaillent en harmonie pour agir sur les différentes couches de la peau. Anticipant les effets du temps, cette brume protège de manière proactive contre la perte en hydratation et maintient l''élasticité de la peau. L''allantoïne réconforte, tandis que l''huile de fleur de Pelargonium Graveolens ajoute une touche sensorielle. Élevant les soins de la peau au rang de célébration du soin de soi, cette brume offre non seulement une nutrition optimale, mais aussi une véritable expérience sensorielle. Profite de la fusion de la science et de la nature pour dévoiler une peau plus douce, plus lisse et résistante aux signes du temps. Embrasse chaque goutte comme une étreinte rajeunissante et laisse ta peau se délecter de cette essence régénératrice. Recommandé pour : Tous types de peaux.', 100, 'ml', 'isntree-hyaluronic-acid-water-mist', 'https://korean-skincare.fr/products/isntree-hyaluronic-acid-water-mist', 'https://aurore-cdn.b-cdn.net/products/isntree-hyaluronic-acid-water-mist.webp', 'Après avoir nettoyé ton visage, tiens la bouteille à 20 cm de ton visage, ferme les yeux et vaporise délicatement. Tapote délicatement ta peau pour faire pénétrer le produit. Autre solution : vaporise directement sur un coton ou dans tes paumes et applique délicatement sur ton visage.', 1855, '2026-05-07 17:37:39.791581+00', '2026-06-14 15:14:07.573+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6515-7734-b860-536d620a7875', '__OWNER_ID__', 'Uriage Xemose C8+ Huile lavante anti-grattage 500ml', 'Uriage', 'body-wash', 'jar', 'AQUA (WATER, Aqua, Sorbitol, Glycerin, Sodium Laureth Sulfate, Coco-Glucoside, SODIUM COCOAMPHOACETATE, SODIUM METHYL COCOYL TAURATE, Caprylyl Glycol, Citric Acid, Sodium Benzoate, Glyceryl Oleate, POLYQUATERNIUM-10, PEG-75 SHEA BUTTER GLYCERIDES, SHEA, SAFFLOWER OIL/PALM OIL AMINOPROPANEDIOL ESTERS, POLYGLYCERYL-10 STEARATE, Tocopherol, TRIETHYL CITRATE, POLYGLYCERYL-6 BEHENATE, HYDROGENATED VEGETABLE GLYCERIDES CITRATE, BEHENIC ACID, Ceramide NP, Cetearyl Alcohol, Cholesterol, Glyceryl Stearate, Lactic Acid, Ceramide NS, Ceramide EOP, Ceramide AP, SODIUM CETEARYL SULFATE', '', 500, 'ml', 'uriage-xemose-c8-huile-lavante-anti-grattage-500ml-268050', 'https://www.atida.fr/uriage-xemose-huile-nettoyante-apaisante-500ml.html', 'https://aurore-cdn.b-cdn.net/products/uriage-xemose-c8-huile-lavante-anti-grattage-500ml-268050.webp', '', 1599, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.573+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4175-7627-bb2e-a844cb1e2800', '__OWNER_ID__', 'Oat PDRN Gentle Refining Toner', 'Purito Seoul', 'toner', 'pump', 'Avena Sativa Seed Water, Aqua, Butylene Glycol, Glycerin, 1,2-Hexanediol, Hydrogenated Lecithin, Panthenol, Hydroxyacetophenone, Glyceryl Stearate, Ceramide NP, Dipotassium Glycyrrhizate, Ethylhexylglycerin, Avena Sativa Extract, Beta-Glucan, Sodium Phytate, Sodium DNA, Arginine, Citric Acid', 'L''Oat PDRN Gentle Refining Toner Purito Seoul est un tonique apaisant et régénérant conçu pour hydrater, calmer et affiner les peaux sensibles ou fragilisées. Formulé avec de l’extrait d’avoine biologique et du PDRN, ce tonique léger soutient en douceur la régénération de la peau tout en renforçant la barrière d’hydratation. Sa texture aqueuse mais nourrissante s’absorbe rapidement, préparant la peau aux étapes suivantes de ta routine sans aucune sensation collante ni irritation. Idéal pour les peaux sèches, sensibles ou sujettes aux rougeurs, ce tonique aide à lisser les textures irrégulières, améliorer la résistance de la peau et laisser le teint doux et équilibré. L''Oat PDRN Gentle Refining Toner Purito Seoul est le tonique quotidien parfait pour celles et ceux recherchant un soin apaisant avec des bienfaits réparateurs supplémentaires. Recommandé pour : Peaux sèches, sensibles, tous types de peaux.', 200, 'ml', 'purito-seoul-oat-pdrn-gentle-refining-toner', 'https://korean-skincare.fr/products/purito-seoul-oat-pdrn-gentle-refining-toner', 'https://aurore-cdn.b-cdn.net/products/purito-seoul-oat-pdrn-gentle-refining-toner.webp', 'Après le nettoyage, verse une quantité appropriée dans tes mains ou sur un coton et applique uniformément sur ton visage. Tapote délicatement pour favoriser l’absorption. Utilise matin et soir.', 2195, '2026-05-07 17:37:39.701247+00', '2026-06-14 15:14:07.573+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-41a7-7ce4-97c1-cea30c08aae0', '__OWNER_ID__', 'Ultra-Low Molecular Hyaluronic Acid Toner', 'ISNTREE', 'toner', 'pump', 'Aqua, Methylpropanediol, 1,2-Hexanediol, Sea Water, Glycerin, Betaine, Allantoin, Butylene Glycol, Caprylyl Glycol, Ethylhexylglycerin, Panthenol, Gomme Xanthane, Extrait de Malachite, Disodium EDTA, Hydrolyzed Hyaluronic Acid, Pentylene Glycol, Xylitylglucoside, Anhydroxylitol, Sodium Hyaluronate, Xylitol, Potassium Hyaluronate, Glucose, Hydrolyzed Sodium Hyaluronate, Sodium Acetylated Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Copolymère de Hyaluronate de Sodium, Hyaluronate de Diméthylsilanol, Hydrolyzed Sodium Hyaluronate, Hyaluronic Acid, Sodium Hyaluronate, Extrait d''Hamamélis de Virginie, Extrait de Feuille de Chamaecyparis Obtusa, Sodium Hyaluronate, Sodium Hyaluronate', 'L''Ultra-Low Molecular Hyaluronic Acid Toner Isntree donne un coup de fouet revitalisant grâce à sa formule légère à absorption rapide. Infusé d''eau de mer profonde riche en minéraux provenant de l''île d''Ulleung, en Corée, et de 14 types d''acide hyaluronique, ce tonique vegan hydrate et apaise la peau en profondeur, la laissant rebondie et rafraîchie. Il contient également du glycéryl glucoside pour offrir une riche hydratation, et du bêta-glucane pour renforcer la barrière d''hydratation. Enrichi de divers extraits de plantes, ce tonique calme la peau tout en assurant une hydratation durable. Recommandé pour : Sans risques pour l''acné fongique, peaux sèches, tous types de peaux.', 300, 'ml', 'isntree-ultra-low-molecular-hyaluronic-acid-toner', 'https://korean-skincare.fr/products/isntree-ultra-low-molecular-hyaluronic-acid-toner', 'https://aurore-cdn.b-cdn.net/products/isntree-ultra-low-molecular-hyaluronic-acid-toner.webp', 'Lors de la première étape après le nettoyage, prélève une quantité appropriée sur une compresse en coton et passe-la délicatement le long de la texture de ta peau pour faciliter l''absorption.', 1954, '2026-05-07 17:37:39.751625+00', '2026-06-14 15:14:07.573+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-41f9-7a72-8bbe-99d800b23523', '__OWNER_ID__', 'Onion Newpair Clear Pad', 'ISNTREE', 'toner', 'pack', 'Extrait d''Allium Cepa Bulb, Butylene Glycol, Glycerin, Aqua, 1,2-Hexanediol, Niacinamide, Houttuynia Cordata Extract, Héparine de Sodium, Panthenol, Allantoin, Trehalose, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Sodium Acetylated Hyaluronate, Beta-Glucan, Tranexamic Acid, Sodium Ascorbyl Phosphate, Gluconolactone, Hydroxyéthylcellulose de Cétyle, Adenosine, Extrait de Fleur de Melia Azadirachta, Coccinia Indica Fruit Extract, Citric Acid, Ethylhexylglycerin', 'Les Onion Newpair Clear Pads Isntree sont une solution parfaite pour les peaux à tendance acnéique, conçues pour faire disparaître les imperfections et calmer l''inflammation. Chaque compresse est enrichie d''extrait de bulbe d''Allium Cepa (oignon) et de niacinamide pour traiter efficacement les cicatrices d''acné, éclaircir les taches brunes et réduire l''hyperpigmentation. Infusées d''une essence hydratante contenant trois types d''acide hyaluronique et du bêta-glucane, ces compresses hydratent et apaisent la peau en profondeur. De plus, l''inclusion d''acide tranexamique et de dérivés de vitamine C aide à exfolier les cellules mortes de la peau et à améliorer son teint. Recommandé pour : Hyperpigmentation, sans risques pour l''acné fongique, peaux sensibles, tous types de peaux.', 250, 'ml', 'isntree-onion-newpair-clear-pad', 'https://korean-skincare.fr/products/isntree-onion-newpair-clear-pad', 'https://aurore-cdn.b-cdn.net/products/isntree-onion-newpair-clear-pad.webp', 'Après t''être lavé le visage, à l''aide d''une compresse tonique, essuie ton visage de l''intérieur vers l''extérieur le long de la texture de ta peau, en évitant le contour des yeux et de la bouche. Tu peux aussi laisser poser la compresse sur ton visage pendant 10 minutes maximum.', 2495, '2026-05-07 17:37:39.833514+00', '2026-06-14 15:14:07.573+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4303-7c2c-b9ee-32f9561cbe39', '__OWNER_ID__', 'Black Rice Hyaluronic Toner - Free of Alcohol & Fragrance', 'Haruharu Wonder', 'toner', 'pump', 'Aqua, Betaine, Glycerin, Propanediol, Extrait de Racine de Scutellaria Baicalensis, Oryza Sativa Extract, Extrait d''Écorce de Pousse de Phyllostachys Pubescens, Gomme Xanthane, Cellulose Gum, 1,2-Hexanediol, Butylene Glycol, Extrait de Pulsatilla Koreana, Zanthoxylum Piperitum Fruit Extract, Extrait de Usnea Barbata, Aspergillus Ferment, Gluconate de Sodium, Hyaluronic Acid, Beta-Glucan, Gomme de Graine de Tamarindus Indica, Panax Ginseng Root Extract, Glucose, Cyclodextrin', 'Profite de la délicate touche d''hydratation du Haruharu WONDER Black Rice Hyaluronic Toner Free of Alcohol & Fragrance, un élixir nourrissant conçu avec 95 % d''ingrédients d''origine naturelle. Cette formule sans alcool et sans parfum, enrichie de 2 000 ppm d''extrait de riz noir coréen, d''acide hyaluronique et de bêta-glucane, hydrate intensément les peaux sensibles tout en stimulant le renouvellement des cellules cutanées. Ce tonique régénère et revitalise la peau, laissant derrière lui un teint rebondi et radieux. Infusé des bienfaits puissants de l''extrait de riz noir pour améliorer l''élasticité de la peau et de l''acide hyaluronique pour une hydratation en profondeur, ce tonique est un régal luxueux pour ta peau, garantissant un visage lumineux et nourri à chaque application. Recommandé pour : Sans risque pour l''acné fongique, peaux sensibles, peaux sèches, tous types de peaux.', 300, 'ml', 'haruharu-wonder-black-rice-hyaluronic-toner-free-of-alcohol-fragrance', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-hyaluronic-toner-free-of-alcohol-fragrance', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-hyaluronic-toner-free-of-alcohol-fragrance.webp', 'Commence par nettoyer ta peau. Distribue délicatement une quantité appropriée de produit sur ta peau avec tes mains ou à l''aide d''une compresse en coton, en évitant le contour des yeux et de la bouche. Tapote légèrement pour une absorption maximale.', 2145, '2026-05-07 17:37:40.099621+00', '2026-06-14 15:14:07.576+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-41fe-7690-924c-b21945dcc438', '__OWNER_ID__', 'Yam Root Vegan Milk Toner', 'ISNTREE', 'toner', 'pump', 'Extrait de Racine Dioscorea Japonica, Glycerin, Butylene Glycol, 1,2-Hexanediol, Aqua, Trehalose, Panthenol, Helianthus Annuus Seed Oil, Limnanthes Alba Seed Oil, Macadamia Ternifolia Seed Oil, Argania Spinosa Kernel Oil, Inulin Lauryl Carbamate, Sodium Surfactin, Ceramide NP, Cholesterol, Stearic Acid, Deoxyphytantriyl Palmitamide MEA, Caprylic/Capric Triglyceride, Hydrogenated Lecithin, Hibiscus Esculentus Fruit Extract, Extrait de racine de Nelumbo Nucifera, Undaria Pinnatifida Extract, Laminaria Japonica Extract, Extrait de graines de Glycine Max, Extrait de fruit de Cocos Nucifera, Oryza Sativa Extract, Extrait de graines de Prunus Amygdalus Dulcis, Extrait de son d''avoine (Avena Sativa), Extrait de malt, Pentylene Glycol, Caprylyl Glycol, Hydroxyacetophenone, Polyacrylate de sodium, Citric Acid, Disodium EDTA', 'Le Yam Root Vegan Milk Toner Isntree est un tonique profondément hydratant infusé avec 80 % d''extrait de racine d''igname d''Andong pour nourrir et hydrater la peau. Formulé avec de la phyto-mucine botanique et de l''eau lipidique, notamment du stéarate de céramide NP, du cholestérol, de l''acide stéarique et de la lécithine hydrogénée, ce tonique renforce la barrière cutanée, offrant ainsi une protection contre les facteurs d''agression externes. Riche en huiles et en extraits naturels comme l''huile de graines de tournesol, l''huile de graines de Limnanthes Alba, l''huile de graines de macadamia et l''huile d''argan, il apporte une couche supplémentaire d''hydratation et de nutrition. Recommandé pour : Peaux sèches, mixtes ou normales.', 200, 'ml', 'isntree-yam-root-vegan-milk-toner', 'https://korean-skincare.fr/products/isntree-yam-root-vegan-milk-toner', 'https://aurore-cdn.b-cdn.net/products/isntree-yam-root-vegan-milk-toner.webp', 'Agite bien pour mélanger le contenu avant de l''utiliser. Prélève une quantité adéquate de produit sur une compresse de coton, ou dans tes paumes, et applique-le sur ta peau. Tapote délicatement le produit sur ta peau pour favoriser son absorption. *Lorsque ta peau est plus sèche que d''habitude, applique le tonique 2 ou 3 fois à la suite et laisse-le pénétrer.', 1757, '2026-05-07 17:37:39.838254+00', '2026-06-14 15:14:07.573+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6572-7966-8258-d932efb82163', '__OWNER_ID__', 'Dexeryl Essentiel Crème Lavante 200ml', 'Dexeryl', 'body-wash', 'jar', 'Aqua, Glycerin, cetearth-60 myristyl glycol, Coco-Glucoside, zinc coceth sulfate, sodium cocamphoacetate, Polysorbate 20, Ascorbyl Palmitate, Benzoic Acid, BHT, Citric Acid, disodium laureth sulfosucconate, Glyceryl Oleate, hydrogenated palm glycerides citrate, Laureth-3, Lecithin, maleic acid, Microcrystalline Wax, Paraffinum Liquidum, Paraffin, Sodium Benzoate, Sodium Chloride, Sodium Hydroxide, Styrene/Acrylates Copolymer, Tocopherol, xanthan gum', '', 200, 'ml', 'dexeryl-essentiel-creme-lavante-200ml-268042', 'https://www.atida.fr/dexeryl-essentiel-creme-lavante-200ml.html', 'https://aurore-cdn.b-cdn.net/products/dexeryl-essentiel-creme-lavante-200ml-268042.webp', '', 639, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.574+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4263-7458-a950-5721c3735cd3', '__OWNER_ID__', 'ACNE Toner', 'Pyunkang Yul', 'toner', 'pump', 'Aqua, Butylene Glycol, Dimethyl Sulfone, Chlorhydrate de Pyridoxine, Salix Alba Bark Extract, Niacinamide, Extrait de Fruit de Forsythia Suspensa, Centella Asiatica Extract, Extrait de Racine de Polygonum Cuspidatum, Extrait de Racine de Scutellaria Baicalensis, Camellia Sinensis Leaf Extract, Glycyrrhiza Uralensis Root Extract, Chamomilla Recutita (Matricaria) Flower Extract, Rosmarinus Officinalis Leaf Extract, Copper Tripeptide-1, Glycerin, Hydroxyacetophenone, Extrait de Myrtus Communis, Extrait de Tropaeolum majus, Ethylhexylglycerin, Disodium EDTA', 'L''Acne Toner Pyunkang Yul est un tonique léger qui aide à exfolier en douceur les cellules mortes de la peau, à contrôler l''excès de sébum et à réduire les pores. L''extrait d''écorce de saule élimine les impuretés pour une texture de peau plus lisse, tandis que les extraits de matricaire et d''hydrocotyle asiatique aident à calmer l''acné et à revitaliser la peau.', 150, 'ml', 'pyunkang-yul-acne-toner', 'https://korean-skincare.fr/products/pyunkang-yul-acne-toner', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-acne-toner.webp', 'Distribue une quantité de produit suffisante sur un coton Passe-le sur l''ensemble de ton visage Retourne le coton et tapote doucement pour absorber l''excédent de produit', 1027, '2026-05-07 17:37:39.939089+00', '2026-06-14 15:14:07.574+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4240-7783-ab47-f0fa0588889a', '__OWNER_ID__', 'Essence Toner', 'Pyunkang Yul', 'toner', 'pump', 'Extrait de Racine d''Astragale (Astragalus Membranaceus), 1,2-Hexanediol, Butylene Glycol, Bis-PEG-18 Éther Méthylique Diméthyl Silane, Hydroxyéthylcellulose, Carbomer, Arginine', 'Découvre le pouvoir hydratant de l''Essence Toner Pyunkang Yul. Formulée avec de l''extrait de racine d''Astragalus Membranaceus, cette essence tonique nourrit et revitalise la peau en profondeur. Grâce à sa texture légère et rapidement absorbée, il délivre une vague d''hydratation, laissant ta peau rebondie et rafraîchie. Dis adieu à la sécheresse et bonjour à un teint radieux avec l''Essence Toner Pyunkang Yul. L''Essence Toner est le produit le plus vendu de Pyunkang Yul. Il s''agit d''une marque de soins de la peau lancée par la célèbre clinique de médecine orientale Pyunkang, un établissement bien connu pour traiter les troubles cutanés atopiques en se concentrant sur l''utilisation d''ingrédients coréens traditionnels ou hanbang. La marque est cruelty-free et respectueuse de l''environnement. Elle évite les tests sur les animaux et n''utilise pas de matières plastiques en excès. Recommandé pour : Peaux sèches, peaux à tendance acnéique. Peut être utilisé pour : Tous types de peaux.', 200, 'ml', 'pyunkang-yul-essence-toner', 'https://korean-skincare.fr/products/pyunkang-yul-essence-toner', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-essence-toner.webp', 'Nettoie ton visage à l''aide d''un nettoyant doux. Après le nettoyage, verse une petite quantité de l''Essence Toner Pyunkang Yul sur tes paumes ou sur un disque de coton. Applique délicatement le tonique sur ton visage et ton cou, en commençant par le centre et en allant vers l''extérieur. Laisse le tonique pénétrer complètement dans ta peau. Applique ensuite ta crème hydratante ou ton sérum préféré pour plus d''hydratation et de bienfaits.', 1464, '2026-05-07 17:37:39.90434+00', '2026-06-14 15:14:07.574+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-426e-7875-bcf7-01d33212ab22', '__OWNER_ID__', 'Calming Moisture Mist', 'Pyunkang Yul', 'mist', 'spray', 'Aqua, Glycerin, Ethylhexyl Palmitate, 1,2-Hexanediol, Butylene Glycol, Hydroxypropyl Bislauramide MEA, Méthyl Gluceth-10, Tétraisostéarate de Sorbeth-30, Dipropylene Glycol, Panthenol, Sesquiisostéarate de Sorbitan, Copolymère d''acrylates/béhénate-25 de méthacrylate, Sodium Citrate, Tromethamine, PPG-8-Céteth-20, Citric Acid, Huile de Fruit de Citrus Aurantium Bergamia (Bergamote), Hydrogenated Lecithin, Cetearyl Alcohol, Stearic Acid, Ceramide NP, Ceramide NS, Cholesterol, Phytosphingosine, Ceramide AP, Ceramide AS, Ceramide EOP', 'La Calming Moisture Misture Pyunkang Yul est une brume pour le visage qui augmente instantanément le niveau d''hydratation des peaux délicates. Elle contient des extraits de bambou, de cica, d''arbre à thé, de chèvrefeuille et d''écorce de saule blanc pour des effets apaisants, du panthénol et cinq types d''acide hyaluronique pour l''hydratation, ainsi que de l''AHA et du PHA pour une exfoliation en douceur.', 100, 'ml', 'pyunkang-yul-calming-moisture-mist', 'https://korean-skincare.fr/products/pyunkang-yul-calming-moisture-mist', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-calming-moisture-mist.webp', 'Vaporise sur le visage à une distance de 20 à 30 cm n''importe où et n''importe quand tu ressens un besoin d''hydratation. Peut être utilisé par-dessus du maquillage, sur tes cheveux ou même sur ton corps.', 1317, '2026-05-07 17:37:39.950348+00', '2026-06-14 15:14:07.574+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44fb-7adc-b183-17773a5bc6fe', '__OWNER_ID__', 'Yuja Niacin 30 Days Miracle Brightening Toner', 'SOME BY MI', 'toner', 'pump', 'Citrus Junos Fruit Extract, Niacinamide, 1,2-Hexanediol, Glycerin, Laurate de polyglycéryl-10, C12-14 Pareth-7, Aqua, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Ethylhexylglycerin, Huile de zeste de Citrus Junos (500 ppm), Butylene Glycol, Adenosine, Tromethamine, Disodium EDTA, Coptis Chinensis Root Extract, Hydrogenated Lecithin, Stéarate de polyglycéryl-10, Panthenol, Sodium Ascorbyl Phosphate, Extrait de Saussurea Involucrata, Bisabolol, Maltodextrin, Protéine végétale hydrolysée, Sambucus Nigra Flower Extract, Extrait de fleur d''oranger Citrus Aurantium Dulcis, Extrait de fleur de Magnolia Liliflora, Extrait de fleur de Plumeria Rubra, Extrait de Lilium Tigrinum, Acide folique, Biotin, Pyridoxine, Extrait de Pancratium Maritimum, Tocopherol, Cyanocobalamin, Acide linoléique, Chlorhydrate de thiamine, Bêta-carotène, Riboflavine, Inositol, Limonene', 'Le Yuja Niacin 30 Days Miracle Brightening Toner SOME BY MI est un tonique quotidien hautement concentré qui peut aider à cibler le teint terne, les imperfections et l''hyperpigmentation. Il est enrichi à 90 % d''extrait de yuja (cédrat) riche en vitamine C pour éclaircir et hydrater. Le niacinamide, l''arbutine et le glutathion aident à unifier ton teint, tandis que 12 types de vitamines revitalisent et apaisent ta peau pour un teint frais et satiné. Recommandé pour :', 150, 'ml', 'some-by-mi-yuja-niacin-30-days-miracle-brightening-toner', 'https://korean-skincare.fr/products/some-by-mi-yuja-niacin-30-days-miracle-brightening-toner', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-yuja-niacin-30-days-miracle-brightening-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 1845, '2026-05-07 17:37:40.603562+00', '2026-06-14 15:14:07.574+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42ad-74f7-9023-ddb66eea894b', '__OWNER_ID__', 'Ultimate Calming Solution Toner', 'Pyunkang Yul', 'toner', 'pump', 'Aqua, Glycerin, Phellodendron Amurense Bark Extract, Cetearyl Alcohol, Extrait d''écorce de Paeonia Lactiflora, Cetyl Alcohol, Glyceryl Stearate, Extrait de racine de Scutellaria Baicalensis, Stearyl Alcohol, Caprylic/Capric Triglyceride, Cetyl Ethylhexanoate, Extrait de Mentha Arvensis, Dipropylene Glycol, Hydroxyacéto phénone, Carbomer, Palmitic Acid, Stearic Acid, 1,2-Hexanediol, Arginine, Myristyl Alcohol, Ethylhexylglycerin, Alcool Laurique, Citrus Aurantium Dulcis Peel Oil, Huile de fruit de Citrus Aurantium Bergamia, Mentha Piperita Oil, Myristic Acid, Squalane, Butyrospermum Parkii Butter, Lonicera Japonica Flower Extract, Butylene Glycol, Ceramide NP, Huile de graine d''Adansonia Digitata, Hydrogenated Lecithin, Pentylene Glycol, Melaleuca Alternifolia Leaf Extract, Sodium Hyaluronate, Tocopherol, Caprylyl Glycol, Sodium Hyaluronate Crosspolymer, Ceramide NP, Hydrolyzed Hyaluronic Acid, Centella Asiatica Extract, Ceramide EOP, Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Madecassoside, Acide Madécassique, Asiaticoside, Acide Asiatique, Limonene, Citronellol, Geraniol, Linalool', 'L''Ultimate Calming Solution Toner Pyunkang Yul offre une solution de soin complète en combinant une exfoliation délicate et des propriétés apaisantes, ce qui permet de soulager efficacement les peaux irritées. Infusé d''un mélange d''extrait de Centella Asiatica, d''extrait d''arbre à thé et d''extrait de fleur de chèvrefeuille, ce tonique calme et rétablit l''équilibre eau-huile de la peau. Il contient de l''extrait d''écorce de Phellodendron Amurense et de l''extrait d''écorce/de sève de Paeonia Lactiflora pour combattre les bactéries responsables de l''acné tout en améliorant le teint et la texture de la peau. Enrichi de cinq types de céramides et d''acides hyaluroniques, il hydrate et renforce la barrière d''hydratation de la peau. Recommandé pour : Peaux sèches, tous types de peaux.', 110, 'ml', 'pyunkang-yul-ultimate-calming-solution-toner', 'https://korean-skincare.fr/products/pyunkang-yul-ultimate-calming-solution-toner', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-ultimate-calming-solution-toner.webp', 'Après avoir nettoyé ta peau, applique le produit sur ta peau en évitant le contour des yeux et de la bouche. Tapote légèrement ta peau pour faciliter l''absorption.', 1954, '2026-05-07 17:37:40.013169+00', '2026-06-14 15:14:07.575+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42bb-721a-a316-6e30050141e6', '__OWNER_ID__', 'Black Tea Deep Infusion Toner', 'Pyunkang Yul', 'toner', 'pump', 'Aqua, Butylene Glycol, Glycerin, Glycereth-26, Niacinamide, Taurate de Polyacryloyldiméthyl Taurate de Sodium, Caprylyl Glycol, Ether de Dicaprylyl, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Diméthicone/Vinyl Diméthicone Crosspolymer, Hydroxyacetophenone, Pentylene Glycol, Tromethamine, Camellia Sinensis Leaf Extract, Dipropylene Glycol, Maltodextrin, Ethylhexylglycerin, Polysilicone-15, Caramel, Adenosine, Dilaurate de Polyglyceryl-10, Gomme Xanthane, Extrait de Eclipta Prostrata, Coccinia Indica Fruit Extract, Disodium EDTA, Silica, Methylpropanediol, Panthenol, Hippophae Rhamnoides Fruit Extract, Extrait de Beurre de Karité, Myristate de Polyglyceryl-10, 1,2-Hexanediol, Caprylic/Capric Triglyceride, Macadamia Ternifolia Seed Oil, Extrait de Baie de Panax Ginseng, Ethylhexyl Palmitate, Cetyl Ethylhexanoate, Phellodendron Amurense Bark Extract, Coptis Japonica Root Extract, Extrait de Racine de Scutellaria Baicalensis, Extrait de Scrophularia Buergeriana, Glutamate de Lauroyl de Phytostérols/Behenyl/Octyldodécyle, Cholesterol, Extrait de Racine de Piper Methysticum, Gardenia Florida Fruit Extract, Stérols de Brassica Campestris, Hydrogenated Lecithin, Acetyl Hexapeptide-8, Fructose, Saccharomyces Ferment Filtrate, Oléate de Polyglyceryl-10, Sodium Hyaluronate, Centella Asiatica Extract, Glucose, Phosphate de Cétyl de Potassium, Ceramide NP, Beta-Glucan, Hydrolyzed Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Sodium Hyaluronate Crosspolymer, Acide Asiaticique, Asiaticoside, Sodium Acetyl Hyaluronate, Ceramide NS, Acide Madécassique, Madecassoside, Ceramide EOP', 'Le Black Tea Deep Infusion Toner Pyunkang Yul est un puissant tonique anti-âge. Il est formulé avec du thé noir fermenté pour nourrir la peau en profondeur ainsi qu''avec des peptides et de l''adénosine pour éclaircir le teint et atténuer l''apparence des rides et ridules. L''ajout de kombucha et d''armoise permet en outre d''obtenir un pouvoir antioxydant profond. Ce tonique hydratant rééquilibre le ratio huile/eau des peaux fatiguées et leur confère un éclat radieux.', 130, 'ml', 'pyunkang-yul-black-tea-deep-infusion-toner', 'https://korean-skincare.fr/products/pyunkang-yul-black-tea-deep-infusion-toner', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-black-tea-deep-infusion-toner.webp', 'Prélève 1 à 2 pompes de produit, puis applique-le sur l''ensemble de ton visage en effectuant un mouvement de massage.', 2785, '2026-05-07 17:37:40.026813+00', '2026-06-14 15:14:07.575+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42e7-7377-b401-bb64e85b9d61', '__OWNER_ID__', 'Calming Toner Pad', 'Pyunkang Yul', 'toner', 'pack', 'Aqua, Butylene Glycol, Propanediol, Glycerin, Allantoin, Pentylene Glycol, Panthenol, Dipropylene Glycol, Melaleuca Alternifolia Leaf Extract, Salix Alba Bark Extract, 1,2-Hexanediol, Gluconolactone, Sodium Hyaluronate, Extrait de Bambusa Vulgaris, Cetyl Ethylhexanoate, Ethylhexyl Palmitate, Caprylic/Capric Triglyceride, Hydrolyzed Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Lonicera Japonica Flower Extract, Centella Asiatica Extract, Sodium Hyaluronate Crosspolymer, Sodium Acetyl Hyaluronate, C12-14 Pareth-12, Madecassoside, Acide madécassique, Asiatocoside, Acide asiatique, Citric Acid, Myristate de Polyglyceryl-10, Ethylhexylglycerin, Disodium EDTA, Caprylyl Glycol, Hydroxyacetophenone', 'Le Calming Toner Pad Pyunkang Yul est un tonique exfoliant destiné à tous ceux qui recherchent un exfoliant chimique à la fois doux et apaisant, mais aussi efficace. Les AHA et PHA éliminent les cellules mortes et les impuretés de la peau. L''extrait d''écorce de saule blanc contrôle l''excès de sébum, tandis que l''extrait de Centella Asiatica apaise la peau irritée. L''extrait de bambou, le panthénol et cinq types d''acide hyaluronique aident à réhydrater la peau.', 70, 'pcs', 'pyunkang-yul-calming-toner-pad', 'https://korean-skincare.fr/products/pyunkang-yul-calming-toner-pad', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-calming-toner-pad.webp', 'Après le nettoyage, prends une compresse et masse doucement ton visage avec le côté en relief, en évitant le contour des yeux. Retourne la compresse et passe-la sur ton visage en utilisant le côté doux. Replace le couvercle hermétiquement pour t''assurer que les compresses restent humides et propres.', 1661, '2026-05-07 17:37:40.07115+00', '2026-06-14 15:14:07.575+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64dd-7a19-b471-270da7ed7025', '__OWNER_ID__', 'Bioderma Nodé Shampoing Antipelliculaire Purifiant Cuir Chevelu Gras 400ml', 'Bioderma', 'shampoo', 'jar', 'Aqua, magnesium laureth sulfate, Sodium Lauroyl Sarcosinate, sodium cocoamphoacetate, Panthenol, Disodium EDTA, Polysorbate 20, zinc gluconate, Mannitol, Xylitol, Rhamnose, Fructooligosaccharides, climbazole, Piroctone Olamine, Salicylic Acid, Coco-Glucoside, Glyceryl Oleate, Polyacrylate Crosspolymer-6, peg-90 glyceryl isostearate, polyquaternium-7, laureth 2, Sodium Hydroxide, Citric Acid, Sodium Benzoate, Parfum, Hexyl Cinnamal, Limonene, Sodium Chloride, Linalool, citronellol. [bi 678]', '', 400, 'ml', 'bioderma-node-shampoing-antipelliculaire-purifiant-cuir-chevelu-gras-400ml-256413', 'https://www.atida.fr/bioderma-node-p-shampooing-purifiant-antipelliculaire-400ml.html', 'https://aurore-cdn.b-cdn.net/products/bioderma-node-shampoing-antipelliculaire-purifiant-cuir-chevelu-gras-400ml-256413.webp', '', 1018, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.575+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4335-71a1-8594-b83aadff6651', '__OWNER_ID__', 'Black Rice Probiotics Barrier 2% NAD+ Serum Mist', 'Haruharu Wonder', 'mist', 'bar', 'Aqua, Butylene Glycol, Nicotinamide Adenine Dinucleotide, 1,2-Hexanediol, Coco-Caprylate/Caprate, Potassium Cetyl Phosphate, Limnanthes Alba Seed Oil, Galactomyces Ferment Filtrate, Hydroxyacetophenone, Glycerin, Caprylic/Capric Triglyceride, Oryza Sativa Extract, Sodium Citrate, Squalane, Hydrogenated Polyisobutene, Phyllostachys Pubescens Shoot Bark Extract, Glyceryl Stearate, Propanediol, Panthenol, Bifida Ferment Lysate, Aspergillus Ferment, Cetyl Alcohol, Hydrogenated Lecithin, Ethylhexylglycerin, Polyglyceryl-10 Laurate, Polyglyceryl-3 Methylglucose Distearate, Stearyl Alcohol, Disodium EDTA, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Oryza Sativa Lees Extract, Panax Ginseng Root Extract, Myristyl Alcohol, Lauryl Alcohol, Ceramide NP, Cetearyl Alcohol, Stearic Acid, Cyclodextrin, Ceramide NS, Phytosphingosine, Cholesterol, Ceramide AS, Ceramide AP, Ceramide EOP', 'La Black Rice Probiotics Barrier 2% NAD+ Serum Mist Haruharu Wonder est une brume faciale hydratante et protectrice de la barrière cutanée qui combine les bienfaits nourrissants des probiotiques de riz noir avec 2 % de NAD+ pour rafraîchir, renforcer et revitaliser ta peau. Conçue pour apporter un boost instantané d’hydratation tout en améliorant la résistance de ta peau, cette brume sérum aide à obtenir un teint plus lisse et équilibré tout au long de la journée. Recommandé pour : Tous types de peaux, en particulier les peaux déshydratées, ternes, sensibles ou nécessitant un soutien de la barrière cutanée et un rafraîchissement quotidien.', 80, 'ml', 'haruharu-wonder-black-rice-probiotics-barrier-2-nad-serum-mist', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-probiotics-barrier-2-nad-serum-mist', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-probiotics-barrier-2-nad-serum-mist.webp', 'Agite doucement avant usage. Tiens le flacon à environ 20–30 cm de ton visage et vaporise uniformément les yeux fermés. Utilise à tout moment de la journée pour hydrater et apporter du confort. Peut être appliquée après le nettoyage et le toner comme étape hydratante, et sur le maquillage pour rafraîchir le teint.', 1695, '2026-05-07 17:37:40.148982+00', '2026-06-14 15:14:07.576+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4380-7737-956b-d40e428e7207', '__OWNER_ID__', 'Black Rice Toner', 'I''m From', 'toner', 'pump', 'Aqua, Eau de Graines d’Oryza Sativa, Éther de Dicaprylyl, Methylpropanediol, Hydrogenated Poly(C6-14 Olefin), 1,2-Hexanediol, Niacinamide, Sodium Chloride, Glycerin, Extrait de Fleurs de Melia Azadirachta, Propanediol, Hydrogenated Lecithin, Myristate de Polyglycéryl-10, Coccinia Indica Fruit Extract, Ethylhexylglycerin, Adenosine, Gomme Xanthane, Extrait de Cacao de Theobroma Cacao, Dextrin, Polyglycéryl-3, Extrait de Riz Oryza Sativa, Tocopherol, Copolymère de Sodium Hyaluronate, Laurate de Polyglycéryl-10, Butylene Glycol, Huile de Son de Riz Oryza Sativa, Polyglutamic Acid, Panthenol, Xylose, Glycolic Acid, Disodium EDTA, Anthocyane', 'Le Black Rice Toner I’m From est un tonique nourrissant, riche en antioxydants, conçu pour renforcer la barrière cutanée, améliorer l’élasticité et redonner de l’éclat à la peau. Formulé avec de l’extrait de riz noir, naturellement riche en antioxydants, ce tonique protège la peau contre les agressions environnementales tout en apportant une hydratation profonde et durable. Sa texture légère mais lactée pénètre facilement, offrant confort et douceur sans sensation de lourdeur. Enrichi en niacinamide et en acide hyaluronique, il aide à illuminer le teint, lisser la texture de la peau et soutenir la rétention d’hydratation. Doux et sans alcool, ce tonique convient à un usage quotidien pour tous les types de peaux, y compris les peaux sensibles et sèches. Recommandé pour : Tous types de peaux.', 150, 'ml', 'im-from-black-rice-toner', 'https://korean-skincare.fr/products/im-from-black-rice-toner', 'https://aurore-cdn.b-cdn.net/products/im-from-black-rice-toner.webp', 'Applique une quantité appropriée de produit sur un coton ou directement dans tes mains. Applique en suivant doucement les lignes de ta peau. Laisse le tonique pénétrer complètement avant de poursuivre ta routine beauté habituelle. Astuce : Utilise-le quotidiennement pour un teint lumineux et hydraté.', 2195, '2026-05-07 17:37:40.224263+00', '2026-06-14 15:14:07.576+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4396-778c-b526-4bb9f1b1ae69', '__OWNER_ID__', 'Supple Preparation Unscented Toner', 'Dear Klairs', 'toner', 'pump', 'Aqua, Butylene Glycol, Diméthylsulfone, Betaine, Caprylic/Capric Triglyceride, Gomme de Natto, Sodium Hyaluronate, Disodium EDTA, Centella Asiatica Extract, Glycyrrhiza Glabra Root Extract, Polyquaternium-51, Chlorphenesin, Tocopheryl Acetate, Carbomer, Panthenol, Arginine, Extrait de Fruit/Feuille/Tige de Luffa Cylindrica, Beta-Glucan, Althaea Rosea Flower Extract, Aloe Barbadensis Leaf Extract, Hydroxyéthylcellulose, Portulaca Oleracea Extract, Lysine HCL, Proline, Sodium Ascorbyl Phosphate, Acétyl Méthionine, Théanine, Copper Tripeptide-1', 'Le Supple Preparation Unscented Toner Dear Klairs est une version actualisée du Supple Preparation Facial Toner, très populaire et très apprécié, formulé sans parfum ni huiles essentielles ! Ce tonique hydratant équilibre le pH et améliore l''efficacité de ta routine beauté sans irriter les peaux sensibles. Avec un mélange apaisant d''extraits de plantes, d''acide hyaluronique hydratant et de Centella Asiatica calmante, ce tonique léger est une première étape essentielle de ta routine beauté.', 180, 'ml', 'dear-klairs-supple-preparation-unscented-toner', 'https://korean-skincare.fr/products/dear-klairs-supple-preparation-unscented-toner', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-supple-preparation-unscented-toner.webp', 'Dépose une bonne quantité de tonique sur une compresse en coton. Applique en suivant délicatement les lignes de ta peau. Retourne la compresse et tapote doucement pour faire pénétrer le produit.', 2199, '2026-05-07 17:37:40.246357+00', '2026-06-14 15:14:07.576+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43af-7412-b35b-bf4019481e51', '__OWNER_ID__', 'Fundamental Ampule Mist', 'Dear Klairs', 'mist', 'spray', 'Camellia Sinensis Leaf Water, Butylene Glycol, Glycerin, Extrait de Fruit de Luffa Cylindrica, Oryza Sativa Extract, Hibiscus Esculentus Fruit Extract, Betaine, Trehalose, 1,2-Hexanediol, Aqua, Extrait d''Artemisia Princeps, Panthenol, Sorbitol, Sesquioleate de Sorbitan, Ethylhexylglycerin, Laminaria Japonica Extract, Sodium Hyaluronate, Hydroxyéthylcellulose, Disodium EDTA, Hydrogenated Lecithin, Ceramide NP', 'La Fundamental Ampule Mist Dear Klairs est une brume à base d''eau de thé vert de première qualité, formulée avec du riz, des concombres, du gombo et de l''armoise pour une hydratation intensive et un soin antioxydant. Cette brume ampoule riche en nutriments peut également être utilisée pour remplacer le tonique dans ta routine, car elle emprisonne l''hydratation sans qu''il soit nécessaire de la superposer pour une hydratation de longue durée. Offre à ta peau une apparence saine et fraîche et lutte contre l''aspect terne en seulement quelques pulvérisations.', 125, 'ml', 'dear-klairs-fundamental-ampule-mist', 'https://korean-skincare.fr/products/dear-klairs-fundamental-ampule-mist', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-fundamental-ampule-mist.webp', 'Vaporise 2 à 3 fois sur l''ensemble de ton visage à une distance de 25 cm. Tu peux aussi utiliser cette brume à tout moment de la journée pour apaiser, rafraîchir et hydrater ta peau.', 2694, '2026-05-07 17:37:40.271142+00', '2026-06-14 15:14:07.577+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4430-7cba-b5b6-64d60031cd07', '__OWNER_ID__', 'Hyal Reyouth Toner', 'Dr. Ceuracle', 'toner', 'pump', 'Aqua, Glycerin, Methylpropanediol, Propanediol, 1,2-Hexanediol, Niacinamide, Glycérine-26, Panthenol, Butylene Glycol, Betaine, Ethylhexylglycerin, Glycéryl Glucoside, Dioscorea Japonica Root Extract, Tréhalose Glycosylé, Adenosine, Gomme Xanthane, Hydrolysat D’Amidon Hydrogéné, Raffinose, Sodium Hyaluronate, Hyaluronate Hydroxypropyltrimonium, Cellulose Gum, Lecithin, Parfum, Extrait De Graines D’Amaranthus Caudatus, Arctium Lappa Root Extract, Inulin, Extrait De Phellinus Linteus, Ulmus Davidiana Root Extract, Polyquaternium-51, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Centella Asiatica Extract, Octyldodéceth-16, Tromethamine, Biosaccharide Gum-1, Hydrolyzed Hyaluronic Acid, Sodium Acetyl Hyaluronate, Hyaluronic Acid, Sodium Hyaluronate Crosspolymer', 'Le Hyal Reyouth Toner Dr. Ceuracle est un gel tonique enrichi de six acides hyaluroniques différents, qui travaillent en harmonie pour transformer ta peau de l''intérieur. Ce tonique exceptionnel offre une hydratation ultime et un soulagement apaisant pour les peaux sèches et irritées. Sa texture gel légère pénètre sans effort dans la peau et lui apporte l''hydratation et le confort dont elle a tant besoin. Ce tonique viendra restaurer la barrière d''hydratation naturelle de ta peau, la fortifiant et la protégeant après le nettoyage. Les différents types d''acide hyaluronique pénètrent chaque couche de ta peau, assurant une hydratation profonde et durable. Enrichi de provitamines B5 et B3, ce tonique fait passer l''hydratation de ta peau à la vitesse supérieure. En formant et en renforçant la barrière d''hydratation de la peau, cette dernière reste souple et hydratée pendant une période prolongée. Pour ajouter une touche de vivacité, le fructane (un type de fructose) favorise la reproduction des cellules cutanées, tout en stimulant l''élasticité de la peau, révélant ainsi un teint plus jeune et plus résistant. Recommandé pour : Tous types de peaux.', 120, 'ml', 'dr-ceuracle-hyal-reyouth-toner', 'https://korean-skincare.fr/products/dr-ceuracle-hyal-reyouth-toner', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-hyal-reyouth-toner.webp', 'Après le nettoyage, applique une quantité modérée de tonique dans ta main ou sur un disque de coton et étale-le sur la peau. Laisse le temps au tonique de pénétrer complètement avant de procéder au reste de ta routine.', 2375, '2026-05-07 17:37:40.400704+00', '2026-06-14 15:14:07.577+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43b8-7252-b976-8d0417f0cbe8', '__OWNER_ID__', 'Supple Preparation Facial Toner', 'Dear Klairs', 'toner', 'pump', 'Aqua, Butylene Glycol, Diméthyl Sulfone, Betaine, Caprylic/Capric Triglyceride, Gomme de Natto, Sodium Hyaluronate, Disodium EDTA, Centella Asiatica Extract, Glycyrrhiza Glabra Root Extract, Polyquaternium-51, Chlorphenesin, Tocopheryl Acetate, Carbomer, Panthenol, Arginine, Extrait de fruit/feuille/tige de Luffa Cylindrica, Beta-Glucan, Althaea Rosea Flower Extract, Aloe Barbadensis Leaf Extract, Hydroxyéthylcellulose, Portulaca Oleracea Extract, Lysine HCL, Proline, Phosphate de sodium ascorbyl, Acétyl méthionine, Théanine, Lavandula Angustifolia Oil, Eucalyptus Globulus Leaf Oil, Pelargonium Graveolens Oil, Citrus Limon Peel Oil, Citrus Aurantium Dulcis Peel Oil, Cananga Odorata Flower Oil, Tripeptide-1 de cuivre', 'Le Supple Preparation Facial Toner Dear Klairs est un tonique rafraîchissant qui élimine la saleté et l''excès de sébum tout en rétablissant l''équilibre du pH. Il prépare la peau à mieux absorber les étapes suivantes de ta routine beauté, améliorant ainsi l''efficacité des sérums et des crèmes. Formulé avec des acides aminés pour réduire les irritations et hydrater la peau en profondeur, ce tonique est une étape essentielle de ta routine beauté.', 180, 'ml', 'dear-klairs-supple-preparation-facial-toner', 'https://korean-skincare.fr/products/dear-klairs-supple-preparation-facial-toner', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-supple-preparation-facial-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 2177, '2026-05-07 17:37:40.28002+00', '2026-06-14 15:14:07.577+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-46d3-7dd3-b4d9-921614c6ef98', '__OWNER_ID__', 'Dark Spot Correcting Glow Toner', 'AXIS-Y', 'toner', 'pump', 'Aqua, Butylene Glycol, Niacinamide, Ethylhexyl Stearate, Caprylic/Capric Triglyceride, Cetyl Ethylhexanoate, Glutathione, Phosphate de Sodium Ascorbyl, Salix Alba Bark Extract, Adenosine, Sodium Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Sodium Acetyl Hyaluronate, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hydrolyzed Sodium Hyaluronate, Potassium Hyaluronate, Panthenol, Squalane, Glycerin, Allantoin, Cyanocobalamin, Extrait de Fruit de Terminalia Ferdinandiana, Hippophae Rhamnoides Fruit Extract, Extrait de Fruit de Malpighia Glabra, Extrait de Brocoli (Brassica Oleracea Italica), Extrait de Racine de Morus Alba, Extrait de Graine de Phaseolus Radiatus, Extrait de Graine de Canavalia Gladiata, Extrait de Graine de Glycine Soja, Extrait de Graine de Lentille Esculenta, Extrait de Graine de Caroube (Ceratonia Siliqua), Extrait de Feuille de Centella Asiatica, Ceramide NP, Acétyl Octapeptide-3, Dipeptide-1, Tripeptide-2, Palmitoyl Dipeptide-7, Dipeptide-4, Sorbitan Stéarate, Cetyl Alcohol, 1,2-Hexanediol, Stearic Acid, Polysorbate 60, Ethylhexylglycerin, Ingrédients Non-Saponifiables d''Huile d''Olive Hydrogénée, Disodium EDTA, Hydroxypropyl Cyclodextrin, Pueraria Lobata Root Extract, Lysat de Fermentation de Lactobacillus, Chlorphenesin, Maltodextrin, Extrait de Fleur de Melia Azadirachta, Ocimum Sanctum Leaf Extract, Melia Azadirachta Leaf Extract, Arginine, Phytostérols, Carbomer, Curcuma Longa Root Extract, Extrait de Corallina Officinalis, Caprylyl Glycol, Sodium Citrate, Laurate de Polyglycéryle-10, Citric Acid', 'Le Dark Spot Correcting Glow Toner AXIS-Y offre une solution puissante mais délicate pour éclaircir et équilibrer la peau. Cette formule innovante à double couche combine 98% de glutathion pur, 5% de niacinamide et un dérivé hydrosoluble de la vitamine C pour réduire la production de mélanine, atténuer les taches brunes et rehausser l''éclat général de la peau. Présenté sous forme de brume rafraîchissante pour le visage, il apaise et hydrate avec un fini doux et non irritant, parfait pour les peaux les plus sensibles. Il a été cliniquement prouvé qu''il réduisait instantanément les rougeurs et qu''il atténuait les taches brunes en cas d''utilisation continue. Ce tonique est idéal pour un usage quotidien afin d''obtenir un teint lumineux et éclatant. Recommandé pour : Peaux sèches, hyperpigmentation, tous types de peaux.', 125, 'ml', 'axis-y-dark-spot-correcting-glow-toner', 'https://korean-skincare.fr/products/axis-y-dark-spot-correcting-glow-toner', 'https://aurore-cdn.b-cdn.net/products/axis-y-dark-spot-correcting-glow-toner.webp', 'Agite bien pour mélanger les couches de sérum et de tonique. Ferme les yeux et vaporise uniformément sur l''ensemble de ton visage, en laissant la fine brume pénétrer dans ta peau. Utilise immédiatement après le nettoyage ou l''application de ton maquillage pour retenir l''hydratation et obtenir un éclat frais et durable.', 2195, '2026-05-07 17:37:41.075702+00', '2026-06-14 15:14:07.577+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43d9-77b8-9d1f-c9de03c74b5e', '__OWNER_ID__', 'Freshly Juiced Vitamin Essence Toner', 'Dear Klairs', 'toner', 'pump', 'Aqua, Butylene Glycol, Propanediol, Niacinamide, Caprylic/Capric Triglyceride, 1,2-Hexanediol, Glycerin, Hydroxyacetophenone, Arginine, Carbomer, Glycérth-25 PCA Isostéarate, Diéthoxyéthyl Succinate, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Ethylhexylglycerin, Adenosine, Extrait de Feuille d’Eriobotrya Japonica, Extrait Hydrolysé de Gardenia Florida, Extrait Hydrolysé de Malt, Extrait Hydrolysé de Viola Tricolor, Disuccinate d’Éthylènediamine Trisodique, Squalane, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Extrait de Mentha Viridis, Sodium Hyaluronate, Tocopherol, Ferulic Acid, Lactobacillus Ferment, Extrait de Stellaria Media, Glycine Soja Oil, Stérols de Glycine Soja, Laurate d’Hexyle, Sodium Phytate, Huile d’Avocat Persea Gratissima, Ascorbic Acid, Gluconolactone, ADN de Sodium, Cetearyl Alcohol, Ascorbyl Palmitate, Citrate de Glycérides de Palme Hydrogenés, Laurate de Polyglycéryl-10, Glutathione, Hydrogenated Lecithin', 'Le Freshly Juiced Vitamin Essence Toner combine luminosité et hydratation dans une formule légère et rapidement absorbée. Enrichi en vitamine C double, libre et encapsulée, il cible les taches brunes et le teint irrégulier tout en minimisant les irritations. Le glutathion liposomal et le PDRN dérivé du riz apportent des bienfaits antioxydants et réparateurs pour la peau. Pour encore plus d’éclat, le niacinamide, le PHA (gluconolactone) et cinq types d’acide hyaluronique, incluant les formes à faible poids moléculaire et en crosspolymère, offrent une hydratation profonde et soutiennent la barrière cutanée. Vegan, cruelty-free et sans parfum artificiel, ce tonique est idéal pour une peau lumineuse sans sensation de lourdeur. Recommandé pour : Tous types de peaux.', 180, 'ml', 'dear-klairs-freshly-juiced-vitamin-essence-toner', 'https://korean-skincare.fr/products/dear-klairs-freshly-juiced-vitamin-essence-toner', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-freshly-juiced-vitamin-essence-toner.webp', 'Après le nettoyage (et éventuellement après l’étape tonique/essence), verse une quantité appropriée de produit dans ta paume ou sur un coton. Tapote doucement la formule sur ton visage et ton cou pour qu’elle soit entièrement absorbée. Poursuis avec ton sérum et/ou ta crème comme d’habitude. Astuce : Utilise ce produit matin et soir pour un effet éclaircissant optimal ; le matin, applique ensuite un écran solaire pour protéger les résultats des UV.', 1995, '2026-05-07 17:37:40.313348+00', '2026-06-14 15:14:07.577+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43de-70b7-9a6d-ad1afacdb3cb', '__OWNER_ID__', 'EGF Blue Calming Toner Pad', 'Dear Klairs', 'toner', 'pack', 'Aqua, Butylene Glycol, Glycerin, 1,2-Hexanediol, Allantoin, Trehalose, Polyglyceryl-10 Laurate, Ethylhexylglycerin, Caprylyl Glycol, Hydroxyethylcellulose, Xanthan Gum, Maltodextrin, Gardenia Florida Fruit Extract, Guaiazulene, Centella Asiatica Leaf Extract, Centella Asiatica Extract, Hamamelis Virginiana Leaf Extract, Scutellaria Baicalensis Root Extract, Protease, Lecithin, Diospyros Kaki Leaf Extract, Sodium Hyaluronate, Vitis Vinifera Fruit Extract, Potassium Hyaluronate, Carthamus Tinctorius Flower Extract, Coffea Arabica Seed Extract, Polygonum Cuspidatum Root Extract, Camellia Sinensis Leaf Extract, Castanea Crenata Shell Extract, Zanthoxylum Piperitum Fruit Extract, Dimethylsilanol Hyaluronate, Sodium Acetylated Hyaluronate, Sodium Hyaluronate Crosspolymer, Hydroxypropyltrimonium Hyaluronate, Hydrolyzed Sodium Hyaluronate, Hydrolyzed Calcium Hyaluronate, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Sodium Sulfated Hyaluronate, Sodium Stearoyl Hyaluronate, Sodium Oleoyl Hyaluronate, sh-Oligopeptide-1, sh-Polypeptide-1', 'Les EGF Blue Calming Toner Pads Dear Klairs offrent un soin apaisant et réparateur dans un format pratique de compresses pré-imprégnées, parfaites pour calmer les irritations, recharger l’hydratation et affiner la texture en un seul geste. Infusées en EGF (Epidermal Growth Factor) et en guaiazulène, ces compresses tonifiantes douces aident à réduire les rougeurs, soutenir la régénération de la peau et renforcer la barrière d’hydratation, ce qui les rend idéales pour les peaux sensibles, à tendance acnéique ou fragilisées. Chaque compresse douce et gaufrée glisse facilement sur la peau pour délivrer une essence légère et rafraîchissante tout en offrant une exfoliation douce. Les EGF Blue Calming Toner Pads Dear Klairs sont tes alliés pour un soin apaisant quotidien. Utilise-les comme étape rapide de tonique, comme mini masque ou comme reset de la peau en journée pour laisser ton teint équilibré, apaisé et visiblement plus sain. Recommandé pour : Tous types de peaux, peaux sensibles, à tendance acnéique.', 150, 'ml', 'dear-klairs-egf-blue-calming-toner-pad', 'https://korean-skincare.fr/products/dear-klairs-egf-blue-calming-toner-pad', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-egf-blue-calming-toner-pad.webp', 'Après le nettoyage, passe doucement la compresse sur ton visage en évitant le contour des yeux. Tapote l’essence restante. Peut également être laissé sur des zones spécifiques comme compresse apaisante pendant 5 à 10 minutes.', 1995, '2026-05-07 17:37:40.317873+00', '2026-06-14 15:14:07.578+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64fa-7f54-9af7-db5037012256', '__OWNER_ID__', 'Anti Age Hyaluron Filler Soin Contour des Yeux SPF20', 'Eucerin', 'eye-cream', 'tube', 'Aqua, Glycerin, HYDROGENATED COCO-GLYCERIDES, Avobenzone, C12-15 ALKYL BENZOATE, Cera Alba, Dicaprylyl Carbonate, Butylene Glycol, Behenyl Alcohol, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Ethylhexyl Triazone, Ensulizole, Methylpropanediol, HYDROXYPROPYL STARCH PHOSPHATE, Stearyl Alcohol, Sodium Hyaluronate, ARCTIUM LAPPA FRUIT EXTRACT, CREATINE, 1-METHYLHYDANTOIN-2-IMIDE, Tocopherol, Palmitic Acid, Stearic Acid, Myristic Acid, Arachidic Acid, Oleic Acid, SODIUM STEAROYL GLUTAMATE, Sodium Hydroxide, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Lauroyl Lysine, XANTHAN GUM, Sodium Chloride, Trisodium EDTA, 1,2-Hexanediol, Ethylhexylglycerin, Phenoxyethanol', 'EUCERIN ANTI AGE HYALURON FILLER SOIN CONTOUR DES YEUX SPF20 15ML, en vente en ligne sur le site de votre parapharmacie à prix discount.
INSERT INTO public.products VALUES ('019e0384-4408-7150-957e-e37180647a03', '__OWNER_ID__', 'Tea Tree Purifine Toner Pad', 'Dr. Ceuracle', 'toner', 'pack', 'Melaleuca Alternifolia Leaf Water, Methylpropanediol, Butylene Glycol, Glycereth-26, Niacinamide, Propanediol, 1,2-Hexanediol, Arginine, Salicylic Acid, Dipropylene Glycol, Alketh-12 C12-14, Hydroxyacetophenone, Gomme Xanthane, Caprylyl Glycol, Zinc PCA, Gluconolactone, Ethylhexylglycerin, Betaine, Panthenol, Dipotassium Glycyrrhizate, Aqua, Extrait d’Écorce de Saule Blanc Salix Alba, Disodium EDTA', 'Tu en as marre de lutter contre les boutons tenaces et la peau grasse ? Découvre les Tea Tree Purifine Toner Pads Dr. Ceuracle, ta dose quotidienne pour une peau nette et apaisée. Imprégnées d''un mélange puissant d''extrait d''arbre à thé, ces compresses pré-imbibées offrent un moyen pratique et efficace d''exfolier en douceur, de contrôler l''excès de sébum et d''apaiser la peau irritée. Dis adieu aux pores obstrués et aux rougeurs grâce au pouvoir naturel de l''arbre à thé qui purifie et équilibre ta peau, la laissant fraîche, affinée et visiblement plus saine. Parfaites pour les routines chargées, ces compresses sont ton arme secrète pour conserver un teint net et éclatant de confiance, jour après jour. Recommandé pour : Peaux grasses, à tendance acnéique, mixtes.', 160, 'ml', 'dr-ceuracle-tea-tree-purifine-toner-pad', 'https://korean-skincare.fr/products/dr-ceuracle-tea-tree-purifine-toner-pad', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-tea-tree-purifine-toner-pad.webp', 'Nettoie ton visage. Passe le côté texturé sur l''ensemble de ton visage (en évitant les yeux) pour une exfoliation en douceur. Retourne la compresse et tapote pour faire pénétrer l''essence. Poursuis ta routine (sérum, crème hydratante, crème solaire). Ferme bien le couvercle. Utilise tous les jours, matin et/ou soir. Conseil : Laisse le côté lisse poser sur certaines zones un mini-masque.', 2195, '2026-05-07 17:37:40.360012+00', '2026-06-14 15:14:07.578+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4443-76db-9e28-300dbb1c9150', '__OWNER_ID__', '5α Control Clearing Toner', 'Dr. Ceuracle', 'toner', 'pump', 'Aqua, Betaine, Glycerin, Extrait d''écorce/feuille/tige d''Hamamelis Virginiana, Extrait de Ferments de Lactobacillus/Soja, Dioscorea Japonica Root Extract, Extrait de Saccharomyces Cerevisiae, Extrait de Germe de Triticum Vulgare, Tremella Fuciformis Extract, Extrait d''Ecorce de Cinnamomum Zeylanicum, Extrait de Phellinus Linteus, Extrait de Cordyceps Sinensis, Extrait de Ganoderma Lucidum, Sodium Hyaluronate, Butylene Glycol, Sodium PCA, Capryloyl Glycine, Hexylene Glycol, Dipotassium Glycyrrhizate, Candida Ferment, Sarcosine, Allantoin, PEG-60 Glycérides d''Amande, Carbomer, Disodium EDTA, Acide Nordihydroguaïarétique, Acide Oléanolique, PEG-40 Huile de Ricin Hydrogénée, Parfum, 1,2-Hexanediol, Hydroxyacetophenone, Caprylyl Glycol, Ethylhexylglycerin', 'Le Control Clearing Toner 5α Dr.Ceuracle est un tonique purifiant qui ravive les peaux ternes provoquées par un excès de sébum, en rétablissant une peau raffraichie et purifiée, sans brillance ni effet gras. Formulé avec le complexe 5α, il contrôle la sécrétion excessive de sébum et rééquilibre le ratio huile/eau de la peau pour une peau fraîche et saine en parfaite santé. Il contient également de l''AC NET qui aide à soulager et à apaiser les problèmes de peau, et de l''acide hyaluronique qui hydrate la peau en profondeur. Ce tonique a une texture légère et aqueuse qui est facilement absorbée par la peau, lui donnant une sensation de fraîcheur et de bien-être. Il favorise l''absorption des soins consécutifs en éliminant les cellules mortes et les impuretés pour affiner la texture de la peau. Il est parfait pour les peaux grasses et acnéiques à la recherche d''une routine tonique douce mais efficace.', 120, 'ml', 'dr-ceuracle-5-alpha-control-clearing-toner', 'https://korean-skincare.fr/products/dr-ceuracle-5-alpha-control-clearing-toner', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-5-alpha-control-clearing-toner.webp', 'Applique une quantité suffisante de produit sur un coton. Passe-le délicatement sur ton visage nettoyé au préalable. Tu peux aussi distribuer une quantité suffisante de produit sur le bout de tes doigts. Tapote doucement sur ta peau jusqu''à absorption complète.', 2345, '2026-05-07 17:37:40.419324+00', '2026-06-14 15:14:07.578+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-440b-7ff3-af3a-14347f3d4e37', '__OWNER_ID__', 'Cica Regen 92 Toner', 'Dr. Ceuracle', 'toner', 'pump', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, Butyrospermum Parkii Butter, 1,2-Hexanediol, Distearate de Polyglycéryl-3 Méthylglucose, Dicaprylyl Carbonate, Glyceryl Stearate SE, Alcool Behénique, Centella Asiatica Extract, Carbomer, Tromethamine, Glutamate de Stéaroyle de Sodium, Ethylhexylglycerin, Microcrystalline Cellulose, Adenosine, Disodium EDTA, Cellulose Gum, Madecassoside, Beta-Glucan, Extrait de Fruit d’Actinidia Arguta, Tocopherol', 'Apaise, hydrate et renforce les peaux sensibles avec le Toner Cica Regen 92 Dr. Ceuracle, une formule douce infusée à 92 % d’extrait de Centella Asiatica pour soulager instantanément les irritations et restaurer l’hydratation. Enrichi en madécassoside et en extrait de kiwi, ce tonique aide à réparer les peaux abîmées et à les protéger des agressions extérieures. Sa composition douce et hypoallergénique, formulée avec 13 ingrédients d’origine naturelle, en fait un soin idéal même pour les peaux les plus sensibles. Grâce à sa texture nourrissante proche d’une essence, il s’applique facilement en couches pour offrir une hydratation durable et un teint doux et équilibré. Recommandé pour : Peaux sensibles, tous types de peaux.', 120, 'ml', 'dr-ceuracle-cica-regen-92-toner', 'https://korean-skincare.fr/products/dr-ceuracle-cica-regen-92-toner', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-cica-regen-92-toner.webp', 'Après le nettoyage, applique une quantité modérée de tonique sur ta peau, en évitant le contour des yeux et de la bouche. Tapote légèrement pour favoriser l’absorption.', 1545, '2026-05-07 17:37:40.363945+00', '2026-06-14 15:14:07.578+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-449d-734e-aa97-e9162245a248', '__OWNER_ID__', 'Rose Collagen Mist Serum', 'Mary&May', 'mist', 'spray', 'Aqua, Glycerin, Ethylhexyl Palmitate, Butylene Glycol, Niacinamide, Rosa Damascena Flower Water, Extrait de Collagène (3,350 ppm), Collagène Hydrolysé (3,350 ppm), Collagène Soluble (3,350 ppm), Dipropylene Glycol, Helianthus Annuus Seed Oil, Hydroxyacetophenone, Betaine, Persea Gratissima Oil, Olea Europaea Fruit Oil, 1,2-Hexanediol, Allantoin, Adenosine, Extrait de Racine d''Alkanna Tinctoria, Caprylyl Glycol, Disodium EDTA, Pentylene Glycol, Esters d''Huile de Jojoba et de Graines de Macadamia, Sodium Hyaluronate, Squalene, Sodium Hyaluronate Crosspolymer, Ethylhexylglycerin, Hydrolyzed Hyaluronic Acid, Tocopherol, Hyaluronic Acid, Macadamiate de Phytostérol, Hydrolyzed Sodium Hyaluronate, Phytostérols, Parfum', 'Le Rose Collagen Mist Serum MARY & MAY est un sérum au collagène qui traite la sécheresse de la peau. Soulage la peau sèche avec ce sérum en brume formulé avec de l''eau de rose de Damas, du collagène et des huiles d''olive, de jojoba et d''avocat. Il forme une couche d''hydratation et d''huile sur la peau pour fournir une hydratation instantanée tout en améliorant l''élasticité et l''éclat de la peau.', 100, 'ml', 'mary-may-rose-collagen-mist-serum-1', 'https://korean-skincare.fr/products/mary-may-rose-collagen-mist-serum-1', 'https://aurore-cdn.b-cdn.net/products/mary-may-rose-collagen-mist-serum-1.webp', 'Agite bien avant de d''utiliser. Vaporise sur ton visage. Tapote délicatement pour faire pénétrer.', 1855, '2026-05-07 17:37:40.509088+00', '2026-06-14 15:14:07.578+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6537-7a91-9b96-16eeb76535f5', '__OWNER_ID__', 'Xerial Peel Masque Exfoliant Pieds', 'SVR', 'foot-cream', 'jar', 'Aqua, Alcohol, Lactic Acid, ISOPENTYLDIOL, ISOPROPYL ALCOHOL, PEG-60 HYDROGENATED CASTOR OIL, Urea, Butylene Glycol, Glycolic Acid, AMMONIUM ACRYLOYLDIMETHYL TAURATE/VP COPOLYMER, Potassium Hydroxide, Squalane, Glycerin, Hydrogenated Lecithin, Camellia Sinensis Leaf Extract, CLEMATIS VITALBA LEAF EXTRACT, EQUISETUM ARVENSE EXTRACT, Fucus Vesiculosus Extract, HEDERA HELIX (IVY) EXTRACT, SPIRAEA ULMARIA FLOWER EXTRACT, HYDROXYPROPYL METHYLCELLULOSE STEAROXY ETHER, SODIUM METHYL STEAROYL TAURATE', 'XERIAL PEEL Masque exfoliant Pieds discount, le soin expert de SVR sous forme de chaussettes dans votre parapharmacie en ligne à prix discount, pour réparer les pieds très secs et abîmés avec callosités et rugosités rapidement.
INSERT INTO public.products VALUES ('019e0384-44a2-7089-b581-b0c131eaa51f', '__OWNER_ID__', 'Vitamine B5 + Bifida Toner', 'Mary&May', 'toner', 'pump', 'Aqua, Glycerin, Butylene Glycol, Lysat de Ferment Bifida (30,000 ppm), Niacinamide, Panthenol, Glycereth-26, Dipropylene Glycol, Cetearyl Olivate, Sorbitan Olivate, Hydroxyacetophenone, Laurate de Polyglycéryl-10, Laurate de Polyglycéryl-4, Betaine, Caprylyl/Capryl Glucoside, 1,2-Hexanediol, Adenosine, Caprylyl Glycol, Disodium EDTA, Gomme Xanthane, Parfum, Sodium Hyaluronate', 'Le Vitamine B5 + Bifida Toner MARY & MAY est un tonique gorgé de vitamine B5 et de lysat de ferment de bifida pour hydrater la peau en profondeur tout en renforçant la barrière cutanée, révélant ainsi un teint vibrant et éclatant. Le lysat de ferment de bifida reconstitue les nutriments pour une peau éclatante de santé, renforce sa barrière pour favoriser sa régénération et élimine les cellules mortes pour un teint lisse. Ce tonique est riche en vitamine B5, un humectant efficace, pour hydrater et calmer la peau. Sa texture à absorption rapide laisse à la peau une sensation de fraîcheur et d''hydratation.', 120, 'ml', 'mary-may-vitamine-b5-bifida-toner', 'https://korean-skincare.fr/products/mary-may-vitamine-b5-bifida-toner', 'https://aurore-cdn.b-cdn.net/products/mary-may-vitamine-b5-bifida-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 1464, '2026-05-07 17:37:40.513782+00', '2026-06-14 15:14:07.579+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44c3-7f48-b93e-0278fc64dd3c', '__OWNER_ID__', 'Vegan CICA Tea Tree AHA PHA Toner', 'Mary&May', 'toner', 'pump', 'Aqua, Melaleuca Alternifolia Leaf Water, Glycerin, Dipropylene Glycol, Butylene Glycol, Niacinamide, 1,2-Hexanediol, Propanediol, Caprylyl Glycol, C12-14 Pareth-12, Ethylhexylglycerin, Adenosine, Citric Acid, Gluconolactone, Allantoin, Gomme Xanthane, Xylitylglucoside, Extrait de Feuille de Centella Asiatica, Anhydroxylitol, Mentha Arvensis Leaf Oil, Xylitol, Glucose, Extrait de Feuille de Pinus Densiflora, Citrus Junos Fruit Extract, Extrait d''Artemisia Annua', 'Le Vegan CICA Tea Tree AHA PHA Toner 200ml Mary & May est un soin puissant conçu pour débarrasser ta peau des cellules mortes et des problèmes indésirables. Ce tonique est doté d''une formule à faible pH, servant de bouclier à la barrière naturelle de ta peau et maintenant un équilibre cutané harmonieux. Sa formule transparente et claire à base d''eau travaille avec diligence pour éliminer les cellules mortes et l''excès de sébum, laissant derrière elle un fini rafraîchissant et profondément hydraté. L''une des caractéristiques principales de ce tonique remarquable est sa composition 100 % vegan, ce qui en fait un choix idéal pour ceux qui recherchent une solution d''exfoliation sans irritation pour un usage quotidien. Grâce à la combinaison dynamique d''AHA et de PHA, ce tonique éclaircit et rajeunit efficacement la peau en éliminant les cellules mortes et les impuretés. De plus, l''inclusion de niacinamide aide à contrôler la production de sébum et à éclaircir les imperfections, garantissant ainsi un teint plus clair et plus uniforme. De plus, le CICA Tea Tree Toner Mary & May exploite la puissance de 300 000 ppm d''eau naturelle de feuilles d''arbre à thé, réputée pour ses propriétés apaisantes et soulageantes pour la peau. Il agit comme une mesure préventive contre l''apparition de troubles cutanés, grâce à sa capacité à lutter contre l''acné avec l''inclusion de Gesolza, dérivée d''herbes médicinales orientales traditionnelles. Pour couronner le tout, ce tonique garde ta peau claire et hydratée tout au long de la journée, grâce à ses ingrédients actifs hydratants brevetés, qui mélangent le bouleau et le xylitol pour protéger même les zones les plus sujettes à la sécheresse. Améliore ta routine beauté avec le Vegan CICA Tea Tree AHA PHA Toner Mary & May pour un teint radieux et équilibré au quotidien. Recommandé pour : Tous types de peaux.', 200, 'ml', 'mary-may-vegan-cica-tea-tree-aha-pha-toner', 'https://korean-skincare.fr/products/mary-may-vegan-cica-tea-tree-aha-pha-toner', 'https://aurore-cdn.b-cdn.net/products/mary-may-vegan-cica-tea-tree-aha-pha-toner.webp', 'Tonique : Après avoir nettoyé ton visage, prélève une quantité appropriée de produit et applique-le sur ta peau pour qu''elle l''absorbe légèrement. Tonique sur coton : Après avoir nettoyé ton visage, applique du produit sur une compresse de coton et passe-la délicatement le long de ton grain de peau. Masque : Après avoir imbibé une compresse de produit, place-la sur la zone à traiter pendant environ 5 minutes.', 2251, '2026-05-07 17:37:40.547849+00', '2026-06-14 15:14:07.579+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4592-7321-a607-e8e14407da54', '__OWNER_ID__', 'Niacinamide 5 TXA Brightening Pad', 'Anua', 'toner', 'pack', 'Aqua, Methylpropanediol, Niacinamide, Butylene Glycol, Glycerin, 1,2-Hexanediol, Ethylhexylglycerin, Adenosine, Arginine, Carbomer, Disodium EDTA, Cyanocobalamin, Bétaïne Salicylate, Hydrolyzed Sodium Hyaluronate, Madecassoside, Tranexamic Acid, Gluconolactone, Extrait de Pourpier Portulaca Oleracea, Extrait de Graine de Vitis Vinifera, Extrait de Saururus Chinensis, Filtrat de Ferment de Riz Sake, Oligopeptide-2, Laurate de Polyglycéryl-10, Caprylyl Glycol, Copper Tripeptide-1, Hexapeptide-9, Hexapeptide-11, Pentapeptide Palmitoyl-4, Tripeptide Palmitoyl-1, Tripeptide-1', 'Les Niacinamide 5 TXA Brightening Pads Anua sont une solution pratique et efficace pour lutter contre le teint terne et irrégulier. Imprégnées d''un mélange puissant de 5 % de niacinamide et d''acide tranexamique, ces compresses pré-imbibées sont conçues pour illuminer visiblement le teint, réduire l''apparence des taches brunes et apaiser les marques d''acné. Leur forme unique en croissant permet une adhérence parfaite aux zones contourées comme le dessous des yeux et les pommettes, garantissant un traitement ciblé des zones sujettes à la décoloration et à la sécheresse. Au-delà de leurs principaux bienfaits éclaircissants, ces compresses polyvalentes offrent également une exfoliation douce et une hydratation en profondeur. Formulées à base de PHA et de vitamine B12 rose nourrissante, elles affinent le grain de peau, redonnent de l''éclat et rendent la peau plus lisse et plus souple. Adaptées à un usage quotidien, les Niacinamide 5 TXA Brightening Pads peuvent être intégrées à ta routine matinale et nocturne, soit comme tonique rapide à passer sur la peau, soit comme mini-masque à laisser poser pour un coup de fouet éclaircissant et apaisant intensif. Recommandé pour : Peaux ternes et sensibles, tous types de peaux.', 210, 'ml', 'anua-niacinamide-5-txa-brightening-pad', 'https://korean-skincare.fr/products/anua-niacinamide-5-txa-brightening-pad', 'https://aurore-cdn.b-cdn.net/products/anua-niacinamide-5-txa-brightening-pad.webp', 'Applique les compresses en forme de croissant sur les zones à traiter (comme le dessous des yeux ou les pommettes) et laisse agir pendant 10 à 20 minutes. Passe délicatement une compresse sur l''ensemble de ton visage pour lisser et préparer ta peau. Conseil : pour un effet éclaircissant intensifié, utilise les compresses comme mini-masque sur les taches brunes ou les zones ternes ciblées pendant 10 à 20 minutes pendant que tu vaques à tes occupations matinales.', 1976, '2026-05-07 17:37:40.754096+00', '2026-06-14 15:14:07.579+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-452a-7364-86f3-7350e041828e', '__OWNER_ID__', 'Beta Panthenol Repair Toner', 'SOME BY MI', 'toner', 'pump', 'Aqua, Propanediol, Methylpropanediol, Niacinamide, Glycerin, 1,2-Hexanediol, Panthenol, Betaine, Alcane C13-14, Caprylic/Capric Triglyceride, Trehalose, Ceramide NP, Ethylhexylglycerin, Adenosine, Hydrogenated Lecithin, Dipropylene Glycol, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Allantoin, Xylitol, Glycéryl Glucoside, Musa Sapientum Fruit Extract, Rosa Damascena Flower Water, Beta-Glucan, Sodium Citrate, Pyrus Communis Fruit Extract, Extrait de Graine de Prunus Domestica, Sorbitan Olivate, Cucumis Melo Fruit Extract, Olivate de Cétéaryle, Citric Acid, Sodium Phytate, Extrait de Feuille/Tige de Hedera Helix, Glucose, Macadamia Ternifolia Seed Oil, Sodium Hyaluronate, Beta-Sitosterol, Lysat de Fermentation de Bifida, Lysat de Fermentation de Lactococcus, Lysat de Fermentation de Lactobacillus, Phytostérols, Hyaluronate Hydroxypropyltrimonium, Sodium Acetylated Hyaluronate, Hydrolyzed Sodium Hyaluronate, Polymère Croisé de Hyaluronate de Sodium, Potassium Hyaluronate', 'Revitalise ta peau sèche ou terne avec le Beta Panthenol Repair Toner SOME BY MI, un élixir rajeunissant et réparateur de barrière cutanée, enrichi de Beta-Panthenol™ exclusif. Ce mélange breveté de D-panthénol et de bêta-sitostérol rentre en synergie avec les probiotiques pour promouvoir la santé de la peau. Exempt d''alcools et de parabènes, ce tonique va bien plus loin qu''un soin conventionnel, il équilibre le pH de la peau et fortifie sa barrière naturelle. Recommandé pour : Peaux sèches, tous types de peaux.', 150, 'ml', 'some-by-mi-beta-panthenol-repair-toner', 'https://korean-skincare.fr/products/some-by-mi-beta-panthenol-repair-toner', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-beta-panthenol-repair-toner.webp', 'Applique une quantité modérée sur la peau, en évitant le contour des yeux et de la bouche. Tapote légèrement pour une meilleure absorption.', 1848, '2026-05-07 17:37:40.650028+00', '2026-06-14 15:14:07.579+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-45bc-7a9a-a6a7-4429636d2cbe', '__OWNER_ID__', 'PDRN 100 Hyaluronic Acid Booster Toner', 'Anua', 'toner', 'pump', 'Aqua, Butylene Glycol, Glycerin, Pentylene Glycol, Propanediol, Saccharum Officinarum Extract, Xylitylglucoside, Extrait de Graine de Glycine Soja, Extrait de Malachite, Xylitol, Melia Azadirachta Leaf Extract, Extrait de Vincetoxicum Atratum, Extrait de Fleur de Melia Azadirachta, Coccinia Indica Fruit Extract, Althaea Rosea Flower Extract, Extrait de Fleur d’Aloe Barbadensis, Hydrolyzed Hyaluronic Acid, Solanum Melongena Fruit Extract, Ocimum Sanctum Leaf Extract, Extrait de Corallina Officinalis, Curcuma Longa Root Extract, 1,2-Hexanediol, Betaine, Hydroxyacetophenone, Panthenol, Ethylhexylglycerin, Anhydroxylitol, Allantoin, ADN de Sodium, Dipropylene Glycol, Octanediol, Lecithin, Tocopherol, Copolymère d’Acide Hyaluronique/Collagène Hydrolysé, C12-13 Alketh-9, Phosphate Dipotassique, Acétyl Glutamine, Copper Tripeptide-1, Cellulose Gum, Disodium EDTA, Gomme Xanthane', 'Le PDRN 100 Hyaluronic Acid Booster Toner Anua est un tonique hydratant et réparateur, conçu pour reconstituer l’hydratation, renforcer la barrière cutanée et améliorer la résilience globale de la peau. Formulé avec du PDRN et un mélange hydratant d’acide hyaluronique, il aide à repulper la peau, lisser les textures rugueuses et réduire l’apparence des ridules de sécheresse pour un teint plus sain et lumineux. Sa texture légère à pénétration rapide procure une hydratation longue durée sans effet collant, ce qui le rend idéal pour un usage quotidien en superposition. Il prépare également la peau à une meilleure absorption des sérums et des crèmes, laissant la peau douce, équilibrée et rafraîchie. Recommandé pour : Soin des pores, tous types de peaux.', 250, 'ml', 'anua-pdrn-100-hyaluronic-acid-booster-toner', 'https://korean-skincare.fr/products/anua-pdrn-100-hyaluronic-acid-booster-toner', 'https://aurore-cdn.b-cdn.net/products/anua-pdrn-100-hyaluronic-acid-booster-toner.webp', 'Après le nettoyage, applique une quantité appropriée de produit sur ton visage à l’aide de tes mains ou d’un coton. Tapote délicatement jusqu’à absorption complète. Utilise matin et soir, puis poursuis avec un sérum et une crème hydratante.', 1855, '2026-05-07 17:37:40.796532+00', '2026-06-14 15:14:07.58+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4007-7c15-9976-eef993aa681f', '__OWNER_ID__', 'DIVE-IN Low Molecular Hyaluronic Acid Soothing Cream', 'Torriden', 'moisturizer', 'jar', 'Aqua, Butylene Glycol, Glycerin, 1,2-Hexanediol, Didécène Hydrogéné, Allantoin, Trehalose, Extrait de Hamamelis Virginiana, Panthenol, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Sodium Acetylated Hyaluronate, Hydrolyzed Sodium Hyaluronate, Copolymère Acrylate de Glycéryle/Acide Acrylique, Copolymère PVM/MA, Copolymère Acrylate d''Hydroxyéthyl/Sodium Acryloyldimethyl Taurate, 2,3-Butanediol, Cetearyl Alcohol, Alcools C14-22, Glucoside Alkylique C12-20, Pentylene Glycol, Sorbitan Isostearate, Caprylic/Capric Triglyceride, Melia Azadirachta Leaf Extract, Extrait de Fleur de Melia Azadirachta, Coccinia Indica Fruit Extract, Solanum Melongena Fruit Extract, Ocimum Sanctum Leaf Extract, Curcuma Longa Root Extract, Extrait de Corallina Officinalis, Extrait de Salvia Sclarea, Extrait de Fleur de Lavandula Angustifolia, Extrait de Fleur d''Hyacinthus Orientalis, Chamomilla Recutita (Matricaria) Flower Extract, Extrait de Fleur de Centaurea Cyanus, Extrait de Borago Officinalis, Disodium EDTA, Carbomer, Tromethamine, Gomme Xanthane, Glutathione, Extrait de Malachite, Ethylhexylglycerin', 'La DIVE-IN Low Molecular Hyaluronic Acid Soothing Cream Torriden est une crème luxueuse à base d''acide hyaluronique 5D-Complex, qui procure une hydratation profonde et un effet revitalisant pour la peau. Infusée d''ingrédients respectueux de la peau comme le tréhalose et le panthénol, elle maintient non seulement ses niveaux d''hydratation, mais apaise également les irritations, garantissant ainsi un teint calme et équilibré. Pour nourrir davantage la peau, cette crème est enrichie du Blue Complex HR, composé de six extraits botaniques qui offrent une délicieuse explosion de nutriments. Sa texture gel légère et aqueuse permet une absorption rapide et laisse derrière elle un fini rafraîchissant et non collant, ce qui en fait un complément parfait à ta routine beauté quotidienne. Il s''agit d''une crème légère, à la texture de gel aqueux. Cela assure une absorption rapide et un fini rafraîchissant et non collant que tu vas adorer. Profite du pouvoir rajeunissant et hydratant de cette crème apaisante, et laisse-toi guider vers un teint éclatant et rempli de douceur. Recommandé pour : Peaux sensibles, tous types de peaux.', 100, 'ml', 'torriden-dive-in-low-molecular-hyaluronic-acid-soothing-cream', 'https://korean-skincare.fr/products/torriden-dive-in-low-molecular-hyaluronic-acid-soothing-cream', 'https://aurore-cdn.b-cdn.net/products/torriden-dive-in-low-molecular-hyaluronic-acid-soothing-cream.webp', 'Tous les matins et tous les soirs, prélève une quantité appropriée de crème et presse-la délicatement sur ta peau. Pour un traitement profondément hydratant et apaisant, applique généreusement une couche épaisse du produit sur les zones souhaitées comme un masque de nuit. Améliore ta routine beauté en appliquant ce produit par-dessus ton masque tissu pour un boost d''hydratation.', 2195, '2026-05-07 17:37:39.335604+00', '2026-06-14 15:14:07.579+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-454d-7e21-9d67-2e628f24f576', '__OWNER_ID__', 'Galactomyces Glutathione Glow Milky Toner', 'SOME BY MI', 'toner', 'pump', 'Galactomyces Ferment Filtrate, Glycerin, 1,2-Hexanediol, Aqua, Methylpropanediol, Butane, Diphenyl Diméthicone, Bis-PEG-18 Méthyl Ether Diméthyl Silane, C12-14 Pareth-12, Hydroxyacéto-phénone, Hydrogenated Lecithin, Sodium Citrate, Polyglycéryl-10 Oléate, Ethylhexylglycerin, Citric Acid, Adenosine, Oryza Sativa Extract, Glutathione, 1,2-Hexanediol, Caprylyl Glycol, Tocopherol, Acide 2-O-Ethyl Ascorbique, Extrait de Graine d''Amaranthus Caudatus, Betaine, Hydrolyzed Hyaluronic Acid, Oryza Sativa Extract, Ceramide NP, Propanediol, Saccharomyces Ferment Filtrate, Acetyl Hexapeptide-8', 'Retrouve une peau lumineuse et hydratée avec le Galactomyces Glutathione Glow Milky Toner SOME BY MI. Formulé avec 86 % de filtrat de ferment Galactomyces, ce tonique offre une hydratation profonde, une protection antioxydante et un éclat radieux. Infusé de glutathion et de vitamine C, ce tonique éclaircit visiblement le teint tout en adoucissant la peau pour un fini lisse et satiné, parfait comme base pour une application de maquillage impeccable. Enrichi d''extrait de riz et de céramide NP, ce tonique renforce l''éclat naturel de la peau et sa barrière d''hydratation sans résidus collants.', 200, 'ml', 'some-by-mi-galactomyces-glutathione-glow-milky-toner', 'https://korean-skincare.fr/products/some-by-mi-galactomyces-glutathione-glow-milky-toner', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-galactomyces-glutathione-glow-milky-toner.webp', 'Applique une quantité appropriée sur un coton ou dans la paume de tes mains. Applique délicatement en suivant les lignes de ta peau. Tapote délicatement pour faire pénétrer le contenu.', 1995, '2026-05-07 17:37:40.685755+00', '2026-06-14 15:14:07.58+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4564-7ad2-b938-8ae5e5d3b625', '__OWNER_ID__', 'Retinol Bakuchiol Bubble Toner', 'SOME BY MI', 'toner', 'pump', 'Aqua, Butylene Glycol, Propanediol, Glycerin, 1,2-Hexanediol, Niacinamide, C12-14 Alketh-12, Methylpropanediol, Laurate de Saccharose, Ethylhexylglycerin, Sodium Citrate, Copolymère d’Acide Acrylique/Sodium MA, Hydrogenated Lecithin, Extrait de Potentilla Anserina, Citric Acid, Adenosine, Polyquaternium-51, Extrait de Grain d’Avoine Sativa, Extrait de Feuille de Cynara Scolymus, Disodium EDTA, Beta-Glucan, Camellia Sinensis Leaf Water, Gomme Xanthane, Bakuchiol, Caprylyl Glycol, Retinol, Glycine Soja Oil, Sodium Hyaluronate, Allantoin, Arginine, Trehalose, Retinal, Distearate de Saccharose, Caprylic/Capric Triglyceride, Cyclodextrine Hydroxypropyl, Extrait de Fleur/Feuille de Chamomilla Recutita, Extrait de Borago Officinalis, Extrait de Fleur de Centaurea Cyanus, Extrait de Fleur de Lavandula Angustifolia, Parfum', 'Le Retinol Bakuchiol Bubble Toner SOME BY MI est un tonique moussant conçu pour offrir une exfoliation légère et un renouvellement de la peau tout en minimisant les irritations. Lors de l’application, les micro-bulles s’activent pour aider à faire pénétrer des actifs comme le rétinol, le rétinal et le bakuchiol tout en détachant les impuretés et le sébum. La formule est complétée par des agents hydratants tels que l’acide hyaluronique et des extraits botaniques apaisants (avoine, feuille d’artichaut, centella) pour aider à équilibrer et calmer la peau après la mousse. Recommandé pour : Teint terne, texture irrégulière, pores dilatés et premiers signes de l’âge.', 100, 'ml', 'some-by-mi-retinol-bakuchiol-bubble-toner', 'https://korean-skincare.fr/products/some-by-mi-retinol-bakuchiol-bubble-toner', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-retinol-bakuchiol-bubble-toner.webp', 'Après le nettoyage, verse ou pompe une quantité modérée dans tes mains. Tapote doucement sur peau sèche ou légèrement humide jusqu’à activation de la mousse. Laisse agir environ 30 à 60 secondes, puis poursuis avec tes soins suivants. Astuce : Commence par utiliser ce tonique 2 à 3 fois par semaine et augmente la fréquence uniquement si ta peau le tolère. Toujours appliquer ensuite une lotion ou un sérum hydratant pour atténuer l’effet des rétinoïdes.', 1895, '2026-05-07 17:37:40.708541+00', '2026-06-14 15:14:07.58+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4690-76d4-9e8c-2d50169e243f', '__OWNER_ID__', 'Extreme Essence Toner', 'RealBarrier', 'toner', 'pump', 'Aqua, Glycerin, Propanediol, Dimethicone, Helianthus Annuus Seed Oil, Glyceryl Stearate, Xylitol, Sodium Hyaluronate Crosspolymer, Hydrolyzed Glycosaminoglycans, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Butylene Glycol, Sorbitan Laurate, Hydroxyethylcellulose, Acetyl Dipeptide-1 Cetyl Ester, Panthenol, Beta-Glucan, Madecassoside, Myristoyl/ Palmitoyl Oxostearamide/Arachamide Mea, Ceramide NP, Bis-Capryloyloxypalmitamido Isopropanol, Xylitylglucoside, Anhydroxylitol, Glucose, Allantoin, Polyglyceryl-4 Caprate, Hydroxypropyl Methylcellulose, Carbomer, Sodium Polyacrylate, Caprylic Acid, Raspberry Ketone, Ethylhexylglycerin, Sodium Phytate, Benzyl Glycol, Caprylyl Glycol, 1,2- Hexanediol, Mentha Viridis Leaf Oil, Mentha Viridis Extract, Citrus Nobilis Peel Oil, Pelargonium Graveolens Oil, Thymus Vulgaris Oil, Eucalyptus Globulus Leaf Oil, Barosma Betulina Leaf Extract', 'Le Real Barrier Cream Extreme Essence Toner est un lait tonique de type essence qui aide à réhydrater la peau après le nettoyage. Ce tonique nourrissant contient la formule brevetée MLE Skin Barrier Formula qui utilise un complexe de céramides pour aider à protéger et à renforcer la barrière cutanée. Le trio calmant composé de panthénol, d''allantoïne et de madécassoside agit de concert pour calmer et protéger les peaux irritées, tandis que 5 acides hyaluroniques aident à renforcer la capacité de la peau à retenir l''hydratation. Recommandé pour : Peaux normales à sèches.', 200, 'ml', 'real-barrier-extreme-essence-toner', 'https://korean-skincare.fr/products/real-barrier-extreme-essence-toner', 'https://aurore-cdn.b-cdn.net/products/real-barrier-extreme-essence-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 2445, '2026-05-07 17:37:41.008337+00', '2026-06-14 15:14:07.58+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-46b9-7f60-b80f-c5dec9d2ab4d', '__OWNER_ID__', 'Heartleaf Calming Toner Skin Booster', 'Abib', 'toner', 'pump', 'Aqua, Houttuynia Cordata Extract, Glycerin, Butylene Glycol, Pentylene Glycol, Xylitol, Bifida Ferment Lysate, Sodium Hyaluronate, Extrait De Graine De Glycine Soja (Soja), Centella Asiatica Extract, Hydrolyzed Hyaluronic Acid, Extrait De Racine De Scutellaria Baicalensis, Extrait De Feuille De Gaultheria Procumbens (Wintergreen), Lonicera Japonica Flower Extract, Betaine, 1,2-Hexanediol, Panthenol, Ethylhexylglycerin, Octanediol, Tocopherol, Gomme-4 De Biosaccharide, Disodium EDTA, Gomme Xanthane', 'Le Heartleaf Calming Toner Skin Booster Abib est un tonique apaisant et hydratant qui rafraîchit également la température de la peau. Formulé avec 50 000 ppm d''extrait de Houttuynia Cordata et d''acide hyaluronique, ce tonique aide à éliminer l''excès de sébum et les cellules mortes de la peau tout en lui apportant une hydratation intensive.', 200, 'ml', 'abib-heartleaf-calming-toner-skin-booster', 'https://korean-skincare.fr/products/abib-heartleaf-calming-toner-skin-booster', 'https://aurore-cdn.b-cdn.net/products/abib-heartleaf-calming-toner-skin-booster.webp', 'Applique délicatement une petite quantité sur ta peau à l''aide d''un coton ou de tes mains. Tapote légèrement pour faire pénétrer.', 2118, '2026-05-07 17:37:41.049846+00', '2026-06-14 15:14:07.582+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-45d3-73ff-a68a-1a7fbf17f1b4', '__OWNER_ID__', 'No.9 NAD PDRN Glow Boosting Toner', 'Numbuzin', 'toner', 'pump', 'Aqua, Methylpropanediol, Niacinamide, Copolymère Peg/Ppg-17/6, Propanediol, 1,2-Hexanediol, Tripropylene Glycol, Glyceryl Glucoside, Xylitylglucoside, Huile de Ricin Hydrogénée Peg-40, Anhydroxylitol, Glycerin, Laurate de Polyglycéryl-10, Candida Ferment, Pareth-10 C20-40, Tocopheryl Acetate, Xylitol, Cetearyl Alcohol, ADN de Sodium, Hydrogenated Lecithin, Glucose, Polyacrylate Crosspolymer-6, Ethylhexylglycerin, Adenosine, Ceramide NP, Sodium Phytate, Helianthus Annuus Seed Oil, Melia Azadirachta Leaf Extract, Extrait de Fleur de Melia Azadirachta, Citric Acid, Hydroxyethylcellulose, Sodium Citrate, Phytostérols, Extrait de Fruit de Luffa Cylindrica, Extrait de Fleur d’Aloe Barbadensis, Solanum Melongena Fruit Extract, Alcool Tert-Butylique, Ocimum Sanctum Leaf Extract, Curcuma Longa Root Extract, Extrait de Corallina Officinalis, Cyanocobalamin, Caprylic/Capric Triglyceride, Collagène Hydrolysé, Butylene Glycol, Adénosine Triphosphate, Nicotinamide Adénine Dinucléotide, Resveratrol, Pullulan, Sarcosinate de Palmitoyle de Sodium, Palmitic Acid, Pareth-12 C12-14, Peptide de Pois (Pisum Sativum), Stearic Acid, Laurate de Polyglycéryl-6, Caprylyl Glycol, Dipeptide Diaminobutyroyl Benzylamide Diacetate, Dextrane, Élastine Hydrolysée, Collagène Soluble, Acétyl Tétrapeptide-3, Extrait de Fleur de Trèfle Rouge (Trifolium Pratense), Disodium EDTA, Myristic Acid, Acetyl Hexapeptide-8, Mannose, Sh-Octapeptide-4, Sh-Decapeptide-7, Palmitoyl Pentapeptide-4, Palmitoyl Tripeptide-1, Copper Tripeptide-1, Hexapeptide-9, Nonapeptide-1, Tripeptide-1, Arachidic Acid, Collagène, Élastine, Glutathione, Palmitoyl Tetrapeptide-7, Polypeptide Arginine/Lysine, Oligopeptide-29, Oligopeptide-32, Acetyl Tetrapeptide-5, Acétyl Tétrapeptide-9, Acétyl Tétrapeptide-2, Acétyl Octapeptide-3, Acétyl Hexapeptide-1, Polypeptide Cuivre Alanine/Histidine/Lysine HCl, Acétyl Dipeptide-1 Ester Cétylique, Acétyl Sh-Pentapeptide-1, Biotinoyl Tripeptide-1, Dipeptide-4, Hexapeptide-11, Hexapeptide-12, Lauric Acid, Myristoyl Pentapeptide-17, Myristoyl Hexapeptide-16, Myristoyl Pentapeptide-4, Nicotinoyl Tripeptide-1, Nonapeptide-7, Nicotinoyl Tripeptide-35, Nicotinoyl Dipeptide-26, Nicotinoyl Dipeptide-23, Octapeptide-2, Palmitoyl Tripeptide-5, Palmitoyl Hexapeptide-12, Pentapeptide-13, Palmitoyl Tétrapeptide-10, Palmitoyl Tripeptide-38, Palmitoyl Tripeptide-29, Palmitoyl Tripeptide-8, Sr-Oligopeptide-91 Clostridium Botulinum Polypeptide-1, Tétrapeptide-44, Tétrapeptide-30, Tripeptide-10 Citrulline, Tripeptide-32, Tripeptide-29, Sh-Polypeptide-22, Sh-Oligopeptide-1, Sh-Polypeptide-1, Sh-Polypeptide-9, Sh-Oligopeptide-2, Sh-Polypeptide-11, Sh-Polypeptide-3, Sh-Polypeptide-16, Sh-Polypeptide-62', 'Le No.9 NAD PDRN Glow Boosting Toner est un tonique revitalisant haute performance conçu pour restaurer l’éclat, améliorer l’uniformité du teint et soutenir le renouvellement visible de la peau. Formulé avec un complexe NAD avancé et du PDRN (Polydeoxyribonucleotide), il aide à redynamiser les peaux fatiguées et ternes tout en favorisant l’élasticité et un aspect plus lisse et sain. Sa texture légère mais intensément hydratante apporte immédiatement confort et fraîcheur, tout en préparant la peau à une absorption optimale des sérums et crèmes. Avec une utilisation régulière, la peau paraît plus lumineuse, plus résistante et naturellement éclatante. Doux et bien équilibré, ce tonique convient à un usage quotidien et à tous les types de peau, y compris les peaux sensibles. Recommandé pour : Peaux ternes et fatiguées, peaux sèches, tous types de peaux.', 150, 'ml', 'numbuzin-no-9-nad-pdrn-glow-boosting-toner', 'https://korean-skincare.fr/products/numbuzin-no-9-nad-pdrn-glow-boosting-toner', 'https://aurore-cdn.b-cdn.net/products/numbuzin-no-9-nad-pdrn-glow-boosting-toner.webp', 'Après le nettoyage, applique une quantité appropriée sur le visage à l’aide des mains ou d’un coton. Tapote délicatement jusqu’à absorption complète. Utilise matin et soir, puis poursuis avec un sérum et une crème hydratante. Astuce : Pour booster l’éclat et l’absorption, applique le tonique en 2 à 3 couches légères avec les mains, en tapotant doucement entre chaque couche. Cette méthode intensifie l’hydratation et maximise les effets illuminateurs du NAD et du PDRN, en particulier sur les peaux ternes ou déshydratées.', 2395, '2026-05-07 17:37:40.819118+00', '2026-06-14 15:14:07.58+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-45ed-73d9-a24f-ce3e25bd71d7', '__OWNER_ID__', 'No.4 Hydrating Glow Mineral Toner', 'Numbuzin', 'toner', 'pump', 'Onsen-Sui, 1,2-Hexanediol, Methylpropanediol, Glycerin, Niacinamide, Sorbitol, Xylitol, Hydroxyethyl Urea, Sodium Polystyrene Sulfonate, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Morinda Citrifolia Extract, Carica Papaya Fruit Extract, Butylene Glycol, Madecassoside, Centella Asiatica Extract, Chamomilla Recutita (Matricaria) Flower Extract, Rosmarinus Officinalis Leaf Extract, Glycyrrhiza Glabra Root Extract, Pentylene Glycol, Polygonum Cuspidatum Root Extract, Scutellaria Baicalensis Root Extract, Camellia Sinensis Leaf Extract, Gluconolactone, Aqua, Hydroxyethylcellulose, Polyglyceryl-10 Laurate, Betaine Salicylate, Polyquaternium-51, Disodium EDTA', 'Le No.4 Hydrating Glow Mineral Toner Numbuzin est conçu pour préparer ta peau aux étapes suivantes de ta routine beauté ou à l''application de ton maquillage de base. Infusé avec 89% d''eau thermale et cinq types d''acide hyaluronique, ce tonique hydrate en profondeur et rajeunit les peaux sensibles. Il contient également du PHA pour exfolier en douceur et lisser la peau sans provoquer d''irritation, et du niacinamide pour éclaircir le teint et réduire l''apparence des taches brunes. Sa formule exceptionnelle garantit un soin optimal de ta peau, la laissant rafraîchie, lisse et éclatante. Recommandé pour : Hyperpigmentation, peaux sensibles, tous types de peaux.', 200, 'ml', 'numbuzin-no-4-hydrating-glow-mineral-toner', 'https://korean-skincare.fr/products/numbuzin-no-4-hydrating-glow-mineral-toner', 'https://aurore-cdn.b-cdn.net/products/numbuzin-no-4-hydrating-glow-mineral-toner.webp', 'Après avoir lavé ton visage, applique le produit avec tes mains ou une compresse tonique de l''intérieur vers l''extérieur de ton visage en suivant ton grain de peau, en évitant le contour des yeux et de la bouche.', 1995, '2026-05-07 17:37:40.845143+00', '2026-06-14 15:14:07.581+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-463b-78fe-b5e0-f383c7332252', '__OWNER_ID__', 'Red Toner 2.0', 'Medicube', 'toner', 'pump', 'Aqua, Methylpropanediol, Alcohol, Butylene Glycol, Niacinamide, 1,2-Hexanediol, Méthyl Gluceth-20, Betaine, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Tromethamine, Allantoin, C12-14 Alketh-12, Ethylhexylglycerin, Adenosine, Disodium EDTA, Diméthyl Sulfone, Melaleuca Alternifolia Leaf Oil, Salicylic Acid, Sodium Hyaluronate, Soufre Colloïdal, Zinc PCA, Pentylene Glycol, Acide Lévulinique, 4-Terpineol, Troxérutine, Propanediol, Camellia Sinensis Leaf Extract, Extrait de Feuille de Centella Asiatica, Extrait de Cladosiphon Okamuranus, Salix Alba Bark Extract, Decyl Glucoside, Coptis Japonica Root Extract, Extrait de Graines de Coffea Arabica, Extrait de Feuille de Citrus Aurantium Bergamia, Extrait de Feuille de Pinus Densiflora, Extrait de Racine d’Asparagus Cochinchinensis, Ferment d’Aureobasidium Pullulans, Extrait de Racine de Lepidium Meyenii, Acide Hydroxycinnamique, Rutine', 'Le Red Toner 2.0 est un tonique apaisant à faible irritation, formulé pour les peaux sensibles et à tendance acnéique. Il combine niacinamide, acide salicylique, soufre colloïdal et plus de 19 types d’extraits végétaux pour calmer les rougeurs, réguler la production de sébum et affiner les pores sans laisser de film collant. Sa texture légère est non comédogène, ce qui le rend adapté à une utilisation quotidienne matin et soir. Recommandé pour : Peaux à tendance acnéique, sensibles et mixtes.', 100, 'ml', 'medicube-red-toner-2-0', 'https://korean-skincare.fr/products/medicube-red-toner-2-0', 'https://aurore-cdn.b-cdn.net/products/medicube-red-toner-2-0.webp', 'Après le nettoyage, applique une quantité modérée de produit sur ton visage en évitant le contour des yeux. Tapote délicatemen pour favoriser l’absorption. Utilise le matin et le soir, ou chaque fois que la peau est grasse ou irritée. Poursuis avec ton sérum et ta crème hydratante.', 2495, '2026-05-07 17:37:40.923442+00', '2026-06-14 15:14:07.581+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64ee-7a46-80b2-9e976282bc9b', '__OWNER_ID__', 'Urea Advance Relife Moisturizing Milk', 'Prequel', 'moisturizer', 'bottle', 'Butyrospermum Parkii Butter, C12-15 ALKYL BENZOATE, C15-19 Alkane, CANDELILLA/JOJOBA/RICE BRAN POLYGLYCERYL-3 ESTERS, Caprylic/Capric Triglyceride, Cetearyl Alcohol, Citric Acid, Cyclopentasiloxane, Dimethicone, Ethylhexyl Stearate, Ethylhexylglycerin, Glycerin, Jojoba Esters, LAURYL GLUCOSIDE, Phenoxyethanol, POLYGLYCERYL-6 DISTEARATE, POTASSIUM CETYL PHOSPHATE, Sodium Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Sodium Citrate, TETRASODIUM GLUTAMATE DIACETATE, Tocopherol, Urea, Aqua', 'Un lait corporel hautement hydratant conçu pour lisser et réparer les peaux très sèches.', 400, 'ml', 'prequel-urea-advance-relife-moisturizing-milk', 'https://www.skinsafeproducts.com/prequel-urea-advance-relife-moisturizing-milk-10-urea-niacinamide-shear-butter-13-5-fl-oz-400-ml', 'https://aurore-cdn.b-cdn.net/products/prequel-urea-advance-relife-moisturizing-milk.webp', 'Urée 10% + Niacinamide + Beurre de Karité. Idéal pour les peaux rugueuses et squameuses.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.581+00', 'skincare', '[]', 'lait', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4625-748f-828c-b4c53cacaa9a', '__OWNER_ID__', 'PDRN Pink Collagen Toning Gel Toner Pad', 'Medicube', 'toner', 'pack', 'Aqua, Glycerin, Methylpropanediol, Niacinamide, Xylitol, Hydroxyacetophenone, Octyldodeceth-16, Diglycerin, Allantoin, Cellulose Gum, Ethylhexylglycerin, Hydroxyethylcellulose, Sodium Citrate, Sodium Gluconate, Dipropylene Glycol, Adenosine, Butylene Glycol, 1,2-Hexanediol, Citric Acid, Cyanocobalamin, Anthemis Nobilis Flower Oil, Pyrus Communis Fruit Extract, Rosa Damascena Flower Water, Prunus Persica Fruit Extract, Thuja Orientalis Extract, Jasminum Officinale Flower Water, Citrus Aurantium Amara Flower Extract, Centella Asiatica Extract, Allium Cepa Bulb Extract, Chamomilla Recutita Extract, Salvia Officinalis Extract, Rosmarinus Officinalis Leaf Oil, Hedera Helix Leaf/Stem Extract, Cucumis Melo Fruit Extract, Hibiscus Esculentus Fruit Extract, Carum Petroselinum Extract, Corchorus Olitorius Leaf Extract, Polygonum Cuspidatum Root Extract, Collagen, Artemisia Annua Extract, Nelumbium Speciosum Flower Extract, Oryza Sativa Extract, Saccharomyces Ferment Filtrate, Sodium DNA, Capryloyl Salicylic Acid, Caprylic/Capric Triglyceride, Hydrogenated Lecithin, Sucrose Stearate, Phaseolus Radiatus Seed Extract, Hydrogenated Lecithin, Cetearyl Alcohol, Retinol, Polyglyceryl-10 Myristate, Tocopheryl Acetate, Asiaticoside, Madecassic Acid, Madecassoside, Asiatic Acid', 'Les PDRN Pink Collagen Toning Gel Toner Pads Medicube est un soin raffermissant et éclaircissant sous forme de compresses tonifiantes ultra-hydratantes imbibées d’une essence gel rafraîchissante. Infusées en PDRN et en complexe de collagène rose, ces compresses multi-actions aident à améliorer l’élasticité, lisser la texture rugueuse et restaurer un éclat sain tout en apportant un effet rafraîchissant et tonifiant à chaque passage. Parfaite pour les peaux ternes, déshydratées ou matures, chaque compresse douce et double-face exfolie délicatement tout en inondant la peau d’hydratation et d’ingrédients actifs soutenant la production de collagène et le renouvellement cutané. Les PDRN Pink Collagen Toning Gel Toner Pads Medicube sont ton allié pour un boost d’hydratation, de fermeté et d’éclat rapide, pratique et propre. Recommandé pour : Tous types de peaux.', 120, 'ml', 'medicube-pdrn-pink-collagen-toning-gel-toner-pad', 'https://korean-skincare.fr/products/medicube-pdrn-pink-collagen-toning-gel-toner-pad', 'https://aurore-cdn.b-cdn.net/products/medicube-pdrn-pink-collagen-toning-gel-toner-pad.webp', 'Après le nettoyage, passe doucement la compresse sur ton visage en évitant le contour des yeux. Utilise le côté embossé pour une exfoliation douce et le côté lisse pour tonifier et hydrater. Poursuis avec un sérum ou une crème. Utilise quotidiennement ou selon les besoins.', 2445, '2026-05-07 17:37:40.901101+00', '2026-06-14 15:14:07.581+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4645-793c-a1a3-43dad424ed49', '__OWNER_ID__', 'Triple Collagen Toner 4.0', 'Medicube', 'toner', 'pump', 'Aqua, Glycerin, Butylene Glycol, 1,2-Hexanediol, Niacinamide, Dipropylene Glycol, Propanediol, Trehalose, Ethylhexylglycerin, Adenosine, Collagène Hydrolysé, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate, Collagène Soluble, Atélo-Collagène, Extrait de Collagène, Phosphate Disodique, Polysorbate 60, Sodium Phosphate, Hydroxyéthylcellulose, Ammonium Acryloyldimethyltaurate/VP Copolymer, Glycéreth-25 PCA Isostéarate, Disodium EDTA, Parfum', 'Transforme ta routine beauté avec le Triple Collagen Toner 4.0 Medicube, une formule puissante enrichie de collagène hydrolysé, de collagène atelo et de collagène soluble pour stimuler l''élasticité de la peau et révéler un teint éclatant de jeunesse. Ce tonique profondément hydratant fournit des nutriments essentiels pour repulper et lisser ta peau, tandis que l''acide hyaluronique, le hyaluronate de sodium et le niacinamide retiennent l''hydratation et rehaussent l''éclat de la peau. Parfait pour tous les types de peaux, y compris les peaux sensibles, il affine leur texture et maintient ton teint hydraté tout au long de la journée. Profite d''une hydratation et d''une souplesse optimales grâce à ce soin indispensable à ta routine beauté. Recommandé pour : Tous types de peaux.', 140, 'ml', 'medicube-triple-collagen-toner-4-0', 'https://korean-skincare.fr/products/medicube-triple-collagen-toner-4-0', 'https://aurore-cdn.b-cdn.net/products/medicube-triple-collagen-toner-4-0.webp', 'Après le nettoyage, applique une quantité modérée de produit sur ton visage, en évitant le contour de la bouche et des yeux. Tapote délicatement pour faire pénétrer le produit dans ta peau. Conseil : Mélange le produit avec ton fond de teint ou ta base de maquillage pour créer un effet lumineux sur ta peau.', 1895, '2026-05-07 17:37:40.933451+00', '2026-06-14 15:14:07.582+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-653e-7e60-b04d-85c53610300b', '__OWNER_ID__', 'SVR Topialyse Huile Lavante 1L', 'SVR', 'body-wash', 'jar', 'Aqua, Glycerin, Sodium C14-16 Olefin Sulfonate, SODIUM LAUROAMPHOACETATE, Coco-Betaine, Niacinamide, Citric Acid, SODIUM OLIVAMPHOACETATE, Alpha-Glucan Oligosaccharide, Parfum, Saccharide Isomerate, Caprylyl/Capryl Glucoside, Sodium Benzoate, Potassium Sorbate, POLYGLYCERYL-3 COCOATE, POLYGLYCERYL-10 LAURATE, GOSSYPIUM HERBACEUM (COTTON) SEED OIL, Sodium Citrate', '', 1, 'l', 'svr-topialyse-huile-lavante-1l-269161', 'https://www.atida.fr/svr-topialyse-huile-lavante-micellaire-relipidante-1l.html', 'https://aurore-cdn.b-cdn.net/products/svr-topialyse-huile-lavante-1l-269161.webp', '', 1554, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.582+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4651-71d4-a831-124c675b1c95', '__OWNER_ID__', 'Atobarrier 365 Cream Mist', 'AESTURA', 'mist', 'bar', 'Aqua, Glycerin, Butylene Glycol, Caprylic/Capric Triglyceride, Hydrogenated Poly(C6-14 Olefin), Dimethicone, Cetyl Ethylhexanoate, Hydroxypropyl Bislauramide Mea, 1,2-Hexanediol, Sodium Surfactin, Cholesterol, Glyceryl Caprylate, Disodium EDTA, Ethylhexylglycerin, Behenic Acid, Tocopherol', 'L''Atobarrier 365 Cream Mist AESTURA est un spray hydratant bi-couche qui combine la nutrition d’une crème avec la fraîcheur d’une brume pour apporter une hydratation instantanée et durable. Formulé avec le Triple Lipid Complex breveté, ce spray ultra-fin aide à reconstituer les céramides, le cholestérol et les acides gras pour renforcer la barrière cutanée tout en prévenant la perte d’hydratation. La technologie des micro-particules assure une répartition uniforme sans lourdeur ni sensation collante. Parfait pour une hydratation sur le pouce, ce spray apaise la sécheresse, calme la sensation de tiraillement et restaure le confort tout au long de la journée, même sur le maquillage. L''Atobarrier 365 Cream Mist AESTURA laisse la peau douce, équilibrée et résistante, en faisant un indispensable pour les environnements secs, les voyages ou les routines de réparation de la barrière. Recommandé pour : Peaux sèches, tendues ou déshydratées ; barrière cutanée affaiblie.', 120, 'ml', 'aestura-atobarrier-365-cream-mist', 'https://korean-skincare.fr/products/aestura-atobarrier-365-cream-mist', 'https://aurore-cdn.b-cdn.net/products/aestura-atobarrier-365-cream-mist.webp', 'Agite bien avant utilisation pour mélanger les couches de crème et d’essence. Tiens à 20–30 cm de ton visage et vaporise uniformément. Tapote doucement pour faire pénétrer. Utilise à tout moment de la journée selon les besoins.', 2395, '2026-05-07 17:37:40.945009+00', '2026-06-14 15:14:07.582+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4665-7359-b838-406be6b4d5dd', '__OWNER_ID__', 'Theracne 365 Hydro Active Toner', 'AESTURA', 'toner', 'pump', 'Aqua, Butylene Glycol, Glycerin, Niacinamide, Isopentyldiol, Betaine, Panthenol, Allantoin, Dipotassium Glycyrrhizate, Xanthan Gum, Disodium EDTA, Ethylhexylglycerin, Cellulose Gum, Salicylic Acid, Zinc Chloride, Tocopherol', 'Le Theracne 365 Hydro Active Toner AESTURA est un tonique équilibrant et régulateur de sébum conçu pour hydrater les peaux à tendance acnéique tout en aidant à prévenir les éruptions. Cette formule légère et rapidement absorbée élimine les impuretés résiduelles après le nettoyage et recharge la peau en hydratation sans obstruer les pores. Développé avec une expertise dermatologique, il aide à maintenir un équilibre optimal entre eau et sébum pour garder la peau nette et confortable. Enrichi en ingrédients apaisants et renforçant la barrière cutanée, le Theracne 365 Hydro Active Toner AESTURA calme les rougeurs, affine la texture de la peau et prépare le visage aux soins ciblés. Une utilisation régulière favorise un teint plus lisse, plus clair et plus équilibré sans sécheresse ni irritation. Recommandé pour : Peaux à tendance acnéique, excès de sébum, pores obstrués, texture irrégulière.', 200, 'ml', 'aestura-theracne-365-hydro-active-toner', 'https://korean-skincare.fr/products/aestura-theracne-365-hydro-active-toner', 'https://aurore-cdn.b-cdn.net/products/aestura-theracne-365-hydro-active-toner.webp', 'Après le nettoyage, applique une quantité appropriée sur un coton ou tes mains et balaie ou tapote doucement ton visage. Continue avec un sérum et une crème hydratante. Utilise matin et soir.', 2795, '2026-05-07 17:37:40.965123+00', '2026-06-14 15:14:07.583+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4692-7bd5-adb2-e91f474ebd31', '__OWNER_ID__', 'Aqua Soothing Toner', 'RealBarrier', 'toner', 'pump', 'Aqua, Centella Asiatica Leaf Water, Propanediol, Dipropylene Glycol, Glycerin, 1,2-Hexanediol, Caprylic/Capric Triglyceride, Hydrogenated Lecithin, Esters Hydrolysés de Jojoba, Phytostéryl/Octyldodécyl Lauroyl Glutamate, Ceramide NP, Myristoyl/Palmitoyl Oxostearamide/Arachamide MEA, Allantoin, Panthenol, Madecassoside, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Glycosaminoglycanes Hydrolysées, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Huile de Fruit de Citrus Aurantium Bergamia (Bergamote), Huile de Fleur de Thymus Mastichina, Caprylyl Glycol, Litsea Cubeba Fruit Oil, Acetyl Hexapeptide-8, Benzyl Glycol, Ethylhexylglycerin, Cétone de Framboise, Caprate de Polyglycéryl-4, Sodium Citrate, Citric Acid', 'L''Aqua Soothing Toner Real Barrier est conçu pour les peaux échauffées et sujettes aux rougeurs. C''est le compagnon idéal de l''Aqua Soothing Gel Cream. Il est utilisé pour préparer la peau, la rafraîchir, la calmer et la tempérer. C''est un tonique hydratant à faible pH, qui aide à améliorer et à promouvoir l''hydratation sur le long terme grâce à 5 formes différentes d''acide hyaluronique (hyaluronate de sodium, polymère croisé d''hyaluronate de sodium, glucosaminoglycanes hydrolysés, acide hyaluronique hydrolysé, acide hyaluronique), tous présents dans la formule en quantités variables, chacun avec sa propre fonction, mais tous contribuant à l''hydratation des différentes couches de l''épiderme. Infusé avec de la Centella Asiatica, qui aide à apaiser et à calmer les irritations causées par le stress environnemental, il contient également du panthénol pour soulager, du madécassoside pour hydrater et de l''allantoïne pour apaiser. Une formule respectueuse pour la peau, même avec un usage quotidien.', 200, 'ml', 'real-barrier-aqua-soothing-toner', 'https://korean-skincare.fr/products/real-barrier-aqua-soothing-toner', 'https://aurore-cdn.b-cdn.net/products/real-barrier-aqua-soothing-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le délicatement sur l''ensemble de ton visage. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 1998, '2026-05-07 17:37:41.010616+00', '2026-06-14 15:14:07.583+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-47a1-7852-9b55-c0985dd64e3d', '__OWNER_ID__', 'Waterfull Hyaluronic Acid Toner', 'JUMISO', 'toner', 'pump', 'Aqua, Butylene Glycol, 1,2-Hexanediol, Glycerin, Madecassoside, Asiaticoside, Centella Asiatica Extract, Salicornia Herbacea Extract, Phragmites Communis Extract, Chrysanthellum Indicum Extract, Asarum Sieboldii Root Extract, Coptis Japonica Root Extract, Rheum Palmatum Root/Stalk Extract, Larix Sibirica Wood Extract, Illicium Verum Fruit Extract, Corydalis Turtschaninovii Root Extract, Quercus Mongolia Leaf Extract, Persicaria Hydropiper Extract, Machilus Thunbergii Bark Extract, Ceramide NP, Hydrogenated Lecithin, Panthenol, Pantolactone, Beta-Glucan, Propanediol, Helianthus Annuus Seed Oil, Camellia Japonica Seed Oil, Macadamia Ternifolia Seed Oil, Argania Spinosa Kernel Oil, Limnanthes Alba Seed Oil, Sodium Hyaluronate, Hydrolyzed Glycosaminoglycans, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Hyaluronic Acid, Sodium Acetylated Hyaluronate, Octyldodecanol, Ethylhexylglycerin, Trehalose, Benzyl Glycol, Caprylyl Glycol, Raspberry Ketone, Disodium EDTA', 'Profite d''une vague d''hydratation avec le Waterfull Hyaluronic Acid Toner Jumiso, enrichi du Waterfull 7-Complex Hyaluronic Acid pour une hydratation multicouche. Ce tonique est doté d''un mélange de céramides, de centella et de madécassoside, qui agissent harmonieusement pour renforcer la barrière cutanée et emprisonner l''hydratation tout en apaisant les rougeurs et l''inflammation. Sans parfum et sans alcool, il est rapidement absorbé par la peau sans laisser de résidus collants, ce qui le rend adapté à tous les types de peau, y compris les peaux grasses et sujettes à l''acné. Recommandé pour : Peaux sensibles, peaux sèches, tous types de peaux.', 250, 'ml', 'jumiso-waterfull-hyaluronic-acid-toner', 'https://korean-skincare.fr/products/jumiso-waterfull-hyaluronic-acid-toner', 'https://aurore-cdn.b-cdn.net/products/jumiso-waterfull-hyaluronic-acid-toner.webp', 'Commence par nettoyer ta peau. Etale délicatement une quantité appropriée de produit sur ta peau avec tes mains ou à l''aide d''une compresse en coton, en évitant le contour des yeux et de la bouche. Tapote légèrement pour une absorption maximale.', 2195, '2026-05-07 17:37:41.28138+00', '2026-06-14 15:14:07.583+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-46eb-7ad6-939b-9f87e54ddacd', '__OWNER_ID__', 'Daily Purifying Treatment Toner', 'AXIS-Y', 'toner', 'pump', 'Aqua, Centella Asiatica Extract, Eau de Feuilles d''Aloe Barbadensis, Butylene Glycol, Alcohol, Sodium Hyaluronate, Melaleuca Alternifolia Leaf Extract, Sesquioleate de Sorbitan, Vaccinium Myrtillus Fruit Extract, Extrait de Canne à Sucre Saccharum Officinatum, Extrait d''Érable à Sucre Acer Saccharum, Extrait de Fruit d''Orange Citrus Aurantium Dulcis, Extrait de Fruit de Citrus Medica Limonum, Betaine, Salicylic Acid, Extrait de Sauge Salvia Officinalis, Houttuynia Cordata Extract, Extrait de Hieracium Pilosella, Extrait de Fruit d''Anis Illicium Verum, Extrait de Fruit de Pamplemousse Citrus Paradisi, Extrait de Fleur de Nelumbium Speciosum, Extrait de Racine de Paeonia Suffruticose, Extrait de Racine de Scutellaria Baicalensis, Huile de Ricin Hydrogénée PEG-60, Chlorphenesin, Ethylhexylglycerin, Sodium Citrate, Gluconolactone, Arginine, Extrait de Racine de Rhubarbe Rheum Palmatum, Extrait de Feuille d''Artemisis Princeps, Extrait de Racine de Ginseng Panax, Carbomer, Diméthyl Sulfone, Huile de Lavande Lavandula Angustifolia, Melaleuca Alternifolia Leaf Oil', 'Le Daily Purifying Treatment Toner AXIS-Y est un produit purifiant qui désincruste les pores tout en calmant les irritations de la peau. Ce tonique assainissant s''attaque à la racine du problème en se débarrassant des bactéries et de la pollution qui provoquent l''inflammation de la peau. Il exfolie en douceur les cellules mortes de la peau.', 200, 'ml', 'axis-y-daily-purifying-treatment-toner', 'https://korean-skincare.fr/products/axis-y-daily-purifying-treatment-toner', 'https://aurore-cdn.b-cdn.net/products/axis-y-daily-purifying-treatment-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 2307, '2026-05-07 17:37:41.099627+00', '2026-06-14 15:14:07.583+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4715-72d1-9bb5-a1a3539deeda', '__OWNER_ID__', 'Collagen Toner Pad', 'MIXSOON', 'toner', 'pack', 'Aqua, Butylene Glycol, Urée Hydroxyéthylée, Niacinamide, Succinate de Diéthoxyéthyle, 1,2-Hexanediol, Hydroxyacetophenone, Isostéarate de Glycéreth-25 PCA, Propanediol, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate, Glycerin, Extrait de Grain de Maïs (Zea Mays), Inulin, Glucose, Gomme Xanthane, Ethylhexylglycerin, Adenosine, Sodium Phytate, Citric Acid, ADN de Sodium, Collagène Hydrolysé', 'Redonne de l''élasticité et de l''éclat à ta peau fatiguée et terne avec les Collagen Toner Pads MIXSOON, un soin raffermissant et hydratant bourré de collagène vegan et de PDRN d''origine végétale pour booster l''élasticité et réduire les ridules. Avec de la niacinamide, de l''adénosine et trois types d''acide hyaluronique, ces compresses revitalisantes hydratent en profondeur et éclaircissent tout en lissant le grain de peau. Le tissu en cellulose doux et déchirable adhère confortablement sans irriter, parfait pour une hydratation rapide ou un soin ciblé. Testé cliniquement et adapté même aux peaux les plus sensibles, c''est ton nouveau produit quotidien pour un teint repulpé et éclatant. Recommandé pour : Peaux sensibles et sèches, tous types de peaux.', 170, 'ml', 'mixsoon-collagen-toner-pad', 'https://korean-skincare.fr/products/mixsoon-collagen-toner-pad', 'https://aurore-cdn.b-cdn.net/products/mixsoon-collagen-toner-pad.webp', 'Comme tonique à passer : essuie délicatement ta peau après le nettoyage pour lisser le grain de peau et booster l''effet du produit de soin appliqué ensuite. Comme masque : applique sur les zones sèches ou irritées pour apaiser.', 1995, '2026-05-07 17:37:41.141059+00', '2026-06-14 15:14:07.583+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-471f-7262-9513-ecbc8716cc37', '__OWNER_ID__', 'Bifida Toner', 'MIXSOON', 'toner', 'pump', 'Aqua, Butylene Glycol, 1,2-Hexanediol, Bifida Ferment Lysate', 'Le Bifida Toner MIXSOON offre une solution transformatrice pour la réparation et l''hydratation de ta peau, en exploitant le pouvoir du bifida, un puissant probiotique. En stimulant le processus de régénération de la peau, ce tonique renforce efficacement la barrière cutanée, réduisant les boutons et les rougeurs tout en apportant une hydratation intense. Ses propriétés apaisantes en font un produit idéal pour soulager les peaux fragiles et irritées, tout en protégeant contre les dommages causés par les radicaux libres et en réduisant la sensibilité de la peau. Recommandé pour : Sans risques pour l''acné fongique, peaux sensibles, tous types de peaux.', 150, 'ml', 'mixsoon-bifida-toner', 'https://korean-skincare.fr/products/mixsoon-bifida-toner', 'https://aurore-cdn.b-cdn.net/products/mixsoon-bifida-toner.webp', 'Commence par nettoyer ta peau. Étale délicatement une quantité appropriée de produit de façon uniforme sur ta peau avec tes mains ou à l''aide d''un coton, en évitant le contour des yeux et de la bouche. Tapote légèrement pour une absorption maximale.', 1395, '2026-05-07 17:37:41.151043+00', '2026-06-14 15:14:07.584+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4723-7e5c-b3d1-d92c74528aea', '__OWNER_ID__', 'Bean Toner', 'MIXSOON', 'toner', 'pump', 'Aqua, 1,2-Hexanediol, Glycereth-26, Glycerin, Extrait de Graine de Glycine Max, Betaine, Allantoin, C12-14 Pareth-12, Ethylhexylglycerin, Disodium EDTA, Citric Acid, Sodium Citrate, Propanediol, Lactobacillus/Filtrat de Fermentation de Racine de Ginseng Panax, Lactobacillus Ferment, Lactobacillus/Extrait de Fermentation de Soja, Saccharomyces/Filtrat de Fermentation de Graines de Coix Lacryma-Jobi Ma-Yuen, Saccharomyces/Filtrat de Fermentation de Pomme de Terre', 'Laisse ta peau s''abandonner à la caresse nourrissante du Bean Toner MIXSOON, un élixir apaisant enrichi d''extrait de graines de Glycine Max (soja). Ce tonique doux transcende l''ordinaire, offrant des bienfaits apaisants et adoucissants aux peaux irritées tout en leur assurant une protection essentielle contre les radicaux libres. Infusé avec la puissante combinaison de bétaïne et de Lactobacillus/Filtrat de Ferment de Racine de Panax Ginseng, il délivre une puissante dose d''hydratation et d''effets anti-âge, laissant ta peau rebondie et rajeunie. Recommandé pour : Peaux sensibles, sans risque pour l''acné fungale, tous types de peaux.', 100, 'ml', 'mixsoon-bean-toner', 'https://korean-skincare.fr/products/mixsoon-bean-toner', 'https://aurore-cdn.b-cdn.net/products/mixsoon-bean-toner.webp', 'Commence par nettoyer ton visage. Passe délicatement une quantité suffisante de produit sur la peau de façon uniforme avec tes mains ou à l''aide d''un coton. Tapote doucement pour une absorption optimale.', 1164, '2026-05-07 17:37:41.15574+00', '2026-06-14 15:14:07.585+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4726-73ae-b08e-131978ab7a99', '__OWNER_ID__', 'Calming Boosting Mist', 'MIXSOON', 'mist', 'spray', 'Centella Asiatica Extract, Houttuynia Cordata Extract, Extrait de Fleur de Bellis Perennis, Melaleuca Alternifolia Leaf Extract, Sodium Hyaluronate', 'Fais l''expérience d''une hydratation et d''un soulagement instantanés grâce à la Calming Boosting Mist MIXSOON, un allié polyvalent pour ta routine beauté. Parfaite pour rafraîchir et hydrater ta peau à tout moment et en tout lieu, cette brume permet une hydratation et un apaisement efficaces, ce qui la rend idéale pour tous les types de peau. Enrichie en extraits de Centella Asiatica et de Houttuynia Cordata, elle apaise en douceur les peaux irritées et réduit les inflammations, tandis que le hyaluronate de sodium renforce la barrière d''hydratation de la peau. Conçue pour les peaux sensibles, cette brume est indispensable pour maintenir un teint calme et revitalisé tout au long de la journée. Recommandé pour : Sans risques pour l''acné fongique, peaux sensibles, tous types de peaux.', 50, 'ml', 'mixsoon-calming-boosting-mist', 'https://korean-skincare.fr/products/mixsoon-calming-boosting-mist', 'https://aurore-cdn.b-cdn.net/products/mixsoon-calming-boosting-mist.webp', 'Commence par nettoyer ta peau. Ferme les yeux et vaporise une quantité adéquate de produit à 20 cm de ton visage. Tapote légèrement pour une absorption maximale.', 1501, '2026-05-07 17:37:41.158113+00', '2026-06-14 15:14:07.585+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4733-7f44-880c-5bff78e39ec0', '__OWNER_ID__', 'Hyaluronic Acid Toner Pad', 'MIXSOON', 'toner', 'pack', 'Aqua, Methylpropanediol, Butylene Glycol, Érythritol, 1,2-Hexanediol, Propanediol, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate, Hydroxyacetophenone, Isostéarate de Glycéreth-25 PCA, Panthenol, Glucoside de Glycéryle, Glycerin, Ethylhexylglycerin, Méthyl Diisopropyl Propionamide, Disodium EDTA, Hydroxyéthylcellulose, Tocopherol, Helianthus Annuus Seed Oil', 'Les Hyaluronic Acid Toner Pads MIXSOON sont un allié hydratant incontournable, qui apporte une bouffée d''hydratation à chaque utilisation. Enrichies en plusieurs types d''acide hyaluronique et en panthénol, ces compresses ultra-douces à la texture gel apaisent instantanément les peaux sèches et ternes tout en renforçant leur barrière cutanée naturelle. Conçues avec deux côtés, un côté gel apaisant et un côté gaze de coton douce, elles offrent à la fois les bienfaits d''un tonique et d''un soin apaisant en une seule étape. Testées cliniquement et sans risque pour les peaux sensibles, ces compresses toniques laissent ton teint repulpé, éclatant et rafraîchi. Recommandé pour : Sans risque pour l''acné fongique, peaux sèches, tous types de peaux.', 180, 'ml', 'mixsoon-hyaluronic-acid-toner-pad', 'https://korean-skincare.fr/products/mixsoon-hyaluronic-acid-toner-pad', 'https://aurore-cdn.b-cdn.net/products/mixsoon-hyaluronic-acid-toner-pad.webp', 'Comme tonique à passer : essuie délicatement ta peau après le nettoyage pour lisser le grain de peau et booster l''effet du produit de soin suivant. Comme masque : Applique sur les zones sèches ou irritées pour apaiser.', 1543, '2026-05-07 17:37:41.171868+00', '2026-06-14 15:14:07.585+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4736-70a7-8627-75734a8b8206', '__OWNER_ID__', 'Heartleaf Toner', 'MIXSOON', 'toner', 'pump', 'Houttuynia Cordata Extract', 'Profite d''un voyage revitalisant avec le Heartleaf Toner MIXSOON, enrichi d''essence naturelle de Houttuynia Cordata pour un rituel de soin rajeunissant. À chaque application, délecte-toi du toucher délicat et de la réparation en douceur de ce tonique, qui vient apaiser et équilibrer ta peau, la laissant rafraîchie et prête à affronter la journée qui s''annonce. La Houttuynia Cordata, connue pour ses propriétés calmantes et équilibrantes, favorise la santé et la vitalité de la peau, garantissant un teint rayonnant et un éclat naturel. Recommandé pour : Sans risques pour l''acné fongique, peaux sensibles, tous types de peaux.', 150, 'ml', 'mixsoon-heartleaf-toner', 'https://korean-skincare.fr/products/mixsoon-heartleaf-toner', 'https://aurore-cdn.b-cdn.net/products/mixsoon-heartleaf-toner.webp', 'Commence par nettoyer ta peau. Étale délicatement une quantité appropriée uniformément sur ta peau avec tes mains ou à l''aide d''un disque de coton, en évitant le contour des yeux et de la bouche. Tapote légèrement pour une absorption maximale.', 1183, '2026-05-07 17:37:41.173953+00', '2026-06-14 15:14:07.585+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-653d-785b-8da3-d23d2c221fb3', '__OWNER_ID__', 'Sebiaclear Micro-Peel', 'SVR', 'exfoliant', 'bottle', 'Aqua, Alcohol Denat, Niacinamide, Lactobionic Acid, ZINC GLUCONATE, Salicylic Acid, Sodium Hydroxide, Parfum', 'Lotion lissante et désincrustante pour peaux mixtes à grasses à base de duo d''acides.', 150, 'ml', 'svr-sebiaclear-micro-peel', 'https://fr.labo-svr.com', 'https://aurore-cdn.b-cdn.net/products/svr-sebiaclear-micro-peel.webp', '4% Niacinamide. 1% Zinc. Acide lactobionique et salicylique. Texture eau rafraîchissante.', 1750, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.585+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4776-712a-88f8-bbcd2e5ebaae', '__OWNER_ID__', 'Greenful Balancing Toner', 'Beplain', 'toner', 'pump', 'Extrait de Graine de Phaseolus Radiatus (à 426,000 ppm), Aqua, Butylene Glycol, Dipropylene Glycol, Glycereth-26, 1,2-Hexanediol, Hydroxyacetophenone, Glyceryl Glucoside, Xylitylglucoside, Anhydroxylitol, Allantoin, Panthenol, Glycerin, Xylitol, Sodium Hyaluronate, Dipotassium Glycyrrhizate, Gluconolactone, Glucose, Gomme Xanthane, Extrait d''Écorce de Magnolia Kobus, Disodium EDTA, Sodium Citrate', 'Le Greenful balancing Toner Be Plain est un tonique doux, au pH équilibré, qui aide à apaiser et à équilibrer les peaux irritées et sensibles, pour une peau douce et rafraîchie. Sa texture légère et aqueuse élimine les résidus après le lavage et laisse la peau confortable et rafraîchie. Sa formule légèrement acide, au pH équilibré, rétablit un pH sain dans la peau avec un fini non collant, satiné et frais.', 200, 'ml', 'be-plain-greenful-balancing-toner', 'https://korean-skincare.fr/products/be-plain-greenful-balancing-toner', 'https://aurore-cdn.b-cdn.net/products/be-plain-greenful-balancing-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 1995, '2026-05-07 17:37:41.237982+00', '2026-06-14 15:14:07.586+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64fd-70f3-b597-6c076b3c88e3', '__OWNER_ID__', 'Labello Sun Protect SPF50 Soin des Levres', 'Eucerin', 'lip-care', 'stick', 'Octyldodecanol, Ricinus Communis Seed Oil, Cera Alba, HYDROGENATED RAPESEED OIL, Avobenzone, Ethylhexyl Salicylate, Butyrospermum Parkii Butter, Cetyl Palmitate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Ethylhexyl Triazone, Parfum, Helianthus Annuus Seed Oil, Tocopherol, Linalool, Citronellol', 'Pour des lèvres hydratées et protégées du soleil, LABELLO Stick Sun Protect en ligne, à prix discount, prend soin de vos lèvres tout au long de la journée.
INSERT INTO public.products VALUES ('019e0384-4753-7ffa-95e1-a0e85ad03d4f', '__OWNER_ID__', 'Cicatree Clean Toner', 'MIXSOON', 'toner', 'pump', 'Aqua, Butylene Glycol, Dipropylene Glycol, Glycerin, 1,2-Hexanediol, Niacinamide, Melaleuca Alternifolia Leaf Water, Centella Asiatica Extract, Glycéryl Glucoside, C12-14 Pareth-12, Panthenol, Sodium Citrate, Allantoin, Dipotassium Glycyrrhizate, Ethylhexylglycerin, Disodium EDTA, Glucose, Gomme Xanthane, Melaleuca Alternifolia Leaf Oil, Citric Acid, Betaine Salicylate, Gluconolactone, Sodium Hyaluronate', 'Profite des bienfaits rajeunissants du Clean Toner Cicatree, spécialement conçu pour apaiser et illuminer la peau. Formulé avec un mélange non collant à base d''eau enrichi d''acide hyaluronique et de panthénol, ce tonique hydrate en profondeur, augmentant les niveaux d''hydratation de la peau de 77 %, tout en maintenant un équilibre sain du pH de 5,7. Infusé d''AHA, BHA et PHA, il purifie et lisse délicatement la peau, ciblant les imperfections à l''aide de l''acide salicylique. De l''arbre à thé et de l''extrait de Centella Asiatica offrent un soulagement apaisant aux peaux irritées, tandis que le niacinamide éclaircit et unifie le teint. Recommandé pour : Sans risques pour l''acné fongique, peaux à hyperpigmentation, peaux à tendance acnéique, tous types de peaux.', 150, 'ml', 'mixsoon-cicatree-clean-toner', 'https://korean-skincare.fr/products/mixsoon-cicatree-clean-toner', 'https://aurore-cdn.b-cdn.net/products/mixsoon-cicatree-clean-toner.webp', 'Commence par nettoyer ta peau. Étale délicatement une quantité appropriée de produit uniformément sur ta peau avec tes mains ou à l''aide d''un disque de coton. Tapote légèrement pour une absorption maximale.', 1425, '2026-05-07 17:37:41.203891+00', '2026-06-14 15:14:07.586+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4785-7473-82fa-fe499dc098b2', '__OWNER_ID__', 'Cica Care Balancing Toner', 'Rovectin', 'toner', 'pump', 'Aqua, Dipropylene Glycol, Glycerin, Methylpropanediol, Propanediol, 1,2-Hexanediol, C12-14 Pareth-12, Panthenol, Madecassoside, Centella Asiatica Extract, Hedera Helix Ivy Leaf/Stem Extract, Pyrus Malus Apple Fruit Extract, Jasminum Officinale Jasmine Flower Water, Perilla Ocymoides Leaf Extract, Tanacetum Vulgare Extract, Glycine, Serine, Glutamic Acid, Aspartic Acid, Leucine, Alanine, Lysine, Arginine, Tyrosine, Phenylalanine, Proline, Threonine, Valine, Isoleucine, Histidine, Cysteine, Methionine, Disodium EDTA, Prunus Amygdalus Amara Bitter Almond Kernel Oil, Vanilla Planifolia Fruit Extract, Butylene Glycol', 'Le Cica Care Balancing Toner Rovectin cible les peaux les plus sensibles et irritées, fragilisées par des facteurs courants comme les poussées hormonales, l’âge ou la rosacée. Testé sur peaux sensibles, ce tonique Cica Care apaise en douceur et aide à protéger les peaux affaiblies. Enrichi en Centella Asiatica (cica), madecassoside et panthénol, il aide à réduire les rougeurs, soutient la réparation cutanée et apporte une hydratation durable. Sa texture légère, presque aqueuse, pénètre rapidement pour laisser la peau fraîche, rebondie et parfaitement prête pour la suite de ta routine. Idéal pour les peaux sensibles, acnéiques ou facilement réactives. Recommandé pour : Tous types de peaux.', 260, 'ml', 'cica-care-purifying-toner', 'https://korean-skincare.fr/products/cica-care-purifying-toner', 'https://aurore-cdn.b-cdn.net/products/cica-care-purifying-toner.webp', 'Applique une quantité appropriée de produit sur un coton. Glisse le coton en suivant délicatement les lignes de ta peau. Retourne le coton et tapote doucement pour faire pénétrer.', 2895, '2026-05-07 17:37:41.253156+00', '2026-06-14 15:14:07.586+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-47b8-778c-a1d1-aa2e682a7514', '__OWNER_ID__', 'All Day Vitamin Glow Boost Facial Toner', 'JUMISO', 'toner', 'pump', 'Aqua, Butylene Glycol, Dipropylene Glycol, 1,2-Hexanediol, Niacinamide, Eau de Hippophae Rhamnoides, Hippophae Rhamnoides Fruit Extract, Glycerin, Méthyl Gluceth-20, Betaine, Panthenol, 2-O-Ethyl Acide Ascorbique, Allantoin, Arginine, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Disodium EDTA, Citric Acid, Tranexamic Acid, Dipotassium Glycyrrhizate, Hydroxyéthylcellulose, Undaria Pinnatifida Extract, Extrait de Graine de Perilla Ocymoides, Ascorbic Acid, Propanediol, Caprylyl Glycol, Camellia Japonica Flower Extract', 'L''All Day Vitamin Glow Boost Facial Toner Jumiso est un tonique vegan sans parfum qui prépare et hydrate la peau tout en renforçant son éclat naturel. Infusé de niacinamide, d''acide ascorbique, d''acide tranexamique et de panthénol, ce tonique aide à calmer et à affiner les pores, à unifier le teint et à promouvoir un éclat durable. Idéal comme première étape après le nettoyage, il nettoie et rafraîchit la peau tout en la préparant pour une meilleure absorption des produits de soin suivants. Grâce à sa formule légère et non grasse, ce tonique sans alcool laisse la peau équilibrée et lisse, ce qui en fait un produit idéal pour tous les types de peau. Recommandé pour : Sans risque pour l''acné fongique, peaux sèches, tous types de peaux.', 125, 'ml', 'jumiso-all-day-vitamin-glow-boost-facial-toner', 'https://korean-skincare.fr/products/jumiso-all-day-vitamin-glow-boost-facial-toner', 'https://aurore-cdn.b-cdn.net/products/jumiso-all-day-vitamin-glow-boost-facial-toner.webp', 'Commence par nettoyer ta peau. Distribue délicatement une quantité appropriée de produit sur ta peau à l''aide de tes mains ou d''un disque de coton, en évitant le contour des yeux et de la bouche. Tapote légèrement pour une absorption maximale.', 2395, '2026-05-07 17:37:41.304309+00', '2026-06-14 15:14:07.586+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e07e6-00e0-7595-919c-7bafb42f0446', '__OWNER_ID__', 'Flawless Nightly Eye 2% Retinoid Serum', 'Dr Sam''s', 'eye-cream', 'pump', 'Aqua, Butyrospermum Parkii Butter, Propanediol, Niacinamide, Cetearyl Olivate, Sorbitan Olivate, Ascorbyl Glucoside, Dimethyl Isosorbide, Squalane, Cetyl Alcohol, Phenoxyethanol, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Gluconolactone, Sodium Hydroxide, Hydroxypinacolone Retinoate, Sodium Stearoyl Glutamate, Sodium Benzoate, Polysorbate 60, Disodium EDTA, Ethylhexylglycerin, Sorbitan Isostearate, Calcium Gluconate', 'Eye serum with 2% Granactive Retinoid and Niacinamide. Brightens dark circles, reduces fine lines, and hydrates the delicate eye area.', 15, 'ml', 'dr-sams-flawless-nightly-eye-serum', 'https://drsambunting.com/en-eu/products/flawless-nightly-eye-serum', 'https://aurore-cdn.b-cdn.net/products/dr-sams-flawless-nightly-eye-serum.webp', NULL, 4800, '2026-05-08 14:02:54.559103+00', '2026-06-14 15:14:07.587+00', 'skincare', '[]', 'mousse', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
