INSERT INTO public.products VALUES ('019e0384-3de9-7267-ba7d-c782488c414d', '__OWNER_ID__', 'Dare Body Hand Cream', 'MISSHA', 'hand-cream', 'jar', 'Aqua, Butyrospermum Parkii Butter, Glycerin, Cetearyl Alcohol, Glycereth-26, Caprylic/Capric Triglyceride, Glyceryl Stearate SE, Polysorbate 60, Glyceryl Stearate, PEG-100 Stearate, Sorbitan Stearate, Cetyl Ethylhexanoate, Dimethicone, Dipropylene Glycol, Palmitic Acid, Stearic Acid, Parfum, Hydroxyacetophenone, 1,2-Hexanediol, Carbomer, Sodium Hydroxide, Xanthan Gum, Sucrose Cocoate, Disodium EDTA, Cyclomethicone, Tocopheryl Acetate, Butylene Glycol, Centerlla Asiatica Gotu Kola Extract, Coumarin, Geraniol, Linalool, Citronellol, Hexyl Cinnamal, Limonene, lpha-Isomethyl Ionone *Liste générale ; les ingrédients peuvent légèrement varier selon le parfum. Veuillez vous référer à l’emballage réel pour les détails exacts', 'La Dare Body Hand Cream MISSHA est une formule richement hydratante mais à absorption rapide qui laisse tes mains douces, lisses et délicieusement parfumées. Enrichie en ingrédients nourrissants comme le beurre de karité et la glycérine, elle aide à protéger les peaux sèches tout en offrant une hydratation durable sans sensation de gras. Disponible dans une variété de parfums signature, allant des notes florales fraîches aux notes confortables et propres, cette crème pour les mains transforme l’hydratation quotidienne en un plaisir sensoriel. La Dare Body Hand Cream MISSHA est l’essentiel nomade parfait pour des mains douces et soignées. Recommandé pour : Tous types de peaux, y compris les mains sèches et sensibles.', NULL, NULL, 'missha-dare-body-hand-cream', 'https://korean-skincare.fr/products/missha-dare-body-hand-cream', 'https://aurore-cdn.b-cdn.net/products/missha-dare-body-hand-cream.webp', 'Applique une petite quantité sur mains propres et sèches. Masse doucement jusqu’à absorption complète, en insistant sur les zones sèches comme les articulations et les cuticules. Réapplique au besoin tout au long de la journée pour une hydratation et un parfum continus.', 495, '2026-05-07 17:37:38.792931+00', '2026-06-14 15:14:07.595+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
