INSERT INTO public.products VALUES ('019e0384-3c80-7397-abc8-5ecb76c29311', '__OWNER_ID__', 'Jelloskin Massage Cream for Face & Body', 'Beauty of Joseon', 'body-lotion', 'jar', 'Aqua, Glycerin, Propanediol, Hydrogenated Poly(C6-14 Olefin), Niacinamide, Polyglyceryl-6 Distearate, Cetearyl Alcohol, Propylheptyl Caprylate, Ammonium Acryloyldimethyltaurate/VP Copolymer, Candelilla/​Jojoba/​Rice Bran Polyglyceryl-3 Esters, 1,2-Hexanediol, Vinyl Dimethicone, Glyceryl Stearate, Methyl Trimethicone, Hydroxyacetophenone, Dipropylene Glycol, Laminaria Japonica Extract, Eclipta Prostrata Leaf Extract, Coptis Japonica Root Extract, Butylene Glycol, Oryza Sativa (Rice) Bran Oil, Ethylhexylglycerin, Xanthan Gum, Sodium Stearoyl Glutamate, Fructooligosaccharides, Adenosine, Glyceryl Polymethacrylate, Hydrogenated Lecithin, Beta-Glucan, Panthenol, Hydrolyzed Hyaluronic Acid, Maltodextrin, Tocopherol, Methylpropanediol, Hydrolyzed Gardenia Florida Extract, Ceramide NP, Opuntia Coccinellifera Fruit Extract, Phaseolus Vulgaris (Kidney Bean) Seed Extract', 'Découvre la Jelloskin Massage Cream for Face & Body Beauty of Joseon, une crème hydratante et revitalisante polyvalente conçue pour les massages du visage et du corps. Sa texture unique à la texture de gelée glisse sans effort sur la peau et pénètre en profondeur pour stimuler les niveaux d''hydratation. Riche en ingrédients nourrissants comme le niacinamide, le panthénol et l''extrait de haricot de Centiger, cette crème améliore l''élasticité de la peau, réduit les signes de l''âge et favorise un teint soyeux, lisse et éclatant. Formulée avec la formule Hanbang de Beauty of Joseon et en collaboration avec byAva, elle équilibre harmonieusement le corps et l''esprit, ce qui la rend idéale pour apaiser les tensions physiques et mentales par le massage tout en fortifiant la barrière cutanée. Recommandé pour : Tous types de peaux.', 200, 'ml', 'beauty-of-joseon-jelloskin-massage-cream-for-face-body1', 'https://korean-skincare.fr/products/beauty-of-joseon-jelloskin-massage-cream-for-face-body1', 'https://aurore-cdn.b-cdn.net/products/beauty-of-joseon-jelloskin-massage-cream-for-face-body1.webp', 'Applique une quantité suffisante de produit sur tout ton corps, y compris ton visage. Pour de meilleurs résultats, masse avec tes mains ou un gua sha après avoir appliqué généreusement la crème.', 2421, '2026-05-07 17:37:38.432093+00', '2026-06-14 15:14:07.594+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64f2-7b58-a56d-bb0a1d1941af', '__OWNER_ID__', 'HAND Remedy — Advanced Hand & Cuticle Butter Cream', 'Remedy Science', 'hand-cream', 'tube', 'Aqua, Butyrospermum Parkii Butter, Glyceryl Stearate SE, Glycerin, Propanediol, Cetearyl Olivate, C15-19 Alkane, Cetearyl Alcohol, Retinol, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Squalane, Coco-Caprylate, Butylene Glycol, Pentylene Glycol, Glycine Soja Oil, Glycolic Acid, Lactic Acid, Acetyl Heptapeptide-4, Ceramide NP, Ceramide AP, Ceramide EOP, Glycine Soja (Soybean) Extract, Curcuma Longa Root Extract, Cucumis Sativus Fruit Extract, Sorbitan Olivate, Sodium Stearoyl Glutamate, Aloe Barbadensis Leaf Juice, Avena Sativa (Oat) Kernel Flour, Phytosphingosine, Cholesterol, Sodium Lauroyl Lactylate, Carbomer, Xanthan Gum, Acacia Senegal Gum, Propylene Glycol Alginate, Cetyl Lactate, Tocopherol, Caprylyl Glycol, Phenethyl Alcohol, Leuconostoc Ferment Filtrate, Phenoxyethanol, Ethylhexylglycerin, Sodium Hydroxide, Citric Acid', 'Rich hand treatment with encapsulated retinol, shea butter, and ceramides. Hydrates, firms, brightens discoloration, and helps repair the look of damage.', 67, 'ml', 'remedy-hand-cream', 'https://remedyskin.com/products/dry-hand-cream-retinol', 'https://aurore-cdn.b-cdn.net/products/remedy-hand-cream.webp', 'Hero: 20% Shea Butter, 0.1% Encapsulated Retinol, Ceramides (NP + AP + EOP)', 1995, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.594+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44b7-7558-af2b-8dc3a2b8a4f9', '__OWNER_ID__', 'Shea Butter & Rice Bran Body Cream', 'Mary&May', 'body-lotion', 'jar', 'Aqua, Butyrospermum Parkii Butter, Glycerin, Alkyl Benzoate C12-15, Polyglyceryl-3 Distearate, Caprylyl Methicone, Glyceryl Stearate, Cetearyl Alcohol, Polymethylsilsesquioxane, Oryza Sativa Extract, 1,2-Hexanediol, Copolymère d’Acryloyldiméthyltaurate/VP, Alcool Béhenyl, Hydroxyacetophenone, Glutamate Stéaroyl de Sodium, Citrate de Stéarate de Glycéryl, Ethylhexylglycerin, Butylene Glycol, Gomme de Xanthane, Disodium EDTA, Ceramide NP, Caprylyl Glycol, Tocopherol', 'La Shea Butter & Rice Bran Body Cream Mary & May est un soin corporel luxueux et sans parfum conçu pour nourrir et hydrater en profondeur les peaux sèches, rugueuses et sensibles. Formulé avec 20 % de beurre de Butyrospermum Parkii (karité) à haute concentration, il apporte une hydratation intense, adoucit les zones rugueuses comme les coudes et les pieds, laissant la peau douce et souple. L’extrait de son de riz (Oryza Sativa), riche en vitamines et acides aminés, nourrit la peau pour un teint clair et lumineux, tandis que le Ceramide NP renforce et protège la barrière cutanée, maintenant l’hydratation pour une hydratation durable. Sa texture douce et crémeuse fond sur la peau, pénètre rapidement sans sensation collante, offrant un fini velouté et rafraîchissant. Cette formule 100 % vegan, cruelty-free et testée dermatologiquement utilise des ingrédients EWG Green Grade, sans parabènes, parfums artificiels, alcools, huiles minérales, sulfates ni allergènes. Emballée dans des matériaux écologiques (papier recyclé et encre à base d’huile de soja), elle respecte l’éthique clean beauty et durabilité de Mary & May. Adaptée à tous les types de peaux, particulièrement les peaux sèches et sensibles, elle traite la sécheresse, la texture rugueuse et la faiblesse de la barrière cutanée, ce qui la rend idéale pour un usage quotidien. Recommandé pour : Tous types de peaux.', 250, 'ml', 'mary-may-shea-butter-rice-bran-body-cream', 'https://korean-skincare.fr/products/mary-may-shea-butter-rice-bran-body-cream', 'https://aurore-cdn.b-cdn.net/products/mary-may-shea-butter-rice-bran-body-cream.webp', 'Après la douche : Après la douche ou lorsque ta peau semble sèche, applique une quantité modérée de crème. Masse doucement pour favoriser l’absorption.', 2495, '2026-05-07 17:37:40.535256+00', '2026-06-14 15:14:07.594+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4270-7fac-921e-6e37645cd1d9', '__OWNER_ID__', 'Low pH Scalp Shampoo', 'Pyunkang Yul', 'shampoo', 'jar', 'Aqua, Coco-Betaine, Alaninate de Sodium Cocoyl, Lauryl Glucoside, Disodium Laureth Sulfosuccinate, Glycerin, Sodium Chloride, Méthyl Isethionate de Sodium Lauroyl, Hydroxyacetophenone, Cetyl Alcohol, Caprylyl Glycol, Polyquaternium-10, Citric Acid, Menthol, Chlorure de Guar Hydroxypropyltrimonium, Melaleuca Alternifolia Leaf Oil, Pentétate de Pentasodium, Citrus Paradisi Peel Oil, Butylene Glycol, Extrait de Racine d''Acorus Calamus, Extrait de Bulbe d''Allium Cepa (Oignon), Extrait d''Artemisia Capillaris, Brassica Oleracea Italica Extract, 1,2-Hexanediol, Extrait de Racine de Cnidium Officinale, Houttuynia Cordata Extract, Cystéine, Méthionine, Melaleuca Alternifolia Leaf Extract, Salvia Officinalis Leaf Extract, Camellia Japonica Flower Extract, Zingiber Officinale Root Extract, Ethylhexylglycerin', 'Le Low pH Scalp Shampoo Pyunkang Yul est un shampooing sans sulfate, non desséchant, qui prend soin de ton cuir chevelu et de tes cheveux. Le faible pH de ce shampooing, combiné à des surfactants naturels doux, assure un nettoyage en douceur qui ne privera pas ton cuir chevelu et tes cheveux de leurs huiles naturelles.', 290, 'ml', 'pyunkang-yul-low-ph-scalp-shampoo', 'https://korean-skincare.fr/products/pyunkang-yul-low-ph-scalp-shampoo', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-low-ph-scalp-shampoo.webp', 'Applique une quantité modérée de la formule sur l''ensemble de tes cheveux humides. Masse délicatement et rince abondamment à l''eau tiède.', 1595, '2026-05-07 17:37:39.952782+00', '2026-06-14 15:14:07.595+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4516-761a-bd56-62258219ffb5', '__OWNER_ID__', 'Cica Peptide Derma Scalp Shampoo', 'SOME BY MI', 'shampoo', 'jar', 'Aqua, Bétaïne de Cocamidopropyle, Glutamate de Cocoyl TEA, Méthylaminopropionate de Lauroyle de Sodium, Disodium Laureth Sulfosuccinate, Cocamide MEA, Sodium Chloride, Parfum, Polyquaternium-10, Glycol Caprylique, Hydroxyacéto-phénone, Éther Myristyle PPG-3, Panthenol, Salicylic Acid, Menthol, Citric Acid, Niacinamide, Sodium Benzoate, Pentétate de Pentasodium, Butylene Glycol, Gluconolactone, Aminométhyl Propanol, 1,2-Hexanediol, Biotin, Extrait de Feuille de Mentha Piperita, Extrait de Mentha Viridis, Extrait de Fleur/Feuille/Tige de Leonurus Sibiricus, Extrait de Germes de Nelumbo Nucifera, Houttuynia Cordata Extract, Extrait d''Artemisia Vulgaris, Camellia Sinensis Leaf Extract, Extrait de Feuille de Mentha Rotundifolia, Centella Asiatica Extract, Ethylhexylglycerin, Protéine de Maïs Hydrolysée, Protéine de Soja Hydrolysée, Protéine de Blé Hydrolysée, Hexapeptide-9, Palmitoyl Pentapeptide-4, Palmitoyl Tripeptide-5, Palmitoyl Tripeptide-1, Palmitoyl Tetrapeptide-7, Palmitoyl Oligopeptide, Tripeptide-1, Copper Tripeptide-1, Acide Asiatique, Asiaticoside, Acetyl Hexapeptide-8, Acétyl Tétrapeptide-2, Acide Madecassique, Madecassoside, Nonapeptide-1', 'Revitalise ton cuir chevelu et contrôle la chute de cheveux avec le Cica Peptide Derma Scalp Shampoo SOME BY MI. Sa formule puissante est infusée de onze types de peptides pour hydrater et nourrir en profondeur le cuir chevelu, favorisant ainsi une croissance saine des cheveux. La biotine et les protéines d''origine végétale provenant d''haricots, de blé et de maïs renforcent le cuir chevelu, tandis que l''hydrocotyle asiatique (Centella Asiatica) apaise les irritations et favorise la régénération de la peau. Enrichi en menthol, ce shampooing procure une sensation de fraîcheur, tandis que le PHA exfolie délicatement pour éliminer les cellules mortes, les impuretés et l''excès de sébum, garantissant ainsi un cuir chevelu propre et revitalisé à chaque lavage.', 285, 'ml', 'some-by-mi-cica-peptide-derma-scalp-shampoo', 'https://korean-skincare.fr/products/some-by-mi-cica-peptide-derma-scalp-shampoo', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-cica-peptide-derma-scalp-shampoo.webp', 'Mouille tes cheveux et ton cuir chevelu avec de l''eau tiède. Fais mousser une quantité normale de shampooing et applique-le sur tes cheveux et ton cuir chevelu. Masse soigneusement. Rince abondamment à l''eau tiède.', 1954, '2026-05-07 17:37:40.630196+00', '2026-06-14 15:14:07.595+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64ec-7942-bbf0-f10eaf3e8b83', '__OWNER_ID__', 'Ducray Dexyane Huile Lavante Protectrice 400ml', 'Ducray', 'body-wash', 'jar', 'Aqua, Glycerin, Disodium Cocoyl Glutamate, oleth-10, sodium cocoamphoacetate, Ceteareth-60 Myristyl Glycol, peg-120 methyl glucose dioleate, Coco-Glucoside, Butyrospermum Parkii Butter, Caprylyl Glycol, Carthamus Tinctorius Seed Oil, Citric Acid, Coco-Glucoside, Cocos Nucifera Oil, Glyceryl Oleate, Glycyrrhetinic Acid, hydrogenated palm glycerides citrate, isoleucine, Lactic Acid, Propylene Glycol, Sodium Benzoate, Sodium Chloride, Tocopherol, Trisodium Ethylenediamine Disuccinate', '', 400, 'ml', 'ducray-dexyane-huile-lavante-protectrice-400ml-269600', 'https://www.atida.fr/ducray-dexyane-huile-lavante-400ml.html', 'https://aurore-cdn.b-cdn.net/products/ducray-dexyane-huile-lavante-protectrice-400ml-269600.webp', '', 1377, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.595+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44b3-7221-a6e2-34dd34a7915c', '__OWNER_ID__', 'Seoul Edition Hand Cream', 'Mary&May', 'hand-cream', 'jar', 'Bergamot & Pear Hand Cream : Aqua, Propanediol, Glycerin, Phenyl Trimethicone, Methyl Trimethicone, 1,2-Hexanediol, Trehalose, Coptis Japonica Root Extract, Extrait de Fruit de Poire, Hydrogenated Polyisobutene, Cetearyl Alcohol, Polyglyceryl-3 Methylglucose Distearate, Glyceryl Stearate, Dicaprylyl Carbonate, Ammonium Acryloyldimethyl Taurate/VP Copolymer, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Caprylyl Glycol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Butylene Glycol, Arginine, Ethylhexylglycerin, Disodium EDTA, Sorbitan Isostearate, Ceramide NP, Tocopherol, Parfum Muguet & Lotus Hand Cream : Aqua, Helianthus Annuus Seed Oil, Glycerin, Propanediol, Palmitic Acid, Stearic Acid, Cetearyl Glucoside, Cetearyl Alcohol, Glyceryl Stearate, Caprylic/Capric Triglyceride, Hydrogenated Polydecene, Extrait de Fleur de Lotus, Sodium Hyaluronate, 1,2-Hexanediol, Butyrospermum Parkii Butter, Hydroxyacetophenone, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Butylene Glycol, Ethylhexylglycerin, Gomme Xanthane, Disodium EDTA, Sorbitan Isostearate, Ceramide NP, Tocopherol, Parfum Shea Butter & Rice Bran Hand Cream : Aqua, Butyrospermum Parkii Butter, Glycerin, Cetearyl Alcohol, Coco-Caprylate/Caprate, Polyglyceryl-3 Distearate, Caprylyl Methicone, Glyceryl Stearate, Polymethylsilsesquioxane, Oryza Sativa Extract, 1,2-Hexanediol, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Behenyl Alcohol, Hydroxyacetophenone, Sodium Stearoyl Glutamate, Glyceryl Stearate Citrate, Ethylhexylglycerin, Butylene Glycol, Gomme Xanthane, Sorbitan Isostearate, Disodium EDTA, Ceramide NP, Caprylyl Glycol, Tocopherol', 'La Seoul Edition Hand Cream Mary & May offre un soin luxueux et profondément hydratant inspiré des subtilités de la K-Beauty. Formulée pour apaiser et nourrir les mains sèches sans laisser de résidus collants, cette crème pour les mains associe des ingrédients traditionnels tels que le beurre de karité et le son de riz à des textures légères pour une hydratation quotidienne ou intensive. Selon la version, par exemple Shea Butter & Rice Bran, Muguet & Lotus ou Bergamot & Pear, la crème peut être sans parfum ou parfumée avec des notes délicates telles que le muguet floral, le lotus, la bergamote citronnée ou la poire. Laisse ton humeur guider ton choix. Recommandé pour : Tous types de peaux, peaux sèches.', NULL, NULL, 'mary-may-seoul-edition-hand-cream', 'https://korean-skincare.fr/products/mary-may-seoul-edition-hand-cream', 'https://aurore-cdn.b-cdn.net/products/mary-may-seoul-edition-hand-cream.webp', 'Prélève une quantité modérée de crème. Applique sur tes mains et masse délicatement pour une meilleure absorption.', 1095, '2026-05-07 17:37:40.530991+00', '2026-06-14 15:14:07.596+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4522-7c89-ac9b-af82eb6f5b0a', '__OWNER_ID__', 'Cica Peptide Derma Scalp Conditioner', 'SOME BY MI', 'conditioner', 'jar', 'Aqua, Dipropylene Glycol, Stearyl Alcohol, Cetyl Alcohol, Behentrimonium Chloride, Chlorure de Steartrimonium, Propylene Glycol, Panthenol, Stéaramidopropyl Diméthylamine, Alcool Isopropylique, Pyrithione de Zinc, Caprylyl Glycol, Salicylic Acid, Polyquaternium-10, Menthol, Chlorure de Guar Hydroxypropyltrimonium, Arginine, Polynaphthalenesulfonate de Sodium, Extrait de Protéine de Lait, Butylene Glycol, Sodium Chloride, Extrait de Feuille de Mentha Piperita, Extrait de Mentha Viridis, 1,2-Hexanediol, Camellia Sinensis Leaf Extract, Houttuynia Cordata Extract, Extrait de Fleur/Feuille/Tige de Leonurus Sibiricus, Extrait de Germes de Nelumbo Nucifera, Extrait d’Artemisia Vulgaris, Extrait de Feuille de Mentha Rotundifolia, Extrait de Graine de Glycine Max, Extrait de Graine de Nigella Sativa, Oryza Sativa Extract, Extrait de Fruit de Ribes Nigrum, Rubus Fruticosus Fruit Extract, Extrait de Graine de Sesamum Indicum, Extrait de Graine de Salvia Hispanica, Vaccinium Angustifolium Fruit Extract, Centella Asiatica Extract, Biotin, Ethylhexylglycerin, Protéine de Maïs Hydrolysée, Protéine de Soja Hydrolysée, Protéine de Blé Hydrolysée, Copper Tripeptide-1, Hexapeptide-9, Nonapeptide-1, Palmitoyl Tripeptide-5, Palmitoyl Pentapeptide-4, Palmitoyl Tripeptide-1, Palmitoyl Oligopeptide, Palmitoyl Tetrapeptide-7, Tripeptide-1, Acetyl Hexapeptide-8, Acétyl Tetrapeptide-2, Madecassoside, Acide Madécassique, Asiaticoside, Acide Asiatique, Parfum', 'Profite de cheveux plus doux et démêlés en seulement trois minutes grâce au Cica Peptide Derma Scalp Treatment SOME BY MI ! Spécialement formulé pour lutter contre la chute des cheveux, ce traitement pour cuir chevelu est infusé de cica, de peptides et d''un complexe noir unique - un mélange puissant d''extraits de cassis, de mûre, de sésame noir et de riz noir qui nourrit intensément le cuir chevelu et les cheveux. Cette riche combinaison d''antioxydants et de nutriments essentiels aide à fortifier la racine des cheveux, à favoriser leur croissance saine et à les protéger contre les dommages causés par les facteurs environnementaux. Exempt de silicones et de sulfates, ce produit est respectueux pour la peau et n''obstrue pas les pores. Sa formule riche en nutriments laisse tes cheveux brillants, lisses et éclatants de vie, ce qui en fait la solution parfaite pour une chevelure plus saine et plus résistante.', 50, 'ml', 'some-by-mi-cica-peptide-derma-scalp-treatment', 'https://korean-skincare.fr/products/some-by-mi-cica-peptide-derma-scalp-treatment', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-cica-peptide-derma-scalp-treatment.webp', 'Humidifie tes cheveux et ton cuir chevelu avec de l''eau tiède. Applique une quantité adéquate de produit et masse l''ensemble de ton cuir chevelu et de tes cheveux. Rince à l''eau tiède après 2 ou 3 minutes.', 974, '2026-05-07 17:37:40.642608+00', '2026-06-14 15:14:07.596+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4658-79dc-b16b-e166e292bd03', '__OWNER_ID__', 'Atobarrier 365 Body Lotion', 'AESTURA', 'body-lotion', 'bar', 'Aqua, Butylene Glycol, Glycerin, Propanediol, Pentaerythrityl Tetraethylhexanoate, Hydrogenated Poly(C6-14 Olefin), 1,2-Hexanediol, Phenyl Trimethicone, Bis-Hydroxyethoxypropyl Dimethicone, Synthetic Wax, C14-22 Alcohols, Plant Squalane, Cetearyl Alcohol, Hydroxypropyl Starch Phosphate, Xanthan Gum, Glyceryl Stearate, Hydrogenated Lecithin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, C12-20 Alkyl Glucoside, Acetyl Glucosamine, Stearic Acid, Glyceryl Stearate Citrate, Hydrogenated Vegetable Oil, Glyceryl Caprylate, Tromethamine, Panthenol, Polyglyceryl-10 Stearate, Palmitic Acid, Ethylhexylglycerin, Disodium EDTA, Gluconolactone, Polyglyceryl-3 Methylglucose Distearate, Carbomer, Thymol Trimethoxycinnamate, Cholesterol, Ceramide NP, Glucose, Oenothera Biennis Oil, Hydroxypropyl Bispalmitamide MEA, Mannitol, Myristic Acid, Lauric Acid, Tocopherol, Copernicia Cerifera Wax Extract, Acrylates/Ammonium Methacrylate Copolymer, Silica, Arachidic Acid, Caesalpinia Sappan Stem Powder, Oleic Acid', 'L''Atobarrier 365 Body Lotion AESTURA est une lotion hydratante quotidienne développée par des dermatologues, conçue pour renforcer et protéger les peaux sèches et sensibles. Grâce au Complexe Triple Lipid breveté de la marque, cette formule légère mais profondément nourrissante imite les lipides naturels de la barrière cutanée pour restaurer l’hydratation, réduire la sécheresse et améliorer la résilience globale de la peau. Elle pénètre rapidement sans effet collant, offrant une hydratation longue durée qui garde la peau confortable tout au long de la journée. Idéale pour les peaux sensibles, sujettes à l’eczéma ou facilement irritables, cette lotion corporelle apporte une hydratation 24 heures tout en renforçant la barrière cutanée contre les agressions extérieures. L''Atobarrier 365 Body Lotion AESTURA laisse ta peau douce, lisse et équilibrée, faisant d’elle un essentiel quotidien fiable pour toute la famille. Recommandé pour : Tous types de peaux.', 400, 'ml', 'aestura-atobarrier-365-body-lotion', 'https://korean-skincare.fr/products/aestura-atobarrier-365-body-lotion', 'https://aurore-cdn.b-cdn.net/products/aestura-atobarrier-365-body-lotion.webp', 'Applique une quantité appropriée sur peau propre et sèche et masse délicatement jusqu’à absorption complète. Utilise quotidiennement, surtout après la douche, pour une hydratation optimale.', 3595, '2026-05-07 17:37:40.952532+00', '2026-06-14 15:14:07.596+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
