INSERT INTO public.products VALUES ('019de0ab-6573-7f66-8157-84409298bd1c', '__OWNER_ID__', 'Eau Thermale Jonzac Nutritive ATO Huile Lavante Relipidante Bio 500ml', 'Eau Thermale Jonzac', 'body-wash', 'spray', 'AQUA/WATER/EAU : Eau thermale de Jonzac et eau purifiée GLYCERIN : Humectant retenant l''eau à la surface de la peau MALVA SYLVESTRIS (MALLOW) EXTRACT* : Eau florale de fleurs de Mauve bio reconnue apaisante PROPANEDIOL : Humectant retenant l''eau à la surface de la peau SODIUM COCOYL GLUTAMATE, Decyl Glucoside, Polyglyceryl-4 Caprate, SODIUM COCOAMPHOACETATE, LAURYL GLUCOSIDE : Agents lavants doux XANTHAN GUM, CHONDRUS CRISPUS (CARRAGEENAN) : Gélifiants COCOS NUCIFERA (COCONUT) OIL* : Huile de coco bio reconnue pour limiter le développement de certaines bactéries (S. aureus) ALPHA-GLUCAN OLIGOSACCHARIDE : Actif prébiotique reconnu protecteur du microbiome SODIUM PCA : Actif reconnu pour augmenter la synthèse des lipides épidermiques LACTIC ACID, Sodium Hydroxide, CITRIC ACID : Agents garantissant un pH adapté à la peau CAPRYLYL GLYCOL, SODIUM LEVULINATE, LEVULINIC ACID, SODIUM CHLORIDE : Stabilisants PARFUM (FRAGRANCE) : Composition parfumante haute tolérance 100% d''origine naturelle SODIUM BENZOATE : Conservateur4. Hydratation des couches supérieures de l''épiderme. * Ingrédients issus de l’agriculture biologique', '', 500, 'ml', 'eau-thermale-jonzac-nutritive-ato-huile-lavante-relipidante-bio-500ml-266677', 'https://www.atida.fr/eau-thermale-jonzac-nutritive-ap-huile-lavante-relipidante-bio-500ml.html', 'https://aurore-cdn.b-cdn.net/products/eau-thermale-jonzac-nutritive-ato-huile-lavante-relipidante-bio-500ml-266677.webp', '', 1179, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.599+00', 'bodycare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cc8-7a08-a699-ff9a778f4f12', '__OWNER_ID__', 'Blueberry Rebalancing 5.5 Cleanser', 'INNISFREE', 'cleanser', 'jar', 'Aqua, Glycerin, Sodium Cocoyl Isethionate, Hydroxypropyl Starch Phosphate, Diglycerin, Limonene, Potassium Benzoate, Sodium Methyl Cocoyl Taurate, Potassium Cocoyl Glycinate, Potassium Cocoate, Lavandula Angustifolia Oil, Butylene Glycol, Allantoin, Citric Acid, Linalool, Sodium Phytate, Citrus Aurantium Dulcis Peel Oil, 1,2-Hexanediol, Vaccinium Angustifolium Fruit Extract, Panthenol, Caprylic/Capric Triglyceride, Maltodextrin, Saccharide Hydrolysate, Propanediol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Polyquaternium-67, Euterpe Oleracea Fruit Extract, Rubus Idaeus Leaf Extract', 'Le nettoyant 5.5 rééquilibrant aux bleuets d''Innisfree est un nettoyant doux pour le visage qui aide à garder votre peau équilibrée et hydratée. Avec une formule légèrement acide, il nettoie sans enlever l''humidité, laissant votre peau fraîche et douce. Infusé d''extrait de myrtille et d''autres ingrédients naturels, il crée une mousse douce qui élimine la saleté et les impuretés tout en gardant la peau confortable et lisse. Parfait pour un usage quotidien, ce nettoyant aide à maintenir un teint sain et éclatant sans sensation de tiraillement ou de sécheresse après le lavage. Recommandé pour : Peaux normales à sèches.', 100, 'ml', 'innisfree-blueberry-rebalancing-5-5-cleanser', 'https://korean-skincare.fr/products/innisfree-blueberry-rebalancing-5-5-cleanser', 'https://aurore-cdn.b-cdn.net/products/innisfree-blueberry-rebalancing-5-5-cleanser.webp', 'Utilise le nettoyant matin et soir, après le démaquillage. Commence par humidifier tes mains et ton visage. Prend une petite quantité de nettoyant dans la main et fais-le mousser. Masse délicatement ton visage en évitant le contour des yeux et de la bouche. Rince à l''eau tiède.', 1495, '2026-05-07 17:37:38.504522+00', '2026-06-14 15:14:07.599+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3ce0-7476-a72b-3aa31d0ecf72', '__OWNER_ID__', 'SoonJung pH 6.5 Whip Cleanser', 'ETUDE', 'cleanser', 'jar', 'Aqua, Glycerin, Sorbitol, Propanediol, Lauryl Glucoside, Disodium Cocoyl Glutamate, Panthenol, Citric Acid, Glyceryl Caprylate, Ethylhexylglycerin, Madecassoside, Butylene Glycol, Tocopherol, Camellia Sinensis Leaf Extract', 'Le SoonJung pH 6.5 Whip Cleanser Etude House est une mousse nettoyante crémeuse à la texture fouettée qui maintient la peau hydratée et apaisée tout en la nettoyant. Formulé avec 98 % d''ingrédients d''origine naturelle, ce nettoyant doux utilise le madécassoside et le panthénol pour hydrater en profondeur et réparer les dommages. Avec une formule hypoallergénique simple est exempte d''irritants potentiels tels que des parfums synthétiques, des huiles minérales ou des parabènes, ce nettoyant est parfait pour tous les types de peau, en particulier les peaux sensibles. Recommandé pour : Tous types de peaux. Peut être utilisé pour : Tous types de peaux.', 150, 'ml', 'etude-house-soon-jung-whip-cleanser', 'https://korean-skincare.fr/products/etude-house-soon-jung-whip-cleanser', 'https://aurore-cdn.b-cdn.net/products/etude-house-soon-jung-whip-cleanser.webp', 'Mouille ton visage avec de l''eau. Dépose une quantité suffisante de Soon Jung Whip Cleanser sur tes mains et fais-le mousser. Masse délicatement le nettoyant sur ton visage, en évitant le contour des yeux, puis rince à l''eau. Utilise-le quotidiennement pour un nettoyage doux et rafraîchissant.', 1517, '2026-05-07 17:37:38.528154+00', '2026-06-14 15:14:07.599+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6512-7813-bfe1-ffd178a1d06c', '__OWNER_ID__', 'Garancia L''Appel de la Forêt Crème Lumière Eclat & Jeunesse 30ml', 'Garancia', 'moisturizer', 'jar', 'Aqua, Coco-Caprylate/Caprate, Glycerin, Cetearyl Alcohol, Microcrystalline Cellulose, Linum Usitatissimum Seed Oil, 1,2-Hexanediol, BRASSICA CAMPESTRIS (RAPESEED) SEED OIL*, POLYGONUM TINCTORIUM LEAF EXTRACT*, LIGUSTRUM LUCIDUM SEED EXTRACT*, PALMITOYL TETRAPEPTIDE-10, ACER RUBRUM EXTRACT*, Jojoba Esters, Helianthus Annuus Seed Wax, AGAR*, Acacia Senegal Gum, XANTHAN GUM*, LYSINE CARBOXYMETHYL CYSTEINATE*, Glyceryl Stearate, POLYGLYCERIN-3*, SODIUM STEAROYL GLUTAMATE*, Caprylyl Glycol, Parfum, Potassium Sorbate, Citric Acid', '', 30, 'ml', 'garancia-l-appel-de-la-foret-creme-lumiere-eclat-jeunesse-30ml-249794', 'https://www.atida.fr/garancia-l-appel-de-la-foret-creme-lumiere-eclat-jeunesse-30ml.html', 'https://aurore-cdn.b-cdn.net/products/garancia-l-appel-de-la-foret-creme-lumiere-eclat-jeunesse-30ml-249794.webp', '', 3132, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.605+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3fd4-7c8a-b2c5-3f1bfdb593c4', '__OWNER_ID__', 'Birch Juice Moisturizing Cleanser', 'ROUND LAB', 'cleanser', 'jar', 'Aqua, Glycerin, Sodium Cocoyl Alaninate, Lauryl Hydroxysultaine, Disodium Cocoamphodiacetate, Sodium Methyl Cocoyl Taurate, Acrylate/​C10-30 Alkyl Acrylate Crosspolymer, Betula Alba Juice(10,000 Ppm), Butylene Glycol, Sodium Hyaluronate, Hyaluronic Acid, Sodium Chloride, Glyceryl Glucoside, Ascorbic Acid, 1,2-Hexanediol, Artemisia Annua Extract, Anthemis Nobilis Flower Oil, Pinus Sylvestris Leaf Oil, Quillaja Saponaria Bark Extract, Caprylyl Glycol, Coco-Glucoside, Glyceryl Caprylate, Sodium Cocoyl Isethionate, Hexylene Glycol, Citric Acid, Disodium EDTA', 'Le Birch Juice Moisturizing Cleanser ROUND LAB est un nettoyant moussant doux et hydratant pour une peau propre et rebondie. Sa formule au pH équilibré permet de maximiser ses bienfaits pour la peau. De plus, il est formulé avec des ingrédients naturels incroyablement hydratants, profondément rafraîchissants et non irritants pour la peau, même pour les types de peau très réactifs.', 150, 'ml', 'round-lab-birch-juice-moisturizing-cleanser', 'https://korean-skincare.fr/products/round-lab-birch-juice-moisturizing-cleanser', 'https://aurore-cdn.b-cdn.net/products/round-lab-birch-juice-moisturizing-cleanser.webp', 'Distribue une petite quantité de produit et fais-le bien mousser. Masse délicatement l''ensemble de ton visage, puis rince abondamment à l''eau tiède.', 1195, '2026-05-07 17:37:39.2846+00', '2026-06-14 15:14:07.6+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64eb-7f0b-afb3-f5a5e3161752', '__OWNER_ID__', 'Ducray Ictyane Crème Émolliente Nutritive 400ml', 'Ducray', 'moisturizer', 'jar', 'Aqua, Glycerin, Paraffinum Liquidum, Glyceryl Stearate, peg-12, Isohexadecane, Microcrystalline Wax, Palmitic Acid, Stearic Acid, crambe abyssinica seed oil, Alpha-Isomethyl Ionone, Benzyl Salicylate, BHT, caffeine carboxylic acid, Caprylyl Glycol, Citronellol, Dimethicone, Ethylhexylglycerin, Parfum, Geraniol, Hydroxycitronellal, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Limonene, Linalool, Paraffin, Polysorbate 60, Sorbitan Isostearate, Tocopherol, Triethanolamine', '', 400, 'ml', 'ducray-ictyane-creme-emolliente-nutritive-400ml-275479', 'https://www.atida.fr/ducray-ictyane-creme-emolliente-nutritive-corps-400ml-7020838.html', 'https://aurore-cdn.b-cdn.net/products/ducray-ictyane-creme-emolliente-nutritive-400ml-275479.webp', '', 1647, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.6+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4118-7e93-978c-919d1fe7dd35', '__OWNER_ID__', 'Mighty Bamboo Panthenol Cleanser', 'Purito Seoul', 'cleanser', 'jar', 'Aqua, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Coco-Betaine, Sodium Chloride, Sodium Lauroyl Methyl Isethionate, Sodium Methyl Isethionate, Lauric Acid, Sodium Laurate, Hydroxyacetophenone, Ethylhexylglycerin, Disodium EDTA, Allantoin, Panthenol, Betaine, Tromethamine, 1,2-Hexanediol, Bambusa Vulgaris Extract, Melaleuca Alternifolia Leaf Oil', 'Le nettoyant Purito SEOUL Mighty Bamboo Panthenol Cleanser est un nettoyant doux pour le visage, au pH équilibré, qui élimine efficacement les impuretés sans décaper la peau. Infusé d''extrait de bambou, de panthénol (3 000 ppm) et d''allantoïne, il aide à hydrater, à apaiser et à soutenir la barrière cutanée tout en laissant la peau fraîche et souple. La formule gel douce mousse doucement, offrant un nettoyage rafraîchissant qui convient aussi bien le matin que le soir. L''ajout d''huile de feuilles d''arbre à thé et de bétaïne contribue à calmer et à nourrir la peau, ce qui en fait un produit idéal pour tous les types de peau, y compris les peaux sensibles. Recommandé pour : Tous les types de peau.', 150, 'ml', 'mighty-bamboo-panthenol-cleanser', 'https://korean-skincare.fr/products/mighty-bamboo-panthenol-cleanser', 'https://aurore-cdn.b-cdn.net/products/mighty-bamboo-panthenol-cleanser.webp', 'Utilise le nettoyant matin et soir, après le démaquillage. Commence par humidifier tes mains et ton visage. Prend une petite quantité de nettoyant dans la main et fais mousser. Masse délicatement ton visage en évitant le contour des yeux et de la bouche. Rince à l''eau tiède.', 1366, '2026-05-07 17:37:39.608802+00', '2026-06-14 15:14:07.601+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6508-7e18-973a-dbb43eb65aca', '__OWNER_ID__', 'ISDIN Isdinceutics Hyaluronic Moisture Normal Crème Hydratante Visage Anti-Âge 50g', 'ISDIN', 'moisturizer', 'jar', 'Aqua, C15-19 Alkane, Propanediol, Glycerin, Caprylic/Capric Triglyceride, Butylene Glycol, cellulose, sodium acrylates crosspolymer-2, Dimethicone, 1,2-Hexanediol, Panthenol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Caprylyl Glycol, Ammonium Acryloyldimethyltaurate/VP Copolymer, Tocopheryl Acetate, Trehalose, Urea, Parfum, Tocopherol, vigna aconitifolia seed extract, Dimethicone Crosspolymer, Citric Acid, Maltodextrin, Sodium Hyaluronate, tetrasodium glutamate diacetate, Hydrolyzed Hyaluronic Acid, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Pentylene Glycol, serine, Camellia Japonica Flower Extract, alteromonas ferment extract, Algin, disodium phosphate, glyceryl polyacrylate, Pullulan, Potassium Phosphate, CI 42090, CI 17200', '', 50, 'g', 'isdin-isdinceutics-hyaluronic-moisture-normal-creme-hydratante-visage-anti-age-50g-244669', 'https://www.atida.fr/isdin-isdinceutics-hyaluronic-moisture-normal-creme-hydratante-visage-anti-age-50g.html', 'https://aurore-cdn.b-cdn.net/products/isdin-isdinceutics-hyaluronic-moisture-normal-creme-hydratante-visage-anti-age-50g-244669.webp', '', 3699, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.601+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-415c-7011-851c-a2d2f3ce78bf', '__OWNER_ID__', 'Clear Code Superfruit Cleanser', 'Purito Seoul', 'cleanser', 'jar', 'Aqua, Glycerin, Butylene Glycol, Dipropylene Glycol, Coco-Betaine, Lauryl Hydroxysultaine, Disodium Cocoamphodiacetate, Sodium Chloride, Extrait de Fruit de Morinda Citrifolia, Sodium Methyl Cocoyl Taurate, Saccharomyces Ferment Filtrate, Extrait de Feuille de Cryptomeria Japonica, Extrait de Feuille de Nelumbo Nucifera, Sodium Lauroyl Methyl Isethionate, Salicylic Acid, Hydroxyacetophenone, Pentylene Glycol, Hexylene Glycol, Ethylhexylglycerin, Allantoin, Disodium EDTA, Trométamine, Extrait de Malachite, Coptis Chinensis Root Extract, Acide Gluconique, Pyrus Communis Fruit Extract, Rosa Damascena Flower Water, Prunus Persica Fruit Extract, Extrait de Feuille/Tige de Hedera Helix, Extrait de Fruit de Pimpinella Anisum, Extrait de Fruit de Vanilla Planifolia, Extrait de Fruit de Cucumis Melon, 1,2-Hexanediol, Caprylyl Glycol, Citric Acid', 'Le Clear Code Superfruit Cleanser Purito SEOUL est une solution clarifiante nouvelle génération conçue pour nettoyer en profondeur et rééquilibrer les peaux grasses et mixtes. Formulé avec de l''extrait de fruit de noni apaisant et de l''acide salicylique exfoliant, ce nettoyant vegan aide à réguler la production de sébum, à désincruster les pores obstrués et à détoxifier la peau sans la déshydrater. Sa formule douce au pH équilibré rééquilibre le microbiome de ta peau, la laissant rafraîchie, hydratée et apaisée après chaque lavage. Grâce à ses microbulles qui permettent un nettoyage en profondeur, il est idéal pour tous ceux qui cherchent à purifier leur peau tout en maintenant un ratio huile/eau idéal. Recommandé pour : Tous types de peaux.', 150, 'ml', 'purito-seoul-clear-code-superfruit-cleanser', 'https://korean-skincare.fr/products/purito-seoul-clear-code-superfruit-cleanser', 'https://aurore-cdn.b-cdn.net/products/purito-seoul-clear-code-superfruit-cleanser.webp', 'Masse délicatement 2 à 3 pompes de mousse nettoyante sur ton visage et ton cou, en évitant le contour des yeux et de la bouche. Rince abondamment à l''eau tiède.', 1748, '2026-05-07 17:37:39.675816+00', '2026-06-14 15:14:07.601+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-41b9-7501-92ae-348eec7ad54f', '__OWNER_ID__', 'Green Tea Fresh Cleanser', 'ISNTREE', 'cleanser', 'jar', 'Aqua, Glycerin, Alaninate De Sodium Cocoyl, Disodium Cocoamphodiacetate, Butylene Glycol, Taurate De Sodium Méthyl Cocoyl, 1,2-Hexanediol, Hydroxysultaine De Lauryl, Gomme Xanthane, Sodium Chloride, Caprylyl Glycol, Acrylates/C10-30 Alkylaacrylate Crosspolymer, Poudre De Feuille De Camellia Sinensis, Feuille De Camellia Sinensis, Camellia Sinensis Leaf Extract, Sodium Phytate, Extrait De Malt, Hexylene Glycol, Oenothera Biennis Flower Extract, Pinus Palustris Leaf Extract, Extrait De Racine De Pueraria Thunbergiana, Ulmus Davidiana Root Extract, Ethylhexylglycerin, Glycosaminoglycanes Hydrolysés, Propanediol, Sodium Hyaluronate Crosspolymer, Sodium Hyaluronate, Benzyl Glycol, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid', 'Profite d''un nettoyage revitalisant avec le Green Tea Fresh Cleanser Isntree, qui contient des extraits de thé vert nourrissants provenant de l''île de Jeju et de Boseong. Sa formule gel douce mais efficace exploite la puissance de quatre types d''acide hyaluronique pour capturer l''hydratation, garantissant un teint souple et hydraté après le nettoyage. Dis adieu à l''excès de sébum et aux impuretés grâce à ce nettoyant rafraîchissant qui purifie la peau sans provoquer de tiraillements ni de sécheresse. Infusé d''extraits botaniques naturels, dont de l''extrait de fleur d''onagre et de l''extrait de feuille de pin, il laisse à ta peau une sensation de fraîcheur et de jeunesse après chaque utilisation. Recommandé pour : Peaux sensibles, tous types de peaux.', 120, 'ml', 'isntree-green-tea-fresh-cleanser', 'https://korean-skincare.fr/products/isntree-green-tea-fresh-cleanser', 'https://aurore-cdn.b-cdn.net/products/isntree-green-tea-fresh-cleanser.webp', 'Applique une quantité adéquate de nettoyant sur ta peau mouillée. Masse en effectuant de légers mouvements circulaires. Rince à l''eau tiède.', 1922, '2026-05-07 17:37:39.76917+00', '2026-06-14 15:14:07.601+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6505-7265-8b6d-939a57aeeb66', '__OWNER_ID__', 'ISDIN Fotoprotector Transparent Spray Crème Solaire Corps SPF30 250ml', 'ISDIN', 'sunscreen', 'spray', 'Alcohol Denat, isobutane, dibutyl adipate, Dicaprylyl Ether, diisopropyl sebacate, Octocrylene, C15-19 Alkane, Ethylhexyl Salicylate, butyl metjoxydibenzoylmethane, Ethylhexyl Triazone, Aqua, acrylates/octylacrylamide copolymer, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, butane, butyloctyl salicylate, propane, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Tocopheryl Acetate, Parfum, Zingiber Officinale Root Extract', '', 250, 'ml', 'isdin-fotoprotector-transparent-spray-creme-solaire-corps-spf30-250ml-244637', 'https://www.atida.fr/isdin-fotoprotector-transparent-spray-creme-solaire-corps-spf30-250ml.html', 'https://aurore-cdn.b-cdn.net/products/isdin-fotoprotector-transparent-spray-creme-solaire-corps-spf30-250ml-244637.webp', '', 2061, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.602+00', 'solaire', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4249-7cff-b7ee-8043c2f7c8e5', '__OWNER_ID__', 'ACNE Facial Cleanser', 'Pyunkang Yul', 'cleanser', 'jar', 'Aqua, Cocamidopropyl Betaine, Methyl Oleoyl Taurate de Sodium, PEG-75, Copolymère d''Acrylates, Glycerin, Disodium Cocoamphodipropionate, PEG-120 Methyl Glucose Dioleate, Diméthyl Sulfone, Chlorhydrate de Pyridoxine, Salix Alba Bark Extract, Extrait de Fruit de Forsythia Suspensa, Butylene Glycol, Centella Asiatica Extract, Extrait de Racine de Polygonum Cuspidatum, Extrait de Racine de Scutellaria Baicalensis, Camellia Sinensis Leaf Extract, Glycyrrhiza Uralensis Root Extract, Chamomilla Recutita (Matricaria) Flower Extract, Rosmarinus Officinalis Leaf Extract, Sodium Chloride, Copper Tripeptide-1, Allantoin, Citric Acid, Potassium Hydroxide, Sodium Benzoate, Phenoxyethanol, Disodium EDTA', 'L''Acne Facial Cleanser Pyunkang Yul Acne nettoie efficacement la peau sans l''irriter. L''extrait d''écorce de saule blanc aide à exfolier les cellules mortes, tandis que l''extrait de fruit de Forsythia Suspensa et la Centella Asiatica calment les inflammations et revitalisent la peau. Convient aux personnes ayant une peau à tendance grasse, acnéique ou sensible. Recommandé pour : Peaux à tendance grasse ou acnéique. Peut être utilisé pour : Tous types de peaux.', 120, 'ml', 'acne-facial-cleanser', 'https://korean-skincare.fr/products/acne-facial-cleanser', 'https://aurore-cdn.b-cdn.net/products/acne-facial-cleanser.webp', 'Prélève une petite quantité de nettoyant et fais-le mousser. Masse sur l''ensemble du visage en effectuant de légers mouvements circulaires. Rince à l''eau tiède.', 778, '2026-05-07 17:37:39.913704+00', '2026-06-14 15:14:07.602+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42af-7aee-8812-2d037b59d8d2', '__OWNER_ID__', 'Calming Pore Clear Wash Off Pack', 'Pyunkang Yul', 'mask', 'jar', 'Aqua, Kaolin, Glycerin, Dipropylene Glycol, Montmorillonite, 1,2-Hexanediol, Bentonite, Héctorite, Illite, Poudre de Feuille de Camellia Sinensis, Copolymère d’Acrylate d’Hydroxyéthyle/Taurate d’Acryloyldiméthyle de Sodium, Citric Acid, Sodium Citrate, Melaleuca Alternifolia Leaf Extract, Salix Alba Bark Extract, Melia Azadirachta Leaf Extract, Butylene Glycol, Ethylhexylglycerin, Disodium EDTA, Sorbitan Isostearate, Extrait de Fleur de Melia Azadirachta, Gluconolactone, Extrait Fermenté de Lactobacillus/Soja, Glutamate de Sodium, Myristate de Polyglycéryl-10, Hydroxyacetophenone, Pentylene Glycol, Caprylyl Glycol, Extrait d’Artemisia Capillaris, Centella Asiatica Extract, Sodium Hyaluronate, Lonicera Japonica Flower Extract, Caprylic/Capric Triglyceride, Cetyl Ethylhexanoate, Ethylhexyl Palmitate, Extrait de Racine de Nardostachys Chinensis, Hydrolyzed Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Polymère Croisé d’Hyaluronate de Sodium, Sodium Acetyl Hyaluronate, Madecassoside, Acide Madécassique, Asiaticoside, Acide Asiatique', 'Retrouve et une peau plus lisse et nette instantanément grâce au Calming Pore Clear Wash Off Pack Pyunkang Yul. Ce masque à la fois délicat et efficace est formulé avec 11 000 ppm d''extraits d''armoise et de haricot mungo pour nettoyer les pores en profondeur et éliminer les impuretés, laissant ta peau rafraîchie et visiblement plus douce. Enrichi d''extraits apaisants de Centella Asiatica, d''arbre à thé et de fleurs de Lonicera Japonica, ce masque calme les peaux irritées et sensibles tout en contrôlant l''excès de sébum et en procurant une hydratation optimale. Sa formule crème douce, enrichie en AHA et PHA, exfolie délicatement, révélant un teint plus sain et plus éclatant. Recommandé pour : Peaux sèches, peaux à tendance acnéique, tous types de peaux.', 100, 'g', 'pyunkang-yul-calming-pore-clear-wash-off-pack', 'https://korean-skincare.fr/products/pyunkang-yul-calming-pore-clear-wash-off-pack', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-calming-pore-clear-wash-off-pack.webp', 'Après avoir lavé ton visage, prélève une quantité appropriée de produit et applique une couche sur ton visage sec. Rince délicatement à l''eau tiède après 10~15 minutes.', 1945, '2026-05-07 17:37:40.015489+00', '2026-06-14 15:14:07.602+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-650a-76aa-9e60-e93d844bb33b', '__OWNER_ID__', 'Garancia Pschitt Magique Nouvelle Peau Visage Micropeeling Sans Grain Edition Limitée Psychédélique 100ml', 'Garancia', 'exfoliant', 'tube', 'Aqua, Glycerin, Coco-Glucoside, Citrus Limon Fruit Extract, Rosa Damascena Flower Water, centaurea cyanus flower water*, Hamamelis Virginiana Water, Caprylyl/Capryl Glucoside, lactobacillus*, Propylene Glycol, Camellia Sinensis Leaf Water, Cucumis Sativus Fruit Extract, cocos nucifera (coconut) fruit extract*, Bacillus Ferment, papain*, Algin, Potassium Sorbate, Citric Acid, Parfum, Carbomer, 1,2-Hexanediol, caprylyl glycol *origine naturelle / natural origin 98% d’ingrédients d’origine naturelle', '', 100, 'ml', 'garancia-pschitt-magique-nouvelle-peau-visage-micropeeling-sans-grain-edition-limitee-psychedelique-100ml-248660', 'https://www.atida.fr/garancia-pschitt-magique-100ml.html', 'https://aurore-cdn.b-cdn.net/products/garancia-pschitt-magique-nouvelle-peau-visage-micropeeling-sans-grain-edition-limitee-psychedelique-100ml-248660.webp', '', 2799, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.602+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-438e-7e1b-a6bc-ef504170ad90', '__OWNER_ID__', 'Fig Enzyme Powder Cleanser', 'I''m From', 'cleanser', 'jar', 'Zea Mays Corn Starch, Sodium Cocoyl Isethionate, Sodium Lauroyl Glutamate, Hydrolyzed Hyaluronic Acid, Ficus Carica Fig Fruit Water, Aspergillus Ferment, Triticum Aestivum Wheat Seed Extract, Ficus Carica Fig Fruit Extract, Sodium Myristoyl Glutamate, Allantoin, Papain, Glycerin, Mandelic Acid, Maltodextrin, Aqua, 1,2-Hexanediol, Lipase, Protease, Ficin, Parfum', 'Le Fig Enzyme Powder Cleanser I''m From est un nettoyant visage en poudre qui se transforme en mousse, conçu pour exfolier, purifier et illuminer ton teint en douceur. Formulé avec 1,2 % d''extrait de figue et d''enzymes de papaïne, ce nettoyant élimine efficacement les cellules mortes, les impuretés et l''excès de sébum sans agresser la peau. Idéale pour tous les types de peaux, en particulier les peaux sensibles et à tendance acnéique, cette formule à faible pH aide à maintenir la barrière naturelle de la peau tout en offrant un fini lisse, rafraîchi et éclatant. Il suffit d''ajouter de l''eau pour activer la poudre ultra-fine et obtenir une mousse douce qui nettoie en profondeur et améliore visiblement la texture de la peau. Ce produit de soin coréen, facile à transporter, est parfait pour le nettoyage quotidien ou l''exfoliation hebdomadaire, offrant une solution douce mais efficace pour les peaux ternes, congestionnées ou irrégulières. Recommandé pour : Tous types de peaux.', 50, 'g', 'im-from-fig-enzyme-powder-cleanser', 'https://korean-skincare.fr/products/im-from-fig-enzyme-powder-cleanser', 'https://aurore-cdn.b-cdn.net/products/im-from-fig-enzyme-powder-cleanser.webp', 'Verse une petite quantité de poudre (environ la taille d''une pièce de monnaie) dans la paume de ta main. Ajoute quelques gouttes d''eau tiède et frotte tes mains pour créer une mousse douce. Masse doucement la mousse sur ton visage humide en faisant des mouvements circulaires, en évitant le contour des yeux. Rince bien à l''eau tiède et continue avec ton tonique, ton sérum et ta crème hydratante. Conseil : Pour une exfoliation plus profonde, laisse la mousse agir sur ta peau pendant 30 à 60 secondes avant de rincer. Tu peux aussi la mélanger avec quelques gouttes de ton tonique préféré au lieu de l''eau pour un effet apaisant supplémentaire.', 2295, '2026-05-07 17:37:40.238703+00', '2026-06-14 15:14:07.602+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43f6-7b7f-875d-1c401bb957cd', '__OWNER_ID__', 'Pro Balance Night Enzyme Wash', 'Dr. Ceuracle', 'cleanser', 'jar', 'Zea Mays Starch, Sodium Cocoyl Isethionate, Sodium Lauroyl Glutamate, Diglycérine, Sodium Palmitate, Citric Acid, Poudre de Charbon, Allantoin, Huile d’Orange Citrus Aurantium Dulcis, Huile de Zeste de Mandarine Citrus Nobilis, Huile de Fruit Litsea Cubeba, Aqua, Butylene Glycol, Protéase, Lactobacillus Ferment, 1,2-Hexanediol, Extrait de Graines d’Amaranthus Caudatus, Ulmus Davidiana Root Extract, Caprylyl Glycol, Filtrat de Ferment Bifida, Lysat de Ferment Bifida, Lysat de Ferment Lactobacillus, Lysat de Ferment Lactococcus, Filtrat de Ferment Saccharomyces, Tropolone, Limonene *Ingrédients contenant AHA', 'Réveille ta peau éclatante et fraîche avec le Pro Balance Night Enzyme Wash Dr.Ceuracle, un nettoyant doux mais puissant qui passe de la poudre à la mousse, conçu pour agir pendant ton sommeil. Formulé avec des enzymes d’origine naturelle et le Pro Balance Biotics Complex™ signature de la marque, ce nettoyant exfoliant nocturne aide à éliminer les cellules mortes, l’excès de sébum et les impuretés quotidiennes sans perturber la barrière hydrolipidique naturelle de la peau. Idéal même pour les peaux les plus sensibles, la poudre ultra-fine s’active au contact de l’eau pour créer une mousse douce et crémeuse, laissant le teint plus lisse, plus clair et parfaitement préparé pour la réparation nocturne. Infusé avec un mélange de probiotiques, prébiotiques et enzymes végétales, ce nettoyant innovant soutient le microbiome cutané, favorisant un teint sain et équilibré. Son action exfoliante douce aide à désobstruer les pores et à affiner la texture sans irritation, faisant de ce produit le rituel parfait pour les peaux ternes ou congestionnées. Que tu te détendes après une longue journée ou que tu profites de ta routine de soins du soir, le Pro Balance Night Enzyme Wash offre une expérience nettoyante luxueuse, efficace et apaisante, pour dormir en toute sérénité, sachant que ta peau est entre de bonnes mains. Recommandé pour : Tous types de peaux.', 50, 'g', 'dr-ceuracle-pro-balance-night-enzyme-wash', 'https://korean-skincare.fr/products/dr-ceuracle-pro-balance-night-enzyme-wash', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-pro-balance-night-enzyme-wash.webp', 'Dispense une petite quantité de poudre et ajoute de l’eau pour créer une mousse. Masse délicatement sur ton visage humide, puis rince abondamment. Utilise le soir avant d’appliquer ton tonique et ta crème hydratante. À utiliser quotidiennement ou selon la sensibilité de ta peau.', 2195, '2026-05-07 17:37:40.342667+00', '2026-06-14 15:14:07.602+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6555-7c4f-9ded-de179a3c61fa', '__OWNER_ID__', 'Klorane Lait d''Avoine Shampoing Sec Extra-Doux 50g', 'Klorane', 'shampoo', 'bottle', 'Butane, propane, Oryza Sativa Starch, isobutane, Alcohol, aluminum starch octenyl succinate, avena sativa (oat), kernel oil (avena sativa kernel oil), Benzyl Salicylate, Cetrimonium Chloride, Cyclodextrin, Parfum, Hexyl Cinnamal, Isopropyl Myristate, Limonene, Silica', '', 50, 'g', 'klorane-lait-d-avoine-shampoing-sec-extra-doux-50g-276170', 'https://www.atida.fr/klorane-shampooing-sec-avoine-rotopoudre-50g.html', 'https://aurore-cdn.b-cdn.net/products/klorane-lait-d-avoine-shampoing-sec-extra-doux-50g-276170.webp', '', 856, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.603+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4479-716b-a164-b2e385a28744', '__OWNER_ID__', 'Rose Hyaluronic Hydra Wash Off Pack', 'Mary&May', 'mask', 'jar', 'Aqua, Diglycérol, Glycerin, Kaolin, Bentonite, Propylene Glycol, Zea Mays Starch, 1,2-Hexanediol, Rosa Damascena Flower Water, Panthenol, Poudre de Fleur de Rosa Gallica, Gomme Xanthan, Copolymère d''Acrylamide/Sodium Acryloyldimethyltaurate, Polyisobutene, Betaine, Butylene Glycol, Parfum, Ethylhexylglycerin, Dipropylene Glycol, CI 77491, CI 77491, Disodium EDTA, Glucoside de Caprylyl, Oleate de Sorbitan, Allantoin, Hydrogenated Lecithin, Centella Asiatica Extract, Ficus Carica Fruit Extract, Ceramide NP, Sodium Hyaluronate, Tocopherol, Hyaluronic Acid, Polymère Croisé de Sodium Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Sodium Acetyl Hyaluronate', 'Améliore ta routine beauté avec le Rose Hyaluronic Hydra Wash-Off Pack MARY & MAY, un luxueux masque à l''argile vegan conçu pour imprégner ta peau de l''essence naturelle de roses françaises. Ce masque hydratant combine des pétales de roses françaises fraîches et des extraits de roses de Damas dans une formule riche à base d''eau qui offre une hydratation et une vitalité inégalées. Enrichi d''un mélange d''argile glaciaire canadienne, d''argile blanche d''Amazonie, d''argile rose française et d''argile volcanique, il nettoie efficacement les pores et absorbe l''excès de sébum, laissant ta peau lisse et nette. Sa texture crémeuse s''étale sans effort, offrant une hydratation profonde sans aucune sensation grasse, et se rince facilement à l''eau, garantissant que ta peau reste douce et rafraîchie. Recommandé pour : Soin des pores, peaux sèches, tous types de peaux.', 125, 'g', 'mary-may-rose-hyaluronic-hydra-wash-off-pack', 'https://korean-skincare.fr/products/mary-may-rose-hyaluronic-hydra-wash-off-pack', 'https://aurore-cdn.b-cdn.net/products/mary-may-rose-hyaluronic-hydra-wash-off-pack.webp', 'Après avoir lavé ton visage, étale le produit délicatement sur l''ensemble de ton visage sec, à l''exception du contour des yeux et de la bouche. Masse délicatement en fonction de l''état de ta peau. Après 10 à 15 minutes, lorsque le masque a séché, rince-le délicatement à l''eau tiède. *Prélève une quantité suffisante de produit et applique-le en couche épaisse pour que l''hydratation et les principes actifs du masque à l''argile puissent être efficacement absorbés.', 2052, '2026-05-07 17:37:40.472992+00', '2026-06-14 15:14:07.603+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4506-7de2-a61d-851a1c083392', '__OWNER_ID__', 'Yuja Niacin Brightening All-In-One Cleanser', 'SOME BY MI', 'cleanser', 'jar', 'Aqua, Sodium C14-16 Olefin Sulfonate, Citrus Junos Fruit Extract, Cocamidopropyl Betaine, Copolymère d''Acrylates, 1,2-Hexanediol, Gluconolactone, Tétradécène, Sodium Chloride, Glycerin, Hexadécène, Isomérate de Saccharide, Caprylyl Glycol, Gomme Xanthane, Sodium Citrate, Citric Acid, Niacinamide, Propanediol, Sodium Hyaluronate, 3-O-Ethyl Ascorbic Acid, Acide Succinique, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Extrait de Feuille d''Eriobotrya Japonica, Hydrogenated Lecithin, Glycosaminoglycanes Hydrolysées, Stéarate de Polyglycéryl-10, Panthenol, Extrait de Mentha Viridis, Sodium Acetyl Hyaluronate, Benzyl Glycol, Sodium Ascorbyl Phosphate, Ethylhexylglycerin, Biotin, Pyridoxine, Acide Folique, Hyaluronic Acid, Cétone de Framboise, Tocopherol, Cyanocobalamin, Acide Linoléique, Chlorhydrate de Thiamine, Inositol, Riboflavine, Bêta-Carotène, Disodium EDTA, Parfum, Limonene, Linalool', 'Revitalise ta peau avec le Yuja Niacin Brightening All-In-One Cleanser SOME BY MI, un petit bijou de soin polyvalent enrichi de 11 % d''extrait de yuja et de niacinamide. Ce nettoyant tout-en-un va au-delà du simple nettoyage, en incorporant de l''acide succinique pour exfolier délicatement et de l''acide hyaluronique pour réguler la production de sébum et maintenir un niveau d''hydratation optimal, prévenant ainsi les poussées d''acné. Sa texture gel se transforme en une mousse dense, assurant un nettoyage profond et minutieux, laissant ta peau avec un fini lisse, radieux et d''apparence plus saine. Recommandé pour : Peaux sèches, tous types de peaux.', 100, 'ml', 'some-by-mi-yuja-niacin-brightening-all-in-one-cleanser-1', 'https://korean-skincare.fr/products/some-by-mi-yuja-niacin-brightening-all-in-one-cleanser-1', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-yuja-niacin-brightening-all-in-one-cleanser-1.webp', 'En utilisant une petite quantité d''eau, fais mousser et masse délicatement ta peau, en évitant l''intérieur des yeux. Rince abondamment à l''eau tiède.', 1704, '2026-05-07 17:37:40.61468+00', '2026-06-14 15:14:07.603+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-47c4-7a21-871c-f4c7461ed219', '__OWNER_ID__', 'All Day Vitamin Clean & Mild Facial Cleanser', 'JUMISO', 'cleanser', 'jar', 'Aqua, Cocamidopropyl Betaine, Glycerin, Acrylates Copolymer, 1,2-Hexanediol, Tromethamine, Sodium Chloride, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Citrus Paradisi Peel Oil, Salicylic Acid, Ascorbic Acid, Chlorhexidine Digluconate, Coptis Japonica Root Extract, Hippophae Rhamnoides Extract, Limonene', 'Ce nettoyant pour le visage à faible pH de JUMISO est parfait pour les personnes ayant une peau à problèmes ! Il contient de l''acide salicylique pour dissoudre le sébum et les impuretés, tandis que les vitamines et l''extrait de baies de mer et de pamplemousse hydratent la peau. Une combinaison optimale pour une peau équilibrée ! Conseils d''application : Prélève une quantité suffisante de produit dans ta main. Mélange avec de l''eau et fais mousser. Masse délicatement la mousse sur ton visage. Rince avec de l''eau tiède.', 150, 'ml', 'jumiso-all-day-vitamin-clean-mild-facial-cleanser', 'https://korean-skincare.fr/products/jumiso-all-day-vitamin-clean-mild-facial-cleanser', 'https://aurore-cdn.b-cdn.net/products/jumiso-all-day-vitamin-clean-mild-facial-cleanser.webp', NULL, 1995, '2026-05-07 17:37:41.316528+00', '2026-06-14 15:14:07.603+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44c1-7e10-b805-747a2a5d855c', '__OWNER_ID__', 'Cica Tea Tree Soothing Wash Off Pack', 'Mary&May', 'mask', 'jar', 'Aqua, Kaolin, Bentonite, Illite, 1,2-Hexanediol, Glycerin, Niacinamide, Diheptanoate de Glycol Néopentyle, Dipropylene Glycol, Betaine, Propanediol, Poudre de Zeste de Citrus Limon, Polyacrylate-13, Gomme Xanthan, Montmorillonite, Acide 2-O-Éthyl Ascorbique, Ethylhexylglycerin, Magnesium Aluminum Silicate, Hydrogenated Polyisobutene, Parfum, Laurate de Polyglycéryle-10, Disodium EDTA, Ethylhexyl Palmitate, Sorbitan Isostearate, Butylene Glycol, Quartz, Gluconolactone, Prunus Persica Fruit Extract, Citric Acid, Tocopherol', 'Transforme ta routine beauté avec le Cica Tea Tree Soothing Wash Off Pack MARY & MAY, un masque à l''argile de première qualité conçu pour offrir des résultats dignes d''un institut de beauté depuis le confort de ta maison. Formulé avec un puissant mélange d''argiles kaolin et bentonite, ce masque absorbe efficacement l''excès d''huile, les impuretés et le sébum, laissant tes pores propres et ta peau lisse après une seule utilisation. Infusé d''ingrédients naturels apaisants comme la Centella Asiatica, l''extrait d''arbre à thé et la calamine, ce masque calme la peau irritée tout en maintenant l''hydratation, grâce à sa texture douce et crémeuse qui se rince facilement sans dessécher la peau. Recommandé pour : Peaux sèches, tous types de peaux.', 125, 'g', 'mary-may-cica-tea-tree-soothing-wash-off-pack', 'https://korean-skincare.fr/products/mary-may-cica-tea-tree-soothing-wash-off-pack', 'https://aurore-cdn.b-cdn.net/products/mary-may-cica-tea-tree-soothing-wash-off-pack.webp', 'Après t''être lavé le visage, étale délicatement sur l''ensemble de ton visage sec, en évitant le contour des yeux et de la bouche. Masse délicatement en fonction de l''état de ta peau. Après 10 à 15 minutes, lorsque le masque a séché, rince-le délicatement à l''eau tiède. *Prélève une quantité suffisante de produit et applique-le en couche épaisse pour que l''hydratation et les principes actifs du masque puissent être efficacement absorbés.', 2248, '2026-05-07 17:37:40.545786+00', '2026-06-14 15:14:07.603+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
