INSERT INTO public.products VALUES ('019e0384-3c7d-7cea-94c2-975b6ee29c08', '__OWNER_ID__', 'Hanbang Serum Discovery Kit', 'Beauty of Joseon', 'serum', 'dropper', 'Calming : Eau de Feuille de Camellia Sinensis, Aqua, Methylpropanediol, Glycerin, Butylene Glycol, Centella Asiatica Extract, Panthenol, Pentylene Glycol, 1,2-Hexanediol, Chondrus Crispus Extract, Saccharum Officinarum Extract, Extrait d''Artemisia Vulgaris, Melia Azadirachta Leaf Extract, Sodium Hyaluronate, Extrait de Fleur de Melia Azadirachta, Theobroma Cacao Seed Extract, Extrait de Propolis, Succinate de Diethoxyethyl, Betaine, Octanediol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Allantoin, Sodium Polyacryloyldimethyl Taurate, Tromethamine, Ethylhexylglycerin, Dipotassium Glycyrrhizate, Polyquaternium-51, Copolymère d''Acrylate de Glycéryle/Acide Acrylique, Sodium Phytate, Dextrin, Tocophérol. Glow : Extrait de Propolis, Dipropylene Glycol, Glycerin, Butylene Glycol, Aqua, Niacinamide, 1,2-Hexanediol, Extrait de Fleur de Melia Azadirachta, Melia Azadirachta Leaf Extract, Sodium Hyaluronate, Curcuma Longa Root Extract, Ocimum Sanctum Leaf Extract, Theobroma Cacao Seed Extract, Melaleuca Alternifolia Leaf Extract, Centella Asiatica Extract, Extrait de Corallina Officinalis, Extrait de Graine de Lotus Corniculatus, Huile de Graine de Calophyllum Inophyllum, Salicylate de Bétaïne, Sodium Polyacryloyldimethyl Taurate, Tromethamine, Laurate de Polyglycéryl-10, Caprylyl Glycol, Ethylhexylglycerin, Dextrin, Pentylene Glycol, Octanediol, Tocopherol, Gomme Xanthane, Carbomère. Glow Deep : Eau de Son d''Oryza Sativa (Riz), Aqua, Glycerin, Butylene Glycol, 1,2-Hexanediol, Dipropylene Glycol, Alpha-Arbutine, Niacinamide, Methyl Gluceth-20, Panthenol, Polyglycérine-3, Trehalose, Glucoside de Glycéryle, Esters Hydrolysés de Jojoba, Copolymère d''Acrylate d''Hydroxyéthyle/Taurate d''Acryloyldiméthyle de Sodium, Ethylhexylglycerin, Hydroxyéthylcellulose, Gomme Xanthane, Arginine, Acrylates/C10-30 Alkyl Acrylate