INSERT INTO public.products VALUES ('019e0384-4150-7cd9-9501-4d69b9943c3b', '__OWNER_ID__', 'Azelaic Acid 10 Kojic Tea Tree Serum', 'Purito Seoul', 'serum', 'dropper', 'Aqua, Azelaic Acid, Melaleuca Alternifolia Leaf Water, Butylene Glycol, Caprylic/Capric Triglyceride, Hydroxypropyl Cyclodextrin, Disodium Phosphate, 1,2-Hexanediol, Glycerin, Niacinamide, Maltodextrin, Hydroxyethylcellulose, Coptis Japonica Root Extract, Agar, Gellan Gum, Kojic Acid, Ethylhexylglycerin, Idebenone, Adenosine, Trisodium Ethylenediamine Disuccinate, Malachite Extract, Melaleuca Alternifolia Leaf Oil, Arginine, Xanthan Gum, Tocopherol, Glutathione, Bisabolol, Helianthus Annuus Seed Oil, Xanthophylls', 'L''Azelaic Acid 10 Kojic Tea Tree Serum Purito Seoul est un soin multi-correcteur qui cible les imperfections, les décolorations et la texture irrégulière grâce à un mélange doux mais efficace d’ingrédients affinant la peau. Enrichi en acide azélaïque, acide kojique et guaiazulène, ce sérum léger aide à atténuer les taches, contrôler l’excès de sébum et apaiser l’inflammation, tout en favorisant un teint plus uniforme et éclatant. Il est idéal pour celles et ceux confrontés aux marques post-acné, au teint terne ou à la sensibilité. La formule est conçue pour être puissante mais non irritante, ce qui la rend adaptée même aux personnes débutant avec les actifs. Une utilisation régulière aide à affiner les pores, illuminer le teint et réduire les rougeurs, laissant la peau visiblement plus lisse et équilibrée. Recommandé pour : Peaux à tendance acnéique, peaux ternes, tous types de peaux.', 30, 'ml', 'purito-seoulazelaic-acid-10-kojic-tea-tree-serum', 'https://korean-skincare.fr/products/purito-seoulazelaic-acid-10-kojic-tea-tree-serum', 'https://aurore-cdn.b-cdn.net/products/purito-seoulazelaic-acid-10-kojic-tea-tree-serum.webp', 'Après le nettoyage et l’application d’un tonique, applique une petite quantité uniformément sur ton visage. Utilise dans ta routine du soir, ou le matin avec une protection solaire. Introduis progressivement et évite de l’utiliser avec d’autres acides ou exfoliants puissants le même jour.', 2195, '2026-05-07 17:37:39.664605+00', '2026-06-14 15:14:07.615+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
