INSERT INTO public.products VALUES ('019e0384-3fb3-76af-857a-7a886007afa2', '__OWNER_ID__', 'Pig Nose Clear Black Head 3 Step Kit', 'Holika Holika', 'moisturizer', 'jar', 'Étape 1 : Eau, Hamamelis Virginiana Water, Butylene Glycol, Salvia Officinalis Leaf Extract, Extrait de Feuille de Melissa Officinalis, Extrait de Racine d''Arctium Majus, Extrait de Feuille de Mentha Piperita (Menthe Poivrée), Extrait de Fruit de Juniperus Communis, Hypericum Perforatum Extract, Extrait de Racine de Saponaria Officinalis, Extrait de Fleur de Chrysanthemum Indicum, Camellia Sinensis Leaf Extract, Rosmarinus Officinalis Leaf Extract, Extrait de Feuille de Aspalathus Linearis, Extrait de Fleur/Feuille de Thymus Vulgaris (Thym), Extrait de Jasminum Officinale (Jasmin), Extrait de Acer Saccharum (Érable à Sucre), Extrait de Fruit/Citronelle de Citrus Aurantium Dulcis (Orange), Extrait de Fruit/Feuille de Vaccinium Myrtillus, Saccharum Officinarum Extract, Extrait de Citrus Medica Limonum (Citron), Aloe Barbadensis Leaf Juice, Caprylyl Glycol, 1,2-Hexanediol, Propanediol, Extrait de Fruit d''Illicium Verum (Anis), Parfum. Étape 2 : Eau, PVP, Copolymère de Copolyol de Diméthicone, Kaolin, Titanium Dioxide, Copolymère VP/VA, Propylene Glycol, Méthylparabène, Citrus Limon Fruit Extract, Aloe Barbadensis Leaf Juice, CI 17200. Étape 3 : Eau, Glycerin, Propanediol, Sodium Hyaluronate, Érythritol, Trehalose, Hydroxyéthylcellulose, Citrus Limon Fruit Extract, Dipotassium Glycyrrhizate, Extrait de Fruit d''Illicium Verum (Anis étoilé), Aloe Barbadensis Leaf Juice, Extrait de Fruit de Citrus Aurantifolia (Citron vert), Extrait de Feuille de Diospyros Kaki, Vitis Vinifera Fruit Extract, Caprylyl Glycol, 1,2-Hexanediol, Huile de Ricin Hydrogénée PEG-60, Chlorphenesin, Phenoxyethanol, Disodium EDTA, Parfum', 'Le Pig Nose Clear Black Head 3 Step Kit Holika Holika est un kit qui permet de traiter les pores encombrés en 3 étapes. Ces patchs pour le nez éliminent les points noirs en douceur et en toute sécurité. Ce kit commence par ouvrir les pores, puis éliminer les impuretés qui s''y trouvent, et enfin refermer les pores pour un résultat optimal et une prévention future.', NULL, NULL, 'holika-holika-pig-nose-clear-black-head-3-step-kit', 'https://korean-skincare.fr/products/holika-holika-pig-nose-clear-black-head-3-step-kit', 'https://aurore-cdn.b-cdn.net/products/holika-holika-pig-nose-clear-black-head-3-step-kit.webp', 'Étape 1 Après le nettoyage, place l''étape 1 sur ton nez pendant 15 à 20 minutes. Retire-le lentement et essuie les points noirs ou les impuretés qui se trouvent dans tes pores. Étape 2 Mouille ton nez avec de l''eau et place l''étape 2 sur ton nez. Au bout de 10 à 15 minutes, retire-le lentement en commençant par un bord. Étape 3 Après les étapes 1 et 2, place l''étape 3 sur ton nez. Retire-le après 10-15 minutes et tapote délicatement pour une meilleure absorption.', 295, '2026-05-07 17:37:39.251223+00', '2026-06-14 15:14:07.698+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
