INSERT INTO public.products VALUES ('019e0384-3cea-7fe4-9183-9d5e084ea670', '__OWNER_ID__', 'SoonJung Panthensoside Sheet Mask', 'ETUDE', 'mask', 'pack', 'Aqua, Dipropylene Glycol, 1,2-Hexanediol, Panthenol, Madecassoside, Extrait de Feuille de Centella Asiatica, Carbomer, Laurate de Polyglycéryl-10, Glycerin, Myristate de Polyglycéryl-10, Allantoin, Arginine, Trehalose, Ethylhexylglycerin, Disodium EDTA', 'Le SoonJung Panthensoside Sheet Mask Etude House est un masque tissu 100 % bambou rempli d''ingrédients apaisants et hydratants. Tout comme les autres produits Soon Jung, ce masque tient la promesse 9-free, c''est-à-dire qu''il est exempt des 9 irritants cutanés les plus courants tels que les parfums synthétiques, les parabènes et les tensioactifs. Il est idéal pour les peaux sensibles car il contient du madécassoside pour calmer la peau, du panthénol pour la réparer et de la glycérine pour l''hydrater.', 1, 'pcs', 'soon-jung-panthensoside-sheet-mask', 'https://korean-skincare.fr/products/soon-jung-panthensoside-sheet-mask', 'https://aurore-cdn.b-cdn.net/products/soon-jung-panthensoside-sheet-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 250, '2026-05-07 17:37:38.53874+00', '2026-06-14 15:14:07.629+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
