INSERT INTO public.products VALUES ('019de0ab-6545-7232-82ea-81f9f9f1ab28', '__OWNER_ID__', 'Dercos Densi-Solutions Baume Épaisseur', 'Vichy', 'hair-serum', 'tube', 'Aqua, Aqua, HYDROXYPROPYL STARCH PHOSPHATE, Glycerin, QUATERNIUM-87, Stearyl Alcohol, Behentrimonium Chloride, Euphorbia Cerifera Cera, Euphorbia Cerifera Cera, Caprylyl Glycol, CETYL ESTERS, Geraniol, Hexyl Cinnamal, Isononyl Isononanoate, ISOPROPYL ALCOHOL, Limonene, Linalool, Mentha Piperita Oil, Mentha Piperita Oil, Menthol, 2-OLEAMIDO-1,3-OCTADECANEDIOL, Phenoxyethanol, Propylene Glycol, Rhamnose, Sodium Hydroxide, Tocopheryl Acetate, Parfum, Parfum', 'Ce baume épaisseur après-shampooing purifie le cuir chevelu et agit sur les longueurs pour augmenter le volume et retrouver une chevelure plus forte, plus épaisse, comme régénérée. A prix discount dans votre parapharmacie en ligne.
