INSERT INTO public.products VALUES ('019e0384-431c-7665-a517-8ac3b8808046', '__OWNER_ID__', 'Black Rice Facial Oil', 'Haruharu Wonder', 'oil', 'dropper', 'Huile de Son de Riz (Oryza Sativa), Helianthus Annuus Seed Oil, Caprylic/Capric Triglyceride, Trioléine, Simmondsia Chinensis Seed Oil, Heptyl Undécylénate, Huile de Graines de Camélia, Huile d''Amande Douce (Prunus Amygdalus Dulcis), Tocopherol, Dioleate de Glycéryle, Lavandula Angustifolia Oil', 'La Haruharu WONDER Black Rice Facial Oil est une huile légère, parfaitement équilibrée, idéale pour toute l''année, même l''été. Cette huile à absorption étonnamment rapide est composée de cinq huiles naturelles dérivées de plantes. Son ingrédient phare est l''huile de son de riz noir, qui représente 45 % de la formule. Le riz noir contient une forte concentration de polyphénols et de flavonoïdes, qui protègent la peau contre les radicaux libres, notamment les rayons ultraviolets et la pollution, et favorisent la croissance de nouvelles cellules cutanées. Les huiles de jojoba, d''amande douce, de graines de tournesol et de lavande renforcent la protection de la peau, favorisent son élasticité et apaisent les irritations. Cette huile très polyvalente peut être utilisée seule ou mélangée à une crème, une essence ou un fond de teint pour obtenir un effet bonne mine.', 30, 'ml', 'haruharu-wonder-black-rice-facial-oil', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-facial-oil', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-facial-oil.webp', 'Applique 1 à 3 gouttes sur ta peau et masse doucement en tapotant jusqu''à absorption complète.', 1826, '2026-05-07 17:37:40.124245+00', '2026-06-14 15:14:07.63+00', 'skincare', '[]', 'huile', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
