INSERT INTO public.products VALUES ('019de0ab-6561-74fb-a22f-d722e0f806e3', '__OWNER_ID__', 'Sensitive Professional Bain de Bouche', 'Elmex', 'mouthwash', 'bottle', 'Aqua, Glycerin, Sorbitol, Propylene Glycol, DISODIUM PYROPHOSPHATE, PEG-40 HYDROGENATED CASTOR OIL, PVM/MA COPOLYMER, TETRAPOTASSIUM PYROPHOSPHATE, SODIUM LEVULINATE, SODIUM ANISATE, AMINE FLUORIDE (OLAFLUR) (125PPM F⁻), Parfum, Potassium Hydroxide, SODIUM SACCHARINE, Sodium Fluoride, CI19140, CI 42051', 'Le bain de bouche ELMEX Sensitive Professional, un bain de bouche qui s’utilise au quotidien et complète le brossage habituels des dents pour renforcer l’émail des dents et lutter contre la sensibilité dentaire.
INSERT INTO public.products VALUES ('019e0384-3bf1-7127-a2d6-35d8eeaebef4', '__OWNER_ID__', 'Acne Pimple Master Patches', 'COSRX', 'patch', 'pack', 'Résine de Pétrole, Cellulose Gum, Copolymère Séquencé de Styrène-Isoprène-Styrène, Film de Polyuréthane, Polyisobutylène, Paraffine Liquide, Tétrakisméthane', 'Ces patchs discrets et efficaces sont spécialement formulés pour cibler et traiter les poussées d''acné pendant la nuit. Composés d''un mélange d''ingrédients de pointe, dont la résine de pétrole, la gomme de cellulose et le film de polyuréthane, ces patchs créent une barrière protectrice qui contribue à réduire les rougeurs et l''inflammation et à accélérer la cicatrisation. Il te suffit d''appliquer un patch sur le bouton à traiter et tu te réveilleras le lendemain avec une peau nette et purifiée. Découvre le potentiel libérateur des patchs Acne Pimple Master et retrouve confiance en toi grâce à un teint zéro défaut. Recommandés pour : Peaux à tendance grasse et acnéique. Peut être utilise pour : Tous types de peaux.', 24, 'pcs', 'cosrx-acne-pimple-master-patches', 'https://korean-skincare.fr/products/cosrx-acne-pimple-master-patches', 'https://aurore-cdn.b-cdn.net/products/cosrx-acne-pimple-master-patches.webp', 'Nettoie la zone autour du bouton à traiter. Choisis un patch de taille supérieure à celle de l''imperfection à traiter. Place le patch sur la zone à traiter.', 392, '2026-05-07 17:37:38.288664+00', '2026-06-14 15:14:07.631+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6561-7bfe-b8c8-575b0a0020f2', '__OWNER_ID__', 'Dentifrice Sensitive Professionnel Blancheur', 'Elmex', 'toothpaste', 'tube', 'Calcium Carbonate, Aqua, Sorbitol, BICARBONATE, Sodium Lauryl Sulfate, SODIUM MONOFLUOROPHOSPHATE, Cellulose Gum, Sodium Bicarbonate, TETRASODIUM PYROPHOSPHATE, SODIUM SACCHARIN, Benzyl Alcohol, XANTHAN GUM, Limonene, Titanium Dioxide', 'ELMEX DENTIFRICE SENSITIVE PROFESSIONNEL BLANCHEUR LOT DE 2X75ML en vente en ligne sur le site de votre parapharmacie à prix discount est le produit qu''il vous faut pour des dents blanches et une protection efficace contre la sensibilité dentaire. Ce dentifrice est spécialement conçu pour les dents sensibles et offre une protection professionnelle contre les caries tout en révélant la blancheur naturelle des dents en douceur.
INSERT INTO public.products VALUES ('019de0ab-6562-70a3-9591-cf3df5edb484', '__OWNER_ID__', 'Sensitive Dentifrice Repare & Previent', 'Elmex', 'toothpaste', 'tube', 'Calcium Carbonate, Aqua, Sorbitol, Glycerin, Parfum, POLOXAMER 407, SODIUM MONOFLUOROPHOSPHATE, Cocamidopropyl Betaine, Zinc Oxide, Benzyl Alcohol, Cellulose Gum, TETRASODIUM PYROPHOSPHATE, ZINC CITRATE, Sodium Bicarbonate, XANTHAN GUM, SODIUM SACCHARIN, SUCRALOSE, ANETHOLE, BETA-CARYOPHYLLENE, Eucalyptus Globulus Leaf Oil, Limonene, Mentha Piperita Oil, Menthol, PINENE', 'ELMEX SENSITIVE DENTIFRICE REPARE & PREVIENT 75ML est en vente en ligne sur le site de votre parapharmacie à prix discount, offrant une protection quotidienne pour les dents et gencives sensibles.
