INSERT INTO public.products VALUES ('019de0ab-6581-7fb9-971f-77f8eddb7b33', '__OWNER_ID__', 'Sunissime Huile SPF30 + Gelee Apres Soleil', 'Lierac', 'after-sun', 'tube', 'Aqua, Glycerin, ISOSTEARYL ISOSTEARATE, Propanediol, ISOPENTYLDIOL, Ammonium Acryloyldimethyltaurate/VP Copolymer, 1,2-Hexanediol, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Parfum, Ethylhexylglycerin, Chlorphenesin, Citric Acid, Sorbitan Isostearate, Pentylene Glycol, Hamamelis Virginiana Leaf Extract, PORPHYRIDIUM CRUENTUM EXTRACT, Caprylyl Glycol, XANTHAN GUM, Geraniol, GERANYL ACETATE, 4205A', 'LIERAC SUNISSIME HUILE SOYEUSE SOLAIRE SPF30 150ML + GELEE FRAICHE APRES SOLEIL 75ML OFFERTE est en vente en ligne sur le site de votre parapharmacie à prix discount, offrant une protection solaire pour le corps avec un soin après-soleil rafraîchissant.
INSERT INTO public.products VALUES ('019e0384-3c24-79a7-a3fb-2823ca917a2a', '__OWNER_ID__', 'Refresh AHA BHA Vitamin C Daily Toner', 'COSRX', 'toner', 'pump', 'Actinidia Chinensis (Extrait de Fruit de Kiwi), Extrait de Fruit de Hylocereus Undatus, Eau d''Écorce de Salix Alba (Saule Blanc), Eau de Fruit de Pyrus Malus (Pomme), Butylene Glycol, Niacinamide, 1,2-Hexanediol, Éthyl Hexanediol, Sodium Lactate, Aqua, Glycolic Acid, Allantoin, Panthenol, Adenosine, Bétaïne Salicylate, Ascorbyl Glucoside', 'Le Refresh ABC Daily Toner COSRX est un tonique revitalisant quotidien qui contient de l''AHA, de l''AHA et de la vitamine C pour exfolier légèrement la peau. Il est fabriqué avec seulement 16 ingrédients essentiels, dont le COMPLEXE GOLDEN-RX breveté, de l''AHA, du BHA et de la vitamine C pour améliorer la texture de la peau et lui donner un teint plus éclatant et plus raffiné. Ce tonique possède une texture aqueuse légère qui est immédiatement absorbée par la peau, la laissant douce, lisse et prête à recevoir le reste des produits de ta routine beauté.', 150, 'ml', 'refresh-aha-bha-vitaminc-daily-toner', 'https://korean-skincare.fr/products/refresh-aha-bha-vitaminc-daily-toner', 'https://aurore-cdn.b-cdn.net/products/refresh-aha-bha-vitaminc-daily-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 1266, '2026-05-07 17:37:38.340371+00', '2026-06-14 15:14:07.634+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-651a-7898-a28c-efe4aea64d16', '__OWNER_ID__', 'Dermabsolu Soin Regard Combleur', 'Avène', 'eye-cream', 'tube', 'Aqua, Paraffinum Liquidum, Caprylic/Capric Triglyceride, Isohexadecane, Glyceryl Stearate, PEG-100 Stearate, Glycerin, Dimethicone, METHYL GLUCETH-20, PROPYLENE GLYCOL ALGINATE, Bakuchiol, Simmondsia Chinensis Seed Oil, 1,2-Hexanediol, Caprylyl Glycol, Carbomer, Dimethicone Crosspolymer, Disodium EDTA, GLYCERYL LINOLEATE, GLYCERYL LINOLENATE, Glyceryl Oleate, GLYCERYL PALMITATE, Glycine Soja Oil, PEG-30 DIPOLYHYDROXYSTEARATE, Propylene Glycol, SODIUM DEXTRAN SULFATE, Sodium Hydroxide, Sorbitol, Tocopherol, Tocopheryl Glucoside, VANILLA TAHITENSIS FRUIT EXTRACT, Aqua', 'AVENE DERMABSOLU SOIN REGARD COMBLEUR 15ML : Découvrez ce soin innovant en vente en ligne, sur le site de votre parapharmacie à prix discount, pour un regard visiblement rajeuni et revitalisé.
INSERT INTO public.products VALUES ('019de0ab-64f3-73d9-890c-a4183fcdd0e1', '__OWNER_ID__', 'Triple Hyaluronic Moisturizing Cleanser', 'COSRX', 'cleanser', 'tube', '1,2-Hexanediol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Arachidic Acid, Butylene Glycol, Citric Acid, Coco-Glucoside, Disodium EDTA, Ethylhexylglycerin, Parfum, Glycerin, Glyceryl Stearate, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Lauric Acid, Myristic Acid, Oleic Acid, Palmitic Acid, Panthenol, POLYQUATERNIUM-7, POTASSIUM COCOYL GLYCINATE, Potassium Hydroxide, QUILLAJA SAPONARIA BARK EXTRACT, Sodium Benzoate, Sodium Hyaluronate, Sodium Cocoyl Isethionate, Stearic Acid, Aqua', 'Nettoyant moussant triple acide hyaluronique, nettoie sans dessécher la peau.', 150, 'ml', 'cosrx-triple-hyaluronic-moisturizing-cleanser', 'https://www.skinsafeproducts.com/cosrx-triple-hyaluronic-moisturizing-cleanser-5-07-fl-oz-150ml', 'https://aurore-cdn.b-cdn.net/products/cosrx-triple-hyaluronic-moisturizing-cleanser.webp', 'Formule douce adaptée à toutes peaux, y compris peaux sèches.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.632+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3d15-702e-bffe-dc2da325753a', '__OWNER_ID__', 'SoonJung 10-Panthensoside Cica Balm', 'ETUDE', 'balm', 'jar', 'Aqua, Propanediol, Panthenol, Squalane, Cetearyl Alcohol, 1,2-Hexanediol, Diisostearyl Malate, Polyglyceryl-10 Stearate, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Tromethamine, Glyceryl Stearate, Cetearyl Glucoside, Stearic Acid, Hydrogenated Lecithin, Polyglyceryl-3 Methylglucose Distearate, Disodium EDTA, Sorbitan Isostearate, Madecassoside, Butylene Glycol, Glucose, Camellia Sinensis Leaf Extract', 'Le SoonJung 10-Panthensoside Cica Balm Etude House apaise, hydrate en profondeur et soulage les peaux irritées. Formulé avec 92% d''ingrédients d''origine naturelle, ce baume innovant utilise le madécassoside et le panthénol pour hydrater et réparer la peau en profondeur. Grâce à sa formule hypoallergénique simple et exempte d''irritants tels que des parfums synthétiques, des huiles minérales ou des parabènes, ce baume est parfait pour tous les types de peau, en particulier pour les bébés à la peau sensible.', 50, 'ml', 'etude-house-soonjung-10-panthensoside-cica-balm', 'https://korean-skincare.fr/products/etude-house-soonjung-10-panthensoside-cica-balm', 'https://aurore-cdn.b-cdn.net/products/etude-house-soonjung-10-panthensoside-cica-balm.webp', 'Applique une quantité suffisante sur ta peau. Tapote délicatement pour faciliter l''absorption.', 2095, '2026-05-07 17:37:38.580791+00', '2026-06-14 15:14:07.633+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42d1-7b68-bd2d-bae90db7b0bc', '__OWNER_ID__', 'Ato Panthenol Ceramide Balm Cream', 'Pyunkang Yul', 'balm', 'jar', 'Lonicera Japonica Flower Extract, Glycol Butylique, Bis-Diglyceryl Polyacyladipate-2, Triméthicone Phényl Diphénylsiloxy, Cetyl Ethylhexanoate, Méthicone Caprylyle, Glycereth-26, Diheptanoate de Glycol Néopentyle, 1,2-Hexanediol, Oleate de Polyglycéryl-4, Aqua, Oleate de Polyglycéryl-6, Tetraéthylhexanoate de Pentaérythritol, Panthenol, Polyhydroxystearic Acid, Disteardimonium Hectorite, Sorbitol, Sodium Chloride, Cetyl Palmitate, Diisostéarate/Sebacate/Polyhydroxystéarate de Polyglycéryl-4, Diéthyl Sébacate, Caprylic/Capric Triglyceride, Oleate de Polyglycéryl-3, Ceramide EOP, Triisostéaroyl Dimer Dilinoleate de Polyglycéryl-3, Tocopherol, Gomme Xanthane, Disodium EDTA, Myristate de Polyglycéryl-10, Hydroxyacétylphénone, Pentylene Glycol, Caprylyl Glycol, Ethylhexyl Palmitate, Extrait de Mentha Viridis, Extrait de Melissa Officinalis, Calendula Officinalis Flower Extract, Glycerin, Dipropylene Glycol, Glycérine Éthylhexyle', 'Profite d''une nutrition et d''une hydratation profondes avec l''Ato Panthenol Ceramide Balm Cream Pyunkang Yul. Ce baume ultra-nourrissant est infusé de 10 000 ppm de panthénol et de 1 000 ppm de céramide, créant une puissante barrière protectrice qui renforce et hydrate ta peau. Formulé avec 56,5 % d''extrait de fleur de chèvrefeuille, il offre des effets apaisants tandis que ses ingrédients de grade écologique vérifiés par l''EWG garantissent un soin délicat pour les peaux sensibles. Idéal pour ceux qui recherchent une hydratation intense et un renforcement de la barrière cutanée. Recommandé pour : Peaux déshydratées, peaux sensibles, peaux sèches, tous types de peaux.', 30, 'ml', 'pyunkang-yul-ato-panthenol-ceramide-balm-cream', 'https://korean-skincare.fr/products/pyunkang-yul-ato-panthenol-ceramide-balm-cream', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-ato-panthenol-ceramide-balm-cream.webp', 'Prélève une quantité appropriée de produit et étale délicatement sur ta peau lors de la dernière étape de ta routine beauté, en évitant le contour des yeux et de la bouche.', 1855, '2026-05-07 17:37:40.049438+00', '2026-06-14 15:14:07.633+00', 'skincare', '[]', 'baume', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c91-72a8-8dd0-e93ad1c4694b', '__OWNER_ID__', 'Cica Sleeping Mask', 'LANEIGE', 'mask', 'pack', 'Aqua, Propanediol, Cétéaryl Éthylhexanoate, Squalane, Oléfine Polyhydrogénée C6-14, Glycerin, Panthenol, Cetearyl Alcohol, Butyrospermum Parkii Butter, Citrate de Glyceryl Stéarate, 1,2-Hexanediol, Distearate de Polyglyceryl-3 Méthylglucose, Stéarate de Polyglyceryl-10, Copolymère d’Hydroxyéthylacrylate/Acrylate de Sodium Diméthyltaurate, Butylene Glycol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Glyceryl Caprylate, Ethylhexylglycerin, Disodium EDTA, Asiaticoside, Acide Madécassique, Sorbitan Isostearate, Acide Asiatique, Melaleuca Alternifolia Leaf Oil, Ferment d’Aureobasidium Pullulans, Extrait de Feuille de Chamaecyparis Obtusa, Huile de Cymbopogon Martini, Tocopherol', 'Le Cica Sleeping Mask LANEIGE est un masque qui renforce la barrière protectrice de la peau et la guérit pendant la nuit. Ce masque contient une puissante levure forestière cica qui aide la peau à se rétablir pendant que tu dors. Cet ingrédient a montré un taux de régénération de la peau impressionnant de 111,9 %, encore plus efficace que le madécassoside. Réveille-toi avec une peau apaisée, saine et heureuse !', 60, 'ml', 'laneige-cica-sleeping-mask', 'https://korean-skincare.fr/products/laneige-cica-sleeping-mask', 'https://aurore-cdn.b-cdn.net/products/laneige-cica-sleeping-mask.webp', 'Avant d''aller au lit, étale délicatement une quantité appropriée de masque sur le bout de ton nez, tes joues, ton front et ton menton. Laisse agir toute la nuit. Rince le matin.', 2845, '2026-05-07 17:37:38.449084+00', '2026-06-14 15:14:07.634+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-45d9-749b-9676-cd7b5b99d654', '__OWNER_ID__', 'No.3 Pore Reset Ampoule Shot', 'Numbuzin', 'serum', 'dropper', 'Aqua, Methylpropanediol, Niacinamide, Diméthicone/Vinyl Diméthicone Crosspolymère, Glycerin, HDI/PPG/Polycaprolactone Crosspolymère, 1,2-Hexanediol, Pentylene Glycol, Lecithin, Chondrus Crispus Extract, Saccharum Officinarum Extract, Extrait de Fève de Cacao, Glycine Soja Oil, Extrait de Fleur de Melia Azadirachta, Ocimum Sanctum Leaf Extract, Melia Azadirachta Leaf Extract, Curcuma Longa Root Extract, Extrait de Corallina Officinalis, Pullulane, Polyacrylate Crosspolymer-6, Panthenol, Silybine, Tocopherol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Caprylyl Glycol, Dextrin, Tromethamine, Ethylhexylglycerin, Adenosine, Silica, Sodium Phytate, Retinol, Sodium Dilauramidoglutamide Lysine, Isocéteth-10, Isocéteth-25, Caprylic/Capric Triglyceride, Cholesterol, Ubiquinone, Zinc PCA, Phospholipides, Ceramide NP, Arginine, Phytostérols, BHT, Phenoxyethanol', 'La No.3 Pore Reset Ampoule Shot Numbuzin est ton arme secrète pour traiter les pores dilatés et la peau à problèmes tout en obtenant un teint plus uniforme. Cette puissante ampoule, parfaite pour une utilisation de nuit, est formulée avec un mélange d''ingrédients puissants pour revitaliser ta peau. Le rétinol, la silybine et l''adénosine travaillent en harmonie pour améliorer l''élasticité de la peau et lui donner une apparence plus ferme et plus jeune. La niacinamide, l''un des ingrédients les plus populaires en matière de soins de la peau, occupe le devant de la scène dans cette formule, offrant un soin éclaircissant qui aide à estomper les imperfections et le teint inégal de la peau. Ce qui distingue l''ampoule Numbuzin, c''est son intégration d''ingrédients naturels tels que l''extrait de racine de curcuma et l''extrait de feuille de basilic sacré. Ces extraits de plantes extraordinaires ont des effets apaisants et anti-inflammatoires, ce qui permet d''atténuer les rougeurs et de calmer la peau irritée. En appliquant cette ampoule luxueuse, tu pourras ressentir les effets apaisants de ces ingrédients botaniques, laissant à ta peau une sensation de fraîcheur et de régénération. La volonté de qualité de Numbuzin est évidente à travers les ingrédients soigneusement sélectionnés qui composent cette ampoule innovante, garantissant que ta peau reçoive les soins qu''elle mérite. Incorpore la No.3 Pore Reset Ampoule Shot Numbuzin n°3 à ta routine beauté de nuit et observe une transformation remarquable de la texture de ta peau et de son teint en général. Dis adieu aux pores dilatés et bonjour à un teint radieux et rajeuni à chaque application. Recommandé pour : Tous types de peaux.', 40, 'ml', 'no-3-pore-reset-ampoule-shot', 'https://korean-skincare.fr/products/no-3-pore-reset-ampoule-shot', 'https://aurore-cdn.b-cdn.net/products/no-3-pore-reset-ampoule-shot.webp', 'Après avoir appliqué un tonique, étale une petite quantité de produit sur les zones où les pores sont visibles et tapote délicatement pour faire pénétrer dans ta peau. À utiliser uniquement pendant ta routine de nuit. *Contient des ingrédients sensibles à la lumière et à la chaleur, à n''utiliser que la nuit, et il est préférable de conserver ce produit au réfrigérateur. *Lors de la première utilisation, commence par une petite quantité et utilise ensuite le produit tous les 2 ou 3 jours, si aucune irritation n''est ressentie, augmente lentement la quantité et la période d''utilisation.', 2495, '2026-05-07 17:37:40.825142+00', '2026-06-14 15:14:07.633+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64f2-7d82-b1cd-c765a6ddb7aa', '__OWNER_ID__', 'REMEDY for dry lips', 'Remedy Science', 'lip-care', 'tube', 'Petrolatum, Hydroxystearic/Linolenic/Oleic Polyglycerides, Helianthus Annuus Seed Wax, Sucrose Acetate Isobutyrate, C18-38 Alkyl Hydroxystearoyl Stearate, Dimethicone, Ethylhexyl Palmitate, Butyrospermum Parkii Butter, C12-15 Alkyl Benzoate, Capryloyl Glycerin/Sebacic Acid Copolymer, Diheptyl Succinate, Tribehenin, Squalane, Sorbitan Isostearate, Ceramide NP, Helianthus Annuus Seed Oil, Persea Gratissima Oil, Simmondsia Chinensis Seed Oil, Ascorbyl Tetraisopalmitate, Tocopheryl Acetate, Palmitoyl Tripeptide-1, Aloe Barbadensis Leaf Extract, Chamomilla Recutita (Matricaria) Flower Extract, Lactic Acid', 'A lip treatment that does triple duty as an all-in-one peptide treatment, hydrating mask, and sealing ointment — helps repair dry lips and lock in moisture.', 10, 'ml', 'remedy-dry-lips', 'https://remedyskin.com/products/dry-lips', 'https://aurore-cdn.b-cdn.net/products/remedy-dry-lips.webp', 'Formule anhydre (base Petrolatum). Hero: Ceramides, Squalane, Palmitoyl Tripeptide-1, Petrolatum, Dimethicone, Shea Butter', 1795, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.633+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-41e1-70d1-b333-be49fa066679', '__OWNER_ID__', 'Onion Newpair Spot Patch Basic', 'ISNTREE', 'patch', 'pack', 'Polyisobutene, Cellulose Gum, Aqua, Butylene Glycol, Niacinamide, 1,2-Hexanediol, Extrait de Bulbe d''Allium Cepa', 'Combats tes problèmes de peau avec l''Onion Newpair Spot Patch Basic Isntree, un patch hydrocolloïde contre l''acné conçu pour s''attaquer aux imperfections et les traiter efficacement. Infusé d''extrait d''oignon Muan et de niacinamide, ce patch protège non seulement la zone affectée mais calme également l''inflammation de la peau, accélérant ainsi le processus de guérison. Sa formulation, qui comprend des ingrédients comme le butylène glycol, vise à adoucir la texture irrégulière de la peau. Adapté aux peaux à tendance acnéique, ce patch anti-acné a subi des tests d''irritation cutanée, garantissant une solution à la fois douce et puissante pour toutes les personnes qui souhaitent combattre leurs imperfections. Incorpore ce patch à ta routine beauté pour bénéficier de soins ciblés que ta peau mérite. Recommandé pour : Sans risques pour l''acné fongique, peaux sensibles, tous types de peaux.', 24, 'pcs', 'isntree-onion-newpair-spot-patch-basic', 'https://korean-skincare.fr/products/isntree-onion-newpair-spot-patch-basic', 'https://aurore-cdn.b-cdn.net/products/isntree-onion-newpair-spot-patch-basic.webp', 'Lave-toi soigneusement le visage avec un nettoyant. Colle le patch sur ta peau sèche avant de procéder à ta routine beauté. Au bout de 8 à 10 heures, le patch deviendra blanc après avoir absorbé le pus et les impuretés. Lorsqu''il devient blanc, enlève-le délicatement. Remplace-le ensuite par un nouveau.', 495, '2026-05-07 17:37:39.808932+00', '2026-06-14 15:14:07.633+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c16-7426-8c39-b3f63ab3494d', '__OWNER_ID__', 'Full Fit Propolis Light Ampoule', 'COSRX', 'serum', 'dropper', 'Extrait de Propolis, Butylene Glycol, Glycerin, Betaine, 1,2-Hexanediol, Extrait de Graine de Cassia Obtusifolia, Sodium Hyaluronate, Hydroxyéthylcellulose, Carbomer, Panthenol, Arginine', 'La Full Fit Propolis Light Ampule COSRX contient 83,25 % de propolis noire - un ingrédient antibactérien et anti-inflammatoire naturel. Cette ampoule aide à guérir les peaux stressées et à réduire les rougeurs. Cette ampoule a été développée en mettant l''accent sur l''amélioration de la texture de la peau, et même avec sa concentration élevée de propolis et sa texture visqueuse, elle fait office d''une excellente base de maquillage et ne donne pas l''impression d''être huileuse ou grasse. La présence de nutriments concentrés dans l''ampoule aide à renforcer la barrière cutanée et à retenir l''hydratation, ce qui donne à la peau un éclat sain et radieux et la laisse lisse et hydratée toute la journée.', 30, 'ml', 'cosrx-full-fit-propolis-light-ampoule-1', 'https://korean-skincare.fr/products/cosrx-full-fit-propolis-light-ampoule-1', 'https://aurore-cdn.b-cdn.net/products/cosrx-full-fit-propolis-light-ampoule-1.webp', 'Applique uniformément après avoir nettoyé ton visage et utilisé un tonique. Masse délicatement et tapote sur l''ensemble de ton visage pour une absorption rapide. Passe à l''étape de l''hydratation.', 1996, '2026-05-07 17:37:38.326181+00', '2026-06-14 15:14:07.633+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4281-73c8-8bd7-cce8e4041b36', '__OWNER_ID__', 'Calming Clear Spot Patch (Intensive Care)', 'Pyunkang Yul', 'patch', 'pack', 'Cellulose Gum, Polyoléfine C6-20 Hydrogénée, Polyisobutene, Copolymère de Styrène/Isoprène, Salicylic Acid, Melaleuca Alternifolia Leaf Oil, Houttuynia Cordata Extract, Niacinamide, Centella Asiatica Extract', 'Cible et apaise les imperfections gênantes avec les Pyunkang Yul Calming Clear Spot Patchs (Intensive Care). Ces patchs hydrocolloïdes de 0,2 mm sont conçus pour couvrir et apaiser les imperfections plus importantes, en procurant un effet calmant intense tout en absorbant efficacement les impuretés et le pus. Formulés avec trois puissants ingrédients apaisants pour la peau - la Centella Asiatica, l''huile d''arbre à thé et l''extrait d''Houttuynia Cordata - ces patchs aident à réduire l''irritation et protègent contre les germes extérieurs. Idéaux pour tous les types de peau, ils offrent une barrière protectrice discrète qui favorise une guérison plus rapide et une peau plus nette. Recommandé pour : Peaux à tendance acnéique, sans risque pour l''acné fongique, tous types de peaux.', 165, 'pcs', 'pyunkang-yul-calming-clear-spot-patch-intensive-care', 'https://korean-skincare.fr/products/pyunkang-yul-calming-clear-spot-patch-intensive-care', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-calming-clear-spot-patch-intensive-care.webp', 'Applique sur peau propre et appuie pendant 2 à 3 secondes pour favoriser une meilleure adhérence. Retire le patch lorsqu''il devient blanc après absorption du pus.', 1464, '2026-05-07 17:37:39.969032+00', '2026-06-14 15:14:07.634+00', 'skincare', '[]', 'patch', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44c6-71a2-bec8-fcca2b5a384f', '__OWNER_ID__', 'AHA BHA PHA Body Toner Mist', 'SOME BY MI', 'mist', 'spray', 'Aqua, Butylene Glycol, Glycerin, Niacinamide, 1,2-Hexanediol, Polyglyceryl-10 Laurate, Erythritol, Sodium Citrate, Citric Acid, Gluconolactone, Ethylhexylglycerin, Methyl Diisopropyl Propionamide, Succinic Acid, Adenosine, Ammonium Acryloyldimethyltaurate/VP Copolymer, Disodium EDTA, Mentha Piperita Oil, Bambusa Vulgaris Leaf Extract, Chamaecyparis Obtusa Leaf Extract, Pinus Densiflora Leaf Extract, Thuja Orientalis Extract, Camellia Sinensis Leaf Extract, Diospyros Kaki Leaf Extract, Cryptomeria Japonica Leaf Extract, Foeniculum Vulgare Seed Extract, Gardenia Florida Fruit Extract, Rosmarinus Officinalis Leaf Extract, Tilia Cordata Flower Extract, Centella Asiatica Extract, Moringa Oleifera Seed Extract, Artemisia Capillaris Extract, Melaleuca Alternifolia Leaf Extract, Salicylic Acid, Leucine, Alanine, Aspartic Acid, Isoleucine, Phenylalanine, Arginine, Glutamic Acid, Glycine, Histidine, Methionine, Ornithine, Proline, Serine, Taurine, Valine, Dimethyl Sulfone, Zinc PCA, Asiaticoside, Madecassoside, Asiatic Acid, Madecassic Acid, Menthol', 'L''AHA BHA PHA Body Toner Mist SOME BY MI est un soin corporel clarifiant conçu pour cibler les boutons, la texture rugueuse et les pores obstrués du corps. Formulé avec un puissant mélange d’AHA, BHA et PHA, ce spray léger exfolie délicatement les cellules mortes, élimine l’excès de sébum et aide à garder les pores dégagés. Le format pratique en spray permet une application facile sur les zones difficiles à atteindre comme le dos et les épaules. Enrichi en ingrédients botaniques apaisants, l''AHA BHA PHA Body Toner Mist SOME BY MI aide à calmer les rougeurs tout en maintenant l’hydratation de la peau. Avec une utilisation régulière, il améliore la texture générale de la peau, réduit les imperfections corporelles et favorise un teint plus lisse et visiblement plus clair. Recommandé pour : Tous types de peaux.', 140, 'ml', 'some-by-mi-aha-bha-pha-body-toner-mist', 'https://korean-skincare.fr/products/some-by-mi-aha-bha-pha-body-toner-mist', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-aha-bha-pha-body-toner-mist.webp', 'Vaporise uniformément sur peau propre sur les zones sujettes aux boutons ou à la rugosité comme le dos, la poitrine ou les bras. Laisse-le pénétrer complètement. Utilise-le quotidiennement après la douche.', 1317, '2026-05-07 17:37:40.549992+00', '2026-06-14 15:14:07.635+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4094-711f-8b4c-e5bbcea09105', '__OWNER_ID__', 'Madagascar Centella Tone Brightening Boosting Toner', 'SKIN1004', 'toner', 'pump', 'Aqua, 1,2-Hexanediol, Niacinamide, Pentylene Glycol, Butylene Glycol, Glycerin, Propanediol, Centella Asiatica Extract, Gomme Xanthane, Panthenol, Allantoin, Betaine, Ethylhexylglycerin, Xylitylglucoside, Anhydroxylitol, Disodium EDTA, Xylitol, Madecassoside, Glucose, Carica Papaya Fruit Extract, Pyrus Malus Fruit Extract, Extrait de Fruit de Prunus Mume, Vitis Vinifera Fruit Extract, 3-O-Ethyl Ascorbic Acid, Caprylic/Capric Triglyceride', 'Le Madagascar Centella Tone Brightening Boosting Toner SKIN1004 est un tonique fonctionnant en duo qui aide à reconstituer l''hydratation et à améliorer le tonus de la peau. Il est doté de l''ingrédient breveté MadeWhite™ extrait de la Centella Asiatica de Madagascar pour un résultat éclaircissant pour la peau. Sa texture aqueuse et sa faible acidité laissent ta peau souple, revitalisée et éclatante de jeunesse.', 210, 'ml', 'skin1004-centella-tone-brightening-boosting-toner', 'https://korean-skincare.fr/products/skin1004-centella-tone-brightening-boosting-toner', 'https://aurore-cdn.b-cdn.net/products/skin1004-centella-tone-brightening-boosting-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 1320, '2026-05-07 17:37:39.475835+00', '2026-06-14 15:14:07.635+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c79-753e-b466-3201f864d274', '__OWNER_ID__', 'Green Plum Refreshing Toner: AHA + BHA', 'Beauty of Joseon', 'toner', 'pump', 'Aqua, Eau De Fruit De Prunus Mume, Dipropylene Glycol, 1,2-Hexanediol, Tromethamine, Glycolic Acid, Extrait De Graine De Phaseolus Radiatus, Panax Ginseng Root Extract, Eau De Son D''Oryza Sativa (Riz), Portulaca Oleracea Extract, Butylene Glycol, Glycerin, Salicylic Acid, Melia Azadirachta Leaf Extract, Extrait De Fleur De Melia Azadirachta, Fructose, Tocopherol, Glucose, Sodium PCA, Triéthylhexanoïne, Diphenyl Diméthicone, C12-14, Pareth-12, Ethylhexylglycerin, Hydrogenated Lecithin, Polyglyceryl-10 Oléate, Disodium EDTA', 'Le Green Plum Refreshing Toner : AHA + BHA Beauty of Joseon est un tonique exfoliant quotidien léger et doux qui permet d''éliminer les cellules mortes, l''excès de sébum et d''autres impuretés qui peuvent rester à la surface de la peau après le nettoyage. Son ingrédient principal est l''eau de prune verte, qui est utilisée depuis longtemps dans la phytothérapie. En tant qu''ingrédient cosmétique, l''eau de prune verte aide à éliminer les cellules mortes et à soigner la texture de la peau. Elle crée une merveilleuse synergie avec l''extrait de haricot mungo, un ingrédient apaisant pour la peau, et les exfoliants chimiques AHA et BHA (2% d''acide glycolique et 0,5% d''acide salicylique) pour améliorer la santé générale de la peau.', 150, 'ml', 'beauty-of-joseon-green-plum-refreshing-toner', 'https://korean-skincare.fr/products/beauty-of-joseon-green-plum-refreshing-toner', 'https://aurore-cdn.b-cdn.net/products/beauty-of-joseon-green-plum-refreshing-toner.webp', 'Après le nettoyage du matin et du soir, imbibe un coton et passe-le délicatement sur ta peau, de l''intérieur vers l''extérieur. Sinon, verse une quantité suffisante dans la paume de ta main et tapote légèrement sur ta peau pour la faire pénétrer.', 1422, '2026-05-07 17:37:38.425201+00', '2026-06-14 15:14:07.635+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3ef9-78e7-823c-2ddce6689b04', '__OWNER_ID__', 'Dear Hydration Skin Softening Toner', 'BANILA CO', 'toner', 'pump', 'Aqua, Glycerin, Butylene Glycol, Glycereth-26, Pentylene Glycol, Methylpropanediol, Propanediol, Xylitol, 1,2-Hexanediol, Diethoxyethyl Succinate, Caprylyl Glycol, Polyglyceryl-10 Laurate, Ethlhexlglycerin, Sodium Phytate, Arylates/C10-30 Alkyl Acrylate Crosspolymer, Biosaccharide Gum-1, Parfum, Xanthan Gum, Citric Acid, Polyquaternium-51, Tromethamine, Cynanchum Atratum Extract, Althaea Rosea Flower Extract, Camellia Sinensis Seed Oil, Xylityglucoside, Anhydroxylitol, Tocopherol, Yeast Ferment Extract, Glucose, Opuntia Ficus-Indica Fruit Extract, Candida Ferment', 'Le tonique adoucissant pour la peau Dear Hydration de BANILA CO est un tonique revitalisant conçu pour équilibrer, hydrater et affiner la texture de votre peau en une seule étape, favorisant un teint plus lisse et plus clair. Formulé avec de l''eau de cactus rose, il exfolie en douceur tout en réhydratant la peau, la laissant douce, souple et éclatante. Testé par des dermatologues et adapté à tous les types de peau, ce tonique est la préparation parfaite pour le reste de votre programme de soins. Au cœur de la formule se trouve le cactus rose (figuier de Barbarie), une plante puissante riche en antioxydants et en acides gras qui hydrate et nourrit en profondeur même les peaux les plus sèches. En complément, on trouve le Pink Biome™ exclusif, un complexe hydratant résilient dérivé du désert d''Atacama. Ensemble, ces ingrédients contribuent à renforcer la barrière naturelle de la peau, à la protéger contre les facteurs de stress environnementaux et à maintenir une hydratation durable, faisant de ce tonique une étape essentielle vers un teint sain et éclatant. Recommandé pour : Tous les types de peau.', 200, 'ml', 'banila-co-dear-hydration-skin-softening-toner', 'https://korean-skincare.fr/products/banila-co-dear-hydration-skin-softening-toner', 'https://aurore-cdn.b-cdn.net/products/banila-co-dear-hydration-skin-softening-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 1795, '2026-05-07 17:37:39.065407+00', '2026-06-14 15:14:07.635+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-40a0-72a9-b48b-4c49e1c69014', '__OWNER_ID__', 'Madagascar Centella Tea-Trica Purifying Toner', 'SKIN1004', 'toner', 'pump', 'Aqua, Chamaecyparis Obtusa Water, Melaleuca Alternifolia Leaf Water, Butylene Glycol, Centella Asiatica Extract, Propanediol, Pinus Palustris Leaf Extract, Methyl Gluceth-20, 1,2-Hexanediol, Hydroxyacetophenone, Carbomer, Polyglycéryl-10 Laurate, Tromethamine, Pentylene Glycol, Ethylhexylglycerin, Caprylyl Glycol, Citric Acid, Disodium EDTA, Melaleuca Alternifolia Leaf Oil, Sodium Citrate, Salicylic Acid, Extrait De Coque De Castanea Crenata, Extrait De Fleur De Lavandula Angustifolia', 'Le Madagascar Centella Tea-Trica Purifying Toner SKIN1004 est un tonique indispensable pour les peaux grasses ou sujettes à l''acné. Formulé avec de l’extrait de Centella Asiatica, de l’eau de feuille d’arbre à thé et des ingrédients exfoliants doux, il aide à éliminer les impuretés de surface et à affiner l’apparence des pores pour un teint plus lisse et équilibré. Sa texture légère à base d’eau s’absorbe rapidement sans effet collant, laissant la peau fraîche, hydratée et agréablement purifiée.', 210, 'ml', 'skin1004-madagascar-centella-tea-trica-purifying-toner', 'https://korean-skincare.fr/products/skin1004-madagascar-centella-tea-trica-purifying-toner', 'https://aurore-cdn.b-cdn.net/products/skin1004-madagascar-centella-tea-trica-purifying-toner.webp', 'Après le nettoyage, applique quelques gouttes sur tes doigts ou sur un coton. Tapote délicatement sur ton visage.', 2210, '2026-05-07 17:37:39.488014+00', '2026-06-14 15:14:07.635+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4074-7009-9924-38ee0e9803b6', '__OWNER_ID__', 'Madagascar Centella Poremizing Clear Toner', 'SKIN1004', 'toner', 'pump', 'Aqua, Propanediol, 1,2-Hexanediol, Glycerin, Centella Asiatica Extract, Hydroxyacetophenone, Betaine, Mineral Salts, Panthenol, Ethylhexylglycerin, Sodium Polyacryloyldimethyl Taurate, Disodium EDTA, Butylene Glycol, Salix Alba Bark Extract, Castanea Crenata Shell Extract, Lavandula Angustifolia Flower Extract, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate, Allantoin, Citric Acid, Capryloyl Salicylic Acid, Gluconolactone, Sodium Citrate, Salicylic Acid, Glycolic Acid', 'Le SKIN1004 Poremizing Clear Toner est un tonique exfoliant rafraîchissant conçu pour nettoyer et minimiser les pores pour une peau plus lisse et plus saine. Enrichi en sel rose de l''Himalaya contenant 80 minéraux essentiels, il élimine les impuretés tandis que le complexe 4-HA (AHA, BHA, PHA, LHA) exfolie en douceur pour éliminer les cellules mortes et affiner la texture de la peau. Sa formule Sebum Cleaner contrôle efficacement l''excès de sébum, laissant un fini propre, équilibré et rafraîchi. Doté d''ingrédients hydratants et apaisants tels que l''extrait de centella asiatica, l''acide hyaluronique et le panthénol, ce tonique permet à la peau de rester calme et hydratée tout en obtenant un teint purifié et revitalisé. Recommandé pour : Le soin des pores, les peaux grasses, mixtes et normales.', 210, 'ml', 'skin1004-madagascar-centella-poremizing-clear-toner', 'https://korean-skincare.fr/products/skin1004-madagascar-centella-poremizing-clear-toner', 'https://aurore-cdn.b-cdn.net/products/skin1004-madagascar-centella-poremizing-clear-toner.webp', 'Utilise le tonique après le nettoyage. Applique quelques gouttes sur un disque de coton ou sur tes doigts. Tapote délicatement sur ton visage.', 1567, '2026-05-07 17:37:39.443826+00', '2026-06-14 15:14:07.636+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64d5-7ada-8460-f9ad58a126f9', '__OWNER_ID__', 'Heartleaf 70% Soothing Cream', 'Anua', 'moisturizer', 'jar', '1,2-Hexanediol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Ammonium Acryloyldimethyltaurate/VP Copolymer, ASIATIC ACID, ASIATICOSIDE, Betaine, Butylene Glycol, CAPRYLYL METHICONE, Centella Asiatica Extract, CHLORELLA VULGARIS EXTRACT, Dimethiconol, Dipotassium Glycyrrhizate, Dipropylene Glycol, Ethylhexylglycerin, Fructooligosaccharides, Fructose, GLUCOSE, Glycerin, GLYCERYL ACRYLATE/ACRYLIC ACID COPOLYMER, Houttuynia Cordata Extract, HYDROGENATED POLYDECENE, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, ISOAMYL LAURATE, MADECASSIC ACID, Niacinamide, Panthenol, Pentylene Glycol, POLYMETHYLSILSESQUIOXANE, Portulaca Oleracea Extract, Sodium Phytate, Tocopherol, Tromethamine, VINYL DIMETHICONE, Aqua, XANTHAN GUM', 'Crème apaisante 70% heartleaf + centella + niacinamide. Réduit les rougeurs et les imperfections tout en hydratant.', 100, 'ml', 'anua-heartleaf-70-soothing-cream', 'https://www.skinsafeproducts.com/anua-heartleaf-70-soothing-cream-3-38-fl-oz-100-ml', 'https://aurore-cdn.b-cdn.net/products/anua-heartleaf-70-soothing-cream.webp', 'Chlorella vulgaris + fructooligosaccharides + portulaca. Texture légère gel-crème. Sans parfum.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.636+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-418b-7ee6-8e36-7cabf2f5cde4', '__OWNER_ID__', 'Green Tea Fresh Toner', 'ISNTREE', 'toner', 'pump', 'Camellia Sinensis Leaf Extract, Aqua, Extrait de Feuille de Ginkgo Biloba, Centella Asiatica Extract, Salix Alba Bark Extract, Vaccinium Angustifolium Fruit Extract, Pinus Palustris Leaf Extract, Ulmus Davidiana Root Extract, Oenothera Biennis Flower Extract, Pueraria Lobata Root Extract, Hydrolyzed Hyaluronic Acid, Ammonium Acryloyldimethyltaurate/VP Copolymer, Allantoin, Dipotassium Glycyrrhizate, Beta-Glucan, Disodium EDTA, Hydroxyacétylphénone', 'Idéal pour les peaux sensibles, grasses et mixtes, le Green Tea Fresh Toner Isntree utilise des ingrédients naturels greens certifiés par l''EWG pour équilibrer et nourrir la peau. Sa formule comprend un mélange d''extraits de plantes - Anti Sebum P(HD) - pour contrôler le sébum et 80 % d''extrait de thé vert provenant de l''île de Jeju pour protéger, éclaircir et équilibrer davantage la peau. Parmi les autres ingrédients notables, on trouve l''extrait de Centella Asiatica pour renforcer la barrière cutanée, l''acide hyaluronique hydrolysé pour hydrater, l''allantoïne pour apaiser, et l''extrait de fruit de myrtille pour soulager le stress. Recommandé pour : Peaux sensibles, peaux grasses, peaux mixtes. Peut être utilisé pour : Tous types de peaux.', 200, 'ml', 'isntree-green-tea-fresh-toner', 'https://korean-skincare.fr/products/isntree-green-tea-fresh-toner', 'https://aurore-cdn.b-cdn.net/products/isntree-green-tea-fresh-toner.webp', 'Applique quelques gouttes de tonique dans tes mains ou sur un coton. Tapote délicatement sur l''ensemble de ton visage et de ton cou nettoyés pour un résultat optimal. Fais suivre d''un sérum et d''une crème hydratante.', 1611, '2026-05-07 17:37:39.723706+00', '2026-06-14 15:14:07.636+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-421b-7ff9-86bf-54440109e2d6', '__OWNER_ID__', 'Chestnut BHA 0.9% Clear Toner', 'ISNTREE', 'toner', 'pump', 'Aqua, Butylene Glycol, Glycerin, 1,2-Hexanediol, Extrait de Coque de Castanea Crenata (Châtaigne), Betaine Salicylate, Trehalose, Panthenol, Salix Alba Bark Extract, Sodium Hyaluronate, Extrait de Jacinthe d''Orient (Jacinthe), Extrait de Salvia Sclarea (Sauge Sclarée), Extrait de Fleur de Centaurea Cyanus (Bleuet), Extrait de Borago Officinalis, Chamomilla Recutita (Matricaria) Flower Extract, Extrait de Fleur de Lavandula Angustifolia (Lavande), Portulaca Oleracea Extract, Tromethamine, Gomme Xanthane, Ethylhexylglycerin, Disodium EDTA', 'Le Chestnut BHA 0.9% Clear Toner Isntree exfolie en douceur, débarrassant la peau des cellules mortes, de l''excès de sébum et des points noirs, révélant ainsi un teint revitalisé. Ce tonique va même au-delà du soin de la peau, en embrassant le développement durable grâce à l''utilisation de coquilles de châtaignes laissées à l''abandon. Enrichies en tanins, ces coquilles permettent de resserrer les pores, d''équilibrer le ratio huile/eau de la peau, et de limiter la production de sébum, ce qui garantit un fini hydraté et mat. Le triple acide hyaluronique ajoute une autre couche, en fortifiant la barrière d''hydratation de la peau pour une souplesse durable. L''ingrédient vedette, l''acide salicylique (BHA), purifie délicatement la peau et favorise sa luminosité naturelle. Idéal pour les novices ou les expérimentés en matière de BHA, il suffit d''adapter l''utilisation : commence par 2 à 3 applications par semaine, puis augmente progressivement. Protège ta peau du soleil dans la journée avec un écran solaire après l''application du BHA.', 200, 'ml', 'isntree-chestnut-bha-0-9-clear-toner', 'https://korean-skincare.fr/products/isntree-chestnut-bha-0-9-clear-toner', 'https://aurore-cdn.b-cdn.net/products/isntree-chestnut-bha-0-9-clear-toner.webp', 'Lors de la première étape de ta routine beauté après le nettoyage, prélève une quantité appropriée de produit sur un disque de coton et passe-le délicatement le long de ton grain de peau pour le faire pénétrer.', 2095, '2026-05-07 17:37:39.867728+00', '2026-06-14 15:14:07.636+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42a8-7a72-9505-cfeabb9cce24', '__OWNER_ID__', 'Calming Deep Moisture Toner', 'Pyunkang Yul', 'toner', 'pump', 'Aqua, Propanediol, Glycerin, Dipropylene Glycol, Panthenol, Citric Acid, Gluconolactone, Salix Alba Bark Extract, Lonicera Japonica Flower Extract, Sodium Hyaluronate, Centella Asiatica Extract, Melaleuca Alternifolia Leaf Extract, Salvia Officinalis Leaf Extract, Camellia Japonica Flower Extract, Hydrolyzed Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Sodium Hyaluronate Crosspolymer, Acide Asiaticique, Asiaticoside, Sodium Acetylated Hyaluronate, Acide Madécassique, Madecassoside, Betaine, Butylene Glycol, Caprylyl Glycol, Pentylene Glycol, Hydroxyacetophenone, C12-14 Pareth-12, Sodium Citrate, Disodium EDTA, 1,2-Hexanediol', 'Le Calming Deep Moisture Toner Pyunkang Yul est un tonique hydratant conçu pour les personnes ayant une peau à tendance acnéique. Il est formulé avec des ingrédients doux qui sont également très hydratants et efficaces pour apaiser les peaux acnéiques. L''AHA et le BHA exfolient et aident à éclaircir les cicatrices d''acné et à contrôler le sébum, tandis que des ingrédients comme l''extrait de centella calme la peau et l''écorce de saule blanc aide à contrôler le sébum.', 150, 'ml', 'pyunkang-yul-calming-deep-moisture-toner', 'https://korean-skincare.fr/products/pyunkang-yul-calming-deep-moisture-toner', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-calming-deep-moisture-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 1562, '2026-05-07 17:37:40.008518+00', '2026-06-14 15:14:07.636+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-442c-78c9-836c-467e557e12a0', '__OWNER_ID__', 'Pure VC Mellight Ampoule Set', 'Dr. Ceuracle', 'serum', 'dropper', 'Ascorbic Acid, Extrait de Fruit d''Hippophae Hamnoides, Dipropylene Glycol, Propanediol, Methylpropanediol, Sodium PCA, C12-14 Pareth-12, Portulaca Oleracea Extract, Aqua, Ammonium Acryloyldimethyltaurate/VP Copolymer, Hydroxyacetophenone, Panthenol, Glycerin, Allantoin, Citric Acid, Idebenone, Tocopherol, Tranexamic Acid, Caprylic/Capric Triglyceride, Lavandula Angustifolia Oil, Disodium EDTA, Ethylhexylglycerin, Glycyrrhiza Glabra Root Extract, Huile de Fruit de Citrus Aurantium Bergamia, Rosmarinus Officinalis Leaf Oil, Sodium Citrate, Hydrogenated Lecithin, 1,2-Hexanediol, Sodium Hyaluronate, Fullerenes, Chamomilla Recutita Flower Oil, Glutamate de Phytostéryl/Octyldodécyle Lauroyl, Anthemis Nobilis Flower Oil, Hydroxypropyl Cyclodextrine, Ceramide NP, Glutathione', 'Le Pure VC Mellight Ampoule Set Dr. Ceuracle est la clé d''une peau radieuse et rajeunie. Ce coffret haut de gamme contient quatre ampoules de vitamine C pure, enrichies de glutathion, d''acide tranexamique, d''idébénone et de vitamine E, créant ainsi un puissant programme de traitement de 4 semaines. Cette combinaison dynamique éclaircit visiblement la peau, estompe les taches d''hyperpigmentation, stimule la synthèse du collagène et raffermit la peau pour un teint jeune et lumineux. La texture liquide soyeuse de l''ampoule n''est pas collante, ce qui garantit une application confortable. En exploitant les puissantes propriétés anti-inflammatoires de ces ingrédients, elle apaise même les peaux les plus sensibles, leur donnant un aspect sain, radieux et uniforme. Formulé avec 100 000 ppm de poudre de vitamine C pure, ce duo de "mélanine" et de "lumière" agit harmonieusement pour atténuer les taches brunes et renforcer la vitalité de la peau. Les résultats de tests cliniques effectués sur cet ensemble d''ampoules attestent de la réduction des taches brunes et de l''éclaircissement des peaux ternes et irrégulières, ce qui en fait une solution fiable pour obtenir un teint sain et plein de vitalité. La formulation des ampoules remplace la base aqueuse par de l''extrait d''argousier pour offrir à ta peau une nutrition et une hydratation durables. Cet ensemble d''ampoules a passé des tests dermatologiques de sûreté et d''amélioration de la pigmentation, ce qui garantit que ta peau est entre de bonnes mains. Avec son mélange d''ingrédients actifs bien connus comme l''idébénone, le glutathion, l''acide tranexamique, la vitamine E et le fullerène, il permet non seulement d''améliorer l''éclat de la peau, mais aussi de favoriser sa santé globale. Élève ta routine beauté avec le Pure VC Mellight Ampoule Set Dr.Ceuracle et dévoile le véritable potentiel de luminosité et de vitalité de ta peau. Recommandé pour : Peaux sensibles, sans risques pour l''acné fongique, tous types de peaux. Ce coffret comprend : 4 x Pure VC Mellight Ampoule Set (8ml)', 8, 'ml', 'dr-ceuracle-pure-vc-mellight-ampoule-set', 'https://korean-skincare.fr/products/dr-ceuracle-pure-vc-mellight-ampoule-set', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-pure-vc-mellight-ampoule-set.webp', 'Pousse le bouchon de l''ampoule pour libérer la poudre de vitamine C. Remplace le bouchon par l''applicateur pipette. Applique 2 à 3 gouttes sur ton e visage, en évitant le contour des yeux et de la bouche.', 4995, '2026-05-07 17:37:40.396436+00', '2026-06-14 15:14:07.637+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-457e-78aa-9403-66a46c5bbfa2', '__OWNER_ID__', 'Peach 77% Niacin Essence Toner', 'Anua', 'toner', 'pump', 'Prunus Persica Fruit Extract, 2,3-Butanediol, Aqua, Glycerin, Dipropylene Glycol, Niacinamide, Butylene Glycol, 1,2-Hexanediol, Lactobacillus Ferment, Methylpropanediol, Ferment de Streptococcus Thermophilus, Jus de Pyrus Malus, Bifida Ferment Lysate, Bacillus Ferment, Extrait de Phellinus Linteus, Xylose, Galactomyces Ferment Filtrate, Alpha-Arbutin, Extrait de Fleur de Prunus Persica, Sodium Hyaluronate, Protéine Végétale Hydrolysée, Laurate de Polyglycéryl-10, Propanediol, Squalane, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Caprylic/Capric Triglyceride, Diméthicone Diphenyl, Triéthylhexanoïne, Ethylhexylglycerin, Stéarate de Polyglycéryl-10, Adenosine, Hydrogenated Lecithin, Dipotassium Glycyrrhizate, Tromethamine, Polyacrylate de Sodium, Panthenol, Sodium Hyaluronate Crosspolymer, Ceramide NP, Allantoin, Cyanocobalamin, Polyglutamic Acid, Glutamate Stéaroïque de Sodium, Tocopherol, Ascorbyl Glucoside, Betaine Salicylate, Ascorbic Acid, Maltodextrin, Glycine, Sérine, Glutamic Acid, Acide Aspartique, Leucine, Alanine, Lysine, Arginine, Tyrosine, Phénylalanine, Proline, Thréonine, Valine, Isoleucine, Histidine, Cystéine, Méthionine, Gomme Xanthane, Parfum', 'Le Peach 77% Niacin Essence Toner Anua est un incontournable de toute routine beauté, fusionnant la puissance revitalisante du niacinamide avec l''essence rafraîchissante de la pêche. Avec une concentration remarquable de 77 % de niacinamide, ce tonique est un soin efficace qui répond à différents problèmes de peau. Le niacinamide, aussi appelé vitamine B3, est un ingrédient polyvalent qui améliore la texture de la peau, atténue les ridules, réduit les pores et favorise l''uniformité et le tonus de la peau. Ce tonique aux multiples vertus procure un teint radieux grâce à l''essence de pêche qui, en plus de lui conférer un parfum délicieux, contribue à ses effets hydratants et éclaircissants, laissant la peau souple et rafraîchie. Élaboré avec une formule légère à absorption rapide, le Peach 77% Niacin Essence Toner Anua s''intègre facilement à ta routine beauté quotidienne, préparant ta peau à absorber efficacement les produits suivants. Adapté à tous les types de peau, ce tonique ravive et rajeunit le teint. De multiples méthodes d''application sont possibles, en le tapotant sur la peau pour le faire pénétrer, en l''appliquant comme un masque tissu, ou encore sur un coton pour éliminer les cellules mortes de la peau. Ce tonique offre une approche versatile des soins de la peau, garantissant un visage radieux et revitalisé. Recommandé pour : Peaux sèches, peaux sensibles, tous types de peaux.', 250, 'ml', 'anua-peach-77-niacin-essence-toner', 'https://korean-skincare.fr/products/anua-peach-77-niacin-essence-toner', 'https://aurore-cdn.b-cdn.net/products/anua-peach-77-niacin-essence-toner.webp', 'Applique une quantité modérée de produit sur ta peau, en évitant le contour des yeux et de la bouche. Tapote légèrement pour une meilleure absorption. Alternativement : Distribue une quantité appropriée de produit sur un disque de coton. Passe le coton le long de la texture de l=ta peau pour éliminer les cellules mortes. Alternativement : Distribue une quantité appropriée de produit sur un disque de coton, et place-le sur ta peau pendant 5 à 10 minutes pour l''utiliser comme un masque tissu hydratant.', 1929, '2026-05-07 17:37:40.734445+00', '2026-06-14 15:14:07.637+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42de-7736-91ae-bb4a79ebec82', '__OWNER_ID__', 'Brightening Vita Toner', 'Pyunkang Yul', 'toner', 'pump', 'Aqua, Propanediol, 1,2-Hexanediol, Glycerin, Niacinamide, Betaine, Panthenol, Extrait de Perle, Dipropylene Glycol, Sodium Citrate, Adenosine, Citric Acid, Disodium EDTA, Butylene Glycol, Myristate de Polyglycéryl-10, Sodium Hyaluronate, Cetyl Ethylhexanoate, Caprylic/Capric Triglyceride, Caprylyl Glycol, Ethylhexyl Palmitate, Extrait de Fleur de Chrysanthemum Morifolium, Extrait de Racine de Broussonetia Kazinoki, Hyaluronic Acid, Ascorbic Acid', 'Revitalise ta peau terne et en manque d''éclat grâce au Brightening Vita Toner Pyunkang Yul, un puissant mélange d''ingrédients éclaircissants et hydratants conçu pour transformer ton teint en seulement quatre semaines. Infusé de vitamine C pure et de niacinamide, ce tonique agit pour atténuer les imperfections et améliorer l''éclat de la peau, tandis que l''adénosine et l''acide hyaluronique procurent une hydratation profonde et un effet repulpant. Enrichi d''extraits de perles et de racines de mûrier, il laisse ta peau parfaitement lisse et éclatante. Recommandé pour : Hyperpigmentation, peaux sèches, tous types de peaux.', 150, 'ml', 'pyunkang-yul-brightening-vita-toner', 'https://korean-skincare.fr/products/pyunkang-yul-brightening-vita-toner', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-brightening-vita-toner.webp', 'Prélève une quantité modérée de produit dans la paume de ta main et presse délicatement sur ton visage pour faire pénétrer. Tu peux aussi l''appliquer sur une compresse de coton et la passer délicatement le long de ton grain de peau. Lorsque tu sens que ta peau chauffe, imbibe abondamment une compresse du produit et utilise-la comme masque tissu.', 1757, '2026-05-07 17:37:40.062247+00', '2026-06-14 15:14:07.637+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4300-7b54-8227-d56cd9030f96', '__OWNER_ID__', 'Black Rice Hyaluronic Toner', 'Haruharu Wonder', 'toner', 'pump', 'Aqua, Betaine, Glycerin, Propanediol, Oryza Sativa Extract, Extrait d''Écorce de Pousses de Phyllostachys Pubescens, Aspergillus Ferment, Extrait de Racine de Ginseng Panax, Cyclodextrin, Extrait de Racine de Scutellaria Baicalensis, Hyaluronic Acid, Beta-Glucan, Cellulose Gum, Gomme Xanthane, Butylene Glycol, Extrait d''Usnée Barbue (Lichen), Zanthoxylum Piperitum Fruit Extract, Extrait de Pulsatilla Koreana, Sodium Phytate, Gomme de Tamarin (Tamarindus Indica), Laurate de Polyglyceryl-10, Myristate de Polyglyceryl-10, Glucose, 1,2-Hexanediol, Alcohol, Lavandula Angustifolia Oil', 'Le Haruharu WONDER Black Rice Hyaluronic Toner fournit une hydratation instantanée et durable, composée à 95 % d''ingrédients d''origine naturelle. Les deux ingrédients phares, le riz noir fermenté et l''acide hyaluronique, se combinent pour apporter un regain de nutrition anti-âge aux peaux fatiguées. Le riz noir regorge de polyphénols et de flavonoïdes, qui protègent la peau contre les radicaux libres, notamment la pollution et les rayons ultraviolets, et favorisent la régénération des cellules cutanées. L''acide hyaluronique apporte une hydratation réconfortante en profondeur, tandis que le bêta-glucane et l''extrait de ginseng rouge soignent et rajeunissent la peau.', 300, 'ml', 'haruharu-wonder-black-rice-hyaluronic-toner', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-hyaluronic-toner', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-hyaluronic-toner.webp', 'Distribue une quantité de produit suffisante sur un coton Passe-le délicatement sur l''ensemble de ton visage Retourne le coton et tapote doucement pour absorber l''excédent de produit', 2052, '2026-05-07 17:37:40.096503+00', '2026-06-14 15:14:07.637+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4370-71a7-8559-aecf0e5275c6', '__OWNER_ID__', 'Fig Cleansing Balm', 'I''m From', 'cleanser', 'tube', 'Cetyl Ethylhexanoate, Polyethylene, Synthetic Wax, Ficus Carica Fruit Extract, Peg-10 Isostearate, Peg-20 Glyceryl Triisostearate, Caprylic/Capric Triglyceride, Parfum, Sorbitan Sesquioleate, Caprylyl Glycol, Ethylhexylglycerin, Moringa Oleifera Seed Oil, Curcuma Longa Root Extract, Extrait de Fleur de Melia Azadirachta, Melia Azadirachta Leaf Extract, Extrait d''Écorce de Melia Azadirachta, Extrait de Corallina Officinalis, Ocimum Sanctum Leaf Extract', 'Le Fig Cleansing Balm I''m From est un baume à la texture de sorbet qui se transforme sans effort en une huile nourrissante et qui s''émulsionne finalement en un lait doux. La transformation de ce baume en plusieurs étapes permet d''éliminer efficacement le maquillage, les cellules mortes et les autres impuretés, laissant ta peau parfaitement nettoyée et rafraîchie. L''ingrédient clé, l''eau d''huile de figue, joue un rôle essentiel dans l''amélioration de la santé de ta peau. Elle dissout efficacement le sébum, minimisant ainsi l''apparence des points noirs, tout en atténuant les taches brunes et en apaisant les rougeurs, ce qui permet d''obtenir un teint plus uniforme. Enrichi d''une multitude de vitamines et de polyphénols, ce baume nettoyant hydrate en profondeur et revitalise les peaux fatiguées, les laissant souples et douces après chaque utilisation. Engagé dans la cosmétique verte et écologique, I''m From a conçu ce baume nettoyant pour qu''il soit vegan, cruelty-free et exempt d''une multitude d''ingrédients nocifs tels que les colorants artificiels, les parabènes, les sulfates, les produits d''origine animale, l''alcool, les huiles minérales, les huiles essentielles et les silicones. Exploitant la puissance d''extraits naturels reconnus, le Fig Cleansing Balm I''m From offre un soin efficace qui non seulement nettoie, mais aussi rajeunit le teint. Améliore ton rituel de nettoyage avec ce baume transformateur pour une peau rafraîchie, revitalisée et d''une propreté éclatante. Recommandé pour : Tous types de peaux.', 100, 'ml', 'fig-cleansing-balm', 'https://korean-skincare.fr/products/fig-cleansing-balm', 'https://aurore-cdn.b-cdn.net/products/fig-cleansing-balm.webp', 'Utilise la spatule pour prélever une quantité adéquate de produit. Étale-le délicatement sur ton visage et laisse-le agir pendant 10 à 15 minutes. Rince délicatement en massant ton visage avec de l''eau tiède.', 3326, '2026-05-07 17:37:40.207925+00', '2026-06-14 15:14:07.642+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4315-700e-9f47-4e7b000400a5', '__OWNER_ID__', 'Black Bamboo Mist', 'Haruharu Wonder', 'mist', 'spray', 'Eau D.I, Glycerin, Betaine, Propanediol, 1,2-Hexanediol, Extrait de Feuille de Phyllostachys Nigra, Extrait d''Écorce de Pousse de Phyllostachys Pubescens, Extrait de Pousse de Bambusa Vulgaris, Sodium Phytate, Alcohol, Beta-Glucan, Aspergillus Ferment, Zanthoxylum Piperitum Fruit Extract, Extrait de Pulsatilla Koreana, Extrait de Usnea Barbata (Lichen), Laurate de Polyglyceryl-10, Myristate de Polyglyceryl-10, Parfum', 'La Black Bamboo Mist Haruharu WONDER est fabriquée à partir de bambou riche en antioxydants et bénéfique pour la peau. Elle nourrit en profondeur et hydrate les peaux fatiguées. Sa formule à absorption rapide regorge de riches nutriments grâce au processus de fermentation de HaruHaru qui permet de renforcer les antioxydants naturels présents dans le bambou, son ingrédient phare. Testée pour être non irritante, cette formule naturelle à 95 % contient également du bêta-glucane régénérant pour une peau d''apparence plus ferme et plus lisse.', 150, 'ml', 'haruharu-wonder-black-bamboo-mist', 'https://korean-skincare.fr/products/haruharu-wonder-black-bamboo-mist', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-bamboo-mist.webp', 'Vaporise 2 à 3 fois sur l''ensemble du visage à une distance de 25 cm. Tu peux aussi utiliser cette brume à tout moment de la journée pour apaiser, rafraîchir et hydrater la peau.', 1750, '2026-05-07 17:37:40.116799+00', '2026-06-14 15:14:07.637+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4378-77d3-a3f2-32048fd4299f', '__OWNER_ID__', 'Rice Toner Pad', 'I''m From', 'toner', 'pack', 'Aqua, Methylpropanediol, Dipropylene Glycol, Glycerin, Niacinamide, Olea Europaea Fruit Oil, Hydroxyacetophenone, C12-14 Pareth-12, Caprylyl Glycol, Polyglyceryl-3 Methylglucose Distearate, 1,2-Hexanediol, Arginine, Betaine, Carbomer, Sodium Citrate, Glyceryl Stearate SE, Ethylhexylglycerin, Methyl Glucose Sesquistearate, Adenosine, Citric Acid, Disodium EDTA, Gomme de Xanthane, Oryza Sativa Extract, Oryza Sativa Extract, Dipotassium Glycyrrhizate', 'Les Rice Toner Pads I''m From sont des compresses toniques hydratantes et nourrissantes conçues pour hydrater en profondeur, exfolier en douceur et illuminer le teint. Enrichies en complexe de riz Yeoju à 1 %, issu de rizières biologiques de Yeoju, en Corée du Sud, ces compresses triple couche sont conçues pour améliorer la texture, le teint et l''élasticité de la peau tout en offrant une hydratation longue durée. La formule convient à tous les types de peaux, en particulier aux peaux sensibles, grâce à sa conception douce et non irritante. Les ingrédients clés tels que l''extrait de riz et le niacinamide illuminent la peau, réduisent la pigmentation et lissent le grain de peau, tandis que le matériau extensible et ultra-adhésif des compresses garantit une application apaisante et non irritante. Chaque boîte contient 60 compresses double face (140 ml) et une mini-pince pour une utilisation hygiénique. Les compresses peuvent être utilisées comme tonique à passer pour affiner la peau ou comme masque tonique pour un soin ciblé, ce qui en fait un complément polyvalent à toute routine beauté. Recommandé pour : Tous types de peaux.', 60, 'pcs', 'im-from-rice-toner-pad', 'https://korean-skincare.fr/products/im-from-rice-toner-pad', 'https://aurore-cdn.b-cdn.net/products/im-from-rice-toner-pad.webp', 'Après avoir nettoyé ta peau, utilise le côté en relief de la compresse pour nettoyer ton visage en suivant ton grain de peau, en évitant le contour des lèvres et des yeux. Passe à nouveau la compresse sur ton visage délicatement avec le côté opposé de la compresse pour préparer ta peau. Tu peux également utiliser la compresse comme un masque apaisant en la plaçant sur les zones irritées et en la laissant agir jusqu''à 3 minutes.', 2695, '2026-05-07 17:37:40.216343+00', '2026-06-14 15:14:07.638+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cc2-75ec-b7e6-2491b301e4c0', '__OWNER_ID__', 'Jeju Orchid Eye Cream', 'INNISFREE', 'eye-cream', 'jar', 'Aqua, Butylene Glycol, Glycerin, Squalane, Cetyl Ethylhexanoate, Limnanthes Alba Seed Oil, Copernicia Cerifera Wax/Copernicia Cerifera Cera/Cire De Carnauba, Niacinamide, Cyclopentasiloxane, Butyrospermum Parkii Butter, Glyceryl Stearate, Cyclohexasiloxane, C14-22 Alcohols, 1,2-Hexanediol, Arachidyl Alcohol, Palmitic Acid, Stearic Acid, Cetearyl Alcohol, PEG-100 Stearate, Propanediol, Behenylalcohol, Polyacrylate 13, C12-20 Alkyl Glucoside, Arachidyl Glucoside, Parfum, Polyisobutene, Hydrogenated Lecithin, Glyceryl Caprylate, Polyglyceryl-3 Methylglucose Distearate, Ethylhexylglycerin, Xanthan Gum, Disodium EDTA, Adenosine, Polysorbate 20, Sorbitan Isostearate, Avena Sativa Kernel Extract, Caffeine, Hyaluronic Acid, Mannitol, Hexyl Cinnamal, Linalool, Betaine, Myristic Acid, Glucose, Orchid Extract, Lauric Acid, Phenoxyethanol, Copper Tripeptide-1, Tocopherol, Acetyl Tetrapeptide-5, Acetyl Tetrapeptide-11', 'La crème pour les yeux Innisfree Jeju Orchid Eye Cream est une crème riche et nourrissante pour les yeux alimentée par OrchidElixir 2.0™ des orchidées de Jeju pour aider à lisser, à raffermir et à éclaircir la peau délicate autour de vos yeux. Avec des ingrédients hydratants comme le squalane et l''acide hyaluronique, ainsi que de la caféine pour rafraîchir les yeux fatigués, elle agit pour réduire les poches et les ridules tout en gardant la peau douce et hydratée. La texture crémeuse s''absorbe parfaitement, laissant votre zone sous les yeux rayonnante et reposée.', 30, 'ml', 'innisfree-jeju-orchid-eye-cream', 'https://korean-skincare.fr/products/innisfree-jeju-orchid-eye-cream', 'https://aurore-cdn.b-cdn.net/products/innisfree-jeju-orchid-eye-cream.webp', 'Prends une quantité appropriée de produit et applique-le sur le contour de tes yeux Ensuite, tu peux tapoter légèrement pour améliorer l''absorption du produit..', 2995, '2026-05-07 17:37:38.498263+00', '2026-06-14 15:14:07.638+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3d0d-78b4-832e-be42a56692db', '__OWNER_ID__', 'Sunprise Mild Watery Light SPF50 PA+++', 'ETUDE', 'moisturizer', 'jar', 'Aqua, Dibutyl Adipate, Propanediol, Diisopropyl Sebacate, Ethylhexyl Triazone, Terephthalylidene Dicamphor Sulfonic Acid, Polyglyceryl-3 Distearate, Glycerin, Tromethamine, Cetyl Alcohol, 1,2-Hexanediol, Pentylene Glycol, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Caprylyl Méthicone, Polysilicone-15, Polymethylsilsesquioxane, Triglycéride Caprylique/Caprique/Succinique, Glyceryl Stearate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Phosphate Cétylique de Potassium, Methylpropanediol, Ammonium Acryloyldimethyltaurate/VP Copolymer, Parfum, Ammonium Polyacryloyldimethyl Taurate, Glycéryl Stéarate Citrate, Ethylhexylglycerin, Carbomer, Polyacrylate de Sodium, Polyéther-1, Acrylates/C10-30 Alky Acrylate Crosspolymer, T-Butyl Alcohol, Helianthus Annuus Seed Oil, Huile de Graine d''Adansonia Digitata, Butylene Glycol, Biosaccharide Gum-1, Tocopherol, Extrait d''Opuntia Ficus-Indica, Sodium Hyaluronate, Phenoxyethanol, Aloe Barbadensis Leaf Juice, Citric Acid, Potassium Sorbate, Extrait de Racine de Carex Humillis, Sodium Benzoate, Extrait de Fruit de Malpighia Emarginata, Euterpe Oleracea Fruit Extract, Extrait de Fruit de Terminalia Ferdinandiana', 'Le Sunprise Mild Watery Light SPF50 PA+++ Etude House est un gel solaire hydratant et rafraîchissant. Ce gel anti-UV enrichi de FPS 50 protège la peau du vieillissement prématuré causé par l''exposition nocive au soleil. Sa formule hydrosoluble non collante s''applique en douceur. Contenant 20 sortes d''ingrédients végétaux tels que l''extrait de carex nain, l''extrait de graines de tournesol, l''aloe vera, l''extrait de Portulaca Oleracea, la baie d''açaï et l''acérola, entre autres.', 50, 'g', 'etude-house-sunprise-mild-watery-light', 'https://korean-skincare.fr/products/etude-house-sunprise-mild-watery-light', 'https://aurore-cdn.b-cdn.net/products/etude-house-sunprise-mild-watery-light.webp', 'À la fin de ta routine beauté, applique délicatement sur les zones exposées aux rayons UV. En évitant le contour des yeux, tapote ta peau pour faire pénétrer le produit.', 1256, '2026-05-07 17:37:38.573347+00', '2026-06-14 15:14:07.638+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43e9-7119-b59b-f5e57cd12019', '__OWNER_ID__', 'Vegan Kombucha Tea Mist', 'Dr. Ceuracle', 'mist', 'spray', 'Aqua, Cetyl Ethylhexanoate, Propanediol, Pentylene Glycol, Glycerin, Niacinamide, Methylpropanediol, 1,2-Hexanediol, Polydecène Hydrogéné, Trilaureth-4 Phosphate, Hydrogenated Lecithin, Hydroxyacetophenone, Camellia Sinensis Leaf Water, Ethylhexylglycerin, Disodium EDTA, Adenosine, Cellulose Gum, Parfum, Dextrin, Theobroma Cacao Seed Extract, Extrait De Potentilla Anserina, Polyquaternium-51, Extrait De Graines D’Avena Sativa, Extrait De Feuilles De Cynara Scolymus, Beta-Glucan, Butylene Glycol, Lactococcus Ferment Lysate, Extrait De Fruits De Schisandra Chinensis, Camellia Sinensis Leaf Extract, Saccharomyces Ferment Filtrate, Fructooligosaccharides, Centella Asiatica Extract, Extrait De Racine De Cyperus Rotundus, Tocopherol, Sodium Chloride, Glutathione, Distearate De Saccharose, Caprylic/Capric Triglyceride, Hydroxypropyl Cyclodextrine', 'La Vegan Kombucha Tea Mist est une brume visage vegan conçue pour rafraîchir, hydrater et rééquilibrer la peau. Elle contient de l’extrait de thé noir fermenté (kombucha) ainsi qu’un Vegan Tea Complex riche en probiotiques et antioxydants, qui aide à renforcer la barrière d’hydratation de la peau et à réguler l’équilibre eau-sébum. Grâce à sa brume ultra-fine et légère, elle peut s’utiliser par-dessus le maquillage ou tout au long de la journée pour un boost d’éclat instantané. Des ingrédients comme le niacinamide et le glutathione apportent une action illuminatrice, tandis que l’eau et les extraits de feuilles de thé apaisent et purifient la peau. Recommandé pour : Peaux sèches, peaux sensibles, tous types de peaux.', 80, 'ml', 'dr-ceuracle-vegan-kombucha-tea-mist', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-kombucha-tea-mist', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-kombucha-tea-mist.webp', 'Agite bien le flacon pour mélanger la texture et les différentes phases de la formule. Ferme les yeux et vaporise uniformément sur ton visage et ton cou à une distance d’environ 20–30 cm. Tapote délicatement avec tes doigts pour favoriser l’absorption ou applique plusieurs couches pour une hydratation renforcée ou un rafraîchissement en déplacement. Astuce : Utilise cette brume chaque fois que ta peau est agressée par l’environnement (avion, climatisation, port du masque) ou juste après le maquillage pour un fini frais et lumineux.', 2195, '2026-05-07 17:37:40.328994+00', '2026-06-14 15:14:07.638+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4423-7edc-b7eb-eb7c2d601046', '__OWNER_ID__', 'Hyal Reyouth Oil Drop Mist', 'Dr. Ceuracle', 'mist', 'spray', 'Aqua, Polyglycérine-3, Butylene Glycol, Glycerin, 1,2-Hexanediol, Squalane, Succinate de Diéthoxyéthyl, Panthenol, Tromethamine, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Ethylhexylglycerin, Adenosine, Pantolactone, Melia Azadirachta Leaf Extract, Extrait de Fleur de Melia Azadirachta, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Hyaluronate de Sodium Diméthylsilanol, Sodium Hyaluronate, Hyaluronic Acid, Potassium Hyaluronate, Inulin, Coccinia Indica Fruit Extract, Sodium Hyaluronate Crosspolymer, Hyaluronate de Sodium Hydroxypropyltrimonium, Extensine Hydrolysée, Hyaluronate de Sodium Diméthylsilanol, Hydrogenated Lecithin, Sodium Acetylated Hyaluronate, Solanum Melongena Fruit Extract, Simmondsia Chinensis Seed Oil, Tocopherol, Ceramide NP, Curcuma Longa Root Extract, Extrait de Corallina Officinalis, Ocimum Sanctum Leaf Extract, Extrait de Collagène, Disodium EDTA, Parfum', 'Profite d''une explosion d''hydratation et de jeunesse avec la Hyal Reyouth Oil Drop Mist Dr. Ceuracle, une brume rafraîchissante à base d''huile dans le sérum, conçue pour rétablir l''hydratation et l''élasticité de la peau. Infusée d''ingrédients puissants comme l''extrait de canne à sucre et le squalane végétal, elle hydrate et répare en profondeur la peau sèche, améliorant sa texture et son apparence. Enrichie en panthénol et en fructane, cette brume forme une solide barrière d''hydratation à la surface de la peau, prévenant la déshydratation tout en renforçant son élasticité. Sa formule innovante Fresh & Deep assure une absorption optimale des éléments hydratants, laissant derrière elle une barrière hydratante rafraîchissante. Recommandé pour : Peaux sèches, sensibles, tous types de peaux.', 125, 'ml', 'dr-ceuracle-hyal-reyouth-oil-drop-mist', 'https://korean-skincare.fr/products/dr-ceuracle-hyal-reyouth-oil-drop-mist', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-hyal-reyouth-oil-drop-mist.webp', 'Commence par nettoyer ta peau. Ferme tes yeux et vaporise une quantité adéquate à 20 cm de ton visage. Tapote légèrement pour une absorption maximale.', 2649, '2026-05-07 17:37:40.38767+00', '2026-06-14 15:14:07.639+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4456-7888-82ba-03593dd88d48', '__OWNER_ID__', 'Pro Balance Biotics Toner', 'Dr. Ceuracle', 'toner', 'pump', 'Aqua, Propanediol, Glycerin, Glycereth-26, 1,2-Hexanediol, Portulaca Oleracea Extract, Trehalose, Centella Asiatica Extract, Ficus Carica Fruit Extract, Huile de Citrus Aurantium Dulcis (Orange), Hydrogenated Lecithin, Citrus Nobilis Peel Oil, Litsea Cubeba Fruit Oil, Eau Minérale, Betaine, Octyldodécèth-16, Butylene Glycol, Sodium Citrate, Lactobacillus Ferment, Citric Acid, Disodium EDTA, Ceramide NP, Lactobacillus Ferment Lysate, Lactococcus Ferment Lysate, Bifida Ferment Lysate, Bifida Ferment Lysate, Saccharomyces Ferment Filtrate, Théanine, Lipides de Lait, Glutathione, Ethylhexylglycerin', 'Le Pro Balance Biotics Toner Dr. Ceuracle est un tonique qui renforce la barrière cutanée, essentielle au maintien de la santé de la peau. Enrichi en G.Fer-kefir et en 5 Probiotics Complex pour soutenir le microbiome de la peau et renforcer sa barrière naturelle, ce tonique léger aide à restaurer la perte d''hydrataion et à faire disparaître l''aspect terne et fatigué de la peau. Enrichi en eau biomimétique - un ingrédient composé d''eau minérale, de L-théanine, de gluthathion et de lipides de lait qui reproduit l''hydratation naturelle de la peau - il agit comme une solution désaltérante à action rapide pour la peau en l''hydratant, la repulpant et l''adoucissant. Incroyablement légère et dotée d''une texture douce et réconfortante, sa formule riche en probiotiques est également assez douce pour aider à apaiser ta peau si tu as abusé des acides et des actifs dans ta routine beauté.', 300, 'ml', 'dr-ceuracle-pro-balance-biotics-toner', 'https://korean-skincare.fr/products/dr-ceuracle-pro-balance-biotics-toner', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-pro-balance-biotics-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 2346, '2026-05-07 17:37:40.438412+00', '2026-06-14 15:14:07.639+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-459d-7aa8-bee5-b04ac601cc34', '__OWNER_ID__', 'Azelaic 10 Hyaluron Redness Soothing Pad', 'Anua', 'toner', 'pack', 'Aqua, Butylene Glycol, Dipropylene Glycol, Propanediol, Glycerin, Betaine, Diglycérine, Methylpropanediol, Urée Hydroxyéthylée, 1,2-Hexanediol, Hydroxyacetophenone, Glycéreth-25 PCA Isostéarate, Panthenol, Melia Azadirachta Leaf Extract, Gomme Xanthane, Ethylhexylglycerin, Disodium EDTA, Extrait de Fleur de Melia Azadirachta, Allantoin, Polyacrylate de Sodium, Copolymère Acrylate de Glycéryle/Acide Acrylique, Copolymère PVM/MA, Theobroma Cacao Seed Extract, Dextrin, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Sodium Hyaluronate, Azelaic Acid, Bisabolol, Dipotassium Glycyrrhizate, Extrait de Maïs (Zea Mays), Centella Asiatica Extract, Extrait de Feuille de Centella Asiatica, Extrait de Racine de Centella Asiatica, Acide Asiatic, Asiaticoside, Acide Madécassique, Madecassoside, Ceramide NP, Extrait de Chlorella Vulgaris, Melaleuca Alternifolia Leaf Water, Squalane, Hyaluronate de Diméthylsilanol, Hydrolyzed Sodium Hyaluronate, Inulin, Extrait d’Écorce de Pinus Pinaster, Potassium Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Sodium Hyaluronate Crosspolymer, Glucose, Diméthylsilanol Hyaluronate de Sodium, Sodium Acetylated Hyaluronate', 'Découvre le secret d''une peau apaisée et nette grâce aux Azelaic 10 Hyaluron Redness Soothing Pads Anua, soigneusement conçues pour traiter les signes visibles d''irritation et favoriser un teint plus équilibré. Cette compresse innovante contient un mélange puissant de 10 % d''acide azélaïque, un ingrédient réputé pour sa capacité à réduire les rougeurs et à uniformiser le teint, ainsi que plusieurs formes d''acide hyaluronique pour hydrater en profondeur et renforcer la barrière naturelle de la peau. Retrouve confiance en toi grâce à un teint visiblement apaisé et adopte cette compresse spécialement formulée comme produit incontournable pour une peau plus saine et éclatante de santé. Recommandé pour : Peaux sensibles, tous types de peaux.', 230, 'ml', 'anua-azelaic-10-hyaluron-redness-soothing-pad', 'https://korean-skincare.fr/products/anua-azelaic-10-hyaluron-redness-soothing-pad', 'https://aurore-cdn.b-cdn.net/products/anua-azelaic-10-hyaluron-redness-soothing-pad.webp', 'Après avoir nettoyé ta peau, prélève une compresse. Applique la compresse directement sur les zones concernées qui présentent des rougeurs, des irritations ou des éruptions cutanées (par exemple, les joues, le front, le menton). Laisse agir pendant 5 à 20 minutes, comme un mini masque tissu. Retire la compresse et tapote doucement ton visage pour faire pénétrer l''essence restante dans ta peau. Conseil : les compresses sont extensibles, tu peux donc les étirer doucement pour couvrir des zones plus larges si nécessaire.', 1976, '2026-05-07 17:37:40.765526+00', '2026-06-14 15:14:07.639+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4663-7286-a3f3-14477778f987', '__OWNER_ID__', 'A-Cica 365 Hydrating Relief Toner pH4.5', 'AESTURA', 'toner', 'pump', 'Aqua, Butylene Glycol, Glycerin, Niacinamide, 1,2-Hexanediol, Gluconolactone, Tromethamine, Xanthan Gum, Ethylhexylglycerin, Lecithin, Sodium Metaphosphate, Polyglyceryl-10 Oleate, Sodium Hyaluronate, 3-O-Ethyl Ascorbic Acid, Zinc PCA, Polyglyceryl-4 Caprate, Asiaticoside, Madecassic Acid, Glyceryl Caprylate, Asiatic Acid, Madecassoside, Sodium Trimetaphosphate, Propylene Glycol, Tocopherol, Oryza Sativa Rice Bran Oil', 'L''A-Cica 365 Hydrating Relief Toner pH4.5 AESTURA est un tonique apaisant à faible pH conçu pour hydrater, calmer et rééquilibrer les peaux sensibles ou sujettes aux boutons. Formulé à un pH optimal de 4,5, il aide à maintenir la barrière protectrice naturelle de la peau tout en réduisant les rougeurs et les irritations. Alimenté par le complexe A-Cica et des ingrédients qui soutiennent la barrière cutanée, ce tonique léger apporte une hydratation immédiate tout en favorisant la résilience cutanée à long terme. Sa texture rafraîchissante et aqueuse pénètre rapidement sans laisser de film collant, ce qui le rend idéal à superposer dans les routines du matin et du soir. L''A-Cica 365 Hydrating Relief Toner AESTURA aide à calmer la peau stressée, affiner la texture et préparer le teint pour les étapes suivantes de ta routine. Recommandé pour : Peaux sensibles ou sujettes aux boutons, rougeurs.', 200, 'ml', 'aestura-a-cica-365-hydrating-relief-toner-ph4-5', 'https://korean-skincare.fr/products/aestura-a-cica-365-hydrating-relief-toner-ph4-5', 'https://aurore-cdn.b-cdn.net/products/aestura-a-cica-365-hydrating-relief-toner-ph4-5.webp', 'Après le nettoyage, applique une quantité appropriée sur un coton ou tes mains et passe doucement sur ton visage en balayant ou en tapotant. Suivre avec un sérum et une crème. Utilise matin et soir.', 2695, '2026-05-07 17:37:40.963069+00', '2026-06-14 15:14:07.639+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4375-7d57-a8c0-c41a8faeef23', '__OWNER_ID__', 'Beet Purifying Mask (Expiring 8/15/2026)', 'I''m From', 'mask', 'pack', 'Aqua, Kaolin, Dipropylene Glycol, Propanediol, Cetyl Alcohol, Cellulose, Caprylic/Capric Triglyceride, 1,2-Hexanediol, Alcool Arachidylique, Glyceryl Stearate, Isononyl Isononanoate, Palmitic Acid, Poudre de Racine de Beta Vulgaris, Stearic Acid, Behenyl Alcohol, Glucoside d''Arachidylique, Bentonite, Poudre de Coque de Cocos Nucifera, Poudre de Graines de Vitis Vinifera, Hydroxyacetophenone, Polyacrylate-13, Gomme Xanthane, Hydrogenated Polyisobutene, Phosphate de Cétyle de Potassium, Ethylhexylglycerin, Parfum, Disodium EDTA, CI 77491, Laurate de Polyglycéryl-10, Ethylhexyl Palmitate, Myristic Acid, Sorbitan Isostearate, Glucose, Panthenol, Extrait de Racine de Beta Vulgaris, Sucrose, Tocopherol, Citric Acid, Gluconolactone', 'Le Beet Purifying Mask I''m From est un traitement transformateur à rincer, qui incorpore les puissants bienfaits de l''enzyme de betterave rouge de Damyang, en Corée. Enrichie de 1,5 % d''enzyme de betterave rouge, cette formule d''argile douce pénètre profondément dans les pores, purifiant et régulant efficacement la production de sébum pour un teint plus frais. Le processus méticuleux de vieillissement de 72 heures de l''argile avec l''enzyme de betterave rouge assure une rétention optimale de l''hydratation sans aucun tiraillement après le rinçage, offrant ainsi une hydratation profonde à la peau. Sa composition riche en bêta-carotène contribue à ses qualités apaisantes, ce qui en fait une option parfaite pour les peaux sèches. Idéal pour ceux qui cherchent à débarrasser leur peau des cellules mortes et des impuretés, et à raviver les peaux abîmées, ce masque offre une solution rafraîchissante pour les peaux ternes ou sensibles. La méthode naturelle d''enzymes séchées de ce masque, mise au point par I''m From, exploite la puissance de la betterave rouge pour fournir des nutriments essentiels et des composés actifs. Le bêta-carotène contenu dans la betterave rouge non seulement nourrit la peau mais possède également des propriétés calmantes, ce qui en fait un choix adapté aux peaux sensibles. Grâce aux enzymes de betterave rouge et à la poudre de coque de noix de coco, ce masque crémeux semblable à de l''argile ne se contente pas de purifier les pores, il dévoile également un grain de peau plus lisse et plus lumineux. Avec un temps d''application recommandé allant jusqu''à 15 minutes, ce masque purifiant élimine sans effort les impuretés et l''excès de sébum tout en maintenant l''équilibre hydrique de la peau, laissant derrière lui un teint rajeuni et éclatant. Recommandé pour : Peaux sèches. Conseils d''application : Après le nettoyage, applique sur le visage en évitant le contour des yeux et de la bouche. Après 10 à 15 minutes, rince soigneusement à l''eau tiède.', 120, 'g', 'im-from-beet-purifying-mask', 'https://korean-skincare.fr/products/im-from-beet-purifying-mask', 'https://aurore-cdn.b-cdn.net/products/im-from-beet-purifying-mask.webp', NULL, 1395, '2026-05-07 17:37:40.213504+00', '2026-06-14 15:14:07.64+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cbd-7c60-91a3-c84da190ff38', '__OWNER_ID__', 'Olive Vitamin E Real Cleansing Tissue', 'INNISFREE', 'cleanser', 'jar', 'Aqua, Isopropyl Palmitate, Cetyl Ethylhexanoate, Triethylhexanoin, Isododecane, Dipropylene Glycol, Pentaerythrityl Tetraethylhexanoate, 1,2-Hexanediol, Polysorbate 20, Caprylyl/Capryl Glucoside, Ethylhexylglycerin, Sodium Metaphosphate, Citric Acid, Olea Europaea Fruit Oil, Tocopherol', 'Le mouchoir en papier Innisfree Olive Vitamine E Real Cleansing Tissue (30 feuilles) est un démaquillant doux mais efficace, infusé d''huile d''olive et de vitamine E, conçu pour nettoyer la peau tout en préservant son équilibre hydrique. Sa formule douce dissout sans effort le maquillage et les impuretés, laissant la peau fraîche, nourrie et lisse sans aucun résidu gras. Enrichis en ingrédients hydratants et riches en antioxydants, ils aident à protéger et à revitaliser la peau. Parfaites pour un usage quotidien, elles permettent un nettoyage pratique et apaisant à tout moment et en tout lieu. Recommandé pour : Peaux sèches et normales.', NULL, NULL, 'innisfree-olive-vitamin-e-real-cleansing-tissue', 'https://korean-skincare.fr/products/innisfree-olive-vitamin-e-real-cleansing-tissue', 'https://aurore-cdn.b-cdn.net/products/innisfree-olive-vitamin-e-real-cleansing-tissue.webp', 'Passe la lingette délicatement sur ta peau pour la débarrasser du maquillage et des impuretés. Essuie en douceur le contour des yeux pour éviter que la formule ne pénètre dans tes yeux. Garde les lingettes recouvertes de l''autocollant refermable pour qu''elles restent humides.', 1590, '2026-05-07 17:37:38.493584+00', '2026-06-14 15:14:07.64+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-475a-728e-9d2a-c9342dca44f6', '__OWNER_ID__', 'H.C.T. Bubble Toner', 'MIXSOON', 'toner', 'pump', 'Aqua, Glycerin, Dipropylene Glycol, Diglycérine, Melaleuca Alternifolia Leaf Extract, Houttuynia Cordata Extract, Centella Asiatica Extract, Camellia Sinensis Leaf Water, Caprate de Polyglyceryl-4, Decyl Glucoside, Hydroxyacetophenone, Laurate de Polyglyceryl-10, Caprylyl Glycol, Coco-Glucoside, Ethylhexylglycerin, Disodium EDTA, Dipotassium Glycyrrhizate, 1,2-Hexanediol, Tocopherol', 'Découvre le H.C.T. Bubble Toner MIXSOON, un tonique mousse à bulles conçu spécifiquement pour les peaux à tendance acnéique. Formulé avec des ingrédients clés comme l''extrait de feuille de Melaleuca Alternifolia (arbre à thé), l''extrait d''Houttuynia Cordata et l''extrait de Centella Asiatica, ce tonique agit en synergie pour apaiser les peaux troublées et irritées. Sa texture mousse douce calme la peau sans provoquer d''irritation supplémentaire, laissant ton teint frais et revitalisé. Avec une formule douce mais efficace, il aide à rétablir l''équilibre de la peau tout en l''hydratant et en la nourrissant. Recommandé pour : Peaux à tendance acnéique, peaux sensibles, tous types de peaux.', 150, 'ml', 'mixsoon-h-c-t-bubble-toner', 'https://korean-skincare.fr/products/mixsoon-h-c-t-bubble-toner', 'https://aurore-cdn.b-cdn.net/products/mixsoon-h-c-t-bubble-toner.webp', 'Commence par nettoyer ta peau. Étale délicatement une quantité suffisante sur ta peau avec tes mains ou à l''aide d''un disque de coton, en évitant le contour des yeux et de la bouche. Tapote légèrement pour une absorption maximale.', 2375, '2026-05-07 17:37:41.210086+00', '2026-06-14 15:14:07.64+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-475c-737e-9422-4285cbd78584', '__OWNER_ID__', 'H.C.T. Mist', 'MIXSOON', 'mist', 'spray', 'Centella Asiatica Extract, Melaleuca Alternifolia Leaf Extract, Houttuynia Cordata Extract, Glycerin, Butylene Glycol, 1,2-Hexanediol, Aqua, Panthenol, Sodium Hyaluronate', 'La H.C.T. Mist MIXSOON offre une solution rafraîchissante aux peaux à tendance acnéique ou irritées, grâce à un mélange d''ingrédients apaisants et anti-acnéiques comme les extraits de feuilles d''arbre à thé, de Houttuynia Cordata et de cica. Enrichie de panthénol et d''acide hyaluronique, cette brume agit pour réparer et hydrater la peau, en maintenant les niveaux d''hydratation pour un teint revitalisé. Testée cliniquement pour être non irritante, elle apporte un soulagement instantané des irritations ou une hydratation rapide lorsqu''elle est vaporisée sur la peau entre les étapes de ta routine beauté. Grâce à sa formule en spray à fine brume, elle assure une application facile pour une expérience apaisante et hydratante, ce qui en fait un complément essentiel à toute routine beauté adaptée aux peaux à problèmes. Recommandé pour : Tous types de peaux.', 50, 'ml', 'mixsoon-h-c-t-mist', 'https://korean-skincare.fr/products/mixsoon-h-c-t-mist', 'https://aurore-cdn.b-cdn.net/products/mixsoon-h-c-t-mist.webp', 'Commence par nettoyer ta peau. Ferme les yeux et vaporise une quantité adéquate à 20 cm de ton visage. Tapote légèrement pour une absorption maximale.', 2895, '2026-05-07 17:37:41.212126+00', '2026-06-14 15:14:07.64+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-477e-782d-a4a3-1c9fdbb29e14', '__OWNER_ID__', 'Clean Lotus Water Calming Toner', 'Rovectin', 'toner', 'pump', 'Eau de Fleur de Nelumbo Nucifera, Aqua, Glycerin, Butylene Glycol, Propanediol, 1,2-Hexanediol, Betaine, Extrait de Fleur de Nelumbium Speciosum, Extrait de Feuille de Nelumbo Nucifera, Extrait de Racine de Nelumbo Nucifera, Glycéryl Glucoside, Xylitylglucoside, Anhydroxylitol, Xylitol, Glucose, Allantoin, Huile de Juniperus Mexicana, Sodium Hyaluronate, Hydroxypropyl Trimonium Hyaluronate, Extrait de Cynanchum Atratum, Extrait d''Écorce de Magnolia Kobus, Hydrolyzed Hyaluronic Acid, Sodium Acetylated Hyaluronate, Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Potassium Hyaluronate, C12-14 Pareth-12, Ethylhexylglycerin, Gomme Xanthane, Citric Acid, Disodium EDTA, Sodium Citrate', 'Le Clean Lotus Water Calming Toner ROVECTIN est un tonique rafraîchissant et apaisant qui aide à calmer et à hydrater ta peau. Formulé avec de l''eau de lotus, un puissant antioxydant connu pour ses propriétés anti-inflammatoires, ce tonique aide à apaiser la peau irritée et à réduire les rougeurs. En plus de l''eau de lotus, ce tonique contient également de la Centella Asiatica et de l''hamamélis, deux ingrédients naturels qui agissent ensemble pour resserrer les pores et améliorer la texture de la peau. La Centella Asiatica est connue pour sa capacité à apaiser et à réparer les peaux abîmées, tandis que l''hamamélis est un astringent naturel qui aide à contrôler la production de sébum et à réduire l''inflammation. Le Clean Lotus Water Calming Toner ROVECTIN est exempt de produits chimiques agressifs comme les parabènes, les sulfates et les parfums artificiels, ce qui le rend suffisamment doux pour les peaux les plus sensibles.', 120, 'ml', 'rovectin-clean-lotus-water-calming-toner', 'https://korean-skincare.fr/products/rovectin-clean-lotus-water-calming-toner', 'https://aurore-cdn.b-cdn.net/products/rovectin-clean-lotus-water-calming-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Sinon, distribue le produit sur le bout de tes doigts. Tapote délicatement ta peau jusqu''à ce que le produit soit absorbé.', 2346, '2026-05-07 17:37:41.246379+00', '2026-06-14 15:14:07.64+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64ec-7de5-8d78-589115413c04', '__OWNER_ID__', '1025 Dokdo Cleanser', 'Round Lab', 'cleanser', 'tube', '1,2-Hexanediol, ALANINE, Allantoin, ARGININE, Beta-Glucan, Butylene Glycol, Caprylic/Capric Triglyceride, Ceramide NP, Chamomilla Recutita Flower Oil, Citric Acid, Coco-Betaine, Disodium EDTA, Ethylhexylglycerin, Fructooligosaccharides, Glutamic Acid, Glycerin, GLYCINE, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Lysine, Sea Water, Panthenol, Lecithin, POLYQUATERNIUM-67, POTASSIUM BENZOATE, POTASSIUM COCOATE, POTASSIUM COCOYL GLYCINATE, PROLINE, Pullulan, SACCHARIDE HYDROLYSATE, SERINE, SODIUM ACETATE, Sodium Chloride, Sodium Cocoyl Isethionate, Sodium Hyaluronate, SODIUM METHYL COCOYL TAURATE, THREONINE, Aqua', 'Un nettoyant moussant doux qui retire les poussières fines et impuretés sans tirailler la peau.', 150, 'ml', 'round-lab-1025-dokdo-cleanser', 'https://www.skinsafeproducts.com/round-lab-1025-dokdo-cleanser-150ml-moisturizing-cleansing-gentle-bubbly-foam-cleanser-150ml', 'https://aurore-cdn.b-cdn.net/products/round-lab-1025-dokdo-cleanser.webp', 'Eau de mer profonde et Acide Hyaluronique, convient à tous les types de peaux, même sensibles.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.675+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43fa-78a4-8491-a244815a6fc3', '__OWNER_ID__', 'Scalp DX Scaling Shampoo', 'Dr. Ceuracle', 'shampoo', 'jar', 'Aqua, Disodium Laureth Sulfosuccinate, Cocamidopropyl Hydroxysultaine, Lauryl Glucoside, Parfum, Sodium Chloride, Styrene/Acrylates Copolymer, Alcool Cetyl, Cocamide MIPA, Menthol, Sodium Cocoyl Isethionate, Panthenol, Polyquaternium-10, Potassium Sorbate, Salicylic Acid, Trihydroxystéarate, Citric Acid, Betaine, Niacinamide, Acide de Coco, Disodium EDTA, Sodium Isethionate, Alcohol Denat, Panthenyl Ethyl Ether, Inositol, Phenoxyethanol, Sodium Citrate, Lactic Acid, Lactose, Protéine de Lait, Déhydroacétate de Sodium, Glycerin, Acétyl Cystéine, Acétyl Méthionine, Arginine, Biotin, Panax Ginseng Root Extract, Dipropylene Glycol, Hydroxyacetophenone, Caprylyl Glycol, 1,2-Hexanediol, Houttuynia Cordata Extract, Butylene Glycol, Extrait de Salvia Officinalis, Extrait de Racine d’Angelica Gigas, Extrait de Chamomilla Recutita, Extrait de Feuille de Gaultheria Procumbens, Extrait de Graine de Glycine Soja, Extrait de Jasminum Officinale, Extrait de Lavandula Angustifolia, Extrait de Mentha Piperita, Extrait d’Écorce de Morus Alba, Extrait de Feuille d’Origanum Majorana, Extrait de Racine de Polygonum Multiflorum, Extrait de Saccharomyces Cerevisiae, Extrait de Thymus Vulgaris, Extrait de Fruit de Ziziphus Jujuba, Extrait de Racine d’Acorus Calamus, Extrait de Graine d’Adansonia Digitata, Camellia Japonica Flower Extract, Euterpe Oleracea Fruit Extract, Laminaria Japonica Extract, Extrait de Fruit de Malpighia Emarginata, Extrait de Graine de Moringa Oleifera, Extrait de Fleur de Nelumbo Nucifera, Extrait de Propolis, Prunus Persica Fruit Extract, Extrait de Fruit de Prunus Serotina, Extrait de Fleur de Prunus Serrulata, Pyrus Malus Fruit Extract, Dipotassium Glycyrrhizate', 'Le Scalp DX Scaling Shampoo Dr. Ceuracle est formulé pour nettoyer et revitaliser en profondeur le cuir chevelu, éliminant les accumulations, l’excès de sébum et les impuretés pouvant obstruer les pores et provoquer des irritations. Enrichi en ingrédients exfoliants doux mais efficaces, ce shampooing aide à apaiser les cuirs chevelus sensibles tout en favorisant un environnement équilibré pour une croissance capillaire plus saine. Ses extraits botaniques calmants réduisent rougeurs et desquamation, laissant le cuir chevelu frais, revitalisé et confortable après chaque lavage. Idéal pour les cuirs chevelus présentant des problèmes tels que pellicules, démangeaisons ou excès de sébum, ce shampooing offre un nettoyage complet sans dépouiller le cuir chevelu de son hydratation essentielle. Une utilisation régulière soutient la barrière naturelle du cuir chevelu, prévenant la sécheresse. Que ton cuir chevelu soit gras, sensible ou mixte, le Scalp DX Scaling Shampoo Dr. Ceuracle est l’étape parfaite pour restaurer la clarté du cuir chevelu et préparer tes cheveux à une santé et vitalité optimales. Recommandé pour : Pellicules, démangeaisons, excès de sébum et perte de cheveux.', 500, 'ml', 'dr-ceuracle-scalp-dx-scaling-shampoo', 'https://korean-skincare.fr/products/dr-ceuracle-scalp-dx-scaling-shampoo', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-scalp-dx-scaling-shampoo.webp', 'Mouille soigneusement tes cheveux et ton cuir chevelu. Applique une quantité appropriée de shampooing et masse délicatement ton cuir chevelu avec tes doigts, en insistant sur les zones présentant des dépôts ou des irritations. Laisse agir 2 à 3 minutes pour permettre aux ingrédients actifs de pénétrer en profondeur. Rince abondamment à l’eau tiède. Pour de meilleurs résultats, utilise 2 à 3 fois par semaine ou selon les besoins, suivi de ton après-shampooing ou traitement capillaire habituel.', 2395, '2026-05-07 17:37:40.346476+00', '2026-06-14 15:14:07.641+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64de-796b-893b-01e365ffb9df', '__OWNER_ID__', 'Atobarrier 365 Hydro Soothing Cream', 'Aestura', 'moisturizer', 'tube', '1,2-Hexanediol, Allantoin, Arachidic Acid, ARGININE, BEHENIC ACID, Butylene Glycol, C12-20 ALKYL GLUCOSIDE, C14-22 Alcohols, Caprylic/Capric Triglyceride, Carbomer, Cetyl Ethylhexanoate, Cholesterol, Dicaprylyl Carbonate, Disodium EDTA, Ethylhexylglycerin, Glycerin, Glyceryl Caprylate, Hydrogenated Poly(C6-14 Olefin), HYDROXYPROPYL BISLAURAMIDE MEA, Myristic Acid, Oleic Acid, Palmitic Acid, Propanediol, Sodium Hyaluronate, Stearic Acid, Tocopherol, Aqua', 'Crème hydratante apaisante à la texture légère, idéale pour hydrater les peaux mixtes à grasses sans laisser de fini gras.', 60, 'ml', 'aestura-atobarrier-365-hydro-soothing-cream-60-ml', 'https://www.skinsafeproducts.com/aestura-atobarrier-365-hydro-soothing-cream-60-ml', 'https://aurore-cdn.b-cdn.net/products/aestura-atobarrier-365-hydro-soothing-cream-60-ml.webp', 'Arginine + Allantoin + Glycérine + Hyaluronate de Sodium — Parfait pour peaux déshydratées cherchant de la légèreté.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.641+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3e7b-7945-9576-d7c64e292094', '__OWNER_ID__', 'Dare Body Moisturizing Wash', 'MISSHA', 'body-wash', 'jar', 'Aqua, Disodium Cocoamphodiacetate, Sodium Methyl Cocoyl Taurate, Sodium Chloride, Coco-Glucoside, Glycerin, Parfum, 1,2-Hexanediol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Styrene/Acrylates Copolymer, Citric Acid, Tromethamine, Panthenol, Disodium EDTA, Hexylene Glycol, Butylene Glycol, 1-Methylhydantoin-2-Imide, Glycine, Glucosamine HCl, Glutamic Acid, Glutamine, Dipotassium Phosphate, Lysine, Leucine, Magnesium Citrate, Magnesium Chloride, Magnesium PCA, Methionine, Valine, Serine, Sucrose, Cysteine, Citrulline, Sea Salt, Asparagine, Aspartic Acid, Isoleucine, Alanine, Arginine, Copper Tripeptide-1, Calcium Chloride, Taurine, Tyrosine, Threonine, Tryptophan, Phenylalanine, Proline, Histidine, Ethylhexylglycerin, Hydroxyacetophenone, Formic Acid, Hexyl Cinnamal, Alpha-Isomethyl Ionone, Citronellol, Linalool', 'Le Dare Body Moisturizing Wash MISSHA est un nettoyant corporel doux et respectueux de ta peau qui transforme ta douche en un véritable rituel sensoriel de soin. Enrichi en ingrédients hydratants comme la glycérine et des extraits végétaux, il crée une mousse douce et crémeuse qui élimine efficacement les impuretés tout en laissant ta peau nourrie et lisse. Ce gel douche enveloppe ta peau d’un parfum durable et d’hydratation. Le Dare Body Moisturizing Wash MISSHA est parfait pour une utilisation quotidienne et laisse ta peau propre, hydratée et confortable, avec un fini aussi agréable que son parfum. Recommandé pour : Tous types de peaux.', 500, 'ml', 'missha-dare-body-moisturizing-wash', 'https://korean-skincare.fr/products/missha-dare-body-moisturizing-wash', 'https://aurore-cdn.b-cdn.net/products/missha-dare-body-moisturizing-wash.webp', 'Dépose une quantité adéquate de produit sur une éponge de douche ou dans tes mains. Fais mousser abondamment et masse délicatement sur ta peau humide. Rince soigneusement à l’eau tiède.', 1895, '2026-05-07 17:37:38.939431+00', '2026-06-14 15:14:07.641+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4538-762d-8af8-4de8cad985e7', '__OWNER_ID__', 'Super Matcha Pore Tightening Toner', 'SOME BY MI', 'toner', 'pump', 'Camellia Sinensis Leaf Extract, Propanediol, Salix Alba Bark Extract, Niacinamide, 1,2-Hexanediol, Silicate de Lithium Magnésium Sodium, Chlorure de Calcium, Silica, Sodium Citrate, Laurate de Polyglycérine-10, Myristate de Polyglycérine-10, Ethylhexylglycerin, Adenosine, Glycerin, Citric Acid, Disodium EDTA, Parfum, Centella Asiatica Extract, Eau de Glacier, Eau Gazeuse, Melaleuca Alternifolia Leaf Water, Houttuynia Cordata Extract, Butylene Glycol, Madecassoside, Aqua, Asiaticoside, Acide Asiatique, Acide Madecassique, Glyceryl Caprylate, Hexyl Cinnamal', 'Le Super Matcha Pore Tightening Toner Some By Mi est une lotion liquide-poudre biphasée (à mélanger avant l''emploi) enrichie d''eau de matcha et d''ingrédients en poudre brevetés qui régulent la production de sébum. Ce tonique contient également un complexe d''ingrédients apaisants composé d''extrait d''écorce de saule, d''arbre à thé, de Centella Asiatica et d''Houttuynia Cordata qui aident à apaiser et à contrôler l''acné.', 150, 'ml', 'some-by-mi-super-matcha-pore-tightening-toner', 'https://korean-skincare.fr/products/some-by-mi-super-matcha-pore-tightening-toner', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-super-matcha-pore-tightening-toner.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 1578, '2026-05-07 17:37:40.664231+00', '2026-06-14 15:14:07.641+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4357-7364-892e-93a631f099b6', '__OWNER_ID__', 'Ginseng Mask', 'I''m From', 'mask', 'pack', 'Glycerin, Panax Ginseng Root Extract, Butylene Glycol, Huile de Graine de Panax Ginseng, Glycyrrhiza Uralensis Root Extract, Extrait de Racine de Paeonia Albiflora, Extrait de Racine d''Angelica Gigas, Extrait de Racine de Rheum Palmatum, Extrait de Racine d''Angelica Pubescens, Extrait de Schizonepeta Tenuifolia, Phellodendron Amurense Bark Extract, Extrait de Malt, Glycosaminoglycanes Hydrolysés, Hyaluronic Acid, Extrait de Résine de Boswellia Serrata, 1,2-Hexanediol, Aqua, Ethylhexylglycerin, PEG-60 Huile de Ricin Hydrogénée, Isohexadecane, Polysorbate 80, Sodium Acrylate/Sodium Acryloyldimethyl Taurate Copolymer', 'Le Ginseng Mask I''m From est un traitement luxueux infusé de la puissance concentrée de ginseng rouge coréen âgé de 6 ans, visant à revitaliser ta peau, la laissant souple, lumineuse et profondément nourrie. Enrichi de 3,97 % d''extrait de ginseng rouge et d''huile de graines de Panax Ginseng, ce masque à rincer de première qualité cible efficacement divers problèmes de peau. Les propriétés riches en antioxydants du ginseng facilitent le renouvellement cellulaire et la détoxification des pores, tout en reconstituant l''élasticité et la fermeté de la peau. La formulation du masque, exempte d''additifs nocifs et de parfum, agit pour atténuer les ridules, les rides et les imperfections de la peau, révélant un teint raffiné et plus clair. Sa consistance épaisse élimine efficacement les cellules mortes et les impuretés, favorisant l''équilibre optimal du ratio huile/eau de ta peau. Ce masque est un luxe ultime pour toutes les personnes qui cherchent à rajeunir leur peau, en particulier pour les peaux ternes, sèches ou fatiguées, les teints inégaux, les problèmes de vieillissement prématuré ou les problèmes d''éclat. Exploitant les bienfaits du ginseng rouge coréen, de l''acide hyaluronique, de la niacinamide et d''autres ingrédients clés, il procure une hydratation intense, équilibre le teint de la peau, possède des propriétés anti-âge et améliore l''élasticité de la peau. Le masque est méticuleusement formulé sans parabènes, sulfates, phtalates, parfums artificiels ou colorants, ce qui garantit une solution de soin sûre et efficace. Profite de ses bienfaits anti-âge en l''appliquant uniformément, pour améliorer l''éclat et la vitalité de ta peau et transcender ta routine beauté. Recommandé pour : Peaux sensibles, tous types de peaux.', 120, 'g', 'im-from-ginseng-mask', 'https://korean-skincare.fr/products/im-from-ginseng-mask', 'https://aurore-cdn.b-cdn.net/products/im-from-ginseng-mask.webp', 'Après le nettoyage, applique sur ton visage, en évitant le contour des yeux et de la bouche. Après 5 à 10 minutes, rince abondamment à l''eau tiède. * La viscosité du masque peut varier en fonction de la température ambiante. Si la consistance du masque devient trop grossière, adoucis la texture du bout de tes doigts légèrement humides pour faciliter l''application.', 3495, '2026-05-07 17:37:40.183023+00', '2026-06-14 15:14:07.642+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c09-7f17-8030-3d663368965f', '__OWNER_ID__', 'The Retinol 0.1 Cream', 'COSRX', 'moisturizer', 'jar', 'Aqua, Caprylic/Capric Triglyceride, Propanediol, Glycerin, Tocopheryl Acetate, Cetearyl Alcohol, Trehalose, Panthenol, Butyrospermum Parkii Butter, Glycine Soja Oil, Ammonium Acryloyldimethyltaurate/VP Copolymer, Dimethicone, Polyméthacrylate de Glycéryle, Helianthus Annuus Seed Oil, Stéarate de Polyglycéryl-10, Hydrogenated Lecithin, Copolymère d''Acrylate d''Hydroxyéthyle/Sodium Taurate de Diméthyl, Carbomer, Tromethamine, Glyceryl Stearate, Polysiloxane-11, Sulfite de Sodium, Tocopherol, Daucus Carota Sativa Root Extract, Retinol, Allantoin, Glyceryl Caprylate, Cire de Son de Riz Oryza Sativa, Tocotriénols, Stearic Acid, Distéarate de Methylglucose Polyglycéryl-3, Palmitic Acid, Disodium EDTA, Éthylhexylglycérol, Adenosine, Sorbitan Isostearate, Huile d''Elaeis Guineensis, BHT, Bêta-Carotène, Myristic Acid, Lauric Acid, Ascorbic Acid, Limnanthes Alba Seed Oil, 3-O-Ethyl Ascorbic Acid, Glutathione, Sodium Hyaluronate, 1,2-Hexanediol, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hyaluronic Acid, Sodium Acetylated Hyaluronate', 'La Retinol 0.1 Cream COSRX aide à obtenir une peau jeune et radieuse. Cette crème puissante est formulée avec 0,1 % de rétinol pur, connu pour sa capacité à stimuler l''élasticité de la peau, à atténuer les rides et à redonner de l''éclat à la peau. Conçue pour cibler les signes du vieillissement cutané, notamment les crevasses, la perte de fermeté de la peau et la rugosité, cette crème pour le visage regorge d''ingrédients actifs qui constituent une puissante solution anti-âge. En plus du rétinol pur, sa formule comprend du panthénol pour atténuer les irritations, de l''adénosine pour bannir l''affaissement de la peau et du tocotriénol (une forme de vitamine E) pour lutter contre les radicaux libres. La Retinol 0.1 Cream est spécialement conçue pour être utilisée la nuit, ce qui permet aux puissants ingrédients d''opérer leur magie pendant que tu dors. Avec une utilisation régulière, cette crème aide à atténuer les rides et les ridules, te laissant une apparence plus jeune et rajeunie.', 20, 'ml', 'cosrx-the-retinol-0-1-cream', 'https://korean-skincare.fr/products/cosrx-the-retinol-0-1-cream', 'https://aurore-cdn.b-cdn.net/products/cosrx-the-retinol-0-1-cream.webp', 'Après avoir utilisé une essence ou un sérum, tapote une petite quantité de produit à l''aide de ton annulaire. Applique uniformément sur ton visage, ton cou et sur les zones concernées par les rides. Limite l''utilisation initiale à trois fois par semaine ; augmente graduellement la fréquence jusqu''à un soir sur deux, en fonction de ta tolérance. *Laisse-toi une "période d''adaptation" lors de l''utilisation du rétinol*. SEMAINE 1~2 - Fréquence : utiliser tous les deux jours le soir. - Mode d''emploi : après le nettoyage, à l''étape de la crème hydratante, applique une petite quantité de produit sur les zones concernées. - Par exemple, sous les yeux, autour de la bouche, sur le front et le cou. (Quantité recommandée : 0,1 ml par section / 1 grain de riz) SEMAINE 3 ~ - Fréquence : peut être appliqué tous les soirs. - Mode d''emploi : Après le nettoyage, lors de l''étape de la crème hydratante, étale le produit sur l''ensemble de ton visage. * La phase de "développement de la tolérance" peut être raccourcie ou prolongée en fonction des différences individuelles. * Maintenir cette phase jusqu''à ce qu''aucune gêne ne soit ressentie. * Augmenter progressivement la fréquence et les zones d''application.', 2454, '2026-05-07 17:37:38.313863+00', '2026-06-14 15:14:07.642+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c21-7ea5-92bd-4e4c6566b70b', '__OWNER_ID__', 'Pure Fit Cica Calming True Sheet Mask', 'COSRX', 'mask', 'pack', 'Aqua, Butylene Glycol, Glycerin, Alcohol, Betaine, Centella Asiatica Extract, Gomme de Xanthane, Paeonia Suffruticosa Root Extract, 1,2-Hexanediol, Laurate de Polyglyceryl-10, Chamomilla Recutita (Matricaria) Flower Extract, Glyceryl Caprylate, Panthenol, Ethylhexylglycerin, Disodium EDTA, Eucalyptus Globulus Leaf Oil, Extrait de Feuille de Centella Asiatica, Melaleuca Alternifolia Leaf Oil, Hydrogenated Lecithin, Diéthylhexyl Sodium Sulfosuccinate, Caprylic/Capric Triglyceride, Stéarate de Sucrose, Pantolactone, Dipropylene Glycol, Asiaticoside, Acide Asiatic, Acide Madécassique, Cholesterol, Madecassoside, Extrait de Racine de Centella Asiatica', 'Le Cica Calming True Sheet Mask COSRX truffé d''ingrédients Pure Fit Cica offre un soin apaisant intensif aux peaux sensibles et fragilisées. Avec 7 ingrédients centella riches en antioxydants, il délivre un triple effet calmant pour renforcer, apaiser et protéger les peaux irritées. Sa texture aqueuse légère assure un confort optimal tandis que ses principes actifs pénètrent rapidement sans coller ni stimuler la peau.', 1, 'pcs', 'cosrx-pure-fit-cica-calming-true-sheet-mask', 'https://korean-skincare.fr/products/cosrx-pure-fit-cica-calming-true-sheet-mask', 'https://aurore-cdn.b-cdn.net/products/cosrx-pure-fit-cica-calming-true-sheet-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 395, '2026-05-07 17:37:38.337644+00', '2026-06-14 15:14:07.642+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c3e-71b9-b34f-efa06ca82539', '__OWNER_ID__', 'Pure Fit Cica Cream Intense', 'COSRX', 'moisturizer', 'jar', 'Centella Asiatica Extract, Extrait de Feuille de Centella Asiatica, Extrait de Racine de Centella Asiatica, Butylene Glycol, Cetyl Alcohol, Helianthus Annuus Seed Oil, Caprylic/Capric Triglyceride, Glycerin, Olivate de Cétylérine, 1,2-Hexanediol, Sorbitan Olivate, Macadamia Ternifolia Seed Oil, Panthenol, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Ethylhexylglycerin, Cera Alba, Arginine, Carbomer, Asiaticoside, Acide Madécassique, Acide Asiatique, Huile de Centella Asiatica, Madecassoside, Allantoin, Sodium Hyaluronate, Glycine Soja Oil, Aqua, Extrait d''Écorce de Pinus Pinaster', 'La Pure Fit Cica Cream Intense COSRX est un soin excellent pour les peaux sensibles qui ont besoin d''une hydratation intense et d''effets apaisants. Enrichie de 61,2 % de complexe Cica-7 et de 1 000 ppm d''huile de cica, cette crème offre des ingrédients puissants qui agissent ensemble pour offrir protection et nutrition à ta peau. La texture épaisse et crémeuse de la Pure Fit Cica Cream Intense COSRX est conçue pour pénétrer profondément dans la peau sans laisser de fini gras. Elle renforce et répare la peau, la restaurant à son état d''origine en fournissant une barrière qui protège contre les agresseurs externes et la perte en hydratation. Testée dermatologiquement pour être hypoallergénique et adaptée aux peaux sensibles, cette crème est un must pour tous ceux qui souffrent de sécheresse, de rougeurs ou d''irritations. Son puissant mélange d''ingrédients apporte un soulagement immédiat et une hydratation durable, laissant ta peau douce, souple et revitalisée.', 50, 'ml', 'cosrx-pure-fit-cica-cream-intense', 'https://korean-skincare.fr/products/cosrx-pure-fit-cica-cream-intense', 'https://aurore-cdn.b-cdn.net/products/cosrx-pure-fit-cica-cream-intense.webp', 'Applique une quantité adéquate de produit uniformément sur ton visage lors de la dernière étape de ta routine beauté. Fais-le pénétrer délicatement dans ta peau pour une meilleure absorption.', 1957, '2026-05-07 17:37:38.366013+00', '2026-06-14 15:14:07.642+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3d8d-7604-b2f3-2fb917b9ef52', '__OWNER_ID__', 'Velvet Finish Cushion SPF50+ PA+++', 'MISSHA', 'moisturizer', 'jar', 'Aqua, Cyclopentasiloxane, Titanium Dioxide CI 77891, Ethylhexyl Methoxycinnamate, Methyl Methacrylate Crosspolymer, Methyl Trimethicone, Ethylhexyl Salicylate, Glycerin, Lauryl PEG-10 Tris Silylethyl Dimethicone, Niacinamide, Pentylene Glycol, Butylene Glycol, Chamaecyparis Obtusa Water, Centella Asiatica Leaf Extract, Melissa Officinalis Leaf Extract, Aloe Barbadensis Leaf Extract, Aspalathus Linearis Extract, Camellia Sinensis Leaf Extract, Chrysanthemum Indicum Flower Extract, Jasminum Officinale Flower Extract, Rosmarinus Officinalis Extract, Thymus Vulgaris Extract, Allium Cepa Bulb Extract, Gelidium Cartilagineum Extract, Salvia Officinalis Extract, Cetyl Ethylhexanoate, PEG-10Dimethicone, Silica, Magnesium Sulfate, Vinyl Dimethicone/Methicone Silsesquioxane Crosspolymer, Bis-PEG-15 Methyl Ether Dimethicone, Cetearyl Dimethicone/Vinyl Dimethicone Crosspolymer, Disteardimonium Hectorite, Stearic Acid, Alumina, Aluminum Hydroxide, Triethoxycaprylylsilane, Ethylhexylglycerin, Adenosine, 1,2-Hexanediol, Disodium EDTA, Phenoxyethanol, Parfum, Benzyl Alcohol, Citronellol, Benzyl Benzoate, Coumarin, Geraniol, Amyl Cinnamal, Linalool, Limonene, Alpha-Isomethyl Ionone, Iron Oxides CI 77492, Iron Oxides CI 77491, Iron Oxides CI 77499', 'The Missha Velvet Finish Cushion SPF50+ PA+++ is a long-lasting sheer velvet cushion. The soft, light texture makes it easy to apply thinly and evenly, but also helps to cover blemishes. The key ingredients centella and rosemary work to soothe and moisturize the skin. How to use: Take an appropriate amount on the puff and apply it on face. For best results, tap lightly across the face, avoiding the eye areas.', 15, 'g', 'missha-velvet-finish-cushion-spf50-pa', 'https://korean-skincare.fr/products/missha-velvet-finish-cushion-spf50-pa', 'https://aurore-cdn.b-cdn.net/products/missha-velvet-finish-cushion-spf50-pa.webp', NULL, 1995, '2026-05-07 17:37:38.701178+00', '2026-06-14 15:14:07.643+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3d4c-708e-9309-7287d3191287', '__OWNER_ID__', 'Airy Fit Sheet Mask', 'MISSHA', 'mask', 'pack', 'Red Ginseng : Water, Glycerin, Dipropylene Glycol, Cetyl Ethylhexanoate, 1,2-Hexanediol, Stearic Acid, Sorbitan Sesquioleate, Cetearyl Alcohol, Sorbitan Stearate, Glyceryl Stearate, Carbomer, Arginine, Butylene Glycol, Caprylic/Capric Triglyceride, Coptis Japonica Root Extract, Glycyrrhiza Glabra Licorice Root Extract, Zingiber Officinale Ginger Root Extract, Camellia Sinensis Leaf Extract, Trehalose, Ethylhexylglycerin, Cellulose Gum, Xanthan Gum, Disodium EDTA, Dipotassium Glycyrrhizate, Olea Europaea Olive Fruit Oil, Sodium Hyaluronate, Panax Ginseng Root Extract, Salvia Sclarea Clary Oil, Pogostemon Cablin Oil, Apium Graveolens Celery Seed Oil, Copaifera Officinalis Balsam Copaiba Resin, Daucus Carota Sativa Carrot Seed Oil, Eucalyptus Globulus Leaf Oil, Citrus Aurantium Dulcis Orange Oil Pomegranate : Water, Dipropylene Glycol, Butylene Glycol, 1,2-Hexanediol, Hydroxyethylcellulose, Glycerin, Carbomer, Arginine, Coptis Japonica Root Extract, Glycyrrhiza Glabra Licorice Root Extract, Zingiber Officinale Ginger Root Extract, Camellia Sinensis Leaf Extract, Ethylhexylglycerin, Allantoin, Disodium EDTA, Polyglyceryl-10 Myristate, Polyglyceryl-10 Laurate, Punica Granatum Fruit Extract, Trehalose, Dipotassium Glycyrrhizate, Sodium Hyaluronate, Olea Europaea Olive Fruit Oil, Glyceryl Acrylate/Acrylic Acid Copolymer, Citrus Nobilis Mandarin Orange Peel Oil, PVM/MA Copolymer, Pelargonium Graveolens Oil, Citrus Aurantium Dulcis Orange Oil, Litsea Cubeba Fruit Oil, Lavandula Angustifolia Lavender Oil Honey : Water, Dipropylene Glycol, Butylene Glycol, 1,2-Hexanediol, Hydroxyethylcellulose, Glycerin, Carbomer, Arginine, Coptis Japonica Root Extract, Glycyrrhiza Glabra Licorice Root Extract, Zingiber Officinale Ginger Root Extract, Camellia Sinensis Leaf Extract, Ethylhexylglycerin, Allantoin, Citrus Aurantium Bergamia Bergamot Fruit 