INSERT INTO public.products VALUES ('019de0ab-64ed-762d-965f-e3abef1e740b', '__OWNER_ID__', 'Birch Juice Moisturizing Cream', 'Round Lab', 'moisturizer', 'jar', '1,2-Hexanediol, Acacia Senegal Gum, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, AGAR, ALOE BARBADENSIS FLOWER EXTRACT, Ammonium Acryloyldimethyltaurate/VP Copolymer, Ascorbic Acid, BETULA PLATYPHYLLA JAPONICA JUICE, Butylene Glycol, Coccinia Indica Fruit Extract, CORALLINA OFFICINALIS EXTRACT, Curcuma Longa Root Extract, Dipotassium Glycyrrhizate, Disodium EDTA, Ethylhexylglycerin, Glycerin, GLYCERYL ACRYLATE/ACRYLIC ACID COPOLYMER, Glyceryl Caprylate, GLYCERYL GLUCOSIDE, Hyaluronic Acid, HYDROLYZED HIBISCUS ESCULENTUS EXTRACT, Isododecane, Isononyl Isononanoate, Jojoba Esters, LUPINUS ALBUS SEED EXTRACT, MELIA AZADIRACHTA FLOWER EXTRACT, Melia Azadirachta Leaf Extract, MORINGA OLEIFERA SEED EXTRACT, Ocimum Sanctum Leaf Extract, Panthenol, Pentaerythrityl Tetraethylhexanoate, Pentylene Glycol, POLYDECENE, POLYGLYCERYL-3 METHYLGLUCOSE DISTEARATE, Sodium Hyaluronate, Solanum Melongena Fruit Extract, Tromethamine, Aqua', 'Une crème hydratante profonde qui forme une barrière protectrice pour maintenir l''eau dans les tissus.', 80, 'ml', 'round-lab-birch-juice-moisturizing-cream', 'https://www.skinsafeproducts.com/round-lab-birch-juice-moisturizing-cream-unscented-48-2-71fl-oz', 'https://aurore-cdn.b-cdn.net/products/round-lab-birch-juice-moisturizing-cream.webp', 'Sève de bouleau et esters de Jojoba, idéale pour les peaux normales à sèches.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.676+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3bfd-7682-98a3-65245d0c6898', '__OWNER_ID__', 'Aloe Soothing Sun Cream SPF50+ PA+++', 'COSRX', 'moisturizer', 'jar', 'Aqua, Ethylhexyl Methoxycinnamate, Glycerin, Propylene Glycol, Cyclopentasiloxane, Ensulizole, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Dicaprylyl Carbonate, Méthoxycinnamate d''Isoamyle, Phosphate de Cétyle Potassique, Alcohol, Dimethicone, Butylene Glycol, Glyceryl Stearate, Titanium Dioxide, Alcools C14-22, Méthacrylate de Polyméthyle, Cetyl Alcohol, PEG-100 Stearate, Triethanolamine, Silica, Sodium Hydroxide, Polymère Croisé de Diméthicone/Vinyl Diméthicone, Glucoside C12-20 Alkyle, Hydroxyde d''Aluminium, Stearic Acid, Parfum, Caprylyl Glycol, Phenoxyethanol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Extrait de Feuille d''Aloe Arborescens, Dipotassium Glycyrrhizate, Carbomer, Gomme Xanthane, Limonene, Tocopheryl Acetate, Disodium EDTA, Hexyl Cinnamal, Linalool, Benzyl Salicylate, Geraniol, Benzyl Alcohol, Citronellol, Benzyl Benzoate, Citral', 'Fais l''expérience d''une protection solaire ultime avec l''Aloe Soothing Sun Cream SPF50+/ PA+++. Cette formule légère et hydratante est soigneusement élaborée avec un mélange d''ingrédients nourrissants pour protéger ta peau des rayons UV nocifs. Formulée avec des extraits botaniques apaisants, notamment l''aloès, l''onagre et l''arbre à thé, elle calme et nourrit ta peau, lui donnant une sensation de fraîcheur et de protection. Avec son indice de protection élevé (SPF50), cette crème solaire est ton compagnon idéal de soin quotidien contre le soleil. Embrasse le soleil tout en préservant la santé et l''éclat de ta peau grâce à l''Aloe Soothing Sun Cream SPF50. Recommandé pour : Tous types de peaux.', 50, 'ml', 'cosrx-aloe-soothing-sun-cream', 'https://korean-skincare.fr/products/cosrx-aloe-soothing-sun-cream', 'https://aurore-cdn.b-cdn.net/products/cosrx-aloe-soothing-sun-cream.webp', 'Applique une quantité généreuse sur ton visage 30 minutes avant de sortir au soleil. Renouvelle l''application au besoin pour une protection solaire parfaite tout au long de la journée.', 1337, '2026-05-07 17:37:38.30132+00', '2026-06-14 15:14:07.676+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64ef-7731-b3cf-0ad80c566eef', '__OWNER_ID__', 'Brightening All In One Cleanser Yuja Niacin', 'Some By Mi', 'cleanser', 'bottle', '1,2-Hexanediol, 3-0-ETHYL ASCORBIC ACID, ACRYLATES COPOLYMER, BENZYL GLYCOL, BETA-CAROTENE, Biotin, Caprylyl Glycol, Citric Acid, Citrus Junos Fruit Extract, Cocamidopropyl Betaine, Cyanocobalamin, Disodium EDTA, ERIOBOTRYA JAPONICA LEAF EXTRACT, Ethylhexylglycerin, FOLIC ACID, Parfum, Gluconolactone, Glycerin, HEXADECENE, Hyaluronic Acid, Hydrogenated Lecithin, HYDROLYZED GLYCOSAMINOGLYCANS, Hydrolyzed Hyaluronic Acid, Inositol, Limonene, Linalool, LINOLEIC ACID, MENTHA VIRIDIS (SPEARMINT) EXTRACT, Niacinamide, Panthenol, POLYGLYCERYL-10 STEARATE, Propanediol, PYRIDOXINE, RASPBERRY KETONE, RIBOFLAVIN, Saccharide Isomerate, Sodium Acetylated Hyaluronate, Sodium Ascorbyl Phosphate, Sodium C14-16 Olefin Sulfonate, Sodium Chloride, Sodium Citrate, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, SUCCINIC ACID, TETRADECENE, THIAMINE HCL, Tocopherol, Aqua, XANTHAN GUM', 'Nettoyant tout-en-un qui purifie, illumine et hydrate la peau en une seule étape.', 100, 'ml', 'some-by-mi-brightening-all-in-one-cleanser-yuja-niacin', 'https://www.skinsafeproducts.com/some-by-mi-brightening-all-in-one-cleanser-yuja-niacin-3-38-fl-oz-100-ml', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-brightening-all-in-one-cleanser-yuja-niacin.webp', 'Enrichi en Niacinamide, Acide Ascorbyl Phosphate de Sodium et Acide Hyaluronique — idéal pour les peaux ternes cherchant éclat et hydratation.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.676+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64ef-79e5-bf29-c678edbd824b', '__OWNER_ID__', 'Galactomyces Pure Vitamin C Glow Serum', 'Some By Mi', 'serum', 'bottle', '1,2-Hexanediol, ADANSONIA DIGITATA SEED EXTRACT, Adenosine, Allantoin, ARONIA MELANOCARPA FRUIT EXTRACT, Ascorbic Acid, ASPALATHUS LINEARIS EXTRACT, Haematococcus Pluvialis Extract, BAMBUSA VULGARIS EXTRACT, Biotin, Brassica Oleracea Italica Extract, Butylene Glycol, C12-14 ALKETH-12, Calendula Officinalis Flower Extract, Caprylic/Capric Triglyceride, CARAMEL, CITRUS AURANTIUM BERGAMIA (BERGAMOT) FRUIT OIL, Cyanocobalamin, Dipropylene Glycol, Ethylhexylglycerin, Euterpe Oleracea Fruit Extract, Ficus Carica Fruit Extract, FOLIC ACID, Galactomyces Ferment Filtrate, Glycerin, GLYCERYL ACRYLATE/ACRYLIC ACID COPOLYMER, Houttuynia Cordata Extract, Hydrogenated Lecithin, HYDROXYETHYLCELLULOSE, Inositol, Lavandula Angustifolia Oil, Leuconostoc Ferment Filtrate, Limonene, Linalool, LINOLEIC ACID, Maltodextrin, Niacinamide, OPUNTIA COCCINELLIFERA FRUIT EXTRACT, OPUNTIA FICUS-INDICA EXTRACT, Panthenol, PHENYLETHYL RESORCINOL, PHOENIX DACTYLIFERA (DATE) FRUIT EXTRACT, POLYGLYCERYL-10 STEARATE, PROPOLIS EXTRACT, PVM/MA COPOLYMER, PYRIDOXINE, RIBES NIGRUM (BLACK CURRANT) FRUIT EXTRACT, Rubus Fruticosus Fruit Extract, Rubus Idaeus Fruit Extract, SACCHARIDE HYDROLYSATE, Sodium Ascorbyl Phosphate, Sodium Hyaluronate, SPARASSIS CRISPA EXTRACT, SPIRULINA MAXIMA EXTRACT, THIAMINE HCL, Tocopherol, Trehalose, Tromethamine, TUBER MAGNATUM EXTRACT, Vaccinium Angustifolium Fruit Extract, VACCINIUM MACROCARPON (CRANBERRY) FRUIT EXTRACT, Vaccinium Myrtillus Fruit Extract, Aqua, XANTHAN GUM', 'Sérum éclat à la Vitamine C et au filtrat de Galactomyces qui unifie le teint et stimule la luminosité.', 30, 'ml', 'some-by-mi-galactomyces-pure-vitamin-c-glow-serum', 'https://www.skinsafeproducts.com/some-by-mi-galactomyces-pure-vitamin-c-glow-serum-1-01-fl-oz-30-ml', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-galactomyces-pure-vitamin-c-glow-serum.webp', 'Association d''Acide Ascorbique, Niacinamide, Phénylethyl Résorcinol et Galactomyces Ferment Filtrate — recommandé pour les peaux ternes avec irrégularités de pigmentation.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.677+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cf0-789b-9a7d-4b1e8e1311d4', '__OWNER_ID__', 'Fixing Tint', 'ETUDE', 'moisturizer', 'jar', 'Aqua, Isododecane, Dimethicone, Copolymère de Diphenyl Diméthicone/Vinyl Diphenyl Diméthicone/Silsesquioxane, Butylene Glycol, Disteardimonium Hectorite, Phosphate de Tricalcium, Copolymère de Diméthicone/Vinyl Diméthicone, Malate de Diisostéaryl, Sorbitan Isostearate, Lauryl Polyglyceryl-3 Polydiméthylsiloxyéthyl Diméthicone, Diglycérine, Cetyl PEG/PPG-10/1 Diméthicone, Stearyl Diméthicone, Magnesium Sulfate, 1,2-Hexanediol, Diphenylsiloxy Phényl Triméthicone, Dioxyde de Titane CI 77891, Carbonate de Propylène, Polyglyceryl-3 Diisostéarate, Octadécène, Copolymère d’Acrylates/Polytriméthylsiloxyméthacrylate, Oxyde de Fer Rouge, Oxyde de Fer Noir, Polyglyceryl-3 Polydiméthylsiloxyéthyl Diméthicone, Helindone Rose CN, Parfum, Silice Diméthyl Silylate, Sorbitan Olivate, Triéthoxycaprylylsilane, Phosphate de Dicalcium, Jaune Sunset FCF, Phloxine B, Ethylhexylglycerin, Bleu Brillant FCF, Sesquioleate de Sorbitan, Hydroxyde d’Aluminium, Tocopherol, Pentaérythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate *Ingredients may differ between product variations. The list shown includes all possible ingredient options', 'La Fixing Tint ETUDE est une encre à lèvres hydro-mat longue tenue conçu pour offrir une couleur vive et sans transfert, avec une texture légère et confortable. Cette encre à lèvres vegan et cruelty-free adhère délicatement aux lèvres sans les dessécher grâce à sa formule résistante au masque, limitant les transferts. Disponible en plusieurs teintes, elle offre une pigmentation intense et une texture semi-mate qui sublime la couleur des lèvres tout en maintenant une bonne hydratation. Des ingrédients clés comme le diméthicone et le butylène glycol apportent une sensation hydratante, tandis que la texture légère garantit un confort durable sans effet collant. Adaptée à différents styles, du fini couvrant au dégradé naturel, cette encre est idéale pour celles et ceux qui recherchent une couleur audacieuse, durable et non irritante. Formulée sans alcool agressif, sans parabènes et sans allergènes courants, elle convient parfaitement à une utilisation quotidienne.', 4, 'g', 'etude-fixing-tint', 'https://korean-skincare.fr/products/etude-fixing-tint', 'https://aurore-cdn.b-cdn.net/products/etude-fixing-tint.webp', 'Ajuste la quantité de produit à l’aide de l’embout applicateur. Applique au centre de tes lèvres puis estompe vers l’extérieur pour un dégradé naturel.', 1195, '2026-05-07 17:37:38.544338+00', '2026-06-14 15:14:07.677+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64df-73f2-9ef0-ba7fdc0f8098', '__OWNER_ID__', 'Dive-In Hydrating Serum', 'Torriden', 'serum', 'bottle', '1,2-Hexanediol, Allantoin, Beta-Glucan, Betaine, Butylene Glycol, Carbomer, Ceramide NP, Cholesterol, Dipropylene Glycol, Ethylhexylglycerin, Glycerin, GLYCERYL ACRYLATE/ACRYLIC ACID COPOLYMER, Hamamelis Virginiana Leaf Extract, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, MADECASSIC ACID, Madecassoside, MALACHITE EXTRACT, Paeonia Suffruticosa Root Extract, Panthenol, Pentylene Glycol, POLYGLYCERYL-10 LAURATE, Portulaca Oleracea Extract, Propanediol, PVM/MA COPOLYMER, SCUTELLARIA BAICALENSIS ROOT EXTRACT, Sodium Acetylated Hyaluronate, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Trehalose, Tromethamine, Aqua, XANTHAN GUM', 'Sérum hydratant à complexe d''acide hyaluronique multi-poids pour une hydratation en couches, du cœur jusqu''à la surface cutanée.', 50, 'ml', 'torriden-dive-in-hydrating-serum', 'https://www.skinsafeproducts.com/torriden-dive-in-hydrating-serum-hyaluronic-acid-complex-1-69-fl-oz-50-ml-pack-of-2', 'https://aurore-cdn.b-cdn.net/products/torriden-dive-in-hydrating-serum.webp', 'Acide hyaluronique multi-formes + Bêta-Glucane + Céramides + Madécassoside. Idéal pour peaux déshydratées à barrière fragilisée.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.677+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64de-7bb9-88ca-bf5db8e3db8b', '__OWNER_ID__', 'Dive-In Low Molecular Hyaluronic Acid Mask', 'Torriden', 'mask', 'pack', '1,2-Hexanediol, Allantoin, Butylene Glycol, Calendula Officinalis Flower Extract, Carbomer, Chamomilla Recutita (Matricaria) Flower Extract, Coccinia Indica Fruit Extract, CORALLINA OFFICINALIS EXTRACT, Curcuma Longa Root Extract, Dipropylene Glycol, Ethylhexylglycerin, Glycerin, GLYCERYL ACRYLATE/ACRYLIC ACID COPOLYMER, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Hydroxyacetophenone, MALACHITE EXTRACT, MELIA AZADIRACHTA FLOWER EXTRACT, Melia Azadirachta Leaf Extract, Ocimum Sanctum Leaf Extract, Panthenol, Pentylene Glycol, Portulaca Oleracea Extract, PVM/MA COPOLYMER, Saccharide Isomerate, Sodium Acetylated Hyaluronate, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Solanum Melongena Fruit Extract, Trehalose, Tromethamine, Aqua, XANTHAN GUM', 'Masque tissu à l''acide hyaluronique de bas poids moléculaire pour une hydratation intense et apaisante en une seule application.', 10, 'patchs', 'torriden-dive-in-mask', 'https://www.skinsafeproducts.com/torriden-dive-in-low-molecular-hyaluronic-acid-mask-0-91-fl-oz-27-ml-10-count', 'https://aurore-cdn.b-cdn.net/products/torriden-dive-in-mask.webp', 'Acide hyaluronique multi-formes + Panthénol + Extraits de camomille. Idéal pour peaux sensibles et stressées.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.677+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-64de-7fbd-8773-b59e4f8de6ba', '__OWNER_ID__', 'Dive-In Soothing Cream', 'Torriden', 'moisturizer', 'jar', '1,2-Hexanediol, 2,3-BUTANEDIOL, Allantoin, BORAGO OFFICINALIS EXTRACT, Butylene Glycol, C12-20 ALKYL GLUCOSIDE, C14-22 Alcohols, Caprylic/Capric Triglyceride, Carbomer, CENTAUREA CYANUS FLOWER EXTRACT, Cetearyl Alcohol, Chamomilla Recutita (Matricaria) Flower Extract, Coccinia Indica Fruit Extract, CORALLINA OFFICINALIS EXTRACT, Curcuma Longa Root Extract, Disodium EDTA, Ethylhexylglycerin, Glutathione, Glycerin, GLYCERYL ACRYLATE/ACRYLIC ACID COPOLYMER, HAMAMELIS VIRGINIANA (WITCH HAZEL) EXTRACT, HYACINTHUS ORIENTALIS (HYACINTH) EXTRACT, HYDROGENATED DIDECENE, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, LAVANDULA ANGUSTIFOLIA (LAVENDER) FLOWER EXTRACT, MALACHITE EXTRACT, MELIA AZADIRACHTA FLOWER EXTRACT, Melia Azadirachta Leaf Extract, Ocimum Sanctum Leaf Extract, Panthenol, Pentylene Glycol, PVM/MA COPOLYMER, SALVIA SCLAREA (CLARY) EXTRACT, Sodium Acetylated Hyaluronate, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Solanum Melongena Fruit Extract, Sorbitan Isostearate, Trehalose, Tromethamine, Aqua, XANTHAN GUM', 'Crème apaisante légère à l''acide hyaluronique formulée pour calmer les irritations et restaurer le confort cutané.', 50, 'ml', 'torriden-dive-in-soothing-cream', 'https://www.skinsafeproducts.com/torriden-dive-in-soothing-cream-2-70-fl-oz-50-ml', 'https://aurore-cdn.b-cdn.net/products/torriden-dive-in-soothing-cream.webp', 'Acide hyaluronique multi-formes + Glutathion + Extraits de lavande et d''hamamélis. Idéal pour peaux sensibles et réactives.', 0, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.677+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3bff-785a-81b2-9453067eb363', '__OWNER_ID__', 'Advanced Snail Hydrogel Eye Patch', 'COSRX', 'eye-cream', 'jar', 'Aqua, Glycerin, Mucine d''Escargot, Niacinamide, Carraghenane, 1,2-Hexanediol, Gomme de Caroube, Betaine, Hydroxyacetophenone, Allantoin, Chlorphenesin, Gomme de Guar, Chlorure de Calcium, Butylene Glycol, Sucrose, Cellulose Gum, Adenosine, Potassium Chloride, Dipotassium Glycyrrhizate, Ethylhexylglycerin, PEG-90M', 'L''Advanced Snail Hydrogel Eye Patch COSRX Advanced Snail Hydrogel aide à rajeunir et à dorloter les yeux fatigués. Ce patch pour les yeux ultra-léger est spécialement formulé pour apporter une hydratation intense à la zone délicate du dessous de l''œil. Infusé de la puissante essence Advanced Snail 96 Mucin Power, ce patch hydrogel pour les yeux hydrate en profondeur et revitalise la peau, la laissant rebondie et rajeunie. Ce patch pour les yeux est enrichi de 20 400 ppm de mucine d''escargot, qui nourrit la peau avec des nutriments essentiels et stimule l''élasticité de la peau. Il contient également 2 % de niacinamide qui contribue à affiner et à illuminer la peau, te laissant un teint clair et éclatant. La texture en nid d''abeille du patch adhère parfaitement à la peau, ce qui garantit une diffusion efficace des principes actifs dans la peau. Utilise ces patchs pour les yeux pour traiter et prévenir les rides du sourire, les rides autour des yeux et les rides du front. Avec une utilisation régulière, ces patch pour les yeux COSRX laisseront ta peau rafraîchie, revitalisée et rajeunie.', 60, 'pcs', 'cosrx-advanced-snail-hydrogel-eye-patch', 'https://korean-skincare.fr/products/cosrx-advanced-snail-hydrogel-eye-patch', 'https://aurore-cdn.b-cdn.net/products/cosrx-advanced-snail-hydrogel-eye-patch.webp', 'Applique les patchs d''hydrogel sur la zone souhaitée à l''aide de la pince à épiler fournie à l''intérieur. Retire-les au bout de 20 à 30 minutes.', 2230, '2026-05-07 17:37:38.30346+00', '2026-06-14 15:14:07.678+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c50-70cd-8b0a-69ea6bf6789d', '__OWNER_ID__', 'PDRN Exosome Skinplaning Glaze Mask', 'COSRX', 'mask', 'pack', 'Aqua, Polyvinyl Alcohol, Octyldodecanol, Methylpropanediol, Butylene Glycol, Niacinamide, Caprylic/Capric Triglyceride, 1,2-Hexanediol, Algin, Polysorbate 80, Pentaerythrityl Tetraethylhexanoate, Pullulan, Simmondsia Chinensis Seed Oil, Polyglyceryl-10 Oleate, Glyceryl Stearate, PEG-100 Stearate, Titanium Dioxide, Disteardimonium Hectorite, Synthetic Fluorphlogopite, CI 77019, Microcrystalline Cellulose, Ethylhexylglycerin, Sphingomonas Ferment Extract, Adenosine, Cellulose Gum, Sodium Phytate, Sodium DNA, Tin Oxide, Glutathione, Acetyl Glucosamine, Allantoin, Panthenol, Hydrolyzed Collagen, Gluconolactone, Mannitol, Centella Asiatica Leaf Extract, Glycerin, Lactobacillus Extracellular Vesicles, Hydrated Silica, Citric Acid, Sodium Hyaluronate, Caprylyl Glycol, Acetyl Hexapeptide-8', 'Le PDRN Exosome Skinplaning Glaze Mask COSRX est un masque gel de nouvelle génération qui offre hydratation intense, renouvellement cutané et un fini éclatant, le tout en un seul soin. Ce masque agit en profondeur pour soutenir la régénération, améliorer l’élasticité et embellir l’apparence des peaux fatiguées, texturées ou déshydratées. Sa texture innovante « glaze » procure un effet lissant délicat, mimant les résultats d’un soin skinplaning sans exfoliation physique. Idéal pour les peaux ternes, sèches ou stressées, ce masque enveloppe le visage d’une couche fraîche et moelleuse qui apaise instantanément et restaure l’hydratation. C’est le soin hebdomadaire parfait pour obtenir un teint visiblement plus lisse, repulpé et lumineux. Recommandé pour : Tous types de peaux.', 50, 'ml', 'cosrx-pdrn-exosome-skinplaning-glaze-mask', 'https://korean-skincare.fr/products/cosrx-pdrn-exosome-skinplaning-glaze-mask', 'https://aurore-cdn.b-cdn.net/products/cosrx-pdrn-exosome-skinplaning-glaze-mask.webp', 'Après le nettoyage et le tonique, applique une couche épaisse et uniforme sur le visage en évitant le contour des yeux et des lèvres. Laisse poser 15–20 minutes, puis rince à l’eau tiède. À utiliser 2–3 fois par semaine ou chaque fois que la peau a besoin d’un coup d’éclat.', 2195, '2026-05-07 17:37:38.383825+00', '2026-06-14 15:14:07.678+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c01-7a16-bd35-ac32fe26ca09', '__OWNER_ID__', 'The Niacinamide 15 Serum', 'COSRX', 'serum', 'dropper', 'Aqua, Pentylene Glycol, Niacinamide, Butylene Glycol, Acetyl Glucosamine, 1,2-Hexanediol, Zinc PCA, Trehalose, Gomme Xanthane, Pullulane, Allantoin, Ethylhexylglycerin, Sodium Phytate, Citric Acid, Tocopherol', 'Le Niacinamide 15 Serum COSRX se distingue comme une solution hautement concentrée, conçue de façon experte pour combattre l''acné et les taches brunes grâce à son puissant mélange d''ingrédients. Avec un taux substantiel de 15 % de niacinamide, ce sérum fait des merveilles pour calmer les éruptions cutanées, contrôler l''excès de sébum et affiner les pores obstrués. L''inclusion de N-acétylglucosamine exfolie délicatement la peau et estompe efficacement l''hyperpigmentation, tandis que le zinc PCA assure l''équilibre du ratio huile-eau, réduisant l''inflammation et favorisant le rétablissement de la peau. Parfaitement adapté à tous les types de peau confrontés au problème des points noirs, des comédons et des pores dilatés, ce sérum régule non seulement le sébum mais lisse également la texture rugueuse de la peau et améliore l''apparence des cicatrices d''acné. La synergie minutieuse des ingrédients de sa formule en fait une solution puissante pour un contrôle total de l''acné, offrant une solution complète aux pores obstrués, à l''excès de sébum et à la texture rugueuse de la peau. Recommandé pour : Tous types de peaux.', 20, 'ml', 'copy-of-the-niacinamide-15-serum', 'https://korean-skincare.fr/products/copy-of-the-niacinamide-15-serum', 'https://aurore-cdn.b-cdn.net/products/copy-of-the-niacinamide-15-serum.webp', 'Après le nettoyage, pendant l''étape du sérum, applique quelques gouttes sur ta peau. Utilise le bout de tes doigts pour masser délicatement et faire pénétrer le sérum, en commençant par le centre de ton visage et en allant vers les bords.', 1900, '2026-05-07 17:37:38.30557+00', '2026-06-14 15:14:07.678+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c10-719a-88ff-98600f67d27a', '__OWNER_ID__', 'Advanced Snail Mucin Power Gel Cleanser', 'COSRX', 'cleanser', 'tube', 'Aqua, Copolymère d''Acrylates, Butylene Glycol, Glycerin, Disodium Laureth Sulfosuccinate, Sodium Cocoyl Isethionate, 1,2-Hexanediol, Coco-Glucoside, Lauryl Betaine, Mucine d''Escargot, Arginine, Tromethamine, Potassium Cocoyl Glycinate, Parfum, Carbomer, Sodium Chloride, Ethylhexylglycerin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Sodium Polyacrylate, Disodium EDTA', 'L''Advanced Snail Mucin Power Gel Cleanser COSRX est un nettoyant moussant léger qui élimine la saleté, le sébum et le maquillage sans perturber la barrière cutanée. Conçu pour ceux qui recherchent un nettoyant doux qui aide à apaiser la peau irritée, ce gel nettoyant exploite le pouvoir reconstituant de la mucine d''escargot. Formulé avec 10 000 ppm de mucine d''escargot pour éliminer efficacement les impuretés sans endommager la barrière cutanée. Adapté aux peaux sèches, ternes ou irritées, ce nettoyant laissera ton teint éclatant, frais et lisse.', 150, 'ml', 'cosrx-advanced-snail-mucin-power-gel-cleanser', 'https://korean-skincare.fr/products/cosrx-advanced-snail-mucin-power-gel-cleanser', 'https://aurore-cdn.b-cdn.net/products/cosrx-advanced-snail-mucin-power-gel-cleanser.webp', 'Humidifie ton visage et fais mousser une quantité de nettoyant de la taille d''un petit pois entre tes paumes. Fais pénétrer la mousse dans ta peau en massant du front jusqu''à la mâchoire. Rince abondamment à l''eau tiède.', 1637, '2026-05-07 17:37:38.320022+00', '2026-06-14 15:14:07.678+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c07-7dc1-8b2b-e766471c5af0', '__OWNER_ID__', 'Oil-Free Ultra-Moisturizing Lotion', 'COSRX', 'moisturizer', 'jar', 'Jus de Betula Platyphylla Japonica, Butylene Glycol, Glycerin, Dimethicone, Betaine, Cetearyl Alcohol, 1,2-Hexanediol, Cetearyl Olivate, Sorbitan Olivate, Ethylhexylglycerin, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Éthyl Hexanediol, Gomme Xanthane, Allantoin, Panthenol, Sodium Hyaluronate, Sodium Lactate, 4-Terpineol, Aqua', 'Un soin hydratant quotidien extrêmement hydratant recommandé pour le jour et la nuit. Cette lotion subtile et légère contient 70 % d''eau d''écorce de saule (sève de bouleau), un ingrédient naturel respectueux de la peau, plein de vitamines et d''antioxydants, qui calme et traite efficacement les peaux irritées en les nourrissant. La lotion pénètre rapidement sans laisser de résidu gras, ce qui la rend parfaite pour tous ceux qui ont une peau grasse ou mixte. Pour les peaux sèches, la Oil Free Ultra Moisturizing Lotion COSRX peut également être un simple produit quotidien de base, car la sève de bouleau est efficace pour restaurer et maintenir l''hydratation de la peau. La consistance de la Oil Free Ultra Moisturizing Lotion COSRX est très légère et non grasse. Une fois appliquée, elle pénètre en profondeur très rapidement, laissant la peau fraîche, douce et soyeuse. Son flacon-pompe permet de garder le produit propre car il n''est pas nécessaire de toucher directement le produit pour l''appliquer. Il est également plus facile de distribuer la quantité exacte nécessaire. Hypoallergénique, testée par des dermatologues, cruelty-free, sans parabènes.', 100, 'ml', 'cosrx-oil-free-ultra-moisturizing-lotion', 'https://korean-skincare.fr/products/cosrx-oil-free-ultra-moisturizing-lotion', 'https://aurore-cdn.b-cdn.net/products/cosrx-oil-free-ultra-moisturizing-lotion.webp', 'Applique délicatement une quantité adéquate de crème sur ton visage. Tapote délicatement la zone où la crème a été appliquée, afin qu''elle soit absorbée le long de la texture de ta peau.', 1701, '2026-05-07 17:37:38.311807+00', '2026-06-14 15:14:07.678+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c12-7419-a91e-9dd6333b4403', '__OWNER_ID__', 'Poreless Clarifying Charcoal Mask', 'COSRX', 'mask', 'pack', 'Aqua, Silica, Propanediol, Kaolin, Glycerin, Terre de Diatomées, 1,2-Hexanediol, Butylene Glycol, Extrait de Graines de Camellia Sinensis, Betaine, Carbomer, Tromethamine, Hydroxyacetophenone, Titanium Dioxide, Copolymère Ammonium Acryloyldiméthyltaurate/VP, Cellulose, Poudre de Charbon, Calamine, Cellulose Gum, Gomme Xanthane, Silice Diméthyl Silylate, Disodium EDTA, Ethylhexylglycerin, Éthylcellulose, Gardenia Florida Fruit Extract, Dextrin, Lauric Acid, Amidon de Maïs (Zea Mays), Hydroxyde d''Aluminium, Mannitol, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate, Stéarate de Polyglycéryl-10, Salicylic Acid', 'Le Poreless Clarifying Charcoal Mask COSRX, le masque purifiant et perfecteur de peau par excellence, transformera ta routine beauté du soir en une expérience de salon professionnelle ! Ce masque à couleur changeante commence avec une teinte rose et devient progressivement gris, pour finir avec une magnifique teinte blanche, laissant ta peau plus belle que jamais et te procurant une sensation de bien-être. La formule innovante du Poreless Clarifying Charcoal Mask COSRX contient des capsules de calamine rose qui calment et contrôlent instantanément la production de sébum, ce qui le rend parfait pour les peaux grasses ou à tendance acnéique. Le masque libère ensuite une vague de charbon qui pénètre au plus profond de tes pores pour les détoxifier et les nettoyer, laissant à ta peau une sensation de fraîcheur et de revitalisation. En séchant, le masque resserre tes pores et lisse la surface de ta peau, te conférant un teint radieux et sans défaut. Avec le Poreless Clarifying Charcoal Mask COSRX, tu peux profiter d''un soin du visage professionnel dans le confort de ta propre maison.', 110, 'g', 'cosrx-poreless-clarifying-charcoal-mask', 'https://korean-skincare.fr/products/cosrx-poreless-clarifying-charcoal-mask', 'https://aurore-cdn.b-cdn.net/products/cosrx-poreless-clarifying-charcoal-mask.webp', 'Après avoir nettoyé ton visage, applique le masque rose uniformément sur ton visage sec. Masse délicatement pour laisser les capsules de charbon agir. Rince délicatement au bout de 5 à 10 minutes.', 1745, '2026-05-07 17:37:38.322196+00', '2026-06-14 15:14:07.678+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c14-74af-b5b9-4c32a97a0142', '__OWNER_ID__', 'Hydrium Triple Hyaluronic Water Wave Sheet Mask', 'COSRX', 'mask', 'pack', 'Aqua, Butylene Glycol, Alcohol, Panthenol, Betaine, 1,2-Hexanediol, Paeonia Suffruticosa Root Extract, Centella Asiatica Extract, Laurate de Polyglycéryl-10, Chamomilla Recutita (Matricaria) Flower Extract, Glyceryl Caprylate, Arginine, Gomme Xanthane, Carbomer, Sodium Hyaluronate, Ethylhexylglycerin, Disodium EDTA, Pantolactone, Eucalyptus Globulus Leaf Oil, Hydrolyzed Hyaluronic Acid, Sulfosuccinate de Sodium Diéthylhexyle, Dipropylene Glycol, Acétyl-Hyaluronate de Sodium', 'Le Triple Hyaluronic Water Wave Sheet Mask COSRX libère une bouffée d''hydratation grâce à son essence à absorption rapide contenant trois acides hyaluroniques et du panthénol. Les propriétés hydrophiles de l''acide hyaluronique aident à fixer l''hydratation pour favoriser sa rétention et atténuer la déshydratation. Son tissu en cellulose biodégradable d''origine naturelle permet à l''essence hydratante de rafraîchir la peau et de l''hydrater en profondeur.', 1, 'pcs', 'cosrx-hydrium-triple-hyaluronic-water-wave-sheet-mask', 'https://korean-skincare.fr/products/cosrx-hydrium-triple-hyaluronic-water-wave-sheet-mask', 'https://aurore-cdn.b-cdn.net/products/cosrx-hydrium-triple-hyaluronic-water-wave-sheet-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 395, '2026-05-07 17:37:38.324219+00', '2026-06-14 15:14:07.679+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c18-75e5-9360-26cea9443fad', '__OWNER_ID__', 'Balancium Comfort Ceramide Cream', 'COSRX', 'moisturizer', 'jar', 'Centella Asiatica Leaf Water, Butylene Glycol, Glycerin, Helianthus Annuus Seed Oil, Caprylic/Capric Triglyceride, Alcool Cétylique/Stéarylique, Betaine, 1,2-Hexanediol, Olivate de Cétyle, Huile de Palme (Elaeis Guineensis), Ceramide NP, Sorbitan Olivate, Hydrogenated Lecithin, Triéthylhexanoin, Cire d’Abeille PEG-8, Huile de Noyau de Palme (Elaeis Guineensis), Copolymère d’Acrylate d’Hydroxyéthyle/Sodium Acryloyldiméthyl Taurinate, Ethylhexylglycerin, Cyclohexasiloxane, Extrait de Graine de Cassia Obtusifolia, Distearate de Sucrose, Dipropylene Glycol, Panthenol, Niacinamide, Crosspolymère de Diméthicone/Vinyl Diméthicone, Glyceryl Stearate, Gomme Xanthane, Sodium Hyaluronate, Limonene, Huile de Fruit de Bergamote (Citrus Aurantium Bergamia), Asiaticoside, Acide Asiatique, Acide Madecassique et Linalool', 'Fais profiter ta peau d''un confort ultime avec la Balancium Comfort Ceramide Cream COSRX, formulée pour fortifier ta barrière cutanée et rétablir l''équilibre de ta peau. Cette crème contient du RX Ceramide NP, qui régénère la peau sensibilisée et endommagée pour une sensation de santé et de confort de l''intérieur. Infusée de Centella Asiatica de qualité médicale, elle équilibre efficacement le ratio huile/eau de la peau tout en améliorant son élasticité. Sa texture baume mat assure une hydratation sans résidu gras, ce qui la rend idéale pour les types de peaux grasses et sèches, en particulier celles à tendance acnéique. Recommandé pour : Peaux sèches et sensibles, tous types de peaux.', 80, 'g', 'balancium-comfort-ceramide-cream', 'https://korean-skincare.fr/products/balancium-comfort-ceramide-cream', 'https://aurore-cdn.b-cdn.net/products/balancium-comfort-ceramide-cream.webp', 'Applique une quantité adéquate de produit uniformément sur ton visage, en évitant le contour des yeux.', 2213, '2026-05-07 17:37:38.32829+00', '2026-06-14 15:14:07.679+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c1a-797b-bee8-45c1568a273f', '__OWNER_ID__', 'The Hyaluronic Acid 3 Serum', 'COSRX', 'serum', 'dropper', 'Aqua, Butylene Glycol, Propanediol, Glycerin, Sodium Hyaluronate, Pentylene Glycol, 1,2-Hexanediol, Diéthoxyéthyl Succinate, Taurate de Polyacryloyldiméthyl Sodium, Betaine, Gomme Xanthane, Dimethicone, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Sodium PCA, Sodium Lactate, PCA, Copolymère d''Acrylate de Glycéryle/Acide Acrylique, Hydrogenated Lecithin, Ethylhexylglycerin, Sérine, Alanine, Glycine, Sodium Phytate, Sorbitan Isostearate, Copolymère PVM/MA, Glutamic Acid, Citric Acid, Lysine HCl, Thréonine, Arginine, Taurate de Sodium Méthylique Stéaroyl, Proline, Ceramide NP, Cholesterol, Caprylic/Capric Triglyceride, Phytosphingosine, Stearic Acid, Oleic Acid, Alcohol, Tocopherol, Lactic Acid, Caprylyl Glycol, Caprylhydroxamic Acid', 'Le Hyaluronic Acid 3 Serum COSRX est un sérum léger et hydratant qui est formulé avec trois types d''acide hyaluronique, connus pour leur capacité à attirer et à retenir l''humidité. L''acide hyaluronique est une substance naturellement présente dans la peau qui contribue à la maintenir hydratée, rebondie et d''apparence jeune. Cependant, avec l''âge, les niveaux naturels d''acide hyaluronique de notre peau diminuent, ce qui peut entraîner une sécheresse, des ridules et d''autres signes de vieillissement. Les trois différents types d''acide hyaluronique contenus dans ce sérum travaillent ensemble pour fournir différents niveaux d''hydratation aux différentes couches de la peau. Cela signifie que le sérum peut aider à hydrater les couches plus profondes de la peau, ainsi que la surface, lui donnant un aspect et une sensation plus souples. Ce sérum convient à tous les types de peau, y compris les peaux grasses et acnéiques. Pour utiliser le sérum, il suffit d''en appliquer une petite quantité sur le visage et le cou après l''avoir nettoyé et avoir utilisé un tonique, et de le faire suivre de ta crème hydratante habituelle. Tu peux l''utiliser le matin et/ou le soir, selon tes préférences.', 20, 'ml', 'cosrx-the-hyaluronic-acid-3-serum', 'https://korean-skincare.fr/products/cosrx-the-hyaluronic-acid-3-serum', 'https://aurore-cdn.b-cdn.net/products/cosrx-the-hyaluronic-acid-3-serum.webp', 'Après le nettoyage, pendant l''étape du sérum, applique quelques gouttes sur ta peau. Utilise le bout de tes doigts pour masser délicatement et faire pénétrer le sérum, en commençant par le centre de ton visage et en allant vers les bords.', 1980, '2026-05-07 17:37:38.330492+00', '2026-06-14 15:14:07.679+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c27-7c40-b5b0-4d3a7c5c807a', '__OWNER_ID__', 'Propolis Honey Overnight Mask', 'COSRX', 'mask', 'pack', 'Extrait de Propolis, Butylene Glycol, Glycerin, Extrait de Miel, Extrait de Gelée Royale, 1,2-Hexanediol, Aqua, Betaine, Extrait de Graine de Cassia Obtusifolia, Carbomer, Arginine, Ethylhexylglycerin, Myristate de Polyglycéryl-10, Laurate de Polyglycéryl-10, Gomme de Xanthane, Helianthus Annuus Seed Oil, Polyacrylate de Sodium, Panthenol, Allantoin, Adenosine, Sodium Hyaluronate, Cera Alba', 'Le Propolis Honey Overnight Mask COSRX possède une formulation rafraîchissante et hydratante pour calmer les peaux irritées et sensibles et soulager les rougeurs. Ce masque de nuit à la propolis contient de l''extrait de miel de propolis antibactérien pour protéger les peaux sujettes aux imperfections. À utiliser pendant la nuit, en soin à rincer ou comme crème hydratante quotidienne.', 60, 'ml', 'cosrx-full-fit-propolis-honey-overnight-mask', 'https://korean-skincare.fr/products/cosrx-full-fit-propolis-honey-overnight-mask', 'https://aurore-cdn.b-cdn.net/products/cosrx-full-fit-propolis-honey-overnight-mask.webp', 'Comme masque de nuit : Utilise-le à la fin de ta routine beauté de base avant de te coucher. Applique une quantité suffisante sur ta peau. Comme masque à rincer : Applique une quantité généreuse de masque au miel et laisse-le agir pendant 15 minutes. Rince-le avec un tonique ou de l''eau tiède. Comme crème (le matin) : Utilise-le à la fin de ta routine beauté de base et passe à ton maquillage habituel.', 1745, '2026-05-07 17:37:38.343452+00', '2026-06-14 15:14:07.679+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43e5-702b-8b05-99c39228a4d1', '__OWNER_ID__', 'Pro Balance Morning Enzyme Wash', 'Dr. Ceuracle', 'cleanser', 'jar', 'Maltose, Amidon De Maïs Zea Mays, Glycinate De Cocoyl De Sodium, Glutamate De Lauroyl De Sodium, Glutamate De Myristoyl De Sodium, Microcrystalline Cellulose, Silica, Citric Acid, Dipotassium Glycyrrhizate, Allantoin, Huile D’Orange Citrus Aurantium Dulcis, Huile De Zeste De Mandarine Citrus Nobilis, Litsea Cubeba Fruit Oil, Aqua, Butylene Glycol, Protéase, Lactobacillus Ferment, 1,2-Hexanediol, Ulmus Davidiana Root Extract, Extrait De Graine D’Amaranthus Caudatus, Caprylyl Glycol, Bifida Ferment Lysate, Bifida Ferment Lysate, Saccharomyces Ferment Filtrate, Lactobacillus Ferment Lysate, Lactococcus Ferment Lysate, Tropolone, Limonene', 'Le Pro Balance Morning Enzyme Wash Dr. Ceuracle est un nettoyant en poudre enzymatique doux, conçu pour nettoyer et rééquilibrer la peau sans perturber sa barrière naturelle d’hydratation. Sa formule à pH bas élimine efficacement l’excès de sébum, les cellules mortes et les impuretés accumulées pendant la nuit, tout en maintenant une hydratation optimale. Grâce à ses enzymes naturelles telles que la protéase, la papaye et l’amylase, ce nettoyant exfolie légèrement la peau pour lisser sa texture et affiner les pores sans irritation. Enrichi en probiotiques et extraits botaniques apaisants, il soutient un microbiome cutané sain, calme les sensibilités et renforce la barrière cutanée. Idéal pour un usage quotidien le matin, ce nettoyant non agressif laisse la peau propre, douce et rafraîchie, sans tiraillements ni sécheresse. Convient à tous types de peaux, y compris sensibles ou à tendance acnéique. Recommandé pour : Tous types de peaux.', 50, 'g', 'dr-ceuracle-pro-balance-morning-enzyme-wash', 'https://korean-skincare.fr/products/dr-ceuracle-pro-balance-morning-enzyme-wash', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-pro-balance-morning-enzyme-wash.webp', 'Verse une petite quantité de poudre dans tes mains humides et fais mousser. Masse doucement sur ta peau humide, puis rince abondamment à l’eau tiède. Utilise le matin ou comme nettoyant doux quotidien.', 2295, '2026-05-07 17:37:40.324949+00', '2026-06-14 15:14:07.681+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c1f-74a1-9c03-9975c7d95119', '__OWNER_ID__', 'Hydrium Triple Hyaluronic Moisture Cleanser', 'COSRX', 'cleanser', 'jar', 'Aqua, Glycerin, Stearic Acid, Myristic Acid, Lauric Acid, Potassium Hydroxide, Palmitic Acid, Cocoyl Glycinate de Potassium, Coco-Glucoside, Glyceryl Stearate, Parfum, Polyquaternium-7, Copolymère d''Acrylates d''Alkyle en C10-30, Isethionate de Cocoyl de Sodium, Arachidic Acid, Disodium EDTA, 1,2-Hexanediol, Oleic Acid, Sodium Benzoate, Extrait d''Écorce de Quillaja Saponaria, Citric Acid, Butylene Glycol, Panthenol, Hyaluronic Acid, Ethylhexylglycerin, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate', 'Le Hydrium Triple Hyaluronic Moisture Cleanser CosRX est un nettoyant doux qui mousse abondamment pour éliminer la saleté et les impuretés de la peau. Enrichi d''acide hyaluronique et de vitamine B5, ce nettoyant aide à retenir l''hydratation et à repulper la peau tout en la laissant propre et rafraîchie.', 150, 'ml', 'cosrx-hydrium-triple-hyaluronic-moisture-cleanser', 'https://korean-skincare.fr/products/cosrx-hydrium-triple-hyaluronic-moisture-cleanser', 'https://aurore-cdn.b-cdn.net/products/cosrx-hydrium-triple-hyaluronic-moisture-cleanser.webp', 'Utilise le nettoyant matin et soir, après le démaquillage. Commence par humidifier tes mains et ton visage. Distribue une quantité suffisante de nettoyant sur tes mains mouillées pour le faire mousser. Masse délicatement ton visage en évitant le contour des yeux et de la bouche. Rince à l''eau tiède.', 1029, '2026-05-07 17:37:38.335057+00', '2026-06-14 15:14:07.679+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c1c-7dd1-93e9-a846f3f5f859', '__OWNER_ID__', 'The Vitamin C 13 serum', 'COSRX', 'serum', 'dropper', 'Aqua, Ascorbic Acid, Butylene Glycol, Dipropylene Glycol, Tromethamine, 3-O-Ethyl Ascorbic Acid, Panthenol, Acetyl Glucosamine, Caffeine, Sodium Hyaluronate, Sulfite de Sodium, Disodium EDTA, Glutathione, Adenosine, Gardenia Florida Fruit Extract, Allantoin, Dextrin, Squalane, Tocotriénols, Tocopherol, Huile de Palme Elaeis Guineensis, Arginine, Niacinamide, Glycyrrhiza Glabra Root Extract', 'Le Vitamine C 13 Serum COSRX, un sérum à la fois doux et puissant, est parfait pour tous ceux qui cherchent à obtenir un teint plus lumineux et plus uniforme. Ce sérum est formulé avec une forme douce de vitamine C, ce qui permet aux peaux sensibles de l''utiliser quotidiennement sans irritation. L''utilisation régulière du Vitamin C 13 Serum aide à estomper les imperfections, les taches brunes et les taches de rousseur, améliorant ainsi le teint. Grâce à son puissant mélange d''ingrédients naturels, dont 13 % de vitamine C, ce sérum agit pour éclaircir et rajeunir ton teint, te laissant une apparence plus jeune et plus radieuse. Non seulement le Vitamin C 13 Serum aide à estomper l''hyperpigmentation, mais il aide aussi à protéger ta peau contre les dommages futurs. Ses puissantes propriétés antioxydantes te défendent contre les radicaux libres et les autres facteurs de stress environnementaux, ce qui permet à ta peau de rester saine et éclatante.', 20, 'ml', 'cosrx-the-vitamin-c-13-serum', 'https://korean-skincare.fr/products/cosrx-the-vitamin-c-13-serum', 'https://aurore-cdn.b-cdn.net/products/cosrx-the-vitamin-c-13-serum.webp', 'Après le nettoyage, pendant l''étape du sérum, agite légèrement le flacon une ou deux fois d''un côté à l''autre. Applique quelques gouttes sur ta peau. Utilise le bout de tes doigts pour masser délicatement et faire pénétrer le sérum, en commençant par l''intérieur de ton visage et en progressant vers les bords.', 1583, '2026-05-07 17:37:38.33273+00', '2026-06-14 15:14:07.679+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c31-703f-922f-65a58f1ce069', '__OWNER_ID__', 'Peptide-132 Ultra Perfect Hair Bonding Treatment', 'COSRX', 'moisturizer', 'jar', 'Water/​Aqua/​Eau, Glycerin, Dimethicone, Cetyl Ethylhexanoate, Isopentyldiol, Cetyl Alcohol, Stearyl Alcohol, Behentrimonium Chloride, Coco-Caprylate/Caprate, Stearamidopropyl Dimethylamine, Sorbitol, Dipropylene Glycol, Dimethiconol, Hydroxypropyl Starch Phosphate, Amodimethicone, Lactic Acid, Maltitol, Parfum, Caprylyl Glycol, Trideceth-10, Sodium Gluconate, Ethylhexylglycerin, Anthemis Nobilis Flower Water, 1,2-Hexanediol, Propanediol, Argania Spinosa Kernel Oil, Olea Europaea Fruit Oil, Camellia Japonica Seed Oil, Simmondsia Chinensis Seed Oil, Oryza Sativa (Rice) Bran Oil, Vitis Vinifera Seed Oil, Biotin, Tripeptide-1, Tripeptide-3, Tripeptide-2, Macadamia Ternifolia Seed Oil, Sodium Hyaluronate, Tocopherol, Laminaria Japonica Extract, Sodium Metaphosphate, Avena Sativa (Oat) Peptide, Arginine, Serine, Glutamic Acid, Threonine, Leucine, Proline, Aspartic Acid, Isoleucine, Glycine, Soluble Collagen, Hydrolyzed Hyaluronic Acid, Phenylalanine, Alanine, Tyrosine, Lysine, Sodium Hyaluronate Crosspolymer, Histidine, Hyaluronic Acid, Caffeine, Panthenol, Niacinamide, Hydrogenated Lecithin, Butylene Glycol, Cetearyl Alcohol, Valine, Stearic Acid, Sodium Acetylated Hyaluronate, Ceramide NP, Phytosphingosine, Cholesterol, Hydrolyzed Vegetable Protein, Methionine, Ceramide NS, Cystine, Ceramide AP, Ceramide EOP, Tryptophan, Ceramide AS', 'Revitalise tes cheveux avec le Peptide-132 Ultra Perfect Hair Bonding Treatment COSRX, une innovation K-beauty de qualité salon propulsée par le brevet PEPTIDE-132™ pour réparer les cheveux abîmées, restaurer l''élasticité et offrir une brillance lisse et sans frisottis. Cette crème riche et soyeuse nourrit profondément grâce à des huiles végétales comme l''argan, le jojoba et la macadamia, ainsi qu''à la biotine et aux acides aminés, renforçant les cheveux de la racine aux pointes et transformant les cheveux secs, cassants ou traités chimiquement en mèches lisses et résistantes. Profite d’un soin de niveau professionnel à la maison avec ce traitement intensif, conçu pour réparer les pointes fourchues et renforcer les liens capillaires pour tous les niveaux de dommages, de la sécheresse légère au stress chimique sévère. Enrichi en protéine végétale hydrolysée, collagène et plusieurs formes d’acide hyaluronique, il retient l''hydratation et améliore la maniabilité, laissant les cheveux doux, éclatants et en parfaite santé après chaque utilisation. Recommandé pour : Tous types de cheveux, y compris secs, abîmés, épais, frisottis, colorés, décolorés ou traités chimiquement.', 120, 'ml', 'cosrx-peptide-132-ultra-perfect-hair-bonding-treatment-1', 'https://korean-skincare.fr/products/cosrx-peptide-132-ultra-perfect-hair-bonding-treatment-1', 'https://aurore-cdn.b-cdn.net/products/cosrx-peptide-132-ultra-perfect-hair-bonding-treatment-1.webp', 'Distribue le traitement : Presse une petite quantité de Peptide-132 Ultra Perfect Hair Bonding Treatment COSRX dans tes paumes. Applique sur les cheveux : Étale uniformément des mi-longueurs jusqu’aux pointes sur cheveux propres et essorés après le shampooing. Masse délicatement : Travaille le produit dans tes cheveux pour assurer une pénétration profonde, en insistant sur les zones abîmées. Rince soigneusement : Laisse poser 5 à 10 minutes, puis rince à l’eau tiède ; utiliser 1 à 2 fois par semaine.', 2095, '2026-05-07 17:37:38.352909+00', '2026-06-14 15:14:07.68+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c2e-7e09-9d50-9a04d8d7dcfd', '__OWNER_ID__', 'Full Fit Honey Sugar Lip Scrub', 'COSRX', 'lip-care', 'tube', 'Sucrose, Caprylic/Capric Triglyceride, Glycerin, Euphorbia Cerifera Cera, Sorbeth-30 Tetraoléate, Butyrospermum Parkii Butter, Bis-Diglycéryl Polyacyladipate-2, Aqua, Hectorite de Stearalkonium, 1,2-Hexanediol, Carbonate de Propylène, Extrait de Theobroma Cacao (Cacao), Ethylhexylglycerin, Butylene Glycol, Saccharum Officinarum Extract, Dextrin, Citrus Limon Fruit Extract, Mel', 'Le Full Fit Honey Sugar Lip Scrub COSRX est un gommage pour les lèvres qui élimine en douceur les peaux mortes grâce à des cristaux de sucre et maintient les lèvres hydratées grâce à de l''extrait de miel. Il laisse tes lèvres agréables et douces comme du velours. Utilise le gommage pour préparer tes lèvres avant d''appliquer du rouge à lèvres pour un résultat super lisse.', 20, 'g', 'cosrx-fulll-fit-honey-sugar-lip-scrub', 'https://korean-skincare.fr/products/cosrx-fulll-fit-honey-sugar-lip-scrub', 'https://aurore-cdn.b-cdn.net/products/cosrx-fulll-fit-honey-sugar-lip-scrub.webp', 'À l''aide de la spatule incluse, prélève une petite quantité de produit. Utilise le bout de tes doigts pour frotter doucement sur tes lèvres jusqu''à ce qu''elles soient douces. Rince soigneusement à l''eau et applique ensuite un baume pour les lèvres.', 1584, '2026-05-07 17:37:38.350766+00', '2026-06-14 15:14:07.68+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c37-7b25-8d12-9d63d171c516', '__OWNER_ID__', 'Refresh AHA BHA VITAMIN C Daily Cream', 'COSRX', 'moisturizer', 'jar', 'Extrait de fruit d''Actinidia Chinensis, Extrait de fruit d''Hylocereus Undatus, Eau d''Hippophae Rhamnoides, Butylene Glycol, Cetyl Ethylhexanoate, Niacinamide, 1,2-Hexanediol, Macadamia Ternifolia Seed Oil, Cetearyl Alcohol, Betaine, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Ethylhexylglycerin, Carbomer, Arginine, Panthenol, Olivate de Cétéaryle, Sorbitan Olivate, Allantoin, Adenosine, Sodium Hyaluronate, Alpha-Arbutine, Lactate de Menthyle, Extrait de Mentha Haplocalix, Tocopherol, Lactobionic Acid, Huile de fruit de Citrus Aurantium Bergamia, Bétaïne Salicylate, Ascorbyl Glucoside, Glycolic Acid, Aqua', 'La Refresh AHA BHA VITAMIN C Daily Cream COSRX est une crème exfoliante douce mais efficace qui aide à éclaircir et à hydrater la peau. Elle contient un mélange d''acides alpha-hydroxy (AHA) et d''acides bêta-hydroxy (BHA) qui agissent ensemble pour éliminer les cellules mortes de la peau et désincruster les pores, tout en favorisant le renouvellement des cellules cutanées pour un teint plus lisse et plus éclatant. L''acide glycolique contenu dans ce produit aide également à briser les liens entre les cellules mortes de la peau, révélant ainsi une peau plus lumineuse et au teint plus uniforme. En plus de ses propriétés exfoliantes, la Refresh AHA BHA VITAMIN C Daily Cream COSRX contient également de la vitamine C, qui aide à éclaircir la peau et à réduire l''apparence des taches brunes et de l''hyperpigmentation. La vitamine C est un puissant antioxydant qui aide à protéger la peau des facteurs de stress environnementaux comme la pollution et les rayons UV, tout en favorisant la production de collagène pour une peau plus ferme et d''apparence plus jeune. Globalement, la Refresh AHA BHA VITAMIN C Daily Cream COSRX est un produit de soin polyvalent qui peut aider à améliorer l''apparence et la texture de ta peau. Que tu souffres d''acné, de taches brunes ou de sécheresse, cette crème peut aider à résoudre ces problèmes tout en fournissant une exfoliation et une hydratation douces.', 50, 'ml', 'cosrx-refresh-aha-bha-vitamin-c-daily-cream', 'https://korean-skincare.fr/products/cosrx-refresh-aha-bha-vitamin-c-daily-cream', 'https://aurore-cdn.b-cdn.net/products/cosrx-refresh-aha-bha-vitamin-c-daily-cream.webp', 'Applique uniformément sur ton visage jour et nuit. Tapote délicatement ta peau pour la faire pénétrer.', 1599, '2026-05-07 17:37:38.359576+00', '2026-06-14 15:14:07.68+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c3b-7fce-8d61-f2822c93ddc1', '__OWNER_ID__', 'Refresh AHA BHA Vitamin C Lip Plumper', 'COSRX', 'lip-care', 'tube', 'Petrolatum, Hydrogenated Polyisobutene, Polyisobutene, Phytosteryl/​Isostearyl/​Cetyl/​Stearyl/​Behenyl Dimer Dilinoleate, Butyrospermum Parkii Butter, Diisostearyl Malate, Ethylene/​Propylene/​Styrene Copolymer, Sorbitan Sesquioleate, Microcrystalline Wax, Vanillyl Butyl Ether, Butylene/​Ethylene/​Styrene Copolymer, Ethylhexylglycerin, Aqua, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Butylene Glycol, Melia Azadirachta Leaf Extract, Melia Azadirachta Flower Extract, Coccinia Indica Fruit Extract, Amber Powder, Mentha Piperita (Peppermint) Leaf Extract, Solanum Melongena Fruit Extract, Ocimum Sanctum Leaf Extract, Curcuma Longa Root Extract, Corallina Officinalis Extract, Moringa Oleifera Seed Oil, Magnesium Ascorbyl Phosphate, Citric Acid, Betaine Salicylate, Anemarrhena Asphodeloides Root Extract', 'Le Refresh AHA BHA Vitamin C Lip Plumper COSRX est un repulpeur de lèvres énergisant et polyvalent qui donne visiblement du volume à tes lèvres, les lisse et les hydrate.', 20, 'g', 'cosrx-refresh-aha-bha-vitamin-c-lip-plumper', 'https://korean-skincare.fr/products/cosrx-refresh-aha-bha-vitamin-c-lip-plumper', 'https://aurore-cdn.b-cdn.net/products/cosrx-refresh-aha-bha-vitamin-c-lip-plumper.webp', 'Applique une bonne quantité sur tes lèvres. Il se peut que tu ressentes des picotements dus à l''effet repulpant du produit selon l''état de tes lèvres, ce qui est courant pour les produits repulpants pour les lèvres (causé par le Vanillyl Butyl Ether).', 1661, '2026-05-07 17:37:38.363886+00', '2026-06-14 15:14:07.681+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c40-723f-b108-5d6de282e40e', '__OWNER_ID__', 'Hydrium Moisture Power Enriched Cream', 'COSRX', 'moisturizer', 'jar', 'Aqua, Glycerin, Ethylhexyl Stearate, Vinyl Diméthicone, Pentylene Glycol, Cocos Nucifera Oil, 1,2-Hexanediol, Cetearyl Alcohol, Panthenol, Polyméthylsilsesquioxane, Alcool Arachidylique, Extrait de Propolis, Copolymère d''Acrylate d''Hydroxyéthyl/Sodium Taurate de Diméthyl, Stéarate de Polyglycéryl-6, Butylene Glycol, Carbomer, Behenyl Alcohol, Glyceryl Stearate, Tromethamine, Dimethiconol, Caprylyl Glycol, Glucoside d''Arachidyle, Hydrogenated Lecithin, Ceramide NP, Ethylhexylglycerin, Gomme Xanthane, Stéarate de Saccharose, Béhénate de Polyglycéryl-6, Amidon de Polyacrylate de Sodium, Stearic Acid, Palmitic Acid, Sodium Hyaluronate, Cholesterol, Hyaluronic Acid, Glycosphingolipides, Hydrolyzed Hyaluronic Acid', 'La Hydrium Moisture Power Enriched Cream COSRX donne à la peau une hydratation intense et durable sans provoquer d''acné ou boucher les pores. La vitamine B5 (d-panthénol) hydrate et agit comme un agent anti-inflammatoire, tandis que la propolis aide à équilibrer le ratio huile/eau de la peau. Le céramide protège et renforce la barrière cutanée.', 50, 'ml', 'cosrx-hydrium-moisture-power-enriched-cream', 'https://korean-skincare.fr/products/cosrx-hydrium-moisture-power-enriched-cream', 'https://aurore-cdn.b-cdn.net/products/cosrx-hydrium-moisture-power-enriched-cream.webp', 'Apply after cleansing and toning, and follow with moisturizer. Gently massage all over face and dab for better absorption.', 3068, '2026-05-07 17:37:38.368064+00', '2026-06-14 15:14:07.681+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c48-790a-b1d2-6f14deea1f7a', '__OWNER_ID__', 'Peptide-132 Ultra Perfect Hair Bonding Oil Serum', 'COSRX', 'serum', 'dropper', 'Dimethicone, Hydrogenated Poly(C6-14 Olefin), Cetyl Ethylhexanoate, Dicaprylyl Carbonate, Dimethiconol, Disiloxane, Dicaprylyl Ether, Aminopropyl Dimethicone, Argania Spinosa Kernel Oil, Hexyldecanol, Parfum, Tocopherol, Olea Europaea Fruit Oil, Camellia Japonica Seed Oil, Simmondsia Chinensis Seed Oil, Oryza Sativa (Rice) Bran Oil, Vitis Vinifera Seed Oil, Macadamia Ternifolia Seed Oil, Tripeptide-1, Tripeptide-3, Tripeptide-2', 'Le Peptide-132 Ultra Perfect Hair Bonding Oil Serum COSRX est un sérum capillaire léger et performant conçu pour renforcer et réparer les cheveux abîmés. Infusé du PEPTIDE-132™ breveté de la marque, il aide à renforcer les liens de kératine, offrant plus de solidité et de résilience. La formule contient également un mélange de 7 huiles végétales et de vitamine E, qui nourrissent les cheveux, réduisent les frisottis et apportent une brillance éclatante sans laisser de résidu gras. Sa texture ultra-légère s’absorbe rapidement, convenant à tous les types de cheveux, en particulier les cheveux épais ou abîmés. Recommandé pour : Tous types de cheveux, particulièrement abîmés, frisottants ou épais.', 28, 'ml', 'cosrx-peptide-132-ultra-perfect-hair-bonding-oil-serum', 'https://korean-skincare.fr/products/cosrx-peptide-132-ultra-perfect-hair-bonding-oil-serum', 'https://aurore-cdn.b-cdn.net/products/cosrx-peptide-132-ultra-perfect-hair-bonding-oil-serum.webp', 'Applique une petite quantité de sérum sur cheveux humides ou secs, en concentrant sur les longueurs et les pointes. Répartis délicatement le produit avec les doigts ou un peigne. Coiffe comme d’habitude. Pour des résultats optimaux, utilise quotidiennement pour maintenir douceur et brillance.', 1995, '2026-05-07 17:37:38.376464+00', '2026-06-14 15:14:07.682+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c46-753d-9bcb-f8d5407038ee', '__OWNER_ID__', '5 PDRN Hyaluronic Acid Vital Hydrating Hydrogel Mask', 'COSRX', 'mask', 'pack', 'Aqua, Glycerin, Acrylates Copolymer, Niacinamide, 1,2-Hexanediol, Ceratonia Siliqua Gum, Chondrus Crispus, Agar, Sclerotium Gum, Potassium Chloride, Sucrose, Butylene Glycol, Sodium Hyaluronate, Cellulose Gum, Polyglyceryl-10 Laurate, Panthenol, Allantoin, Xanthan Gum, Ethylhexylglycerin, Adenosine, Coptis Japonica Root Extract, Sodium Phytate, Sodium DNA, Alpha-Arbutin, Cyanocobalamin, Lactobacillus Ferment, Hydrolyzed Collagen, Centella Asiatica Extract, Caprylyl Glycol, Hydroxypropyltrimonium Hyaluronate, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Hyaluronic Acid, Potassium Hyaluronate, Sodium Hyaluronate Crosspolymer, Tocopherol, Acetyl Hexapeptide-8, Propanediol, Pentylene Glycol, Sodium Acetylated Hyaluronate, Hydrolyzed DNA', 'Le 5 PDRN Hyaluronic Acid Vital Hydrating Hydrogel Mask COSRX est un masque ultra-apaisant et profondément reconstituant conçu pour offrir une hydratation instantanée et durable. Formulé avec 5 types de PDRN pour favoriser la régénération et la résistance de la peau, ainsi que de l’acide hyaluronique pour retenir l’hydratation, ce masque hydrogel luxueux aide à repulper la peau et à restaurer un éclat sain et lumineux. Le matériau hydrogel rafraîchissant adhère parfaitement au visage, maximisant l’absorption sans glisser ni se dessécher. Idéal pour les peaux sèches, déshydratées ou fatiguées, ce masque revitalise et apaise instantanément, le rendant parfait après une exposition au soleil, pour récupérer après un voyage ou pour ton boost d’hydratation hebdomadaire. Avec une utilisation régulière, le 5 PDRN Hyaluronic Acid Vital Hydrating Hydrogel Mask COSRX favorise un teint plus lisse, plus ferme et plus éclatant. Recommandé pour : Peaux sèches, déshydratées ou fatiguées.', 1, 'pcs', 'cosrx-5-pdrn-hyaluronic-acid-vital-hydrating-hydrogel-mask-set', 'https://korean-skincare.fr/products/cosrx-5-pdrn-hyaluronic-acid-vital-hydrating-hydrogel-mask-set', 'https://aurore-cdn.b-cdn.net/products/cosrx-5-pdrn-hyaluronic-acid-vital-hydrating-hydrogel-mask-set.webp', 'Après le nettoyage et l’application d’un tonique, applique le masque hydrogel sur ton visage en l’ajustant aux contours de ton visage. Laisse poser pendant 15 à 20 minutes, puis retire-le et tapote délicatement l’essence restante. Pas besoin de rincer.', 495, '2026-05-07 17:37:38.374218+00', '2026-06-14 15:14:07.682+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c42-728f-80a9-a2958bb77e71', '__OWNER_ID__', 'Cica Creamy Foam Cleanser', 'COSRX', 'cleanser', 'tube', 'Aqua, Glycerin, Myristic Acid, Palmitic Acid, Stearic Acid, Lauric Acid, Potassium Hydroxide, Glyceryl Stearate, 1,2-Hexanediol, Polyquaternium-7, Ethylhexylglycerin, Citrus Limon Fruit Extract, Huile de Citrus Nobilis, Disodium EDTA, Butylene Glycol, Eucalyptus Globulus Leaf Oil, Lavandula Angustifolia Oil, Huile de Pinus Palustris, Melia Azadirachta Leaf Extract, Extrait de Fleur de Melia Azadirachta, Sodium Benzoate, Coccinia Indica Fruit Extract, Poudre d''Ambre, Solanum Melongena Fruit Extract, Ocimum Sanctum Leaf Extract, Curcuma Longa Root Extract, Extrait de Feuille de Centella Asiatica, Extrait de Corallina Officinalis, Moringa Oleifera Seed Oil, Hydrogenated Lecithin, Caprylic/Capric Triglyceride, Stéarate de Saccharose, Centella Asiatica Extract, Cetyl Alcohol, Extrait de Racine de Centella Asiatica, Acide Asiatique, Asiaticoside, Acide Madécassique, Madecassoside', 'Le Cica Creamy Foam Cleanser COSRX est un formidable nettoyant qui transformera ta routine beauté. Infusée du complexe Pure Fit Cica-7, cette mousse nettoyante crémeuse offre une protection ultime à ta peau délicate tout en éliminant la saleté et les impuretés. Formulé avec des ingrédients puissants comme la Centella Asiatica, ce nettoyant aide à calmer la peau irritée, à réduire les rougeurs et l''inflammation, et à favoriser un teint plus sain et plus uniforme. La texture crémeuse de la mousse offre une expérience de nettoyage à la fois douce et efficace qui laisse à ta peau une sensation de fraîcheur et de propreté, sans la décaper de son hydratation essentielle. La Cica Creamy Foam Cleanser COSRX convient à tous les types de peau, en particulier aux personnes ayant une peau sensible ou à tendance acnéique. Le complexe Pure Fit Cica-7 aide à renforcer la barrière cutanée, à prévenir les éruptions futures et à garantir que ta peau reste saine et protégée.', 150, 'ml', 'cosrx-cica-creamy-foam-cleanser', 'https://korean-skincare.fr/products/cosrx-cica-creamy-foam-cleanser', 'https://aurore-cdn.b-cdn.net/products/cosrx-cica-creamy-foam-cleanser.webp', 'Distribue une quantité suffisante de nettoyant sur tes mains mouillées pour faire le faire mousser. Masse délicatement la mousse sur ton visage. Rince abondamment à l''eau tiède.', 1095, '2026-05-07 17:37:38.370067+00', '2026-06-14 15:14:07.682+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c52-752d-a9a0-ba0a73370bc5', '__OWNER_ID__', 'Vitamin E Vitalizing Sunscreen', 'COSRX', 'moisturizer', 'jar', 'Aqua, Propanediol, Homosalate, Octocrylene, Ethylhexyl Salicylate, Butyloctyl Salicylate, Avobenzone, Diphenylsiloxy Phényl Triméthicone, Dimethicone, Copolymère VP/Eicosène, Silica, Trisiloxane, Cyclopentasiloxane, Trimethylsiloxysilicate, 1,2-Hexanediol, Behenyl Alcohol, Glyceryl Stearate, PEG-100 Stearate, Alcools C14-22, Cetyl Alcohol, Phosphate de Potassium Cétylique, Polyacrylate-13, Polyisobutene, Parfum, Glucoside d''Alkyle C12-20, Butylene Glycol, Disodium EDTA, Ethylhexylglycerin, Polysorbate 20, Sorbitan Isostearate, Dextrin, Extrait de Cacao (Theobroma Cacao), Extrait de Coton (Gossypium Herbaceum), Glucose, Tocopherol', 'La Vitamin E Vitalizing Sunscreen COSRX est une crème solaire à large spectre d''indice de protection SPF 50+ PA+++. En plus d''une formule légère, il est enrichi de vitamine E et de silice pour réduire l''apparence des rides et ridules et réguler la production excessive de sébum pour un fini mat. Sa formule non grasse ne laisse pas de traces blanches.', 50, 'ml', 'cosrx-vitamin-e-vitalizing-sunscreen', 'https://korean-skincare.fr/products/cosrx-vitamin-e-vitalizing-sunscreen', 'https://aurore-cdn.b-cdn.net/products/cosrx-vitamin-e-vitalizing-sunscreen.webp', 'Applique 15 minutes avant de sortir au soleil sur les zones du visage/corps exposées au soleil. Renouvelle l''application toutes les deux heures pour une protection solaire optimale pendant la journée.', 1662, '2026-05-07 17:37:38.386191+00', '2026-06-14 15:14:07.682+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c58-7fab-be9d-9f2e3831e5fd', '__OWNER_ID__', 'Hydrium Centella Aqua Soothing Ampoule', 'COSRX', 'serum', 'dropper', 'Aqua, Centella Asiatica Extract, Dipropylene Glycol, Glycerin, 1,2-Hexanediol, Betaine, Chondrus Crispus Extract, Saccharum Officinarum Extract, Pentylene Glycol, Octanediol, Copolymère d''Acrylodiméthyltaurate/VP d''Ammonium, Gomme Xanthane, Ethylhexylglycerin, Allantoin, Madecassoside, Panthenol', 'La Hydrium Centella Aqua Soothing Ampoule COSRX est une ampoule légère à absorption rapide qui hydrate et calme efficacement les peaux sensibles. Elle est composée à 42 % d''extrait de Centella Asiatica pour calmer les peaux sensibilisées, tandis que la vitamine B5 (d-panthénol) vient hydrater la peau et agit comme un agent anti-inflammatoire.', 40, 'ml', 'cosrx-hydrium-centella-aqua-soothing-ampoule', 'https://korean-skincare.fr/products/cosrx-hydrium-centella-aqua-soothing-ampoule', 'https://aurore-cdn.b-cdn.net/products/cosrx-hydrium-centella-aqua-soothing-ampoule.webp', 'Applique deux ou trois gouttes sur ton visage en évitant le contour des yeux et de la bouche. Répartis uniformément et masse pour une absorption optimale.', 2245, '2026-05-07 17:37:38.392835+00', '2026-06-14 15:14:07.682+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c54-7851-a7ed-c60e03a1887e', '__OWNER_ID__', 'One Step moisture Up Pad', 'COSRX', 'exfoliant', 'pack', 'Aqua, Butylene Glycol, Propanediol, Glycerin, 1,2-Hexanediol, Betaine Salicylate, Betaine, Panthenol, Allantoin, Myristate de Polyglyceryl-10, Laurate de Polyglyceryl-10, Sodium Hydroxide, Gluconolactone, Sodium Hyaluronate, Huile de Fruit de Citrus Aurantium Bergamia (Bergamote), Carbomer, Arginine, Citrus Limon Peel Oil, Pentylene Glycol, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Hyaluronic Acid, Ethylhexylglycerin, Squalane', 'Comme un mini traitement pour le visage en un seul geste, les One Step Moisture Up Pads COSRX constituent un moyen ingénieux et pratique d''exfolier en douceur et de régénérer les peaux sèches et sensibles. Ces compresses désaltérantes et tonifiantes sont imprégnées d''un cocktail d''ingrédients bénéfiques, dont de l''extrait de propolis - un antiseptique naturel efficace pour traiter les imperfections, l''acné et les rougeurs - et de l''acide hyaluronique hydratant. Un incontournable cosmétique coréen qui procure une hydratation durable.', 70, 'pcs', 'cosrx-one-step-moisture-up-pad', 'https://korean-skincare.fr/products/cosrx-one-step-moisture-up-pad', 'https://aurore-cdn.b-cdn.net/products/cosrx-one-step-moisture-up-pad.webp', 'Utilise une compresse lors de l''étape du tonique après le nettoyage, une ou deux fois par jour. Passe délicatement la compresse sur ta peau. Tapote et absorbe l''excédent d''essence apaisante sur ta peau. Procède à tes soins habituels sans rincer. Replace le couvercle hermétiquement pour t''assurer que les compresses restent humides et propres.', 1583, '2026-05-07 17:37:38.388397+00', '2026-06-14 15:14:07.683+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c5b-71b1-95be-4afb3269961f', '__OWNER_ID__', 'Green Hero Calming Pad', 'COSRX', 'exfoliant', 'pack', 'Camellia Sinensis Leaf Water, Butylene Glycol, Extrait de Feuille de Taraxacum Officinale, Centella Asiatica Extract, Hamamelis Virginiana Leaf Extract, Melaleuca Alternifolia Leaf Extract, Extrait d''Artemisia Princeps, 1,2-Hexanediol, Extrait de Graine de Cassia Obtusifolia, Lactobionic Acid, Maltodextrin, Parthénol, Laurate de Polyglycéryl-10, Myristate de Polyglycéryl-10, Glycerin, Arginine, Acide Asiatique, Acide Madécassique, Sodium Hyaluronate, Allantoin, Asiaticoside, Extrait de Gardenia, Huile de Fruit de Citrus Aurantium Bergamia, Lactate de Menthol, Extrait de Mentha Haplocalix', 'Les Green Hero Calming Pads COSRX ont été imprégnées d''une essence destinée à apaiser et à calmer la peau irritée. Elles sont formulées avec le complexe green-RX (eau de feuille de Camellia Sinensis, extrait de Centella Asiatica, Hamamelis Virginiana, extrait de feuille de ti, extrait d''Artemisia Princeps) pour rafraîchir, calmer et hydrater tandis que le PHA élimine en douceur les cellules mortes. Ce tonique aide à cibler les rougeurs, la peau déshydratée, l''excès de sébum et les pores visibles.', 70, 'pcs', 'cosrx-green-hero-calming-pad', 'https://korean-skincare.fr/products/cosrx-green-hero-calming-pad', 'https://aurore-cdn.b-cdn.net/products/cosrx-green-hero-calming-pad.webp', 'Utilise les compresses lors de l''étape du tonique après le nettoyage, une ou deux fois par jour. Passe délicatement la compresse sur ta peau. Tapote et fais pénétrer le reste de l''essence apaisante sur ta peau. Procède à tes soins habituels sans rincer. Replace le couvercle hermétiquement pour t''assurer que les compresses restent humides et propres.', 2133, '2026-05-07 17:37:38.394996+00', '2026-06-14 15:14:07.683+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c5f-74b2-9ed3-aebf7d0a2256', '__OWNER_ID__', 'Aloe 54.2 Aqua Tone-Up Sunscreen', 'COSRX', 'moisturizer', 'jar', 'Eau de Feuille d''Aloe Barbadensis, Homosalate, Butylene Glycol, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Ethylhexyl Salicylate, Glycerin, Aqua, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Benzoate d''Alkyle C12-15, Méthicone Triméthyle, Niacinamide, Dioxyde de Titane CI 77891, Diisopropyl Sebacate, Acide Téréphtalylidène Dicamphor Sulfonique, 1,2-Hexanediol, Phosphate de Cétyle de Potassium, Cetearyl Alcohol, Tromethamine, Glyceryl Stearate, Behenyl Alcohol, Polyacrylate Crosspolymer-6, Gomme Xanthane, Taurate de Polyacryloyldiméthyl Taurate de Sodium, Hydrogenated Lecithin, Polyacrylate d''Alkyle C10-30, Ethylhexylglycerin, Stearic Acid, Hydroxyde d''Aluminium, Distéarate de Methylglucose Polyglycéryle-3, Palmitic Acid, Oxydes de Fer CI 77491, Disodium EDTA, Triéthoxycaprylylsilane, Oxydes de Fer CI 77492, Sodium Hyaluronate, Allantoin, Myristic Acid, Cyanocobalamin, Lauric Acid, Tocopherol', 'L''Aloe 54.2 Aqua Tone-Up Sunscreen COSRX agit comme un bouclier protecteur contre les rayons UV nocifs, infusé avec 54,2 % d''eau de feuilles d''Aloe Barbadensis qui non seulement défend la peau mais lui offre également une sensation d''apaisement. Cet écran solaire, fonctionnant comme crème solaire éclaircissante, bénéficie d''une formulation douce et non grasse qui protège la peau tout en lui donnant un éclat sain et radieux. Infusée de vitamine B12, elle répond aux préoccupations des peaux sensibles, cible le dessèchement de la peau et l''acné, et protège contre les dommages causés par les UV tout en maintenant l''hydratation et l''élasticité de la peau. L''incorporation de la vitamine B3 aide à soulager les dommages causés par les rayons UV et à combattre les problèmes de pigmentation, tandis que l''acide hyaluronique et l''allantoïne agissent en synergie pour garder la peau hydratée, rebondie et exempte d''irritation, offrant une solution de protection solaire qui se double d''un hydratant léger pour un teint d''apparence fraîche et radieuse. Formulé avec de l''essence apaisante d''eau de feuilles d''Aloe Barbadensis, cette crème solaire va au-delà de la protection contre les UV, en contribuant à la réparation et à l''hydratation de la peau. Sa composition avancée, qui comprend des vitamines essentielles et de l''Acide Hyaluronique, protège non seulement contre les dommages causés par les UV, mais combat également la sécheresse de la peau, en assurant son élasticité et en prévenant la pigmentation. Exempte des éléments typiques des écrans solaires traditionnels qui sont souvent à l''origine d''une sécheresse de la peau, cette crème solaire se distingue comme une solution polyvalente adaptée aux peaux sensibles, offrant une texture légère et non collante qui fait office de base de maquillage efficace tout en apaisant et en hydratant la peau pour une apparence naturelle et radieuse tout au long de la journée. Recommandé pour : Peaux sensibles, sèches, tous types de peaux.', 50, 'ml', 'cosrx-aloe-54-2-aqua-tone-up-sunscreen', 'https://korean-skincare.fr/products/cosrx-aloe-54-2-aqua-tone-up-sunscreen', 'https://aurore-cdn.b-cdn.net/products/cosrx-aloe-54-2-aqua-tone-up-sunscreen.webp', 'Applique généreusement 15 minutes sur les zones exposées avant de sortir au soleil. Renouvelle l''application au moins toutes les deux heures.', 1795, '2026-05-07 17:37:38.399177+00', '2026-06-14 15:14:07.683+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3d1c-7298-9ad8-b1f8c62c2650', '__OWNER_ID__', 'SoonJung 10-Free Moist Emulsion', 'ETUDE', 'moisturizer', 'jar', 'Aqua, Glycerin, Propanediol, Pentaerythrityl Tetraethylhexanoate, Squalane, Panthenol, Cetearyl Alcohol, Bis-Diglyceryl Polyacyladipate-2, Ammonium Acryloyldimethyltaurate/VP Copolymer, Polyglyceryl-3 Methylglucose Distearate, Glyceryl Stearate, Stearic Acid, Hydrogenated Lecithin, Xanthan Gum, Glyceryl Caprylate, Disodium EDTA, Hydroxypropyl Starch Phosphate, Ethylhexylglycerin, Madecassoside, Butylene Glycol, Tocopherol, Camellia Sinensis Leaf Extract', 'La SoonJung 10 Free Moist Emulsion Etude House est une crème hydratante légère à faible pH, parfaite pour apaiser les peaux sensibles. Formulée avec 93 % d''ingrédients d''origine naturelle, cette émulsion apaisante utilise le panthénol, le madécassoside et le squalane pour hydrater en profondeur, redonner de l''élasticité et réparer les peaux abîmées ou stressées. Exempte d''irritants potentiels, notamment de parfums, de colorants artificiels et de parabènes, cette crème hydratante aide à renforcer la résistance de la peau pour lui redonner sa santé et son équilibre.', 130, 'ml', 'etude-house-soon-jung-10-free-moist-emulsion', 'https://korean-skincare.fr/products/etude-house-soon-jung-10-free-moist-emulsion', 'https://aurore-cdn.b-cdn.net/products/etude-house-soon-jung-10-free-moist-emulsion.webp', 'Applique une quantité suffisante sur ta peau. Tapote délicatement pour faciliter l''absorption.', 1795, '2026-05-07 17:37:38.587969+00', '2026-06-14 15:14:07.683+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c61-793e-b1fe-b8157549bc18', '__OWNER_ID__', 'The Peptide Collagen Hydrogel Eye Patch', 'COSRX', 'eye-cream', 'jar', 'Aqua, Dipropylene Glycol, Glycerin, Niacinamide, Ceratonia Siliqua Gum, Chondrus Crispus Powder, Chondrus Crispus, Cellulose Gum, Hydroxyacetophenone, Algin, Caprylyl Glycol, Potassium Chloride, Betaine, Panthenol, Sucrose, Ethylhexylglycerin, Sodium Polyacrylate, Polyglyceryl-10 Laurate, Adenosine, Polyglyceryl-10 Myristate, Maltodextrin, Caffeine, Collagen, Butylene Glycol, Cyanocobalamin, 1,2-Hexanediol, Sodium Hyaluronate, Dipotassium Glycyrrhizate, Pantolactone, Pentylene Glycol, Acetyl Hexapeptide-8, Dunaliella Salina Extract, sh Polypeptide-121, Palmitoyl Tripeptide-5, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Potassium Hyaluronate, Hydrolyzed Sodium Hyaluronate, Acetyl Tetrapeptide-5, Citric Acid, Disodium EDTA', 'Les Peptide Collagen Hydrogel Eye Patches COSRX sont un soin ciblé conçu pour illuminer, raffermir et hydrater la zone délicate du contour des yeux. Enrichis en collagène, peptides et niacinamide, ces patchs hydrogel rafraîchissants aident à réduire l’apparence des ridules, des poches et des cernes tout en améliorant l’élasticité et la texture de la peau. Le matériau hydrogel adhère confortablement à la peau, permettant aux ingrédients actifs de pénétrer efficacement sans glisser ni se dessécher. Parfait pour les peaux fatiguées, stressées ou vieillissantes, ces patchs offrent un effet immédiat et des bienfaits durables en cas d’utilisation régulière. Que ce soit pour préparer le maquillage, se détendre le soir ou rafraîchir le regard après une longue journée, les Peptide Collagen Hydrogel Eye Patches COSRX procurent un effet apaisant et raffermissant qui laisse le contour des yeux visiblement plus lumineux, lisse et bien hydraté. Recommandé pour : Tous types de peaux.', 60, 'pcs', 'cosrx-the-peptide-collagen-hydrogel-eye-patch', 'https://korean-skincare.fr/products/cosrx-the-peptide-collagen-hydrogel-eye-patch', 'https://aurore-cdn.b-cdn.net/products/cosrx-the-peptide-collagen-hydrogel-eye-patch.webp', 'Après le nettoyage et le tonique, utilise la spatule fournie pour appliquer un patch sous chaque œil. Laisse poser 15–20 minutes, puis tapote délicatement l’essence restante. Utilise 2–3 fois par semaine ou selon les besoins.', 1935, '2026-05-07 17:37:38.401437+00', '2026-06-14 15:14:07.683+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c69-74cc-a400-206f3bcb67af', '__OWNER_ID__', 'Relief Sun Aqua-fresh : Rice + B5 SPF50+ PA++++', 'Beauty of Joseon', 'moisturizer', 'jar', 'Aqua, Eau de Graine d''Oryza Sativa, Dibutyl Adipate, Butyloctyl Salicylate, Ethylhexyl Triazone, 1,2-Hexanediol, Drometrizole Trisiloxane, Polyglycéryl-3 Distearate, Terephthalylidene Dicamphor Sulfonic Acid, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Polyméthylsilsesquioxane, Tromethamine, Panthenol, Pentylene Glycol, Glycérine Stéarate, Silica, Caprylyl Méthicone, Avena Sativa Kernel Extract, Extrait de Feuille de Cynara Scolymus, Camellia Sinensis Leaf Water, Hydrogenated Lecithin, Huile de Son d''Oryza Sativa, Sodium Hyaluronate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Propanediol, Phosphate de Cétyl de Potassium, Poly C10-30 Alkyl Acrylate, Methylpropanediol, Carbomer, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Ethylhexylglycerin, Gomme de Xanthane, Glycerin, Polyéther-1, Polyquaternium-51, Beta-Glucan, Biosaccharide Gum-1, Inositol, Tocopherol, Acide Phérolique, Citric Acid, Ceramide NP, Phytosphingosine, Acides Aminés de Riz, Rice sh-Oligopeptide-2', 'Obtiens l''équilibre ultime entre hydratation et protection solaire avec le Relief Sun Aqua-fresh : Rice + B5 Beauty of Joseon. Cette version améliorée de la crème solaire populaire Relief Sun offre une protection à large spectre SPF 50+ PA++++ dans une formule légère à absorption rapide. Enrichie de 30 % d''eau de riz, de panthénol (vitamine B5) et d''avoine colloïdale, elle nourrit, apaise et revitalise la peau agressée par l''exposition aux UV. Parfaite pour tous les types de peaux, sa texture aqueuse, semblable à celle d''une lotion, ne laisse pas de traces blanches ni de résidus collants, ce qui la rend idéale pour ceux qui préfèrent un fini transparent et satiné. Profite d''une peau hydratée et éclatante de santé grâce à ce produit quotidien essentiel et rafraîchissant. Recommandé pour : Tous types de peaux.', 50, 'ml', 'beauty-of-joseon-relief-sun-aqua-fresh-rice-b5', 'https://korean-skincare.fr/products/beauty-of-joseon-relief-sun-aqua-fresh-rice-b5', 'https://aurore-cdn.b-cdn.net/products/beauty-of-joseon-relief-sun-aqua-fresh-rice-b5.webp', 'Lors de la dernière étape de ta routine beauté, étale une quantité généreuse de produit sur les zones exposées au soleil. Renouvelle l''application toutes les 2 à 3 heures.', 1426, '2026-05-07 17:37:38.409134+00', '2026-06-14 15:14:07.684+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c6c-7ae3-87c1-0dded6a383b9', '__OWNER_ID__', 'Glow Deep Serum : Rice + Alpha-Arbutin', 'Beauty of Joseon', 'serum', 'dropper', 'Eau de Son d''Oryza Sativa (Riz), Aqua, Glycerin, Butylene Glycol, 1,2-Hexanediol, Dipropylene Glycol, Alpha-Arbutine, Niacinamide, Méthyl Gluceth-20, Panthenol, Polyglycérine-3, Trehalose, Glyceryl Glucoside, Esters Hydrolysés de Jojoba, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Ethylhexylglycerin, Hydroxyéthylcellulose, Gomme Xanthane, Arginine, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Arginine, Disodium EDTA, Coptis Japonica Root Extract, Sorbitan Isostearate, Glucose, Extrait de Graine de Coix Lacryma-Jobi Ma-Yuen, Extrait de Graine de Soja (Glycine Soja), Extrait d''Orge (Hordeum Distichon), Oryza Sativa Extract, Extrait de Graine de Sésame (Sesamum Indicum), Extrait de Graine de Blé (Triticum Vulgare), Extrait de Graine de Vigna Radiata, Extrait de Maïs (Zea Mays)', 'Le Glow Deep Serum : Rice + Alpha-Arbutin Beauty Of Joseon est un sérum léger et hydratant enrichi d''ingrédients Hanbang (médecine traditionnelle coréenne à base de plantes) pour éclaircir la peau et lutter contre la pigmentation. L''arbutine et l''eau de son de riz agissent efficacement pour éclaircir la peau terne et la rendre plus uniforme. Tous les ingrédients de ce sérum sont de catégorie verte certifiés par l''EWG. Recommandé pour : Peaux normales, sèches, sensibles. Peut être utilisé pour : Tous types de peaux.', 30, 'ml', 'beauty-of-joseon-glow-deep-serum-rice-arbutin', 'https://korean-skincare.fr/products/beauty-of-joseon-glow-deep-serum-rice-arbutin', 'https://aurore-cdn.b-cdn.net/products/beauty-of-joseon-glow-deep-serum-rice-arbutin.webp', 'Nettoie ton visage et sèche-le en le tapotant. Applique 2 à 3 gouttes de sérum sur ton visage, en évitant tes yeux. Tapote ensuite délicatement ta peau pour faciliter l''absorption.', 1262, '2026-05-07 17:37:38.412476+00', '2026-06-14 15:14:07.684+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c71-7d35-8612-ad064fdb80ea', '__OWNER_ID__', 'Ground Rice and Honey Glow Mask', 'Beauty of Joseon', 'mask', 'pack', 'Aqua, Kaolin, Mel, Glycerin, Propanediol, Dipropylene Glycol, Poudre de Coque d''Oryza Sativa, Isononyl Isononanoate, 1,2-Hexanediol, Cetyl Alcohol, Caprylic/Capric Triglyceride, Distéarate de Polyglycéryl-3 Méthylglucose, Glyceryl Stearate, Butylene Glycol, Son d''Oryza Sativa, Extrait de Lie d''Oryza Sativa, Oryza Sativa Extract, Extrait de Miel, Bentonite, Palmitic Acid, Stearic Acid, Behenyl Alcohol, Cellulose, Zea Mays Starch, Gomme Xanthane, Hydroxyacéto-phénone, Phosphate de Potassium Cétylique, Ethylhexylglycerin, Polyacrylate-13, Hydrogenated Polyisobutene, Sodium Phytate, Laurate de Polyglycéryl-10, Ethylhexyl Palmitate, Sorbitan Isostearate, Lactate de Menthy', 'Profite du pouvoir rajeunissant du Ground Rice and Honey Glow Mask Beauty of Joseon, un masque nettoyant transformateur enrichi de lie de makgeolli recyclée et d''ingrédients naturels tels que la poudre de cosse de riz et le miel. Ce masque multitâche offre des avantages complets en matière de soins de la peau, combinant des effets éclaircissants, antioxydants, hydratants et apaisants en une seule application. L''argile kaolin purifie les pores et absorbe l''excès de sébum, tandis que le miel hydrate en profondeur et calme les inflammations, laissant la peau purifiée et nourrie sans aucune sensation de tiraillement. La poudre de cosse de riz, qui exfolie en profondeur, améliore la texture de la peau, ce qui la rend adaptée à tous les types de peau. Améliore ta routine beauté avec ce masque pour obtenir une peau radieuse, lisse et revitalisée. Recommandé pour : Peaux sèches, tous types de peaux.', 150, 'ml', 'beauty-of-joseon-ground-rice-and-honey-glow-mask', 'https://korean-skincare.fr/products/beauty-of-joseon-ground-rice-and-honey-glow-mask', 'https://aurore-cdn.b-cdn.net/products/beauty-of-joseon-ground-rice-and-honey-glow-mask.webp', 'Après le nettoyage, applique le produit uniformément sur ton visage sec, en évitant le contour des yeux et de la bouche. Après 15 à 20 minutes, masse délicatement avec de l''eau tiède pour rincer.', 1337, '2026-05-07 17:37:38.417644+00', '2026-06-14 15:14:07.684+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c7b-7965-8ab4-7ced032d1dda', '__OWNER_ID__', 'Calming Serum Green Tea+Panthenol', 'Beauty of Joseon', 'serum', 'dropper', 'Camellia Sinensis Leaf Water, Artemisia Capillaris Extract (30%), Panthenol, Glycerin, Butylene Glycol, Aqua, 1,2-Hexanediol, Methylpropanediol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Tromethamine, Coptis Japonica Root Extract, Ethylhexylglycerin, Betaine, Allantoin, Dipotassium Glycyrrhizate, Glyceryl Acrylate/​Acrylic Acid Copolymer, Polyquaternium-51, Malt Extract, Punica Granatum Extract, Clitoria Ternatea Flower Extract, Garcinia Mangostana Peel Extract, Sodium Hyaluronate', 'Le Calming Serum Green Tea+Panthenol Beauty of Joseon est un sérum calmant enrichi de 76 % d''extrait de thé vert, de 2 % de panthénol et de vitamine C pour apaiser les peaux abîmées et sensibles tout en offrant des effets hydratants, anti-âge et éclaircissants pour redonner à la peau son éclat, sa santé et sa jeunesse. Recommandé pour : Peaux sensibles, peaux sèches. Peut être utilisé pour : Tous types de peaux.', 30, 'ml', 'beauty-of-joseon-calming-serum-propolis-niacinamide', 'https://korean-skincare.fr/products/beauty-of-joseon-calming-serum-propolis-niacinamide', 'https://aurore-cdn.b-cdn.net/products/beauty-of-joseon-calming-serum-propolis-niacinamide.webp', 'Nettoie ton visage et sèche-le en le tamponnant. Applique 2 à 3 gouttes de sérum sur ton visage, en évitant les yeux. Utilise-le quotidiennement pour un effet calmant et apaisant sur ta peau.', 1262, '2026-05-07 17:37:38.427472+00', '2026-06-14 15:14:07.684+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c77-70f3-906d-7b596f23e5d4', '__OWNER_ID__', 'Matte sun stick : Mugwort+Camelia SPF50 PA++++', 'Beauty of Joseon', 'moisturizer', 'jar', 'Methyl Methacrylate Crosspolymer, Synthetic Wax, Adipate De Dibutyle, Coco-Caprylate/Caprate, Isopropyl Palmitate, Caprylyl Méthicone, Caprylyl Triméthicone, Ethylhexyl Palmitate, Silica, Vinyl Diméthicone/Méthicone Silsesquioxane Crosspolymère, Benzoate D''hexyle Diéthylamino Hydroxybenzoyl, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Nitrure De Bore, Salicylate De Butyloctyle, Ethylhexyl Triazone, Microcrystalline Wax, Polysilicone-15, Vinyl Diméthicone, Camellia Japonica Seed Oil, Polyglycéryl-4 Diisostéarate/Polyhydroxystéarate/Sébacate, Curcuma Longa Root Extract, Extrait De Fleur De Melia Azadirachta, Melia Azadirachta Leaf Extract, Extrait De Corallina Officinalis, Extrait D''écorce De Melia Azadirachta, Ocimum Sanctum Leaf Extract, Moringa Oleifera Seed Oil, Coccinia Indica Fruit Extract, Solanum Melongena Fruit Extract, Poudre D''ambre, Aqua, Extrait De Fleur D''aloe Barbadensis, Simmondsia Chinensis Seed Oil, 1,2-Hexanediol, Extrait D''artemisia Capillaris, Huile De Graine De Camellia Sinensis, Hyaluronic Acid, Panthenol, Butylene Glycol, Propanediol, Extrait De Bambusa Vulgaris, Camellia Sinensis Leaf Extract, Glycerin, Methylpropanediol, Centella Asiatica Extract, Extrait De Morinda Citrifolia, Extrait De Graine De Vigna Radiata, Ethylhexylglycerin', 'Le Matte sun stick : Mugwort+Camelia SPF50 PA++++ Beauty of Joseon est un soin idéal pour ta routine quotidienne de protection solaire, qui ne laisse aucune trace blanche. Avec un indice SPF50 PA++++ élevé, ce stick solaire est parfait pour tous ceux qui préfèrent un format simple et facile à utiliser sans faire de compromis sur la protection. Dis adieu au fini gras et pâteux avec cette formule innovante, qui contient de la poudre de silice pour absorber l''excès de sébum et laisser à ta peau un fini mat et durable. Mais ce n''est pas tout - notre stick solaire contient également des ingrédients puissants tels que des extraits d''armoise, de cica et de thé vert pour nourrir, hydrater et apaiser ta peau. Profite d''une protection solaire idéale et d''un soin efficace avec le Matte Sun Stick de Beauty of Joseon. Parfait pour les retouches sur le pouce ou l''utilisation quotidienne, ce produit laissera ta peau protégée, hydratée et saine. Alors, pourquoi attendre ?', 18, 'g', 'beauty-of-joseon-matte-sun-stick-mugwort-camelia-spf50-pa', 'https://korean-skincare.fr/products/beauty-of-joseon-matte-sun-stick-mugwort-camelia-spf50-pa', 'https://aurore-cdn.b-cdn.net/products/beauty-of-joseon-matte-sun-stick-mugwort-camelia-spf50-pa.webp', 'Lors de la dernière étape de ta routine beauté, applique-le légèrement sur les zones exposées au soleil. Emporte-le avec toi et applique-le fréquemment sur les zones qui ont besoin d''une protection solaire.', 1337, '2026-05-07 17:37:38.422901+00', '2026-06-14 15:14:07.684+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c82-7974-a340-d15fd56a80fb', '__OWNER_ID__', 'Revive Under Eye Patch Ginseng + Retinal', 'Beauty of Joseon', 'eye-cream', 'jar', 'Panax Ginseng Root Water, Aqua, Glycerin, Collagen Water, 1,2-Hexanediol, Chondrus Crispus, Hydroxyacetophenone, Algin, Ceratonia Siliqua Gum, Butylene Glycol, Potassium Chloride, Xanthan Gum, Hydrolyzed Collagen, Glucomannan, Sucrose, Titanium Dioxide, CI 77019, Synthetic Fluorphlogopite, Adenosine, Maltodextrin, Disodium EDTA, Dipotassium Glycyrrhizate, Allantoin, Tin Oxide, Hydrogenated Lecithin, Centella Asiatica Extract, Ficus Carica Fruit Extract, Beta-Glucan, Ceramide NP, Caprylyl Glycol, Bakuchiol, Retinal, Acetyl Hexapeptide-8', 'Les Revive Under Eye Patches (Ginseng + Retinal) Beauty of Joseon sont un soin ciblé pour les yeux conçu pour améliorer visiblement le teint terne, la sécheresse et les premiers signes de vieillissement autour des yeux. Infusés avec de l’extrait de ginseng pour nourrir et revitaliser et du retinal pour soutenir le renouvellement et la fermeté de la peau, ces patchs aident à lisser l’apparence des ridules tout en apportant un contour des yeux rafraîchi et lumineux. Grâce à un ajustement confortable qui épouse la peau et une formule riche en essence, les patchs apportent une hydratation rapide et un soin de l’élasticité, parfaits pour les yeux fatigués, les poches ou pour préparer le contour des yeux avant le maquillage. Adaptés à une utilisation quotidienne ou hebdomadaire, ils laissent le contour des yeux plus lisse, hydraté et reposé. Recommandé pour : Peaux sèches, tous types de peaux.', 60, 'pcs', 'beauty-of-joseon-revive-under-eye-patch-ginseng-retinal', 'https://korean-skincare.fr/products/beauty-of-joseon-revive-under-eye-patch-ginseng-retinal', 'https://aurore-cdn.b-cdn.net/products/beauty-of-joseon-revive-under-eye-patch-ginseng-retinal.webp', 'Après le nettoyage et le tonique applique les patchs sous tes yeux. Laisse poser 10 à 20 minutes. Retire-les et tapote doucement l’excès d’essence. Poursuis avec un contour des yeux ou une crème hydratante.', 1895, '2026-05-07 17:37:38.434439+00', '2026-06-14 15:14:07.685+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c8a-7c6e-91ba-398605d3dfe8', '__OWNER_ID__', 'Perfect Renew 3X Skin Refiner', 'LANEIGE', 'moisturizer', 'jar', 'Aqua, Butylene Glycol, Glycerin, Betaine, 1,2-Hexanediol, Polyméthacrylate de Glycéryle, Ethylhexyl Palmitate, Ppg-13-Décyltétradécéth-24, Propanediol, Hydrogenated Lecithin, Polymère Croisé d''Acrylates/C10-30 Alkyl Acrylate, Tromethamine, Pentylene Glycol, Parfum, Ethylhexylglycerin, Adenosine, Allantoin, Disodium EDTA, Ectoin, Taurate de Méthyl Stéaryle de Sodium, Sodium Hyaluronate, Taurine, Caprylyl Glycol, Dextrin, Extrait de Théobroma Cacao, Bioflavonoïdes, Glycine Soja Oil, Retinol, Tocopherol, BHT, Acetyl Tetrapeptide-2', 'Découvre un soin anti-âge exceptionnel avec le Perfect Renew 3X Skin Refiner LANEIGE, un tonique transformateur pour la première étape de ta routine beauté, conçu pour rajeunir la peau soumise aux agressions extérieures et la préparer aux produits cosmétiques qui suivront. Infusé d''un puissant mélange de taurine et d''ectoïne, ce tonique affineur de peau offre des propriétés texturantes et apaisantes, tandis que son complexe exclusif 3X, composé de rétinol, de peptide et de flavonoïde RE.D, fournit un soin anti-âge complet dès le début de ta routine beauté. Sa formule hautement concentrée garantit un résultat optimal avec une petite quantité de produit, ciblant les rides et autres problèmes cutanés liés au vieillissement, et laissant la peau nourrie et résistante. Sa texture rafraîchissante de type gel, enrichie de hyaluronate de sodium, est instantanément absorbée par la peau, la laissant parfaitement hydratée. Ce soin fonctionnel antirides est une étape essentielle de ta routine beauté, offrant une vitalité juvénile et une recharge d''hydratation à ta peau, lui laissant une sensation de revitalisation et d''hydratation. Recommandé pour : Anti-âge, peaux sèches.', 150, 'ml', 'laneige-perfect-renew-3x-skin-refiner-1', 'https://korean-skincare.fr/products/laneige-perfect-renew-3x-skin-refiner-1', 'https://aurore-cdn.b-cdn.net/products/laneige-perfect-renew-3x-skin-refiner-1.webp', 'Après avoir nettoyé ton visage, tourne le bouchon du flacon vers le bas pour faire apparaître la pompe du tonique. Distribue 1 à 2 pompes de produit dans la paume de ta main. Tapote légèrement ta peau, en évitant le contour des yeux et de la bouche.', 4995, '2026-05-07 17:37:38.442555+00', '2026-06-14 15:14:07.685+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c85-70d9-b9c9-694ec47b2557', '__OWNER_ID__', 'Water Bank Blue Hyaluronic Cleansing Foam', 'LANEIGE', 'cleanser', 'tube', 'Aqua, Glycerin, Myristic Acid, Stearic Acid, PEG-32, Potassium Hydroxide, Palmitic Acid, Lauric Acid, Bétaïne de Cocamidopropyle, Glyceryl Stearate, PEG-100 Stearate, Microcrystalline Cellulose, Parfum, Sodium Chloride, Disodium EDTA, Butylene Glycol, Sodium Benzoate, Extrait de Feuille de Mentha Arvensis, Hydrolyzed Hyaluronic Acid, Polycaprolactone, Titanium Dioxide, Propanediol, 1,2-Hexanediol, Lactic Acid, PEG-75, Polyquaternium-10, Copolymère d''Acide Lactique/Glycolique, Ethylhexylglycerin, Hydroxyde d''Aluminium, Triéthoxycaprylylsilane, Extrait de Fruit de Lycium Chinense, Panthenol, Papaïne, Rubus Idaeus Fruit Extract, Vaccinium Angustifolium Fruit Extract, Extrait de Graine de Coffea Arabica, Extrait de Fruit de Sapindus Mukorossi, Extrait de Fruit de Vaccinium Macrocarpon, Fragaria Chiloensis Fruit Extract, Extrait de Graine de Rubus Chamaemorus, Phenoxyethanol, Undaria Pinnatifida Extract', 'Offre à ta peau le soin luxueux de la Water Bank Blue Hyaluronic Cleansing Foam Laneige, un nettoyant dynamique révolutionnaire. Cette mousse abondante et souple transforme ta routine de nettoyage en une expérience de chouchoutage, en lavant en profondeur les résidus de maquillage et les impuretés qui obstruent les pores. Infusé d''acide hyaluronique bleu de taille microscopique, un ingrédient d''hydratation de pointe exclusif à Laneige, ce nettoyant ne se contente pas de nettoyer, il hydrate aussi, garantissant une peau régénérée et qui ne tiraille jamais. Le processus unique de double fermentation avec le Fucoidan, dérivé d''algues des profondeurs, renforce la puissance de l''acide hyaluronique, et un processus méticuleux d''affinage par microfiltration garantit sa puissance. Cette formule, enrichie de capsules de cellulose et d''enzyme de papaïne, non seulement nettoie mais lisse et adoucit également visiblement ta peau. Le résultat est un teint éclatant et satiné, grâce à la présence d''acide hyaluronique bleu, minuscule mais puissant, qui est absorbé rapidement pour une hydratation profonde et durable. Rafraîchis, détoxifie et exfolie ta peau avec la Water Bank Blue Hyaluronic Cleansing Foam, qui ouvre la voie à un nouveau type de nettoyage du visage. Recommandé pour : Peaux mixtes, peaux normales, peaux sèches.', 150, 'g', 'laneige-water-bank-blue-hyaluronic-cleansing-foam', 'https://korean-skincare.fr/products/laneige-water-bank-blue-hyaluronic-cleansing-foam', 'https://aurore-cdn.b-cdn.net/products/laneige-water-bank-blue-hyaluronic-cleansing-foam.webp', 'En utilisant une petite quantité d''eau, fais mousser et masse délicatement la peau avec le produit, en évitant l''intérieur des yeux. Rince abondamment à l''eau tiède.', 3134, '2026-05-07 17:37:38.436823+00', '2026-06-14 15:14:07.685+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c93-723e-8f3c-1c5dbc0a90f9', '__OWNER_ID__', 'Water Sleeping Mask EX', 'LANEIGE', 'mask', 'pack', 'Aqua, Butylene Glycol, Glycerin, Trehalose, Méthyl Triméthicone, 1,2-Hexanediol, Squalane, Phényl Triméthicone, PCA Diméthicone, Caprylyl Méthicone, Ammonium Acryloyldimethyltaurate/VP Copolymer, Lactobacillus Ferment Lysate, Carbomer, Propanediol, Tromethamine, Copolymère d''Acrylates / d''Alkyl Acrylate C10-30, Glyceryl Caprylate, Ethylhexylglycerin, Disodium EDTA, Raffinose, Béhenate de Stéaryle, Extrait de Malachite, Parfum, Distearate de Polyglycéryl-3 Méthylglucose, Carbamate de Lauryl Inuline, Tranexamic Acid, Tryptophane, Hydroxypropyl Bispalmitamide MEA, Beta-Glucan, Limonene, Extrait d''Acorus Gramineus, Linalool, Tocopherol', 'Restaure ta peau déshydratée pendant la nuit. Ce masque innovant est formulé avec de l''eau minérale hydro ionisée hautement concentrée pour fournir des doses intenses d''hydratation à la peau desséchée et stressée. Son parfum calmant infusé de fleur d''oranger, de rose et de bois de santal détend et réconforte tandis que les extraits d''abricot et d''onagre éclaircissent et purifient la peau fatiguée. Résultat : la peau paraît radieuse et offre une sensation de fraîcheur et de douceur. Réveille-toi avec une peau douce et éclatante.', 70, 'ml', 'laneige-water-sleeping-mask-ex', 'https://korean-skincare.fr/products/laneige-water-sleeping-mask-ex', 'https://aurore-cdn.b-cdn.net/products/laneige-water-sleeping-mask-ex.webp', 'Avant d''aller te coucher, étale délicatement une quantité appropriée du masque sur le bout de ton nez, tes joues, ton front et ton menton. Laisse agir toute la nuit. Rince le matin.', 2595, '2026-05-07 17:37:38.451061+00', '2026-06-14 15:14:07.685+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43f8-7a34-a318-1da73de601d2', '__OWNER_ID__', 'PLC Calming Solution Pad', 'Dr. Ceuracle', 'exfoliant', 'pack', 'Aqua, Butylene Glycol, Glycerin, Dipropylene Glycol, Glycéryl Glucoside, Hydroxyacetophenone, Sulfate d''Aluminium, Caprylyl Glycol, Allantoin, Extrait de Feuille d''Aloe Barbadensis Aloe Vera, C12-14 Alketh-12, Ethylhexylglycerin, Centella Asiatica Extract, Glucose, 1,2-Hexanediol, Dipotassium Glycyrrhizate', 'Les PLC Calming Solution Pads Dr. Ceuracle sont un essentiel apaisant et rafraîchissant pour la peau, conçus pour calmer les irritations, réduire les rougeurs et rétablir l’équilibre cutané. Infusés avec le Phyto Green Complex, ces disques de coton ultra-doux délivrent un mélange concentré d’extraits végétaux riches en antioxydants et en propriétés anti-inflammatoires. Chaque compresse est pré-imprégnée d’une formule douce mais efficace qui hydrate tout en renforçant la barrière naturelle de la peau, idéale pour les peaux sensibles ou stressées. La PLC Calming Solution aide à améliorer la texture et le teint de la peau, laissant le visage plus lisse, uniforme et rafraîchi après chaque utilisation. Parfaites pour un usage quotidien, ces compresses apaisantes peuvent remplacer le tonique, servir de rafraîchissement rapide pour la peau ou même agir comme un masque ciblé pour les zones sujettes aux rougeurs ou à la sensibilité. Testées dermatologiquement et exemptes d’agents irritants, les PLC Calming Solution Pads conviennent à tous les types de peau, y compris les peaux sensibles et à tendance acnéique. Leur design à double texture élimine délicatement les impuretés tout en infusant la peau d’une hydratation apaisante, offrant une étape polyvalente dans toute routine de soins. Que tu cherches à calmer ta peau après une exposition au soleil, à réduire les irritations post-exfoliation, ou simplement à maintenir un teint équilibré, ces compresses offrent des résultats visibles à chaque passage. Recommandé pour : Tous types de peaux, y compris sensibles, sèches, mixtes et à tendance acnéique.', 130, 'pcs', 'dr-ceuracle-plc-calming-solution-pad', 'https://korean-skincare.fr/products/dr-ceuracle-plc-calming-solution-pad', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-plc-calming-solution-pad.webp', 'Après le nettoyage, passe doucement la compresse sur ton visage en évitant le contour des yeux. Utilise le côté lisse pour appliquer l’essence uniformément et le côté texturé pour une exfoliation douce si désiré. Tapote légèrement l’essence restante pour une meilleure absorption. Poursuis avec ton sérum et ta crème habituels.', 2495, '2026-05-07 17:37:40.344586+00', '2026-06-14 15:14:07.685+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c95-715a-aa50-615ef2508112', '__OWNER_ID__', 'Lip Sleeping Mask EX', 'LANEIGE', 'lip-care', 'tube', 'Diisostearyl Malate, Hydrogenated Polyisobutene, Phytostéryl/Isostéaryl/Cétyl/Stéaryl/Behenyl Dimer Dilinoléate, Polymères d’Oléfine C6-14 Hydrogénés, Polyisobutene, Cire Microcristalline/ Cera Microcristallina/ Cire Microcristalline, Butyrospermum Parkii Butter, Synthetic Wax, Copolymère d’Éthylène/Propylène/Styrene, Tétrastéarate de Saccharose Triacétate, CI 77019, Euphorbia Cerifera Cera, Esters de Cire de Candelilla, Beurre de Graines d’Astrocaryum Murumuru, Dioxyde de Titane CI 77891, Parfum, Glyceryl Caprylate, Diisostéarate de Polyglycéryl-2, Copolymère Butylène/Éthylène/Styrene, Cire de Copernicia Cerifera/ Cera de Copernicia Cerifera/ Cire de Carnauba, Méthicone, Triisostéarate de Polyglycéryl-2, Cocos Nucifera Oil, Jaune 6 Lake, Tétrahydroxyhydrocinnamate de Pentaérythrityl Tetra-di-t-butyl, Rouge 6, Ascorbic Acid, Aqua, Glycerin, Propanediol, BHT, Jus de Fruit de Punica Granatum, Jus de Rubus Idaeus, Jus de Vitis Vinifera', 'Le Lip Sleeping Mask EX LANEIGE est un masque pour les lèvres sans rinçage qui apaise et hydrate les lèvres pour les rendre plus souples. Parfois, un baume à lèvres ne suffit pas et quelle que soit la quantité que tu appliques, tes lèvres auront toujours l''air sèches et gercées. C''est là qu''intervient le Lip Sleeping Mask de Laneige, composé du Moisture Wrap qui forme un film protecteur pour emprisonner l''hydratation et les ingrédients actifs, et du Berry Mix Complex riche en antioxydants et en vitamine C pour protéger les lèvres et exfolier en douceur les desquamations. Une couche généreuse de ce masque apaisant au coucher aide à réduire les squames pour que tu puisses te réveiller avec des lèvres rafraîchies, souples et douces au toucher. Recommandé pour : Lèvres sèches et abîmées.', NULL, NULL, 'laneige-lip-sleeping-mask-ex', 'https://korean-skincare.fr/products/laneige-lip-sleeping-mask-ex', 'https://aurore-cdn.b-cdn.net/products/laneige-lip-sleeping-mask-ex.webp', 'Applique une bonne quantité sur tes lèvres à l''aide de la spatule le soir. Le lendemain matin, essuie délicatement tes lèvres avec un mouchoir en papier pour éliminer les cellules mortes.', 1695, '2026-05-07 17:37:38.452995+00', '2026-06-14 15:14:07.686+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c97-7511-bbea-5a5686035e0e', '__OWNER_ID__', 'Radian-C Sun Cream SPF50+ PA++++', 'LANEIGE', 'moisturizer', 'jar', 'Aqua, Butylene Glycol, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Homosalate, Ethylhexyl Salicylate, C12-15 Alkyl Benzoate, Diisopropyl Sébacate, Cetearyl Alcohol, Silica, Glycerin, Phosphate de Cétyl Potassique, Titanium Dioxide, Terephthalylidene Dicamphor Sulfonic Acid, Triméthicone Phényl, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Adipate de Dibutyle, 1,2-Hexanediol, Tromethamine, Panthenol, Limonene, Polyacrylate Crosspolymer-6, Stéarate d''Aluminium, Polyméthacrylate de Méthyle, Polyhydroxystearic Acid, Parfum, Gomme Xanthane, Caprylyl Glycol, Éthyl Ascorbyl Ether, Glyceryl Caprylate, Triméthoxycinnamate de Thymol, Glyceryl Stearate, Alumina, Hydrogenated Lecithin, Disodium EDTA, Stearic Acid, Alcool C12-15, Distearate de Polyglycéryl-3, Palmitic Acid, Linalool, Ceramide NP, Citral, Alcool T-Butyl, Geraniol, Myristic Acid, Lauric Acid', 'La Radian-C Sun Cream Laneige est la solution ultime pour une protection complète contre les UV, le soin des imperfections et le contrôle de la pigmentation. Offrant un SPF50+ PA++++, cette crème solaire légère et rafraîchissante est dotée de l''ingrédient éclaircissant innovant Melasolv™ pour estomper efficacement l''hyperpigmentation et minimiser les taches brunes causées par les rayons UV et les particules en suspension. Sa texture légère comme l''air assure une absorption facile sans aucune sensation collante, ce qui la rend parfaite pour des applications multiples tout au long de la journée. Infusée de céramide et de panthénol, elle maintient la peau hydratée, contribuant ainsi à un teint sain et éclatant. Cette crème solaire protège non seulement des rayons UV, mais agit également comme un écran solaire éclaircissant de haute efficacité, fortifié avec des ingrédients brevetés pour combattre la pigmentation. Découvre les avantages d''une crème solaire qui soigne la santé de ta peau, en maintenant une sensation de fraîcheur et d''hydratation tout en offrant une protection solaire optimale. Recommandé pour : Peaux sensibles, peaux sèches.', 50, 'ml', 'laneige-radian-c-sun-cream-spf50', 'https://korean-skincare.fr/products/laneige-radian-c-sun-cream-spf50', 'https://aurore-cdn.b-cdn.net/products/laneige-radian-c-sun-cream-spf50.webp', 'Applique une quantité adéquate de crème solaire uniformément sur ton visage, partout où une protection contre les UV est nécessaire lors de la dernière étape de ta routine beauté, en évitant le contour des yeux et de la bouche.', 2248, '2026-05-07 17:37:38.455186+00', '2026-06-14 15:14:07.686+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c99-7974-9095-4c78298ea941', '__OWNER_ID__', 'Bouncy & Firm Lip Treatment', 'LANEIGE', 'lip-care', 'tube', 'Polyéthylène Hydrogéné, Hydrogenated Polyisobutene, Copolymère d’Éthylène/Propylène/Styrene, Caprylic/Capric Triglyceride, Tocopheryl Acetate, Squalane, Aqua, Stearyl Alcohol, Extrait de Racine de Lithospermum Erythrorhizon, Cetyl Alcohol, Parfum, Copolymère de Butylène/Éthylène/Styrene, Myristyl Alcohol, Esters Cétyliques d’Huile d’Olive Hydrogénée, Cire de Son de Riz (Oryza Sativa), Hydrogenated Lecithin, Butylene Glycol, Citronellol, Tétrakis(dibutylhydroxhydrocinnamate) de Pentaérythritol, Méthoxypropane-1,3-diol (Menthoxypropanediol), Linalool, 1,2-Hexanediol, Geraniol, Limonene, Cholesterol, CI 77491, Hexyl Cinnamal, Ceramide NP, Propanediol, Palmitic Acid, Stearic Acid, Polypeptide de Glycine de Soja, Sodium Hyaluronate, Ethylhexylglycerin, Disodium EDTA, Collagène Hydrolysé, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hyaluronic Acid, Extrait de Racine de Paeonia Albiflora, Sodium Acetylated Hyaluronate, Extrait de Fleur de Paeonia Albiflora', 'Offre à tes lèvres un aspect rebondi, pulpeux et ferme avec le Bouncy & Firm Lip Treatment LANEIGE ! Cette formule riche, semblable à du miel, est infusée de Peony & Collagen Complex™, de peptides, de céramides et d''acide hyaluronique 5D pour hydrater en profondeur, lisser et augmenter visiblement le volume des lèvres. Le niacinamide et la caféine agissent pour illuminer et revigorer, tandis que les céramides aident à renforcer la barrière des lèvres pour une hydratation longue durée.', 12, 'g', 'laneige-bouncy-firm-lip-treatment', 'https://korean-skincare.fr/products/laneige-bouncy-firm-lip-treatment', 'https://aurore-cdn.b-cdn.net/products/laneige-bouncy-firm-lip-treatment.webp', 'Appliquer directement sur les lèvres au besoin.', 2595, '2026-05-07 17:37:38.457474+00', '2026-06-14 15:14:07.686+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3ca7-7d04-9f87-7f408701c578', '__OWNER_ID__', 'Cream Skin Refiner', 'LANEIGE', 'moisturizer', 'jar', 'Aqua, Butylene Glycol, Glycerin, Limnanthes Alba Seed Oil, 1,2-Hexanediol, Stéarate de Polyglycéryle-10, Citrate de Stéaryle de Glycéryle, Glutamate de Stéaryle de Sodium, Carbamate de Lauryl d''Inuline, Glyceryl Caprylate, Ethylhexylglycerin, Propanediol, Disodium EDTA, Camellia Sinensis Leaf Extract, Tocopherol', 'La Cream Skin Refiner LANEIGE est un tonique fortifiant pour la peau qui hydrate en profondeur et renforce la barrière cutanée. Combinant les fonctions d''un tonique et d''une crème pour favoriser une hydratation durable grâce à la technologie Cream Blending, ce produit est enrichi en eau de feuilles de thé blanc riche en acides aminés pour apaiser et renforcer la barrière cutanée. À lui seul, ce tonique lissant laissera ta peau profondément hydratée, comme si tu avais appliqué une crème ou un soin hydratant. Recommandé pour : Peaux sèches, déshydratées. Peut être utilisé pour : Tous types de peaux.', 170, 'ml', 'laneige-cream-skin-refiner', 'https://korean-skincare.fr/products/laneige-cream-skin-refiner', 'https://aurore-cdn.b-cdn.net/products/laneige-cream-skin-refiner.webp', 'Imbibe plusieurs disques de coton d''une quantité suffisante de produit. Tapote délicatement sur ton visage et ton cou, en insistant sur les zones qui ont besoin d''être hydratées et nourries. Laisse le produit pénétrer complètement dans ta peau (environ deux minutes) et poursuis avec tes soins habituels. Utilise-le quotidiennement pour un teint hydraté et rebondi.', 3095, '2026-05-07 17:37:38.471683+00', '2026-06-14 15:14:07.686+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cb1-72f6-a387-5f950230c6d2', '__OWNER_ID__', 'Energy Mask', 'INNISFREE', 'mask', 'pack', 'Acai Berry: Water, Methylpropanediol, Butylene Glycol, Caprylic/Capric Triglyceride, Cetyl Ethylhexanoate, Butyrospermum Parkii Butter, Methyl Gluceth-20, Cetearyl Olivate, 1,2-Hexanediol, Sorbitan Olivate, Glycereth-26, Carbomer, Arginine, Glyceryl Caprylate, Hydrogenated Polyisobutene, Sphingomonas Ferment Extract, Ethylhexylglycerin, Paeonia Suffruticosa Root Extract, Centella Asiatica Extract, Allantoin, Disodium EDTA, Chamomilla Recutita (Matricaria) Flower Extract, Euterpe Oleracea Fruit Extract, Aloe Barbadensis Leaf Juice, Vanilla Planifolia Fruit Extract, Pyrus Communis Fruit Extract, Prunus Persica Fruit Extract, Rubus Suavissimus Leaf Extract, Prunus Armeniaca Fruit Extract, Pyrus Malus Fruit Extract, Hedera Helix Leaf/Stem Extract Aloe: Water, Butylene Glycol, Dipropylene Glycol, Glycerin, Aloe Barbadensis Leaf Juice, Glyceryl Polymethacrylate, 1,2-Hexanediol, Polyglyceryl-10 Laurate, Carbomer, Arginine, Glyceryl Caprylate, Xanthan Gum, Ethylhexylglycerin, Paeonia Suffruticosa Root Extract, Centella Asiatica Extract, Disodium EDTA, Chamomilla Recutita (Matricaria) Flower Extract, Parfum, Diethylhexyl Sodium Sulfosuccinate, Sodium Hyaluronate Green Tea: Water, Butylene Glycol, Dipropylene Glycol, Glycerin, Glyceryl Polymethacrylate, 1,2-Hexanediol, Polyglyceryl-10 Laurate, Carbomer, Arginine, Glyceryl Caprylate, Xanthan Gum, Ethylhexylglycerin, Camellia Sinensis Leaf Extract, Paeonia Suff Ruticosa Root Extract, Centella Asiatica Extract, Disodium EDTA, Chamomilla Recutita (Matricaria) Flower Extract, Rosa Damascena Flower Water, Pyrus Communis Fruit Extract, Cucumis Melo Seed Extract, Diethylhexyl Sodium Sulfosuccinate, Iris Florentina Root Extract, Sodium Hyaluronate, Vetiveria Zizanoides Root Oil Pomegranate: Water, Butylene Glycol, Dipropylene Glycol, Glycerin, Punica Granatum Fruit Juice, Glyceryl Polymethacrylate, 1,2-Hexanediol, Polyglyceryl-10 Laurate, Carbomer, Arginine, Glyceryl Caprylate, Xanthan Gum, Ethylhexylglycerin, Paeonia Suffruticosa Root Extract, Centella Asiatica Extract, Disodium EDTA, Chamomilla Recutita (Matricaria) Flower Extract, Diethylhexyl Sodium Sulfosuccinate, Vanilla Planifolia Fruit Extract, Pyrus Communis Fruit Extract, Prunus Persica Fruit Extract, Rubus Suavissimus Leaf Extract, Prunus Armeniaca Fruit Extract, Sodium Hyaluronate, Pyrus Malus Fruit Extract, Hedera Helix Leaf/Stem Extract', 'La collection Innisfree Energy Mask offre des masques quotidiens biodégradables en feuilles infusés d''extraits botaniques frais pour offrir rapidement des bienfaits ciblés en matière de soins de la peau. Avec différentes options au choix, chaque masque est conçu pour répondre à des besoins spécifiques, de l''hydratation en profondeur à l''éclaircissement et à l''apaisement. Fabriqués avec des matériaux respectueux de l''environnement et sans ingrédients d''origine animale, ces masques végétaliens et sans cruauté sont parfaits pour donner à votre peau un coup de pouce en matière de nutrition et d''éclat. Que votre peau ait besoin d''un petit coup de pouce ou d''une dose d''hydratation, il existe un masque énergétique pour chaque problème de peau. Recommandé pour : Tous les types de peau.', NULL, NULL, 'innisfree-energy-mask', 'https://korean-skincare.fr/products/innisfree-energy-mask', 'https://aurore-cdn.b-cdn.net/products/innisfree-energy-mask.webp', 'Après le nettoyage, utilise un tonique pour affiner ton grain de peau. Déplie et place le masque sur ton visage, en évitant le contour des yeux et des lèvres. Laisse agir pendant 10 à 20 minutes. Jette le masque et tapote délicatement pour une meilleure absorption.', 295, '2026-05-07 17:37:38.480988+00', '2026-06-14 15:14:07.687+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3c9b-7d1a-bc5d-dc7c1905257b', '__OWNER_ID__', 'Bouncy & Firm Eye Sleeping Mask', 'LANEIGE', 'eye-cream', 'jar', 'Aqua, Glycerin, Sodium Acrylates Crosspolymer-2, Butylene Glycol, Niacinamide, 1,2-Hexanediol, Panthenol, Polyglycérine-3, Polyméthacrylate de Glycéryle, Caffeine, Lactobacillus Ferment Lysate, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Propanediol, Gomme de Xanthane, Dipotassium Glycyrrhizate, Ethylhexylglycerin, Adenosine, Métaphosphate de Sodium, Caprylyl Glycol, Tryptophane, Collagène Hydrolysé, Dextrin, Extrait de Theobroma Cacao, Sodium Hyaluronate, Cyanocobalamin, Extrait de Racine de Paeonia Albiflora, Tocopherol, Hydrolyzed Hyaluronic Acid, Acétyl Tétrapeptide-2, Sodium Hyaluronate Crosspolymer, Hyaluronic Acid, Extrait de Fleur de Paeonia Albiflora, Sodium Acetylated Hyaluronate', 'Le Bouncy & Firm Eye Sleeping Mask Laneige est un traitement de nuit revitalisant conçu pour dégonfler, resserrer et lisser la zone délicate du dessous de l''œil pendant ton sommeil. Infusé de caféine, ce gel léger aide à réduire les poches et à refroidir la température de la peau, tandis que le Peony & Collagen Complex™ - un mélange de collagène, d''extrait de pivoine et de peptides - renforce l''élasticité et l''hydratation pour atténuer les ridules. Sa texture nuage rafraîchissante glisse sans effort et sans coller, ce qui en fait une option apaisante et non irritante pour les peaux sensibles. Recommandé pour : Peaux sèches et sensibles, tous types de peaux.', 20, 'g', 'laneige-bouncy-firm-eye-sleeping-mask', 'https://korean-skincare.fr/products/laneige-bouncy-firm-eye-sleeping-mask', 'https://aurore-cdn.b-cdn.net/products/laneige-bouncy-firm-eye-sleeping-mask.webp', 'Prélève une perle de produit et applique une fine couche sur le contour de tes yeux. Tapote légèrement ta peau pour faciliter l''absorption du produit.', 3195, '2026-05-07 17:37:38.459628+00', '2026-06-14 15:14:07.687+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3ca0-7841-92d3-dac89b34b975', '__OWNER_ID__', 'Water Bank Blue Hyaluronic Intensive Cream', 'LANEIGE', 'moisturizer', 'jar', 'Aqua, Butylene Glycol, Cetearyl Alcohol, Glycerin, Polyoléfine C6-14 Hydrogénée, Succinate de Diéthylhexyle, 1,2-Hexanediol, Glyceryl Stearate SE, Lauroyl Glutamate de Phytostéryl/Behenyl/Octyldodécyle, Trioleine, Glyceryl Stearate, Squalane, Méthyl Triméthicone, Isononanoate d’Isononyle, Myristate de Myristyle, Triglycérides C10-18, Lactobacillus Ferment Lysate, Glucoside de Cétéaryle, Carbomer, Copolymère d’Acrylate d’Hydroxyéthyle/Acryloyldiméthyltaurate de Sodium, Glutamate de Stéaroyle de Sodium, Tromethamine, Niacinamide, Métaphosphate de Sodium, Glyceryl Caprylate, Propanediol, Ethylhexylglycerin, Ceramide NP, Parfum, Caprylyl Glycol, Hydrolyzed Hyaluronic Acid, Sorbitan Isostearate, Sodium Hyaluronate, Dextrin, Asiaticoside, Extrait de Fleur de Carthamus Tinctorius, Acide Madécassique, Acide Asiatique, Extrait de Theobroma Cacao, Tocopherol, Sodium Hyaluronate Crosspolymer, Hyaluronic Acid, Huile Végétale, Extrait Cellulaire de Feuille d’Adenium Obesum, Sodium Acetylated Hyaluronate, Acétyl Tetrapeptide-2, Undaria Pinnatifida Extract', 'Profite d''une hydratation profonde et longue durée avec la Water Bank Blue Hyaluronic Intensive Cream Laneige, une crème hydratante riche et délicate conçue pour réparer et protéger même les peaux les plus sèches. Enrichie en acide hyaluronique bleu, en huile oméga et en peptides, cette formule testée cliniquement apaise les rougeurs, renforce la barrière cutanée et améliore l''élasticité de la peau. La crème hydrate en profondeur les 15 couches de la peau, la gardant hydratée jusqu''à 120 heures tout en améliorant sa résistance et sa texture. Idéale pour les peaux fragilisées par la sécheresse ou les irritations extérieures, cette crème intensive laisse ton teint doux, souple et visiblement revitalisé. Recommandé pour : peaux normales à sèches.', 50, 'ml', 'laneige-water-bank-blue-hyaluronic-intensive-cream', 'https://korean-skincare.fr/products/laneige-water-bank-blue-hyaluronic-intensive-cream', 'https://aurore-cdn.b-cdn.net/products/laneige-water-bank-blue-hyaluronic-intensive-cream.webp', 'Applique et étale délicatement sur ta peau à la fin de ta routine beauté, en évitant le contour des yeux et de la bouche. Tapote légèrement pour faire pénétrer dans ta peau.', 3295, '2026-05-07 17:37:38.464364+00', '2026-06-14 15:14:07.687+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cc4-76b8-81cc-045f59c9c7c9', '__OWNER_ID__', 'Green Tea Amino Hydrating Cleansing Oil', 'INNISFREE', 'cleanser', 'tube', 'Cetyl Ethylhexanoate, Isopropyl Palmitate, Sorbeth-30 Tetraoleate, Caprylic/Capric Triglyceride, Decyl Cocoate, C9-12 Alkane, Diisostearyl Malate, Parfum, Coco-Caprylate/Caprate, Prunus Armeniaca Kernel Oil, Simmondsia Chinensis Seed Oil, Oryza Sativa Bran Oil, Camellia Sinensis Seed Oil, Prunus Amygdalus Dulcis Oil, Aqua, Arginine, Butylene Glycol, Propanediol, 1,2-Hexanediol, Acorus Calamus Root Extract, Ethylhexylglycerin, Sodium Metaphosphate, Camellia Sinensis Leaf Extract', 'L''huile nettoyante hydratante au thé vert Innisfree est un nettoyant léger et rafraîchissant qui fait fondre le maquillage, l''écran solaire et la saleté sans assécher la peau. Composée d''extraits de thé vert et d''acides aminés, elle nettoie en douceur tout en gardant la peau douce et hydratée. Un mélange d''huiles naturelles, notamment de graines de thé vert et de jojoba, aide à éliminer les impuretés et l''excès de sébum, laissant à votre peau une sensation de propreté et de fraîcheur. La formule se rince facilement sans aucun résidu gras, ce qui en fait une excellente première étape dans votre routine de soins de la peau.', 150, 'ml', 'innisfree-green-tea-amino-hydrating-cleansing-oil', 'https://korean-skincare.fr/products/innisfree-green-tea-amino-hydrating-cleansing-oil', 'https://aurore-cdn.b-cdn.net/products/innisfree-green-tea-amino-hydrating-cleansing-oil.webp', 'Appliquer 2 à 3 fois la pompe sur des paumes sèches et propres et masser délicatement le visage sec en effectuant des mouvements circulaires du bout des doigts pour éliminer le maquillage, la crème solaire et les impuretés. Emulsionner en ajoutant un peu d''eau pour obtenir une mousse laiteuse et poursuivre les mouvements circulaires. Rincer complètement à l''eau tiède. Convient pour une utilisation le matin et le soir. Associez-le à votre nettoyant préféré pour un double nettoyage en profondeur.', 1995, '2026-05-07 17:37:38.500337+00', '2026-06-14 15:14:07.689+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cac-755c-aeff-ae6022befe25', '__OWNER_ID__', 'No-Sebum Mineral Powder', 'INNISFREE', 'moisturizer', 'jar', 'Silica, Aluminum Starch Octenyl Succinate, Dimethicone/Vinyl Dimethicone Crosspolymer, Caprylic/Capric Triglyceride, CI 77019, Methicone, Ethylhexylglycerin, Dimethicone, Glyceryl Caprylate, Mineral Salt, Tocopherol', 'La No Sebum Mineral Powder INNISFREE est une poudre libre avec un excellent contrôle du sébum qui laisse un fini lisse et sans brillance sur la peau. Elle est formulée avec des minéraux naturels de Jeju et de la menthe pour contrôler les niveaux d''huile et d''hydratation et pour favoriser un maquillage lisse et homogène. Remplace ton papier anti-sébum ou tes papiers buvards par cette poudre et garde ta peau douce et mate toute la journée. Recommandé pour : Peaux mixtes, peaux grasses. Peut être utilisé pour : Tous types de peaux.', 5, 'g', 'innisfree-no-sebum-mineral-powder', 'https://korean-skincare.fr/products/innisfree-no-sebum-mineral-powder', 'https://aurore-cdn.b-cdn.net/products/innisfree-no-sebum-mineral-powder.webp', 'Après avoir appliqué ton maquillage ou ton soin, tapote ou diffuse délicatement la poudre sur les zones de ton visage qui ont tendance à être grasses ou à briller, en te concentrant sur la zone T. Estompe la poudre uniformément et légèrement sur ta peau. Utilise-la au besoin tout au long de la journée pour contrôler la brillance et obtenir un fini mat.', 950, '2026-05-07 17:37:38.476179+00', '2026-06-14 15:14:07.687+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3ca3-7021-9169-6a996d04d964', '__OWNER_ID__', 'Water Bank Blue Hyaluronic Moisture Cream', 'LANEIGE', 'moisturizer', 'jar', 'Aqua, Butylene Glycol, Glycerin, Squalane, Sucrose Polystearate, Pentaerythrityl Tetraethylhexanoate, Methyl Trimethicone, Dibutyl Adipate, 1,2-Hexanediol, Glyceryl Stearate, Polyglyceryl-3 Methylglucose Distearate, Bis-Hydroxyethoxypropyl Dimethicone, Stearyl Dimethicone, Triglycéride Caprylique/Caprique/Myristique/Stéarique, Stearic Acid, Palmitic Acid, Hydrogenated Polyisobutene, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Cetyl Alcohol, Propanediol, Octadecene, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Parfum, Gomme Xanthane, Glyceryl Caprylate, Dextrin, Tromethamine, Ethylhexylglycerin, Disodium EDTA, Sorbitan Isostearate, Allantoin, Hydrolyzed Hyaluronic Acid, Beta-Glucan, Ceramide NP, Myristic Acid, Arachidic Acid, Lactobacillus Ferment Lysate, Tocophérol Vitamine E, Undaria Pinnatifida Extract', 'Profite d''une hydratation intense et longue durée avec la Water Bank Blue Hyaluronic Moisture Cream Laneige, un soin révolutionnaire à base d''acide hyaluronique bleu micro-granulé qui répare la peau en profondeur et aide à garder son hydratation. Cette crème ne se contente pas d''hydrater la surface de la peau, elle pénètre plus profondément dans la barrière cutanée pour reconstituer l''hydratation perdue et renforcer la résilience de la peau de l''intérieur. Sa texture ultra-légère et soyeuse fond sur la peau pour un fini rafraîchissant et non gras, laissant ton teint doux, lisse et éclatant de santé. Parfaite pour les peaux sèches, stressées ou qui ont besoin d''une nutrition en profondeur. Enrichie en algues fermentées des profondeurs marines et en squalane, qui renforcent la barrière cutanée, cette crème agit en harmonie avec ta peau pour retenir l''hydratation tout en apaisant les sensibilités et en équilibrant les niveaux d''hydratation et de sébum. Cliniquement prouvée pour assurer 100 heures d''hydratation continue, cette crème est ton alliée quotidienne contre la sécheresse, les tiraillements et les agressions environnementales. Que tu sois confrontée à des conditions météorologiques difficiles, à la fatigue due aux écrans ou à la pollution quotidienne, la Water Bank Blue Hyaluronic Moisture Cream protège et régénère ta peau pour un teint visiblement plus rebondi, plus éclatant et plus sain chaque jour. Recommandé pour : Peaux sèches, sensibles et déshydratées.', 50, 'ml', 'laneige-water-bank-blue-hyaluronic-moisture-cream', 'https://korean-skincare.fr/products/laneige-water-bank-blue-hyaluronic-moisture-cream', 'https://aurore-cdn.b-cdn.net/products/laneige-water-bank-blue-hyaluronic-moisture-cream.webp', 'Nettoie ton visage et applique un tonique comme d''habitude. Applique ton sérum ou ton essence. Prélève une petite quantité de crème et applique-la délicatement sur ton visage et ton cou. Masse en mouvements circulaires ascendants jusqu''à absorption complète. Utilise matin et soir comme dernière étape de ta routine de soins de la peau. Conseil : Pour un boost d''hydratation supplémentaire, applique une couche épaisse avant de te coucher comme masque hydratant de nuit ; tu te réveilleras avec une peau repulpée, éclatante et rafraîchie.', 3495, '2026-05-07 17:37:38.46682+00', '2026-06-14 15:14:07.687+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3ca5-77f1-aa16-4fc2b77df48d', '__OWNER_ID__', 'Lip Glowy Balm', 'LANEIGE', 'lip-care', 'tube', 'Berry: Hydrogenated Polyisobutene, Phytosteryl/Isostearyl/Cetyl/ Stearyl/Behenyl Dimer Dilinoleate, Hydrogenated Poly, Diisostearyl Malate, Polyisobutene, Phytosteryl Isostearyl Dimer Dilinoleate, Microcrystalline Wax /Cera Microcristallina / Cire Microcristalline, Butyrospermum Parkii Butter, Sucrose Tetrastearate Triacetate, Synthetic Wax, Ethylene/ Propylene/Styrene Copolymer, CI 77019, Astrocaryum Murumuru Seed Butter, Euphorbia Cerifera Wax / Candelilla Cera Hydrocarbons / Cire Decandelilla, Butylene/Ethylene/ Styrene Copolymer, Parfum, Candelilla Wax Esters, Dehydroacetic Acid, Dimethicone, Methicone, Copernicia Cerifera Wax / Copernicia Cerifera Cera / Cire De Carnauba, Polyglyceryl-2 Triisostearate, Red 7 Lake, Red 6, Aqua, Propanediol, BHT, Lyciumchinense Fruit Extract, Rubus Idaeus Fruit Extract, Vaccinium Angustifolium Fruit Extract, Coffea Arabica Seed Extract, Sapindus Mukorossi Fruit Extract, Vaccinium Macrocarpon Fruit Extract, Fragaria Chiloensis Fruit Extract, Rubus Chamaemorus Seed Extract, Phenoxyethanol Gummy Bear: Hydrogenated Polyisobutene, Phytosteryl/Isostearyl/Cetyl/Stearyl/Behenyl Dimer Dilinoleate, Hydrogenated Poly, Diisostearyl Malate, Polyisobutene, Phytosteryl Isostearyl Dimer Dilinoleate, Microcrystalline Wax / Cera Microcristallina / Cire Microcristalline, Butyrospermum Parkii Butter, Sucrose Tetrastearate Triacetate, Ethylene/Propylene/Styrene Copolymer, Synthetic Wax, CI 77019, Euphorbia Cerifera Wax / Candelilla Cera Hydrocarbons / Cire De Candelilla, Astrocaryum Murumuru Seed Butter, Parfum, Candelilla Wax Esters, Titanium Dioxide, Polyglyceryl-2 Diisostearate, Dimethicone, Dehydroacetic Acid, Butylene/Ethylene/Styrene Copolymer, Methicone, Copernicia Cerifera Wax / Copernicia Cerifera Cera / Cire De Carnauba, Polyglyceryl-2 Triisostearate, Red 7, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Blue 1 Lake, Polyhydroxystearic Acid, Bht Mango: Hydrogenated Polyisobutene, Phytosteryl/Isostearyl/Cetyl/Stearyl/Behenyl Dimer Dilinoleate, Diisostearyl Malate, Hydrogenated Poly, Polyisobutene, Phytosteryl Isostearyl Dimer Dilinoleate, Microcrystalline Wax / Cera Microcristallina / Cire Microcristalline, Butyrospermum Parkii Butter, Sucrose Tetrastearate Triacetate, Ethylene/Propylene/Styrene Copolymer, CI 77019, Euphorbia Cerifera Wax / Euphorbia Cerifera Cera / Cire De Candelilla, Astrocaryum Murumuru Seed Butter, Synthetic Wax, Parfum, Candelilla Wax Esters, Dehydroacetic Acid, Butylene/Ethylene/Styrene Copolymer, Methicone, Titanium Dioxide, Polyglyceryl-2 Triisostearate, Copernicia Cerifera Wax / Copernicia Cerifera Cera / Cire De Carnauba, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Red 7 Lake, Tocopheroln Sweet Candy: Hydrogenated Polyisobutene, Phytosteryl/Isostearyl/Cetyl/Stearyl/Behenyl Dimer Dilinoleate, Diisostearyl Malate, Polyisobutene, Hydrogenated Poly, Phytosteryl Isostearyl Dimer Dilinoleate, Microcrystalline Wax / Cera Microcristallina / Cire Microcristalline, Butyrospermum Parkii Butter, Sucrose Tetrastearate Triacetate, Ethylene/Propylene/Styrene Copolymer, CI 77019, Euphorbia Cerifera Wax / Euphorbia Cerifera Cera / Cire De Candelilla, Astrocaryum Murumuru Seed Butter, Synthetic Wax, Parfum, Candelilla Wax Esters, Polyglyceryl-2 Triisostearate, Dehydroacetic Acid, Butylene/Ethylene/Styrene Copolymer, Silica, Methicone, Titanium Dioxide, Copernicia Cerifera Wax / Copernicia Cerifera Cera / Cire De Carnauba, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, CI 42090, Red 7 Lake, Tocopherol', 'Gardez vos lèvres douces, hydratées et brillantes toute la journée avec le baume à lèvres Laneige Lip Glowy Balm, le compagnon idéal du Lip Sleeping Mask. Infusée de beurre de karité et de beurre de graines de Murumuru, cette formule légère mais riche en hydratation emprisonne l''hydratation et prévient le dessèchement tout en ajoutant une teinte subtile et une brillance pulpeuse. Son tube de poche permet de l''appliquer facilement à tout moment et n''importe où, pour une explosion rafraîchissante d''hydratation et un aspect naturellement pulpeux. Disponible dans de délicieux parfums tels que Berry, Gummy Bear, Mango et Sweet Candy, ce baume offre un fini soyeux et non collant qui permet à vos lèvres de rester nourries et lisses tout au long de la journée.', NULL, NULL, 'lip-glowy-balm', 'https://korean-skincare.fr/products/lip-glowy-balm', 'https://aurore-cdn.b-cdn.net/products/lip-glowy-balm.webp', 'Appliquer directement sur les lèvres selon les besoins. Utiliser seul ou avant le rouge à lèvres pour l''apprêter/après le rouge à lèvres pour le faire briller.', 1995, '2026-05-07 17:37:38.469314+00', '2026-06-14 15:14:07.688+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3caa-71c0-adbf-c3c09d3cce93', '__OWNER_ID__', 'Neo Cushion Glow', 'LANEIGE', 'moisturizer', 'jar', 'Aqua, Cyclopentasiloxane, Titanium Dioxide, Phényl Triméthicone, Homosalate, Glycerin, Ethylhexyl Methoxycinnamate, Titanium Dioxide, PEG-10 Diméthicone, Cyclohexasiloxane, Nitrure de Bore, Trimethylsiloxysilicate, Niacinamide, Lauryl PEG-10 Tris(Triméthylsiloxy)silylethyl Diméthicone, Propanediol, Polyméthacrylate, 1,2-Hexanediol, Copolymère d''Acrylates/Diméthicone, Disteardimonium Hectorite, Oxyde de Fer Jaune, Sodium Chloride, Alumina, Oxychlorure de Bismuth, Stéarate de Glycéryle Citrate, Polysorbate 80, Glutamate de Stéaryl Disodique, Parfum, Hydroxyde d''Aluminium, Diméthicone/PEG-10/15 Copolymère, Caprylyl Glycol, Oxyde de Fer Rouge, Hydrogenated Lecithin, Hydroxystéarate d''éthylhexyle, Siméthicone, Glyceryl Caprylate, Ethylhexylglycerin, Oxyde de Fer Noir, Disodium EDTA, Adenosine, Triéthoxycaprylylsilane, Citronellol, Geraniol, Limonene, Dipropylene Glycol, BHT, Hydroxycitronellal, Triméthoxycinnamate de Thymol, Sodium Citrate, Tocopherol, Sodium Benzoate, Lactic Acid, Potassium Sorbate, Poudre de Diamant, Gomme Xanthane', 'Le Neo Cushion Glow Laneige est un fond de teint cushion flatteur qui permet de créer une peau lumineuse et éclatante. Ce fond de teint se fixe sur la peau pour une luminosité éclatante pendant 24 heures, et est même efficace sur les teints ternes, grâce à l''utilisation de véritables diamants dans sa formule.', NULL, NULL, 'laneige-neo-cushion-glow', 'https://korean-skincare.fr/products/laneige-neo-cushion-glow', 'https://aurore-cdn.b-cdn.net/products/laneige-neo-cushion-glow.webp', 'Applique une quantité appropriée de produit sur une houppette et tapote légèrement sur ton visage. Renouvelle l''application si nécessaire. Ferme bien le couvercle après utilisation pour éviter l''évaporation et la contamination du produit.', 2295, '2026-05-07 17:37:38.47394+00', '2026-06-14 15:14:07.688+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cc0-7258-a9d7-9a0f961775da', '__OWNER_ID__', 'Jeju Orchid Enriched Cream', 'INNISFREE', 'moisturizer', 'jar', 'Aqua, Cyclopentasiloxane, Propanediol, Glycerin, Cyclohexasiloxane, PEG-10 Diméthicone, Squalane, Niacinamide, Triméthicone de Diphenylsiloxy Phenyl, Disteardimonium Hectorite, Sodium Chloride, 1,2-Hexanediol, Lauryl PEG-9 Polydiméthylsiloxyéthyl Diméthicone, Dimethicone, Polysilicone-11, Parfum, Polymère Croisé de Diméthicone/Vinyl Diméthicone, Ethylhexylglycerin, Adenosine, Kaolin, Disodium EDTA, Hyaluronic Acid, Betaine, Glucose, Extrait d''Orchidée, Tocopherol, Polypeptide d''Arginine/Lysine', 'Rafraîchis et renforce ta peau avec la Jeju Orchid Enriched Cream Innisfree, une crème riche et nourrissante qui raffermit la peau, réduit les rides et illumine le teint. Cette crème est formulée avec des orchidées de Jeju, reconnues pour leur richesse en antioxydants, et laisse la peau éclatante et lumineuse. Ce soin tout-en-un pour l’élasticité, l’éclat et la nutrition convient à tous les types de peau. Infusée d’antioxydants puissants issus d’orchidées cultivées sur l’île de Jeju, la Jeju Orchid Enriched Cream procure un soin anti-âge intensif. Une utilisation régulière aide à améliorer la fermeté et l’élasticité de la peau tout en réduisant visiblement l’apparence des ridules et des rides. Elle affine également la texture de la peau et augmente l’éclat pour un teint plus lumineux et jeune. Formulée sans parabènes, ingrédients d’origine animale, huile minérale, colorants synthétiques ni imidazolidinyl urée, cette formule est douce et efficace. Recommandé pour : Tous types de peaux.', 50, 'ml', 'innisfree-jeju-orchid-enriched-cream', 'https://korean-skincare.fr/products/innisfree-jeju-orchid-enriched-cream', 'https://aurore-cdn.b-cdn.net/products/innisfree-jeju-orchid-enriched-cream.webp', 'Applique lors de la dernière étape de ta routine beauté. Étale une quantité généreuse de crème sur ton visage, ton cou et la partie supérieure de ta poitrine. Masse délicatement ta peau pour une meilleure absorption.', 2995, '2026-05-07 17:37:38.496023+00', '2026-06-14 15:14:07.69+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cb3-7a35-9110-31bc4cbc8882', '__OWNER_ID__', 'Green Tea Amino Hydrating Cleansing Foam', 'INNISFREE', 'cleanser', 'tube', 'Aqua, Glycerin, Myristic Acid, Lauric Acid, Potassium Hydroxide, Stearic Acid, Glyceryl Stearate, Glycol Distearate, Palmitic Acid, Lauryl Hydroxysultaine, Polyquaternium-22, Lauryl Glucoside, Propanediol, Parfum, Potassium Cocoyl Glycinate, 1,2-Hexanediol, Hydrolyzed Cornstarch, Pinus Densiflora Leaf Extract, Disodium EDTA, Butylene Glycol, Arginine, Aspartic Acid, Glutamic Acid, Ethylhexylglycerin, Camellia Sinensis Leaf Extract, Acrylates/Stearyl Methacrylate Copolymer, Tremella Fuciformis Extract, Disodium EDTA, Hyaluronic Acid, Xanthan Gum, Ceramide NP, Acorus Calamus Root Extract', 'La mousse nettoyante hydratante au thé vert Innisfree est un nettoyant pour le visage hydratant qui élimine en douceur la saleté et les impuretés sans laisser une sensation de peau sèche ou dénudée. Infusée de thé vert de Jeju et d''un triple complexe d''acides aminés, elle nettoie tout en gardant la peau douce et hydratée. La mousse crémeuse et riche mousse magnifiquement, laissant votre peau rafraîchie, équilibrée et lisse. Parfait pour tous les types de peau, ce nettoyant végétalien et sans cruauté est un moyen doux mais efficace de commencer ou de terminer la journée avec un éclat propre et hydraté. Recommandé pour : Tous les types de peau.', 150, 'g', 'innisfree-green-tea-amino-hydrating-cleansing-foam', 'https://korean-skincare.fr/products/innisfree-green-tea-amino-hydrating-cleansing-foam', 'https://aurore-cdn.b-cdn.net/products/innisfree-green-tea-amino-hydrating-cleansing-foam.webp', 'Prélève une quantité suffisante et fais mousser. Masse délicatement ton visage et rince soigneusement à l''eau tiède.', 1695, '2026-05-07 17:37:38.483518+00', '2026-06-14 15:14:07.688+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cb5-7e08-b4a7-c31c9a528c28', '__OWNER_ID__', 'Green Tea Seed Hyaluronic Serum', 'INNISFREE', 'serum', 'dropper', 'Aqua, Propanediol, Glycerin, 1,2-Hexanediol, Niacinamide, Betaine, Saccharide Isomerate, Camellia Sinensis Seed Oil, Xylitol, Cetearyl Olivate, Hydrogenated Lecithin, Butylene Glycol, Sorbitan Olivate, Lactobacillus Ferment Lysate, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Squalane, Panthenol, Allantoin, Hydroxyethylacrylate/Sodium Acryloyldimethyl Taurate Copolymer, Tromethamine, Triethyl Citrate, Ethylhexylglycerin, Ceratonia Siliqua Gum, Disodium EDTA, Limonene, Camellia Sinensis Leaf Extract, Dipotassium Glycyrrhizate, Citrus Limon Peel Oil, Sodium Hyaluronate, Hyaluronic Acid, Maltodextrin, Theobroma Cacao Extract, 3-O-Ethyl Ascorbic Acid, Sodium Citrate, Citric Acid, Sorbitan Isostearate, Ilex Paraguariensis Leaf Extract, Glyceryl Oleate, Citral, Elettaria Cardamomum Seed Oil, Tocopherol, Lecithin, Sucrose, Lauryl Glucoside, Polyglyceryl-6 Laurate, Myristyl Glucoside, Mentha Viridis Leaf Oil, Cymbopogon Nardus Oil, Ferula Galbaniflua Resin Oil, Xanthan Gum, Lactic Acid, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Sodium Acetylated Hyaluronate', 'Le sérum hyaluronique aux graines de thé vert Innisfree est rempli de thé vert hydratant et d''acide hyaluronique qui rehausse l''hydratation pour garder votre peau douce, rebondie et éclatante. Sa formule légère à absorption rapide aide à retenir l''humidité pour une hydratation durable tout en renforçant la barrière cutanée. Composée du complexe spécial Thé vert+HA™ d''Innisfree, elle nourrit en profondeur et équilibre votre peau, la laissant lisse et rafraîchie toute la journée. Sans parfum ni alcool, ce sérum doux et végétalien est parfait pour obtenir une apparence saine et rosée. Recommandé pour : Tous les types de peau.', 80, 'ml', 'innisfree-green-tea-seed-hyaluronic-serum', 'https://korean-skincare.fr/products/innisfree-green-tea-seed-hyaluronic-serum', 'https://aurore-cdn.b-cdn.net/products/innisfree-green-tea-seed-hyaluronic-serum.webp', 'Applique une quantité suffisante sur ton visage et ton cou parfaitement nettoyés. Masse délicatement pour une meilleure absorption.', 2995, '2026-05-07 17:37:38.485705+00', '2026-06-14 15:14:07.688+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cae-7b2b-8700-44d8206be2cf', '__OWNER_ID__', 'No-Sebum Mineral Pact', 'INNISFREE', 'moisturizer', 'jar', 'CI 77019, Silica, Octyldodecyl Stearoyl Stearate, Squalane, Silica Dimethicone Silylate, Magnesium Myristate, Aluminum Starch Octenylsuccinate, Sorbitan Isostearate, Methicone, Ethylhexylglycerin, Glyceryl Caprylate, Mineral Salts, Aqua, Butylene Glycol, Mentha Arvensis Leaf Extract, Tocopherol, 1,2-Hexanediol', 'Le Pacte minéral sans sébum Innisfree est une poudre de finition légère et facile à utiliser qui contrôle l''excès de sébum pour un look frais et sans brillance. Parfaite pour les retouches quotidiennes, elle aide à fixer le maquillage, à estomper les imperfections et à garder la peau lisse sans qu''elle ne colle. Idéale pour les peaux grasses ou comme indispensable en été pour les peaux sèches, cette poudre compacte absorbe l''excès de sébum tout en conservant un fini naturel et propre. Grâce à ses ingrédients minéraux et à sa formule douce et non desséchante, elle maintient votre maquillage en place tout en donnant à votre peau une apparence équilibrée et rafraîchie tout au long de la journée.', 8, 'g', 'innisfree-no-sebum-mineral-pact', 'https://korean-skincare.fr/products/innisfree-no-sebum-mineral-pact', 'https://aurore-cdn.b-cdn.net/products/innisfree-no-sebum-mineral-pact.webp', NULL, 1495, '2026-05-07 17:37:38.478506+00', '2026-06-14 15:14:07.689+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43e6-7ef4-ab52-6de79ad8e312', '__OWNER_ID__', 'Pure VC Mellight A-tinol Cream', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Active Cream : Eau, Squalane, Éther Dicaprylyl, Propanediol, Methyl Triméthicone, Butyrospermum Parkii Butter, Cetyl Ethylhexanoate, Vinyl Diméthicone, Phosphate De Cétyl Potassique, Glycereth-26, Niacinamide, Polyglycérine-3, Caprylic/Capric Triglyceride, Glyceryl Stearate SE, Cetyl Alcohol, 3-O-Ethyl Ascorbic Acid, Glycérides De Palme Hydrogénés, 1,2-Hexanediol, Glycerin, Behenyl Alcohol, Huile D’Elaeis Guineensis, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Arginine, Butylene Glycol, Huile De Colza Hydrogénée, Hydroxyacetophenone, Dioscorea Japonica Root Extract, Gomme Xanthane, Sodium Hyaluronate, Ethylhexylglycerin, Amidon De Maïs Hydrolysé, Retinol, Alcohol Denat, Adenosine, Beta-Glucan, HDI/Triméthylol Hexyllactone Crosspolymer, Tocopherol, Sucrose, Hydrogenated Lecithin, Alcool Polyvinylique, Ascorbic Acid, Lavandula Angustifolia Oil, Methylpropanediol, Centella Asiatica Extract, Ficus Carica Fruit Extract, Huile De Fruit De Citrus Aurantium Bergamia, Rosmarinus Officinalis Leaf Oil, Caprylyl Glycol, Phellodendron Amurense Bark Extract, Ceramide NP, Glutathione, Hippophae Rhamnoides Fruit Extract, Chamomilla Recutita Flower Oil, Extrait D’Acmella Oleracea, Anthemis Nobilis Flower Oil, Phénylpropanol, Hydroxydécyl Ubquinone, PVP, Fullerenes, Linalool, Limonène Barrier Cream : Eau, Tripropylène Glycol, 1,2-Hexanediol, Niacinamide, Glycerin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Arginine, Copolymère Ammonium Acryloyldiméthyltaurate/VP, Butylene Glycol, Coptis Japonica Root Extract, Octyldodéceth-16, Hydroxyacetophenone, Phytostérols, Panthenol, Ethylhexylglycerin, Alcool Arachidyl, Adenosine, Stearic Acid, Hydrogenated Lecithin, Behenyl Alcohol, Glucoside D’Arachidyl, Bakuchiol, Lavandula Angustifolia Oil, Centella Asiatica Extract, Extrait De Ficus Carica, Huile De Fruit De Citrus Aurantium Bergamia, Cetyl Alcohol, Rosmarinus Officinalis Leaf Oil, Ceramide NP, Anthemis Nobilis Flower Oil, Collagène, Cyanocobalamin, Extrait De Collagène, Glycosaminoglycanes, Élastine Hydrolysée, Tocopherol, Ac', 'La Pure VC Mellight A-Tinol Cream Dr. Ceuracle est une crème riche, antioxydante et enrichie en vitamines, conçue pour illuminer le teint, lutter contre les signes de l’âge et favoriser un teint plus uniforme et éclatant. Elle associe de la vitamine C stabilisée (poudre de vitamine C + dérivé), des actifs de type rétinoïde et des ingrédients soutenant la barrière cutanée pour cibler les taches, le teint terne, les ridules et la texture irrégulière de la peau. Grâce à son mélange d’hydratation, de nutrition et d’actifs, cette crème convient à celles et ceux qui recherchent éclat, anti-âge, soutien de la barrière cutanée et santé globale de la peau en une seule étape. Elle est particulièrement bénéfique pour les peaux ternes, à teint irrégulier, présentant de premiers signes de rides, de sécheresse ou une barrière compromise. Sa formule offre à la fois protection antioxydante et effets de renouvellement cutané, un équilibre parfait pour celles qui souhaitent plus qu’une simple hydratation sans passer directement à des rétinoïdes puissants ou à des traitements éclaircissants agressifs. Recommandé pour : Tous types de peaux.', 70, 'g', 'dr-ceuracle-pure-vc-mellight-a-tinol-cream', 'https://korean-skincare.fr/products/dr-ceuracle-pure-vc-mellight-a-tinol-cream', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-pure-vc-mellight-a-tinol-cream.webp', 'En dernière étape de ta routine, utilise la spatule fournie pour prélever la Formule 1 et la Formule 2 dans un ratio 1:2. Mélange-les puis applique doucement sur l’ensemble de ton visage. Le matin, termine par une protection solaire (particulièrement important lors de l’utilisation d’ingrédients de type vitamine C ou rétinoïde). Pour les peaux sensibles, commence par 2 à 3 utilisations par semaine et observe la tolérance avant de passer à un usage quotidien le soir.', 2295, '2026-05-07 17:37:40.326878+00', '2026-06-14 15:14:07.689+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cb8-742c-aeca-6d5f0faadf51', '__OWNER_ID__', 'Green Tea Hyaluronic Glow Eye & Face Ball', 'INNISFREE', 'eye-cream', 'jar', 'Aqua, Butylene Glycol, Glycerin, Propanediol, Niacinamide, Dimethicone, Phenyl Trimethicone, Caffeine, 1,2-Hexanediol, Squalane, Polysorbate 20, Polysilicone -11, Carbomer, Pca Dimethicone, Polyacrylate Crosspolymer-6, Tromethamine, Boron Nitride, Sodium Polyacryloyldimethyl Taurate, Titanium Dioxide CI 77891, Dimethiconol, Synthetic Fluorphlogopite, Glyceryl Caprylate, Sodium Metaphosphate, Ethylhexylglycerin, Adenosine, Camellia Sinensis Leaf Extract, Arginine, Cyclodextrin, Hydroxypropyl Cyclodextrin, Maltodextrin, Citric Acid, Sodium Hyaluronate, Tin Oxide, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hyaluronic Acid, Tocopherol, Sodium Acetylated Hyaluronate', 'La Boule pour les yeux et le visage Innisfree au thé vert et à l''acide hyaluronique est un sérum rafraîchissant et léger conçu pour hydrater, éclaircir et revitaliser la peau fatiguée. Infusé d''extrait de thé vert, d''acide hyaluronique et de caféine, il hydrate en profondeur tout en aidant à réduire les poches et l''aspect terne du contour des yeux. La formule contient de fines particules scintillantes pour un éclat subtil, laissant votre peau fraîche et radieuse. Doté d''un applicateur roll-on facile à utiliser, ce sérum masse délicatement la peau, améliorant l''absorption et apaisant les zones fatiguées.', 10, 'ml', 'innisfree-green-tea-hyaluronic-glow-eye-face-ball', 'https://korean-skincare.fr/products/innisfree-green-tea-hyaluronic-glow-eye-face-ball', 'https://aurore-cdn.b-cdn.net/products/innisfree-green-tea-hyaluronic-glow-eye-face-ball.webp', 'Prends une quantité appropriée de produit et applique-le sur le contour de tes yeux, Ensuite, tu peux tapoter légèrement pour améliorer l''absorption du produit.', 2395, '2026-05-07 17:37:38.488125+00', '2026-06-14 15:14:07.689+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cc6-7894-9117-b03530f26cd9', '__OWNER_ID__', 'Canola Honey Lip Balm', 'INNISFREE', 'lip-care', 'tube', 'Original: Petrolatum, Polyglyceryl-2 Triisostearate, Diisostearyl Malate, Paraffinum Liquidum, Jojoba Esters, Hydrogenated Polyisobutene, Polyethylene, Meadowfoam Deltá-Lactone, Phytosteryl Hydroxystearate, Hydrogenated Coco-Glycerides, Euphorbia Cerifera Wax/Candelilla Cera Hydrocarbons/Cire De Candelilla, Microcrystalline Wax/Cera Microcristallina / Cire Microcristalline, Mangifera Indica Seed Butter, Ceresin, Prunus Amygdalus Dulcis Oil, Trihydroxystearin, Phenoxyethanol, Caprylyl Glycol, Parfum, Glyceryl Caprylate, Tocopheryl Acetate, Yellow 5 Lake CI 19140, Yellow 6 Lake CI 15985, Tocopherol, Tbhq, Brassica Napus Seed Oil, Aqua, Butylene Glycol, Honey Extract, Ethylhexylglycerin Intensive Moisture: Petrolatum, Polyglyceryl-2 Triisostearate, Diisostearyl Malate, Mineral Oil/Paraffinum Liquidum/Huile Minerale, Jojoba Esters, Hydrogenated Polyisobutene, Polyethylene, Meadowfoam Delta-Lactone, Cholesteryl Hydroxystearate, Hydrogenated Coco-Glycerides, Euphorbia Cerifera Wax/Candelilla Cera Hydrocarbons/Cire De Candelilla, Microcrystalline Wax/Cera Microcristallina/Cire Microcristalline, Mangifera Indica Seed Butter, Ceresin, Prunus Amygdalus Dulcis Oil, Trihydroxystearin, Phenoxyethanol, Caprylyl Glycol, Tocopheryl Acetate, Glyceryl Caprylate, Simmondsia Chinensis Seed Oil, Camellia Japonica Seed Oil, Parfum, Tocopherol, Tbhq, Cymbopogon Schoenanthus Oil, Aqua, Butylene Glycol, Honey Extract, Ethylhexylglycerin', 'Le Canola Honey Lip Balm Innisfree est à la fois un baume brillant pour les lèvres et un gloss qui hydrate les lèvres sèches et gercées pour créer une barrière d''hydratation lisse. Il contient de l''extrait de miel de canola de Jeju, de l''huile de graines de canola et du beurre de graines de mangue qui hydratent et améliorent la souplesse des lèvres. Ce baume à lèvres au miel de canola a un délicieux parfum de miel et est riche en flavonoïdes, en protéines et en nutriments pour donner aux lèvres une fermeté et une souplesse exceptionnelles.', NULL, NULL, 'innisfree-canola-honey-lip-balm', 'https://korean-skincare.fr/products/innisfree-canola-honey-lip-balm', 'https://aurore-cdn.b-cdn.net/products/innisfree-canola-honey-lip-balm.webp', 'Applique généreusement sur tes lèvres au besoin.', 1395, '2026-05-07 17:37:38.502444+00', '2026-06-14 15:14:07.69+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cca-7c30-bc37-8dc09daff58f', '__OWNER_ID__', 'Green Tea Hyaluronic Skin', 'INNISFREE', 'moisturizer', 'jar', 'Aqua, Propanediol, Glycerin, Betaine, Polyglycerin-3, 1,2-Hexanediol, Lactobacillus Ferment Lysate, Gluconolactone, Sodium Metaphosphate, Butylene Glycol, Ethylhexylglycerin, Xanthan Gum, Tromethamine, Camellia Sinensis Leaf Extract, Panthenol, Beta-Glucan, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hyaluronic Acid, Tocopherol, Sodium Acetylated Hyaluronate', 'Le Innisfree Green Tea Hyaluronic Skin est un tonique léger et rafraîchissant qui donne à votre peau un regain d''hydratation tout en la laissant douce et lisse. Infusé de thé vert nourrissant et d''acide hyaluronique hydratant, il aide votre peau à se sentir fraîche et rebondie, prête à absorber les prochaines étapes de votre routine de soins. La formule à absorption rapide est apaisante et douce, ce qui la rend parfaite pour une utilisation quotidienne, matin et soir.', 170, 'ml', 'innisfree-green-tea-hyaluronic-skin', 'https://korean-skincare.fr/products/innisfree-green-tea-hyaluronic-skin', 'https://aurore-cdn.b-cdn.net/products/innisfree-green-tea-hyaluronic-skin.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le sur l''ensemble de ton visage en suivant ton grain de peau. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 2395, '2026-05-07 17:37:38.506667+00', '2026-06-14 15:14:07.69+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3ccf-7435-ba19-bf3dabc2e8d0', '__OWNER_ID__', 'Blueberry Rebalancing Lotion', 'INNISFREE', 'moisturizer', 'jar', 'Purified Water, Glycerin, Caprylic/Capric Triglyceride, Propanediol, Hydrogenated Poly(C6-14 Olefin), 1,2-Hexanediol, Glyceryl Stearate, Caprylyl Methicone, Squalane, Behenyl Alcohol, C12-14 Alkyl-12, Stearyl Alcohol, Methyl Gluceth-20, Vinyl Dimethicone, C30-45 Alkyl Cetearyl Dimethicone Crosspolymer, Carbomer, Tromethamine, Sodium Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Ethylhexylglycerin, Butylene Glycol, Polyisobutene, Limonene, Saccharide Hydrolysate, Sodium Hyaluronate, Sodium Stearoyl Glutamate, Fructooligosaccharides, Pullulan, Lavandula Angustifolia Oil, Linalool, Caprylyl/Capryl Glucoside, Sorbitan Oleate, Hyaluronic Acid, Centella Asiatica Extract, Aster Extract, Chia Seed Extract, Low Sweet Blueberry Extract, Citrus Aurantium Dulcis Peel Oil, Panthenol, Allantoin, Caprylic/Capric Triglyceride, Maltodextrin, Ammonium Acryloyldimethyl Taurate/VP Copolymer, Tocopherol, Acai Palm Fruit Extract, Raspberry Leaf Extract, Hydrolyzed Hyaluronic Acid', 'La Lotion rééquilibrante aux bleuets Innisfree est un hydratant léger qui aide à maintenir le pH naturel de la peau et l''équilibre huile-humidité. Infusée d''extrait de bleuet et de triple acide hyaluronique, elle procure une hydratation profonde et durable tout en gardant la peau douce et confortable. Sa texture fluide et rafraîchissante pénètre rapidement et hydrate la peau sans la rendre lourde ou collante. Cette lotion quotidienne apaise les peaux sèches ou irritées, aide à lisser le grain de la peau et à lui redonner un éclat sain. Parfaite pour tous les types de peau, elle laisse une sensation d''équilibre, de nourriture et de fraîcheur tout au long de la journée.', 130, 'ml', 'innisfree-blueberry-rebalancing-lotion', 'https://korean-skincare.fr/products/innisfree-blueberry-rebalancing-lotion', 'https://aurore-cdn.b-cdn.net/products/innisfree-blueberry-rebalancing-lotion.webp', 'Après avoir nettoyé et préparé ta peau avec un tonique. Applique délicatement une quantité suffisante de crème sur ton visage en évitant le contour des yeux et de la bouche. Tapote délicatement la zone où la crème a été appliquée, afin qu''elle soit absorbée par ta peau.', 1245, '2026-05-07 17:37:38.511048+00', '2026-06-14 15:14:07.69+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3ccc-7e0e-ab68-35f996bde511', '__OWNER_ID__', 'Cherry Blossom Glow Tone-Up Cream', 'INNISFREE', 'moisturizer', 'jar', 'Aqua, Dimethicone, Propanediol, Glycerin, Dicaprylyl Carbonate, Titanium Dioxide, Titanium Dioxide, Polysorbate 80, Niacinamide, 1,2-Hexanediol, Betaine, Diisostéaryl Malate, Trisiloxane, Ammonium Acryloyldiméthyltaurate/VP Copolymère, Parfum, Polyacrylate-13, Hydroxyéthyl Acrylate/Sodium Acryloyldiméthyl Taurate Copolymère, Diméthicone/Vinyl Diméthicone Crosspolymère, Fluorphlogopite Synthétique, Polyisobutene, Glyceryl Caprylate, Hydroxyde d''Aluminium, Ethylhexylglycerin, Triéthoxycaprylylsilane, Sorbitan Isostearate, Polysorbate 20, Disodium EDTA, Polysorbate 60, Extrait de Feuille de Prunus Yedoensis, Oxydes de Fer CI 77491, Oxyde d''Étain, Geraniol, Limonene, Tocopherol, Silica', 'La Cherry Blossom Glow Tone-Up Cream INNISFREE est une crème légère et hydratante qui illumine ta peau et lui donne un éclat frais et radieux. Enrichie en extrait de fleur de cerisier, elle aide à uniformiser le teint tout en laissant la peau douce et hydratée. Sa texture crémeuse se fond facilement, laissant la peau lumineuse et saine avec un fini subtil et légèrement rosé. Parfaite pour un look naturel et éclatant. Formulée avec du niacinamide et des ingrédients bienfaisants pour la peau comme la glycérine et la bétaïne, cette crème tonifiante soutient également la santé de la barrière cutanée tout en offrant une hydratation durable. Sa formule douce, sans alcool et sans parabènes, convient à tous les types de peaux, y compris les peaux sensibles. Utilisée seule ou comme base de maquillage, elle sublime le teint avec un effet floutant, laissant la peau lisse, uniforme et naturellement radieuse. Recommandé pour : Tous types de peaux.', 50, 'ml', 'innisfree-cherry-blossom-glow-tone-up-cream', 'https://korean-skincare.fr/products/innisfree-cherry-blossom-glow-tone-up-cream', 'https://aurore-cdn.b-cdn.net/products/innisfree-cherry-blossom-glow-tone-up-cream.webp', 'Applique lors de la dernière étape de ta routine beauté. Étale une quantité généreuse de crème sur ton visage, ton cou et la partie supérieure de ta poitrine. Masse délicatement ta peau pour une meilleure absorption.', 2395, '2026-05-07 17:37:38.508758+00', '2026-06-14 15:14:07.69+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3d6b-7a37-98ed-5ee95e6aa21c', '__OWNER_ID__', '4D Mascara', 'MISSHA', 'moisturizer', 'jar', 'Aqua, Ethylhexanediol, Cera Alba, Euphorbia Cerifera Cera, Tocopheryl Acetate, Magnesium Aluminum Silicate, Oxyde de fer noir (CI 77499), Alcohol, PVP, Hydroxyéthylcellulose, Acide Isostéarique, Glycerin, Copolymère d''Acrylates, Glyceryl Stearate SE, Sesquioléate de Sorbitane, Triethanolamine, Palmitic Acid, Lanoline, Copolymère Acrylates/Ethylhexyl Acrylate, Dimethicone, Stearic Acid, Copolymère VP/Hexadécène, Glyceryl Caprylate, Alcool polyvinylique, Cire de Copernicia Cerifera (Carnauba), 1,2-Hexanediol, Disodium EDTA, Cetearyl Alcohol', 'Le Mascara 4D Missha vient déposer une couche protectrice sur chaque cil, ce qui donne à vos cils un aspect fourni et volumineux.', 7, 'g', 'missha-4d-mascara', 'https://korean-skincare.fr/products/missha-4d-mascara', 'https://aurore-cdn.b-cdn.net/products/missha-4d-mascara.webp', NULL, 647, '2026-05-07 17:37:38.667499+00', '2026-06-14 15:14:07.691+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cdb-7fb2-b01c-7a32cfcbc00b', '__OWNER_ID__', 'My Lash Serum', 'ETUDE', 'serum', 'dropper', 'Aqua, Butylene Glycol, Glycerin, 1,2-Hexanediol, Ammonium Acryloyldimethyltaurate/VP Copolymer, Caprylyl Glycol, Ethylhexylglycerin, Alcohol, Panthenol, Zingiber Officinale Root Extract, Biotin, Tocopherol', 'Le Sérum My Lash d''Etude House est une formule spécialisée pour le soin des cils, enrichie de biotine, de panthénol et d''extrait de racine de gingembre, qui nourrit et renforce les cils pour leur donner un aspect plus sain et plus fourni. La texture légère et transparente du gel s''absorbe rapidement sans laisser de traces, ce qui permet de l''appliquer facilement de jour comme de nuit. La biotine et le panthénol agissent de concert pour revitaliser et fortifier les cils, tandis que l''extrait de racine de gingembre les nourrit davantage. Avec une utilisation régulière, ce sérum aide à améliorer la résilience des cils et favorise une brillance naturelle et saine pour des cils magnifiquement mis en valeur.', NULL, NULL, 'etude-house-my-lash-serum', 'https://korean-skincare.fr/products/etude-house-my-lash-serum', 'https://aurore-cdn.b-cdn.net/products/etude-house-my-lash-serum.webp', 'Applique lors de la dernière étape de ta routine beauté. Applique principalement à la racine de tes cils.', 795, '2026-05-07 17:37:38.52382+00', '2026-06-14 15:14:07.691+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cf5-7f9e-88af-8131f7219e13', '__OWNER_ID__', 'Dear Darling Oil Tint', 'ETUDE', 'moisturizer', 'jar', '01 Real Cherry : Copopolymère de Polyglyceryl-2 Isostéarate/Dimer Dilinoleate, Polyglyceryl-2 Triisostéarate, Caprylic/Capric Triglyceride, Malate de Diisostéaryle, Silice Dimethyl Silylate, Red 7 Lake CI 15850, Yellow 5 Lake CI 19140, Coco-Caprylate/Caprate, Copolymère d’Huile de Ricin/IPDI, Parfum, Triglycéride Caprylique/Caprique/Succinique, Sorbitan Sesquioleate, Linalool 02 Plum Berry : Copopolymère de Polyglyceryl-2 Isostéarate/Dimer Dilinoleate, Polyglyceryl-2 Triisostéarate, Caprylic/Capric Triglyceride, Malate de Diisostéaryle, Silice Dimethyl Silylate, Red 7 Lake CI 15850, Oxydes de Fer CI 77491, Coco-Caprylate/Caprate, Copolymère d’Huile de Ricin/IPDI, Parfum, Oxydes de Fer CI 77499, Triglycéride Caprylique/Caprique/Succinique, Sorbitan Sesquioleate, Linalool, Limonene 03 Neon Pink : Copopolymère de Polyglyceryl-2 Isostéarate/Dimer Dilinoleate, Polyglyceryl-2 Triisostéarate, Caprylic/Capric Triglyceride, Malate de Diisostéaryle, Silice Dimethyl Silylate, Red 28 Lake CI 45410, Coco-Caprylate/Caprate, Copolymère d’Huile de Ricin/IPDI, Parfum, Triglycéride Caprylique/Caprique/Succinique, Sorbitan Sesquioleate, Yellow 5 Lake CI 19140, Linalool, Limonene 04 Sweet Apple : Copopolymère de Polyglyceryl-2 Isostéarate/Dimer Dilinoleate, Polyglyceryl-2 Triisostéarate, Caprylic/Capric Triglyceride, Malate de Diisostéaryle, Silice Dimethyl Silylate, Red 28 Lake CI 45410, Yellow 5 Lake CI 19140, Coco-Caprylate/Caprate, Copolymère d’Huile de Ricin/IPDI, Parfum, Triglycéride Caprylique/Caprique/Succinique, Sorbitan Sesquioleate, Linalool, Limonene 05 Red Oil : Copopolymère de Polyglyceryl-2 Isostéarate/Dimer Dilinoleate, Polyglyceryl-2 Triisostéarate, Caprylic/Capric Triglyceride, Malate de Diisostéaryle, Red 28 Lake CI 45410, Red 21 CI 45380, Yellow 5 Lake CI 19140, Parfum, Sorbitan Sesquioleate, Linalool, Limonene 06 Pink Oil : Copopolymère de Polyglyceryl-2 Isostéarate/Dimer Dilinoleate, Polyglyceryl-2 Triisostéarate, Caprylic/Capric Triglyceride, Malate de Diisostéaryle, Parfum, Phloxine B, Linalool, Tétrabromofluorescéine, Dioxyde de Titane CI 77891, Limonene, Sorbitan Sesquioleate', 'La Dear Darling Oil Tint ETUDE est une luxueuse encre à lèvres qui offre une couleur éclatante et longue tenue avec une finition ultra-brillante et non collante. Composée de plus de 70 % d’huiles nourrissantes, elle glisse en douceur pour hydrater et adoucir les lèvres tout en apportant une brillance lumineuse. Disponible dans une gamme de teintes ludiques, des rouges juteux aux roses vifs, cette encre à lèvres combine couleur intense et soin des lèvres dans un format élégant et facile à emporter. Recommandé pour : Tous les types de lèvres.', NULL, NULL, 'etude-dear-darling-oil-tint', 'https://korean-skincare.fr/products/etude-dear-darling-oil-tint', 'https://aurore-cdn.b-cdn.net/products/etude-dear-darling-oil-tint.webp', 'Applique directement sur tes lèvres à l’aide de l’applicateur. Pour un look intense et saturé, passe une ou deux couches. Pour un effet plus doux, applique uniquement au centre de tes lèvres puis estompe du bout du doigt pour un fini dégradé naturel.', 1195, '2026-05-07 17:37:38.54977+00', '2026-06-14 15:14:07.691+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-3cd6-7ce3-a0ad-a8f800999234', '__OWNER_ID__', 'SoonJung 2x Barrier Intensive Cream', 'ETUDE', 'moisturizer', 'bar', 'Aqua, Propanediol, Pentaerythrityl Tetraethylhexanoate, Caprylic/Capric Triglyceride, Glycerin, Helianthus Annuus Seed Oil, Polyglyceryl-3 Methylglucose Distearate, Butyrospermum Parkii Butter, Cetearyl Alcohol, Panthenol, 1,2-Hexanediol, Carbomer, Gomme Xanthane, Potassium Hydroxide, Disodium EDTA, Madecassoside, Butylene Glycol, Extrait de Feuille de Camellia Sinesis', 'Cette crème est soigneusement formulée avec un mélange d''ingrédients doux mais efficaces, notamment le propanediol, la glycérine et l''huile de graines de tournesol, pour offrir une hydratation en profondeur et renforcer la barrière naturelle de la peau. Enrichi en panthénol et en madécassoside, il aide à calmer et à apaiser les peaux sensibles ou irritées, favorisant un teint plus sain et plus équilibré. Profite de la texture réconfortante de la Soon Jung 2x Barrier Intensive Cream et adopte le soin ultime pour le bien-être de ta peau. Recommandé pour : Tous types de peaux.', 60, 'ml', 'etude-house-soonjung-2x-barrier-intensive-cream', 'https://korean-skincare.fr/products/etude-house-soonjung-2x-barrier-intensive-cream', 'https://aurore-cdn.b-cdn.net/products/etude-house-soonjung-2x-barrier-intensive-cream.webp', 'Après avoir nettoyé et tonifié ton visage, prélève une petite quantité de la SoonJung 2x Barrier Intensive Cream. Applique délicatement la crème sur ton visage, en insistant sur les zones sèches ou sensibles. Masse la crème dans ta peau jusqu''à ce qu''elle soit complètement absorbée. Utilise la crème matin et soir comme dernière étape de ta routine beauté pour une hydratation profonde et une protection optimale de ta barrière cutanée.', 1595, '2026-05-07 17:37:38.518661+00', '2026-06-14 15:14:07.691+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
