INSERT INTO public.products VALUES ('019e0384-42db-7cb4-8a0c-6450fc1cfbef', '__OWNER_ID__', 'Kids & Baby Cream', 'Pyunkang Yul', 'moisturizer', 'jar', 'Aqua, Glycerin, Dipropylene Glycol, Cetearyl Alcohol, Butyrospermum Parkii Butter, Caprylic/Capric Triglyceride, Ethylhexyl Palmitate, Helianthus Annuus Seed Oil, Octyldodecanol, Polyglycéryle-3 Distearate, Dimethicone, Glyceryl Stearate, Butylene Glycol, Euphorbia Cerifera Cera, Sorbitan Sesquioleate, Cetearyl Glucoside, Caprylyl Glycol, Glycéryle Stéarate Citrate, Microcrystalline Cellulose, Pentylene Glycol, Hydroxyacetophenone, Carbomer, Tromethamine, Cetyl Ethylhexanoate, Centella Asiatica Extract, Ethylhexylglycerin, Gomme Xanthane, Gomme Cellulose, Hydrogenated Lecithin, Disodium EDTA, Tocopherol, 1,2-Hexanediol, Allantoin, Argania Spinosa Kernel Oil, Simmondsia Chinensis Seed Oil, Prunus Amygdalus Dulcis Oil, Persea Gratissima Oil, Panthenol, Glucose, Macadamia Ternifolia Seed Oil, Extrait d''Anastatica Hierochuntica, Cholesterol, Stérols de Brassica Campestris, Phytostéryl/Behényl/Octyldodécyl Lauroyl Glutamate, Sodium Hyaluronate, Lonicera Japonica Flower Extract, Polyglycéryle-10 Oléate, Extrait d''Artemisia Capillaris, Ceramide NP, Phosphate de Cétyle Potassique, Hydrolyzed Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Crosspolymer d''Hyaluronate de Sodium, Sodium Acetyl Hyaluronate, Céramide NS Céramide EOP, Huile de Fruit de Citrus Aurantium Bergamia, Citrus Aurantium Dulcis Peel Oil, Citrus Nobilis Peel Oil, Citral, Limonene, Linalool', 'La Kids & Baby Cream Pyunkang Yul est une crème hydratante hypoallergénique testée par des dermatologues, spécialement conçue pour nourrir et protéger la peau délicate des bébés. Infusée de plante de la résurrection, elle hydrate en profondeur et apaise même les peaux les plus sensibles tout en prévenant la sécheresse, les gerçures et les irritations. Un puissant mélange de 5 types d''acide hyaluronique et de 3 céramides renforce la barrière cutanée, en retenant l''hydratation et en protégeant la peau contre les agressions extérieures. Riche en plantes apaisantes comme la Centella Asiatica, la fleur de chèvrefeuille et l''extrait d''Artemisia Capillaris, cette formule douce soulage l''irritation tandis que six huiles vitaminées - dont le jojoba, le macadamia, l''avocat et l''argan - restaurent la douceur et l''élasticité. Recommandé pour : Peaux normales à sèches.', 400, 'ml', 'kids-baby-cream', 'https://korean-skincare.fr/products/kids-baby-cream', 'https://aurore-cdn.b-cdn.net/products/kids-baby-cream.webp', 'Applique une quantité modérée de crème sur les zones sèches et masse délicatement en mouvements circulaires.', 1838, '2026-05-07 17:37:40.05963+00', '2026-06-14 15:14:07.773+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42d6-7ed3-a29e-8e212147f283', '__OWNER_ID__', 'Moisture Soothing Sun Cream SPF50 PA++++', 'Pyunkang Yul', 'moisturizer', 'jar', 'Aqua, Zinc Oxide, Cyclopentasiloxane, Homosalate, Salicylate de Butyloctyle, Propanediol, Ethylhexyl Salicylate, Caprylate de Propylheptyl, Polyglyceryl-4 Diisostearate/Polyhydroxystearate/Sebacate, Titanium Dioxide, Hectorite de Disteardimonium, Polyglyceryl-3 Polydiméthylsiloxyéthyl Diméthicone, Magnesium Sulfate, Triméthicone Phényl, 1,2-Hexanediol, Polyméthylsilsesquioxane, Copolymère Acrylates/Diméthicone, Triéthoxycaprylylsilane, Stearic Acid, Hydroxyde d''Aluminium, Glyceryl Caprylate, Caprylyl Glycol, Éthylhexylglycérol, Tocopherol, Allantoin, Ceramide NP, Sodium Hyaluronate, Butylene Glycol, Dipropylene Glycol, Glycerin, Camellia Sinensis Leaf Extract, Artemisia Princeps Leaf Extract, Centella Asiatica Extract, Houttuynia Cordata Extract, Glycyrrhiza Glabra Root Extract, Extrait de Bulbe d''Allium Sativum, Lonicera Japonica Flower Extract, Extrait de Salicornia Herbacea, Extrait de Fruit de Xanthium Strumarium, Extrait de Racine de Sophora Angustifolia, Zingiber Officinale Root Extract, Extrait de Fruit de Poncirus Trifoliata, Ulmus Davidiana Root Extract', 'La Moisture Soothing Sun Cream SPF50 PA++++ Pyunkang Yul est une crème solaire hybride physique + chimique hydratante et apaisante. Elle est enrichie en extrait de Centella Asiatica et en céramide pour apaiser et hydrater les peaux sensibles. Sans danger pour ta peau et la nature - ingrédients inoffensifs certifiés par l''EWG et Reef Safe.', 75, 'ml', 'pyunkang-yul-moisture-soothing-sun-cream-spf50-pa', 'https://korean-skincare.fr/products/pyunkang-yul-moisture-soothing-sun-cream-spf50-pa', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-moisture-soothing-sun-cream-spf50-pa.webp', 'Prélève une quantité suffisante de produit et applique-le uniformément sur ta peau, en évitant le contour des yeux.', 2095, '2026-05-07 17:37:40.054772+00', '2026-06-14 15:14:07.774+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42f4-7253-b11e-2f4e72347909', '__OWNER_ID__', 'Kids & Baby Face Lotion', 'Pyunkang Yul', 'moisturizer', 'jar', 'Aqua, Glycerin, Dipropylene Glycol, Macadamia Integrifolia Seed Oil, Methylpropanediol, Polyglycéryl-3 Distéarate Hydrogéné, Caprylic/Capric Triglyceride, Octyldodecanol, Sesquioléate de Sorbitan, Butylene Glycol, Ammonium Acryloyldimethyltaurate/VP Copolymer, Caprylyl Glycol, Citrate de Stéarate de Glycéryle, Pentylene Glycol, Hydroxyacetophenone, Helianthus Annuus Seed Oil, Carbomer, Tromethamine, Trehalose, Hydrogenated Lecithin, Ethylhexylglycerin, Disodium EDTA, Tocopherol, Huile d''Amande Douce (Prunus Amygdalus Dulcis), Moringa Oleifera Seed Oil, Huile d''Avocat (Persea Gratissima), Simmondsia Chinensis Seed Oil, Argania Spinosa Kernel Oil, Huile de Graines de Camellia Sinensis, 1,2-Hexanediol, Centella Asiatica Extract, Glycyrrhiza Glabra Root Extract, Extrait de Feuille d''Artemisia Montana, Huile de Macadamia Ternifolia, Sodium Hyaluronate, Extrait de Fruit de Vaccinium Corymbosum, Extrait d''Anastatica Hierochuntica, Lonicera Japonica Flower Extract, Extrait de Feuille de Ginkgo Biloba, Rosa Canina Fruit Oil, Glutamate de Lauroyl de Phytostéryl/Béhényle/Octyldodécyle, Cholesterol, Stérols de Brassica Campestris, Hydrolyzed Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Oléate de Polyglycéryl-10, Phosphate de Cétyl Potassique, Ceramide NP, Sodium Hyaluronate Crosspolymer, Acétyl Hyaluronate de Sodium, Ceramide NS, Ceramide EOP, Huile de Fruit de Citrus Aurantium Bergamia, Citrus Aurantium Dulcis Peel Oil, Limonene, Linalool', 'La Kids & Baby Face Lotion Pyunkang Yul est une lotion douce et hydratante conçue spécifiquement pour la peau délicate des bébés et des jeunes enfants. Ce produit est formulé avec un mélange d''ingrédients nourrissants qui agissent ensemble pour apaiser et protéger les peaux sensibles. La lotion contient également plusieurs huiles d''origine végétale, notamment l''huile d''amande douce, l''huile de graines de moringa oleifera, l''huile d''avocat, l''huile de jojoba, l''huile d''argan et l''huile de graines de thé vert. Ces huiles apportent une hydratation et une nutrition supplémentaires à la peau. En plus des ingrédients ci-dessus, la lotion contient également plusieurs types de céramides, notamment le céramide NP, le céramide NS et le céramide EOP. Les céramides sont des lipides naturels qui aident à renforcer la barrière cutanée et à retenir l''hydratation. La Kids & Baby Face Lotion Pyunkang Yul est une lotion douce et nourrissante qui convient à un usage quotidien sur la peau délicate des bébés et des jeunes enfants. Son mélange d''ingrédients hydratants, d''huiles et d''extraits végétaux, et de céramides agissent ensemble pour apaiser et protéger les peaux sensibles.', 200, 'ml', 'pyunkang-yul-kids-baby-face-lotion', 'https://korean-skincare.fr/products/pyunkang-yul-kids-baby-face-lotion', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-kids-baby-face-lotion.webp', 'Prends une quantité appropriée et applique-la délicatement sur le visage. Les jours où la peau est particulièrement sèche, applique-la plusieurs fois pour davantage d''hydratation.', 1757, '2026-05-07 17:37:40.083996+00', '2026-06-14 15:14:07.774+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42e5-72db-8dde-aa996758269b', '__OWNER_ID__', 'ATO Mild Sun Cream', 'Pyunkang Yul', 'moisturizer', 'jar', 'Aqua, Butyloctyl Salicylate, Propanediol, Propylheptylcaprylate, Polyglyceryl-4 Diisostearate/Polyhydroxystearate/Sebacate, Disteadimonium Hectorite, Polyglyceryl-3 Polydimethylsiloxyethyl Dimethicone, Magnesium Sulfate, Phenyltrimethicone, 1,2-Hexanediol, Polymethylsilsesquioxane, Copolymère d''Acrylate/Dimethicone, Triethoxycaprylylsilane, Stearic Acid, Hydroxyde d''Aluminium, Glyceryl Caprylate, Caprylyl Glycol, Glycérine d''Ethylhexyl, Tocopherol, Ceramide NP, Sodium Hyaluronate, Butylene Glycol, Dipropylene Glycol, Glycerin, Camellia Sinensis Leaf Extract, Extrait d''Artemisia Princeps, Ulmus Davidiana Root Extract, Extrait de Fruit de Xanthium Strumarium, Extrait de Salicornia Herbacea, Zingiber Officinale Root Extract, Lonicera Japonica Flower Extract, Extrait de Fruit de Poncirus Trifoliata, Extrait de Racine de Sophora Angustifolia, Extrait de Bulbe d''Allium Sativum (Ail), Zinc Oxide, Cyclopentasiloxane, Homosalate, Ethylhexyl Salicylate, Titanium Dioxide, Glycyrrhiza Glabra Root Extract', 'L''Ato Mild Sun Cream de Pyunkang Yul est une nouvelle crème solaire délicate et légère mais particulièrement efficace, qui ne laisse pas de traces blanches. Formulée avec des ingrédients certifiés par l''EWG pour protéger les peaux délicates, et dotée d''un puissant SPF 45 PA+++ à large spectre pour protéger contre les rayons UV et prévenir les dommages causés par les radicaux libres. Cette crème solaire est enrichie d''acide hyaluronique, de céramide et d''extraits de plantes pour apaiser et hydrater les peaux sèches et sensibles.', 75, 'ml', 'pyunkang-yul-ato-mild-sun-cream', 'https://korean-skincare.fr/products/pyunkang-yul-ato-mild-sun-cream', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-ato-mild-sun-cream.webp', 'Applique sur les zones exposées du visage/corps 30 minutes avant de sortir au soleil. Renouvelle l''application toutes les deux heures pour une protection solaire parfaite pendant la journée.', 2294, '2026-05-07 17:37:40.069087+00', '2026-06-14 15:14:07.774+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42eb-71da-9de7-0b56840cef58', '__OWNER_ID__', 'Kids & Baby Sun Cream', 'Pyunkang Yul', 'moisturizer', 'jar', 'Aqua, Dipropylene Glycol, Ethylhexyl Methoxycinnamate, Homosalate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Ethylhexyl Salicylate, Glycerin, Niacinamide, Polyglycéryl-3 Distearate, Cetyl Alcohol, Salicylate De Butyloctyle, Octenylsuccinate D''amidon D''aluminium, Macadamia Ternifolia Seed Oil, Huile D''avocat (Persea Gratissima), Huile D''amande Douce (Prunus Amygdalus Dulcis), Simmondsia Chinensis Seed Oil, Argania Spinosa Kernel Oil, Helianthus Annuus Seed Oil, Extrait De Graines De Quinoa (Chenopodium Quinoa), Oryza Sativa Extract, Extrait De Germe De Riz (Oryza Sativa), Oryza Sativa Extract, Extrait De Fleur/Feuille/Tige De Leonurus Sibiricus, Extrait De Fleur De Nelumbo Nucifera, Houttuynia Cordata Extract, Extrait D''artemisia Vulgaris, Camellia Sinensis Leaf Extract, Hydroxyacetophenone, Pentylene Glycol, Extrait De Graines De Phaseolus Angularis, Caprylyl Glycol, Caprylic/Capric Triglyceride, Extrait D''anastatica Hierochuntica, Extrait De Fruit D''arachis Hypogaea, Extrait De Graines De Phaseolus Vulgaris, Sodium Hyaluronate, Extrait De Graines De Vigna Radiata, Lonicera Japonica Flower Extract, Extrait De Lentille (Lens Esculenta), Cetyl Ethylhexanoate, Ethylhexyl Palmitate, Arginine, Stérols De Brassica Campestris, Cholesterol, Glutamate De Phytostéryle/Behenyle/Octyldodécyle Lauroyl, Hydrogenated Lecithin, Centella Asiatica Extract, Hyaluronate Hydrolysé, Hydroxypropyltrimonium Hyaluronate, Polyglycéryl-10 Oléate, Ceramide NP, Sodium Hyaluronate Crosspolymer, Sodium Acetyl Hyaluronate, Ceramide NS, Ceramide EOP, Copolymère De Diméthicone/Vinyl Diméthicone, Glyceryl Caprylate, Glyceryl Stearate, Trehalose, Phosphate De Cétyle De Potassium, Sesquioleate De Sorbitan, Tromethamine, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Butylene Glycol, Carbomer, Glycéryl Stéarate Citrate, Salix Alba Bark Extract, Myristate De Polyglycéryl-10, Ethylhexylglycerin, Adenosine, Disodium EDTA, Tocopheryl Acetate, 1,2-Hexanediol', 'La Kids & Baby Sun Cream Pyunkang Yul est la solution parfaite pour protéger tes enfants des effets nocifs du soleil. Cette crème solaire puissante mais délicate est spécialement formulée pour apaiser et hydrater la peau fragile de ton enfant tout en lui offrant une protection fiable contre les rayons UV. Avec une protection SPF50+ et PA+++, la Kids & Baby Sun Cream Pyunkang Yul offre une protection supérieure contre les rayons UVA et UVB, ce qui en fait un produit indispensable pour les journées ensoleillées. Sa formule légère et transparente s''applique en douceur sans coller, ce qui permet à tes enfants de rester à l''aise toute la journée. Cette crème solaire est spécialement conçue pour les enfants et les bébés, tu peux donc être assurée qu''elle soit sans danger pour tes enfants. Elle est douce et non irritante, ce qui la rend parfaite même pour les plus jeunes membres de ta famille. La Kids & Baby Sun Cream Pyunkang Yul est également exempte de produits chimiques et de parfums nocifs, ce qui la rend idéale pour les enfants à la peau sensible. Protège tes proches des rayons solaires nocifs avec la Kids & Baby Sun Cream Pyunkang Yul. Sa formule puissante et douce est conçue pour apaiser et hydrater la peau de ton enfant tout en lui offrant une protection solaire supérieure.', 75, 'ml', 'pyunkang-yul-kids-baby-sun-cream', 'https://korean-skincare.fr/products/pyunkang-yul-kids-baby-sun-cream', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-kids-baby-sun-cream.webp', 'Applique une quantité appropriée sur la peau, en évitant le contour des yeux, comme dernière étape de la routine de soins. Renouvelle l''application toutes les 2 ou 3 heures.', 1660, '2026-05-07 17:37:40.075042+00', '2026-06-14 15:14:07.775+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42ef-7405-9ba5-2bffbb849463', '__OWNER_ID__', 'Eye Cream', 'Pyunkang Yul', 'eye-cream', 'jar', 'Extrait de Racine d’Astragalus Membranaceus, Petrolatum, Glycerin, Dimethicone, Butyrospermum Parkii Butter, Stearyl Alcohol, Cetyl Alcohol, Phenyl Trimethicone, 1,2-Hexanediol, Cérésine, Niacinamide, Pentylene Glycol, Polysorbate 60, Butylene Glycol, Adenosine, Aqua, Glyceryl Stearate, Silica, Acetyl Glucosamine, Myristyl Alcohol, Sodium Hyaluronate, Alcool Laurique, Tocopherol, Acide Acétique, Filtrat de Ferment de Racine de Panax Ginseng/Lactobacillus, Lauryl PEG-9 Polydimethylsiloxyethyl Dimethicone, PEG-100 Stearate, Glycyrrhiza Uralensis Root Extract, Huile de Fruit de Citrus Aurantium Bergamia, Linalool, Limonene', 'Réveille et rafraîchis ton regard fatigué avec l''Eye Cream Pyunkang Yul, une formule douce mais efficace qui offre une hydratation intense tout en lissant visiblement les ridules. Enrichie en extrait de ginseng nourrissant, elle aide à améliorer la fermeté de la peau pour un contour des yeux plus jeune et revitalisé. Idéale pour les peaux sèches et mixtes. La crème est proposée dans un format pratique et nomade comprenant 50 sachets individuels de 1 ml, scellés séparément pour préserver la fraîcheur et l’hygiène. Ce conditionnement protège la formule des UV, limite l’exposition à l’air et évite toute contamination. Facile à utiliser, elle est parfaite pour les voyages ou les retouches en déplacement. Recommandé pour : Peaux matures, peaux sèches, tous types de peaux.', 1, 'ml', 'pyunkang-yul-eye-cream', 'https://korean-skincare.fr/products/pyunkang-yul-eye-cream', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-eye-cream.webp', 'Prends un sachet et applique la crème sur le contour de tes yeux. Tapote délicatement pour favoriser l’absorption. Astuce : Pour des résultats optimaux, utilise-la avec l’Essence Toner et la Nutrition Cream de Pyunkang Yul dans le cadre de ta routine beauté quotidienne.', 2312, '2026-05-07 17:37:40.079152+00', '2026-06-14 15:14:07.775+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4327-7308-b1df-03b57cba0b98', '__OWNER_ID__', 'Centella Phyto & 5 Peptide Concentrate Cream', 'Haruharu Wonder', 'serum', 'dropper', 'Aqua, Glycerin, Butylene Glycol, Caprylic/Capric Triglyceride, Helianthus Annuus Seed Oil, Polyglycéryl-3 Distearate, 1,2-Hexanediol, Cetyl Alcohol, Cetyl Palmitate, Ammonium Acryloyldimethyltaurate/VP Copolymer, Palmitate de Sorbitan, Sorbitan Olivate, Glyceryl Stearate, Stearyl Alcohol, Gomme Xanthane, Stéarate de Glycéryle Citrate, Myristyl Alcohol, Squalane, Caffeine, Protéine de Soja Hydrolysée, Hydrogenated Lecithin, Pentylene Glycol, Ethylhexylglycerin, Adenosine, Butyrospermum Parkii Butter, Phytostérols, Alcool Laurique, Centella Asiatica Extract, Protéine de Pois Hydrolysée, Madecassoside, Asiaticoside, Caprylyl Glycol, Xylitylglucoside, Anhydroxylitol, Tripeptide-1 de Cuivre, Xylitol, Acetyl Hexapeptide-8, Acide Asiatique, Acide Madécassique, Glucose, Ceramide NP, Hippophae Rhamnoides Fruit Extract, Oligopeptide-32, Oligopeptide-29, Palmitoyl Pentapeptide-4', 'Régale ta peau grâce à la luxueuse WONDER Centella Phyto 5 Peptide Concentrate Cream Haruharu, une crème polyvalente pour le visage qui répond à de multiples préoccupations en matière de soins de la peau, le tout dans une seule formule complète. Infusée d''un puissant mélange de complexe de 5 peptides, cette crème vegan combat les signes du vieillissement, en améliorant la fermeté de la peau et en minimisant l''apparence des rides et des ridules tout en fortifiant la barrière cutanée. Les protéines de soja hydrolysées et l''adénosine procurent une hydratation intense et favorisent l''élasticité, tandis que le squalane et la caféine agissent pour éclaircir et défroisser la peau, empêchant la perte d''hydratation pour un teint radieux. Avec 150ppm d''extrait de cica, cette crème apaise et hydrate le visage, garantissant une peau apaisée et nourrie. Recommandé pour : Peaux sensibles, peaux sèches, tous types de peaux.', 30, 'ml', 'haruharu-wonder-centella-phyto-5-peptide-concentrate-cream', 'https://korean-skincare.fr/products/haruharu-wonder-centella-phyto-5-peptide-concentrate-cream', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-centella-phyto-5-peptide-concentrate-cream.webp', 'Applique le produit et étale-le délicatement sur ta peau à lors de la dernière étape de ta routine beauté, en évitant le contour des yeux et de la bouche. Tapote légèrement pour faire pénétrer le produit dans ta peau.', 2195, '2026-05-07 17:37:40.135002+00', '2026-06-14 15:14:07.775+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42f1-789e-9636-cd3b84fb86d1', '__OWNER_ID__', 'Kids & Baby Shampoo Sweet Orange', 'Pyunkang Yul', 'shampoo', 'jar', 'Aqua, Glycerin, Dipropylene Glycol, Macadamia Integrifolia Seed Oil, Polyglycéryl-3 Méthylglucose Distearate, Macadamia Ternifolia Seed Oil, Sodium Hyaluronate, Phytosteryl/Behenyl/Odyidodecyl Lauroyl Glutamate, Cholesterol, Stérols de Brassica Campestris, Extrait de Racine de Broussonetia Kazinoki, Extrait de Racine d’Astragalus Membranaceus, Extrait de Fleur de Chrysanthemum Morifolium, Polyglycéryl-10 Oléate, Hydrolyzed Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Phosphate de Cétyl Potassium, Ceramide NP, Sodium Hyaluronate Crosspolymer, Sodium Acetylated Hyaluronate, Ceramide NS, Ceramide EOP, Glyceryl Stearate, Glyceryl Caprylate, Polydecène Hydrogéné, Cetearyl Alcohol, Sorbitan Sesquioleate, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Esters de Jojoba Hydrolysés, Helianthus Annuus Seed Oil, Carbomer, Tromethamine, Caprylic/Capric Triglyceride, Hydrogenated Lecithin, Ethylhexylglycerin, Disodium EDTA, Tocopherol, Butylene Glycol, Sorbitan Isostearate, 1,2-Hexanediol, Caprylyl Glycol, Pentylene Glycol', 'Le Kids & Baby Shampoo Sweet Orange Pyunkang Yul est un shampooing doux au pH faible, spécialement conçu pour le cuir chevelu délicat et les cheveux des enfants et des bébés. Formulé avec cinq types d’acide hyaluronique, des céramides et six huiles naturelles, il offre une hydratation en profondeur et un soin nourrissant. Des extraits botaniques comme la Centella Asiatica, le chèvrefeuille et l’armoise aident à apaiser et calmer la peau, tandis que l’arôme naturel d’orange douce apporte un parfum rafraîchissant et subtil. Sans sulfates, ce shampooing nettoie efficacement sans éliminer les huiles naturelles, pour un moment bain agréable et sûr pour les tout-petits. Recommandé pour : Tous types de cheveux, cuirs chevelus délicats.', 590, 'ml', 'pyunkang-yul-kids-baby-shampoo-sweet-orange', 'https://korean-skincare.fr/products/pyunkang-yul-kids-baby-shampoo-sweet-orange', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-kids-baby-shampoo-sweet-orange.webp', 'Applique une petite quantité de shampooing sur cheveux mouillés. Masse doucement ton cuir chevelu et tes cheveux pour faire mousser. Rince abondamment à l’eau tiède. Convient à une utilisation quotidienne.', 2095, '2026-05-07 17:37:40.081426+00', '2026-06-14 15:14:07.776+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42ed-7275-bd03-4029a461525a', '__OWNER_ID__', 'Kids & Baby Wash', 'Pyunkang Yul', 'body-wash', 'jar', 'Aqua, Disodium Cocoamphodiacétate, Hydroxysultaine de Lauryl, Sodium Chloride, Glycerin, Cocoyl Alaninate de Sodium, Copolymère d’Acrylates, C12-14 Pareth-12, Butylene Glycol, Caprylyl Glycol, Hydroxyacetophenone, Pentylene Glycol, Huile d’Écorce de Citrus Aurantium Dulcis, Huile de Fruit de Citrus Aurantium Bergamia, Huile d’Écorce de Citrus Nobilis, Dipropylene Glycol, Hexylene Glycol, Disodium EDTA, Tocopherol, Simmondsia Chinensis Seed Oil, Prunus Amygdalus Dulcis Oil, Persea Gratissima Oil, Helianthus Annuus Seed Oil, Camellia Japonica Seed Oil, Argania Spinosa Kernel Oil, Centella Asiatica Extract, Salix Alba Bark Extract, Myristate de Polyglycéryl-10, 1,2-Hexanediol, Extrait de Racine d’Acorus Calamus, Extrait d’Artemisia Vulgaris, Camellia Sinensis Leaf Extract, Houttuynia Cordata Extract, Extrait de Feuille de Perilla Frutescens, Propanediol, Caprylic/Capric Triglyceride, Cetyl Ethylhexanoate, Ethylhexyl Palmitate, Extrait de Graine de Chenopodium Quinoa, Oryza Sativa Extract, Extrait de Germe d’Oryza Sativa, Oryza Sativa Extract, Extrait de Graine de Phaseolus Angularis, Macadamia Ternifolia Seed Oil, Extrait de Racine de Cnidium Officinale, Extrait d’Anastatica Hierochuntica, Extrait de Fruit d’Arachis Hypogaea, Extrait de Graine de Phaseolus Vulgaris, Sodium Hyaluronate, Extrait de Graine de Phaseolus Radiatus, Lonicera Japonica Flower Extract, Extrait de Fruit de Lens Esculenta, Oléate de Phytostéryl', 'Chouchoute la peau délicate de ton bout de chou avec le Kids & Baby Wash Pyunkang Yul, un nettoyant pour le corps à la fois doux et profondément hydratant, spécialement formulé pour les bébés et les enfants. Infusé d''ingrédients naturels puissants comme l''extrait de Rose de Jéricho, le son de riz et le chèvrefeuille, ce nettoyant nettoie en profondeur sans priver la peau de son hydratation, la laissant douce et apaisée. L''inclusion de triples céramides et de cinq types d''acide hyaluronique aide à renforcer la barrière cutanée et à fournir une hydratation durable. Recommandé pour : Sans risque pour les enfants et les bébés, peaux sèches et sensibles, peaux normales à sèches.', 590, 'ml', 'pyunkang-yul-kids-baby-wash', 'https://korean-skincare.fr/products/pyunkang-yul-kids-baby-wash', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-kids-baby-wash.webp', 'Fais mousser une quantité modérée de produit avec tes mains mouillées et masse sur le corps, en externe. Rince à l''eau tiède.', 2245, '2026-05-07 17:37:40.077067+00', '2026-06-14 15:14:07.776+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42f6-7a3d-8d9c-fdaf3ae67582', '__OWNER_ID__', 'Essence In Lotion', 'Pyunkang Yul', 'essence', 'dropper', 'Aqua, Glycerin, Dipropylene Glycol, Macadamia Integrifolia Seed Oil, Polyglycéryl-3 Méthylglucose Distearate, Macadamia Ternifolia Seed Oil, Sodium Hyaluronate, Phytosteryl/Behenyl/Odyidodecyl Lauroyl Glutamate, Cholesterol, Stérols de Brassica Campestris, Extrait de Racine de Broussonetia Kazinoki, Extrait de Racine d’Astragalus Membranaceus, Extrait de Fleur de Chrysanthemum Morifolium, Polyglycéryl-10 Oléate, Hydrolyzed Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Phosphate de Cétyl Potassium, Ceramide NP, Sodium Hyaluronate Crosspolymer, Sodium Acetylated Hyaluronate, Ceramide NS, Ceramide EOP, Glyceryl Stearate, Glyceryl Caprylate, Polydecène Hydrogéné, Cetearyl Alcohol, Sorbitan Sesquioleate, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Esters de Jojoba Hydrolysés, Helianthus Annuus Seed Oil, Carbomer, Tromethamine, Caprylic/Capric Triglyceride, Hydrogenated Lecithin, Ethylhexylglycerin, Disodium EDTA, Tocopherol, Butylene Glycol, Sorbitan Isostearate, 1,2-Hexanediol, Caprylyl Glycol, Pentylene Glycol, Hydroxyacetophenone', 'Découvre l''Essence In Lotion Pyunkang Yul, une formule légère mais profondément hydratante qui procure une vague d''hydratation tout en apaisant les peaux sensibles. Infusée avec le mélange signature de la marque d’extraits botaniques nourrissants, cette lotion renforce la barrière naturelle de la peau, calme les irritations et améliore l’élasticité pour un teint lisse et souple. Parfaite pour une utilisation quotidienne, elle prépare la peau à absorber pleinement les bienfaits des étapes suivantes de votre routine. Idéale pour tous types de peaux, en particulier celles sujettes à la sécheresse ou aux rougeurs, l’Essence In Lotion pénètre rapidement sans laisser de résidu collant. Sa formule douce, sans parfum, assure que même les peaux les plus sensibles restent hydratées, équilibrées et rafraîchies. Éleve ta routine de soin avec un produit qui combine soin apaisant et hydratation avancée, offrant à ta peau confort et protection. Recommandé pour : Tous types de peaux, en particulier sensibles et sèches.', 200, 'ml', 'pyunkang-yul-essence-in-lotion', 'https://korean-skincare.fr/products/pyunkang-yul-essence-in-lotion', 'https://aurore-cdn.b-cdn.net/products/pyunkang-yul-essence-in-lotion.webp', 'Après le nettoyage et le tonique, verse une quantité appropriée de lotion dans tes paumes. Applique délicatement sur l’ensemble de ton visage et de ton cou, en tapotant légèrement pour favoriser l’absorption. Utilise matin et soir dans le cadre de ta routine quotidienne de soin. Peut être superposée sous des sérums, essences ou crèmes hydratantes pour un boost supplémentaire d’hydratation. Astuce : Pour un effet apaisant supplémentaire, conserve la lotion au réfrigérateur et applique-la froide. Cela aide à réduire les rougeurs et procure une sensation rafraîchissante, notamment après exposition au soleil ou lors de journées de peau sensible.', 2095, '2026-05-07 17:37:40.086465+00', '2026-06-14 15:14:07.777+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-42fb-799c-80ae-533eb459b986', '__OWNER_ID__', 'Black Rice Moisture 5.5 Soft Cleansing Gel', 'Haruharu Wonder', 'cleanser', 'tube', 'Aqua, Glycerin, Coco-Betaine, Propanediol, Pentylene Glycol, Sodium Chloride, 1,2-Hexanediol, Xanthan Gum, Hydroxyethylcellulose, Potassium Cocoyl Glycinate, Potassium Cocoate, Oryza Sativa Rice Extract, Phyllostachys Pubescens Shoot Bark Extract, Panax Ginseng Root Extract, Aspergillus Ferment Extract Filtrate, Beta-Glucan, Butylene Glycol, Trehalose, Citric Acid, Cyclodextrin, Zanthoxylum Piperitum Fruit Extract, Pulsatilla Koreana Extract, Usnea Barbata Lichen Extract, Ethylhexylglycerin', 'Le Black Rice Moisture 5.5 Soft Cleansing Gel Haruharu WONDER est un gel nettoyant légèrement acide (pH 5.5) formulé avec des ingrédients d''origine naturelle extraits de la noix de coco qui permet un nettoyage en douceur et en profondeur et élimine les cellules mortes et les impuretés. Il est formulé avec de l''extrait de riz noir fermenté qui apporte une hydratation riche et aide à apaiser les peaux sensibles. Sa mousse fine et douce minimise l''irritation de la peau et nettoie en profondeur les impuretés sans endommager la barrière cutanée.', 100, 'ml', 'black-rice-moisture-5-5-soft-cleansing-gel', 'https://korean-skincare.fr/products/black-rice-moisture-5-5-soft-cleansing-gel', 'https://aurore-cdn.b-cdn.net/products/black-rice-moisture-5-5-soft-cleansing-gel.webp', 'Distribue une quantité suffisante de nettoyant sur tes mains mouillées pour faire le faire mousser. Applique soigneusement sur ton visage Rince abondamment à l''eau tiède.', 1415, '2026-05-07 17:37:40.09149+00', '2026-06-14 15:14:07.777+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4364-735d-862f-a4d2ce9fdb85', '__OWNER_ID__', 'Mugwort Cream', 'I''m From', 'moisturizer', 'jar', 'Artemisia Vulgaris, Propanediol, Cyclopentasiloxane, Glycerin, Cetyl Ethylhexanoate, Cyclohexasiloxane, Stearic Acid, Butyrospermum Parkii Butter, Butylene Glycol, Hydrogenated Lecithin, Alcool d''Arachidyle, Glucoside d''Arachidyle, Pinus Palustris Leaf Extract, Ulmus Davidiana Root Extract, Oenothera Biennis Flower Extract, Aqua, 1,2-Hexanediol, Caprylhydroxamic Acid, Acide Alkyl C14-28, Stearyl Alcohol, Behenyl Alcohol, Polyglycéryle-2 Stéarate, Glyceryl Stearate, Panthenol, Dipotassium Glycyrrhizate, Allantoin, Extrait de Résine de Boswellia Serrata, Ammonium Acryloyldimethyltaurate/VP Copolymer, Copolymère d''Acrylate d''Hydroxyéthyle/Sodium Acryloyldiméthyltaurate, Dimethiconol, Saccharomyces Ferment Filtrate, Lactobacillus Ferment, Saccharomyces Ferment Filtrate, Disodium EDTA, Polyglutamic Acid, Pueraria Lobata Root Extract, Huile d''Artemisia Vulgaris', 'La Mugwort Cream I''m From est un produit de soin à la fois délicat et puissant, formulé avec 73,55 % d''extrait d''armoise pour offrir une hydratation apaisante et redonner à la peau une douceur et une santé naturelles. Cette crème rafraîchissante pénètre rapidement comme un gel, procurant une hydratation intense sans laisser de résidu collant. Sa formule légère calme les irritations, purifie la peau et améliore le teint, ce qui la rend idéale pour les peaux sensibles. Avec des ingrédients nourrissants comme le beurre de karité et des extraits fermentés, cette crème permet à la peau de rester nette, radieuse et hydratée tout au long de l''année. Recommandé pour : Peaux sèches et sensibles, peaux normales à sèches.', 50, 'g', 'im-from-mugwort-cream', 'https://korean-skincare.fr/products/im-from-mugwort-cream', 'https://aurore-cdn.b-cdn.net/products/im-from-mugwort-cream.webp', 'Applique et étale délicatement sur ta peau lors de la dernière étape de ta routine beauté, en évitant le contour des yeux et de la bouche. Tapote légèrement pour faire pénétrer le produit dans ta peau.', 2695, '2026-05-07 17:37:40.196023+00', '2026-06-14 15:14:07.777+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4306-72d6-a95f-3d041002d586', '__OWNER_ID__', 'Black Rice Probiotics Barrier Essence', 'Haruharu Wonder', 'essence', 'bar', 'Aqua, Butylene Glycol, Helianthus Annuus Seed Oil, Caprylic/Capric Triglyceride, Hydrogenated Polyisobutene, Limnanthes Alba Seed Oil, Butylène Glycol Dicaprylate/Dicaprate, 1,2-Hexanediol, Phosphate de Cétyle de Potassium, Cetearyl Alcohol, Hydroxyacetophenone, Glycerin, Glyceryl Stearate, Oryza Sativa Extract, Extrait d''Écorce de Pousse de Phyllostachys Pubescens, Hydrogenated Lecithin, Polyglycéryl-10 Laurate, Polyglycéryl-3 Méthylglucose Distearate, Gomme de Xanthan, Filtrat de Fermentation de Galactomyces, Panthenol, Filtrat de Fermentation de Bifida, Aspergillus Ferment, Ethylhexylglycerin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Ceramide NP, Disodium EDTA, Pentylene Glycol, Tromethamine, Butyrospermum Parkii Butter, Phytostérols, Extrait de Lies d''Oryza Sativa, Panax Ginseng Root Extract, Stearic Acid, Palmitic Acid, Caprylyl Glycol, Squalane, Protéine de Blé Hydrolysée, Cyclodextrin, Arachidic Acid, Myristic Acid, Oleic Acid, Ceramide NP, Phytosphingosine, Cholesterol, Ceramide NP, Ceramide NP, Ceramide EOP', 'Améliore ta routine beauté avec la WONDER Black Rice Probiotics Barrier Essence Haruharu, une formule riche en nutriments conçue pour renforcer et rajeunir la barrière cutanée. Dotée d''un complexe de 5 céramides et d''un complexe de 5 acides gras, elle hydrate et lisse en profondeur tout en maintenant l''équilibre de l''hydratation. Infusée de filtrat de ferment Galactomyces pour améliorer l''élasticité de la peau et d''extrait de feuilles de riz noir recyclé pour ses bienfaits antioxydants et apaisants, cette essence produit des effets raffermissants et repulpants à chaque application. La texture légère et crémeuse s''absorbe sans effort, laissant la peau douce et hydratée sans effet collant. Recommandé pour : Peaux sèches et sensibles, peaux normales à sèches.', 120, 'ml', 'haruharu-wonder-black-rice-probiotics-barrier-essence', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-probiotics-barrier-essence', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-probiotics-barrier-essence.webp', 'Bien agiter avant utilisation. Applique une quantité modérée de produit sur tes mains et masse délicatement ton visage et ton cou. Tapote légèrement pour faciliter son absorption.', 2195, '2026-05-07 17:37:40.10204+00', '2026-06-14 15:14:07.777+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4308-7821-9a8d-1c83b1730d2b', '__OWNER_ID__', 'Black Rice Moisture Airfit Daily Sunscreen SPF50+ PA++++', 'Haruharu Wonder', 'moisturizer', 'jar', 'Aqua, Adipate De Dibutyle, Propanediol, Salicylate De Butyloctyle, Ethylhexyl Triazone, Acide Sulfonique De Dicamphor Terephthalylidène, Glycerin, Niacinamide, Tromethamine, Distearate De Polyglycéryl-3, 1,2-Hexanediol, Pentylene Glycol, Hydroxybenzoyl D''Hexyle Diéthylamino Benzoate, Cetearyl Alcohol, Caprylyl Méthicone, Polysilicone-15, Extrait De Stellaria Media (Stellaria), Extrait De Fleur D''Helianthus Annuus (Tournesol), Extrait De Fruit De Vaccinium Vitis-Idaea, Oryza Sativa Extract, Extrait De Fleur De Bellis Perennis (Marguerite), Houttuynia Cordata Extract, Huile De Son D''Oryza Sativa (Riz), Hydrogenated Lecithin, Polyméthylsilsesquioxane, Palmitic Acid, Butylene Glycol, Stearic Acid, Glyceryl Stearate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Phosphate De Cétyle De Potassium, Poly Acrylate D''Alkyle C10-30, Methylpropanediol, Carbomer, Ammonium Acryloyldimethyltaurate/VP Copolymer, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Citrate De Stéarate De Glycéryle, Ethylhexylglycerin, Adenosine, Polyéther-1, Myristic Acid, Gomme-1 De Biosaccharide, Tocopherol, Moringa Oleifera Seed Oil, Ceramide NP, Phytosphingosine, Phenethyl Alcohol, Sodium Chloride, Phosphate Disodique, Potassium Chloride, Potassium Phosphate', 'Adopte une protection solaire efficace avec l''écran solaire quotidien Black Rice Moisture Airfit SPF50+ PA++++ Haruharu WONDER. Cette crème solaire chimique offre une solution légère avec un puissant SPF50+ PA++++ à large spectre pour protéger ta peau des rayons UV nocifs sans aucune trace blanche. Infusé avec de l''extrait de riz noir hautement hydratant, cet écran solaire biologique à la texture de crème vient hydrater ta peau tout en lui apportant des bienfaits antioxydants. Recommandé pour : Peaux sensibles, normales, sèches.', 50, 'ml', 'haruharu-wonder-black-rice-moisture-airfit-daily-sunscreen-spf50-pa-1', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-moisture-airfit-daily-sunscreen-spf50-pa-1', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-moisture-airfit-daily-sunscreen-spf50-pa-1.webp', 'Applique en dernière étape de ta routine beauté. Étale et masse doucement sur ta peau, en évitant le contour des yeux et de la bouche. Renouvelle l''application si nécessaire tout au long de la journée pour une protection solaire maximale.', 1421, '2026-05-07 17:37:40.104397+00', '2026-06-14 15:14:07.778+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-430a-7d61-a86d-6a1b6ea6dd88', '__OWNER_ID__', 'Black Rice Bakuchiol Eye Cream', 'Haruharu Wonder', 'eye-cream', 'jar', 'Aqua, Glycerin, Helianthus Annuus Seed Oil, Caprylic/Capric Triglyceride, Niacinamide, 1,2-Hexanediol, Cetyl Alcohol, Cetearyl Alcohol, Alcools C14-22, Bakuchiol, Stearyl Alcohol, Carbomer, Glucoside Cétéarylique, Tromethamine, Butylene Glycol, Oryza Sativa Extract, Cetyl Palmitate, Glucoside Alkyle C12-20, Copolymère Acrylate de Sodium/Acryloyldiméthyl Taurate de Sodium, Palmitate de Sorbitane, Sorbitan Olivate, Polyisobutene, Myristyl Alcohol, Extrait d''écorce de Pousses de Phyllostachys Pubescens, Zanthoxylum Piperitum Fruit Extract, Extrait d''Usnea Barbata, Extrait de Pulsatilla Koreana, Aspergillus Ferment, Ethylhexylglycerin, Panax Ginseng Root Extract, Cyclodextrin, Adenosine, Alcool Laurylique, Sodium Hyaluronate, Disodium EDTA, Glucoside de Capryly/Capryl, Oléate de Sorbitane, Glucose, Acides Aminés de Blé, Gomme de Natto, Pentylene Glycol, Madecassoside', 'Rajeunis et revitalise la peau délicate du contour de tes yeux avec la Haruharu WONDER Black Rice Bakuchiol Eye Cream. Infusée d''un puissant mélange de bakuchiol et d''extrait de riz noir hydratant, cette crème douce pour les yeux cible les rides, améliore l''élasticité de la peau et favorise un teint plus sain. Enrichie d''extraits de pousses de bambou pour un soin antioxydant, cette crème contient également de la gomme de Cica et de Natto pour lisser les ridules autour des paupières. Tous ses ingrédients sont certifiés EWG Green Grade et formulés à l''aide de l''Ultra-Deep Technology™ pour une diffusion efficace de ses composants actifs. Cette crème pour les yeux pénètre profondément dans la peau et laisse une texture laiteuse et légère qui est absorbée rapidement sans aucune sensation collante. Recommandé pour : Peaux sensibles, peaux sèches, tous types de peaux.', 20, 'ml', 'haruharu-wonder-black-rice-bakuchiol-eye-cream', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-bakuchiol-eye-cream', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-bakuchiol-eye-cream.webp', 'Applique une quantité appropriée du produit sur la zone du contour des yeux. Tapote délicatement pour faire pénétrer le produit dans ta peau et favoriser son absorption.', 2195, '2026-05-07 17:37:40.106714+00', '2026-06-14 15:14:07.778+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-430d-7450-8262-155e7525ab56', '__OWNER_ID__', 'Black Rice 10 Hyaluronic Cream', 'Haruharu Wonder', 'moisturizer', 'jar', 'Eau D.I, Propanediol, Olivate de Cétéaryle, Sorbitan Olivate, Glycerin, Huile de Carthame (Carthamus Tinctorius), Stéarate de Polyglycéryl-3, Alcool de Cétéaryle, Oryza Sativa Extract, Undécylénate d''Heptyle, Caprylic/Capric Triglyceride, Oenothera Biennis Oil, Extrait d''Écorce de Pousses de Phyllostachys Pubescens, Aspergillus Ferment, Extrait de Racine de Ginseng Panax, Cyclodextrin, Hyaluronic Acid, Extrait de Pulsatilla Koreana, Zanthoxylum Piperitum Fruit Extract, Extrait d''Usnée Barbue (Lichen), Cetyl Palmitate, Sodium Phytate, Palmitate de Sorbitan, 1,2-Hexanediol, Alcohol, Butylene Glycol, Lavandula Angustifolia Oil', 'La Haruharu WONDER Black Rice Hyaluronic Cream est un soin hydratant étonnant composé à 95 % d''ingrédients d''origine naturelle. Son ingrédient phare est le riz noir fermenté, un ingrédient plein de nutriments, riche en antioxydants et anti-âge. Le riz noir contient une forte concentration de polyphénols et de flavonoïdes, qui protègent la peau contre les radicaux libres et encouragent la formation de nouvelles cellules cutanées. Ajoute à cela de l''acide hyaluronique profondément hydratant, du ginseng rouge rajeunissant, de l''huile d''onagre et de lavande apaisante, et tu obtiens une crème raffermissante et hydratante parfaite pour ta peau.', 50, 'ml', 'haruharu-wonder-black-rice-10-hyaluronic-cream', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-10-hyaluronic-cream', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-10-hyaluronic-cream.webp', 'Appliquer une quantité suffisante de produit sur l''ensemble de ton visage. Masse délicatement pour faciliter l''absorption.', 1550, '2026-05-07 17:37:40.109148+00', '2026-06-14 15:14:07.778+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4312-7542-8a35-dd87dacc3e63', '__OWNER_ID__', 'Black Rice Triple AHA Gentle Cleansing Gel', 'Haruharu Wonder', 'cleanser', 'tube', 'Aqua, Glycerin, Coco-Betaine, Sodium Chloride, Pentylene Glycol, Propanediol, 1,2-Hexanediol, Gomme Xanthane, Betaine, Glycinate de Cocoyle de Potassium, Hydroxyéthylcellulose, Ethylhexylglycerin, Citric Acid, Acide Tartrique, Mandelic Acid, Oryza Sativa Extract, Extrait d''écorce de Pousses de Phyllostachys Pubescens, Butylene Glycol, Zanthoxylum Piperitum Fruit Extract, Extrait de Pulsatilla Koreana, Extrait d''Usnea Barbata, Aspergillus Ferment, Panax Ginseng Root Extract, Cyclodextrin, Beta-Glucan', 'Profite de la pureté rafraîchissante du Black Rice Triple AHA Gentle Cleansing Gel Haruharu WONDER, conçu avec soin pour nettoyer et exfolier ta peau, dévoilant ainsi un teint radieux. Infusée d''extraits de riz noir fermenté et d''écorce de pousse de bambou, ainsi que de bétaïne et de glycérine, sa formule vegan au pH équilibré assure un nettoyage en profondeur mais en douceur, laissant la peau hydratée après le lavage. Grâce à la puissance du triple AHA, les cellules mortes et l''excès de sébum sont éliminés sans effort, dévoilant des pores plus lisses et dégagés. Recommandé pour : Sans risque pour l''acné fongique, soin des pores, tous types de peaux.', 100, 'ml', 'haruharu-wonder-black-rice-triple-aha-gentle-cleansing-gel', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-triple-aha-gentle-cleansing-gel', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-triple-aha-gentle-cleansing-gel.webp', 'En utilisant une petite quantité d''eau, fais mousser et masse délicatement ta peau, en évitant l''intérieur des yeux. Rince abondamment à l''eau tiède.', 1695, '2026-05-07 17:37:40.114143+00', '2026-06-14 15:14:07.779+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4317-7653-8055-d9efc78f22b4', '__OWNER_ID__', 'Black Rice Pure Mineral Relief Daily Sunscreen SPF50+ PA++++', 'Haruharu Wonder', 'moisturizer', 'jar', 'Aqua, Zinc Oxide, Cyclohexasiloxane, Salicylate de Butyloctyle, Propanediol, Caprylate de Propylheptyle, Méthicone de Caprylyle, Diméthicone Polydiméthylsiloxyéthyl de Polyglycéryl-3, Copolymère réticulé de Méthacrylate de Méthyle, Niacinamide, Triméthicone de Méthyle, Isododecane, Extrait de Stellaria Media, Extrait de Fleur de Helianthus Annuus, Extrait de Fruit de Vaccinium Vitis-Idaea, Oryza Sativa Extract, Extrait de Fleur de Bellis Perennis, Houttuynia Cordata Extract, Huile de Son d''Oryza Sativa, Sodium Hyaluronate, Hydrogenated Lecithin, Hectonite de Disteardimonium, Magnesium Sulfate, Triéthoxycaprylylsilane, Butylene Glycol, 1,2-Hexanediol, Dipolyhydroxystéarate de Polyglycéryl-2, Polyméthylsilsesquioxane, Diméthicone Polydiméthylsiloxyéthyl de Lauryl Polyglycéryl-3, Glyceryl Caprylate, Caprylyl Glycol, Ethylhexylglycerin, Tocopherol, Glycerin, Moringa Oleifera Seed Oil, Ceramide NP, Phytosphingosine, Phenethyl Alcohol, Sodium Chloride, Disodium Phosphate, Potassium Chloride, Potassium Phosphate', 'Découvre une protection solaire à la fois délicate et efficace avec la Black Rice Pure Mineral Relief Daily Sunscreen SPF50+ PA++++ Haruharu WONDER. Conçue pour les peaux sensibles, cette crème solaire minérale non nanométrique est dotée d''un indice de protection SPF50+ PA++++ qui bloque les UV à large spectre, protégeant ainsi la peau des rayons nocifs. Enrichie d''huile de son de riz nourrissante et d''extrait de Houttuynia Cordata apaisant, elle hydrate et calme la peau, laissant derrière elle un fini satiné. Exempt de parfums artificiels, de colorants et d''alcools desséchants, cet écran solaire léger offre une hydratation et une protection sans irritation. Présenté dans un tube-pompe pratique pour une application hygiénique, c''est la solution idéale pour une peau dorlotée et protégée au quotidien. Recommandé pour : Peaux sensibles, peaux sèches, tous types de peaux.', 50, 'ml', 'haruharu-wonder-black-rice-pure-mineral-relief-daily-sunscreen', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-pure-mineral-relief-daily-sunscreen', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-pure-mineral-relief-daily-sunscreen.webp', 'Applique lors de la dernière étape de ta routine beauté. Étale délicatement et masse sur ta peau, en évitant le contour des yeux et de la bouche. Renouvelle l''application si nécessaire tout au long de la journée pour une protection solaire maximale.', 1855, '2026-05-07 17:37:40.119206+00', '2026-06-14 15:14:07.779+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4366-7979-987e-1db5cdc5d9af', '__OWNER_ID__', 'Ginseng Serum', 'I''m From', 'serum', 'dropper', 'Aqua, Extrait de Ginseng Rouge, Butylene Glycol, Betaine, 1,2-Hexanediol, Camellia Sinensis Leaf Extract, Glycerin, Huile de Graine de Panax Ginseng, Glycyrrhiza Uralensis Root Extract, Extrait de Racine de Paeonia Albiflora, Extrait de Racine d''Angelica Gigas, Extrait de Racine de Rheum Palmatum, Extrait de Racine d''Angelica Pubescens, Extrait de Schizonepeta Tenuifolia, Phellodendron Amurense Bark Extract, Hydroxyéthylcellulose, Cyclopentasiloxane, Dimethiconol, Bis-PEG-18 Méthyl Éther Diméthyl Silane, Ethoxydiglycol, Copolymère d''Acrylates/C10-30 Alkyla Acrylate, Tromethamine, PEG-60 Huile de Ricin Hydrogénée, Ethylhexylglycerin, Glycosaminoglycanes Hydrolysées, Hyaluronic Acid, Polyacrylate de Glycéryl, Adenosine, Disodium EDTA, Parfum', 'Le Ginseng Serum I''m From est un sérum calmant à base de ginseng rouge et d''huile de graines de ginseng Panax pour nourrir et hydrater la peau. L''extrait de ginseng rouge hautement concentré confère de l''élasticité aux peaux relâchées et fatiguées. Le ginseng réchauffe efficacement la peau, améliorant la circulation sanguine et facilitant la pénétration des autres nutriments dans les couches plus profondes du derme. L''acide hyaluronique sature les cellules de l''épiderme d''hydratation et lisse les rides. L''extrait de thé vert combat l''inflammation et l''irritation, tandis que l''extrait de pivoine réduit la pigmentation et apporte aux peaux ternes une teinte fraîche et agréable.', 30, 'ml', 'im-from-ginseng-serum', 'https://korean-skincare.fr/products/im-from-ginseng-serum', 'https://aurore-cdn.b-cdn.net/products/im-from-ginseng-serum.webp', 'Après avoir nettoyé et préparé ta peau avec un tonique. Applique délicatement une petite quantité de produit. Masse délicatement pour une meilleure absorption.', 2836, '2026-05-07 17:37:40.198476+00', '2026-06-14 15:14:07.779+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-430f-79a3-8bc4-09655fa8ce38', '__OWNER_ID__', 'Black Rice 10 Hyaluronic Cream Unscented', 'Haruharu Wonder', 'moisturizer', 'jar', 'Aqua, Caprylic/Capric Triglyceride, Carthamus Tinctorius Seed Oil, Oenothera Biennis Oil, Propanediol, Sorbitan Olivate, Olivate de Cetearyl, Stéarate de Polyglycéryl-3, Oryza Sativa Extract, Alcool Cetearyl, Glycerin, Glycérides d''Huile de Graine de Tournesol, Aspergillus Ferment, Zanthoxylum Piperitum Fruit Extract, Extrait d''Usnea Barbata, Extrait de Pulsatilla Koreana, Extrait d''Écorce de Pousse de Phyllostachys Pubescens, Cetyl Palmitate, Gluconate de Sodium, Palmitate de Sorbitan, 1,2-Hexanediol, Gomme Xanthane, Panax Ginseng Root Extract, Sodium Hyaluronate, Butylene Glycol, Potassium Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Hydrolyzed Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Pentylene Glycol, Cyclodextrin, Sodium Hyaluronate Crosspolymer, Sodium Acetylated Hyaluronate', 'Offre à ta peau une étreinte rajeunissante avec la Haruharu WONDER Black Rice 10 Hyaluronic Cream Unscented, une luxueuse crème hydratante enrichie de 95 % d''ingrédients d''origine naturelle. Infusée d''un puissant mélange d''extrait de riz noir, d''acide hyaluronique et d''huile d''onagre, sa formule hydrate et revitalise la peau en profondeur tout en favorisant la régénération cellulaire. Conçue avec un acide hyaluronique de poids moléculaire multiple, elle offre une hydratation complète, laissant la peau rebondie et résistante. Avec une teneur accrue en huile d''onagre et en huile de graines de carthame, elle renforce la barrière cutanée, améliorant ainsi l''élasticité et la souplesse de la peau. Enrichie en extrait de riz noir fermenté et en extrait d''écorce de pousses de bambou, elle calme et apaise les peaux sensibles, garantissant une texture plus douce et légère avec une absorption rapide et un fini rafraîchissant. Recommandé pour : Peaux sèches, peaux sensibles, tous types de peaux.', 50, 'ml', 'haruharu-wonder-black-rice-10-hyaluronic-cream-unscented', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-10-hyaluronic-cream-unscented', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-10-hyaluronic-cream-unscented.webp', 'Applique et étale délicatement sur ta peau lors de la dernière étape de ta routine beauté, en évitant le contour des yeux et de la bouche. Tapote légèrement pour faire pénétrer le produit dans ta peau.', 1795, '2026-05-07 17:37:40.111391+00', '2026-06-14 15:14:07.779+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43a7-7c4c-a794-6c52841171be', '__OWNER_ID__', 'Rich Moist Soothing Cream', 'Dear Klairs', 'moisturizer', 'jar', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, Cyclopentasiloxane, Cetyl Alcohol, Glyceryl Stearate, Cetyl Ethylhexanoate, Butyrospermum Parkii Butter, Simmondsia Chinensis Seed Oil, Stearic Acid, Butylene Glycol, Sesquioleate de sorbitane, Microcrystalline Wax, Betaine, Stéarate de sorbitane, PEG-100 Stearate, Dimethicone, Arginine, Carbomer, Chlorphenesin, Tocopheryl Acetate, Paeonia Suffruticosa Root Extract, Extrait de fruit d''Illicium verum (anis), Extrait de fleur de Nelumbium speciosum (lotus), Extrait de fruit de Citrus paradisi (pamplemousse), Extrait de racine de Scutellaria baicalensis, Citric Acid, Beta-Glucan, Hydrogenated Lecithin, Portulaca Oleracea Extract, 1,2-Hexanediol, Centella Asiatica Extract, Aloe Barbadensis Leaf Extract, Althaea Rosea Flower Extract, Sodium Hyaluronate, Ceramide NP, Disodium EDTA, Polyquaternium-51, Extrait d''Apium graveolens (céleri), Extrait de feuille de Brassica rapa (navet), Oryza Sativa Extract, Extrait de feuille de Brassica oleracea capitata (chou), Triphosphate d''adénosine disodique, Daucus Carota Sativa Root Extract, Brassica Oleracea Italica Extract, Extrait de fruit/feuille/tige de Solanum lycopersicum (tomate), Lysine', 'La Rich Moist Soothing Cream Dear Klairs est une crème hydratante riche qui apporte une hydratation immédiate et durable à la peau. Sa formule nourrissante est enrichie en bêta-glucane dérivé de la levure, en huile de jojoba et en céramides pour renforcer la barrière protectrice de la peau, traiter les peaux sèches et irritées, et améliorer ses capacités naturelles de régénération cellulaire. Convient à tous les types de peau, en particulier aux peaux sensibles.', 80, 'ml', 'dear-klairs-rich-moist-soothing-cream', 'https://korean-skincare.fr/products/dear-klairs-rich-moist-soothing-cream', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-rich-moist-soothing-cream.webp', 'Masse délicatement l''ensemble de ton visage et tapote pour une meilleure absorption.', 2640, '2026-05-07 17:37:40.263602+00', '2026-06-14 15:14:07.789+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-436d-78a7-8832-22804efc5238', '__OWNER_ID__', 'Licorice Calming Cream', 'I''m From', 'moisturizer', 'jar', 'Glycyrrhiza Uralensis Root Extract, Aqua, Propanediol, Glycerin, Phényl Triméthicone, Caprylic/Capric Triglyceride, 1,2-Hexanediol, Extrait de Chlorella Vulgaris, Glycyrrhiza Glabra Root Extract, Extrait de Racine de Cynanchi, Althaea Rosea Flower Extract, Pentylene Glycol, Panthenol, Ammonium Acryloyldimethyltaurate/VP Copolymer, Copolymère d''Acrylate d''Hydroxyéthyle/Sodium Acryloyldiméthyltaurate, Vinyl Diméthicone, Crosspolymère de Diméthicone/Vinyl Diméthicone, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Glucose, Tromethamine, Butylene Glycol, Dimethiconol, Dipotassium Glycyrrhizate, Fructooligosaccharides, Fructose, Microcrystalline Cellulose, Ethylhexylglycerin, Copolymère de Glycéryle Acrylate/Acide Acrylique, Hydrogenated Lecithin, Sorbitan Isostearate, Sodium Phytate, Cellulose Gum, Silica, Cétéaryl Olivate, Ceramide NP, Sorbitan Olivate, Tocopherol, Kanzou Furabonoido, Gomme Xanthane', 'La Licorice Calming Cream I''m From est une crème hydratante apaisante contenant 58 % d''exosomes de réglisse et 100 millions de flavonoïdes de réglisse pour calmer les peaux irritées et sensibles tout en les hydratant en profondeur pendant 24 heures. Cette crème anti-inflammatoire et anti-allergique réduit les rougeurs, les cicatrices de pigmentation et d''acné, laissant ta peau radieuse et unifiée. Infusée d''extrait de réglisse soluble dans l''huile, elle éclaircit la peau et renforce la barrière cutanée, ce qui la rend idéale pour les peaux sensibles et à tendance acnéique. Cliniquement testée en termes de non comédogénicité et d''irritation cutanée, cette crème est parfaite pour obtenir une peau lisse, hydratée et lumineuse. Recommandé pour : Peaux à tendance acnéique, peaux sensibles, peaux sèches, tous types de peaux.', 50, 'ml', 'im-from-licorice-calming-cream', 'https://korean-skincare.fr/products/im-from-licorice-calming-cream', 'https://aurore-cdn.b-cdn.net/products/im-from-licorice-calming-cream.webp', 'Applique une quantité appropriée de produit sur peau propre lors de la dernière étape de ta routine beauté, en évitant le contour des yeux et de la bouche. Tapote délicatement pour faire pénétrer le produit dans ta peau.', 2795, '2026-05-07 17:37:40.205402+00', '2026-06-14 15:14:07.78+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-431a-7024-b20a-b0cb23e6344b', '__OWNER_ID__', 'Black Rice Hyaluronic Anti-Wrinkle Serum', 'Haruharu Wonder', 'serum', 'dropper', 'Aqua, Glycerin, Lecithin, Caprylic/Capric Triglyceride, Camellia Japonica Seed Oil, Hydrogenated Lecithin, Helianthus Annuus Seed Oil, Oryza Sativa Extract, Extrait D’Écorce De Pousses De Phyllostachys Pubescens, Aspergillus Ferment, Hyaluronic Acid, Panax Ginseng Root Extract, Cyclodextrin, Gomme De Sclérotium, Alcools C12-16, Palmitic Acid, Extrait De Ferment D’Alteromonas, Extrait D’Usnea Barbata, Zanthoxylum Piperitum Fruit Extract, Extrait De Pulsatilla Koreana, Beta-Glucan, 1,2-Hexanediol, Stérols De Glycine Soja, Behenyl Alcohol, Simmondsia Chinensis Seed Oil, Glyceryl Stearate, Sodium Phytate, Tocopherol, Adenosine, Phenethyl Alcohol, Butylene Glycol, Alcohol, Lavandula Angustifolia Oil, Linalool, Limonene', 'Le Black Rice Hyaluronic Anti-Wrinkle Serum Haruharu WONDER est parfait pour ceux qui sont à la recherche d''une hydratation et d''une nutrition intenses. Le riz noir fermenté riche en antioxydants et l''acide hyaluronique ultra-hydratant s''associent pour faire de ce sérum laiteux l''étape parfaite de ta routine anti-âge, te laissant une peau rebondie et d''apparence plus ferme. Il contient également de l''extrait de ginseng rouge rajeunissant, de la bétaïne stimulant le collagène et des huiles botaniques hydratantes.', 50, 'ml', 'haruharu-wonder-black-rice-hyaluronic-anti-wrinkle-serum', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-hyaluronic-anti-wrinkle-serum', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-hyaluronic-anti-wrinkle-serum.webp', 'Applique une quantité suffisante après avoir nettoyé ton visage et appliqué un tonique. Tapote délicatement pour une meilleure absorption.', 2248, '2026-05-07 17:37:40.121815+00', '2026-06-14 15:14:07.78+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4330-7756-abda-07c7ac5be1d4', '__OWNER_ID__', 'Black Rice Hyaluronic Botanical 2GF Wonderful Ampoule', 'Haruharu Wonder', 'serum', 'dropper', 'Aqua, Pentylene Glycol, Propanediol, Glycerin, Oryza Sativa Extract, Butylene Glycol, Ammonium Acryloyldimethyltaurate/VP Copolymer, 1,2-Hexanediol, Zanthoxylum Piperitum Fruit Extract, Extrait de Pulsatilla Koreana, Extrait d''Usnea Barbata, Aspergillus Ferment, Cyclodextrin, Panax Ginseng Root Extract, Extrait d''Écorce de Pousse de Phyllostachys Pubescens, Sodium Hyaluronate, Gomme Xanthane, Dipotassium Glycyrrhizate, Adenosine, Disodium EDTA, Mannitol, Sodium Chloride, Sh-Oligopeptide-2 de Riz, Extrait de Chlorella Vulgaris, Madecassoside, Disodium Phosphate, Sh-Polypeptide-1 de Riz, Extrait de Cynanchi Radix, Sodium Phosphate, Potassium Phosphate, Potassium Chloride', 'Profite du pouvoir de transformation de la Haruharu Wonder Black Rice Hyaluronic Botanical 2GF Wonderful Ampoule, un puissant élixir enrichi d''EGF et de FGF pour stimuler la synthèse du collagène et reconstituer l''hydratation de la peau. Conçue avec 2000 ppm d''extrait de riz noir fermenté et d''extrait d''écorce de pousses de Phyllostachys Pubescens fermenté, cette formule riche en antioxydants protège la peau contre les facteurs de stress environnementaux tout en favorisant un teint radieux. Enrichie d''extrait de dompte-venin noir apaisant et de madécassoside hydratant, elle soigne les peaux sensibles, les laissant revitalisées et hydratées en profondeur. Recommandé pour : Sans risque pour l''acné fongique, peaux sèches, peaux sensibles, tous types de peaux.', 30, 'ml', 'haruharu-wonder-black-rice-hyaluronic-botanical-2gf-wonderful-ampoule', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-hyaluronic-botanical-2gf-wonderful-ampoule', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-hyaluronic-botanical-2gf-wonderful-ampoule.webp', 'Commence par nettoyer et tonifier ta peau. Applique 1 à 3 gouttes sur ta peau, en évitant le contour des yeux et de la bouche. Masse délicatement et tapote pour faire pénétrer dans ta peau jusqu''à absorption complète.', 3895, '2026-05-07 17:37:40.144323+00', '2026-06-14 15:14:07.78+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4321-74d6-9831-d9a59634f740', '__OWNER_ID__', 'Centella 4% TXA Dark Spot Go Away Serum', 'Haruharu Wonder', 'serum', 'dropper', 'Aqua, Propanediol, Niacinamide, Tranexamic Acid, Butylene Glycol, 1,2-Hexanediol, Pyrus Communis Fruit Extract, Sodium Polyacryloyldimethyl Taurate, Ethylhexylglycerin, Laurate de Polyglycéryl-10, Madecassoside, Centella Asiatica Extract, Asiaticoside, Ascorbic Acid, Acide Asiatique, Acide Madécassique, Sodium Ascorbyl Phosphate', 'Profite du pouvoir de transformation du Centella 4% TXA Dark Spot Go Away Serum Haruharu WONDER, un puissant sérum vegan conçu pour combattre l''hyperpigmentation et les taches brunes tout en améliorant le teint et la texture de la peau. Infusé d''acide tranexamique et de niacinamide, ce sérum agit rapidement pour atténuer l''apparence de l''hyperpigmentation, illuminer les peaux ternes et affiner les irrégularités de la texture. Enrichi du complexe Centella et d''acide ascorbique, il apaise les irritations et revitalise les peaux fatiguées, laissant derrière lui un fini hydraté et non collant. Testé dermatologiquement et adapté à tous les types de peau, ce sérum est exempt de sulfates, d''alcool desséchant, de parfums artificiels et de parabènes, ce qui garantit un traitement à la fois délicat et efficace pour ta peau. Recommandé pour : Hyperpigmentation, peaux sensibles, tous types de peaux.', 30, 'ml', 'haruharu-wonder-centella-4-txa-dark-spot-go-away-serum', 'https://korean-skincare.fr/products/haruharu-wonder-centella-4-txa-dark-spot-go-away-serum', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-centella-4-txa-dark-spot-go-away-serum.webp', 'Commence par nettoyer ta peau et appliquer un tonique. Applique 1 à 3 gouttes sur ta peau, en évitant le contour des yeux et de la bouche. Masse délicatement et tapote pour faire pénétrer dans ta peau jusqu''à absorption complète.', 2395, '2026-05-07 17:37:40.129146+00', '2026-06-14 15:14:07.78+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-431e-7d5c-8bc2-6f7c6a6b779c', '__OWNER_ID__', 'Black Bamboo Nourishing Calming Hand & Nail Cream', 'Haruharu Wonder', 'hand-cream', 'jar', 'Aqua, Beurre de Graine d''Astrocaryum Murumuru, Ethylhexyl Palmitate, Glycerin, Olivate de Cetearyl, Cocos Nucifera Oil, 1,2-Hexanediol, Sorbitan Olivate, Stearyl Alcohol, Amylopectine, Bambusa Vulgaris Water, Extrait d''Écorce de Pousse de Phyllostachys Pubescens, Panthenol, Tocopherol, Palmitic Acid, Cetyl Alcohol, Butylene Glycol, Glyceryl Stearate, Distearate de Polyglycéryl-3, Extrait de Feuille de Phyllostachys Nigra, Sodium Polyacryloyldimethyl Taurate, Carbomer, Tromethamine, Polydecène Hydrogéné, Allantoin, Ethylhexylglycerin, Stéarate de Glycéryl Citrate, Disodium EDTA, Tridéceth-10, Myristic Acid, Stearic Acid, Myristyl Alcohol, Alcool Laurique, Aspergillus Ferment, Extrait d''Usnea Barbata, Zanthoxylum Piperitum Fruit Extract, Extrait de Pulsatilla Koreana, Parfum, Citronellol, Geraniol, Limonene, Linalool, Citral', 'Dis adieu aux mains sèches et craquelées et aux ongles cassants avec la WONDER Black Bamboo Nourishing Calming Hand & Nail Cream Haruharu. Infusée d''ingrédients puissants comme l''extrait de feuilles de bambou noir, l''eau de bambou et l''extrait de pousses de bambou fermenté, cette crème apporte une vague d''hydratation et de nutriments à ta peau et à tes ongles. Formulée avec du beurre de murumuru, de l''huile de noix de coco et du tocophérol, elle renforce la barrière cutanée et améliore l''élasticité de la peau, laissant tes mains veloutées et tes ongles fortifiés.', 50, 'ml', 'haruharu-wonder-black-bamboo-nourishing-calming-hand-nail-cream', 'https://korean-skincare.fr/products/haruharu-wonder-black-bamboo-nourishing-calming-hand-nail-cream', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-bamboo-nourishing-calming-hand-nail-cream.webp', 'Distribue une quantité modérée de la crème. Applique-la sur tes mains et masse délicatement pour une meilleure absorption.', 1195, '2026-05-07 17:37:40.126687+00', '2026-06-14 15:14:07.781+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4329-7ad3-9eea-d9cf4c66f630', '__OWNER_ID__', 'Black Rice Night Knight Retinol Serum', 'Haruharu Wonder', 'serum', 'dropper', 'Aqua, Caprylic/Capric Triglyceride, Hydrogenated Polyisobutene, Glycerin, Aqua, Glycerin, Caprylic/Capric Triglyceride, Aqua, Retinol, Polyglyceryl-10 Stearate, Hydrogenated Lecithin, Glyceryl Stearate, Polyglyceryl-2 Stearate, Dipropylene Glycol, Stearyl Alcohol, Hydroxyacetophenone, Caprylyl Glycol, Helianthus Annuus Sunflower Seed, 1,2-Hexanediol, C14-22 Alcohols, C12-20 Alkyl Glucoside, Glucose, Aqua, Aqua, Oryza Sativa Rice Extract, Aspergillus Ferment, Panax Ginseng Root Extract, Butylene Glycol, 1,2-Hexanediol, Cyclodextrin, Bakuchiol, Potassium Cetyl Phosphate, Aqua, Phyllostachys Pubescens Shoot Bark Extract, Aspergillus Ferment, 1,2-Hexanediol, Arginine, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Disodium EDTA, Aqua, Ethylhexylglycerin, Xanthan Gum, Adenosine, Ceramide NP', 'Le Black Rice Night Knight Retinol Serum Haruharu WONDER est un soin anti-âge puissant mais doux. Formulé à base de rétinol encapsulé et de bakuchiol naturel, ce sérum agit pendant la nuit pour affiner le grain de peau, réduire l''apparence des ridules et redonner à la peau son éclat de jeunesse. Enrichi en céramide NP et en extrait de riz noir riche en nutriments, il hydrate en profondeur et renforce la barrière cutanée pour un teint repulpé et résistant. Sa formule vegan est non irritante et convient à tous les types de peaux, y compris les peaux sensibles. Recommandé pour : Tous types de peaux.', 20, 'ml', 'haruharu-wonder-black-rice-night-knight-retinol-serum', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-night-knight-retinol-serum', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-night-knight-retinol-serum.webp', 'Le soir, applique une noisette de produit sur peau nettoyée et tonifiée, en évitant le contour des yeux et des lèvres. Utilise un écran solaire pendant la journée lorsque tu utilises ce produit, car le rétinol peut augmenter la sensibilité au soleil. Commence par appliquer 1 à 2 fois par semaine, puis augmente progressivement la fréquence jusqu''à une utilisation quotidienne, si ta peau le tolère. Avertissement : À utiliser uniquement le soir.', 2185, '2026-05-07 17:37:40.137544+00', '2026-06-14 15:14:07.781+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-432b-7eef-b394-2b385a5e851e', '__OWNER_ID__', 'Centella 3% PHA Gentle Liquid Exfoliating Serum', 'Haruharu Wonder', 'exfoliant', 'jar', 'Aqua, Eau de Fruit de Citrus Aurantium Dulcis, Gluconolactone, Butylene Glycol, 1,2-Hexanediol, Caprylyl Glycol, Sodium Hyaluronate, Arginine, Centella Asiatica Extract, Saccharomyces Ferment Filtrate, Ethylhexylglycerin, Pentylene Glycol, Pueraria Lobata Root Extract, Pinus Palustris Leaf Extract, Ulmus Davidiana Root Extract, Extrait de Racine d''Oenothera Biennis, Ectoin, Acide Asiatique, Asiaticoside, Acide Madécassique, Madecassoside', 'Offre à ta peau une exfoliation douce mais efficace avec le Haruharu WONDER Centella 3% PHA Gentle Liquid Exfoliating Serum. Infusé avec 100 000 ppm d''eau d''orange certifiée COSMOS et de PHA, ce sérum élimine délicatement les cellules mortes et les impuretés, dévoilant un teint clair et éclatant. Enrichi en extrait de cica, il apaise et fortifie les peaux sensibles, tandis que l''Anti-Sébum P contrôle l''excès de brillance. Grâce à sa formule vegan et à l''extrait de Centella Asiatica qui renforce la barrière cutanée, ce sérum convient à tous les types de peau. Recommandé pour : Sans risques pour l''acné fongique, tous types de peaux.', 120, 'ml', 'haruharu-wonder-centella-3-pha-gentle-liquid-exfoliating-serum', 'https://korean-skincare.fr/products/haruharu-wonder-centella-3-pha-gentle-liquid-exfoliating-serum', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-centella-3-pha-gentle-liquid-exfoliating-serum.webp', 'Applique 1 à 3 gouttes sur la peau et masse délicatement jusqu''à absorption complète. *Utilise 3 fois maximum par semaine', 2150, '2026-05-07 17:37:40.139774+00', '2026-06-14 15:14:07.781+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6558-7f2b-af95-01d2713c78ca', '__OWNER_ID__', 'Nuxe Huile Prodigieuse® Or 100ml', 'Nuxe', 'hair-oil', 'bottle', 'Coco-Caprylate/Caprate, Macadamia Integrifolia Seed Oil, Dicaprylyl Ether, Caprylic/Capric Triglyceride, Prunus Amygdalus Dulcis Oil, CORYLUS AVELLANA (HAZELNUT) SEED OIL, CI 77019, CAMELLIA OLEIFERA SEED OIL, Parfum, Camellia Japonica Seed Oil, CASTOR OIL/IPDI COPOLYMER, Titanium Dioxide, Argania Spinosa Kernel Oil, Borago Officinalis Seed Oil, Tocopherol, CI 77491, Helianthus Annuus Seed Oil, Tocopheryl Acetate, Rosmarinus Officinalis Leaf Extract, POLYGLYCERYL-3 DIISOSTEARATE, Aqua, Ascorbic Acid, Solanum Lycopersicum Fruit Extract, Linalool, Limonene, Citronellol, GERANIOL. [N2213/C]', '', 100, 'ml', 'nuxe-huile-prodigieuse-or-100ml-261073', 'https://www.atida.fr/nuxe-huile-prodigieuse-or-vaporisateur-100ml.html', 'https://aurore-cdn.b-cdn.net/products/nuxe-huile-prodigieuse-or-100ml-261073.webp', '', 2846, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.781+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4337-7497-ac43-d628002086f8', '__OWNER_ID__', 'Centella 5% Niacinamide Radiance Gel Cream', 'Haruharu Wonder', 'moisturizer', 'jar', 'Aqua, Niacinamide, Propanediol, Centella Asiatica Leaf Water, Glycerin, Dicaprylate / Dicaprate de Butylène Glycol, Squalane, 1,2-Hexanediol, Olivate de Cétyle, Panthenol, Ammonium Acryloyldimethyltaurate/VP Copolymer, Sorbitan Olivate, Carbomer, Gomme de Sclérote, Tromethamine, Helianthus Annuus Seed Oil, Gomme Xanthane, Madecassoside, Ethylhexylglycerin, Disodium EDTA, Xylitol, Ascorbic Acid', 'Retrouve un teint éclatant et uniforme avec le WONDER Centella 5% Niacinamide Radiance Gel Haruharu, un gel-crème léger et hydratant conçu pour estomper les taches brunes, minimiser les ridules et renforcer la barrière cutanée. Infusée de 5 % de niacinamide (vitamine B3) et d''acide ascorbique (vitamine C), cette formule illumine, lisse et protège la peau tout en prévenant l''apparition de nouvelles hyperpigmentations. Un mélange d''eau de feuille de Centella Asiatica, de squalane et de panthénol assure une hydratation durable, gardant la peau pulpeuse et souple sans la rendre grasse. Sa texture vegan à absorption rapide garantit un fini doux et frais, ce qui la rend idéale pour les peaux sensibles à la recherche d''un éclat sain et naturel. Recommandé pour : Tous types de peaux.', 90, 'g', 'haruharu-wonder-centella-5-niacinamide-radiance-gel-cream', 'https://korean-skincare.fr/products/haruharu-wonder-centella-5-niacinamide-radiance-gel-cream', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-centella-5-niacinamide-radiance-gel-cream.webp', 'Applique une quantité suffisante de produit sur ton visage et ton cou, en évitant le contour des yeux et de la bouche. Masse délicatement ta peau, puis fais pénétrer le produit en tapotant.', 2795, '2026-05-07 17:37:40.15116+00', '2026-06-14 15:14:07.782+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4341-7667-bba0-f02b778852cd', '__OWNER_ID__', 'Black Bamboo Daily Soothing Sun Shield SPF50+ PA++++', 'Haruharu Wonder', 'moisturizer', 'jar', 'Aqua, Adipate de Dibutyle, Synthetic Wax, Copolymère de Méthacrylate de Méthyle, Salicylate de Butyloctyle, Triméthicone de Caprylyl, Butylene Glycol, Caprylate de Propylheptyl, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Isododecane, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Méthicone de Caprylyl, Ethylhexyl Triazone, Polysilicone-15, Cérésine, Camellia Japonica Seed Oil, Triméthicone de Diphenylsiloxy Phenyl, Niacinamide, Polyricinoléate de Polyglycéryl-3, Diméthicone de Lauryl Polyglycéryl-3 Polydiméthylsiloxyéthyl, Copolymère de Diméthicone/Vinyl Diméthicone, Sodium Chloride, 1,2-Hexanediol, Diisostéarate/Polyhydroxystéarate/Sébacate de Polyglycéryl-4, Copolymère de Vinyl Diméthicone/Méthicone Silsesquioxane, Caprylyl Glycol, Glyceryl Caprylate, Extrait de Feuille de Phyllostachys Nigra, Extrait d''Écorce de Pousse de Phyllostachys Pubescens, Adenosine, Aspergillus Ferment, Tocopherol, Dipropylene Glycol, Pentylene Glycol, Bambusa Vulgaris Water, Betaine, Ectoin, Panthenol', 'Profite d''une protection solaire optimale grâce à la Wonder Black Bamboo Daily Soothing Sun Shield SPF50+ PA++++ Haruharu. Ce stick solaire innovant offre une protection à large spectre contre les UVA et les UVB en un seul geste, sans laisser de traces blanches. Infusé d''extrait breveté de pousses de bambou fermentées, de niacinamide et d''adénosine, cet écran solaire chimique vegan rafraîchit, hydrate et lisse la peau, offrant un fini semi-mat parfait pour les peaux à tendance grasse. Sa formule sans danger pour les récifs est exempte d''oxybenzone, d''octinoxate, d''OGM, de sulfates et d''alcool desséchant, ce qui la rend idéale pour les peaux sensibles. Enrichie en bétaïne et en ectoïne, elle nourrit et fortifie la barrière cutanée tout en assurant un teint éclatant sans effet gras. Recommandé pour : Peaux sensibles, peaux sèches, tous types de peaux.', 20, 'g', 'haruharu-wonder-black-bamboo-daily-soothing-sun-shield-spf50-pa', 'https://korean-skincare.fr/products/haruharu-wonder-black-bamboo-daily-soothing-sun-shield-spf50-pa', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-bamboo-daily-soothing-sun-shield-spf50-pa.webp', 'Tourne la molette située à la base du récipient pour faire monter le stick de 5 mm, et applique uniformément une quantité appropriée. Renouvelle l''application au besoin tout au long de la journée pour une protection solaire maximale.', 1886, '2026-05-07 17:37:40.161154+00', '2026-06-14 15:14:07.782+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4372-7fdd-a0c6-c5547dc53992', '__OWNER_ID__', 'Vitamin Tree Water-Gel Advanced', 'I''m From', 'moisturizer', 'jar', 'Extrait de Hippophae Rhamnoides, Glycerin, Butylene Glycol, Methylpropanediol, Dipropylene Glycol, Aqua, Niacinamide, 1,2-Hexanediol, Cyclopentasiloxane, Hippophae Rhamnoides Fruit Extract, Cyclohexasiloxane, Sodium Polyacryloyldimethyl Taurate, Panthenol, Polydecène Hydrogéné, Arginine, Carbomer, Portulaca Oleracea Extract, Allantoin, Dipotassium Glycyrrhizate, Chamomilla Recutita (Matricaria) Flower Extract, Tridéceth-10, Ethylhexylglycerin, Pentylene Glycol, Extrait de Résine de Boswellia Serrata, Phenoxyethanol, 3-O-Éthyl Ascorbate, Sodium Hyaluronate, Gomme de Biosaccharide-1, Eau de Feuille d’Aloe Barbadensis, Bambusa Vulgaris Water, Extrait d’Hamamelis Virginiana, Eau de Fleur de Nelumbo Nucifera, Extrait de Fruit de Rubus Chamaemorus, Extrait de Saussurea Involucrata, Extrait de Selaginella Lepidophylla', 'Rafraîchis et apaise instantanément ta peau avec la Vitamin Tree Water Gel Advanced I’m From. Un gel hydratant léger, vegan, formulé avec de l’eau de feuille d''argousier riche en vitamines et du niacinamide éclaircissant. Parfaite pour les peaux grasses, sensibles ou ternes, cette formule à absorption rapide procure un effet rafraîchissant immédiat, une hydratation profonde et un apaisement visible des zones irritées sans laisser de résidu collant. Elle aide également à réguler la production de sébum et à uniformiser le teint, laissant le visage plus clair, lumineux et équilibré. Ce gel avancé pénètre bien dans la peau et favorise une peau saine et rafraîchie à chaque utilisation.', 75, 'g', 'im-from-vitamin-tree-water-gel-advanced', 'https://korean-skincare.fr/products/im-from-vitamin-tree-water-gel-advanced', 'https://aurore-cdn.b-cdn.net/products/im-from-vitamin-tree-water-gel-advanced.webp', 'Distribue une quantité modérée de la crème. Applique-la sur l''ensemble de ton visage et masse délicatement pour une meilleure absorption.', 2745, '2026-05-07 17:37:40.210777+00', '2026-06-14 15:14:07.782+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4339-7833-a77c-502cfeed7302', '__OWNER_ID__', 'Black Rice Hyaluronic Essence', 'Haruharu Wonder', 'essence', 'dropper', 'Aqua, Glycerin, Betaine, Propanediol, Oryza Sativa Extract, Phyllostachys Pubescens Shoot Bark Extract, Aloe Barbadensis Leaf Extract, Panax Ginseng Root Extract, Aspergillus Ferment, Hyaluronic Acid, Beta-Glucan, Carbomer, Xanthan Gum, Trehalose, Tromethamine, 1,2-Hexanediol, Butylene Glycol, Sodium Phytate, Polyglyceryl-10 Laurate, Polyglyceryl-10 Myristate, Pulsatilla Koreana Extract, Usnea Barbata Extract, Zanthoxylum Piperitum Fruit Extract, Cyclodextrin, Alcohol, Lavandula Angustifolia Oil, Linalool', 'L''essence de riz noir hyaluronique Haruharu WONDER est une formule légère et profondément hydratante qui aide à garder la peau douce, lisse et rafraîchie. Composée de riz noir coréen fermenté et d''acide hyaluronique, elle procure une hydratation intense tout en améliorant l''élasticité de la peau et en réduisant les signes de vieillissement. Des ingrédients apaisants comme l''extrait de bambou, l''huile d''onagre et l''huile de lavande aident à calmer et à nourrir la peau, la laissant saine et éclatante. De plus, il est rapidement absorbé sans sensation de collant ou de gras, ce qui le rend parfait pour un usage quotidien. Emballé dans des matériaux respectueux de l''environnement, c''est un soin qui est bon pour votre peau et pour la planète. Recommandé pour : Tous les types de peau.', 50, 'ml', 'haruharu-wonder-black-rice-hyaluronic-essence', 'https://korean-skincare.fr/products/haruharu-wonder-black-rice-hyaluronic-essence', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-rice-hyaluronic-essence.webp', 'Distribue une quantité de produit suffisante sur un coton. Passe-le délicatement sur l''ensemble de ton visage. Retourne le coton et tapote doucement pour absorber l''excédent de produit.', 2052, '2026-05-07 17:37:40.153348+00', '2026-06-14 15:14:07.783+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-433e-7843-a2aa-210a4035ddce', '__OWNER_ID__', 'Rose PDRN Soothing Serum', 'Haruharu Wonder', 'serum', 'dropper', 'Aqua, Glycerin, Isopentyldiol, Niacinamide, Methyl Gluceth-20, 1,2-Hexanediol, Diphenyl Dimethicone, Triéthylhexanoïne, Panthenol, Butylene Glycol, Carbomer, Tromethamine, Polyglycéryl-10 Myristate, Ethylhexylglycerin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Dioscorea Japonica Root Extract, Polyacrylate de Sodium, Copolymère PVM/MA, Adenosine, Amidon de Maïs Hydrolysé, Beta-Glucan, Hydrogenated Lecithin, Centella Asiatica Extract, Sucrose, Ficus Carica Fruit Extract, Ceramide NP, ADN de Sodium, Hyaluronate de Diméthylsilanol, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Sodium Hyaluronate, Squalane, Hyaluronic Acid, Azelaic Acid, Potassium Hyaluronate, Sodium Hyaluronate Crosspolymer, Hydroxypropyltrimonium Hyaluronate, Sodium PCA, Hyaluronate de Sodium Diméthylsilanol, Sodium Acetylated Hyaluronate', 'Le Rose PDRN Soothing Serum Haruharu Wonder est un sérum apaisant et réparateur conçu pour restaurer l’équilibre et la résistance des peaux sensibles ou stressées. Enrichi en Rose PDRN, il soutient la régénération cutanée et aide à améliorer la texture et la vitalité globales de la peau, tout en procurant un apaisement immédiat. Sa formule légère et à absorption rapide hydrate en profondeur sans effet lourd, aidant à réduire les rougeurs et l’inconfort tout en renforçant la barrière cutanée. Enrichi en ingrédients doux et respectueux de la peau, ce sérum laisse le teint apaisé, frais et visiblement plus sain, ce qui en fait un soin quotidien idéal pour les peaux en quête de réparation et de confort. Recommandé pour : Peaux sensibles, irritées ou stressées, peaux sujettes aux rougeurs.', 30, 'ml', 'haruharu-wonder-rose-pdrn-soothing-serum', 'https://korean-skincare.fr/products/haruharu-wonder-rose-pdrn-soothing-serum', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-rose-pdrn-soothing-serum.webp', 'Après le nettoyage et le tonique, applique une quantité appropriée de sérum sur ton visage et ton cou. Tapote délicatement jusqu’à absorption complète. Utilise matin et soir, puis applique une crème hydratante. Le matin, termine par une protection solaire.', 1395, '2026-05-07 17:37:40.158051+00', '2026-06-14 15:14:07.783+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4343-7e83-bcaf-de4ccc25ede2', '__OWNER_ID__', 'Black Bamboo Top-to-Toe SPF Veil', 'Haruharu Wonder', 'moisturizer', 'jar', 'Aqua, Butyloctyl Salicylate, Ethylhexyl Triazone, Isononyl Isononanoate, Dibutyl Adipate, Terephthalylidene Dicamphor Sulfonic Acid, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Glycerin, Niacinamide, Caprylyl Methicone, Hexyl Laurate, Diisopropyl Sebacate, 2,3-Butanediol, Tromethamine, Polyglyceryl-6 Distearate, Silica, 1,2-Hexanediol, Pentylene Glycol, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Polysilicone-15, Candelilla/Jojoba/Rice Bran Polyglyceryl-3 Esters, Panthenol, Poly C10-30 Alkyl Acrylate, Glyceryl Stearate, Lauryl Lactate, Octyldodecanol, Behenyl Alcohol, Carbomer, Cetearyl Alcohol, Ammonium Acryloyldimethyltaurate/VP Copolymer, Hydrogenated Castor Oil/Sebacic Acid Copolymer, Sodium Stearoyl Glutamate, Inulin Lauryl Carbamate, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Ethylhexylglycerin, Adenosine, Echium Plantagineum Seed Oil, Polyacrylate Crosspolymer-6, Helianthus Annuus Seed Oil Unsaponifiables, Camellia Japonica Seed Extract, 3-O-Ethyl Ascorbic Acid, Tetracarboxymethyl Hexanoyl Dipeptide-12, Cardiospermum Halicacabum Flower/Leaf/Vine Extract, Tocopherol, Squalane, Ascorbic Acid, Bambusa Vulgaris Water, Butylene Glycol, Sodium Hyaluronate, Phyllostachys Nigra Leaf Extract, Hydrolyzed Hyaluronic Acid, Sodium Acetylated Hyaluronate', 'The Haruharu Wonder Black Bamboo Top-to-Toe SPF Veil is a lightweight, multi-use sunscreen designed to protect both face and body while delivering hydration and soothing care. Offering broad-spectrum SPF protection, this airy veil-like formula shields the skin from harmful UVA and UVB rays while maintaining a fresh, non-greasy finish. Infused with black bamboo extract, it provides antioxidant benefits and helps support overall skin health. Its fast-absorbing, breathable texture spreads easily without leaving a heavy residue or sticky feel, making it ideal for daily reapplication. The Haruharu Wonder Black Bamboo Top-to-Toe SPF Veil keeps skin protected, hydrated, and comfortable throughout the day. Recommended for: Daily sun protection, face and body use, lightweight sunscreen preference, hydration with UV care. How to use: Apply generously to face and body as the final step of your morning routine. Reapply every 2–3 hours, especially during prolonged sun exposure.', 100, 'ml', 'haruharu-wonder-black-bamboo-top-to-toe-spf-veil', 'https://korean-skincare.fr/products/haruharu-wonder-black-bamboo-top-to-toe-spf-veil', 'https://aurore-cdn.b-cdn.net/products/haruharu-wonder-black-bamboo-top-to-toe-spf-veil.webp', NULL, 2295, '2026-05-07 17:37:40.163736+00', '2026-06-14 15:14:07.783+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4346-75e4-a784-8bc56011a799', '__OWNER_ID__', 'Rice Cream', 'I''m From', 'moisturizer', 'jar', 'Eau de son de riz (Oryza Sativa), Aqua, Glycerin, Butylene Glycol, Cetyl Ethylhexanoate, Tétraéthylhexanoate de Pentaérythrityle, Hydrogenated Polyisobutene, Cire d''abeille synthétique, Butyrospermum Parkii Butter, Distéarate de Methylglucose Polyglyceryl-3, Vinyl Diméthicone, Pentylene Glycol, 1,2-Hexanediol, Behenyl Alcohol, Adenosine, Ammonium Acryloyldimethyltaurate/VP Copolymer, Bisabolol, Caprylic/Capric Triglyceride, Caprylyl Glycol, Ceramide NP, Olivate de Cetearyl, Ethylhexylglycerin, Glyceryl Stearate, Hyaluronic Acid, Hydrogenated Lecithin, Huile de son de riz (Oryza Sativa), Panthenol, Phytosphingosine, Sodium Hyaluronate, Sorbitan Olivate, Tocopherol, Disuccinate d''éthylènediamine trisodique, Gomme xanthane', 'La Rice Cream I''m From est une crème hydratante vegan qui est formulée avec 41 % de céramides de son de riz. Elle contrôle efficacement la production de sébum, emprisonne l''hydratation et renforce la peau, produisant ainsi un éclat de revitalisation. Elle possède une délicieuse texture soyeuse qui se fond instantanément dans la peau.', 50, 'g', 'im-from-rice-cream', 'https://korean-skincare.fr/products/im-from-rice-cream', 'https://aurore-cdn.b-cdn.net/products/im-from-rice-cream.webp', 'Utilise la spatule fournie pour prélever la quantité de crème souhaitée et applique-la sur les zones à traiter.', 3130, '2026-05-07 17:37:40.166224+00', '2026-06-14 15:14:07.783+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-434f-7a76-90a1-aae825da3f95', '__OWNER_ID__', 'Mugwort Mask', 'I''m From', 'mask', 'pack', 'Aqua, Butylene Glycol, Glycerin, Poudre de feuille d''Artemisia Princeps, 1,2-Hexanediol, Extrait de Cordyceps Sinensis, Extrait de racine de Polygonum Cuspidatum, Extrait de racine de Scutellaria Baicalensis, Methylpropanediol, Extrait de feuille de Ligularia Fischeri, Extrait de bourgeon de Rosa Davurica, Camellia Sinensis Leaf Extract, Glycyrrhiza Glabra Root Extract, Chamomilla Recutita (Matricaria) Flower Extract, Rosmarinus Officinalis Leaf Extract, Centella Asiatica Extract, Polyacrylate de glycéryle, Sodium, Carbomer, Arginine, Phenoxyethanol, Allantoin, Dipotassium Glycyrrhizate, Panthenol, Gomme Xanthane, Disodium EDTA', 'Le Mugwort Mask I''M FROM est un masque à rincer à base d''armoise de première qualité provenant du comté de Ganghwa en Corée pour calmer et apaiser les peaux irritées, rougies ou à problèmes. Riche en minéraux et en vitamines, l''armoise coréenne est connue pour sa capacité à restaurer la jeunesse de la peau et pour ses incroyables propriétés calmantes et détoxifiantes. Ce masque cicatrisant à l''armoise est suffisamment doux pour être utilisé quotidiennement. Il en résulte une peau apaisée qui semble plus rafraîchie et renouvelée.', 110, 'g', 'im-from-mugwort-mask', 'https://korean-skincare.fr/products/im-from-mugwort-mask', 'https://aurore-cdn.b-cdn.net/products/im-from-mugwort-mask.webp', 'Après le nettoyage, applique sur ton visage, en évitant le contour des yeux et de la bouche. Après 10 à 15 minutes, rince soigneusement à l''eau tiède.', 2773, '2026-05-07 17:37:40.175514+00', '2026-06-14 15:14:07.784+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4352-70cd-a6c4-409f5aa57370', '__OWNER_ID__', 'Rice Serum', 'I''m From', 'serum', 'dropper', 'Aqua, Propanediol, Glycerin, Methylpropanediol, Cyclopentasiloxane, 1,2-Hexanediol, Caprylyl Méthicone, Niacinamide, Cyclohexasiloxane, Betaine, Squalane, Extrait fermenté de germe de riz Aspergillus, Adenosine, Allantoin, Oligosaccharide d''alpha-glucane, Ammonium Acryloyldimethyltaurate/VP Copolymer, C12-14 Pareth-12, C30-45 Alkyl Cetearyl Dimethicone Crosspolymer, Dipotassium Glycyrrhizate, Disodium EDTA, Éthylhexylglycérol, Glutathione, Hydrolyzed Hyaluronic Acid, Hydroxypropyl Cyclodextrine, Madecassoside, Panthenol, Pentylene Glycol, Portulaca Oleracea Extract, Acide pyruvique, Sodium Hyaluronate, Tocopherol, Gomme xanthane', 'Le Rice Serum I''m From est un sérum vegan éclaircissant, illuminant et hydratant. Il est formulé avec 73 % d''extrait de ferment de germe de riz. Ce sérum est riche en vitamine B et en puissants antioxydants, qui vont stimuler la production de collagène et améliorer l''élasticité de la peau.', 30, 'ml', 'im-from-rice-serum', 'https://korean-skincare.fr/products/im-from-rice-serum', 'https://aurore-cdn.b-cdn.net/products/im-from-rice-serum.webp', 'Après le nettoyage, prépare ta peau avec un tonique. Distribue une quantité appropriée de produit et applique-le sur ton visage de façon uniforme.', 2738, '2026-05-07 17:37:40.177864+00', '2026-06-14 15:14:07.784+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4354-7964-8627-8b0bde9aa8a4', '__OWNER_ID__', 'Rice Sheet Mask', 'I''m From', 'mask', 'pack', 'Aqua, Methylpropanediol, Cetyl Ethylhexanoate, Niacinamide, 1,2-Hexanediol, Caprylic/Capric Triglyceride, Hydrogenated Poly(C6-14 Olefin), Polyglyceryl-6 Stearate, Oryza Sativa Extract, Dipropylene Glycol, Sorbitan Stearate, Hydroxyacetophenone, Arginine, Carbomer, Polyglyceryl-6 Behenate, Caprylyl Glycol, Gomme Xanthane, Adenosine, Ethylhexylglycerin, Betaine, Disodium EDTA, Sodium Hyaluronate, Panthenol, Squalane, Dipotassium Glycyrrhizate, Tocopherol, Pantolactone', 'Le Rice Sheet Mask I''m From est un soin revitalisant enrichi en extrait de riz 100 % naturel, conçu pour éclaircir, hydrater et restaurer les peaux fatiguées. Réputé pour son utilisation traditionnelle dans les rituels de beauté coréens, l''extrait de riz aide à améliorer le teint, à réduire le teint terne et à favoriser une peau saine et éclatante. Ce masque tissu ultra-doux adhère confortablement à la peau, lui apportant une hydratation et une nutrition en profondeur tout en améliorant son élasticité et sa douceur. Parfait pour tous les types de peaux, en particulier celles qui recherchent un teint éclatant et uniforme, il procure un regain de vitalité instantané après une seule utilisation. Enrichi en vitamines, acides aminés et minéraux, le Rice Sheet Mask I''m From va au-delà de l''hydratation ; il agit activement pour renforcer la barrière cutanée, apaiser les sensibilités et affiner le grain de peau. Sa formule légère garantit une absorption rapide sans sensation collante, laissant ta peau rafraîchie, repulpée et lumineuse. Que tu souhaites lutter contre la sécheresse, le teint irrégulier ou les signes de fatigue, ce masque t''offre un rituel de soin facile, inspiré des traditions de soin de la peau coréennes naturelles. Recommandé pour : Tous types de peaux.', 1, 'pcs', 'im-from-rice-sheet-mask', 'https://korean-skincare.fr/products/im-from-rice-sheet-mask', 'https://aurore-cdn.b-cdn.net/products/im-from-rice-sheet-mask.webp', 'Nettoie ton visage et applique un tonique pour préparer la peau et éliminer les impuretés. Ouvre le sachet avec précaution et déplie le masque tissu sans le déchirer. Applique le masque uniformément sur ton visage, en lissant les bulles d''air pour un contact maximal. Laisse agir pendant 10 à 20 minutes pour permettre à l''extrait de riz de pénétrer profondément dans ta peau. Retire délicatement le masque et tapote légèrement pour faire pénétrer le reste de l''essence. Conseil : Pour une expérience encore plus rafraîchissante, Placez le masque au réfrigérateur pendant 10 à 15 minutes avant utilisation.', 295, '2026-05-07 17:37:40.180385+00', '2026-06-14 15:14:07.784+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-435c-74a5-8e4e-929368450823', '__OWNER_ID__', 'Ginseng Eye Cream', 'I''m From', 'eye-cream', 'jar', 'Aqua, Butylene Glycol, Caprylic/Capric Triglyceride, Glycerin, Extrait de Ginseng Rouge, Olivate de Cétéaryle, Simmondsia Chinensis Seed Oil, Butyrospermum Parkii Butter, Cetearyl Alcohol, Sorbitan Olivate, Cera Alba, Methylpropanediol, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Isododecane, Betaine, Gomme de Xanthane, Extrait d''Usnée Barbue, Sodium Hyaluronate, Extrait de Racine d''Angelica Gigas, Panax Ginseng Root Extract, 1,2-Hexanediol, Caprylyl Glycol, Dimethicone, Copolymère de Diméthicone/Vinyldiméthicone, Glyceryl Caprylate, Collagène Soluble, Dipotassium Glycyrrhizate, Allantoin, Adenosine, Disodium EDTA, Extrait de Pulsatille de Corée, Zanthoxylum Piperitum Fruit Extract, Ethylhexylglycerin, Sorbitan Isostearate, Squalane, Sodium Acetylated Hyaluronate, Hydrolyzed Hyaluronic Acid, Parfum', 'La Ginseng Eye Cream I''m From est une crème pour les yeux riche en nutriments qui contient trois types de ginseng rare pour aider à nourrir les yeux fatigués et à obtenir un visage lisse et ferme. Grâce au ginseng cultivé dans le bois, cette crème présente une forte concentration de ginsénosides et une texture ferme qui épouse les courbes de ta peau, remplissant chaque sillon d''hydratation pour un fini visiblement ferme et hydraté. Cette crème luxueuse pour les yeux contient un mélange d''antioxydants puissants et de propriétés anti-âge pour aider à réduire l''apparence des rides et ridules, tout en améliorant la circulation pour minimiser l''apparence des cernes et des poches autour des yeux. Sa texture légère et à absorption rapide la rend parfaite pour un usage quotidien, et elle est exempte de parfums artificiels, de colorants et de conservateurs, ce qui la rend adaptée à tous les types de peau. Si tu cherches une crème pour les yeux qui peut aider à nourrir et à raffermir tes yeux fatigués, la Ginseng Eye Cream I''m From Ginseng est un choix idéal. Grâce à son mélange rare de ginseng et d''autres ingrédients naturels, elle peut aider à améliorer l''apparence de ta peau et lui donner un aspect revitalisé et rafraîchi.', 30, 'g', 'im-from-ginseng-eye-cream', 'https://korean-skincare.fr/products/im-from-ginseng-eye-cream', 'https://aurore-cdn.b-cdn.net/products/im-from-ginseng-eye-cream.webp', 'Comme traitement d''appoint : Applique un tonique pour lisser ton grain de peau. Prends une quantité appropriée de produit et applique-le légèrement autour de tes yeux. Tapote délicatement jusqu''à ce qu''il soit complètement absorbé. Comme crème de soin du visage : Prélève une quantité appropriée de produit à l''étape crème de ta routine. Applique-la uniformément sur l''ensemble de ton visage et fais pénétrer.', 3424, '2026-05-07 17:37:40.188174+00', '2026-06-14 15:14:07.785+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-435e-7c77-a1c4-59e27da5bd0e', '__OWNER_ID__', 'Mugwort Sheet Mask', 'I''m From', 'mask', 'pack', 'Artemisia Princeps Extract, Butylene Glycol, 1,2-Hexanediol, Aqua, Dipropylene Glycol, Glycerin, Hydroxyacetophenone, Carbomer, Arginine, Dipotassium Glycynthizate, Hydrolyzed Hyaluronic Acid, PVM/MA Copolymer, Caramel, Junipers Mexicana Oil, Vetiveria Zizanoides Root Oil, Elettaria Cardamomum Seed Oil, Abies Sibirica Oil, Maltodextrin', 'Le masque en feuille I''m From Mugwort offre un soin puissant et calmant grâce aux bienfaits intensément apaisants de l''armoise Ganghwa, une plante coréenne réputée pour sa capacité à calmer les irritations et à resserrer les pores. Grâce à une méthode d''extraction optimisée, ce masque maximise la concentration des ingrédients actifs pour détendre et restaurer en profondeur la peau fatiguée et stressée. La texture à base d''essence d''eau est rapidement absorbée, tandis que la feuille parfaitement ajustée assure un apport profond de nutriments. Idéal pour les peaux sensibles ou irritées, ce masque laisse votre teint rafraîchi, hydraté et visiblement apaisé. Recommandé pour : Tous les types de peau.', 1, 'pcs', 'im-from-mugwort-sheet-mask', 'https://korean-skincare.fr/products/im-from-mugwort-sheet-mask', 'https://aurore-cdn.b-cdn.net/products/im-from-mugwort-sheet-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 10 à 20 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 337, '2026-05-07 17:37:40.190624+00', '2026-06-14 15:14:07.785+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4368-7cab-9801-3b64aae4ca55', '__OWNER_ID__', 'Rice Glow Peel Off Mask', 'I''m From', 'exfoliant', 'jar', 'Aqua, Octyldodecanol, Polyvinyl Alcohol, Methylpropanediol, Butylene Glycol, Caprylic/Capric Triglyceride, 1,2-Hexanediol, Niacinamide, Simmondsia Chinensis Seed Oil, Algin, Polyglyceryl-10 Oléate, Polysorbate 80, Pentaerythrityl Tetraethylhexanoate, Pullulan, Glyceryl Stearate, PEG-100 Stearate, Panthenol, Disteardimonium Hectorite, Sodium Polystyrene Sulfonate, Microcrystalline Cellulose, Tocopheryl Acetate, Ethylhexylglycerin, Extrait de Ferment de Sphingomonas, Allantoin, Adenosine, Cellulose Gum, Sodium Phytate, Oryza Sativa Extract, Tocopherol, Citric Acid, Ceramide NP, Protéoglycane Soluble, Protéine de Riz Hydrolysée, Acides Aminés de Riz, Silica, Kaolin', 'Le Glow Peel Off Mask I''m From est un soin illuminateur conçu pour exfolier, lisser et illuminer la peau en douceur. À base d''extrait de riz et d''ingrédients naturels d''origine végétale, ce masque peel-off aide à éliminer les cellules mortes et les impuretés, pour révéler un teint plus uniforme et éclatant. Sa formule peel-off unique offre un effet nettoyant en profondeur tout en resserrant les pores et en affinant le grain de peau sans irritation excessive. Enrichi en vitamines, minéraux et antioxydants issus du riz, le Rice Glow Peel Off Mask purifie, nourrit et hydrate la peau, la laissant douce, lumineuse et revitalisée. Idéal pour les peaux ternes, rugueuses ou fatiguées, il offre une expérience spa à domicile sans effort qui rafraîchit et restaure ton éclat naturel. Utilise-le régulièrement pour obtenir un teint plus lumineux et plus lisse et profiter du pouvoir éclaircissant des soins traditionnels coréens à base de riz. Recommandé pour : Peaux ternes, rugueuses ou fatiguées.', 70, 'g', 'im-from-rice-glow-peel-off-mask', 'https://korean-skincare.fr/products/im-from-rice-glow-peel-off-mask', 'https://aurore-cdn.b-cdn.net/products/im-from-rice-glow-peel-off-mask.webp', 'Commence par nettoyer ta peau et appliquer un tonique, puis sèche-la. Applique une couche uniforme du masque sur ton visage, en évitant le contour des yeux et des lèvres. Laisse sécher complètement (environ 20 à 30 minutes). Retire délicatement le masque en commençant par les bords, en le soulevant vers le haut. Rince les résidus à l''eau tiède et poursuis ta routine de soins habituelle. Conseil : Applique une couche légèrement plus épaisse sur les bords de ton visage ; cela rendra le retrait plus facile et plus confortable.', 2695, '2026-05-07 17:37:40.200703+00', '2026-06-14 15:14:07.785+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-436b-71b9-a28f-26c9fc032662', '__OWNER_ID__', 'Mugwort Gel Cleanser', 'I''m From', 'cleanser', 'tube', 'Extrait d''Artemisia Princeps, Aqua, Sulfonate d''oléfine de sodium C14-16, Hydroxysultaine de lauryl, Glycerin, 1,2-Hexanediol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Caprylyl Glycol, Taurate de cocoyle méthyl de sodium, Sodium Chloride, Tromethamine, Hexadécène, Tétradécène, Sulfate de sodium, Huile d''Artemisia Vulgaris, Melia Azadirachta Leaf Extract, Extrait de fleur de Melia Azadirachta, Ocimum Sanctum Leaf Extract, Disodium EDTA, Curcuma Longa Root Extract, Dextrin, Extrait de Theobroma Cacao, Extrait de Corallina Officinalis', 'Découvre le pouvoir nettoyant de la nature avec le Mugwort Gel Cleanser I''m From, enrichi de 60 % d''extraits d''armoise provenant du village de Ganghwa Hwado. Ce gel nettoyant doux élimine en douceur le maquillage, la crème solaire et les impuretés tout en apaisant et en hydratant ta peau. Utilisant une méthode d''extraction à froid, il préserve tout le spectre des ingrédients actifs de l''armoise sans les dégrader. Parfaite pour les peaux sensibles, sa formule testée dermatologiquement nettoie les pores en profondeur, laissant ta peau rafraîchie, lisse et nourrie. Recommandé pour : Peaux sensibles, tous types de peaux.', 150, 'ml', 'im-from-mugwort-gel-cleanser', 'https://korean-skincare.fr/products/im-from-mugwort-gel-cleanser', 'https://aurore-cdn.b-cdn.net/products/im-from-mugwort-gel-cleanser.webp', 'En utilisant une petite quantité d''eau, fais mousser et masse délicatement ta peau, en évitant le contour des yeux. Rince abondamment à l''eau tiède.', 1795, '2026-05-07 17:37:40.202945+00', '2026-06-14 15:14:07.785+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-437d-7ae3-a1c9-55a589b16af0', '__OWNER_ID__', 'Rice Whip Facial Cleanser', 'I''m From', 'cleanser', 'jar', 'Glycerin, Aqua, Sodium Cocoyl Isethionate, Myristic Acid, Potassium Cocoyl Glycinate, Niacinamide, Methylpropanediol, Polyquaternium-7, Butylene Glycol, Ethylhexylglycerin, Caprylyl Glycol, 1,2-Hexanediol, Oryza Sativa Rice Extract, Disodium EDTA, Oryza Sativa Rice Bran Extract, Steareth-30, Sodium Benzoate, Caramel, Gluconolactone, Salicylic Acid, Capryloyl Salicylic Acid, Lactic Acid, Maltodextrin', 'Le Rice Whip Facial Cleanser I’m From est un nettoyant visage en mousse luxueusement douce, infusé d’extrait de riz de Yeoju nourrissant. Spécialement conçu pour éliminer en douceur les impuretés, l’excès de sébum et le maquillage, ce nettoyant laisse ta peau fraîche, hydratée et soyeuse, sans sensation de tiraillement ni de sécheresse. Sa texture aérienne et fouettée se transforme en une mousse riche qui nettoie en profondeur tout en préservant la barrière naturelle d’hydratation de ta peau, le rendant idéal pour un usage quotidien sur tous les types de peaux, y compris les peaux sensibles. Inspirée des secrets de beauté traditionnels du nettoyage à l’eau de riz coréenne, cette formule aide à illuminer les teints ternes et à améliorer la texture de la peau au fil du temps. Riche en vitamines, acides aminés et antioxydants, le Whip Facial Cleanser I’m From purifie tout en aidant à booster l’éclat, laissant ta peau lumineuse et en pleine santé. Que ce soit pour commencer ta routine du matin ou te détendre le soir, ce nettoyant doux mais efficace est ton allié pour un teint propre, équilibré et éclatant. Recommandé pour : Peaux sèches, rugueuses, ternes, tous les types de peaux.', 150, 'ml', 'im-from-rice-whip-facial-cleanser', 'https://korean-skincare.fr/products/im-from-rice-whip-facial-cleanser', 'https://aurore-cdn.b-cdn.net/products/im-from-rice-whip-facial-cleanser.webp', 'Pompe une quantité adéquate de produit dans la paume de ta main. Masse doucement sur ta peau humide en mouvements circulaires, en laissant la mousse éliminer les impuretés et les saletés. Rince abondamment à l’eau tiède et sèche en tapotant. Astuce : Pour un effet éclaircissant supplémentaire, laisse la mousse poser sur ta peau pendant 30 à 60 secondes avant de rincer afin que l’extrait de riz nourrisse et revitalise ta peau.', 1695, '2026-05-07 17:37:40.221457+00', '2026-06-14 15:14:07.786+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4385-7894-9ed0-21b920b170c9', '__OWNER_ID__', 'Mugwort Serum', 'I''m From', 'serum', 'dropper', 'Aqua, Butylene Glycol, 2,3-Butanediol, Glycerin, Methylpropanediol, Niacinamide, 1,2-Hexanediol, Pentylene Glycol, Érythritol, Artemisia Princeps Leaf Extract, Betaine, Methyl Gluceth-10, Panthenol, Hydroxyéthyl Urée, Gomme Xanthane, Gomme de Sclérotium, Carbomer, Caprylic/Capric Triglyceride, Ethylhexylglycerin, Tromethamine, Hydrogenated Lecithin, Allantoin, Citric Acid, Sodium Phytate, Extrait de Fleur de Melia Azadirachta, Ocimum Sanctum Leaf Extract, Dextrin, Extrait de Theobroma Cacao, Melia Azadirachta Leaf Extract, Ceramide NP, Curcuma Longa Root Extract, Extrait de Bulbe d''Ail (Allium Sativum), Extrait de Corallina Officinalis, Beta-Glucan, Cellulose, Polyglutamic Acid, Sodium Hyaluronate, Tocopherol', 'Le Mugwort Serum I''m From est un sérum apaisant et hydratant pour le visage, formulé à partir de 57 % d''extrait de feuilles d''armoise de Ganghwa, provenant de Ganghwa, en Corée du Sud, connu pour ses propriétés antioxydantes et anti-inflammatoires. Conçu pour apaiser les peaux sensibles, irritées et rugueuses, ce sérum présente une texture légère, semblable à un gel aqueux, qui pénètre rapidement sans laisser de sensation collante, pour une hydratation en profondeur et un teint sain et équilibré. Il contient un mélange d''ingrédients clés tels que le niacinamide pour illuminer le teint et contrôler le sébum, le céramide NP pour renforcer la barrière cutanée, et l''acide polyglutamique et l''allantoïne pour une hydratation accrue. La formule contient également de l''exosome d''ail (extrait de bulbe d''Allium Sativum) pour la régénération cellulaire et des extraits riches en antioxydants tels que le curcuma et le cacao pour lutter contre les dommages causés par les radicaux libres. Sans alcools agressifs, parabènes, silicones, sulfates et allergènes courants, ce sérum vegan et cruelty-free est testé dermatologiquement, sans danger pour les récifs coralliens et convient aux peaux sensibles, grasses, mixtes et à tendance acnéique. Il est particulièrement efficace pour réduire les rougeurs, les irritations et les imperfections, ce qui en fait un complément polyvalent aux routines de soins de la peau. Recommandé pour : Tous types de peaux.', 30, 'ml', 'im-from-mugwort-serum', 'https://korean-skincare.fr/products/im-from-mugwort-serum', 'https://aurore-cdn.b-cdn.net/products/im-from-mugwort-serum.webp', 'Après avoir nettoyé ta peau, prépare-la avec un tonique. Prélève une quantité appropriée et applique-la uniformément sur ton visage.', 2795, '2026-05-07 17:37:40.229397+00', '2026-06-14 15:14:07.786+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4387-7e28-9caf-f1f09f162a6a', '__OWNER_ID__', 'Rice Sunscreen', 'I''m From', 'moisturizer', 'jar', 'Oryza Sativa Extract, Zinc Oxide, Cyclohexasiloxane, Butyloctyl Salicylate, Propanediol, Propylheptyl Caprylate, Isododecane, Polyglycéryle-3 Polydiméthylsiloxyéthyl Diméthicone, Methyl Triméthicone, Caprylyl Méthicone, Methyl Methacrylate Crosspolymer, Aqua, Polyméthylsilsesquioxane, Sodium Hyaluronate, Disteardimonium Hectorite, Magnesium Sulfate, Triéthoxycaprylylsilane, 1,2-Hexanediol, Polyglyceryl-2 Dipolyhydroxystearate, Lauryl Polyglycéryle-3 Polydiméthylsiloxyéthyl Diméthicone, Glyceryl Caprylate, Caprylyl Glycol, Ethylhexylglycerin, Tocopherol, Parfum', 'La Rice Sunscreen I''m From offre une protection solaire puissante avec un SPF 50+ PA++++ tout en nourrissant la peau avec 41% d''extrait de riz Goami. Cette crème solaire minérale légère et non nanométrique protège contre les rayons UVA et UVB nocifs sans irriter les peaux sensibles. Sa formule hydratante, riche en acides aminés et en gamma-oryzanol, lisse la texture de la peau, illumine le teint et offre un fini mat naturel sans effet collant. Sans risque pour la peau et l''environnement, cette crème solaire respectueuse des récifs est exempte d''oxybenzone, d''octinoxate et d''autres ingrédients nocifs, ce qui en fait un produit idéal pour un usage quotidien. Recommandé pour : Sans risque pour l''acné fongique, peaux sensibles, tous types de peaux.', 50, 'ml', 'im-from-rice-sunscreen', 'https://korean-skincare.fr/products/im-from-rice-sunscreen', 'https://aurore-cdn.b-cdn.net/products/im-from-rice-sunscreen.webp', 'Après ta crème hydratante de jour, utilise une quantité suffisante de produit et étale-le délicatement sur ton visage, ainsi que sur les parties de ton corps les plus exposées au soleil. Ajoute une couche supplémentaire sur les zones plus vulnérables aux rayons UV, comme le front et le nez. Pour les activités de plein air, renouvelle l''application toutes les 4 heures pour bloquer plus efficacement les rayons UV.', 2445, '2026-05-07 17:37:40.231739+00', '2026-06-14 15:14:07.786+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-438a-7240-8ddc-19b8b68aedb6', '__OWNER_ID__', 'Beet Refresh Pad', 'I''m From', 'exfoliant', 'pack', 'Aqua, Extrait de Racine de Beta Vulgaris, Glycerin, Dipropylene Glycol, Propanediol, Niacinamide, Érythritol, 1,2-Hexanediol, Hydroxyacetophenone, Caprylyl Glycol, Daucus Carota Sativa Root Extract, Pyrus Malus Fruit Extract, Laurate de Polyglycéryl-10, Allantoin, Gomme Xanthane, Adenosine, Arginine, Carbomer, Sodium Hyaluronate, Copolymère de Glycéryl Acrylate/Acide Acrylique, Melia Azadirachta Leaf Extract, Copolymère PVM/MA, Extrait de Fleur de Melia Azadirachta, Extrait Hydrolysé de Gardenia Florida, Diglycyrrhizate Dipotassique, Betaine, Citric Acid, Salicylate de Bétaïne, Maltodextrin, Panthenol, Ethylhexylglycerin, Coccinia Indica Fruit Extract, Extrait de Corallina Officinalis, Pantolactone, Disodium EDTA', 'Le Beet Refresh Pad I''m From apporte une bouffée de vitalité et d''hydratation grâce à ses compresse toniques imbibées d''essence, dotées de 20 % d''extrait de betterave rouge. Cette formule puissante bourrée d''anthocyanine s''attaque non seulement à l''aspect terne de la peau, mais lisse également son grain irrégulier. C''est une solution qui convient à tous les types de peau, grâce au bêta-carotène contenu dans l''extrait de betterave rouge, qui a un effet calmant et fait des merveilles même sur les peaux irritées. Utilisant une méthode de décoction à froid, ces compresses assurent l''intégrité des composés actifs : le liquide épais est infusé à basse température pendant une durée exceptionnelle de 100 heures, transmettant ainsi l''énergie revitalisante de la betterave rouge biologique sans en compromettre les bienfaits. Ces compresses, composées d''un tissu doux, délivrent 20 fois plus d''essence de betterave rouge sans causer d''irritation, laissant la peau hydratée et rafraîchie sans aucun résidu collant. Ces compresses promettent une expérience délicieuse, offrant une hydratation profonde et un confort sans lourdeur, laissant la peau revigorée et remarquablement hydratée, ce qui en fait un ajout précieux à ta routine beauté. Recommandé pour : Tous types de peaux.', 60, 'pcs', 'im-from-beet-refresh-pad', 'https://korean-skincare.fr/products/im-from-beet-refresh-pad', 'https://aurore-cdn.b-cdn.net/products/im-from-beet-refresh-pad.webp', 'Avec son côté en relief, passe délicatement la compresse sur tout le visage, en évitant le contour de la bouche et des yeux. Passe à nouveau la compresse sur ta la peau avec le côté doux pour finir l''application. On peut également utiliser les compresses comme un masque tissu apaisant en les plaçant sur les zones irritées, puis en les laissant poser sur la peau pendant 10 à 20 minutes.', 2195, '2026-05-07 17:37:40.234004+00', '2026-06-14 15:14:07.786+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4391-73fe-a405-8331199c6526', '__OWNER_ID__', 'Fig Cleansing Oil', 'I''m From', 'cleanser', 'tube', 'Ethylhexyl Palmitate, Sorbeth-30 Tetraoleate, Caprylic/Capric Triglyceride, Parfum, Ficus Carica Fruit Extract, Argania Spinosa Kernel Oil, Huile de Graine de Calophyllum Inophyllum, Camellia Japonica Seed Oil, Huile de Graine de Camellia Sinensis, Limnanthes Alba Seed Oil, Macadamia Ternifolia Seed Oil, Simmondsia Chinensis Seed Oil, Aqua, Butylene Glycol, 1,2-Hexanediol, Oenothera Biennis Flower Extract, Pinus Palustris Leaf Extract, Pueraria Lobata Root Extract, Ulmus Davidiana Root Extract', 'Offre à ta peau une expérience de nettoyage sensorielle avec la Fig Cleansing Oil I''m From Fig, un nettoyant de luxe qui élimine facilement le maquillage, la crème solaire et les impuretés sans agresser ta peau. Enrichie en extrait de figue riche en antioxydants et en huiles végétales nourrissantes, cette formule soyeuse glisse sur la peau, élimine les impuretés tout en hydratant. Au fur et à mesure que tu la masses, l''huile se transforme en une émulsion laiteuse qui se rince facilement, laissant ton teint doux, équilibré et rafraîchi. Parfaite pour un usage quotidien, cette huile démaquillante douce mais efficace est idéale pour tous les types de peaux, y compris les peaux sensibles et sèches. L''extrait de figue apaise et protège la barrière cutanée, tandis que des huiles légères comme celles de graines de tournesol et de jojoba aident à maintenir l''hydratation et la pureté de la peau. Que tu te détendes après une longue journée ou que tu prépares ta peau pour une routine matinale rafraîchissante, la Fig Cleansing Oil est le produit idéal pour une peau propre, éclatante et nourrie. Recommandé pour : Tous types de peaux.', 200, 'ml', 'im-from-fig-cleansing-oil', 'https://korean-skincare.fr/products/im-from-fig-cleansing-oil', 'https://aurore-cdn.b-cdn.net/products/im-from-fig-cleansing-oil.webp', 'Commence avec les mains et le visage secs. Verse 2 à 3 pompes d''huile démaquillante dans tes paumes. Masse délicatement ton visage avec l''huile en effectuant des mouvements circulaires, en insistant sur les zones maquillées ou protégées par un écran solaire. Ajoute un peu d''eau pour émulsionner l''huile, qui deviendra alors laiteuse. Continue à masser pendant quelques secondes, puis rince abondamment à l''eau tiède. Si tu préfères un double nettoyage, utilise ensuite ton nettoyant à base d''eau habituel. Conseil : Utilise cette huile démaquillante comme première étape de ta routine de soins du soir pour dissoudre sans effort même le maquillage tenace et laisser ta peau douce et rafraîchie.', 2695, '2026-05-07 17:37:40.241109+00', '2026-06-14 15:14:07.787+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-442e-7b05-acba-a8356032e3ce', '__OWNER_ID__', 'Hyal Reyouth Ampoule', 'Dr. Ceuracle', 'serum', 'dropper', 'Aqua, Panthenol, Methylpropanediol, 1,2-Hexanediol, Niacinamide, Sodium Hyaluronate, Glycerin, Laminaria Japonica Extract, Eclipta Prostrata Leaf Extract, Centella Asiatica Extract, Ficus Carica Fruit Extract, Panax Ginseng Root Extract, Dioscorea Japonica Root Extract, Hydrogenated Lecithin, Olea Europaea Fruit Oil, Octyldodécéth-16, Gomme Xanthane, Inulin, Adenosine, Carbomer, Fructooligosaccharides, Disodium EDTA, Tromethamine, Beta-Glucan, Hydrolyzed Hyaluronic Acid, Butylene Glycol, Ceramide NP, Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Sodium Acetylated Hyaluronate, Hyaluronate Hydroxypropyltrimonium, Parfum, Ethylhexylglycerin', 'La Hyal Reyouth Ampoule Dr. Ceuracle est un élixir raffermissant qui revitalisera ta peau en lui apportant une hydratation riche et durable, et lui redonnera son éclat de jeunesse. Cette puissante ampoule est dotée d''un remarquable complexe 6-Hyal, qui insuffle à ta peau une hydratation intensive, ce qui en fait la solution parfaite pour les peaux sèches et relâchées qui aspirent à une apparence rebondie et revitalisée. Avec une quantité impressionnante de 50 000 ppm de panthénol (vitamine B5) et de fructane, cette ampoule se distingue en favorisant la synthèse du collagène et en fortifiant la barrière cutanée pour un teint ferme et résistant. L''acide hyaluronique concentré à haut poids moléculaire travaille avec diligence pour recharger et repulper la peau affaiblie, offrant un sentiment renouvelé de vitalité et d''élasticité. Dévoile le secret d''une peau radieuse et pleine de jeunesse avec la Dr. Ceuracle Hyal Reyouth Ampoule. Améliore ta routine beauté avec cette formule puissante, et assiste à la transformation de ta peau en un modèle de beauté, qui respire la confiance et l''éclat. Embrasse l''hydratation riche et la fermeté apportées par cette ampoule, et redécouvre la joie d''un teint profondément rajeuni. Recommandé pour : Tous types de peaux.', 50, 'ml', 'dr-ceuracle-hyal-reyouth-ampoule', 'https://korean-skincare.fr/products/dr-ceuracle-hyal-reyouth-ampoule', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-hyal-reyouth-ampoule.webp', 'Prélève 2~3 gouttes et applique-les sur ton visage après avoir appliqué un tonique. Tapote délicatement pour une meilleure absorption.', 2934, '2026-05-07 17:37:40.398592+00', '2026-06-14 15:14:07.787+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-438c-77cc-aa1b-72f42931809d', '__OWNER_ID__', 'Fig Scrub Mask', 'I''m From', 'exfoliant', 'jar', 'Caprylic/Capric Triglyceride, Sucrose, PEG-7 Glyceryl Cocoate, Stearalkonium Hectorite, C13-15 Alkane, Ficus Carica Fruit Powder, Prunus Amygdalus Dulcis Seed Meal, Juglans Regia Shell Powder, Euphorbia Cerifera Cera, Caprylyl Glycol, Parfum, Caramel', 'Le Fig Scrub Mask I''M FROM est un soin exfoliant à double action qui élimine en douceur les cellules mortes tout en nourrissant la peau grâce à l’extrait de figue riche en antioxydants. Formulé avec de la poudre de figue finement moulue et du sucre brun, ce masque offre à la fois une exfoliation physique et enzymatique pour laisser la peau plus lisse, plus douce et plus éclatante. Idéal pour les peaux ternes, rugueuses ou congestionnées, ce masque à rincer contient également des ingrédients hydratants et apaisants pour prévenir les irritations et la sécheresse. Le Fig Scrub Mask I''M FROM est ton allié pour une remise à zéro de la peau douce mais efficace, révélant un teint frais et lumineux. Recommandé pour : Peaux ternes, rugueuses ou fatiguées.', 100, 'g', 'im-from-fig-scrub-mask', 'https://korean-skincare.fr/products/im-from-fig-scrub-mask', 'https://aurore-cdn.b-cdn.net/products/im-from-fig-scrub-mask.webp', 'Après le nettoyage, applique une couche uniforme sur peau humide, en évitant le contour des yeux. Masse délicatement en mouvements circulaires pendant 1 à 2 minutes, puis laisse poser 5 à 10 minutes en masque. Rince abondamment à l’eau tiède. Utilise 1 à 2 fois par semaine.', 2295, '2026-05-07 17:37:40.236308+00', '2026-06-14 15:14:07.787+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4393-79ca-9008-835b53128a52', '__OWNER_ID__', 'Vitamin Fruit Serum', 'I''m From', 'serum', 'dropper', 'Extrait de fruit d''argousier (Hippophae Rhamnoides), Methylpropanediol, 1,2-Hexanediol, Glycerin, Niacinamide, Cyclohexasiloxane, Portulaca Oleracea Extract, Extrait de fruit de Malpighia Glabra, Laminaria Japonica Extract, Eclipta Prostrata Leaf Extract, Extrait d''Acmella Oleracea, Melia Azadirachta Leaf Extract, Curcuma Longa Root Extract, Ocimum Sanctum Leaf Extract, Extrait de Corallina Officinalis, Hippophae Rhamnoides Oil, Hydrogenated Lecithin, Ammonium Acryloyldimethyltaurate/VP Copolymer, Gomme xanthane, Tocopheryl Acetate, Adenosine, Carbomer, Fructooligosaccharides, Disodium EDTA, Beta-Glucan, Tromethamine, Hydrolyzed Hyaluronic Acid, Aqua, Ascorbic Acid, Ethylhexylglycerin', 'Le Vitamin Fruit Serum I''m From est un élixir revitalisant qui exploite les puissants bienfaits de 86,7 % d''extraits d''argousier pour rajeunir et illuminer ta peau. Composé d''un mélange harmonieux d''extraits riches en vitamines, ce sérum nourrit en profondeur les peaux fatiguées et ternes, leur redonnant l''éclat et la vitalité de la jeunesse. En mettant l''accent sur l''éclaircissement et l''uniformisation du teint, cette formule cible les taches brunes, l''hyperpigmentation et les zones irrégulières, dévoilant ainsi un teint plus uniforme et plus radieux. Chargée d''antioxydants, elle agit comme un bouclier protecteur, luttant contre les radicaux libres et le vieillissement prématuré, laissant à ta peau une apparence saine et lumineuse. Sa texture légère et non grasse pénètre sans effort dans la peau, offrant une hydratation durable, garantissant une sensation de douceur, de souplesse et de revitalisation. Avec une concentration impressionnante de 74 % d''extrait d''argousier, réputé pour sa composition riche en vitamines, ce sérum redonne vie aux peaux ternes, en les hydratant et en leur donnant un éclat naturel. Les acides de fruits contenus dans la formule renforcent l''hydratation de la peau, tandis que la texture légère du sérum pénètre rapidement sans résidu collant ni sensation de picotement. Infusé avec une concentration élevée de 1032 mg de vitamine C provenant de l''argousier, ce sérum ne se contente pas d''éclaircir la peau, il la lisse et l''adoucit également. Sa liste d''ingrédients hypoallergéniques et naturels le rend adapté aux peaux sensibles et permet d''obtenir un teint équilibré et net. Pour un effet renforcé, il est recommandé d''associer ce sérum au Vitamin Tree Water Gel, particulièrement bénéfique pour les peaux grasses ou sensibles qui ont besoin à la fois d''hydratation et de purification. Recommandé pour : Peaux sensibles, tous types de peaux.', 30, 'ml', 'im-from-vitamin-fruit-serum', 'https://korean-skincare.fr/products/im-from-vitamin-fruit-serum', 'https://aurore-cdn.b-cdn.net/products/im-from-vitamin-fruit-serum.webp', 'Applique une quantité appropriée de produit uniformément sur ta peau, en évitant le contour des yeux et de la bouche. Tapote légèrement ta peau pour faciliter l''absorption.', 2023, '2026-05-07 17:37:40.243441+00', '2026-06-14 15:14:07.787+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-439b-7cef-879a-459322dd9118', '__OWNER_ID__', 'Freshly Juiced Vitamin Drop', 'Dear Klairs', 'moisturizer', 'jar', 'Aqua, Propylene Glycol, Ascorbic Acid, Hydroxyéthylcellulose, Centella Asiatica Extract, Citrus Junos Fruit Extract, Extrait de Fruit de Illicium Verum (Anis), Extrait de Fruit de Citrus Paradisi (Pamplemousse), Extrait de Fleur de Nelumbium Speciosum, Paeonia Suffruticosa Root Extract, Extrait de Racine de Scutellaria Baicalensis, Polysorbate 60, Brassica Oleracea Italica Extract, Extrait de Fruit de Chaenomeles Sinensis, Huile d''Orange du Brésil, Sodium Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Disodium EDTA, Lavandula Angustifolia Oil, Extrait de Culture de Callus de Camellia Sinensis, Extrait de Bois de Larix Europaea, Extrait de Chrysanthellum Indicum, Extrait de Racine de Rheum Palmatum, Extrait de Racine de Asarum Sieboldi, Extrait de Feuille de Quercus Mongolia, Extrait de Persicaria Hydropiper, Extrait de Racine de Corydalis Turtschaninovii, Coptis Chinensis Root Extract, Extrait d''Écorce de Magnolia Obovata, Lysine HCL, Proline, Sodium Ascorbyl Phosphate, Méthionine Acétylée, Théanine, Lecithin, Glutamine Acétylée, SH-Oligopeptide-1, SH-Oligopeptide-2, SH-Polypeptide-1, SH-Polypeptide-9, SH-Polypeptide-11, Bacillus Ferment, Sodium Hyaluronate, Caprylyl Glycol, Butylene Glycol, 1,2-Hexanediol', 'Le Freshly Juiced Vitamin Drop Dear Klairs est un sérum rajeunissant qui contient 5 % de vitamine C (acide ascorbique) et qui est assez doux même pour les peaux sensibles. La vitamine C est un antioxydant qui offre la meilleure protection qui soit contre le vieillissement et constitue un agent éclaircissant efficace. Le Freshly Juiced Drop KLAIRS aide à estomper les taches brunes, protège de l''hyperpigmentation, maintient la peau ferme en réduisant les ridules, et éclaircit et unifie le teint.', 35, 'ml', 'dear-klairs-freshly-juiced-vitamin-drop', 'https://korean-skincare.fr/products/dear-klairs-freshly-juiced-vitamin-drop', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-freshly-juiced-vitamin-drop.webp', 'Prélève une quantité adéquate de produit à l''aide du compte-gouttes. Masse délicatement ta peau en suivant son grain. Renouvelle l''application sur le contour des yeux secs.', 2542, '2026-05-07 17:37:40.251664+00', '2026-06-14 15:14:07.788+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-439e-7461-b015-5e304ab812fb', '__OWNER_ID__', 'Fundamental Eye Awakening Gel', 'Dear Klairs', 'eye-cream', 'jar', 'Aqua, Glycerin, 1,2-Hexanediol, Butylene Glycol, Portulaca Oleracea Extract, Tromethamine, Sodium PCA, Carbomer, Copolymère d’Hydroxyéthyl Acrylate/Hyaluronate de Sodium Acryloyldimethyl Taurate, Laurate de Polyglycéryl-10, Simmondsia Chinensis Seed Oil, Argania Spinosa Kernel Oil, Propanediol, Ethylhexylglycerin, Tocopherol, Extrait de Graine de Phaseolus Angularis, Gomme Xanthane, Sorbitan Isostearate, Extrait de Perilla Frutescens, Extrait de Fruit de Chaenomeles Sinensis, Extrait de Feuille de Diospyros Kaki, Extrait d’Écorce de Cinnamomum Cassia, Artemisia Princeps Leaf Extract, Extrait de Chrysanthellum Indicum, Camellia Sinensis Leaf Extract, Copper Tripeptide-1, Oligopeptide-32, Oligopeptide-29, Acetyl Hexapeptide-8, Caffeine, Niacinamide, Hydrogenated Lecithin', 'Le Fundamental Eye Awakening Gel Dear Klairs est un gel hydratant contenant de la caféine et de l''extrait de haricot rouge pour garder le contour des yeux net et frais. Cette crème légère améliore les cernes et le teint de la peau tout en aidant à dégonfler les poches et à apporter un effet antioxydant. Ce gel laisse une sensation d''hydratation fraîche pour offrir un fini rafraîchissant, tandis que sa texture à absorption rapide prend soin du contour des yeux même lors des matins bien remplis. Enrichi en caféine, extrait de haricot rouge et thé vert apaisant, ce gel rafraîchissant apporte une dose d’antioxydants et de peptides pour réveiller et dynamiser la peau. Parfait pour tous les types de peaux, en particulier les peaux grasses et mixtes, sa formule fraîche s’absorbe rapidement sans laisser de résidu collant, idéal pour ta routine matinale. Que tu veuilles combattre la fatigue ou simplement maintenir un regard frais et jeune, le Fundamental Eye Awakening Gel Dear Klairs est la solution idéale pour des yeux éclatants et revitalisés. Recommandé pour : Tous types de peaux.', 35, 'ml', 'dear-klairs-fundamental-eye-awakening-gel', 'https://korean-skincare.fr/products/dear-klairs-fundamental-eye-awakening-gel', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-fundamental-eye-awakening-gel.webp', 'Utilise 1 à 2 fois pompe de produit et étale-le sur le contour de tes yeux. Tapote délicatement pour aider à l''absorption. Termine ta routine avec une crème hydratante. Astuce : Pour un effet rafraîchissant supplémentaire, conserve-le au réfrigérateur et applique-le le matin pour aider à réduire les poches.', 2395, '2026-05-07 17:37:40.25405+00', '2026-06-14 15:14:07.788+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43a0-7d52-a439-e67bc94b79cb', '__OWNER_ID__', 'Gentle Black Deep Cleansing Oil', 'Dear Klairs', 'cleanser', 'tube', 'Caprylic/Capric Triglyceride, Cetyl Ethylhexanoate, Isononanoate d''Isononyle, PEG-7 Glyceryl Cocoate, Isopropyl Myristate, Simmondsia Chinensis Seed Oil, Glycine Soja Oil, Sesamum Indicum Seed Oil, Huile de Graine de Ribes Nigrum (Cassis), Tocopheryl Acetate, PEG-20 Glyceryl Triisostearate, Polysorbate 20, Parfum, Butyrospermum Parkii Butter, Huile de Graine de Carapa Guaianensis, Huile de Graine de Vaccinium Macrocarpon (Canneberge)', 'La Gentle Black Deep Cleansing Oil Dear Klairs est une huile nettoyante douce mais efficace qui élimine efficacement la saleté et le maquillage sans irriter la peau et maintient l''hydratation même après le nettoyage. Sa formule hypoallergénique est gorgée d''huiles naturelles telles que l''huile de sésame noir qui fonctionne comme un antioxydant et prévient la déshydratation et le vieillissement, et l''huile de pépins de cassis qui est riche en vitamines et en minéraux, contrôle la production de sébum, augmente l''élasticité et apaise la peau.', 150, 'ml', 'dear-klairs-gentle-black-deep-cleansing-oil', 'https://korean-skincare.fr/products/dear-klairs-gentle-black-deep-cleansing-oil', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-gentle-black-deep-cleansing-oil.webp', 'Applique une quantité appropriée de produit sur ta peau. Masse en effectuant des mouvements circulaires. Rince à l''eau tiède.', 2164, '2026-05-07 17:37:40.256655+00', '2026-06-14 15:14:07.788+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4399-710d-a18b-966a13578706', '__OWNER_ID__', 'Midnight Blue Calming Cream', 'Dear Klairs', 'moisturizer', 'jar', '60ml : Water, Cetyl Ethylhexanoate, Butylene Glycol, Glycerin, Sodium Hyaluronate, Caprylic/Capric Triglyceride, Centella Asiatica Extract, Sorbitan Stearate, Cetyl Alcohol, Butyrospermum Parkii Butter, Argania Spinosa Kernel Oil, Simmondsia Chinensis Seed Oil, Sorbitan Sesquioleate, Glyceryl Stearate, Stearic Acid, Portulaca Oleracea Extract, Anthemis Nobilis Flower Extract, Ceramide NP, Polysorbate 60, Cera Alba, Chlorphenesin, Tocopheryl Acetate, Xanthan Gum, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Morus Alba Root Extract, Tromethamine, Brassica Oleracea Italica Extract, Guaiazulene, Acetyl Hexapeptide-8, Lecithin, Acetyl Glutamine, SH-Oligopeptide-1, SH-Oligopeptide-2, SH-Polypeptide-1, SH-Polypeptide-9, SH-Polypeptide-11, Bacillus Ferment, Caprylyl Glycol, 1,2-Hexanediol 30g : Water, Cetyl Ethylhexanoate, Glycerin, Butylene Glycol, Caprylic/Capric Triglyceride, Centella Asiatica Extract, Sorbitan Stearate, Argania Spinosa Kernel Oil, Butyrospermum Parkii (Shea Butter, Cetyl Alcohol, Simmondsia Chinensis Seed Oil, Sorbitan Sesquioleate, Glyceryl Stearate, Stearic Acid, Portulaca Olerace Extract, Anthemis Nobilis Flower Extract, Candelila Cera, Chlorphenesin, Polysorbate 60, 1,2-Hexanediol, Hydrogenated Lecithin, Tocopheryl Acetate, Xanthan Gum, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Tromethamine, Brassica Oleracea Italica Extract, Morus Alba Root Extract, Guaiazulene, Ceramide NP, Sodium Hyaluronate, Acetyl Glutamine, Lecithin, Bacillus Ferment, Caprylyl Glycol, sh-Oligopeptide-1, sh-Oligopeptide-2, sh-Polypeptide-1, sh-Polypeptide-11, Sh-Polypeptide -9, Acetyl Hexapeptide-8, Palmitic Acid, Arachidic Acid, Oleic Acid', 'La Midnight Blue Calming Cream Dear Klairs est douce et aide à renforcer la barrière cutanée tout en calmant les peaux stressées extrêmement irritées. Son ingrédient phare, le guaiazulène (qui donne à la crème sa couleur bleue naturelle unique), est un composant végétal extrait de l''huile de camomille, un puissant ingrédient calmant qui apaise et rafraîchit la peau enflammée. Il est également efficace pour la régénération cellulaire. Un extrait de Centella Asiatica, une plante originaire de Madagascar connue sous le nom d''herbe du tigre, aide la peau endommagée à se régénérer et prévient les cicatrices. Cette crème peut également être utilisée pour calmer la peau brûlée par le soleil, les rougeurs après le rasage et les irritations après l''extraction de boutons et les procédures laser.', 60, 'ml', 'dear-klairs-midnight-blue-calming-cream', 'https://korean-skincare.fr/products/dear-klairs-midnight-blue-calming-cream', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-midnight-blue-calming-cream.webp', 'Comme masque de nuit : Utilise-le à la fin de la routine beauté avant d''aller te coucher. Applique une quantité suffisante sur ta peau. Comme crème (le matin) : Utilise-la à la fin de la routine beauté et procède à ton maquillage habituel.', 2745, '2026-05-07 17:37:40.248736+00', '2026-06-14 15:14:07.789+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43a3-700f-ae8a-7a93b3d7078f', '__OWNER_ID__', 'All-day Airy Sunscreen SPF50+ PA++++', 'Dear Klairs', 'moisturizer', 'jar', 'Aqua, Adipate de Dibutyle, Salicylate de Butyloctyle, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Polysilicone-15, Benzoate d''Alkyle C12-15, Ethylhexyl Triazone, Méthoxyphényl Triazine de Bis-Éthylhexyloxyphénol, Polyméthylsilsesquioxane, Glycerin, Niacinamide, Stearate de Polyglycéryle-6, Olivate de Cétéaryle, Microcrystalline Cellulose, Panthenol, Silica, Sorbitan Olivate, Dipropylene Glycol, Hydroxyacetophenone, Acrylate d''Alkyle en C10-30, Behénate de Polyglycéryle-6, Allantoin, Caprylyl Glycol, Stearyl Alcohol, Glyceryl Stearate, Copolymère d''Acrylates/Alkyl Acrylate en C10-30, Tromethamine, Adenosine, Cetearyl Alcohol, Disodium EDTA, Butylene Glycol, Portulaca Oleracea Extract, Aloe Barbadensis Leaf Extract, Dioscorea Japonica Root Extract, Laminaria Japonica Extract, Extrait de Fleur de Viola Mandshurica, Ulmus Davidiana Root Extract, Dipotassium Glycyrrhizate, Extrait de Racine de Lepidium Meyenii, 1,2-Hexanediol, Extrait de Fruit de Lycium Chinense, Fragaria Chiloensis Fruit Extract, Extrait de Racine de Berberis Vulgaris, Extrait de Fruit de Morus Nigra', 'L''All-day Airy Sunscreen SPF50+ PA++++ Dear Klairs est un incontournable pour celles et ceux qui recherchent une crème solaire quotidienne au toucher léger et non collant. Avec une contenance de 50ml, cette crème solaire offre une expérience fraîche et agréable sans laisser de traces blanches, ce qui la rend idéale pour être utilisée lors de la dernière étape de ta routine de soin ou comme base de maquillage. Cette crème solaire a été testée de façon rigoureuse pour garantir son efficacité et s''assurer qu''elle soit sans risque pour tous les types de peaux. Elle a passé le test d''irritation cutanée primaire et le test d''irritation cutanée primaire pour peaux sensibles, ainsi que le test d''irritation oculaire. De plus, une évaluation de son effet apaisant sur la peau après une irritation due aux UV a été réalisée pour confirmer son efficacité. La crème solaire Dear Klairs All-day Airy Sunscreen est certifiée SPF50+ et PA++++ afin d''offrir une protection optimale contre les rayons UVA et UVB. Elle est idéale pour celles et ceux qui sont en permanence exposés au soleil ou bien qui passent beaucoup de temps à l''extérieur. Sa texture légère et son fini non gras la rendent facile à utiliser et à réappliquer tout au long de la journée, une garantie que ta peau restera protégée et en bonne santé.', 50, 'ml', 'dear-klairs-all-day-airy-sunscreen-spf50-pa', 'https://korean-skincare.fr/products/dear-klairs-all-day-airy-sunscreen-spf50-pa', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-all-day-airy-sunscreen-spf50-pa.webp', 'Applique une quantité suffisante de façon uniforme sur les zones exposées du visage/corps 30 minutes avant de sortir au soleil.', 1657, '2026-05-07 17:37:40.258889+00', '2026-06-14 15:14:07.789+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43ac-7e68-88a3-918bc275cd35', '__OWNER_ID__', 'Fundamental Nourishing Eye Butter', 'Dear Klairs', 'eye-cream', 'jar', 'Aqua, Glycerin, Stearic Acid, 1,2-Hexanediol, Helianthus Annuus Seed Oil, Betaine, Caffeine, Extrait de graine de Phaseolus Angularis, Artemisia Princeps Leaf Extract, Camellia Sinensis Leaf Extract, Extrait de fruit de Chaenomeles Sinensis, Extrait de Chrysanthellum Indicum, Extrait d''écorce de Cinnamomum Cassia, Extrait de Corallina Officinalis, Curcuma Longa Root Extract, Extrait de feuille de Diospyros Kaki, Extrait de fleur de Melia Azadirachta, Melia Azadirachta Leaf Extract, Ocimum Sanctum Leaf Extract, Acetyl Hexapeptide-8, Copper Tripeptide-1, Oligopeptide-29, Oligopeptide-32, Panthenol, Pantolactone, Hydrogenated Lecithin, Copolymère d''acrylate d''hydroxyéthyle/taurate d''acryloyldiméthyle de sodium, Sodium Hyaluronate, Glyceryl Stearate, Sorbitan Isostearate, Cetyl Alcohol, Propanediol, Arachidic Acid, Oleic Acid, Palmitic Acid, Glucoside de caprylyl/capryl, Ethylhexylglycerin', 'Le Fundamental Nourishing Eye Butter Dear Klairs est une crème hydratante contenant de l''huile de graines de tournesol et des peptides pour protéger la peau du contour des yeux tout en améliorant les ridules. Cette crème nourrissante pour les yeux convient à tout le monde, même aux personnes atteintes de grains de milium, car sa texture douce comme du beurre aide le produit à être absorbé rapidement. Cette crème est riche sans être grasse ou lourde.', 20, 'g', 'dear-klairs-fundamental-nourishing-eye-butter', 'https://korean-skincare.fr/products/dear-klairs-fundamental-nourishing-eye-butter', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-fundamental-nourishing-eye-butter.webp', 'Applique une quantité suffisante de produit autour de tes yeux Tapote délicatement pour aider à l''absorption. Termine ta routine avec une crème hydratante.', 2444, '2026-05-07 17:37:40.268706+00', '2026-06-14 15:14:07.79+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43b1-76d7-b96a-19be8f0a9b07', '__OWNER_ID__', 'Midnight Blue Calming Sheet Mask', 'Dear Klairs', 'mask', 'pack', 'Aqua, Butylene Glycol, Methylpropanediol, Glycereth-26, 1,2-Hexanediol, Salix Alba Bark Extract, Glycerin, Érythritol, Arginine, Carbomer, Carraghenane, Betaine, Allantoin, Ethylhexylglycerin, Propanediol, Polyglycéryl-10 laurate, Copolymère d''acrylate de glycéryl/acide acrylique, Copolymère PVM/MA, Disodium EDTA, Dipotassium Glycyrrhizate, Melaleuca Alternifolia Leaf Oil, Centella Asiatica Extract', 'Le Midnight Blue Calming Mask Dear Klairs est un masque calmant et rafraîchissant qui offre les mêmes bienfaits apaisants que la Midnight Blue Calming Cream, le best-seller de la marque. Ce masque tissu spécial en rayonne est formulé avec de l''érythritol pour rafraîchir la peau et soulager les irritations, et un extrait d''écorce de saule pour désincruster les pores et réduire la production de sébum. L''huile d''arbre à thé et l''extrait de Centella Asiatica sont également présents pour aider à calmer et à guérir les éruptions.', 1, 'pcs', 'dear-klairs-midnight-blue-calming-sheet-mask', 'https://korean-skincare.fr/products/dear-klairs-midnight-blue-calming-sheet-mask', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-midnight-blue-calming-sheet-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 337, '2026-05-07 17:37:40.273304+00', '2026-06-14 15:14:07.79+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43b3-7bca-b8a6-eaa1f23837d4', '__OWNER_ID__', 'Midnight Blue Youth Activating Drop', 'Dear Klairs', 'moisturizer', 'jar', 'Aqua, Butylene Glycol, sh-Oligopeptide-1, sh-Polypeptide-1, Vaccinium Angustifolium Fruit Extract, Lecithin, Sesquioleate de Sorbitan, 1,2-Hexanediol, Caprylyl Glycol, Huile de Ricin Hydrogénée PEG-60, Glycerin, Chlorphenesin, Guaiazulène, Ethylhexylglycerin, Adenosine', 'Le Midnight Blue Youth Activating Drop Dear KLAIRS est un sérum de nuit anti-âge qui aide à réparer la peau abîmée et à améliorer l''apparence des rides et ridules. Les principaux ingrédients EGF et bFGF sont des peptides de haute qualité connus pour leurs effets anti-âge, l''accélération de la régénération de la peau, le renforcement de la barrière cutanée, l''aide à la synthèse du collagène et la fermeté et l''élasticité de la peau. La présence de guaiazulène rend également ce sérum très efficace pour apaiser et réparer la peau irritée ou sensibilisée par les rayons ultraviolets, l''acné et d''autres facteurs.', 20, 'ml', 'dear-klairs-midnight-blue-youth-activating-drop', 'https://korean-skincare.fr/products/dear-klairs-midnight-blue-youth-activating-drop', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-midnight-blue-youth-activating-drop.webp', 'Applique 1 à 3 gouttes sur ta peau et masse délicatement en tapotant jusqu''à absorption complète.', 2934, '2026-05-07 17:37:40.275631+00', '2026-06-14 15:14:07.79+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43b6-7188-82be-f6859a4f5f1e', '__OWNER_ID__', 'Gentle Black Fresh Cleansing Oil', 'Dear Klairs', 'cleanser', 'tube', 'Helianthus Annuus Seed Oil, Caprylic/Capric Triglyceride, Triisostéarate de Glycéryl PEG-20, Vitis Vinifera Seed Oil, Simmondsia Chinensis Seed Oil, Huile de Graines de Ribes Nigrum (Cassis)', 'La Gentle Black Fresh Cleansing Oil Dear Klairs est une huile nettoyante quotidienne légère qui élimine efficacement le maquillage, l''huile et les résidus de saleté tout en hydratant la peau. Formulée avec des ingrédients riches en antioxydants tels que l''huile de graines de tournesol, l''huile de pépins de raisin, l''huile de graines de jojoba et l''huile de cassis, l''huile nettoyante Klairs contribue à donner à la peau une apparence plus jeune et plus éclatante. Elle élimine efficacement toutes les impuretés, prévient l''obstruction des pores et nettoie sans laisser de résidus collants ou gras.', 150, 'ml', 'dear-klairs-gentle-black-fresh-cleansing-oil', 'https://korean-skincare.fr/products/dear-klairs-gentle-black-fresh-cleansing-oil', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-gentle-black-fresh-cleansing-oil.webp', 'Applique une quantité appropriée de produit sur la peau Masse avec un mouvement circulaire. Rince à l''eau tiède.', 2542, '2026-05-07 17:37:40.277966+00', '2026-06-14 15:14:07.79+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43be-791a-9bf2-36e58d6315ed', '__OWNER_ID__', 'Supple Preparation All-Over Lotion', 'Dear Klairs', 'moisturizer', 'jar', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, Sodium Hyaluronate, Butyrospermum Parkii Butter, Ethylhexanoate de cétostearyle, Simmondsia Chinensis Seed Oil, Glyceryl Stearate, Stéarate de sorbitane, Cetyl Alcohol, Stearic Acid, Beta-Glucan, Sesquioleate de sorbitane, Microcrystalline Wax, Cyclopentasiloxane, Betaine, Ceramide NP, Polyquaternium-51, PEG-100 Stearate, Extrait de fruit d''Illicium Verum (Anis), Extrait de fruit de Citrus Paradisi (Pamplemousse), Extrait de fleur de Nelumbium Speciosum, Paeonia Suffruticosa Root Extract, Extrait de racine de Scutellaria Baicalensis, Dimethicone, Tocopheryl Acetate, Chlorphenesin, Carbomer, Arginine, Citric Acid, Ethylhexylglycerin, Portulaca Oleracea Extract, Althaea Rosea Flower Extract, Aloe Barbadensis Leaf Extract, Extrait d''Apium Graveolens (Céleri), Extrait de feuille de Brassica Oleracea Capitata (Chou), Brassica Oleracea Italica Extract, Extrait de feuille de Brassica Rapa (Navet), Daucus Carota Sativa Root Extract, Oryza Sativa Extract, Extrait de fruit/feuille/tige de Solanum Lycopersicum (Tomate), Gomme de Natto, Centella Asiatica Extract, Disodium EDTA, Lysine HCL, Proline, Phosphate de sodium ascorbyl, Acétyl méthionine, Théanine', 'La Supple Preparation All Over Lotion Dear Klairs est une lotion légère pour le visage et le corps qui pénètre rapidement et qui hydrate la peau sans la rendre grasse ou collante. Formulée avec de l''acide hyaluronique, du beurre de karité et de l''huile de graines de jojoba, cette lotion offre une hydratation puissante, tout en nourrissant la peau. Cette lotion multitâche peut être utilisée comme crème pour le corps, pour le visage, pour les mains et même comme revitalisant pour les cheveux !', 250, 'ml', 'dear-klairs-supple-preparation-all-over-lotion', 'https://korean-skincare.fr/products/dear-klairs-supple-preparation-all-over-lotion', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-supple-preparation-all-over-lotion.webp', 'Utilise à la fin de ta routine beauté de base et maquille-toi comme à ton habitude.', 2542, '2026-05-07 17:37:40.286443+00', '2026-06-14 15:14:07.791+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43e0-779e-9996-a9f7ea53ae72', '__OWNER_ID__', 'EGF Blue AC Calming Serum', 'Dear Klairs', 'serum', 'dropper', 'Aqua, Glycerin, 1,2-Hexanediol, Butylene Glycol, Niacinamide, Propanediol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, C12-14 Pareth-12, Tromethamine, Ammonium Acryloyldimethyltaurate/VP Copolymer, Allantoin, Ethylhexylglycerin, Adenosine, Xanthan Gum, Sodium Phytate, Melaleuca Alternifolia Leaf Oil, Melia Azadirachta Leaf Extract, Melia Azadirachta Flower Extract, Malachite Extract, Coccinia Indica Fruit Extract, Solanum Melongena Fruit Extract, Aloe Barbadensis Flower Extract, Sodium Hyaluronate, Ocimum Sanctum Leaf Extract, Hydroxycinnamic Acid, Curcuma Longa Root Extract, Corallina Officinalis Extract, Rutin, Capryloyl Salicylic Acid, Guaiazulene, Gluconolactone, Sea Water, Sodium PCA, Dipropylene Glycol, Panthenol, Brassica Oleracea Capitata Leaf Extract, Camellia Sinensis Leaf Extract, Centella Asiatica Extract, Hydrogenated Lecithin, Sorbitan Olivate, Cetearyl Olivate, Houttuynia Cordata Extract, Brassica Oleracea Italica Extract, Glycine, Serine, Glutamic Acid, sh-Oligopeptide-1, Aspartic Acid, Leucine, Alanine, Lysine, Arginine, Tyrosine, Phenylalanine, Valine, Threonine, Proline, Isoleucine, Histidine, Methionine, Cysteine', 'L''EGF Blue AC Calming Serum Dear Klairs est un soin ciblé conçu pour calmer les imperfections, réduire les rougeurs et soutenir la récupération de la peau, tout en offrant des bienfaits anti-âge. Enrichi en EGF (Epidermal Growth Factor) et en ingrédients apaisants bleus comme le guaiazulène et le panthénol, ce sérum léger aide à apaiser les peaux irritées et à tendance acnéique tout en favorisant le renouvellement cellulaire et en améliorant la texture de la peau. Idéal pour les peaux sensibles ou sujettes aux imperfections, la formule à absorption rapide et non collante se superpose facilement sous d’autres soins ou le maquillage. Une utilisation régulière de l''EGF Blue AC Calming Serum Dear Klairs aide à renforcer la barrière cutanée, estomper les marques post-acné et révéler un teint plus lisse, pur et équilibré. Recommandé pour : Tous types de peaux.', 50, 'g', 'dear-klairs-egf-blue-ac-calming-serum', 'https://korean-skincare.fr/products/dear-klairs-egf-blue-ac-calming-serum', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-egf-blue-ac-calming-serum.webp', 'Après le nettoyage et l’application d’un tonique, applique quelques gouttes uniformément sur ton visage, en insistant sur les zones irritées ou sujettes aux imperfections. Tapote doucement pour faire pénétrer. Utilise matin et soir.', 2297, '2026-05-07 17:37:40.320299+00', '2026-06-14 15:14:07.791+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43ba-74ff-86b6-c453fe027e40', '__OWNER_ID__', 'Daily Comfort Hand Cream', 'Dear Klairs', 'hand-cream', 'jar', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, Helianthus Annuus Seed Oil, Undécane, Distearate de Polyglycéryl-3, 1,2-Hexanediol, Tridécane, Butyrospermum Parkii Butter, Stearyl Alcohol, Hydrogenated Lecithin, Citrate de Glycéryle Stéarate, Trehalose, Extrait d''Écorce de Betula Platyphylla Japonica, Huile de Graine d''Orbignya Oleifera, Panthenol, Pantolactone, Pentylene Glycol, Tocopherol, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Hyroxypropyltrimonium Hyaluronate, Potassium Hyaluronate, Sodium Hyaluronate, Copolymère de Hyaluronate de Sodium, Sodium Acetyl Hyaluronate, Alcool Arachidyle, Behenyl Alcohol, Cetyl Alcohol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Trométamine, Carbomer, Acide Behénique, Myristic Acid, Stearic Acid, Glycérine Éthylhexyle', 'La Daily Comfort Hand Cream Dear Klairs nourrit et hydrate intensément tes mains et tes ongles sans coller. Infusée d''extrait de bouleau et d''huile de graines de babassu, cette crème à absorption rapide garde ta peau douce et saine tout en contribuant au soin des ongles. Testée dermatologiquement, elle est sans risque même pour les peaux sensibles et garantit une hydratation délicate tout au long de la journée. Avec du beurre de karité apaisant et un mélange d''acide hyaluronique, elle emprisonne l''hydratation pour une douceur et un confort durables. Idéale pour un usage quotidien, cette crème pour les mains te laissera une sensation de douceur et de fraîcheur.', 370, 'g', 'dear-klairs-daily-comfort-hand-cream', 'https://korean-skincare.fr/products/dear-klairs-daily-comfort-hand-cream', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-daily-comfort-hand-cream.webp', 'Distribue une quantité appropriée de la crème pour les mains et applique-la sur tes mains sèches. Applique fréquemment après t''être lavé les mains ou lorsque tu constates une sécheresse.', 2895, '2026-05-07 17:37:40.282208+00', '2026-06-14 15:14:07.791+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43bc-783e-b34d-adff7d9c2cd0', '__OWNER_ID__', 'Gentle Black Facial Cleanser', 'Dear Klairs', 'cleanser', 'jar', 'Aqua, Glycerin, Glycinate de Sodium Cocoyl, Glutamate de Sodium Lauroyl, 1,2-Hexanediol, Phosphate d''Amidon Hydroxypropyle, Betaïne Lauryle, Hydroxyacetophenone, Ethylhexylglycerin, Sodium Chloride, Décylène Glycol, Butylene Glycol, Dipropylene Glycol, Laminaria Japonica Extract, Eclipta Prostrata Leaf Extract, Extrait de Graine de Nigella Sativa, Hydrogenated Lecithin, Fructooligosaccharides, Extrait de Graine d''Amaranthus Caudatus, Ulmus Davidiana Root Extract, Beta-Glucan, Ficus Carica Fruit Extract, Centella Asiatica Extract, Rubus Fruticosus Fruit Extract, Hydrolyzed Hyaluronic Acid, Extrait de Tuber Melanosporum, Tocopherol, Ceramide NP, Extrait de Graine de Glycine Soja, Acide Aspartique, Acetyl Hexapeptide-8', 'La Rich Moist Foaming Cleanser Dear Klairs est un nettoyant à faible pH qui élimine efficacement les impuretés tout en laissant la peau hydratée. Sa texture crémeuse et dense est douce sur la peau, ce qui la rend adaptée aux types de peau les plus sensibles. Infusée d''un complexe noir nourrissant de truffe, d''extrait de fruit de mûre, d''extrait de graine de Nigella Sativa et d''extrait de graine de soja, cette mousse nettoyante améliore l''hydratation et la santé de la peau. Elle nettoie sans décaper la peau de ses huiles naturelles, la laissant lisse et rafraîchie. Le Gentle Black Facial Cleanser Dear Klairs est le complément parfait à ta routine beauté quotidienne, assurant un nettoyage doux mais efficace à chaque utilisation.', 140, 'ml', 'dear-klairs-gentle-black-facial-cleanser', 'https://korean-skincare.fr/products/dear-klairs-gentle-black-facial-cleanser', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-gentle-black-facial-cleanser.webp', 'Distribue une quantité appropriée de nettoyant sur tes paumes mouillées. Fais mousser la mousse en frottant par de légers mouvements circulaires puis nettoie ton visage en profondeur. Rince avec de l''eau tiède.', 2195, '2026-05-07 17:37:40.284431+00', '2026-06-14 15:14:07.791+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43c2-7de6-902a-c3200ce7b9d8', '__OWNER_ID__', 'Freshly Juiced Vitamin E Mask', 'Dear Klairs', 'mask', 'pack', 'Aqua, Glycerin, Butylene Glycol, Tocopheryl Acetate, Niacinamide, Sodium Hyaluronate, Carraghenane, Gomme Gellane, Betaine, Algine, Mannane, Ceramide NP, Huile de Ricin Hydrogénée PEG-60, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Chlorphenesin, Arginine, Ethylhexylglycerin, Centella Asiatica Extract, Rubus Fruticosus Fruit Extract, Extrait de Salicornia Herbacea, Extrait de Phragmites Communis, Adenosine, Lavandula Angustifolia Oil, Eucalyptus Globulus Leaf Oil, Pelargonium Graveolens Oil, Citrus Limon Peel Oil, Citrus Aurantium Dulcis Peel Oil, Cananga Odorata Flower Oil', 'Le Freshly Juiced Vitamin E Mask Dear Klairs est le booster ultime qui fournit un excellent pouvoir antioxydant et présente de nombreux avantages pour les peaux sèches, sensibles et vieillissantes. La vitamine E est un antioxydant qui protège la peau de l''invasion d''éléments extérieurs. Avec l''aide de l''adénosine et de la niacinamide, ce produit éclaircit le teint, prévient les rides et hydrate la peau. La texture de ce masque, semblable à un pudding, se transforme en une essence riche au contact de la peau et maintient l''hydratation pendant au moins 8 heures, même sur une peau sèche. Lorsqu''il est utilisé pendant la journée, il peut aider à protéger la peau des rayons du soleil et à prévenir les dommages qu''ils peuvent causer. Son efficacité est renforcée lorsqu''il est utilisée avec de la vitamine C, car la vitamine E la stabilise. Lorsqu''il est appliqué après la Vitamin Drop KLAIRS par exemple, ce masque à la vitamine E contribue à renforcer les effets éclaircissants de la vitamine C présente dans le sérum.', 90, 'ml', 'dear-klairs-freshly-juiced-vitamin-e-mask', 'https://korean-skincare.fr/products/dear-klairs-freshly-juiced-vitamin-e-mask', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-freshly-juiced-vitamin-e-mask.webp', 'Comme masque de nuit : Utilise-le à la fin de la routine beauté avant de te coucher. Applique une quantité suffisante de produit sur ta peau. Comme masque à rincer : Applique une quantité généreuse de masque et laisse-le agir pendant 15 minutes. Rince-le avec un tonique ou de l''eau tiède. Comme crème (le matin) : Utilise-le à la fin de ta routine beauté et passe à l''étape normale du maquillage.', 2689, '2026-05-07 17:37:40.290743+00', '2026-06-14 15:14:07.792+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43c5-724e-8f25-a5ef16784e76', '__OWNER_ID__', 'Gentle Black Sugar Facial Polish', 'Dear Klairs', 'moisturizer', 'jar', 'Caprylic/Capric Triglyceride, Sucre, Cetyl Ethylhexanoate, Glycerin, Butyrospermum Parkii Butter, Tocopheryl Acetate, Euphorbia Cerifera Cera, PEG-7 Cocoate de Glycéryle, Polysorbate 20, Microcrystalline Wax, Cetyl Alcohol, Mélasse, Poudre de Racine de Glycyrrhiza Glabra (Réglisse), Parfum, Huile de Graines de Carapa Guaianensis, Huile de Graines de Vaccinium Macrocarpon (Canneberge)', 'Le Gentle Black Sugar Facial Polish de Dear Klairs est un gommage doux pour le visage à base de sucre noir qui nettoie ta peau en profondeur, tout en éliminant les cellules mortes et les points noirs. Formulé avec du beurre de karité, de l''huile de canneberge et de la vitamine E pour hydrater et protéger les peaux sensibles de toute démangeaison et irritation après le nettoyage. Obtiens instantanément une peau lisse, douce et éclatante !', 110, 'g', 'dear-klairs-gentle-black-sugar-facial-polish', 'https://korean-skincare.fr/products/dear-klairs-gentle-black-sugar-facial-polish', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-gentle-black-sugar-facial-polish.webp', 'Après le nettoyage, applique sur ton visage, en évitant le contour des yeux et de la bouche. Après 10 à 15 minutes, rince soigneusement à l''eau tiède.', 2346, '2026-05-07 17:37:40.292977+00', '2026-06-14 15:14:07.792+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43c7-772f-a6b4-38ec09ff42ad', '__OWNER_ID__', 'Rich Moist Foaming Cleanser', 'Dear Klairs', 'cleanser', 'tube', 'Aqua, Sodium Lauroyl Sarcosinate, Glycerin, Propylene Glycol, Lauric Acid, Caprylic/Capric Triglyceride, Sodium Hyaluronate, Diméthyl sulfone, Potassium Hydroxide, Glycyrrhiza Glabra Root Extract, Betaine, Stearic Acid, Chamaecyparis Obtusa Water, Ananas Sativus Fruit Extract, Chlorphenesin, Melaleuca Alternifolia Leaf Oil, Extrait de fruit d''Illicium verum (anis), Extrait de fruit de Citrus paradisi (pamplemousse), Extrait de fleur de Nelumbium speciosum (lotus), Paeonia Suffruticosa Root Extract, Extrait de racine de Scutellaria baicalensis, Panthenol, Citric Acid, Pyridoxine, Extrait de graine de Linum usitatissimum (lin), Hibiscus Esculentus Fruit Extract, Aloe Barbadensis Leaf Juice, Arctium Lappa Root Extract, Extrait de fleur d''Hibiscus mutabilis, Extrait de feuille de Corchorus olitorius, Protéine de pois hydrolysée, Lecithin, Olea Europaea Fruit Oil, Phytostérols, Squalane, Butyrospermum Parkii Butter, Ceramide NP, Propanediol, Extrait d''Apium graveolens (céleri), Extrait de feuille de Brassica oleracea capitata (chou), Brassica Oleracea Italica Extract, Extrait de feuille de Brassica rapa (navet), Daucus Carota Sativa Root Extract, Oryza Sativa Extract, Extrait de fruit/feuille/tige de Solanum lycopersicum (tomate), Lysine hcl, Proline, Sodium Ascorbyl Phosphate, Méthionine acétylée, Théanine, Tocopheryl Acetate, Extrait de culture de callus de Panax ginseng, Extrait de feuille/racine/tige de Piper methysticum, Centella Asiatica Extract, Portulaca Oleracea Extract, Beta-Glucan, Papaïne', 'La Rich Moist Foaming Cleanser Dear Klairs est un produit hydratant qui convient à tous les types de peau. Il maintient la peau hydratée même après le nettoyage, pour éviter toute sensation de sécheresse ou de tiraillement normalement associée aux mousses nettoyantes. Formulé avec de l''acide hyaluronique et de l''extrait de feuille d''aloès pour calmer et nourrir la peau, ce nettoyant hypoallergénique est également parfait pour les peaux sensibles. Si tu as une peau à tendance acnéique, tu vas adorer l''huile de feuilles d''arbre à thé, qui aide à combattre les éruptions cutanées et t''aidera à retrouver une peau plus claire.', 100, 'ml', 'dear-klairs-rich-moist-foaming-cleanser', 'https://korean-skincare.fr/products/dear-klairs-rich-moist-foaming-cleanser', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-rich-moist-foaming-cleanser.webp', 'Distribue une certaine quantité de produit sur tes mains mouillées pour créer de la mousse. Applique soigneusement sur ton visage Rince soigneusement à l''eau tiède.', 1845, '2026-05-07 17:37:40.295293+00', '2026-06-14 15:14:07.792+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43c9-7d2b-9421-830c65994581', '__OWNER_ID__', 'Maple Energy Infusing Cream', 'Dear Klairs', 'moisturizer', 'jar', 'Sève d’Érable à Sucre (Acer Saccharum Sap), Glycerin, Propanediol, Glycéride Végétal Hydrogéné Acétylé, Squalane, Methyl Gluceth-20, Aqua, 1,2-Hexanediol, Dicaprylate/Dicaprate de Butylene Glycol, Glycérides de Noix de Coco Hydrogénés, Hydrogenated Polyisobutene, Cetearyl Alcohol, Ferment de Riz/Lactobacillus, Cire d’Abeille Synthétique, Dipentaérythrityl Hexa C5-9 Acide Esters, Polyglycéryl-3 Stéarate, Rosinate Hydrogéné Méthylé, Stéarate de Sorbitan, Silica, Maltitol, Olivate de Cétéaryle, Glycérides d’Huile de Graine de Tournesol, Carbomer, Tromethamine, Sorbitan Olivate, Glyceryl Caprylate, Glutamate de Stéaroyle de Sodium, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Copolymère d’Éthylène/Propylène/Styrene, Extrait d’Hibiscus Abelmoschus, Dipotassium Glycyrrhizate, Extrait de Racine d’Igname du Japon (Dioscorea Japonica), Ethylhexylglycerin, Adenosine, Extrait d’Écorce d’Érable Rouge (Acer Rubrum), Extrait de Graine de Chia (Salvia Hispanica), Extrait de Graine de Lin (Linum Usitatissimum), Biosaccharide Gum-1, Asiaticoside, Arginine, Sorbitan Isostearate, Copolymère de Butylène/Éthylène/Styrene, Dextrin, Caprylyl Glycol, Hydroxyéthylcellulose Cétylique, Rutine, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Acetyl Hexapeptide-8, Palmitoyl Tripeptide-1, Palmitoyl Tetrapeptide-7, Tocopherol, Extrait de Graine de Haricot de Lima (Phaseolus Lunatus)', 'Découvre le pouvoir revitalisant de la Maple Energy Infusing Cream Dear Klairs, une crème hydratante anti-âge luxueuse qui transforme la peau sèche et affaissée en une vision d''éclat et de jeunesse. Infusée d''essence naturelle de sirop d''érable revitalisant, de squalane et d''un puissant complexe de 3 peptides, cette crème hydrate et nourrit en profondeur, renforçant la barrière cutanée jusqu''à 65,95 % en seulement 30 minutes. Elle repulpe et raffermit immédiatement la peau en lissant les rides et ridules sur 12 zones clés du visage, y compris la zone délicate des yeux, le front et les lèvres, laissant ton teint souple, énergisé et irrésistiblement éclatant d''une vitalité semblable à du sirop. Sa texture riche et épaisse fonctionne en synergie avec les sérums hydratants pour améliorer la densité de la peau, favoriser l''élasticité et combattre les signes du vieillissement, ce qui donne une apparence plus ferme et plus saine au fil du temps. Idéale pour tous les types de peau à la recherche de bienfaits pour ralentir le vieillissement, la Maple Energy Infusing Cream Dear Klairs exploite les bienfaits de la nature pour redonner du rebond et de la luminosité à ta peau, te permettant ainsi d''affronter chaque jour avec confiance et un éclat naturellement radieux. Recommandé pour : Peaux sensibles, sèches, tous types de peaux.', 60, 'g', 'dear-klairs-maple-energy-infusing-cream', 'https://korean-skincare.fr/products/dear-klairs-maple-energy-infusing-cream', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-maple-energy-infusing-cream.webp', 'Après avoir nettoyé ta peau et avoir appliqué un tonique, applique une quantité appropriée de crème sur ton visage. Masse délicatement en effectuant des mouvements ascendants jusqu''à absorption complète. Utilise-la quotidiennement lors de la dernière étape de ta routine beauté.', 2195, '2026-05-07 17:37:40.297679+00', '2026-06-14 15:14:07.793+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43cc-73cc-a738-6dd1b966c3ea', '__OWNER_ID__', 'All-Day Airy Mineral Sunscreen', 'Dear Klairs', 'moisturizer', 'jar', 'Aqua, Zinc Oxide, Salicylate de Butyloctyle, Caprylate de Propylheptyl, Propanediol, Ethylhexanoate de Cétéaryle, Huile de Coco Hydrogénée, Isododecane, Zinc Oxide, Niacinamide, Polyglyceryl-6 Polyricinoleate, Glycerin, Sodium Chloride, Moringa Oleifera Seed Oil, Camellia Sinensis Leaf Extract, Disteardimonium Hectorite, Triethylhexanoin, Methyl Methacrylate Crosspolymer, Triethoxycaprylylsilane, 1,2-Hexanediol, Ectoin, Polyglyceryl-2 Dipolyhydroxystearate, Polymethyl Methacrylate, Panthenol, Butylene Glycol, Lauryl Dimethicone/Polyglycerin-3 Crosspolymer, Caprylyl Glycol, Glyceryl Caprylate, Ceramide NP, Phytosphingosine, Hydrogenated Lecithin, Dipropylene Glycol, Tocopherol, Sodium Citrate', 'Découvre la All-Day Airy Mineral Sunscreen Dear Klairs, ton nouveau rituel quotidien pour une protection solaire sans inquiétude, surtout si tu as la peau sensible. Cette formule minérale avancée offre une protection SPF50+ PA++++ ultra efficace, rigoureusement éprouvée par des tests complets d''évaluation FPS et PFA (UVA), pour protéger ta peau des rayons UV nocifs. Ce qui la distingue vraiment, c''est sa capacité unique à uniformiser naturellement le teint de ta peau sans laisser de traces blanches ni de résidus collants, se fondant parfaitement pour un fini frais et naturel qui laisse transparaître ta vraie peau. Au-delà d''une protection exceptionnelle, cette crème solaire est un soin doux, attesté par des tests approfondis, notamment des tests d''irritation cutanée primaire (même pour les peaux sensibles) et un test d''irritation oculaire, ce qui la rend idéale même pour les teints les plus délicats. Tu peux compter sa non comédogénicité et son effet régulateur de sébum pendant 12 heures, qui maintiennent ta peau équilibrée et sans brillance toute la journée. De plus, grâce à un test triple de prévention des dommages cutanés liés à l''exposition aux UV et à un rapport méticuleux sur la taille des particules, tu choisis une crème solaire qui est non seulement efficace, mais aussi incroyablement confortable et scientifiquement validée pour la santé de ta peau. Recommandé pour : Peaux sensibles, tous types de peaux.', 60, 'g', 'dear-klairs-all-day-airy-mineral-sunscreen', 'https://korean-skincare.fr/products/dear-klairs-all-day-airy-mineral-sunscreen', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-all-day-airy-mineral-sunscreen.webp', 'Applique uniformément une quantité suffisante lors de la dernière étape de ta routine beauté sur les zones exposées aux rayons UV. Applique la crème par petites sections si nécessaire et étale soigneusement. Si tu prévois de te maquiller, applique ton fond de teint ou ton coussin en tapotant doucement, plutôt qu''en frottant, pour ne pas perturber la couche de crème solaire. Conseil : Veille à toujours bien nettoyer ton visage à la fin de la journée pour éliminer toute trace de crème solaire, de maquillage et d''impuretés. Il est fortement recommandé d''utiliser un nettoyant à base d''huile suivi d''un nettoyant à base d''eau (double nettoyage), en particulier lorsque tu utilises un FPS.', 2295, '2026-05-07 17:37:40.30002+00', '2026-06-14 15:14:07.793+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43ce-77b5-bb74-80c3416c4da0', '__OWNER_ID__', 'Midnight Blue Clearing Water Cream', 'Dear Klairs', 'moisturizer', 'jar', 'Eau Florale d’Anthemis Nobilis, Aqua, Butylene Glycol, Propanediol, Niacinamide, 1,2-Hexanediol, Caprylic/Capric Triglyceride, Ammonium Acryloyldimethyltaurate/VP Copolymer, Carbomer, Arginine, Glucoside de Lauryle, Laurate de Polyglycéryl-6, Allantoin, Glycerin, Ethylhexylglycerin, Glucoside de Myristyle, Gomme Xanthane, Guaiazulène, Pentylene Glycol, Sodium Hyaluronate, Madecassoside, Decyl Glucoside, Caprylyl Glycol, Hydroxypropyltrimonium Hyaluronate, Extrait de Feuille de Mentha Rotundifolia, Camellia Sinensis Leaf Extract, Extrait de Feuille de Thymus Vulgaris, Sodium Acetylated Hyaluronate, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hydrolyzed Sodium Hyaluronate, Potassium Hyaluronate, sh-Polypeptide-9, sh-Polypeptide-11, sh-Polypeptide-1, sh-Oligopeptide-2, sh-Oligopeptide-1', 'La Midnight Blue Clearing Water Cream Dear Klairs est une crème hydratante légère sous forme de gel conçue pour apaiser, rafraîchir et réparer les peaux sensibles et irritées. Grâce à la formule Blue Calming Formula™ exclusive de la marque, qui contient du guaiazulène, des peptides EGF et du madécassoside, elle soulage instantanément la sensibilité à la chaleur en réduisant la température de la peau. Cette crème non comédogène cible les rougeurs, les boutons, le teint terne et la pigmentation tout en boostant l''hydratation grâce à 8 types d''acide hyaluronique. Avec du niacinamide éclaircissant et des plantes apaisantes, elle hydrate, équilibre la production de sébum et aide à révéler un teint plus pur, plus calme et plus éclatant. Recommandé pour : Peaux sensibles, tous types de peaux.', 50, 'g', 'dear-klairs-midnight-blue-clearing-water-cream', 'https://korean-skincare.fr/products/dear-klairs-midnight-blue-clearing-water-cream', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-midnight-blue-clearing-water-cream.webp', 'Applique une petite quantité de crème hydratante sur les zones souhaitées à la fin de ta routine beauté.', 2695, '2026-05-07 17:37:40.302361+00', '2026-06-14 15:14:07.793+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4441-75c2-a777-541ad7991fbc', '__OWNER_ID__', 'Royal Vita Propolis 33 Eye Cream', 'Dr. Ceuracle', 'eye-cream', 'jar', 'Aqua, Butylene Glycol, Extrait de Fruit d''Argousier (Hippophae Rhamnoides), Huile Végétale, Distearate de Polyglyceryl-3 Méthylglucose, Niacinamide, 1,2-Hexanediol, Ammonium Acryloyldimethyltaurate/VP Copolymer, Camellia Japonica Seed Oil, 3-O-Ethyl Ascorbic Acid, Laminaria Japonica Extract, Eclipta Prostrata Leaf Extract, Centella Asiatica Extract, Ficus Carica Fruit Extract, Phellodendron Amurense Bark Extract, Extrait de Gelée Royale, Extrait d''Hamamélis de Virginie (Hamamelis Virginiana), Extrait d''Acmella Oleracea, Extrait de Pourpier (Portulaca Oleracea), Rosmarinus Officinalis Leaf Extract, Chamomilla Recutita (Matricaria) Flower Extract, Theobroma Cacao Seed Extract, Extrait de Graine de Lupinus Albus, Huile d''Orange (Citrus Aurantium Dulcis), Eau de Fleur de Rosa Centifolia, Sodium Hyaluronate, Hydrogenated Lecithin, Huile de Pelure de Mandarine (Citrus Nobilis), Helianthus Annuus Seed Oil, Litsea Cubeba Fruit Oil, Glutamate de Stéaroyle de Sodium, Adenosine, Fructooligosaccharides, Beta-Glucan, Hydrolyzed Hyaluronic Acid, Dextrin, Ceramide NP, Tocopherol, Hydroxyacetophenone, Ethylhexylglycerin', 'La Royal Vita Propolis 33 Eye Cream Dr. Ceuracle possède une formule légère, semblable à un sérum, qui revitalise et nourrit immédiatement la peau délicate du contour des yeux. Elle est infusée avec 33% d''extrait de propolis, et d''extrait de gelée royale, qui agissent ensemble pour hydrater et réparer la peau, lui laissant un teint plus éclatant et plus jeune. Sa formule comprend également de l''extrait de fruit d''argousier riche en antioxydants, de la vitamine C et E et du collagène qui agissent ensemble pour protéger et renforcer la barrière d''hydratation. La crème est livrée avec un embout de massage doré qui renforce l''effet rafraîchissant de la crème, ce qui la rend parfaite pour les peaux fatiguées, déshydratées et le contour des yeux sensible.', 20, 'ml', 'dr-ceuracle-royal-vita-propolis-33-eye-cream', 'https://korean-skincare.fr/products/dr-ceuracle-royal-vita-propolis-33-eye-cream', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-royal-vita-propolis-33-eye-cream.webp', 'Applique une quantité appropriée de produit sur la zone du contour des yeux. Avec l''applicateur, masse délicatement pour une absorption complète.', 2895, '2026-05-07 17:37:40.417265+00', '2026-06-14 15:14:07.801+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43d0-7c18-9c96-00073d060970', '__OWNER_ID__', 'Vita 10 Radiance Sheet Mask', 'Dear Klairs', 'mask', 'pack', 'Aqua, Butylene Glycol, Niacinamide, 1,2-Hexanediol, Glycerin, Erythritol, Arginine, Carbomer, Allantoin, Panthenol, Ethylhexylglycerin, Dipotassium Glycyrrhizate, Polyglyceryl-10 Laurate, Adenosine, Sodium Phytate, Sodium Hyaluronate, Dimethylsilanol Hyaluronate, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Glutathione, Hydrogenated Lecithin, Potassium Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Sodium Hyaluronate Crosspolymer, Sodium Hyaluronate Dimethylsilanol, Sodium Acetylated Hyaluronate, Sodium Ascorbyl Phosphate, Borago Officinalis Extract, Chamomilla Recutita (Matricaria) Flower Extract, Centaurea Cyanus Flower Extract, Hyacinthus Orientalis Extract, Lavandula Angustifolia Flower Extract, Salvia Sclarea Extract, Disodium EDTA, Ceramide NP, Ascorbic Acid, Biotin, Cyanocobalamin, Folic Acid, Pyridoxine, Riboflavin, Thiamine HCl, Nelumbo Nucifera Leaf Extract, Sodium DNA', 'Le Vita 10 Radiance Sheet Mask Dear Klairs est un soin booster d’éclat conçu pour illuminer les peaux ternes et irrégulières grâce à un puissant mélange de 10 multivitamines. Le tissu doux et respirant épouse la peau pour une absorption optimale et une expérience rafraîchissante digne d’un spa. Idéal pour tous les types de peaux, y compris les peaux sensibles, ce masque apporte une hydratation immédiate et des bienfaits éclaircissants à long terme. Que ce soit pour préparer une grande journée ou redonner vie à un teint fatigué, le Vita 10 Radiance Sheet Mask Dear Klairs aide à révéler un teint plus uniforme, lumineux et sain. Recommandé pour : Tous types de peaux.', 1, 'pcs', 'dear-klairs-vita-10-radiance-sheet-mask-set', 'https://korean-skincare.fr/products/dear-klairs-vita-10-radiance-sheet-mask-set', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-vita-10-radiance-sheet-mask-set.webp', 'Après le nettoyage et l’application d’un tonique, applique le masque uniformément sur ton visage. Laisse poser 15 à 20 minutes, puis retire-le et tapote doucement l’essence restante sur la peau. Utilise 2 à 3 fois par semaine pour de meilleurs résultats.', 295, '2026-05-07 17:37:40.304651+00', '2026-06-14 15:14:07.793+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43d2-7e3b-935a-87abee71e155', '__OWNER_ID__', 'Freshly Juiced Vitamin Skin Prep Pads', 'Dear Klairs', 'exfoliant', 'pack', 'Aqua, Butylene Glycol, Glycerin, Methylpropanediol, Niacinamide, 1,2-Hexanediol, Isopentyldiol, Gluconolactone, Arginine, Allantoin, Laurate de Polyglycéryl-10, Ethylhexylglycerin, Gomme Xanthane, Adenosine, Sodium Phytate, Ascorbic Acid, Ascorbyl Tetraisopalmitate, Caprylic/Capric Triglyceride, Lactate de Menthyle, Éthyl Menthane Carboxamide, Sodium Hyaluronate, Centella Asiatica Extract, Méthyl Diisopropyl Propionamide, Hydroxypropyltrimonium Hyaluronate, Extrait de Coriandre (Coriandrum Sativum), Glutathione, Hydrogenated Lecithin, Hydrolyzed Hyaluronic Acid, Sodium Acetyl Hyaluronate, Vinaigre, Hyaluronic Acid, Disodium EDTA, Hydrolyzed Sodium Hyaluronate, Copolymère de Hyaluronate de Sodium, Ceramide NP, Sodium Ascorbyl Phosphate, Potassium Hyaluronate, Asiaticoside, Madecassoside, Acide Asiatique, Acide Madécassique, Biotin, Cyanocobalamin, Acide Folique, Pyridoxine, Riboflavine, Thiamine HCl', 'Les Freshly Juiced Vitamin Skin Prep Pads sont des lingettes multifonctions conçues pour rafraîchir, lisser et illuminer le teint tout en préparant la peau au maquillage. La formule combine des actifs éclaircissants puissants tels que le niacinamide et des dérivés de vitamine C avec dix types d’acide hyaluronique pour offrir à la fois correction du teint et hydratation. Avec des bénéfices ciblés comme le soin des taches grâce au glutathion liposomal, l’apaisement de la barrière cutanée via l’extrait de centella, et un design de lingette séparée pour une utilisation localisée, ce produit offre dix bienfaits en un seul geste, incluant une meilleure adhérence du maquillage, un éclat renforcé, une texture lisse et un affinement des pores. Recommandé pour : Tous types de peaux.', 290, 'ml', 'dear-klairs-freshly-juiced-vitamin-skin-prep-pads', 'https://korean-skincare.fr/products/dear-klairs-freshly-juiced-vitamin-skin-prep-pads', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-freshly-juiced-vitamin-skin-prep-pads.webp', 'Après le nettoyage, prends une lingette et essuie délicatement ton visage du centre vers l’extérieur, en évitant le contour des yeux. Pour un effet type masque, sépare la lingette en sections et place-les sur les zones nécessitant une attention particulière pendant 3 à 5 minutes ; retire-les ensuite et tapote doucement l’essence restante sur la peau. Astuce : Garde le contenant à la verticale et referme-le soigneusement après usage pour éviter le dessèchement des lingettes restantes.', 1571, '2026-05-07 17:37:40.306785+00', '2026-06-14 15:14:07.794+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43d5-701a-ac0d-06af3d91cc65', '__OWNER_ID__', 'Freshly Juiced Vitamin Mask Cleanser', 'Dear Klairs', 'mask', 'pack', 'Glycerin, Aqua, Myristic Acid, Potassium Hydroxide, Palmitic Acid, Stearic Acid, Glyceryl Stearate SE, Sorbitan Olivate, Lauric Acid, Taurate de Méthyl Cocoyl de Sodium, Phosphate d’Amidon Hydroxypropyl, Glycinate de Cocoyl de Potassium, Hydroxysultaine de Lauryle, Glycol Distearate, Poudre d’Écorce de Citrus Unshiu, Dipropylene Glycol, Kaolin, Polyquaternium-7, Hydroxyacetophenone, Huile d’Écorce d’Orange Citrus Aurantium Dulcis, Caprylyl Glycol, Sodium Chloride, Gluconolactone, Sodium Phytate, Extrait de Fleur de Melia Azadirachta, Ocimum Sanctum Leaf Extract, Melia Azadirachta Leaf Extract, Curcuma Longa Root Extract, Extrait de Corallina Officinalis, Panthenol, Sodium Benzoate, Dipotassium Glycyrrhizate, Niacinamide, Ascorbic Acid, Glutathione, Butylene Glycol, Caprylic/Capric Triglyceride, 1,2-Hexanediol, Hydrogenated Lecithin, Sodium Hyaluronate, Beta-Glucan, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Hydroxypropyltrimonium Hyaluronate, Hydrolyzed Sodium Hyaluronate, Potassium Hyaluronate, Pentylene Glycol, Copolymère de Hyaluronate de Sodium, Sodium Acetyl Hyaluronate, Limonene', 'Le Freshly Juiced Vitamin Mask Cleanser Dear, Klairs est un soin polyvalent « 2-en-1 » qui agit à la fois comme un nettoyant riche et crémeux et comme un masque pour un renouvellement cutané plus profond. La formule associe de l’argile dorée et du gluconolactone (PHA) pour aider à purifier les pores, réduire les points noirs et exfolier en douceur les cellules mortes de la peau. Elle contient également des agents éclaircissants puissants, de la vitamine C pure, du niacinamide et du glutathion, pour unifier le teint, booster l’éclat et affiner la texture. Conçue pour tous types de peaux et particulièrement bénéfique pour les peaux présentant des pores visibles, une texture irrégulière, un teint terne ou congestionné, cette combinaison mousse et masque offre à la fois un nettoyage quotidien et un soin intensif ponctuel. Recommandé pour : Tous types de peaux.', 150, 'ml', 'dear-klairs-freshly-juiced-vitamin-mask-cleanser', 'https://korean-skincare.fr/products/dear-klairs-freshly-juiced-vitamin-mask-cleanser', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-freshly-juiced-vitamin-mask-cleanser.webp', 'Comme nettoyant : Distribue une quantité appropriée de produit, fais mousser pour obtenir une mousse dense, puis masse délicatement sur ton visage humide, ensuite rince soigneusement à l’eau tiède. Comme masque : Applique une couche plus épaisse (surtout sur la zone T ou les joues) et laisse poser 3 à 5 minutes. Ajoute ensuite de l’eau tiède, masse pour transformer en mousse, puis rince. Astuce : Les jours où la peau est congestionnée ou a besoin d’un coup d’éclat, utilise la méthode masque. Pour un usage quotidien, traite-le comme ton nettoyant mousse habituel.', 1395, '2026-05-07 17:37:40.308881+00', '2026-06-14 15:14:07.794+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43d7-7375-a309-f30ac2f9b923', '__OWNER_ID__', 'Maple Energy Infusing Serum', 'Dear Klairs', 'serum', 'dropper', 'Sève d’Érable à Sucre (Acer Saccharum Sap), Glycerin, Tripropylene Glycol, Polyglycérine-3, Betaine, Aqua, 1,2-Hexanediol, Squalane, Butylene Glycol, Butyrospermum Parkii Butter, Silica, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Polyglycéryl-4 Oléate, Carbomer, Beurre de Graine de Cupuaçu (Theobroma Grandiflorum), Beurre de Mangue (Mangifera Indica Seed Butter), Beurre de Graine de Murumuru (Astrocaryum Murumuru), Tromethamine, Inulin Lauryl Carbamate, Propanediol, Sodium Polyacrylate, Glyceryl Acrylate/Acrylic Acid Copolymer, Sodium Acrylates Crosspolymer-2, Ethylhexylglycerin, Cetearyl Alcohol, Adenosine, PVM/MA Copolymer, Extrait d’Écorce d’Érable Rouge (Acer Rubrum), Gomme Xanthane, Cellulose Gum, Gomme de Graine de Tamarin (Tamarindus Indica), Stearic Acid, Sorbitan Isostearate, Sodium Surfactin, Extrait de Myrtille (Vaccinium Myrtillus), Pueraria Lobata Root Extract, Caprylyl Glycol, Hydroxyéthylcellulose Cétylique, Glucose, Rutine, Extrait de Roseau (Phragmites Communis), Acetyl Hexapeptide-8, Extrait de Trèfle Rouge (Trifolium Pratense), Palmitoyl Tripeptide-1, Palmitoyl Tetrapeptide-7, Tocopherol, Extrait de Graine de Haricot de Lima (Phaseolus Lunatus)', 'Le Maple Energy Infusing Serum Dear Klairs est un traitement profondément hydratant pour renforcer la barrière naturelle de la peau, conçu pour offrir ce que la marque appelle un « éclat semblable à du sirop. » Renforcé par le Maple Syrup Antiobooster™, un complexe d''extrait de sève d''érable et d''écorce d''érable rouge, ce sérum reconstitue l''hydratation essentielle tout en fortifiant la peau contre les facteurs de stress externes. Enrichi en squalane, en beurre de cupuaçu, en beurre de graines de mangue et en beurre de murumuru, il retient l''hydratation et rétablit le confort pour un teint rebondi et lisse. Pour stimuler davantage la vitalité de la peau, cette formule est infusée de multi-peptides (Acetyl Hexapeptide-8, Palmitoyl Tripeptide-1, et Palmitoyl Tetrapeptide-7), qui aident à améliorer la fermeté, à réduire les ridules visibles, et à affiner la texture de la peau. Une synergie d''extraits botaniques tels que la myrtille, la racine de kudzu et le trèfle apporte une protection antioxydante et un équilibre, laissant la peau radieuse et d''apparence saine. Avec sa texture sirupeuse mais légère, ce sérum vegan et sans alcool pénètre sans effort, ce qui le rend idéal pour un usage quotidien sur tous les types de peaux, y compris les peaux sensibles. Recommandé pour : Peaux sensibles, sèches, tous types de peaux.', 30, 'ml', 'dear-klairs-maple-energy-infusing-serum', 'https://korean-skincare.fr/products/dear-klairs-maple-energy-infusing-serum', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-maple-energy-infusing-serum.webp', 'Après avoir nettoyé ta peau et appliqué un tonique, distribue 1 à 2 gouttes de produit dans tes paumes et applique-les délicatement sur ton visage jusqu''à ce qu''elles soient entièrement absorbées. Peut être réappliqué au besoin tout au long de la journée pour maintenir l''hydratation et l''éclat. Fais suivre d''une crème hydratante ; idéal pour une utilisation matin et soir.', 2395, '2026-05-07 17:37:40.311086+00', '2026-06-14 15:14:07.794+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43db-7aba-bc98-f949e763136a', '__OWNER_ID__', 'Klairs Fundamental Watery Oil Drop', 'Dear Klairs', 'moisturizer', 'jar', 'Aqua, Glycerin, Butylene Glycol, Camellia Sinensis Leaf Water, Extrait de Riz Oryza Sativa, Bifida Ferment Lysate, Betaine, Dipropylene Glycol, Sorbitol, 1,2-Hexanediol, Extrait de Ferment Aspergillus/Riz, Camellia Sinensis Leaf Extract, Dipotassium Glycyrrhizate, Sesquioléate de Sorbitane, Ethylhexylglycerin, Copolymère d''Acrylate d''Acrylate de Sodium/Acryloyldiméthyl Taurate, Sodium Hyaluronate, Hydroxyéthylcellulose, Gomme de Xanthane, Arginine, Carbomer, Tocopheryl Acetate, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Laminaria Japonica Extract, Ceramide NP, Hydrogenated Lecithin, Copper Tripeptide-1, Acetyl Hexapeptide-8', 'Le Fundamental Watery Oil Drop Dear Klairs est un sérum à base d''eau qui hydrate ta peau comme une huile pour le visage. Ce sérum non collant et facilement absorbable est recommandé aux personnes qui souhaitent bénéficier de tous les avantages d''un produit à base d''huile sans le fini huileux ni gras. Formulé avec du thé vert, des extraits de ferments, du céramide et des peptides, ce sérum riche en antioxydants améliore la régénération de la peau et agit comme une solution anti-âge.', 50, 'ml', 'dear-klairs-fundamental-watery-oil-drop', 'https://korean-skincare.fr/products/dear-klairs-fundamental-watery-oil-drop', 'https://aurore-cdn.b-cdn.net/products/dear-klairs-fundamental-watery-oil-drop.webp', 'Prélève une quantité adéquate de produit à l''aide du compte-gouttes. Masse délicatement ta peau en suivant son grain. Renouvelle l''application sur le contour des yeux secs.', 3195, '2026-05-07 17:37:40.315535+00', '2026-06-14 15:14:07.794+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43e2-7e71-95ff-8ff084728df0', '__OWNER_ID__', 'Jeju Matcha Tea Essence', 'Dr. Ceuracle', 'essence', 'dropper', 'Camellia Sinensis Leaf Water, Triéthylhexanoïne, Polyoléfine Hydrogénée (C6-14), Methylpropanediol, Butylene Glycol, Aqua, Niacinamide, 1,2-Hexanediol, Phosphate de Sodium Laureth-4, Glycerin, Coptis Japonica Root Extract, Hydroxyacetophenone, Ethylhexylglycerin, Parfum, Polyquaternium-51, Sodium Hyaluronate, Adenosine, TétraHydroxypropyl Éthylènediamine, Tromethamine, Extrait de Malachite, Hydrogenated Lecithin, Centella Asiatica Extract, Ficus Carica Fruit Extract, Lactococcus Ferment Lysate, Camellia Sinensis Leaf Extract, Ceramide NP, Fructooligosaccharides, Arginine, Glycine, Extrait de Racine de Cyperus Rotundus, Caprylyl Glycol, Capryloyl Salicylic Acid, Gluconolactone, Insaponifiables d’Huile de Graine d’Helianthus Annuus, Sodium Chloride, Acetyl Hexapeptide-8, Copper Tripeptide-1, Hexapeptide-9, Nonapeptide-1, Palmitoyl Pentapeptide-4, Palmitoyl Tetrapeptide-7, Palmitoyl Tripeptide-1, Tripeptide-1, Acetyl Tetrapeptide-5', 'Découvre une vague de vitalité verte et pure avec la Jeju Matcha Tea Essence Dr. Ceuracle, une essence légère mais intensément nourrissante formulée pour rééquilibrer, apaiser et renforcer la peau. Enrichie à 40 % d’extrait de matcha antioxydant récolté sur l’île de Jeju, cette essence offre une protection efficace contre les agressions environnementales tout en aidant à calmer les irritations et à améliorer la clarté du teint. Infusée en probiotiques, acide hyaluronique et panthénol, elle contribue à restaurer la barrière d’hydratation de la peau, laissant le teint hydraté, repulpé et visiblement plus résistant. Sa texture aqueuse ultra-fraîche pénètre instantanément sans effet collant, ce qui la rend idéale pour tous les types de peaux, en particulier les peaux sensibles, ternes ou facilement stressées. Recommandé pour : Tous types de peaux.', 150, 'ml', 'dr-ceuracle-jeju-matcha-tea-essence', 'https://korean-skincare.fr/products/dr-ceuracle-jeju-matcha-tea-essence', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-jeju-matcha-tea-essence.webp', 'Après le nettoyage et le tonique, applique 2 à 3 pressions de l’essence sur ton visage. Tapote délicatement jusqu’à absorption complète. Poursuis avec ton sérum et ta crème hydratante. Utilise matin et soir pour des résultats optimaux. Pour un effet apaisant renforcé, tu peux superposer plusieurs couches (méthode du « 7-skin »).', 2495, '2026-05-07 17:37:40.322788+00', '2026-06-14 15:14:07.794+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43eb-7246-95ee-632e42e62005', '__OWNER_ID__', 'Vegan Kombucha Tea Essence In Gel Mask', 'Dr. Ceuracle', 'mask', 'pack', 'Camellia Sinensis Leaf Water, Aqua, Propanediol, Butylene Glycol, Xylitol, Xylitylglucoside, Anhydroxylitol, Betaine, Extrait De Champignon Tremella Fuciformis, Gluconolactone, Ferment De Thé Noir Saccharomyces/Xylinum Kombucha, Camellia Sinensis Leaf Extract, Lysat De Ferment Lactobacillus, Inuline, Pullulane, Panthenol, Allantoin, Aloe Barbadensis Leaf Extract, Glycerin, Carbomer, Tromethamine, Ethylhexylglycerin, 1,2-Hexanediol, Disodium EDTA', 'Revitalise et rééquilibre ta peau stressée avec le Vegan Kombucha Tea Essence In Gel Mask, un soin à rincer rafraîchissant infusé de la Kombucha Tea Essence emblématique de Dr. Ceuracle. Formulé avec un mélange concentré de thé noir fermenté (kombucha), d’eau de thé vert et de probiotiques vegan, ce masque gel apaisant aide à restaurer l’hydratation, améliorer la clarté de la peau et renforcer la barrière cutanée. Sa texture gel rebondie procure un effet fraîcheur immédiat à l’application, aidant à réduire les signes d’irritation et de fatigue tout en apportant une hydratation profonde. Idéal pour les peaux ternes, déshydratées ou sensibles, il laisse le teint doux, repulpé et visiblement rafraîchi. Recommandé pour : Peaux sèches, sans risque pour l’acné fongique, tous types de peaux.', 36, 'g', 'dr-ceuracle-vegan-kombucha-tea-essence-in-gel-mask', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-kombucha-tea-essence-in-gel-mask', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-kombucha-tea-essence-in-gel-mask.webp', 'Après le nettoyage, applique une couche uniforme du masque gel sur peau sèche. Laisse poser 10 à 15 minutes. Rince à l’eau tiède, puis applique ton tonique, ton sérum et ta crème hydratante. Utilise 2 à 3 fois par semaine, ou chaque fois que ta peau se sent fatiguée ou irritée. Pour un effet encore plus apaisant, place le masque au réfrigérateur avant utilisation.', 395, '2026-05-07 17:37:40.331075+00', '2026-06-14 15:14:07.795+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43ed-707a-abd1-2f681b45d0ac', '__OWNER_ID__', 'Cica Regen Waterproof Sun', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Aqua, Adipate de Dibutyle, Propanediol, Ethylhexyl Triazone, Polyméthylsilsesquioxane, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Niacinamide, Drometrizole Trisiloxane, Methylene Bis-Benzotriazolyl Tetramethylbutylphenol, Coco-Caprylate/Caprate, Caprylyl Methicone, Glycerin, 1,2-Hexanediol, Butylene Glycol, Centella Asiatica Extract, Dioscorea Japonica Root Extract, Laminaria Japonica Extract, Ulmus Davidiana Root Extract, Aloe Barbadensis Leaf Extract, Extrait de Fleur de Viola Mandshurica, Extrait de Salicornia Herbacea, Extrait de Feuille de Corchorus Olitorius, Extrait de Fruit d’Adansonia Digitata, Extrait de Pousse de Bambusa Vulgaris, Extrait de Feuille/Tige de Bambusa Vulgaris, Extrait d’Angelica Keiskei, Extrait de Racine de Nelumbo Nucifera, Hibiscus Esculentus Fruit Extract, Extrait de Mentha Aquatica, Extrait d’Anastatica Hierochuntica, Sodium Hyaluronate, Bambusa Vulgaris Water, Pentylene Glycol, Behenyl Alcohol, Poly C10-30 Alkyl Acrylate, Copolymère VP/Eicosène, Polyglycéryl-3 Methylglucose Distearate, Decyl Glucoside, Tromethamine, Carbomer, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Glutamate de Sodium Stéaroyl, Polyacrylate Crosspolymer-6, Ethylhexylglycerin, Adenosine, Polysaccharide', 'Protège ta peau avec la Cica Regen Waterproof Sun SPF50+ PA++++ Dr. Ceuracle, une crème solaire chimique douce mais puissante, certifiée vegan, qui offre une protection à large spectre tout en apaisant et hydratant la peau. Enrichi en extrait apaisant de Centella Asiatica et en complexe nourrissant de bambou, ce produit défend contre les agressions environnementales et l’irritation. Sa texture légère, semblable à une émulsion, pénètre rapidement, laissant un fini hydraté et non collant, parfait pour un usage quotidien. Résistante à l’eau, sans danger pour les récifs et adapté à tous les types de peaux, cette crème solaire procure une hydratation longue durée et une protection UV fiable. Recommandé pour : Peaux sensibles, tous types de peaux, sans risques pour l’acné fongique.', 50, 'ml', 'dr-ceuracle-cica-regen-waterproof-sun', 'https://korean-skincare.fr/products/dr-ceuracle-cica-regen-waterproof-sun', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-cica-regen-waterproof-sun.webp', 'Lors de la dernière étape de ta routine beauté, applique une quantité modérée de produit sur ta peau au moins 30 minutes avant l’exposition au soleil ou la baignade.', 2395, '2026-05-07 17:37:40.332969+00', '2026-06-14 15:14:07.795+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43f0-7e7a-ab37-0b9cbf386637', '__OWNER_ID__', 'Pro Balance Biotics Moisturizer', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, Stéarate de Sorbitan, 1,2-Hexanediol, Alcool Cétylique et Stéarylique (Cetearyl Alcohol), Glyceryl Stearate, Méthyl Triméthicone, Palmitic Acid, Bisabolol, Stearic Acid, Carbomer, Butylene Glycol, Dipropylene Glycol, Tromethamine, Parfum, Limonene, Eclipta Prostrata Leaf Extract, Laminaria Japonica Extract, Hydroxyacetophenone, Ethylhexylglycerin, Lactobacillus Ferment, Gomme Xanthane, Fructooligosaccharides, Hydrogenated Lecithin, Disodium EDTA, Beta-Glucan, Adenosine, Citral, Panthenol, Hydrolyzed Sodium Hyaluronate, Centella Asiatica Extract, Extrait de Fruit de Figuier (Ficus Carica), Raffinose, Acide Folique, Ceramide NP, Bifida Ferment Lysate, Bifida Ferment Lysate, Lactobacillus Ferment Lysate, Lactococcus Ferment Lysate, Saccharomyces Ferment Filtrate, Cholesterol, Théanine, Lipides du Lait, Glutathione, Pentapeptide-4 Palmitoylé', 'La Pro Balance Biotics Moisturizer Dr. Ceuracle est une solution de pointe conçue pour rétablir l’équilibre du microbiome cutané tout en apportant une hydratation profonde et durable. Grâce à la technologie avancée des probiotiques, ce soin léger mais nourrissant soutient la barrière naturelle de la peau, aidant à réduire la sensibilité, l’inflammation et la sécheresse. Parfait pour équilibrer et apaiser le teint, que ce soit en cas d’irritations, de imperfections ou de stress environnemental, il laisse la peau douce, souple et visiblement plus saine à chaque application. Formulé avec des actifs respectueux de la peau et des extraits botaniques, la Pro Balance Biotics Moisturizer renforce la résilience et favorise un teint lumineux et uniforme. Sa texture à absorption rapide en fait un choix idéal pour les routines du matin et du soir, se superposant facilement sous le maquillage ou l’écran solaire. Adapté à tous les types de peaux, y compris sensibles, ce soin enrichi en probiotiques offre un boost doux mais efficace à ta routine, rendant l’équilibre et la beauté facilement accessibles. Recommandé pour : Peaux sèches et tous types de peaux.', 100, 'ml', 'dr-ceuracle-pro-balance-biotics-moisturizer', 'https://korean-skincare.fr/products/dr-ceuracle-pro-balance-biotics-moisturizer', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-pro-balance-biotics-moisturizer.webp', 'Pompe une quantité appropriée de produit dans ta main. Applique sur ton visage et tapote doucement pour favoriser l’absorption.', 1895, '2026-05-07 17:37:40.336858+00', '2026-06-14 15:14:07.795+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43f2-7cf7-902a-6d3b4d2863cf', '__OWNER_ID__', 'PLC Vita K Liposome Oil Ampoule', 'Dr. Ceuracle', 'lip-care', 'tube', 'Aqua, Diphenyl Dimethicone, Butylene Glycol, Niacinamide, 1,2-Hexanediol, Sodium Chloride, Pentylene Glycol, Extrait de Feuille de Chou (Brassica Oleracea Capitata Leaf Extract), Extrait de Brocoli (Brassica Oleracea Italica Extract), Extrait de Céleri (Apium Graveolens Extract), Extrait de Concombre (Cucumis Sativus Extract), Extrait de Feuille de Kale (Brassica Oleracea Acephala Leaf Extract), Extrait de Persil (Carum Petroselinum Extract), Glycerin, Extrait d’Eclipta Prostrata, Sodium Hyaluronate, Ethylhexylglycerin, Huile de Graines de Moringa (Moringa Oleifera Seed Oil), Parfum, Caprylic/Capric Triglyceride, Hespéridine Méthyl Chalcone, Hydrogenated Lecithin, Polyglyceryl-10 Diisostéarate, Extrait de Fleur d’Arnica (Arnica Montana Flower Extract), Extrait de Feuille d’Hamamélis (Hamamelis Virginiana Leaf Extract), Extrait de Fleur de Mauve (Malva Sylvestris Flower Extract), Extrait de Racine de Ruscus (Ruscus Aculeatus Root Extract), Extrait de Marron d’Inde (Aesculus Hippocastanum Extract), Ménadione 5 ppm, Tocopherol', 'La PLC Vita K Liposome Oil Ampoule Dr. Ceuracle est un soin luxueux et profondément nourrissant conçu pour revitaliser les peaux ternes et fatiguées. Enrichie en vitamine K et en un mélange puissant d’antioxydants encapsulés dans des liposomes, cette huile ampoule légère apporte une hydratation intense tout en renforçant la barrière cutanée. Elle aide à réduire les rougeurs et les cernes, offrant un teint plus clair, radieux et une peau douce et souple. Parfaite pour les peaux sensibles et fatiguées, cette ampoule pénètre rapidement sans laisser de film gras. Utilise-la lors de la dernière étape de ta routine pour verrouiller l’hydratation et améliorer la vitalité générale de la peau. Sa formule apaisante soutient la récupération cutanée, uniformise le teint et atténue les signes d’irritation, constituant un coup de boost essentiel pour les peaux fatiguées ou sensibles. Recommandé pour : Peaux sensibles, fatiguées et ternes.', 50, 'ml', 'dr-ceuracle-plc-vita-k-liposome-oil-ampoule', 'https://korean-skincare.fr/products/dr-ceuracle-plc-vita-k-liposome-oil-ampoule', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-plc-vita-k-liposome-oil-ampoule.webp', 'Après le nettoyage et le tonique, prélève quelques gouttes d’ampoule dans tes paumes ou sur tes doigts. Tapote et presse délicatement le produit sur ton visage et ton cou, en insistant sur les zones rouges, ternes ou irritées. Laisse pénétrer complètement avant d’appliquer une crème ou un écran solaire. Utilise quotidiennement, de préférence le soir, pour une récupération optimale de la peau et une hydratation maximale. Astuce : Intègre-la dans ta routine du soir pour favoriser la récupération et les effets apaisants pendant la nuit.', 1895, '2026-05-07 17:37:40.338758+00', '2026-06-14 15:14:07.795+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43f4-7c74-b53e-a89d2079e597', '__OWNER_ID__', 'Expert Goji Berry Vita Modeling Mask', 'Dr. Ceuracle', 'mask', 'pack', 'Terre de Diatomée, Glucose, Alginate, Sulfate de Calcium, Pyrophosphate de Tétrapotassium, Lycium Barbarum Fruit Extract, Carbonate de Magnésium, Ascorbic Acid, Allantoin, Alginate de Potassium, Adenosine, Betaine, Trehalose, Niacinamide, Extrait de Pourpier (Portulaca Oleracea Extract), Cellulose Gum, Sodium Benzoate, Potassium Sorbate, Huile de Zeste de Mandarine, Limonene', 'L''Expert Goji Berry Vita Modeling Mask Dr. Ceuracle est un masque peel-off de qualité spa qui apporte une dose puissante d’antioxydants, d’hydratation et d’effet raffermissant en une seule étape cocooning. Lorsqu’il est mélangé avec de l’eau ou un activateur, il se transforme en une texture caoutchouteuse malléable qui se solidifie sur la peau, emprisonnant les vitamines et l’extrait de baie de goji pour illuminer, revitaliser et lisser ton teint. Riche en ingrédients nourrissants comme la vitamine C, le niacinamide et l’adénosine, ce masque modelant réduit en douceur les signes de l’âge, ravive les peaux ternes et améliore l’élasticité. Convient à tous les types de peau, il se décolle également facilement après 15 à 30 minutes, laissant un teint rafraîchi, lumineux et visiblement plus lisse. Recommandé pour : Tous types de peaux.', 1000, 'g', 'dr-ceuracle-expert-goji-berry-vita-modeling-mask', 'https://korean-skincare.fr/products/dr-ceuracle-expert-goji-berry-vita-modeling-mask', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-expert-goji-berry-vita-modeling-mask.webp', 'Important ! Mélange la poudre du masque avec de l’eau ou un activateur, généralement à parts égales (1:1). Remue jusqu’à obtenir une consistance gélifiée et étalable. Applique uniformément sur ton visage et laisse poser 15 à 30 minutes jusqu’à durcissement. Décolle délicatement, puis poursuis avec ton tonique et ton sérum ou crème préférée.', 2595, '2026-05-07 17:37:40.340725+00', '2026-06-14 15:14:07.795+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43fc-77dc-9bc3-c040bbc59840', '__OWNER_ID__', 'Expert Charcoal Black Modeling Mask', 'Dr. Ceuracle', 'mask', 'pack', 'Terre de Diatomée, Glucose, Algin, Sulfate de Calcium, Pyrophosphate de Tétrapotassium, Carbonate de Magnésium, Poudre de Charbon, Allantoin, Alginate de Potassium, Gomme Cellulosique, Huile de Menthe Poivrée, Sodium Benzoate, Potassium Sorbate, Parfum, Portulaca Oleracea Extract, Centella Asiatica Extract, Aqua, Butylene Glycol, 1,2-Hexanediol', 'L''Expert Charcoal Black Modeling Mask Dr. Ceuracle est un traitement indulgent de nouvelle génération à base d’alginate qui enveloppe la peau d’une couche veloutée avant de se décoller en un seul geste satisfaisant. Lorsqu’il se fixe, le charbon actif extrait les toxines et impuretés tandis que l’acide alginique riche en minéraux nourrit la peau en profondeur. Résultat : une peau purifiée, raffermie et réveillée, avec un fini lumineux et lifté. Enrichi en acide hyaluronique repulpant, en allantïne apaisante, en extrait de réglisse éclaircissant, en oxyde de zinc protecteur et en gluten de blé hydrolysé renforçant l’élasticité, ce soin luxueux hydrate durablement, apaise les irritations visibles et affine le grain de peau. Exquisément doux mais extrêmement efficace, il offre des résultats de niveau spa pour tous les types de peaux, y compris les peaux sensibles, grasses ou à imperfections. Recommandé pour : Tous les types de peaux, y compris les peaux sensibles et grasses ou à problèmes.', 1000, 'g', 'dr-ceuracle-expert-charcoal-black-modeling-mask', 'https://korean-skincare.fr/products/dr-ceuracle-expert-charcoal-black-modeling-mask', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-expert-charcoal-black-modeling-mask.webp', 'Important ! Mélange la poudre avec de l’eau (environ 1:1, soit environ 50 ml de chaque) jusqu’à obtenir une pâte lisse et étalable. Applique uniformément sur peau propre à l’aide d’une spatule, en évitant les yeux et la bouche. Laisse le masque se solidifier pendant 15 à 20 minutes. Décolle doucement et fais suivre d''un tonique et d''une crème hydratante.', 2595, '2026-05-07 17:37:40.348444+00', '2026-06-14 15:14:07.796+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-43fe-76b4-abc6-b66a1f31b3bb', '__OWNER_ID__', 'Pro Balance Soothing Cleansing Foam', 'Dr. Ceuracle', 'cleanser', 'tube', 'Aqua, Glycerin, Alaninate de Cocoyle de Sodium, Taurate de Méthyl Cocoyle de Sodium, Glucoside de Lauryle, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Caprylyl Glycol, Hydroxysultaine de Lauryle, Coco-Glucoside, Butylene Glycol, Glyceryl Caprylate, Gomme Xanthane, Laurate de Polyglycéryl-10, Lactate de Méthyle, Parfum, Isethionate de Cocoyle de Sodium, Styrene/Acrylates Copolymer, Extrait d’Écorce de Quillaja Saponaria, Sodium Phytate, 1,2-Hexanediol, Citric Acid, Sodium Citrate, Capryloyl Salicylic Acid, Gluconolactone, Panthenol, Trehalose, Spirulina Platensis Extract, Bifida Ferment Lysate, Lactobacillus Ferment, Lactobacillus Ferment Lysate, Lactobacillus Ferment, Lactobacillus Ferment, Lactobacillus Ferment, Lactococcus Ferment Lysate, Lactococcus Ferment Lysate, Leuconostoc Ferment Filtrate', 'La Pro Balance Soothing Cleansing Foam Dr. Ceuracle est une formule gel-eau qui se transforme en une mousse dense et onctueuse pour éliminer efficacement les impuretés et les saletés incrustées dans les pores. Enrichie d''un complexe de 9 probiotiques, cette mousse nettoyante quotidienne aide à restaurer et à maintenir une barrière cutanée saine, ce qui la rend idéale pour les peaux sensibles ou fatiguées. Enrichie en tréhalose hydratant, en lactate de menthyle apaisant et en extrait de spiruline platensis riche en nutriments, elle réhydrate la peau même après un nettoyage en profondeur. Les exfoliants doux PHA et LHA procurent un effet peeling doux, laissant ta peau visiblement plus lisse, plus nette et parfaitement équilibrée. Recommandé pour : Tous types de peaux.', 150, 'ml', 'dr-ceuracle-pro-balance-soothing-cleansing-foam', 'https://korean-skincare.fr/products/dr-ceuracle-pro-balance-soothing-cleansing-foam', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-pro-balance-soothing-cleansing-foam.webp', 'Mouille tes mains, puis prélève une petite quantité de produit et fais mousser. Masse ta peau, puis rince abondamment à l''eau tiède. Conseil : Pour un nettoyage encore plus profond et luxueux, essaie d''utiliser une brosse faciale en silicone ou une éponge konjac douce avec ta mousse nettoyante.', 1545, '2026-05-07 17:37:40.350356+00', '2026-06-14 15:14:07.796+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4400-7575-9d77-0f9bb85f6ed0', '__OWNER_ID__', 'Vegan BHA & Matcha Ampoule', 'Dr. Ceuracle', 'serum', 'dropper', 'Aqua, Glycerin, Dipropylene Glycol, Butylene Glycol, 1,2-Hexanediol, Salicylic Acid, Crosspolymère-6 de Polyacrylate, Tromethamine, Melia Azadirachta Leaf Extract, Betaine, Laurate de Polyglycéryl-10, Carbomer, Hydrogenated Lecithin, Citric Acid, Camellia Sinensis Leaf Extract, Ethylhexylglycerin, Sodium Citrate, Gomme Xanthane, Extrait de Fleur de Melia Azadirachta, Dextrin, Extrait de Theobroma Cacao, Tripeptide-1, Copper Tripeptide-1, Acetyl Tetrapeptide-5, Acétyl Tétrapeptide-2, Palmitoyl Pentapeptide-4, Palmitoyl Tripeptide-1, Hexapeptide-9, Hexapeptide-11, Palmitoyl Tripeptide-5, Disodium EDTA, Parfum', 'Rafraîchis et rééquilibre ta peau grasse et congestionnée avec la Vegan BHA Matcha Ampoule Dr. Ceuracle, une formule légère et non collante conçue pour purifier et apaiser. Enrichie en BHA à 0,5 %, cette ampoule puissante exfolie en douceur et désobstrue les pores, réduisant efficacement l''excès de sébum et les points noirs. L''extrait de matcha de l''île de Jeju offre de puissants bienfaits antioxydants et anti-inflammatoires, apaisant la peau irritée tout en la protégeant contre les signes du vieillissement. Un mélange de neuf peptides favorise la production de collagène et affine les pores dilatés pour un teint plus lisse et plus sain. Conditionnée dans un flacon en verre écologique, cette formule vegan est idéale pour une peau plus nette, plus apaisée et plus équilibrée. Recommandé pour : Peaux à tendance acnéique, soin des pores, tous types de peaux.', 30, 'ml', 'dr-ceuracle-vegan-bha-matcha-ampoule', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-bha-matcha-ampoule', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-bha-matcha-ampoule.webp', 'Après avoir nettoyénta peau et appliqué un tonique, applique 2 à 3 gouttes d''ampoule sur ton visage et ton cou. Masse délicatement et tapote le produit sur ta peau pour aider à l''absorption, puis applique ta crème hydratante préférée. Conseil : Tu peux l''utiliser le matin et le soir ; si tu l''utilises le matin, n''oublie pas de finir avec une crème solaire.', 1795, '2026-05-07 17:37:40.352289+00', '2026-06-14 15:14:07.796+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4402-7349-9431-ab56646e8974', '__OWNER_ID__', 'Vegan Niacin & Rice Ampoule', 'Dr. Ceuracle', 'serum', 'dropper', 'Aqua, Glycerin, Butylene Glycol, Methylpropanediol, Dipropylene Glycol, Triméthicone de Diphénylsiloxyphényl, 1,2-Hexanediol, Niacinamide, Polyoléfine C6-14 Hydrogénée, Caprylic/Capric Triglyceride, Panthenol, Copolymère d’Acrylates, Copolymère d’Hydroxyéthyl Acrylate/Taurate d’Acryloyldiméthyle de Sodium, Tromethamine, Alcane C15-23, Alcane C13-14, Ethylhexylglycerin, Allantoin, Gomme Xanthane, Decyl Glucoside, Sodium Hyaluronate, Pantolactone, Oryza Sativa Extract, Tocopherol, Isosorbide Diméthyle, Rétinoate d’Hydroxypinacolone, Disodium EDTA, Parfum', 'Révèle un teint visiblement plus lumineux et plus lisse grâce à la Vegan Niacin Rice Ampoule Dr. Ceuracle, un soin nourrissant de nuit conçu pour lutter contre le teint terne, le teint irrégulier et les premiers signes de l''âge. Enrichie en niacinamide à 2 % et en extrait de riz purifiant, cette ampoule crémeuse à la texture lactée agit pendant la nuit pour affiner le grain de peau, apaiser les inflammations et estomper l''hyperpigmentation. Enrichie en rétinoate d''hydroxypinacolone, un dérivé doux du rétinoïde, elle exfolie et renforce l''élasticité de la peau sans irritation. Vegan et enrichie en ingrédients apaisants pour la peau tels que le panthénol et l''allantoïne, elle procure une hydratation durable et un éclat radieux au réveil, ce qui en fait le complément idéal de ta routine de soins du soir. Recommandé pour : Hyperpigmentation, tous types de peaux.', 30, 'ml', 'dr-ceuracle-vegan-niacin-rice-ampoule', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-niacin-rice-ampoule', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-niacin-rice-ampoule.webp', 'Après avoir nettoyé ta peau et appliqué un tonique pendant ta routine du soir, dépose 2 à 3 gouttes de produit dans ta main. Applique délicatement sur ton visage, en évitant le contour des yeux et de la bouche. Tapote légèrement pour aider à l''absorption, puis applique ta crème hydratante. Conseil : Appliquer le produit avant une crème plus riche permet à ses ingrédients actifs de pénétrer plus efficacement sans être « dilués » ou bloqués par des formules plus épaisses.', 1795, '2026-05-07 17:37:40.354147+00', '2026-06-14 15:14:07.796+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4406-709d-9132-6cf7592cf024', '__OWNER_ID__', 'Expert Collagen Firming Modeling Mask', 'Dr. Ceuracle', 'mask', 'pack', 'Terre de Diatomée, Glucose, Algin, Sulfate de Calcium, Pyrophosphate de Tétrapotassium, Carbonate de Magnésium, Allantoin, Collagène Hydrolysé, Alginate de Potassium, Adenosine, Cellulose Gum, Huile de Lavande Lavandula Angustifolia, Potassium Sorbate, Sodium Benzoate, Centella Asiatica Extract, Extrait de Pourpier Portulaca Oleracea, Aqua, Butylene Glycol, 1,2-Hexanediol', 'Un soin de luxe pour raffermir, hydrater et rajeunir ton teint. Avec des alginates marins et du collagène puissant, ce masque modelant agit au niveau cellulaire pour redonner de la densité à la peau, lisser les ridules et booster l''élasticité. Sa formule super nourrissante aide à régénérer la peau, la rendre plus éclatante et à unifier le teint tout en réduisant l''apparence des petites veines et de la couperose. Idéal pour lutter contre la sécheresse et le teint terne, il rend ta peau visiblement plus ferme, plus lumineuse et magnifiquement revitalisée après chaque utilisation. Recommandé pour : tous les types de peau.', 30, 'g', 'dr-ceuracle-expert-collagen-firming-modeling-mask', 'https://korean-skincare.fr/products/dr-ceuracle-expert-collagen-firming-modeling-mask', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-expert-collagen-firming-modeling-mask.webp', 'Prépare ta peau en la nettoyant et en appliquant un tonique, et en appliquant éventuellement un sérum pour renforcer les bienfaits du soin. Mélange rapidement la poudre avec de l''eau dans un rapport 1:1 jusqu''à obtenir une pâte lisse et épaisse. Applique immédiatement une couche épaisse et uniforme sur ton visage, en évitant les narines, les yeux et la bouche. Détends-toi pendant 15 à 20 minutes pendant que le masque prend une texture caoutchouteuse. Retire délicatement le masque en commençant par le menton, puis continue avec ta routine de soins habituelle. Conseil : Avant la première utilisation, on te recommande de faire un test d''allergie.', 295, '2026-05-07 17:37:40.357964+00', '2026-06-14 15:14:07.796+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4452-73ce-8395-897953b7c466', '__OWNER_ID__', '5α Control Clearing Cream (Expiring 28/7/2026)', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Aqua, Glycerin, Cyclopentasiloxane, Methylpropanediol, Cyclohexasiloxane, Cetearyl Alcohol, Dimethicone, Extrait d''Ecorce/Feuille/Brindille d''Hamamelis Virginiana (Hamamélis), Betaine, Centella Asiatica Extract, Aloe Barbadensis Leaf Juice, Extrait d''Ecorce de Cinnamomum Zeylanicum, Extrait de Saccharomyces Cerevisiae, Extrait de germe de Triticum Vulgare (blé), Serenoa Serrulata Fruit Extract, Extrait de graine de Sesamum Indicum (Sésame), Extrait de Phellinus Linteus, Extrait de Cordyceps Sinensis, Extrait de Ganoderma Lucidum (Champignon), Hydrogenated Lecithin, Argania Spinosa Kernel Oil, Sodium Hyaluronate, Copolymère Acrylate de Sodium/Acryloyldiméthyl Taurate de Sodium, Isohexadecane, Cetearyl Glucoside, Tromethamine, Butylene Glycol, Carbomer, Bisabolol, Candida Ferment, Tocopheryl Acetate, Sarcosine, Capryloyl Glycine, Hexylene Glycol, PEG-60 Glycérides d''Amandes, Copolymère Acrylate de Glycéryle/Acide Acrylique, Dipotassium Glycyrrhizate, Oléate de Sorbitan, Glucose, Acide Nordihydroguaiaretique, Acide Oléanolique, Polymère Croisé Dimethicone/PEG-10/15, Polysorbate 80, Parfum, 1,2-Hexanediol, Hydroxyacetophenone, Caprylyl Glycol, Ethylhexylglycerin', 'La Control Clearing Cream 5 α Dr.Ceuracle est un gel-crème rafraîchissant qui offre une hydratation intense et un soin apaisant aux peaux sensibles souffrant d''une production excessive de sébum. Sa formule spéciale à base de Sepicontrol A5 réduit l''excès de sébum et la brillance de la peau grâce à une formule brevetée mise au point par le centre de recherche et de développement de Dr. Ceuracle. **Sepicontrol A5: Capryloyle Glycone, Cinnamomum Zeylanicum, Sarconsine. Ce produit fonctionne sur la base d''une technologie qui contrôle la 5 alpha-réductase, une hormone qui provoque une sécrétion anormale de sébum lorsque la peau connaît un déséquilibre.', 50, 'ml', 'dr-ceuracle-5-alpha-control-clearing-cream', 'https://korean-skincare.fr/products/dr-ceuracle-5-alpha-control-clearing-cream', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-5-alpha-control-clearing-cream.webp', 'Applique uniformément une quantité suffisante de produit sur l''ensemble de ton visage. Tapote délicatement pour favoriser l''absorption.', 1595, '2026-05-07 17:37:40.434133+00', '2026-06-14 15:14:07.796+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-440a-7138-86e4-06524706fd68', '__OWNER_ID__', 'Vegan Kombucha Tea Special Set', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Vegan Kombucha Tea Essence : Eau, Triéthylhexanoïne, Hydrogenated Poly(C6-14 Olefin), 1,2-Hexanediol, Methylpropanediol, Butylene Glycol, Glycerin, Trilaurèth-4 Phosphate, Camellia Sinensis Leaf Extract, Saccharomyces Ferment Filtrate, Camellia Sinensis Leaf Water, Insaponifiables d’Huile de Graines de Tournesol (Helianthus Annuus), Polyquaternium-51, Sodium Hyaluronate, Ethylhexylglycerin, Hydrogenated Lecithin, Dextrin, Theobroma Cacao Seed Extract, Centella Asiatica Extract, Ficus Carica Fruit Extract, Extrait de Fruit de Schisandra Chinensis, Extrait de Graines d’Amaranthus Caudatus, Ulmus Davidiana Root Extract, Ceramide NP, Tocophérol Vegan Kombucha Tea Gel Cream : Eau, Glycerin, Methylpropanediol, 1,2-Hexanediol, Éther Dicaprylyl, Glycérh-26, Niacinamide, Butylene Glycol, Dipropylene Glycol, Camellia Sinensis Leaf Extract, Saccharomyces Ferment Filtrate, Eclipta Prostrata Leaf Extract, Laminaria Japonica Extract, Hydroxyacéto-phénone, Camellia Sinensis Leaf Water, Polyquaternium-51, Insaponifiables d’Huile de Graines de Tournesol (Helianthus Annuus), Ethylhexylglycerin, Fructooligosaccharides, Beta-Glucan, Hydrogenated Lecithin, Carbomer, Theobroma Cacao Seed Extract, Dextrin, Extrait de Phellinus Linteus, Arctium Lappa Root Extract, Ammonium Acryloyldiméthyltaurate/VP Copolymère, Gomme Xanthane, Tromethamine, Hydrolyzed Hyaluronic Acid, Extrait de Fruit de Schisandra Chinensis, Rosmarinus Officinalis Leaf Oil, Tocophérol Vegan Kombucha Tea Lip Balm : Polyglycéryl-2 Triisostéarate, Squalane, Bis-Diglycéryl Polyacyladipate-2, Caprylic/Capric Triglyceride, Octyldodecanol, Dimer Dilinoléate de Phytostéryl/Isostéaryl/Cétyl/Stéaryl/Bhényl, Synthetic Wax, Stéaroyl Stéarate d’Octyldodécyl, Polyhydroxystearic Acid, Butyrospermum Parkii Butter, Copolymère Éthylène/Propylène, Euphorbia Cerifera Cera, Extrait d’Eclipta Prostrata, Eclipta Prostrata Leaf Extract, Cire de Carnauba (Copernicia Cerifera), Moringa Oleifera Seed Oil, Aqua, Melia Azadirachta Leaf Extract, Extrait de Fleur de Melia Azadirachta, Butylene Glycol, Extrait de Racine d’Anemarrhena Asphodeloides, Ceramide NP, Citric Acid, Ocimum Sanctum Leaf Extract, Ferment Candida Bombicola/Glucose/Méthyl Rapeseedate, Extrait de Corallina Officinalis, Huile de Germe de Riz (Oryza Sativa), Camellia Sinensis Leaf Extract, Saccharomyces Ferment Filtrate, Extrait de Fruit de Schisandra Chinensis, 1,2-Hexanediol, Camellia Sinensis Leaf Extract', 'Le Vegan Kombucha Tea Special Set Dr. Ceuracle est un trio nourrissant conçu pour revitaliser et hydrater ta peau de la tête aux pieds. Il comprend la Vegan Kombucha Tea Essence, un hybride luxueux entre crème et essence qui restaure en profondeur les peaux sèches, sensibles et ternes grâce à l’extrait de thé kombucha, des ingrédients botaniques et des huiles de graines riches en nutriments, pour un éclat radieux et lumineux. Poursuis avec la Kombucha Tea Gel Cream, une crème légère infusée d’extrait de thé kombucha, d’eau de feuilles de thé vert et d’extraits de fruits pour apporter une hydratation apaisante et une fraîcheur durable. Pour compléter ta routine, un baume à lèvres doux est inclus pour protéger et hydrater tes lèvres. Découvre l’éclat d’une peau saine avec les meilleures formules inspirées de la nature par Dr. Ceuracle. Recommandé pour : Tous types de peaux.', NULL, NULL, 'dr-ceuracle-vegan-kombucha-tea-special-set', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-kombucha-tea-special-set', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-kombucha-tea-special-set.webp', 'Pour de meilleurs résultats, incorpore ces produits dans ta routine quotidienne dans l’ordre suivant : Vegan Kombucha Tea Essence : Agite bien le flacon avant chaque utilisation. Après avoir nettoyé ton visage, verse une quantité appropriée de l’essence dans tes mains ou sur un coton. Applique doucement sur tout le visage, puis tapote légèrement pour favoriser l’absorption. Vegan Kombucha Tea Gel Cream : Après l’application de ton essence ou sérum, prends une quantité modérée de la gel cream et étale-la uniformément sur ton visage. Tapote doucement jusqu’à absorption complète. Vegan Kombucha Tea Lip Balm : Applique directement sur tes lèvres aussi souvent que nécessaire pour les garder hydratées et douces.', 4995, '2026-05-07 17:37:40.362007+00', '2026-06-14 15:14:07.797+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-443d-728a-a3cb-2a99e1124734', '__OWNER_ID__', '5α Control Clearing Cleansing Foam', 'Dr. Ceuracle', 'cleanser', 'tube', 'Aqua, Myristic Acid, Glycerin, Methylpropanediol, Potassium Hydroxide, CocoGlucoside, Lauric Acid, Palmitic Acid, Stearic Acid, Glyceryl Stearate, Centella Asiatica Extract, Ficus Carica Fruit Extract, Extrait d''Acmella Oleracea, Ulmus Davidiana Root Extract, Extrait de Graine d''Amaranthus Caudatus, Serenoa Serrulata Fruit Extract, Extrait de Graine de Sesamum Indicum, Extrait d''écorce de Cinnamomum Zeylanicum, Hydrogenated Lecithin, Huile de Graines de Torreya Nucifera, Argania Spinosa Kernel Oil, Potassium Cocoyl Glycinate, Salicylic Acid, Sorbitan Olivate, Décylène Glycol, Butylene Glycol, Disodium EDTA, Ceramide NP, Candida Ferment, Capryloyl Glycine, Hexylene Glycol, PEG-60 Glycérides d''Amande, Sarcosine, Acide Nordihydroguaiaretique, Acide Oléanolique, Carbomer, 1,2-Hexanediol, Parfum, Ethylhexylglycerin, Caprylyl Glycol', 'La Control Clearing Cleansing Foam 5 α Dr.Ceuracle propose une solution de nettoyage en profondeur qui permet de contrôler efficacement la production de sébum pour une peau propre et rafraîchie. Sa formule contient de l''acide salicylique (BHA) qui dissout efficacement l''excès de sébum, les impuretés et les cellules mortes obstruant les pores. Cette mousse nettoyante est conçue pour retrouver des pores purifiés et affiner la texture de la peau tout en la réhydratant suffisamment pour éviter la création de troubles cutanés. Le complexe 5α permet de contrôler le sébum, de resserrer les pores et de maintenir un équilibre cutané optimal pour une peau saine. La texture crémeuse crée des microbulles denses pour un nettoyage doux mais en profondeur, procurant une sensation de confort optimal après utilisation. Cette mousse nettoyante est idéale pour les personnes ayant une peau à tendance grasse et acnéique, et qui recherchent une routine de nettoyage douce mais efficace.', 200, 'ml', 'dr-ceuracle-5-alpha-control-clearing-cleansing-foam', 'https://korean-skincare.fr/products/dr-ceuracle-5-alpha-control-clearing-cleansing-foam', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-5-alpha-control-clearing-cleansing-foam.webp', 'Distribue la quantité souhaitée de produit sur tes mains humides et fais-le mousser. Masse délicatement sur ton visage en effectuant de légers mouvements circulaires, en évitant le contour des yeux et de la bouche. Rince à l''eau tiède.', 2495, '2026-05-07 17:37:40.413062+00', '2026-06-14 15:14:07.797+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-655b-7aeb-9051-4ff297247e22', '__OWNER_ID__', 'Redken Acidic Bonding Concentrate Après-shampoing réparateur pour cheveux sensibilisés', 'Redken', 'conditioner', 'tube', 'Aqua, Cetearyl Alcohol, Glycerin, Behentrimonium Chloride, Dimethicone, BIS-CETEARYL AMODIMETHICONE, CETYL ESTERS, Citric Acid, ISOPROPYL ALCOHOL, DICETYLDIMONIUM CHLORIDE, Parfum, Sodium Citrate, Phenoxyethanol, CANDELILLA CERA / CANDELILLA WAX, Isopropyl Myristate, HYDROXYPROPYL GUAR, Limonene, Coco-Betaine, AMODIMETHICONE, Cetrimonium Chloride, DILAURYL THIODIPROPIONATE, TRIDECETH-10, Sodium Chloride, Linalool, PEG-100 Stearate, Citronellol, STEARETH-6, TRIDECETH-3, ACETIC ACID, TRISODIUM HEDTA (F.I.L. D258007/1)', '', 500, 'ml', 'redken-acidic-bonding-concentrate-apres-shampoing-reparateur-pour-cheveux-sensibilises-255266', 'https://www.atida.fr/redken-acidic-bonding-concentrate-apres-shampoing-reparateur-pour-cheveux-sensibilises.html', 'https://aurore-cdn.b-cdn.net/products/redken-acidic-bonding-concentrate-apres-shampoing-reparateur-pour-cheveux-sensibilises-255266.webp', '', 3799, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.871+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-440f-7d6d-87ce-45caa65d9105', '__OWNER_ID__', 'Vegan Kombucha Beginning Set', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Vegan Kombucha Tea Essence (50ml) : Eau, Triéthylhexanoïne, Polyoléfine Hydrogénée, 1,2-Hexanediol, Methylpropanediol, Butylene Glycol, Glycerin, Phosphate de Trilaureth-4, Camellia Sinensis Leaf Extract, Saccharomyces Ferment Filtrate, Camellia Sinensis Leaf Water, Insaponifiables d’Huile de Graine de Tournesol Helianthus Annuus, Polyquaternium-51, Sodium Hyaluronate, Ethylhexylglycerin, Hydrogenated Lecithin, Dextrin, Extrait de Graine de Cacao Theobroma, Centella Asiatica Extract, Extrait de Fruit de Figue Ficus Carica, Extrait de Fruit de Schisandra Chinensis, Extrait de Graine d’Amaranthus Caudatus, Ulmus Davidiana Root Extract, Ceramide NP, Tocophérol. Vegan Kombucha Tea Gel Cream (30g) : Eau, Glycerin, Methylpropanediol, 1,2-Hexanediol, Éther de Dicaprylyle, Glycereth-26, Niacinamide, Butylene Glycol, Dipropylene Glycol, Camellia Sinensis Leaf Extract, Saccharomyces Ferment Filtrate, Eclipta Prostrata Leaf Extract, Laminaria Japonica Extract, Hydroxyacetophenone, Camellia Sinensis Leaf Water, Polyquaternium-51, Insaponifiables d’Huile de Graine de Tournesol Helianthus Annuus, Ethylhexylglycerin, Fructooligosaccharides, Beta-Glucan, Hydrogenated Lecithin, Carbomer, Extrait de Graine de Cacao Theobroma, Dextrin, Extrait de Phellinus Linteus, Arctium Lappa Root Extract, Copolymère d’Acrylate d’Ammonium/Acryloyldiméthyltaurate VP, Gomme Xanthane, Tromethamine, Hydrolyzed Hyaluronic Acid, Extrait de Fruit de Schisandra Chinensis, Huile de Feuille de Romarin Rosmarinus Officinalis, Tocopherol', 'Obtient une peau éclatante et équilibrée grâce au Vegan Kombucha Beginning Set Dr. Ceuracle, un duo puissant conçu pour hydrater, apaiser et nourrir. Contenant Vegan Kombucha Tea Essence best-seller, cette essence tonique et crème multifonctionnelle offre une hydratation en profondeur et une nutrition riche en antioxydants, ce qui la rend idéale pour les peaux sèches, sensibles, ternes ou déséquilibrées. Associé à la Vegan Kombucha Tea Gel Cream, un soin hydratant vegan léger infusé de kombucha, ce coffret aide à retenir l''hydratation tout en favorisant un teint frais et éclatant de santé. Parfait pour tous les types de peau, ce coffret délicat et efficace est la première étape vers un teint revitalisé et éclatant. Recommandé pour : Peaux sèches, tous types de peaux.', NULL, NULL, 'dr-ceuracle-vegan-kombucha-beginning-set', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-kombucha-beginning-set', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-kombucha-beginning-set.webp', 'Vegan Kombucha Tea Essence : Bien agiter. Applique en tapotant sur ton visage nettoyé. Applique en plusieurs couches selon les besoins : 1 pour les peaux grasses, 2 pour les peaux mixtes, 3+ pour les peaux sèches. Vegan Kombucha Tea Gel Cream : Applique lors de la dernière étape de ta routine de soins. Masse ton visage et ton cou. Utilise toujours une crème solaire le matin. Conseil : Pour une hydratation et un éclat maximum, surtout si tu as la peau sèche ou terne, essaie d''appliquer l''essence en 2 ou 3 couches, en laissant chaque couche pénétrer avant d''appliquer la suivante.', 2095, '2026-05-07 17:37:40.367781+00', '2026-06-14 15:14:07.797+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4414-7399-853d-dba0fc558847', '__OWNER_ID__', 'Vegan Kombucha Tea Sleep Mask', 'Dr. Ceuracle', 'mask', 'pack', 'Aqua, Glycerin, Butyrospermum Parkii Butter, Cocos Nucifera Oil, Ethylhexyl Palmitate, Coco-Caprylate/Caprate, Butylene Glycol, Alcool Cétéaryle, Oléfine Poly C6-14 Hydrogénée, Macadamia Integrifolia Seed Oil, Niacinamide, Alcool Arachidyle, Methylpropanediol, Polyglycéryle-3 Disstéarate, 1,2-Hexanediol, Alcool Béhenyle, Copolymère Hydroxyéthyl Acrylate/Sodium Acryloyldimethyl Taurate, Hydroxyacetophenone, Silica, Squalane, Polyglycéryle-10 Laurate, Olea Europaea Fruit Oil, Glutamate de Stéaroyle de Sodium, Glucoside d''Arachidyle, Glyceryl Stearate, Esters de Jojoba, Camellia Sinensis Leaf Extract, Filtrat de Fermentation de Saccharomyces, Carbomer, Helianthus Annuus Seed Wax, Tromethamine, Camellia Sinensis Leaf Water, Dipropylene Glycol, Eclipta Prostrata Leaf Extract, Citrate de Stéarate de Glycéryle, Laminaria Japonica Extract, Unsaponifiables d''Huile d''Olive Hydrogénée, Adenosine, Dextrin, Theobroma Cacao Seed Extract, Sorbitan Isostearate, Disodium EDTA, Abies Sibirica Oil, Laurate de Sodium, Bakuchiol, Fructooligosaccharides, Unsaponifiables d''Huile de Graines de Helianthus Annuus, Hydrogenated Lecithin, Polyglycéryle-3, Beta-Glucan, Lauric Acid, Rosmarinus Officinalis Leaf Oil, Salvia Sclarea Oil, Centella Asiatica Extract, Ficus Carica Fruit Extract, Glucose, Pelargonium Graveolens Oil, Extrait de Fruit de Schizandra Chinensis, Hydrolyzed Hyaluronic Acid, Huile de Feuille d''Eugenia Caryophyllus, Tocopherol, Anthemis Nobilis Flower Oil, Ceramide NP, Chamomilla Recutita Flower Oil, Huile de Juniperus Mexicana, Pogostemon Cablin Oil', 'Réveille-toi avec une peau lisse et radieuse grâce au Vegan Kombucha Tea Sleep Mask Dr. Ceuracle ! Ce masque de nuit vegan est enrichi d''un puissant complexe de thé fermenté contenant des probiotiques, de la vitamine B et des nutriments essentiels pour détoxifier et soutenir les défenses immunitaires naturelles de ta peau. Le bakuchiol favorise la régénération de la peau et lui confère un éclat durable, tandis que le céramide, le squalane et les huiles d''origine végétale hydratent en profondeur et restaurent la barrière cutanée pour une hydratation durable. Cliniquement certifiée vegan, sa formule offre une hydratation respectueuse de la peau qui repulpe et lisse visiblement ton teint dès le matin, te procurant une apparence rafraîchie et radieuse au quotidien. Recommandé pour : Peaux normales à sèches.', 100, 'g', 'dr-ceuracle-vegan-kombucha-tea-sleep-mask', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-kombucha-tea-sleep-mask', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-kombucha-tea-sleep-mask.webp', 'Applique le produit en fine couche sur ton visage à l''aide de la spatule fournie et masse délicatement jusqu''à absorption du produit.', 2995, '2026-05-07 17:37:40.372102+00', '2026-06-14 15:14:07.797+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4416-7789-8858-5429348241c9', '__OWNER_ID__', 'Tea Tree Purifine Soothing Mask', 'Dr. Ceuracle', 'mask', 'pack', 'Aqua, Dipropylene Glycol, Glycerin, Niacinamide, Glycereth-26, Glycol Butylique, Paeonia Suffruticosa Root Extract, Centella Asiatica Extract, 1,2-Hexanediol, Chamomilla Recutita (Matricaria) Flower Extract, Carbomer, Trehalose, Panthenol, PEG-60 Huile de Ricin Hydrogénée, Caprylate/Caprate de Glycéryle, Gomme Xanthane, Allantoin, Glycérine Éthylhexyle, Potassium Hydroxide, Hamamelis Virginiana Leaf Extract, Melaleuca Alternifolia Leaf Extract, Disodium EDTA, Parfum', 'Le Tea Tree Purifine Soothing Mask Dr.Ceuracle est un masque tissu doux infusé d''une essence calmante qui purifie et apaise les peaux irritées sans aucun résidu collant. Formulé avec des extraits d''arbre à thé et de Centella Asiatica, ce masque offre un excellent soulagement pour les peaux sensibles, tandis que le tréhalose aide à retenir l''hydratation pour une action durable. Testé dermatologiquement et doux, il est parfait pour calmer les rougeurs et les irritations. Idéal pour les peaux sensibles, ce masque assure une expérience rafraîchissante et hydratante, laissant la peau douce et équilibrée. Recommandé pour : Peaux sensibles, tous types de peaux.', 1, 'pcs', 'dr-ceuracle-tea-tree-purifine-soothing-mask', 'https://korean-skincare.fr/products/dr-ceuracle-tea-tree-purifine-soothing-mask', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-tea-tree-purifine-soothing-mask.webp', 'Après avoir nettoyé ta peau et appliqué un tonique, applique le masque tissu, en l''ajustant aux traits de ton visage et en évitant le contour des yeux et des lèvres. Retire le masque au bout de 15 à 20 minutes. Tapote délicatement ta peau pour améliorer l''absorption.', 159, '2026-05-07 17:37:40.374366+00', '2026-06-14 15:14:07.798+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4418-7a09-a0d6-548cea54c680', '__OWNER_ID__', 'Vegan Active Berry Lifting Cream', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Aqua, Propanediol, Glycerin, Cyclohexasiloxane, 1,2-Hexanediol, Betaine, Polyglycéryl-3, Polyoléfine Hydrogénée C6-14, Isononyl Isononanoate, Dicaprylyl Carbonate, Caprylic/Capric Triglyceride, Stéarate de Polyglycéryl-10, Polydecène Hydrogéné, Laminaria Japonica Extract, Eclipta Prostrata Leaf Extract, Extrait de Fruit de Vaccinium Macrocarpon, Extrait d''Eclipta Prostrata, Melia Azadirachta Leaf Extract, Vitis Vinifera Seed Oil, Sodium Hyaluronate, Hydrogenated Lecithin, Olea Europaea Fruit Oil, Pelargonium Graveolens Oil, Lavandula Angustifolia Oil, Anthemis Nobilis Flower Oil, Citrus Aurantium Dulcis Peel Oil, Huile de Juniperus Mexicana, Copolymère D''Acryloyldiméthyltaurate/VP Ammonium, Alcool C14-22, Diméthicone Vinyl, Dimethiconol, Glucoside Alkyle C12-20, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Trométamine, Polyquaternium-51, Disodium EDTA, Adenosine, Fructooligosaccharides, Glycol Butylique, Gomme de Cyamopsis Tetragonoloba, Agar, Beta-Glucan, Hydrolyzed Hyaluronic Acid, Glucose, Squalane, Gomme Xanthane, Titanium Dioxide, Collagène, Moringa Oleifera Seed Oil, Filtrat de Fermentation de Leuconostoc/Racine de Radis, Resveratrol, Ceramide NP, Triéthoxycaprylylsilane, Hydroxyde d''Aluminium, Glycérine Éthylhexyle, Caprylyl Glycol', 'La Vegan Active Berry Lifting Cream Dr.Ceuracle est une crème hydratante à haute densité, certifiée vegan, conçue pour améliorer l''élasticité et la vitalité de la peau. Infusée de resvératrol encapsulé provenant de raisins français de première qualité et d''un Active Berry Complex reconstitué, cette crème aide à rajeunir la peau pour lui donner une apparence rebondie et pleine de jeunesse. Sa formule offre une hydratation intense grâce au squalane et à la bétaïne d''origine végétale, tandis que le collagène à faible poids moléculaire améliore la fermeté de la peau. Son système unique de libération par capsulage vegan garantit que les ingrédients actifs sont absorbés efficacement, laissant ta peau nette, liftée et pleine de vitalité. Recommandé pour : Peaux sèches, tous types de peaux.', 75, 'ml', 'dr-ceuracle-vegan-active-berry-lifting-cream', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-active-berry-lifting-cream', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-active-berry-lifting-cream.webp', 'Après avoir appliqué l''essence, prélève une quantité modérée et applique-la sur ta peau, en évitant le contour des yeux et de la bouche. Tapote délicatement ta peau pour favoriser l''absorption.', 2738, '2026-05-07 17:37:40.376526+00', '2026-06-14 15:14:07.798+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-441a-7d60-a63c-8aca563e2352', '__OWNER_ID__', 'Vegan Active Berry First Essence', 'Dr. Ceuracle', 'essence', 'dropper', 'Aqua, Glycerin, 1,2-Hexanediol, Methylpropanediol, Glycereth-26, Centella Asiatica Extract, Ficus Carica Fruit Extract, Laminaria Japonica Extract, Eclipta Prostrata Leaf Extract, Extrait de Fruit de Vaccinium Macrocarpon, Extrait d''Eclipta Prostrata, Melia Azadirachta Leaf Extract, Hydrogenated Lecithin, Sodium Hyaluronate, Vitis Vinifera Seed Oil, Olea Europaea Fruit Oil, Pelargonium Graveolens Oil, Lavandula Angustifolia Oil, Anthemis Nobilis Flower Oil, Citrus Aurantium Dulcis Peel Oil, Huile de Juniperus Mexicana, Diglycéride, Isononyl Isononanoate, Octyldodéceth-16, Carbomer, Trométamine, Adenosine, Disodium EDTA, Fructooligosaccharides, Glycol Butylique, Gomme de Cyamopsis Tetragonoloba, Agar, Beta-Glucan, Betaine, Hydrolyzed Hyaluronic Acid, Ceramide NP, Gomme Xanthane, Titanium Dioxide, Moringa Oleifera Seed Oil, Resveratrol, Collagène, Filtrat de Fermentation de Leuconostoc/Racine de Radis, Squalane, Triéthoxycaprylylsilane, Hydroxyde d''Aluminium, Hydroxyacétylphénone, Glycérine Éthylhexyle, Caprylyl Glycol', 'Découvre la Vegan Active Berry First Essence Dr.Ceuracle, une source d''hydratation et de vitalité pour ta peau. Cette essence vegan, infusée de 20 000 ppm d''Active Berry Complex, contient de l''extrait de raisin français de haute qualité, de l''huile de pépins de raisin et du cranbetinol, offrant une hydratation intense tout en stimulant la résilience naturelle de la peau. Enrichie en phyto-collagène provenant de légumes non OGM, elle améliore l''élasticité de la peau, la laissant rebondie et en bonne santé. Sa texture légère et aqueuse pénètre facilement et contient du resvératrol encapsulé qui combat le vieillissement et redonne à la peau un éclat de jeunesse. Parfaite après le nettoyage, elle retient l''hydratation, lisse le grain de la peau et revitalise ton teint à chaque utilisation. Recommandé pour : Peaux sèches, tous types de peaux.', 150, 'ml', 'dr-ceuracle-vegan-active-berry-first-essence', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-active-berry-first-essence', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-active-berry-first-essence.webp', 'Après le nettoyage, prépare ta peau avec une quantité appropriée de tonique. Masse légèrement ta peau pour que les capsules soient bien absorbées.', 1738, '2026-05-07 17:37:40.378725+00', '2026-06-14 15:14:07.798+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-441d-71a8-9c9d-44d18b10417a', '__OWNER_ID__', 'Vegan Active Berry Lip Oil', 'Dr. Ceuracle', 'lip-care', 'tube', 'Polyglycéryl-2 Isostéarate/Dimer Dilinoléate Copolymère, Caprylic/Capric Triglyceride, Simmondsia Chinensis Seed Oil, Ricinus Communis Seed Oil, Polyglycéryl-2 Triisostéarate, Tocopheryl Acetate, Dimer Dilinoléyl Dimer Dilinoléate, Silice Diméthyl Silylate, Vitis Vinifera Seed Oil, Extrait d''Eclipta Prostrata, Curcuma Longa Root Extract, Dehydroacetic Acid, Citric Acid, Melia Azadirachta Leaf Extract, CI 45410, Extrait de Fleur de Melia Azadirachta, Moringa Oleifera Seed Oil, Extrait de Corallina Officinalis, Extrait d''Écorce de Melia Azadirachta, Ocimum Sanctum Leaf Extract, Aqua, Squalane, Glycerin, Glycolipides, Oléate de Polyglycéryl-10, Collagène, 1,2-Hexanediol, Filtrat de Fermentation de Leuconostoc/Racine de Radis, Resveratrol, Extrait de Fruit de Vaccinium Macrocarpon, Caprylyl Glycol, Tocopherol', 'La Vegan Active Berry Lip Oil Dr.Ceuracle est ton produit de référence pour des lèvres pulpeuses et hydratées dans une teinte rose éclatante. Cette huile à lèvres vegan est enrichie d''un puissant mélange de vitamine E, de collagène d''origine végétale et d''huiles botaniques, notamment d''huiles de graines de jojoba et de pépins de grenade, pour nourrir et repulper tes lèvres. Infusé des complexes Active Berry Complex et E Complex, qui contiennent du resvératrol, de l''huile de pépins de raisin et de l''extrait de canneberge, il fournit des soins anti-âge délicats tout en revitalisant et en protégeant contre la déshydratation. Sa formule légère offre une hydratation intense et un éclat naturel, ce qui la rend parfaite pour une utilisation au quotidien et pour les looks glam.', 4, 'ml', 'dr-ceuracle-vegan-active-berry-lip-oil', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-active-berry-lip-oil', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-active-berry-lip-oil.webp', 'Applique généreusement sur tes lèvres au besoin.', 1268, '2026-05-07 17:37:40.381006+00', '2026-06-14 15:14:07.798+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4432-7eb8-b01f-662d9014b63f', '__OWNER_ID__', 'Hyal Reyouth Moist Sun', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Aqua, Adipate de Dibutyle, Propanediol, Ethylhexyl Triazone, Acide Téréphtalylidène Dicamphor Sulfonique, Distéarate de Polyglycéryl-3, Niacinamide, Tromethamine, 1,2-Hexanediol, Pentylene Glycol, Polysilicone-15, Benzoate de Diéthylamino Hydroxybenzoyl Hexyle, Cetearyl Alcohol, Glyceryl Stearate, Méthoxyphényle Triazine Bis-Éthylhexyloxyphénol, Glycerin, Carbomer, Parfum, Ammonium Acryloyldimethyltaurate/VP Copolymer, Citrate de Stéarate de Glycéryle, Carbamate de Lauryl d''Inuline, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Glutamate de Stéaroyl de Sodium, Sodium Hyaluronate, Ethylhexylglycerin, Adenosine, Methylpropanediol, Polyéther-1, Pantothénol, Tocopherol, Gomme de Biosaccharide-1, Inulin, Butylene Glycol, Hydrolyzed Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Hyaluronate de Diméthylsilanol, Hyaluronic Acid, Potassium Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Sodium Hyaluronate Crosspolymer, Sodium Acetylated Hyaluronate, Hyaluronate de Sodium Diméthylsilanol', 'Le Dr. Ceuracle Hyal Reyouth Moist Sunest une excellente crème solaire biologique SPF50+ PA++++ qui va au-delà de la simple protection solaire. Enrichie d''un puissant mélange de fructanes et de dix types d''acide hyaluronique, cette crème solaire protège non seulement ta peau des rayons UV nocifs, mais travaille aussi sans relâche pour lui insuffler une hydratation profonde et durable. Cette formule innovante retient l''hydratation et laisse ta peau souple, rebondie et incroyablement nourrie. Dis adieu à la peau sèche et terne et embrasse un teint radieux et revitalisé qui rayonne de santé. Renforcer les défenses naturelles de ta peau est une priorité absolue, et c''est pourquoi le duo dynamique du panthénol et de la niacinamide a été incorporé à la formule de cette crème solaire. Ensemble, ils fortifient la barrière d''hydratation de ta peau, offrant un bouclier contre les facteurs de stress environnementaux tout en améliorant sa capacité à retenir l''hydratation. Le résultat ? Une peau qui se sent bien protégée et qui semble naturellement radieuse. Recommandé pour : Tous types de peaux, peaux sensibles.', 50, 'ml', 'dr-ceuracle-hyal-reyouth-moist-sun', 'https://korean-skincare.fr/products/dr-ceuracle-hyal-reyouth-moist-sun', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-hyal-reyouth-moist-sun.webp', 'Applique lors de la dernière étape de ta routine beauté, 15 minutes avant l''exposition au soleil. Applique une quantité de la taille d''un doigt en 2 ou 3 doses. Renouvelle l''application fréquemment si nécessaire.', 1954, '2026-05-07 17:37:40.402816+00', '2026-06-14 15:14:07.798+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-441f-738c-9915-ba1a5247bdcd', '__OWNER_ID__', 'Vegan Kombucha Tea Essence', 'Dr. Ceuracle', 'essence', 'dropper', 'Aqua, Triéthylhexanoin, Hydrogenated Poly(C6-14 Olefin), 1,2-Hexanediol, Methylpropanediol, Butylene Glycol, Glycerin, Trilaureth-4 Phosphate, Camellia Sinensis Leaf Extract, Saccharomyces Ferment Filtrate, Camellia Sinensis Leaf Water, Huile de Graine de Helianthus Annuus (Tournesol) Non Saponifiables, Polyquaternium-51, Sodium Hyaluronate, Ethylhexylglycerin, Hydrogenated Lecithin, Dextrin, Theobroma Cacao Seed Extract, Centella Asiatica Extract, Ficus Carica Fruit Extract, Extrait de Fruit de Schisandra Chinensis, Extrait de Graine d’Amaranthus Caudatus, Ulmus Davidiana Root Extract, Ceramide NP', 'La Vegan Kombucha Tea Essence Dr.Ceuracle est un produit multitâche ingénieux qui pénètre comme un tonique et fonctionne comme un hybride crème-essence. La Vegan Kombucha Tea Essence est parfaite pour tous les types de peaux, en particulier les peaux sèches, sensibles, ternes ou déséquilibrées. Combinant les propriétés fortifiantes de l''extrait de thé kombucha avec des plantes botaniques et de l''huile végétale nourrissante, cette formule vegan est conçue pour offrir un teint éclatant et vibrant, en particulier pour les peaux sèches ou qui tiraillent, ou bien grasses en surface tout en étant déshydratées. Riche en probiotiques et en vitamine B, l''extrait de kombucha aide à renforcer la peau et à prévenir les effets néfastes de l''oxydation tout en rééquilibrant l''hydratation. L''eau de feuille de Camellia Sinensis (thé vert) et l''extrait de fruit de Schisandra Chinensis (omija), deux puissants antioxydants, hydratent et protègent plus en profondeur. L''huile de graines de tournesol vient nourrir la peau et lui confère un éclat velouté. Sans parfum. Recommandé pour : Types de peaux sèches, sensibles et d''aspect terne. Peut être utilisé pour : Tous types de peaux.', 150, 'ml', 'dr-ceuracle-vegan-kombucha-tea-essence', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-kombucha-tea-essence', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-kombucha-tea-essence.webp', 'Après avoir nettoyé ton visage, distribue une quantité appropriée de la Vegan Kombucha Tea Essence dans tes mains. Tapote délicatement l''essence sur ton visage, en insistant sur les zones qui ont besoin d''hydratation et de revitalisation. Laisse l''essence pénétrer dans ta peau et poursuis avec ta routine beauté habituelle. Utilise-la quotidiennement pour une peau hydratée et nourrie. **Agite bien l''essence pour la mélanger, elle doit être d''un blanc laiteux avant d''être appliquée.', 3032, '2026-05-07 17:37:40.38311+00', '2026-06-14 15:14:07.799+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4421-781e-9ba5-7a6f0bff4bf5', '__OWNER_ID__', 'Pro Balance Comfort Sun Stick SPF50+ PA++++', 'Dr. Ceuracle', 'moisturizer', 'jar', '1,2-Hexanediol, Adenosine, Alumina, Extrait de Grain d''Avena Sativa, Beta-Glucan, Bifida Ferment Lysate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Butyloctyl Salicylate, C18-21 Alkane, Camellia Sinensis Leaf Water, Caprylic/Capric Triglyceride, Glycol Caprylique, Extrait de Feuille de Cynara Scolymus, Dibutyl Adipate, Carbonate Dicaprylyl, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Diisopropyl Sébacate, Dimethicone, Dipropylene Glycol, Triazone Éthylhexyle, Ethylhexylglycerin, Fructooligosaccharides, Glutathione, Glycerin, Glyceryl Caprylate, Hydrogenated Lecithin, Palmitate Isopropylique, Lactobacillus Ferment, Lactobacillus Ferment Lysate, Lactobacillus Ferment, Extrait de Ferment de Fruit de Lactobacillus/Punica Granatum, Lactobacillus Ferment, Lactococcus Ferment Lysate, Lactococcus Ferment Lysate, Diméthicone Lauryl Polyglycéryl-3 Polydiméthylsiloxyéthyl, Leuconostoc Ferment Filtrate, Methylpropanediol, Lipides Laitiers, Niacinamide, Huile de Son d''Oryza Sativa, Ozokérite, Poly C10-30 Alkyl Acrylate, Polyglycéryl-4 Diisostearate/Polyhydroxystéarate/Sébacoate, Polyglycéryl-5 Polyricinoleate, Polyhydroxystearic Acid, Polyquaternium-51, Sodium Chloride, Stearic Acid, Synthetic Wax, Théanine, Titanium Dioxide, Tocopherol, Crosspolymère de Diméthicone Vinyl/Méthicone Silsesquioxane, Aqua', 'Le Pro Balance Comfort Sun Stick SPF50+ PA++++ Dr. Ceuracle est un stick solaire hybride pratique et efficace, conçu pour protéger ta peau des rayons UV nocifs grâce à une protection à large spectre. Ce stick solaire procure un effet rafraîchissant instantané pour diminuer la température de la peau et apaiser les peaux sensibles, en particulier lors des journées chaudes et ensoleillées. Infusé de 9 types de probiotiques et de prébiotiques, il aide à maintenir la peau en bonne santé et renforce la barrière cutanée pour prévenir la sécheresse et les gerçures. Enrichi en eau minérale, en lipides de lait et en huile d''arbre à thé, ce stick solaire réhydrate en profondeur la peau sèche tout en la protégeant et en l''apaisant sous l''effet des rayons UV puissants. Sa forme rectangulaire pratique assure une application facile et précise, ce qui en fait un incontournable de la protection solaire quotidienne. Recommandé pour : Peaux sensiblex, types de peaux normales à sèches.', 18, 'g', 'dr-ceuracle-pro-balance-comfort-sun-stick', 'https://korean-skincare.fr/products/dr-ceuracle-pro-balance-comfort-sun-stick', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-pro-balance-comfort-sun-stick.webp', 'Lors la dernière étape de ta routine beauté, applique légèrement sur les zones exposées au soleil. Emporte le stick avec toi et applique-le fréquemment sur les zones qui ont besoin d''une protection solaire.', 1755, '2026-05-07 17:37:40.385354+00', '2026-06-14 15:14:07.799+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6544-782b-ae0c-1f9f49c08c32', '__OWNER_ID__', 'Vichy Dercos Shampooing traitant pellicules et démangeaisons cheveux normaux/gras éco-recharge 390ml', 'Vichy', 'shampoo', 'pack', 'Aqua, Sodium Laureth Sulfate, Glycol Distearate, Coco-Betaine, Glycerin, Dimethicone, SELENIUM SULFIDE, Carbomer, CI 47005 / ACID YELLOW 3, Citric Acid, Menthol, 2-OLEAMIDO-1,3-OCTADECANEDIOL, PPG-5-CETETH-20, Salicylic Acid, Sodium Benzoate, Sodium Chloride, Sodium Hydroxide, Tocopheryl Acetate, Parfum', '', 390, 'ml', 'vichy-dercos-shampooing-traitant-pellicules-et-demangeaisons-cheveux-normaux-gras-eco-recharge-390ml-285718', 'https://www.atida.fr/vichy-dercos-shampooing-traitant-pellicules-et-demangeaisons-cheveux-normaux-gras-eco-recharge-390ml.html', 'https://aurore-cdn.b-cdn.net/products/vichy-dercos-shampooing-traitant-pellicules-et-demangeaisons-cheveux-normaux-gras-eco-recharge-390ml-285718.webp', '', 1353, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.871+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4426-715f-aa66-886a49a3d5b7', '__OWNER_ID__', 'Vegan Active Berry Firming Eye Cream', 'Dr. Ceuracle', 'eye-cream', 'jar', 'Aqua, Butylene Glycol, Glycerin, Caprylic/Capric Triglyceride, Cetearyl Alcohol, Diméthicone Vinylique, Olivate de Cétéaryle, Sorbitan Olivate, Isononyl Isononanoate, Limnanthes Alba Seed Oil, Betaine, Butyrospermum Parkii Butter, Simmondsia Chinensis Seed Oil, Extrait de Fruits de Vaccinium Macrocarpon, Extrait de Eclipta Prostrata, Laminaria Japonica Extract, Eclipta Prostrata Leaf Extract, Melia Azadirachta Leaf Extract, Vitis Vinifera Seed Oil, Sodium Hyaluronate, Olea Europaea Fruit Oil, Pelargonium Graveolens Oil, Lavandula Angustifolia Oil, Anthemis Nobilis Flower Oil, Citrus Aurantium Dulcis Peel Oil, Huile de Juniperus Mexicana, Hydrogenated Lecithin, Copolymère d''Acrylate d''Ammonium/Acryloyldiméthyltaurate/VP, Euphorbia Cerifera Cera, Polydecène Hydrogéné, Polyacryloyldiméthyltaurate de Sodium, Diméthicone/Diméthicone Vinylique Crosspolymère, Dimethiconol, Trisiloxane, Gomme Xanthane, Adenosine, Disodium EDTA, Gomme de Cyamopsis Tetragonoloba, Agar, Polyacrylate de Sodium, Glutathione, Squalane, Cholesterol, Tocopherol, Cyanocobalamin, Titanium Dioxide, Palmitic Acid, Stearic Acid, Collagène, Moringa Oleifera Seed Oil, Filtrat de Fermentation de Racine de Leuconostoc, Fructooligosaccharides, Resveratrol, Bakuchiol, Beta-Glucan, Ceramide NP, Hydrolyzed Hyaluronic Acid, Hydroxyde d''Aluminium, Triéthoxycaprylylsilane, 1,2-Hexanediol, Hydroxyacetophenone, Ethylhexylglycerin, Caprylyl Glycol', 'La Vegan Active Berry Firming Eye Cream Dr.Ceuracle est une gâterie luxueuse pour la peau délicate du contour des yeux, qu''elle nourrit et hydrate pour lui donner une apparence plus jeune. Enrichie d''un puissant complexe de baies actives, comprenant du resvératrol, de l''huile de pépins de raisin et du cranbetinol, elle revitalise la peau, renforçant sa vitalité et son éclat. Cette crème pour les yeux est également dotée du Highly Effective Activator Complex, qui contient des vitamines A, G et E, qui ciblent les signes précoces du vieillissement, tels que l''hyperpigmentation et les ridules, et qui améliorent efficacement la texture de la peau. Avec sa texture riche facilement absorbée par la peau, cette formule certifiée vegan et testée hypoallergénique resserre et rajeunit le contour des yeux, le laissant lisse, ferme et magnifiquement rafraîchi. Recommandé pour : Peaux normales, peaux mixtes, peaux sèches.', 32, 'g', 'dr-ceuracle-vegan-active-berry-firming-eye-cream', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-active-berry-firming-eye-cream', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-active-berry-firming-eye-cream.webp', 'Applique une quantité appropriée de produit et applique-le sur la zone autour de tes yeux. Avec l''applicateur, masse délicatement pour une absorption complète.', 2613, '2026-05-07 17:37:40.389974+00', '2026-06-14 15:14:07.799+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-444c-713b-b883-6b06b28b75ac', '__OWNER_ID__', 'Royal Vita Propolis 33 Cream', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Aqua, Butylene Glycol, Hippophae Rhamnoides Fruit Extract, Huile Végétale, Polyglycéryl-3 Distearate de Méthylglucose, Niacinamide, 1,2-Hexanediol, Copolymère Ammonium Acryloyldiméthyltaurate/VP, Camellia Japonica Seed Oil, 3-O-Ethyl Ascorbic Acid, Laminaria Japonica Extract, Eclipta Prostrata Leaf Extract, Centella Asiatica Extract, Ficus Carica Fruit Extract, Phellodendron Amurense Bark Extract, Extrait de Gelée Royale, Extrait d’Hamamélis Virginiana, Extrait d’Acmella Oleracea, Portulaca Oleracea Extract, Rosmarinus Officinalis Leaf Extract, Chamomilla Recutita (Matricaria) Flower Extract, Theobroma Cacao Seed Extract, Extrait de Graines de Lupinus Albus, Huile de Citrus Aurantium Dulcis, Eau de Fleurs de Rosa Centifolia, Sodium Hyaluronate, Hydrogenated Lecithin, Citrus Nobilis Peel Oil, Helianthus Annuus Seed Oil, Litsea Cubeba Fruit Oil, Stéaroyl Glutamate de Sodium, Adenosine, Fructooligosaccharides, Beta-Glucan, Hydrolyzed Hyaluronic Acid, Dextrin, Ceramide NP, Tocopherol, Hydroxyacéto-phénone, Ethylhexylglycerin', 'La Royal Vita Propolis 33 Eye Cream Dr.Ceuracle est une crème légère à la texture sérum qui revitalise et nourrit instantanément la peau délicate du contour des yeux. Enrichie à 33 % en extrait de propolis et en extrait de gelée royale, elle hydrate et aide à réparer la peau, laissant le regard plus lumineux et d’apparence plus jeune. Sa formule contient également de l’extrait de fruit d’argousier riche en antioxydants, des vitamines C et E, ainsi que du collagène, qui agissent ensemble pour protéger et renforcer la barrière d’hydratation. La crème est accompagnée d’un applicateur de massage doré qui intensifie l’effet rafraîchissant et apaisant, ce qui la rend idéale pour les contours des yeux fatigués, déshydratés ou sensibles.', 50, 'g', 'dr-ceuracle-royal-vita-propolis-33-cream', 'https://korean-skincare.fr/products/dr-ceuracle-royal-vita-propolis-33-cream', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-royal-vita-propolis-33-cream.webp', 'Applique une quantité appropriée uniformément sur l''ensemble de ton visage. Tapote délicatement pour améliorer l''absorption.', 2349, '2026-05-07 17:37:40.427969+00', '2026-06-14 15:14:07.799+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-442a-7657-8f28-b9af333b7cba', '__OWNER_ID__', 'Pure VC Mellight Boosting Essence', 'Dr. Ceuracle', 'essence', 'dropper', 'Aqua, Eau de Hippophae Rhamnoides, Methylpropanediol, Butylene Glycol, Glycerin, 1,2-Hexanediol, Niacinamide, Glycereth-26, Extrait de Feuille/Racine/Tige de Piper Methysticum, Laminaria Japonica Extract, Eclipta Prostrata Leaf Extract, Centella Asiatica Extract, Ficus Carica Fruit Extract, Phellodendron Amurense Bark Extract, Ulmus Davidiana Root Extract, Extrait de Graine d''Amaranthus Caudatus, Hydrogenated Lecithin, Lavandula Angustifolia Oil, Huile de Fruit de Citrus Aurantium Bergamia, Rosmarinus Officinalis Leaf Oil, Anthemis Nobilis Flower Oil, Sodium Hyaluronate, 3-O-Ethyl Ascorbic Acid, C12-14 Alkyl-12, Ammonium Acryloyldimethyltaurate/VP Copolymer, Sodium Citrate, Citric Acid, Fructooligosaccharides, Beta-Glucan, Hydrolyzed Hyaluronic Acid, Ceramide NP, Glutathione, Ferulic Acid, PVP, Ascorbic Acid, Tocopherol, Idebenone, Fullerenes, Ethylhexylglycerin, Linalool, Limonene', 'La Pure VC Mellight Boosting Essence Dr.Ceuracle est un élixir de soin enrichi de vitamine C pure pour transformer ton teint. Avec un puissant complexe VC de 21,2 %, comprenant de l''acide ascorbique, de l''acide 3-O-éthyl-ascorbique et de l''eau d''Hippophae Rhamnoides, cette essence offre une protection antioxydante contre les signes du vieillissement de la peau tout en éclaircissant la peau pour un teint clair et sain. L''inclusion de vitamine E, d''acide férulique, de niacinamide et de glutathion fait passer ce soin à un niveau supérieur en se chargeant de réparer les cellules cutanées endommagées et de réduire l''inflammation, tout en favorisant un teint uniforme. Laisse-toi tenter par la luxueuse texture à bulles du Pure VC Mellight Boosting Essence, qui est facilement absorbée par ta peau et te laisse avec une sensation de fraîcheur. L''eau d''Hippophae Rhamnoides, connue pour ses propriétés éclaircissantes pour la peau, contribue à un teint jeune et éclatant. Cette essence exploite également le pouvoir de l''idébénone pour prévenir la perte d''hydratation et raviver l''état de ta peau. Grâce à un mélange soigneusement sélectionné d''extraits botaniques, notamment l''extrait de feuille/racine/tige de Piper Methysticum, l''extrait de Centella Asiatica et l''huile de Lavandula Angustifolia (lavande), cette essence nourrit et apaise ta peau tout en lui conférant un délicieux parfum naturel. Adopte cette essence pour obtenir une peau rebondie et radieuse, grâce à sa capacité à stimuler l''élasticité de la peau et à créer un teint sain et éclatant. Recommandé pour : Peaux sèches, sans risques pour l''acné fongique, tous types de peaux.', 145, 'ml', 'dr-ceuracle-pure-vc-mellight-boosting-essence', 'https://korean-skincare.fr/products/dr-ceuracle-pure-vc-mellight-boosting-essence', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-pure-vc-mellight-boosting-essence.webp', 'Avant d''utiliser la Pure VC Mellight Ampoule, distribue la formule 1 à 2 fois dans la paume de ta main. Masse délicatement l''ensemble de ton visage en suivant ton grain de peau, puis tapote légèrement pour favoriser l''absorption du produit par ta peau. *Pour les peaux très sensibles, il est conseillé d''éviter d''utiliser le produit là où la peau est plus fine.', 2495, '2026-05-07 17:37:40.394289+00', '2026-06-14 15:14:07.8+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4435-7068-9611-99ed2c478143', '__OWNER_ID__', 'Hyal Reyouth Night Cream', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, Polydecène Hydrogéné, Phényl Triméthicone, Betaine, Polyglycéryl-3 Distearate de Méthylglucose, Cetyl Alcohol, Cyclohexasiloxane, Cyclopentasiloxane, Macadamia Integrifolia Seed Oil, Huile de Fruit d’Olea Europaea Olive, Niacinamide, Glyceryl Stearate, Behenyl Alcohol, Distearate de Pentaérythrityl, Trehalose, Panthenol, Dipropylene Glycol, Propanediol, Butylene Glycol, Methylpropanediol, 1,2-Hexanediol, Polyglycéryl-10 Laurate, Copolymère Ammonium Acryloyldiméthyltaurate/VP, Stéaroyl Glutamate de Sodium, Hydrogenated Lecithin, Hydroxyacéto-phénone, Ethylhexylglycerin, Disodium EDTA, Parfum, Adenosine, Beta-Glucan, Polyquaternium-51, Fructooligosaccharides, Inulin, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Sodium Acetylated Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Eclipta Prostrata Leaf Extract, Extrait d’Acmella Oleracea, Laminaria Japonica Extract, Panax Ginseng Root Extract, Extrait de Noyau d’Avoine Avena Sativa, Extrait de Feuille d’Artichaut Cynara Scolymus, Extrait de Pteris Multifida *Liste générale, les ingrédients peuvent varier selon la version du produit. Consulte l’emballage réel pour connaître les détails exacts', 'La Hyal Reyouth Night Cream Dr.Ceuracle est enrichie d''un mélange remarquable de six acides hyaluroniques différents, et est spécifiquement formulée pour étancher la soif des peaux sèches, en leur apportant une hydratation profonde et durable. La formule nourrissante de cette crème de nuit va au-delà de la surface, pénétrant toutes les couches de la peau pour apporter une hydratation intense, laissant ta peau rafraîchie et revitalisée chaque matin. Les vitamines B5 et B3 agissent harmonieusement pour fortifier la barrière d''hydratation de la peau, garantissant ainsi la rétention de l''hydratation pendant longtemps et empêchant la sécheresse de s''installer. En prime, l''inclusion de fructane, un type de fructose puissant, stimule la reproduction des cellules de la peau, favorisant un teint plus jeune et plus vibrant. Embrasse la magie de la Hyal Reyouth Night Cream Dr. Ceuracle et réveille-toi avec un teint rebondi, souple et magnifiquement radieux qui resplendit de santé et de vitalité. Laisse la puissance des acides hyaluroniques et l''efficacité des plantes transformer ta peau, nuit après nuit. Recommandé pour : Tous types de peaux.', 60, 'g', 'dr-ceuracle-hyal-reyouth-night-cream', 'https://korean-skincare.fr/products/dr-ceuracle-hyal-reyouth-night-cream', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-hyal-reyouth-night-cream.webp', 'Lors de la dernière étape de ta routine beauté du soir, applique délicatement une quantité appropriée de produit sur ta peau. Tapote délicatement pour faire pénétrer le produit dans ta peau.', 2836, '2026-05-07 17:37:40.404947+00', '2026-06-14 15:14:07.8+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4467-7e24-a7c9-750ea609cd1c', '__OWNER_ID__', '5α Control Clearing Serum In Emulsion', 'Dr. Ceuracle', 'serum', 'dropper', 'Aqua, Butylene Glycol, Dimethicone, Stéarate de Sorbitan, Extrait d''Ecorce/Feuille/Brindille d''Hamamelis Virginiana (Hamamélis), Cetyl Alcohol, Extrait d''Ecorce de Cinnamomum Zeylanicum, Extrait de Saccharomyces Cerevisiae, Extrait de Germe de Triticum Vulgare (Blé), Extrait de Beurre de Butyrospermum Parkii (Karité), Serenoa Serrulata Fruit Extract, Extrait de Graines de Sesamum Indicum (Sésame), Extrait de Phellinus Linteus, Extrait de Cordyceps Sinensis, Extrait de Ganoderma Lucidum (Champignon), Argania Spinosa Kernel Oil, Sodium Hyaluronate, Stéarate de Saccharose, Sarcosine, Capryloyl Glycine, Hexylene Glycol, Aluminium de Magnésium Silicate, Tocopheryl Acetate, Glyceryl Stearate, Bisabolol, Sesquioléate de Sorbitan, Cocoate de Saccharose, Cire de Drêche, Carbomer, Glycérides d''Amande PEG-60, Tromethamine, Dipotassium Glycyrrhizate, Gomme Xanthane, Disodium EDTA, Glycerin, Acide Nordihydroguaiarétique, Acide Oléanolique, Polysorbate 60, Stéarate PEG-100, Parfum, 1,2-Hexanediol, Hydroxyacetophenone, Caprylyl Glycol, Ethylhexylglycerin', 'Le Control Clearing Serum In Emulsion 5α Dr.Ceuracle aide à contrôler la production de sébum de la peau. Sa formule spéciale à base de Sepicontrol A5 réduit l''excès de sébum et la brillance de la peau grâce à une formule brevetée mise au point par le centre de recherche et de développement de Dr.Ceuracle. **Sepicontrol A5: Capryloyle Glycone, Cinnamomum Zeylanicum, Sarconsine. Ce produit fonctionne sur la base d''une technologie qui contrôle la 5 alpha-réductase, une hormone qui provoque une sécrétion anormale de sébum lorsque la peau connaît un déséquilibre. Bien que les peaux grasses aient tendance à briller en surface, à l''intérieur elles sont souvent très déshydratées. Une synergie exclusive d''extraits de champignons permet de nourrir intensément la peau en profondeur.', 100, 'ml', 'dr-ceuracle-5-alpha-control-clearing-serum-in-emulsion', 'https://korean-skincare.fr/products/dr-ceuracle-5-alpha-control-clearing-serum-in-emulsion', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-5-alpha-control-clearing-serum-in-emulsion.webp', 'Après avoir nettoyé et appliqué un tonique sur ton visage, distribue une quantité suffisante de produit et applique-le sur l''ensemble de ton visage. Masse délicatement pour faciliter l''absorption.', 2121, '2026-05-07 17:37:40.455748+00', '2026-06-14 15:14:07.802+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4439-7063-894f-8248e6008fda', '__OWNER_ID__', 'Tea Tree Purifine Green Up Sun', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Aqua, Zinc Oxide, Melaleuca Alternifolia Leaf Water, C12-15 Alkyl Benzoate, Titanium Dioxide, Butylene Glycol, Butyloctyl Salicylate, Crosspolymère De Diméthicone/Vinyl Diméthicone, Niacinamide, Polyglycéryl-10 Oléate, Isononyl Isononanoate, Adipate De Dibutyle, 1,2-Hexanediol, Propanediol, Pentylene Glycol, Caprylyl Méthicone, Polyméthylsilsesquioxane, Houttuynia Cordata Extract, Extrait D’Artemisia Capillaris, Portulaca Oleracea Extract, Melaleuca Alternifolia Leaf Oil, Coco-Caprylate/Caprate, Triéthoxycaprylylsilane, Polyhydroxystearic Acid, Olivate De Cétéaryle, Sorbitan Olivate, Copolymère VP/Eicosène, Hydroxyde D’Aluminium, Stearic Acid, Methylpropanediol, Dimethiconol, Trisiloxane, Silica, Polyquaternium-51, Dicaprylyl Carbonate, Taurate Polyacryloyldiméthyl De Sodium, Crosspolymère Polyacrylate-6, Glutamate Stéarylique De Sodium, Ethylhexylglycerin, Gomme Xanthane, Polyglycéryl-6 Polyricinoléate, Polyglycéryl-6 Polyhydroxystéarique, Adenosine, Alumina, Polyglycérine-6, Polyéther-1, Hydrolyzed Hyaluronic Acid, Biosaccharide Gum-1, Octadécane, Copolymère D’Acide Lactique/Glycolique, Caprylyl Glycol, Oxide De Chrome Vert, CI 77491', 'Le Tea Tree Purifine Green Up Sun Dr.Ceuracle est une crème solaire multifonctionnelle qui offre une protection solaire puissante tout en fonctionnant en même temps comme une base de maquillage. Sa base teintée d''une nuance verte aide à corriger les rougeurs de la peau, ce qui permet d''obtenir un teint naturel. Infusé d''extrait d''arbre à thé, cette crème solaire apaise les peaux sujettes aux imperfections grâce à ses propriétés anti-inflammatoires, tout en purifiant et en affinant les pores. Son acide hyaluronique de faible poids moléculaire réhydrate la peau en profondeur, lui donnant une sensation d''hydratation et de fraîcheur. De plus, le niacinamide aide à uniformiser le teint et à réduire les taches brunes, restaurant ainsi une peau claire et lumineuse. La Tea Tree Purifine Green Up Sun Dr. Ceuracle possède une formule écologique qui est sans danger pour l''écosystème marin, ce qui en fait un excellent choix pour les consommateurs soucieux de l''environnement. Elle est exempte de produits chimiques nocifs tels que les parabènes, les sulfates et les huiles minérales, ce qui la rend douce et sans danger pour tous les types de peaux. Recommandé pour : Tous types de peaux.', 50, 'ml', 'dr-ceuracle-tea-tree-purifine-green-up-sun', 'https://korean-skincare.fr/products/dr-ceuracle-tea-tree-purifine-green-up-sun', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-tea-tree-purifine-green-up-sun.webp', 'Lors de la dernière étape de ta routine beauté, applique une couche généreuse de produit avant l''exposition au soleil. Renouvelle l''application régulièrement.', 1855, '2026-05-07 17:37:40.408962+00', '2026-06-14 15:14:07.8+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6554-7272-9fbd-9f31ae34c691', '__OWNER_ID__', 'Klorane Beurre de Cupuaçu Gel Douche Parfum Sève de Bambou 200ml', 'Klorane', 'body-wash', 'bottle', 'Aqua, Sodium Laureth Sulfate, Lauryl Betaine, Decyl Glucoside, Caprylyl Glycol, Ceteareth-60 Myristyl Glycol, Citric Acid, Coco-Glucoside, Parfum, Glyceryl Oleate, green 3 (ci 42053), Helianthus Annuus Seed Oil, hydrogenated palm glycerides citrate, peg-7 glyceryl cocoate, Phenoxyethanol, Sodium Benzoate, Sodium Chloride, Theobroma Grandiflorum Seed Butter, Tocopherol, CI 19140', '', 200, 'ml', 'klorane-beurre-de-cupuacu-gel-douche-parfum-seve-de-bambou-200ml-275242', 'https://www.atida.fr/klorane-beurre-de-cupuacu-gel-douche-parfum-seve-de-bambou-200ml-7014451.html', 'https://aurore-cdn.b-cdn.net/products/klorane-beurre-de-cupuacu-gel-douche-parfum-seve-de-bambou-200ml-275242.webp', '', 669, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.8+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-443b-716c-b1b0-a7ddff9a7762', '__OWNER_ID__', 'Vegan Kombucha Tea BB SPF30 PA++', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Camellia Sinensis Leaf Water, Camellia Sinensis Leaf Extract, Saccharomyces Ferment Filtrate, Dipropylene Glycol, Caprylic/Capric Triglyceride, Titanium Dioxide, Cyclopentasiloxane, Dicaprylate/Dicaprate de Butylène Glycol, Salicylate de Butyloctyle, Dimethicone, Polyglycéryl-S Polyricinoléate, Méthylaminopropionate de Myristoyl Hexyldecyl, Niacinamide, Hexahydroxystéarate d''Hexaérythritol/Dihexastéarate/Dihexarosinate, Magnesium Sulfate, Extrait de Fruit de Schisandra Chinensis, Huile de Son de Riz, Sodium Hyaluronate, Zinc Oxide, Héctorite de Disteardimonium, Copolymère de Diméthicone/Vinyl Diméthicone, Panthenol, Isostéarate de Polyglycéryl-4, Polyméthylsilsesquioxane, Euphorbia Cerifera Cera, Diisostéarate/ Polyhydroxystéarate/Sebacate de Polyglyceryl-4, Triéthoxycaprylylsilane, Glyceryl Caprylate, Trihydroxystéarine, Butylene Glycol, Oléate de Polyglycéryl-3, Hydroxyde d''Aluminium, Aqua, Dimer Dilinoléate de Polyglyceryl-3 Diisostéaroyl, Adenosine, Tocopherol, 1,2-Hexanediol, Parfum, Caprylyl Glycol, Ethylhexylglycerin, Oxydes de Fer CI 77492, Oxydes de Fer CI 77491, Oxydes de Fer CI 77499', 'La Vegan Kombucha Tea BB Dr.Ceuracle est une crème hydratante teintée qui offre une couvrance naturelle et légère pour celles qui recherchent un maquillage de type "seconde peau". Formulée avec 20 % d''extrait de thé Kombucha, elle offre de puissants bienfaits antioxydants et est enrichie d''autres ingrédients respectueux de la peau comme le niacinamide, le panthénol et l''adénosine. Avec un FPS 30 et un PA++, cette BB crème offre une protection solaire tout en unifiant le teint. Elle est disponible en deux teintes, adaptées à un large éventail de carnations. Parfaite pour celles et ceux qui souhaitent obtenir un teint impeccable et lumineux tout en prenant soin de leur peau.', 30, 'ml', 'dr-ceuracle-vegan-kombucha-tea-bb', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-kombucha-tea-bb', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-kombucha-tea-bb.webp', 'Lors de la dernière étape de ta routine beauté, applique uniformément une quantité appropriée de crème sur ton visage.', 1695, '2026-05-07 17:37:40.410993+00', '2026-06-14 15:14:07.8+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-443f-74f2-a79b-4244d52f1666', '__OWNER_ID__', '5α Control No Sebum Sun Lotion SPF50+ PA++++', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Aqua, Zinc Oxide, Cyclohexasiloxane, Disiloxane, Salicylate de Butyloctyle, Titanium Dioxide, Dicaprylate/dicaprate de Butylène Glycol, Caprylyl Méthicone, Propanediol, Polymère Croisé de Méthacrylate de Méthyle, Silica, Extrait d''écorce de Cinnamomum Zeylanicum, Lauryl Polyglycéryl-3 Polydiméthylsiloxyéthyle Diméthicone, Stearic Acid, Hydroxyde d''Aluminium, Triéthoxycaprylyl Silane, Sodium Chloride, 1,2-Hexanediol, Polyglycéryl-3 Polydiméthylsiloxyéthyldiméthicone, Caprylylglycol, Glyceryl Caprylate, Ethylhexylglycerin, Candida Ferment, Butylene Glycol, Capryloyl Glycine, Hexylene Glycol, Glycérides d''Amande PEG-60, Sarcosine, Tocopherol, Glycerin, Carbomer, Acide Oléanolique, Acide Nordihydroguaiarétique, Parfum, Potassium Sorbate', 'La Control No Sebum Sun Lotion 5α Dr.Ceuracle est un écran solaire léger et rafraîchissant offrant une puissante protection SPF50+ PA++++ tout en préparant la peau pour le maquillage et lui conférant un effet bonne mine naturel. Formulée avec le complexe 5α, elle contrôle l''excès de sébum pour une finition mate et non grasse. Elle contient également de la vitamine E, qui aide à maintenir la peau hydratée et éclatante tout au long de la journée. Sa formule légère et rafraîchissante est rapidement absorbée par la peau, la laissant douce et lisse. Cette lotion est adaptée aux peaux sensibles et est parfaite pour ceux qui souhaitent obtenir un teint impeccable et radieux tout en protégeant leur peau du soleil. Elle est idéale pour une utilisation quotidienne et peut être utilisée comme base de maquillage grâce à sa capacité à contrôler la production de sébum.', 50, 'ml', 'dr-ceuracle-5a-control-no-sebum-sun-lotion-spf50-pa', 'https://korean-skincare.fr/products/dr-ceuracle-5a-control-no-sebum-sun-lotion-spf50-pa', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-5a-control-no-sebum-sun-lotion-spf50-pa.webp', 'Applique le produit sur les zones exposées de ton visage ou de ton corps, 30 minutes avant de sortir au soleil. Réapplique toutes les deux heures pour une protection solaire optimale pendant la journée.', 2345, '2026-05-07 17:37:40.415203+00', '2026-06-14 15:14:07.8+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6557-7feb-9d74-ea6eb92ac51f', '__OWNER_ID__', 'L''Oréal Professionnel Serie Expert Absolut Repair Masque 250ml', 'L''Oréal Professionnel', 'hair-mask', 'bottle', 'Aqua, Cetearyl Alcohol, Behentrimonium Chloride, candelilla cera / candelilla wax / cire de candelilla, amodimethicone, cetyl esters, isopropyl alcohol, Glycerin, Phenoxyethanol, trideceth-6, Linalool, Lactic Acid, Hexyl Cinnamal, chlorhexidine digluconate, Cetrimonium Chloride, Limonene, Sodium Hydroxide, chenopodium quinoa seed extract, hydroxypropyltrimonium hydrolyzed wheat protein, CI 19140, ci 15985 / yellow 6, Parfum', '', 250, 'ml', 'l-oreal-professionnel-serie-expert-absolut-repair-masque-250ml-254768', 'https://www.atida.fr/l-oreal-professionnel-serie-expert-absolut-repair-masque-250ml.html', 'https://aurore-cdn.b-cdn.net/products/l-oreal-professionnel-serie-expert-absolut-repair-masque-250ml-254768.webp', '', 2540, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.801+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6553-7034-ad6c-a0e9f92323ec', '__OWNER_ID__', 'Klorane Beurre de Cupuaçu Gel Douche Nutritif Eau de Tiaré 200ml', 'Klorane', 'body-wash', 'bottle', 'Aqua, Sodium Laureth Sulfate, Lauryl Betaine, Decyl Glucoside, Caprylyl Glycol, Ceteareth-60 Myristyl Glycol, Citric Acid, Coco-Glucoside, Parfum, Glyceryl Oleate, green 3 (ci 42053), Helianthus Annuus Seed Oil, hydrogenated palm glycerides citrate, peg-7 glyceryl cocoate, Phenoxyethanol, Sodium Benzoate, Sodium Chloride, Theobroma Grandiflorum Seed Butter, Tocopherol, CI 19140', '', 200, 'ml', 'klorane-beurre-de-cupuacu-gel-douche-nutritif-eau-de-tiare-200ml-275235', 'https://www.atida.fr/klorane-beurre-de-cupuacu-gel-douche-parfum-eau-de-tiare-200ml-7014416.html', 'https://aurore-cdn.b-cdn.net/products/klorane-beurre-de-cupuacu-gel-douche-nutritif-eau-de-tiare-200ml-275235.webp', '', 621, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.815+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4445-78e7-9a9c-313ee8a1c485', '__OWNER_ID__', 'Vegan Kombucha Tea Lip Balm', 'Dr. Ceuracle', 'lip-care', 'tube', 'Polyglyceryl-2 Triisostearate, Squalane, Bis-Diglyceryl Polyacyladipate-2, Caprylic/Capric Triglyceride, Octyldodecanol, Dimer Dilinoléate de Phytostéryl/Isostéaryl/Cétyle/Stéaryle/Béhényle, Synthetic Wax, Octyldodécyl Stearoyl Stearate, Polyhydroxystearic Acid, Butyrospermum Parkii Butter, Copolymère Éthylène/Propylène, Euphorbia Cerifera Cera, Cire de Copernicia Cerifera, Extrait de Eclipta Prostrata, Eclipta Prostrata Leaf Extract, Moringa Oleifera Seed Oil, Aqua, Melia Azadirachta Leaf Extract, Extrait de Fleur de Melia Azadirachta, Butylene Glycol, Ceramide NP, Citric Acid, Ocimum Sanctum Leaf Extract, Candida Ferment, Camellia Sinensis Leaf Extract, Extrait de Corallina Officinalis, Huile de Germes de Oryza Sativa, Saccharomyces Ferment Filtrate, Extrait de Fruit de Schisandra Chinensis, 1,2-Hexanediol, Extrait de Racine de Anemarrhena Asphodeloides', 'Le Vegan Kombucha Tea Lip Balm Dr.Ceuracle est un baume à lèvres nourrissant qui prend soin des lèvres sèches et abîmées. Formulé avec des huiles fermentées qui renforcent la barrière lipidique et assurent une hydratation en profondeur, ce baume contient également du Kombucha (thé noir fermenté) pour éliminer les toxines, tandis que le beurre de karité et les céramides maintiennent l''équilibre hydrique de la peau pour prévenir les peaux sèches et gercées.', 3, 'g', 'dr-ceuracle-vegan-kombucha-tea-lip-balm', 'https://korean-skincare.fr/products/dr-ceuracle-vegan-kombucha-tea-lip-balm', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-vegan-kombucha-tea-lip-balm.webp', 'Applique généreusement sur tes lèvres au besoin.', 1268, '2026-05-07 17:37:40.421463+00', '2026-06-14 15:14:07.801+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4447-7989-8b62-e354a22cde59', '__OWNER_ID__', 'Ganghwa Rice Granule Pack', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Oryza Sativa Extract, Glycerin, Aqua, Zea Mays Starch, Poudre de Tige de Bambusa Arundinacea, 1,2-Hexanediol, Nitrure de Bore, Poudre de Oryza Sativa (Riz), Extrait de Pulpe de Solanum Tuberosum (Pomme de Terre), Betaine, Extrait de Graine de Avena Sativa (Avoine), Hydrogenated Lecithin, Sodium Hyaluronate, Polyacrylate-13, Tromethamine, Poudre de Coque de Oryza Sativa (Riz), Hydrogenated Polyisobutene, Copolymère Acrylates/C10-30 Alkyl Acrylate, Gomme Xanthane, Poudre de Graine de Coix Lacryma-Jobi Ma-yuen, Laurate de Polyglycéryl-10, Ethylhexyl Palmitate, Sorbitan Isostearate, Caprylic/Capric Triglyceride, Ceramide NP, Glutamate de Phytostéryl/Octyldodécyl, Parfum, Ethylhexylglycerin', 'Le Ganghwa Rice Granule Pack Ceuracle est un masque à rincer qui contient 30 % d''extrait de riz provenant de l''île immaculée de Ganghwa, fermenté pendant 50 heures et mûri pendant encore 50 heures pour fournir une concentration élevée de vitamines C, A, E et B. Également infusé de poudre de graines d''herbe à chapelets et de poudre de coque de riz, ce gommage sous forme de crème utilise ses trois types de grains pour déloger en douceur les cellules mortes, les impuretés et les pores obstrués afin d''équilibrer le sébum tout en affinant et en adoucissant la texture de la peau. Le céramide NP ajouté renforce la barrière d''hydratation et prévient la perte d''hydratation pour que la peau soit revitalisée et hydratée tout en paraissant lumineuse et éclaircie.', 100, 'g', 'dr-ceuracle-ganghwa-rice-granule-pack', 'https://korean-skincare.fr/products/dr-ceuracle-ganghwa-rice-granule-pack', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-ganghwa-rice-granule-pack.webp', 'Après le nettoyage, applique sur ton visage, en évitant le contour des yeux et de la bouche. Après 10 à 15 minutes, rince soigneusement à l''eau tiède.', 2150, '2026-05-07 17:37:40.423492+00', '2026-06-14 15:14:07.801+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-444e-7201-b144-24fe01bf7845', '__OWNER_ID__', 'Cica Regen Vegan Sun SPF50', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Aqua, Adipate de Dibutyle, Propanediol, Alcohol, Ethylhexyl Triazone, Acide Sulfonique de Terephtalidène Dicamphor, Glycerin, Niacinamide, Tromethamine, Distearate de Polyglycéryl-3, 1,2-Hexanediol, Benzoate de Diéthylamino Hydroxybenzoyl Hexyl, Centella Asiatica Extract, Cetyl Alcohol, Méthicone de Caprylyl, Pentylene Glycol, Polysilicone-15, Extrait de Fruit d''Actinidia Arguta, Extrait de Fleur de Nelumbium Speciosum, Extrait de Fleur d''Hibiscus Sabdariffa, Rosmarinus Officinalis Leaf Oil, Polyméthylsilsesquioxane, Palmitic Acid, Stearic Acid, Glyceryl Stearate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Phosphate de Cétyle de Potassium, Methylpropanediol, Polyéther-1, Carbomer, Copolymère d''Acrylate/VP d''Ammonium Acryloyldiméthyltau rate, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Citrate de Stéarate de Glycéryle, Ethylhexylglycerin, Polyquaternium-51, Adenosine, Myristic Acid, Madecassoside, Acide Madécassique, Asiaticoside, Acide Asiatique', 'Le Cica Regen Vegan Sun Dr.Ceuracle est une crème solaire vegan qui offre une protection SPF 50+ PA++++ tout en nourrissant et en hydratant la peau. Formulée avec le complexe Centella (acide asiatique / acide madécassique / asiaticoside), cette crème solaire chimique légère offre une protection contre les UV et a des effets hydratants et anti-inflammatoires. Elle apaise la peau grâce au complexe Cica Barrier et à l''extrait de Centella Asiatica, et renforce la barrière cutanée grâce au polyquaternium-51. Sa formule douce et légère laisse un fini non collant.', 50, 'ml', 'dr-ceuracle-cica-regen-vegan-sun', 'https://korean-skincare.fr/products/dr-ceuracle-cica-regen-vegan-sun', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-cica-regen-vegan-sun.webp', 'Applique sur les zones exposées du visage/corps 30 minutes avant de sortir au soleil. Renouvelle l''application toutes les deux heures pour une protection solaire parfaite pendant la journée.', 1995, '2026-05-07 17:37:40.430035+00', '2026-06-14 15:14:07.802+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-446a-74f6-87f0-67ded1a4d077', '__OWNER_ID__', 'Royal Vita Propolis 33 Ampoule', 'Dr. Ceuracle', 'serum', 'dropper', 'Extrait de Propolis, Butylene Glycol, Aqua, Panthenol, Eau de Fleur de Rosa Centifolia, Extrait de Pourpier (Portulaca Oleracea), Niacinamide, Propylene Glycol, 1,2-Hexanediol, Extrait de Fruit d''Argousier (Hippophae Rhamnoides), 3-O-Ethyl Ascorbic Acid, Carbomer, Arginine, Phenoxyethanol, Sodium Hyaluronate, Hydroxyéthylcellulose, Adenosine, Centella Asiatica Extract, Extrait d''Hamamélis de Virginie (Hamamelis Virginiana), Extrait de Gelée Royale, Extrait de Spirodela Polyrrhiza', 'La Royal Vita Propolis 33 Ampoule Dr.Ceuracle est une ampoule sérum polyvalente qui nourrit et hydrate la peau en profondeur. Elle contient 33% de propolis pure naturellement réparatrice, de l''extrait de gelée royale pour protéger la peau des radicaux libres et de l''extrait d''algues pour éclaircir les pigmentations. Elle apaise également la peau grâce au panthénol et au niacinamide, et atténue les ridules et les irrégularités du teint. Convient à tous les types de peau, en particulier aux peaux sensibles et sujettes à l''acné.', 30, 'ml', 'dr-ceuracle-royal-vita-propolis-33-ampoule', 'https://korean-skincare.fr/products/dr-ceuracle-royal-vita-propolis-33-ampoule', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-royal-vita-propolis-33-ampoule.webp', 'Après avoir nettoyé et préparé ta peau avec un tonique. Applique délicatement une petite quantité de produit. Masse délicatement pour une meilleure absorption.', 2836, '2026-05-07 17:37:40.458182+00', '2026-06-14 15:14:07.802+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4450-7284-b1e5-0c2b81489008', '__OWNER_ID__', 'Tea Tree Purifine Cleansing Foam', 'Dr. Ceuracle', 'cleanser', 'tube', 'Aqua, Melaleuca Alternifolia Leaf Extract, Phosphate de potassium laureth, Glycinate de cocoyl de potassium, Alaninate de cocoyl de sodium, Diisostéarate de PEG-90, Cocamidopropyl Betaine, Butylene Glycol, Citric Acid, Sodium Chloride, Sodium Benzoate, 1,2-Hexanediol, Glycerin, Éthyl hexanediol, Butyrospermum Parkii Butter, Méthylcellulose hydroxypropyl, Chlorure de guar hydroxypropyltrimonium, Lavandula Angustifolia Oil, Oléate de polyglycéryl-10, Hydrogenated Lecithin, Melaleuca Alternifolia Leaf Oil, Propylene Glycol, Trehalose, Extrait d''écorce de Morus Alba, Extrait de Spirodela polyrhiza, Hippophae Rhamnoides Fruit Extract, Centella Asiatica Extract, Extrait d''écorce de Salix nigra (Saule), Extrait de feuille de Adansonia digitata, Hamamelis Virginiana Water', 'La Tea Tree Purifine 30 Cleansing Foam Dr.Ceuracle est un nettoyant pour le visage doux malgré le nettoyage en profondeur qu''il offre à la peau. En se transformant d''un gel en une mousse, ses bulles douces dissolvent délicatement la saleté et les impuretés tandis que l''arbre à thé apaise les imperfections, le tréhalose et le beurre de karité hydratent, et l''extrait d''argousier stimule l''élasticité de la peau.', 150, 'ml', 'dr-ceuracle-tea-tree-purifine-cleansing-foam', 'https://korean-skincare.fr/products/dr-ceuracle-tea-tree-purifine-cleansing-foam', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-tea-tree-purifine-cleansing-foam.webp', 'Utilise le nettoyant matin et soir, après le démaquillage. Commence par humidifier tes mains et ton visage. Distribue une quantité suffisante de nettoyant sur tes mains mouillées pour le faire mousser. Masse délicatement ton visage en évitant le contour des yeux et de la bouche. Rince à l''eau tiède.', 2249, '2026-05-07 17:37:40.432054+00', '2026-06-14 15:14:07.802+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4481-7198-bd12-bcfdd92b691d', '__OWNER_ID__', 'White Collagen Cleansing Foam', 'Mary&May', 'cleanser', 'tube', 'Extrait de collagène hydrolysé (46,6 %), Myristic Acid, Palmitic Acid, Glycerin, Stearic Acid, Potassium Hydroxide, Lauric Acid, Aqua, Cera Alba, Dipropylene Glycol, Lauryl hydroxysultaine, Niacinamide, Glyceryl Stearate SE, 1,2-Hexanediol, Hydroxyacetophenone, Butylene Glycol, Caprylyl Glycol, Disodium EDTA, Sodium Hyaluronate, Parfum', 'La White Collagen Cleansing Foam MARY & MAY est une mousse riche et crémeuse qui élimine en profondeur les impuretés et équilibre la production de sébum tout en redonnant à la peau son éclat et sa fermeté. Contient également de l''acide hyaluronique pour des bienfaits hydratants supplémentaires.', 150, 'ml', 'mary-may-white-collagen-cleansing-foam', 'https://korean-skincare.fr/products/mary-may-white-collagen-cleansing-foam', 'https://aurore-cdn.b-cdn.net/products/mary-may-white-collagen-cleansing-foam.webp', 'Utilise le nettoyant matin et soir, après le démaquillage. Commence par humidifier tes mains et ton visage. Distribue une quantité suffisante de nettoyant sur tes mains mouillées pour le faire mousser. Masse délicatement ton visage en évitant le contour des yeux et de la bouche. Rince à l''eau tiède.', 1268, '2026-05-07 17:37:40.480975+00', '2026-06-14 15:14:07.802+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4454-75a0-a575-85212733a466', '__OWNER_ID__', '5α Control Melting Cleansing Gel', 'Dr. Ceuracle', 'cleanser', 'tube', 'Cétyléthylhexanoate, PEG-40 Huile de Ricin Hydrogénée, Aqua, Glycerin, Méthyl Gluceth-20, Sorbitol, Isotridecyl Isononanoate, Octyldodéceth-25, Hexyldecyl Myristoylmethylaminopropionate, 1,2-Hexanediol, Butylene Glycol, Hydroxyacetophenone, Parfum, Capryloyl Glycine, Alcohol, Tocopheryl Acetate, Hexylene Glycol, Candida Ferment, Ethylhexylglycerin, Sarcosine, Extrait d''écorce de Cinnamomum Zeylanicum, Extrait d''écorce/feuille/tige d''Hamamelis Virginiana (Hamamélis), Phenoxyethanol, Aloe Barbadensis Leaf Juice, Potassium Sorbate, Portulaca Oleracea Extract, PEG-60 Glycérides d''Amande, Caprylyl Glycol, Citric Acid, Sodium Benzoate, Extrait de Phellinus Linteus, Extrait de Cordyceps Sinensis, Extrait de Ganoderma Lucidum (Champignon), Carbomer, Acide Oléanolique, Acide Nordihydroguaïarétique', 'Le Control Melting Cleansing Gel 5α Dr.Ceuracle est un gel transparent à haute viscosité qui s''étale délicatement sur le visage et s''émulsifie sans eau grâce à un léger frottement, débarrassant la peau des impuretés et du maquillage. Son système d''émulsification unique fait fondre les impuretés présentes sur le visage, le laissant propre et rafraîchi.', 150, 'ml', 'dr-ceuracle-5-alpha-control-melting-cleansing-gel', 'https://korean-skincare.fr/products/dr-ceuracle-5-alpha-control-melting-cleansing-gel', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-5-alpha-control-melting-cleansing-gel.webp', 'Distribue une quantité suffisante de produit dans tes mains sèches. Masse doucement en mouvements circulaires sur ton visage pendant environ 30 secondes jusqu''à ce que la texture se ramollisse. Rince à l''eau tiède.', 1895, '2026-05-07 17:37:40.436244+00', '2026-06-14 15:14:07.803+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4465-7b11-814b-a17871541a31', '__OWNER_ID__', 'Jeju Matcha Clay Pack', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Aqua, Kaolin, Dipropylene Glycol, Bentonite, Camellia Sinensis Leaf Extract, Betaine, Silica, Butylene Glycol, Montmorillonite, 1,2-Hexanediol, Illite, Urée Hydroxyéthyle, Cellulose, Gomme Xanthane, Oxyde de Chrome Vert (CI 77288), Citric Acid, Disodium EDTA, Parfum, Hydroxyacetophenone, Ethylhexylglycerin', 'Le Jeju Matcha Clay Pack Dr. Ceuracle est un masque à l''argile à rincer. Composé de thé vert Matcha récolté sur l''île de Jeju, la plus propre en Corée, ce masque d''argile à rincer utilise également des argiles Kaolin et Bentonite pour dégager les pores obstrués, éliminer l''excès de sébum et éliminer les cellules mortes de la surface de la peau. Les pores semblent plus serrés, la peau plus nette et le parfum rafraîchissant du thé vert aide à revitaliser ton teint. Testé dermatologiquement pour sa douceur et sa fiabilité. Convient à tous les types de peau.', 115, 'g', 'dr-ceuracle-jeju-matcha-clay-pack', 'https://korean-skincare.fr/products/dr-ceuracle-jeju-matcha-clay-pack', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-jeju-matcha-clay-pack.webp', 'Après le nettoyage, applique sur ton visage, en évitant le contour des yeux et de la bouche. Après 10 à 15 minutes, rince soigneusement à l''eau tiède.', 2150, '2026-05-07 17:37:40.45357+00', '2026-06-14 15:14:07.803+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4458-7abc-b86e-fede3f164767', '__OWNER_ID__', 'Hyal Reyouth Lifting Mask Set', 'Dr. Ceuracle', 'mask', 'pack', 'Aqua, Glycerin, Dipropylene Glycol, Alcohol, Copolymère PEG/PPG-17/6, Butylene Glycol, 1,2-Hexanediol, Paeonia Suffruticosa Root Extract, Centella Asiatica Extract, Copolymère Acryloyldiméthyltaurate d''Ammonium/VP, Trehalose, Panthenol, Huile de Ricin Hydrogénée PEG-60, Chamomilla Recutita (Matricaria) Flower Extract, Glyceryl Caprylate, Carbomer, Adenosine, Ethylhexylglycerin, Potassium Hydroxide, Sodium Hyaluronate, Hyaluronate de Sodium Hydroxypropyltrimonium, Propanediol, Collagène Hydrolysé, Sodium Hyaluronate Crosspolymer, Glycosaminoglycanes Hydrolysées, Glycol de Benzyle, Hydrolyzed Hyaluronic Acid, Sodium Acetylated Hyaluronate, Hyaluronic Acid, Cétone de Framboise, Disodium EDTA, Parfum, Linalool', 'Le Hyal Reyouth Lifting Mask Set Dr. Ceuracle restaure les peaux sèches, déshydratées ou d''aspect rugueux qui manquent d''hydratation. Ce masque tissu utilise un complexe 6-Hyaluronic et des vitamines B5 et B3. Le complexe 6-Hyal comprend une combinaison intensément nourrissante de molécules d''hydratation qui agissent ensemble pour prévenir la perte d''hydratation, renforcer l''élasticité de la peau, fournir une hydratation durable et former une barrière d''hydratation à la surface de la peau. Le panthénol (vitamine B5) associé à la vitamine B3 prévient davantage la perte d''hydratation et stimule la production de collagène, tandis que l''adénosine raffermit la peau.', 1, 'pcs', 'dr-ceuracle-hyal-reyouth-lifting-mask-set', 'https://korean-skincare.fr/products/dr-ceuracle-hyal-reyouth-lifting-mask-set', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-hyal-reyouth-lifting-mask-set.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 195, '2026-05-07 17:37:40.440564+00', '2026-06-14 15:14:07.803+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-445a-7d22-a60c-70cda9e654f0', '__OWNER_ID__', 'Pro Balance Creamy Cleansing Foam', 'Dr. Ceuracle', 'cleanser', 'tube', 'Aqua, Myristic Acid, Glycerin, Potassium Hydroxide, Lauric Acid, Palmitic Acid, Stearic Acid, Glucoside de Glycéryle, Lauryl Betaine, Polyglycéryl-2 Stéarate, Cera Alba, Glyceryl Stearate, Stearyl Alcohol, Citrus Aurantium Dulcis Peel Oil, Citrus Paradisi Peel Oil, Huile de Fruit de Citrus Aurantium Bergamia (Bergamote), Butylene Glycol, Glucose, Disodium EDTA, Melaleuca Alternifolia Leaf Oil, Hydrolyzed Hyaluronic Acid, Citrus Limon Fruit Extract, Hippophae Rhamnoides Fruit Extract, Citrus Aurantium Dulcis Fruit Extract, Glycyrrhiza Glabra Root Extract, Lactobacillus Ferment Lysate, 1,2-Hexanediol, Sodium Hyaluronate, Candida Ferment, Lactobacillus Ferment, Lactococcus Ferment Lysate, Bifida Ferment Lysate, Bifida Ferment Lysate, Saccharomyces Ferment Filtrate', 'La Pro Balance Creamy Cleansing Foam Dr.Ceuracle est une mousse nettoyante douce qui élimine le maquillage et les impuretés et laisse la peau douce et hydratée grâce à des ingrédients hydratants naturels, ce qui prévient la sensation d''irritation et de sécheresse après le nettoyage. Elle est formulée avec du Phyto G.Fer-kefir (une levure respectueuse de la peau) qui soulage l''inflammation ainsi qu''un "5 Probiotics Complex" qui se compose de cinq probiotiques et d''huiles végétales naturelles provenant de diverses plantes. Elle renforce également la barrière naturelle de la peau et contient de la vitamine E et de l''acide hyaluronique.', 150, 'ml', 'dr-ceuracle-pro-balance-creamy-cleansing-foam', 'https://korean-skincare.fr/products/dr-ceuracle-pro-balance-creamy-cleansing-foam', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-pro-balance-creamy-cleansing-foam.webp', 'Utilise le nettoyant matin et soir, après le démaquillage. Commence par humidifier tes mains et ton visage. Distribue une quantité suffisante de nettoyant sur tes mains mouillées pour le faire mousser. Masse délicatement ton visage en évitant le contour des yeux et de la bouche. Rince à l''eau tiède.', 1420, '2026-05-07 17:37:40.44264+00', '2026-06-14 15:14:07.803+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-445f-7267-998d-db13de3fb1b1', '__OWNER_ID__', 'Tea Tree Purifine 80 Cream', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Melaleuca Alternifolia Leaf Extract, Butylene Glycol, Glycerin, Glyceryl Stearate, 1,2-Hexanediol, Cyclopentasiloxane, Caprylic/Capric Triglyceride, Ethylhexyl Stearate, Éthylhexanoate de cétéryl, Betaine, Éthyl Hexanediol, Polyacrylate de sodium, PEG-100 Stearate, Glucoside de Cétéaryle, Cetearyl Alcohol, Palmitic Acid, Stearic Acid, Polyacrylate-13, Gomme Xanthane, Panténol, Ethylhexylglycerin, Polyisobutene, Potassium Hydroxide, Lavandula Angustifolia Oil, Aqua, Polysorbate 20, Melaleuca Alternifolia Leaf Oil, Sorbitan Isostearate, Myristic Acid, Extrait d''Hippophae Rhamnoides, Extrait de Fleurs/Feuilles de Thymus Vulgaris (Thym), Extrait de Buddleja Davidii, Centella Asiatica Extract, Hamamelis Virginiana Water', 'La Tea Tree Purifine 80 Cream Dr. Ceuracle est une crème légère et rafraîchissante contenant 80 % d''extraits d''arbre à thé. Elle procure une hydratation durable avec une sensation unique de "clapotis d''hydratation". Idéal pour les peaux à problèmes ou à tendance acnéique, l''extrait d''arbre à thé aide à éliminer et à prévenir les éruptions futures, tandis que le panthénol crée une barrière supplémentaire sur la peau pour lui donner un éclat radieux.', 50, 'g', 'dr-ceuracle-tea-tree-purifine-80-cream', 'https://korean-skincare.fr/products/dr-ceuracle-tea-tree-purifine-80-cream', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-tea-tree-purifine-80-cream.webp', 'Distribue une quantité modérée de la crème Applique-la sur l''ensemble de ton visage et masse délicatement pour une meilleure absorption.', 2444, '2026-05-07 17:37:40.447055+00', '2026-06-14 15:14:07.803+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4463-79e4-99aa-8aa7ea617763', '__OWNER_ID__', 'Cica Regen 95 Soothing Gel', 'Dr. Ceuracle', 'moisturizer', 'jar', 'Centella Asiatica Extract, 1,2-Hexanediol, Aqua, Butylene Glycol, Carbomer, Tromethamine, Adenosine, Disodium EDTA, Extrait de Fleur de Nelumbo Nucifera, Madecassoside, Asiaticoside, Extrait de Fruit d''Actinidia Arguta, Extrait de Fleur d''Hibiscus Sabdariffa, Acide Asiatique, Acide Madécassique, Ethylhexylglycerin', 'Le Cica Regen 95 Soothing Gel Dr. Ceuracle est un masque pour visage formulé avec 95% de Centella Asiatica qui soulage et dynamise les peaux abîmées et irritées. De plus, pour apporter à ta peau une teneur élevée en Centella Asiatica, ce produit ne contient ni pigment ni parfum. L''extrait de Centella Asiatica apaise et répare immédiatement les peaux abîmées et sensibles, les laissant confortables et en bonne santé. L''extrait d''Actinidia Argute (Kiwi) protège la peau des facteurs externes, tels que les poussières fines, et fournit des antioxydants pour l''éclat de la peau.', 110, 'g', 'dr-ceuracle-cica-regen-95-soothing-gel', 'https://korean-skincare.fr/products/dr-ceuracle-cica-regen-95-soothing-gel', 'https://aurore-cdn.b-cdn.net/products/dr-ceuracle-cica-regen-95-soothing-gel.webp', 'Prélève une quantité suffisante de produit. Applique sur l''ensemble de ton visage et masse délicatement pour une meilleure absorption.', 1757, '2026-05-07 17:37:40.451509+00', '2026-06-14 15:14:07.803+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44e1-757a-be7c-76c5c80f67c7', '__OWNER_ID__', 'Retinol Intense Daily Mask', 'SOME BY MI', 'mask', 'pack', 'Aqua, Dipropylene Glycol, Glycerin, Niacinamide, Hydroxyacetophenone, Olea Europaea Fruit Oil, Caprylyl Glycol, Laurate de Polyglycéryl-10, Ethylhexylglycerin, Adenosine, 1,2-Hexanediol, Arginine, Gomme xanthane, Carbomer, Distearate de Polyglycéryl-3 Méthylglucose, Sodium Hyaluronate, Glyceryl Stearate SE, Sesquistearate de Methyl Glucose, Sulfosuccinate de Sodium de Diéthylhexyle, Caprylic/Capric Triglyceride, Dipotassium Glycyrrhizate, Bakuchiol, Butylene Glycol, Octyldodecanol, Oléate de Polyglycéryl-4, Palmitate de Saccharose, Ananas Sativus Fruit Extract, Maltodextrin, Protéine végétale hydrolysée, Hydrogenated Lecithin, Solanum Melongena Fruit Extract, Glycine Soja Oil, Retinol, Retinal, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Copolymère de Hyaluronate de Sodium, Hydroxypropyltrimonium Hyaluronate, Potassium Hyaluronate, Hydrolyzed Sodium Hyaluronate, Pentylene Glycol, Sodium Acetylated Hyaluronate, Disodium EDTA, Parfum, Hydroxycitronellal', 'Embarque pour un voyage de soins vers une peau radieuse et hydratée avec le Retinol Intense Daily Mask SOME BY MI. Ce sérum polyvalent contient un puissant mélange de 20 % de niacinamide, de zinc PCA et d''arbutine, qui apporte des bienfaits éclaircissants et cible les rides et ridules. Infusé avec dix types d''acide hyaluronique, il procure une hydratation intense, laissant la peau rebondie et lumineuse. Sa formule légère pénètre rapidement, garantissant un fini lisse et rafraîchi. L''ajout d''un complexe de rétinol dans le masque tissu extensible resserre les pores et révèle un teint frais. Enrichie de 8 types d''acide hyaluronique et de Bakuchiol, cette formule hypoallergénique convient à tous les types de peau. Absorbée rapidement et non collante, elle crée une base de maquillage idéale. Dévoile un teint plus radieux et revitalisé grâce à ce soin puissant. Recommandé pour : Peaux normales, peaux mixtes, peaux sèches. Comprend : 30 masques tissus.', 30, 'pcs', 'some-by-mi-retinol-intense-daily-mask', 'https://korean-skincare.fr/products/some-by-mi-retinol-intense-daily-mask', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-retinol-intense-daily-mask.webp', 'Après avoir nettoyé ton visage et utilisé un tonique, applique le masque tissu en l''ajustant à ton visage, en évitant le contour des yeux et de la bouche. Retire le masque au bout de 10 à 20 minutes. Tapote délicatement ta peau pour améliorer l''absorption.', 3130, '2026-05-07 17:37:40.577161+00', '2026-06-14 15:14:07.804+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4473-712c-b585-82325896a0c7', '__OWNER_ID__', 'Collagen Peptide Vital Mask', 'Mary&May', 'mask', 'pack', 'Glycerin, Dipropylene Glycol, Collagène Hydrolysé, Hydroxyacetophenone, Laurate de Polyglyceryl-10, Arginine, Carbomer, Laurate de Polyglyceryl-4, Allantoin, Adenosine, Caprylyl/Capryl Glucoside, Hydroxyéthylcellulose, Caprylyl Glycol, 1,2-Hexanediol, Extrait de Collagène, Collagène Soluble, Disodium EDTA, Ethylhexylglycerin, Copper Tripeptide-1, Hexapeptide-11, Hexapeptide-9, Palmitoyl Pentapeptide-4, Palmitoyl Pentapeptide-1, Tripeptide-1', 'Le Mary & May Collagen Peptide Vital Mask est composé de 30 masques tissus dans une boîte grand format. Il te suffit de retirer un masque chaque jour de la boîte, une solution pratique, facile à utiliser et qui protège l''environnement en réduisant les déchets inutiles. Le Collagen Peptide Vital Mask est formulé avec six peptides, qui améliorent efficacement les rides et aident à régénérer la peau, tout en fournissant des effets anti-âge et du collagène à faible poids moléculaire pour l''amélioration des rides et de l''élasticité.', 30, 'pcs', 'mary-may-collagen-peptide-vital-mask', 'https://korean-skincare.fr/products/mary-may-collagen-peptide-vital-mask', 'https://aurore-cdn.b-cdn.net/products/mary-may-collagen-peptide-vital-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 2529, '2026-05-07 17:37:40.466991+00', '2026-06-14 15:14:07.804+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4470-7e8d-a56e-21d8d1b081c7', '__OWNER_ID__', 'Calendula Peptide Ageless Sleeping Mask', 'Mary&May', 'mask', 'pack', 'Aqua, Alcohol Denat, Methylpropanediol, 1,2-Hexanediol, Betaine, Dipropylene Glycol, Extrait de Fleur de Gardenia Florida, Arctium Lappa Root Extract, Extrait de Chapeau d''Agaricus Bisporus, Centella Asiatica Extract, Extrait de Ficus Carica, Extrait de Feuille/Tige d''Oryza Sativa, Extrait de Chamomilla Recutita, Extrait de Chrysanthemum Parthenium, Hydrogenated Lecithin, Sodium Hyaluronate, Calendula Officinalis, Panthenol, Crosspolymère d''Acryla tes/C10-30 Alkyl Acrylate, Glycerin, Tromethamine, Butylene Glycol, Oleate de Polyglycéryle-10, Laurate de Lauryle, Dextrin, Sodium Phytate, Ceramide NP, Tocopherol, Acétate de Hexapeptide-8, Acétate d''Octapeptide-3, Acétate de Tétra peptide-2, Oligopeptide-6, Tripeptide-1, Tripeptide-1 Cuivre, Hexapeptide-2, Dipeptide-2, Acétate de Tétra peptide-3, Acétate de Tripeptide-1, Hexapeptide-9, Tripeptide-2, Nonapeptide-1, Pentapeptide-3, Tripeptide-3, Polypeptide d''Alanine/Histidine/Lysine Cuivre HCl, Dipeptide-4, Acétate de Tétra peptide-5, Palmitoyl Dipeptide-7, Palmitoyl Hexapeptide-14, Palmitoyl Tripeptide-1, Palmitoyl Tripeptide-5, Palmitoyl Pentapeptide-4, Dipeptide Diaminobutyroyl Benzylamide Diacétate, Palmitoyl Tétra peptide-7, Guaiazulène, Parfum, Ethylhexylglycerin', 'Revitalise ta peau pendant la nuit avec le Calendula Peptide Ageless Sleeping Mask MARY & MAY. Ce masque gel vegan, testé cliniquement, est infusé de 2 200ppm d''extrait de calendula, de 25 types de peptides et d''extrait de cica pour apaiser l''inflammation, réparer les lésions et calmer les irritations pendant ton sommeil. Enrichi d''acide hyaluronique pour une hydratation en profondeur et de Guaiazulene de camomille pour réduire les rougeurs, il laisse ta peau rebondie, radieuse et nourrie dès le matin. Parfaite pour les peaux sensibles, sa formule légère et vérifiée par l''EWG adhère en douceur et délivre de puissants ingrédients actifs pour rajeunir ta peau pendant ton repos. Recommandé pour : Peaux sèches, tous types de peaux.', 110, 'g', 'mary-may-calendula-peptide-ageless-sleeping-mask', 'https://korean-skincare.fr/products/mary-may-calendula-peptide-ageless-sleeping-mask', 'https://aurore-cdn.b-cdn.net/products/mary-may-calendula-peptide-ageless-sleeping-mask.webp', 'Lors de la dernière étape de ta routine beauté du soir, prélève une quantité appropriée de produit et applique-le sur ton visage, en évitant le contour des yeux et de la bouche. Rince délicatement ton visage le lendemain matin avec de l''eau tiède.', 2248, '2026-05-07 17:37:40.464798+00', '2026-06-14 15:14:07.804+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4475-71f9-b67c-fbc1ff2452c6', '__OWNER_ID__', 'Idebenone Blackberry Intense Cream', 'Mary&May', 'moisturizer', 'jar', 'Rubus Fruticosus Fruit Extract, Euterpe Oleracea Fruit Extract, Vaccinium Angustifolium Fruit Extract, Glycerin, Butylene Glycol, Aqua, Caprylic/Capric Triglyceride, 1,2-Hexanediol, Niacinamide, Cetearyl Alcohol, Cetyl Ethylhexanoate, Isododecane, Ethylhexyl Palmitate, Olivate de Cétéaryle, Panthenol, Distéarate de Méthylglucose Polyglycéryl-3, Laurate de Polyglycéryl-10, Sorbitan Olivate, Polyacrylate de Sodium, Hydrogenated Lecithin, Ammonium Acryloyldimethyltaurate/VP Copolymer, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Arginine, Polydécène Hydrogénée, Ethylhexylglycerin, Idebenone, Adenosine, Pentylene Glycol, Tridéceth-6, Disodium EDTA, Copolymère d''Acrylate de Glycéryle/Acide Acrylique, Sodium Hyaluronate, Glycol Caprylylique, Sodium Hyaluronate Crosspolymer, Stearic Acid, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Hydrolyzed Sodium Hyaluronate, Ceramide NP, Ceramide NS, Phytosphingosine, Cholesterol, Ceramide AS, Ceramide AP, Ceramide EOP', 'La Idebenone + Blackberry Complex Intensive Total Care Cream MARY & MAY est une puissante crème hydratante enrichie de 63% de Blackberry Complex et de 500 ppm d''idebenone pour lutter contre les radicaux libres, adoucir les ridules et éclaircir la peau. Elle est également infusée de cinq types de céramides pour renforcer la peau et présente une texture riche et soyeuse qui nourrit abondamment la peau.', 70, 'g', 'mary-may-idebenone-blackberry-intense-cream', 'https://korean-skincare.fr/products/mary-may-idebenone-blackberry-intense-cream', 'https://aurore-cdn.b-cdn.net/products/mary-may-idebenone-blackberry-intense-cream.webp', 'Prélève une quantité suffisante de crème. Applique sur l''ensemble de ton visage et tapote délicatement pour faciliter l''absorption.', 1466, '2026-05-07 17:37:40.469016+00', '2026-06-14 15:14:07.804+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4491-7d09-8bbd-6dbdaeb28e14', '__OWNER_ID__', 'Niacinamide Vitamin C Brightening Mask', 'Mary&May', 'mask', 'pack', 'Aqua, Glycerin, Niacinamide, Dipropylene Glycol, Hydroxyacetophenone, Arginine, Carbomer, Sodium Ascorbyl Phosphate, Laurate de Polyglyceryl-10, Laurate de Polyglyceryl-4, Allantoin, Hydroxyéthylcellulose, Caprylyl/Capryl Glucoside, Butylene Glycol, Caprylyl Glycol, Disodium EDTA, Parfum, 1,2-Hexanediol, Sodium Hyaluronate', 'Le Niacinamide Vitamin C Brightening Mask MARY & MAY est composé de 30 masques tissus dans une boîte grand format. Il te suffit de retirer un masque chaque jour de la boîte, une solution pratique, facile à utiliser et qui protège l''environnement en réduisant les déchets inutiles. Le Niacinamide Vitamin C Brightening Mask MARY & MAY est idéal pour ceux qui veulent estomper les cicatrices d''acné et éclaircir leur peau avec l''aide de la niacinamide et de la vitamine C.', 30, 'pcs', 'mary-may-niacinamide-vitamin-c-brightening-mask', 'https://korean-skincare.fr/products/mary-may-niacinamide-vitamin-c-brightening-mask', 'https://aurore-cdn.b-cdn.net/products/mary-may-niacinamide-vitamin-c-brightening-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 2654, '2026-05-07 17:37:40.497715+00', '2026-06-14 15:14:07.804+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4477-7249-9f59-7d0e7c263580', '__OWNER_ID__', 'Premium Idebenone Blackberry Complex Essence Mask', 'Mary&May', 'mask', 'pack', 'Aqua, Glycerin, Dipropylene Glycol, Niacinamide, Trehalose, Rubus Fruticosus Fruit Extract, Vaccinium Angustifolium Fruit Extract, Euterpe Oleracea Fruit Extract, Caprylic/Capric Triglyceride, Glucoside de Caprylyl, Butylene Glycol, Hydrogenated Lecithin, Adenosine, Panthenol, Ubiquinone Hydroxydecyle, Centella Asiatica Extract, Phosphate Ascorbyle de Sodium, Ceramide NP, Sodium Hyaluronate, Palmitoyl Pentapeptide-4, Copper Tripeptide-1, Tripeptide-1, Hexapeptide-9, Palmitoyl Tripeptide-1, Hexapeptide-11, Hydroxyéthylcellulose, Trométamine, Carbomer, Laurate de Polyglycéryle-10, Laurate de Polyglycéryle-4, Hydroxyacetophenone, 1,2-Hexanediol, Octyldodecanol, Caprylyl Glycol, Ethylhexylglycerin, Disodium EDTA, Parfum', 'Revitalise ta peau avec le Premium Idebenone Blackberry Complex Essence Mask MARY & MAY, un luxueux masque tissu gorgé d''acide hyaluronique, d''idebenone riche en antioxydants, et du complexe de mûres breveté de la marque. Conçu pour nourrir et éclaircir les peaux fatiguées, ternes ou matures, ce masque délivre des nutriments en profondeur sous la couche dermique tout en aspirant les impuretés, grâce à ses feuilles de charbon de bambou. Idéal pour un usage quotidien, il hydrate, apaise et rajeunit la peau, lui assurant un éclat durable. Recommandé pour : Peaux sèches, tous types de peaux.', 20, 'pcs', 'mary-may-premium-idebenone-blackberry-complex-essence-mask', 'https://korean-skincare.fr/products/mary-may-premium-idebenone-blackberry-complex-essence-mask', 'https://aurore-cdn.b-cdn.net/products/mary-may-premium-idebenone-blackberry-complex-essence-mask.webp', 'Après le nettoyage, apaise ton visage avec un tonique. Déplie le masque tissu et place-le sur ton visage, en alignant les trous sur tes yeux, ton nez et ta bouche. Laisse-le sur la peau pendant 10 à 20 minutes. Décolle le masque et jette-le. Tapote délicatement l''essence sur ton visage pour une absorption maximale.', 2439, '2026-05-07 17:37:40.471059+00', '2026-06-14 15:14:07.805+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44b5-73b6-8eaa-55c80c92905b', '__OWNER_ID__', 'Retinol 0.1% Bakuchiol Cica Serum', 'Mary&May', 'serum', 'dropper', 'Aqua, Propanediol, Diméthicone Vinyl, Glycerin, Dipropylene Glycol, Hydrogenated Lecithin, Glycolipides, Hydroxyacetophenone, Bisabolol, Cetyl Ethylhexanoate, Huile de Noix de Macadamia, Sorbitan Stéarate, Sodium Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Polyisobutene, Niacinamide, Stérol de Colza, Polyglycéryl-10 Laurate, 1,2-Hexanediol, Cholesterol, Phytostéryl/Behenyl/Octyldodécyl Lauroyl Glutamate, Diméthicone/Vinyl Diméthicone Crosspolymère, Bakuchiol, Butyrospermum Parkii Butter, Retinol, Tocopherol, Disodium EDTA, Ceramide NP, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Dipotassium Glycyrrhizate, Cocoate de Saccharose, Sodium Hyaluronate, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Eau de Fleur de Rose Damascena, Glucoside Caprylyl/Capryl, Adenosine, Sorbitan Oléate, Cetearyl Alcohol, Stearic Acid, Extrait de Fruit de Vanille, Polyglutamic Acid, Tromethamine, Extrait de Feuille de Thé Vert, Benzotriazolyl Dodecyl p-Cresol, Glyceryl Stearate, Polyglycéryl-10 Myristate, Oleic Acid, Butylene Glycol, Huile de Santal, Caprylyl Glycol, Ethylhexylglycerin, Ceramide NS, Phytosphingosine, Carbomer, Arginine, Ceramide AS, Ceramide AP, Extrait de Feuille de Centella Asiatica, Extrait de Racine de Centella Asiatica, Centella Asiatica Extract, ADN de Sodium, Ceramide EOP, Acetyl Hexapeptide-8, Palmitoyl Pentapeptide-4, Copper Tripeptide-1, Acide Asiatique, Asiaticoside, Acide Madecassique, Madecassoside', 'Le Retinol 0.1% Bakuchiol Cica Serum Mary & May est un soin anti-âge doux mais puissant, spécialement conçu pour les peaux sensibles. Cette formule avancée combine 0,1 % de rétinol pur, 1 000 ppm de bakuchiol et des extraits apaisants de Centella Asiatica de Jeju (y compris Cica PDRN et Cica exosomes) pour offrir des améliorations visibles de la fermeté de la peau, des ridules et de l’apparence des pores. Alimenté par un complexe triple peptide comprenant l’acetyl hexapeptide-8, le palmitoyl pentapeptide-4 et le copper tripeptide-1, ce sérum renforce la barrière cutanée, améliore l’élasticité et lisse les signes visibles du vieillissement avec une réduction des rides de 42,9 % et une amélioration de la texture de 21,1 %. Les extraits apaisants de Centella Asiatica (y compris l’acide asiatique, l’asiaticoside, l''acide madecassique et le madecassoside) calment les irritations et soutiennent la régénération de la peau, tandis que la technologie nano-émulsion assure une diffusion profonde et stable du rétinol pour une efficacité maximale avec une irritation minimale. Recommandé pour : Tous types de peaux, teint terne, texture irrégulière, hyperpigmentation et préoccupations liées au vieillissement.', 80, 'ml', 'mary-may-retinol-0-1-bakuchiol-cica-serum', 'https://korean-skincare.fr/products/mary-may-retinol-0-1-bakuchiol-cica-serum', 'https://aurore-cdn.b-cdn.net/products/mary-may-retinol-0-1-bakuchiol-cica-serum.webp', 'Applique après le nettoyage et le tonique : après avoir nettoyé et tonifié ta peau, dépose quelques gouttes de produit sur ton visage et ton cou Masse doucement pour favoriser l’absorption : lisse le sérum délicatement sur ta peau en tapotant légèrement pour améliorer l’absorption Utilise un écran solaire quotidiennement : à appliquer le soir en raison de la photosensibilité du rétinol et utiliser un écran solaire chaque jour pour protéger ta peau, surtout pour les débutants avec le rétinol. Augmente progressivement la fréquence d’utilisation (par exemple 2 à 3 fois par semaine) pour éviter les irritations', 2095, '2026-05-07 17:37:40.533147+00', '2026-06-14 15:14:07.805+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-453a-7a5b-b980-294c00104526', '__OWNER_ID__', 'Snail Truecica Miracle Repair Low pH Gel Cleanser', 'SOME BY MI', 'cleanser', 'tube', 'Aqua, Lauryl Hydroxysultaine, Disodium Cocoamphodiacetate, Sodium Chloride, Cocoyl Glycinate de Potassium, Copolymère d''Acrylates, Taurate Méthyl Cocoyl de Sodium, Cocoate de Potassium, Butylene Glycol, Filtrat de Sécrétion de Mucus d''Escargot, Glycol de Benzyle, Citric Acid, Huile de Fruit de Citrus Aurantium Bergamia (Bergamote), Ethylhexylglycerin, Hexylene Glycol, Disodium EDTA, Salvia Officinalis Oil, Jus de Betula Platyphylla Japonica, Camellia Sinensis Leaf Extract, Glycyrrhiza Glabra Root Extract, Extrait d''Agrimonia Eupatoria, Panthenol, 1,2-Hexanediol, Centella Asiatica Extract, Extrait de Feuille de Perilla Frutescens, Melaleuca Alternifolia Leaf Extract, Phenoxyethanol, Glycine, Dipropylene Glycol, Extrait de Saponaria Officinalis, Sérine, Glutamic Acid, Extrait de Fruit de Kigelia Africana, Acide Aspartique, Caprylic/Capric Triglyceride, Leucine, Alanine, Lysine, Arginine, Asiaticoside, Tyrosine, Phénylalanine, Acide Asiaticique, Acide Madécassique, Thréonine, Proline, Valine, Isoleucine, Pentylene Glycol, Lecithin, Extrait de Racine de Platycodon Grandiflorum, Extrait de Poria Cocos, Extrait de Graine de Coix Lacryma-Jobi Ma-Yuen, Extrait de Racine de Paeonia Albiflora, Histidine, Madecassoside, Cystéine, Méthionine, Extrait de Polygonatum Odoratum, Extrait de Racine de Scutellaria Baicalensis, Extrait de Racine d''Astragalus Membranaceus, Extrait d''Angelica Gigas, Extrait de Fruit de Cornus Officinalis, Extrait d''Artemisia Vulgaris, Extrait de Racine de Rehmannia Glutinosa, Ceramide NP, Lysat de Ferment Bifida, Lysat de Ferment Lactobacillus, Lysat de Ferment Lactococcus', 'Le Snail Truecica Miracle Repair Low pH Gel Cleanser SOME BY MI est doux et délicat avec un pH de 5,5. Il est formulé avec de l''extrait d''escargot noir pour guérir la peau abîmée, et enrichi de 17 types d''acides aminés, de céramide et de panthénol pour renforcer la barrière d''hydratation de la peau et maintenir un teint plus rebondi et plus ferme. Ce nettoyant forme de riches bulles crémeuses qui nettoient la peau sans la laisser sèche ou irritée.', 100, 'ml', 'snail-truecica-miracle-repair-low-ph-gel-cleanser', 'https://korean-skincare.fr/products/snail-truecica-miracle-repair-low-ph-gel-cleanser', 'https://aurore-cdn.b-cdn.net/products/snail-truecica-miracle-repair-low-ph-gel-cleanser.webp', 'Utilise le nettoyant matin et soir, après le démaquillage. Commence par humidifier tes mains et ton visage. Distribue une quantité suffisante de nettoyant sur tes mains mouillées pour le faire mousser. Masse délicatement ton visage en évitant le contour des yeux et de la bouche. Rince à l''eau tiède.', 1464, '2026-05-07 17:37:40.666515+00', '2026-06-14 15:14:07.805+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-447d-70e6-b28d-e9a12ceb245e', '__OWNER_ID__', 'CICA Soothing Sun Cream SPF50+ PA++++', 'Mary&May', 'moisturizer', 'jar', 'Aqua, Adipate de Dibutyle, Propanediol, Benzoate d''Hexyl Diéthylamino Hydroxybenzoyl, Polyméthylsilsesquioxane, Ethylhexyl Triazone, Niacinamide, Methylene Bis-Benzotriazolyl Tetramethylbutylphenol, Coco-Caprylate/Caprate, Butylene Glycol, Caprylyl Méthicone, Triazone de Butamido Diéthylhexyle, Glycerin, 1,2-Hexanediol, Pentylene Glycol, Behenyl Alcohol, Poly Acrylate d''Alkyle C10-30, Distearate de Méthylglucose Polyglyceryl-3, Decyl Glucoside, Tromethamine, Parfum, Carbomer, Copolymère Acrylates/Alkyle C10-30, Glutamate de Stéaroyle de Sodium, Polyacrylate Crosspolymer-6, Ethylhexylglycerin, Adenosine, Gomme Xanthane, Extrait de Racine de Centella Asiatica, Extrait de Feuille de Centella Asiatica, Centella Asiatica Extract, Saccharomyces Ferment Filtrate, Alcool T-butyl, Tocopherol, Asiaticoside, Madecassoside, Betaine, Inositol, Acide Madécassique, Sodium Hyaluronate, Acide Asiatique', 'La CICA Soothing Sun Cream SPF50+ PA++++ MARY & MAY est une crème solaire multifonctionnelle respectueuse des océans, qui hydrate et apaise la peau, et offre des propriétés éclaircissante et anti-âge. Elle est dotée d''un FPS 50+ PA++++ pour la protection contre les UV et formulée avec 10 000 ppm de F-CICA COMPLEX (contenant sept dérivés de Centella Asiatica fermentés avec de la levure) pour des effets apaisants. La texture légère de cette crème solaire pénètre rapidement dans la peau sans laisser de traces blanches.', 50, 'ml', 'mary-may-cica-soothing-sun-cream-spf50-pa', 'https://korean-skincare.fr/products/mary-may-cica-soothing-sun-cream-spf50-pa', 'https://aurore-cdn.b-cdn.net/products/mary-may-cica-soothing-sun-cream-spf50-pa.webp', 'Applique sur les zones exposées du visage/corps 30 minutes avant de sortir au soleil. Renouvelle l''application toutes les deux heures pour une protection solaire parfaite pendant la journée.', 1562, '2026-05-07 17:37:40.476974+00', '2026-06-14 15:14:07.805+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44bf-7b93-9e2b-286d6334f5ab', '__OWNER_ID__', 'Rice Glutathione LHA Cleansing Oil', 'Mary&May', 'cleanser', 'tube', 'Ethylhexyl Palmitate, Sorbeth-30 Tetraoleate, Triethylhexanoin, Cetyl Ethylhexanoate, Isopropyl Palmitate, Malate de Diisostéaryle, Sorbitan Sesquioleate, Caprylic/Capric Triglyceride, Huile de Son de Riz (Oryza Sativa), Capryloyl Salicylic Acid, Aqua, Glycerin, Huile de Fruit de Yuzu (Citrus Junos), Huile de Glycine Max, Glycine Soja Oil, Huile de Graine de Panax Ginseng, Polyglyceryl-10 Laurate, 1,2-Hexanediol, Glutathione, Hydrogenated Lecithin, Kyounin Yu, Camellia Japonica Seed Oil, Prunus Persica Fruit Extract', 'La Rice Glutathione LHA Cleansing Oil Mary & May est un nettoyant léger et multifonctionnel spécialement conçu pour les peaux sensibles. Elle dissout le maquillage, la crème solaire et les impuretés tout en nettoyant en profondeur les pores sans dessécher ni irriter la peau. Enrichie avec 1 000 ppm d’huile de son de riz (Oryza Sativa), elle nourrit et illumine le teint, aidant à équilibrer les zones de teint irrégulier. L’acide capryloyl salicylique (LHA), un exfoliant doux de nouvelle génération, élimine les cellules mortes, les points noirs (amélioration de 39,72 %) et les points blancs (amélioration de 44,56 %), offrant le pouvoir clarifiant de l’acide salicylique avec une action beaucoup plus douce. Recommandé pour : Tous types de peaux, grasses, sèches et mixtes, avec des bienfaits pour les peaux à tendance acnéique et l’hyperpigmentation.', 200, 'ml', 'mary-may-rice-glutathione-lha-cleansing-oil', 'https://korean-skincare.fr/products/mary-may-rice-glutathione-lha-cleansing-oil', 'https://aurore-cdn.b-cdn.net/products/mary-may-rice-glutathione-lha-cleansing-oil.webp', 'Verse une quantité appropriée de produit sur mains sèches et masse doucement sur peau sèche. Ajoute une petite quantité d’eau pour émulsionner et continue de masser pour éliminer les impuretés. Rince abondamment à l’eau tiède.', 2195, '2026-05-07 17:37:40.54364+00', '2026-06-14 15:14:07.806+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-447f-7092-b87d-f27ec7f13399', '__OWNER_ID__', 'Sensitive Soothing Gel Cream', 'Mary&May', 'moisturizer', 'jar', 'Houttuynia Cordata Extract, Melaleuca Alternifolia Leaf Extract, Glycerin, Butylene Glycol, 1,2-Hexanediol, Caprylic/Capric Triglyceride, Ethylhexyl Palmitate, Aqua, Distéarate de Methylglucose Polyglyceryl-3, Isododecane, Panthenol, Arginine, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Ammonium Acryloyldimethyltaurate/VP Copolymer, Ethylhexylglycerin, Caprylyl Glycol, Pentylene Glycol, Disodium EDTA, Dipotassium Glycyrrhizate, Copolymère d''acrylate d''acrylique/glycérique, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid', 'La Sensitive Soothing Gel Blemish Cream MARY & MAY possède une texture gel fraîche, non collante et translucide, qui apporte une hydratation suffisante aux peaux grasses et sensibles. Elle contient 71,8 % d''extrait naturel d''Houttuynia Cordata, qui peut soigner efficacement les problèmes de pores et de peau. Combinée à l''extrait d''arbre à thé australien, elle peut apaiser et nettoyer les peaux sensibles sans les irriter. Contenant du panthénol et 6 types d''acide hyaluronique, elle possède d''excellentes propriétés hydratantes et une capacité de pénétration élevée, ce qui permet à la peau de rester parfaitement hydratée tout au long de la journée.', 70, 'g', 'mary-may-sensitive-soothing-gel-cream', 'https://korean-skincare.fr/products/mary-may-sensitive-soothing-gel-cream', 'https://aurore-cdn.b-cdn.net/products/mary-may-sensitive-soothing-gel-cream.webp', 'Distribue une quantité modérée de crème. Applique-la sur l''ensemble de ton visage et masse délicatement pour une meilleure absorption.', 1121, '2026-05-07 17:37:40.478951+00', '2026-06-14 15:14:07.806+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4483-7360-8f21-427724fcd83b', '__OWNER_ID__', 'CICA Houttuynia Tea Tree Calming Mask', 'Mary&May', 'mask', 'pack', 'Aqua, Glycerin, Dipropylene Glycol, Centella Asiatica Extract, Houttuynia Cordata Extract, Melaleuca Alternifolia Leaf Extract, Hydroxyacetophenone, Arginine, Carbomer, Polyglycéryl-10 Laurate, 1,2-Hexanediol, Polyglycéryl-4 Laurate, Allantoin, Dipotassium Glycyrrhizate, Hydroxyéthylcellulose, Caprylyl/Capryl Glucoside, Caprylyl Glycol, Butylene Glycol, Disodium EDTA, Parfum, Sodium Hyaluronate', 'Le CICA Houttuynia Tea Tree Calming Mask MARY & MAY est composé de 30 masques tissus dans une boîte grand format. Il te suffit de retirer un masque chaque jour de la boîte, une solution pratique, facile à utiliser et qui protège l''environnement en réduisant les déchets inutiles. Le CICA Houttuynia Tea Tree Calming Mask Mary & May est un excellent choix pour apaiser la peau et soulager les problèmes cutanés.', 30, 'pcs', 'mary-may-cica-houttuynia-tea-tree-calming-mask', 'https://korean-skincare.fr/products/mary-may-cica-houttuynia-tea-tree-calming-mask', 'https://aurore-cdn.b-cdn.net/products/mary-may-cica-houttuynia-tea-tree-calming-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 2155, '2026-05-07 17:37:40.483115+00', '2026-06-14 15:14:07.806+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4485-739b-8fd7-9b44eaf949a6', '__OWNER_ID__', 'Niacinamide + Chaenomeles Sinensis Serum', 'Mary&May', 'serum', 'dropper', 'Extrait de Fruit de Chaenomeles Sinensis, Glycérine-26, Niacinamide, 1,2-Hexanediol, Arginine, Carbomer, Ethylhexylglycerin, Caprylyl Glycol', 'Le MARY & MAY Niacinamide + Chaenomeles Sinensis Serum est un sérum pour le visage formulé avec du niacinamide et de l''extrait de Chaenomeles Sinensis pour éclaircir les peaux ternes et déséquilibrées. Il contient 2 % de niacinamide pour éclaircir la peau en inhibant le transfert des mélanosomes, et réguler la production de sébum pour une peau plus équilibrée. Ce sérum est également enrichi de 93 % d''extrait de Chaenomeles Sinensis riche en vitamine C et en flavonoïdes pour obtenir une peau plus lisse et plus éclatante.', 30, 'ml', 'mary-may-niacinamide-chaenomeles-sinensis-serum', 'https://korean-skincare.fr/products/mary-may-niacinamide-chaenomeles-sinensis-serum', 'https://aurore-cdn.b-cdn.net/products/mary-may-niacinamide-chaenomeles-sinensis-serum.webp', 'Prélève une quantité adéquate à l''aide du compte-gouttes. Masse délicatement ta peau en suivant sa texture. Renouvelle l''application sur le contour de tes yeux secs.', 1464, '2026-05-07 17:37:40.485117+00', '2026-06-14 15:14:07.806+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4487-742e-980c-2b7409f6f41c', '__OWNER_ID__', 'Hyaluronic Panthenol Hydra Mask', 'Mary&May', 'mask', 'pack', 'Aqua, Glycerin, Dipropylene Glycol, Hydroxyacetophenone, Laurate de Polyglyceryl-10, Urée Hydroxyéthylée, Laurate de Polyglyceryl-4, Panthenol, Arginine, Carbomer, Glucoside de Caprylyl/Capryl, Parfum, Allantoin, Butylene Glycol, 1,2-Hexanediol, Caprylyl Glycol, Disodium EDTA, Hydroxyéthylcellulose, Sodium Hyaluronate, Pentylene Glycol, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Ethylhexylglycerin, Sodium Hyaluronate, Hydrolyzed Sodium Hyaluronate', 'Le Hyaluronic Panthenol Hydra Mask MARY & MAY est composé de 30 masques tissus dans une boîte grand format. Il te suffit de retirer un masque chaque jour de la boîte, une solution pratique, facile à utiliser et qui protège l''environnement en réduisant les déchets inutiles. Le Hyaluronic Panthenol Hydra Mask est un excellent masque pour hydrater la peau. Il est formulé avec de l''acide hyaluronique qui hydrate efficacement la peau, l''aidant ainsi à rester douce et hydratée, tandis que le panthénol, qui se transforme en vitamine B5 lorsqu''il est absorbé par la peau, aide à retenir son hydratation et à l''apaiser, pour lisser et assouplir les peaux sèches et rugueuses.', 30, 'pcs', 'mary-may-hyaluronic-panthenol-hydra-mask', 'https://korean-skincare.fr/products/mary-may-hyaluronic-panthenol-hydra-mask', 'https://aurore-cdn.b-cdn.net/products/mary-may-hyaluronic-panthenol-hydra-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 2364, '2026-05-07 17:37:40.487174+00', '2026-06-14 15:14:07.806+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4489-7648-b35f-de5474fb209a', '__OWNER_ID__', 'Glutathione Eye Cream Special Set', 'Mary&May', 'eye-cream', 'jar', 'Aqua, Glycereth-26, Ethylhexyl Palmitate, Glycerin, Cetearyl Alcohol, Niacinamide, Caprylic/Capric Triglyceride, Polyoléfine Hydrogénée (C6-14), Cera Alba, Dipropylene Glycol, Polyacrylate de Sodium, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Polyglycéryl-2 Stéarate, Stéarate de Glycol SE, Polydecène Hydrogéné, Hydroxyacetophenone, Isododecane, Glyceryl Stearate, Stearic Acid, Stearyl Alcohol, Hydrogenated Lecithin, Betaine, Glutathione, Panthenol, Tranexamic Acid, Dimethiconol, Copolymère Diméthicone/Vinyl Diméthicone, Huile de Fruit d’Hippophae Rhamnoides, Butylene Glycol, Caprylyl Glycol, Trideceth-6, Adenosine, Sorbitan Isostearate, 1,2-Hexanediol, Disodium EDTA, Sodium Hyaluronate, Acide Ascorbique *Ce produit ne contient ni hydroquinone ni mercure', 'Le Glutathione Eye Cream Special Set Mary&May est un duo de soins contour des yeux éclaircissant et raffermissant, conçu pour cibler les cernes, le teint terne et les premiers signes de l’âge autour des yeux. Formulée avec du glutathion, un puissant antioxydant reconnu pour ses propriétés illuminatrices, cette crème pour les yeux aide à améliorer l’apparence du teint irrégulier tout en soutenant un contour de l’œil plus lisse et visiblement rafraîchi. Sa texture nourrissante mais légère hydrate et adoucit sans effet lourd, aidant à réduire l’apparence des ridules et des signes de fatigue. Adapté à un usage quotidien, ce coffret est idéal pour illuminer le regard fatigué et préserver un contour des yeux plus ferme et d’apparence saine. Ce coffret comprend : Tranexamic Acid + Glutathione Eye Cream (30g + 12g + 12g) Recommandé pour : Peaux sèches, tous types de peaux.', 3, 'pcs', 'mary-may-glutathione-eye-cream-special-set', 'https://korean-skincare.fr/products/mary-may-glutathione-eye-cream-special-set', 'https://aurore-cdn.b-cdn.net/products/mary-may-glutathione-eye-cream-special-set.webp', 'Dépose une petite quantité de produit sur ton annulaire et applique autour du contour de tes yeux. Tapote délicatement jusqu’à absorption complète. Utilise matin et soir.', 1595, '2026-05-07 17:37:40.489285+00', '2026-06-14 15:14:07.807+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-448b-79a3-8242-33a40250e3ef', '__OWNER_ID__', 'Centella Asiatica Serum', 'Mary&May', 'serum', 'dropper', 'Aqua, Glycereth-26, 1,2-Hexanediol, Arginine, Carbomer, Ethylhexylglycerin, Centella Asiatica Extract, Caprylyl Glycol', 'Le Centella Asiatica Serum Mary&May est formulé avec 95 % d''extrait de Centella Asiatica, et apaise les peaux irritées tout en stimulant la régénération de la peau et en améliorant son élasticité. Sa formule à absorption rapide, non collante et cruelty-free est exempte de parabènes, de parfums et de colorants artificiels, d''alcool, d''huile minérale et de tensioactifs.', 30, 'ml', 'mary-may-centella-asiatica-serum', 'https://korean-skincare.fr/products/mary-may-centella-asiatica-serum', 'https://aurore-cdn.b-cdn.net/products/mary-may-centella-asiatica-serum.webp', 'Prélève une quantité adéquate de produit à l''aide du compte-gouttes. Masse délicatement ta peau en suivant son grain. Renouvelle l''application sur le contour des yeux secs.', 1464, '2026-05-07 17:37:40.491504+00', '2026-06-14 15:14:07.807+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-6554-73ea-81b4-67e3d50ea3ef', '__OWNER_ID__', 'Klorane Bleuet Sérum Réveil Tonique 50ml', 'Klorane', 'serum', 'bottle', 'Sodium Hyaluronate, Glycerin, Propanediol, Butylene Glycol, betaine*centaurea cyanus flower water* (eau florale de bleuet), Alcohol, Aqua, Citric Acid, Sodium Citrate, leontopodium alpinum flower/leaf extract* (extrait d''edelweiss), Tapioca Starch, 1,2-Hexanediol, Potassium Sorbate, Sodium Benzoate, Tocopherol, sodium dextran sulfate, Caprylyl Glycol, Ethylhexylglycerin, sclerotium gum, fragrance (parfum),97% d''origine naturelle*ingrédients d’origine naturelle', '', 50, 'ml', 'klorane-bleuet-serum-reveil-tonique-50ml-275504', 'https://www.atida.fr/klorane-bleuet-serum-reveil-tonique-50ml.html', 'https://aurore-cdn.b-cdn.net/products/klorane-bleuet-serum-reveil-tonique-50ml-275504.webp', '', 2484, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.807+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-448d-7a69-b047-ee95c8a56d5b', '__OWNER_ID__', 'Collagen Booster Lotion', 'Mary&May', 'moisturizer', 'jar', 'Aqua, Glycerin, Glycereth-26, Caprylic/Capric Triglyceride, Niacinamide, Cetearyl Alcohol, Adenosine, Collagène Hydrolysé (453 ppm), Collagène Soluble (453 ppm), Extrait de Collagène (453 ppm), Acetyl Hexapeptide-8, Glyceryl Stearate SE, Dipropylene Glycol, Ethylhexanoate de Cétéaryle, Stéarate de Sorbitane, Palmitic Acid, Hydroxyacétylphénone, Stearic Acid, Carbomer, Arginine, Allantoin, Esters d''Huile de Jojoba/Graines de Macadamia, Butylene Glycol, Caprylyl Glycol, Copolymère d''Acrylate de Glycéryle/Acide Acrylique, Disodium EDTA, Squalene, 1,2-Hexanediol, Macadamiate de Phytostérol, Phytostérols, Ethylhexylglycerin, Tocopherol, Parfum', 'La Collagen Booster Lotion MARY & MAY est une lotion anti-âge qui contient 1,3 % de collagène et des peptides pour raffermir la peau et améliorer son élasticité en seulement deux semaines. Son flacon-pompe en verre ambré la rend hygiénique et pratique, tout en minimisant la dégradation du produit par l''air et la lumière du soleil. Cette lotion cible le vieillissement de la peau grâce au lipide botanique, à l''acétyl hexapeptide-8 et au collagène à petites molécules qui stimulent la régénération du collagène tout en renforçant la structure de l''élastine pour une peau d''apparence jeune et ferme. Sa formule légère et à absorption rapide ne laisse pas de fini gras sur la peau, mais lui confère une sensation d''hydratation et de fraîcheur.', 120, 'ml', 'mary-may-collagen-booster-lotion', 'https://korean-skincare.fr/products/mary-may-collagen-booster-lotion', 'https://aurore-cdn.b-cdn.net/products/mary-may-collagen-booster-lotion.webp', 'Applique délicatement une petite quantité de produit. Masse délicatement pour une meilleure absorption.', 1935, '2026-05-07 17:37:40.493538+00', '2026-06-14 15:14:07.807+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019de0ab-655b-704d-9486-4bc1fbb5ef46', '__OWNER_ID__', 'Redken Pâte de Définition de longue durée', 'Redken', 'styling', 'bottle', 'Aqua, PEG-40 HYDROGENATED CASTOR OIL, Dimethicone, Petrolatum, Stearyl Alcohol, C20-40 ALKYL STEARATE, PPG-5-CETETH-20, TRIBEHENIN, VP/VA COPOLYMER, Butylene Glycol, Phenoxyethanol, PEG-150 PENTAERYTHRITYL TETRASTEARATE, Parfum, Cellulose Gum, Sorbic Acid, Ethylhexylglycerin, Disodium EDTA, Hexyl Cinnamal, Benzyl Salicylate, HYDROXYPROPYLTRIMONIUM HYDROLYZED WHEAT PROTEIN, Benzyl Alcohol, Linalool, PEG-90M, CI 19140, CI 14700 / RED 4, Tocopherol, CI 42090', '', 75, 'ml', 'redken-pate-de-definition-de-longue-duree-282834', 'https://www.atida.fr/redken-pate-de-definition-de-longue-duree.html', 'https://aurore-cdn.b-cdn.net/products/redken-pate-de-definition-de-longue-duree-282834.webp', '', 1799, '2026-04-30 23:13:40.719796+00', '2026-06-14 15:14:07.807+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-448f-7bc7-a7fc-3a2b264d49fb', '__OWNER_ID__', 'Vitamin B, C, E Cleansing Balm', 'Mary&May', 'cleanser', 'tube', 'Ethylhexyl Palmitate, Caprylic/Capric Triglyceride, Sorbeth-30 tétraoléate, Polyethylene, Cire d''abeille synthétique, Butyrospermum Parkii Butter, Ascorbic Acid, Panthenol, Tocopherol, Olea Europaea Fruit Oil, Glycerin, Butylene Glycol, Benzylglycol, Extrait de fruit de Citrus Paradisi, Extrait de fruit de Malpighia Glabra, Punica Granatum Fruit Extract, Extrait de fruit de Malus Domestica, Citrus Limon Fruit Extract, Vitis Vinifera Fruit Extract, Jus de Citrus Aurantium Dulcis, Extrait de feuille de Citrus Aurantium Dulcis, Eau de fruit de Citrus Aurantium Dulcis, Extrait de fleur de Citrus Aurantium Dulcis, Extrait de zeste de Citrus Aurantium Dulcis, Cétone de framboise, Aqua, Ethylhexylglycerin, 1,2-Hexanediol, Parfum', 'Laisse-toi tenter par le luxueux Vitamin B, C, E Cleansing Balm MARY & MAY, un baume transformateur à la texture de sorbet qui se transforme en une huile soyeuse au contact de ta peau. Ce baume nettoyant est un concentré de beauté, enrichi d''un trio de vitamines essentielles - B, C et E - pour éliminer délicatement le maquillage, le sébum et les impuretés sans décaper ta peau. Profite de l''efficacité délicate de ce baume qui hydrate, apaise et dévoile un teint radieux. Recommandé pour : Peaux normales à sèches.', 120, 'g', 'mary-may-vitamin-b-c-e-cleansing-balm', 'https://korean-skincare.fr/products/mary-may-vitamin-b-c-e-cleansing-balm', 'https://aurore-cdn.b-cdn.net/products/mary-may-vitamin-b-c-e-cleansing-balm.webp', 'Prélève une quantité appropriée de produit à l''aide de la spatule fournie. Applique sur peau sèche, et masse délicatement pour dissoudre le maquillage. Après avoir émulsionné avec un peu d''eau, rince soigneusement à l''eau tiède.', 2195, '2026-05-07 17:37:40.495643+00', '2026-06-14 15:14:07.807+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4494-721d-807b-ea7c73e6bfe8', '__OWNER_ID__', 'Houttuynia Cordata + Tea Tree Cleansing Foam', 'Mary&May', 'cleanser', 'tube', 'Houttuynia Cordata Extract, Myristic Acid, Palmitic Acid, Glycerin, Melaleuca Alternifolia Leaf Extract, Stearic Acid, Potassium Hydroxide, Lauric Acid, Aqua, Cera Alba, Dipropylene Glycol, Lauryl Hydroxysultaine, Glyceryl Stearate SE, 1,2-Hexanediol, Hydroxyacetophenone, Butylene Glycol, Caprylyl Glycol, Disodium EDTA, Sodium Hyaluronate, Parfum', 'La Houttuynia Cordata + Tea Tree Cleansing Foam MARY & MAY permet un nettoyage en profondeur avec une mousse crémeuse fraîche. Elle offre un soin apaisant des pores grâce à la présence de Houttuynia Cordata et d''arbre à thé. Formulée avec 40,7 % d''Houttuynia Cordata coréen et 6,8 % d''extrait d''arbre à thé australien pour prendre soin des troubles cutanés, cette mousse riche et crémeuse nettoie les pores et les cellules mortes de la peau.', 150, 'ml', 'mary-may-houttuynia-cordata-tea-tree-cleansing-foam', 'https://korean-skincare.fr/products/mary-may-houttuynia-cordata-tea-tree-cleansing-foam', 'https://aurore-cdn.b-cdn.net/products/mary-may-houttuynia-cordata-tea-tree-cleansing-foam.webp', 'Utilise le nettoyant matin et soir, après le démaquillage. Commence par humidifier tes mains et ton visage. Distribue une quantité suffisante de nettoyant sur tes mains mouillées pour le faire mousser. Masse délicatement ton visage en évitant le contour des yeux et de la bouche. Rince à l''eau tiède.', 1395, '2026-05-07 17:37:40.49996+00', '2026-06-14 15:14:07.808+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-467c-73b3-985e-3538e1f015ed', '__OWNER_ID__', 'Face Cream', 'ATOPALM', 'moisturizer', 'jar', 'Aqua, Glycerin, Citrate de Triéthyle, Propanediol, Oxostéaramide/Arachamide MEA de Myristoyle/Palmitoyle, Éthylhexanoate de Cétéaryle, Stéarate de Sorbitan, Glyceryl Stearate, Cetearyl Alcohol, 1,2-Hexanediol, Pentylene Glycol, Silica, Distearate de Polyglycéryl-10, Panthenol, Huile Végétale Hydrogénée, Olea Europaea Fruit Oil, Tocopherol, Carbomer, Caprylyl Glycol, Phytostérols, Allantoin, Bisabolol, Arginine, Stearic Acid, Gomme Xanthane, Sodium Phytate, Helianthus Annuus Seed Oil, Salvia Officinalis Oil, Sodium Hyaluronate, Elettaria Cardamomum Seed Oil, Beta-Glucan, N-Décanoyl Sériol, Bis-Capryloyloxypalmitamido Isopropanol, MEA de Palmitoyle Palmitamide, Huile de Juniperus Mexicana, Pogostemon Cablin Oil, Hydroxypropyltrimonium Hyaluronate, Hydrolyzed Hyaluronic Acid, Anthemis Nobilis Flower Oil, Huile de Fruit de Juniperus Communis, Leucine, Valine, Thréonine, Phénylalanine, Lysine, Sodium Acetyl Hyaluronate', 'La Face Cream ATOPALM offre une hydratation et une protection intensives, reconstituant les niveaux d''hydratation de la peau grâce à cinq acides aminés essentiels, tout en renforçant la barrière cutanée contre les irritants externes. Formulée avec la technologie brevetée MLE d''ATOPALM, cette crème renforce les capacités de rétention d''eau de la peau, ce qui la rend idéale pour les peaux sèches et sensibles. Sa formule faiblement acide, à faible pH, aide à maintenir un équilibre cutané sain sans irritation, garantissant un teint lisse et soyeux. Infusée de vitamines E et B5, elle nourrit, apaise et protège la peau des agressions environnementales, tandis que les huiles de pépins de raisin, de carthame, de thé vert, de tournesol et de jojoba procurent une hydratation profonde et des nutriments essentiels. Recommandé pour : Peaux sensibles, normales, mixtes et sèches.', 35, 'ml', 'atopalm-face-cream', 'https://korean-skincare.fr/products/atopalm-face-cream', 'https://aurore-cdn.b-cdn.net/products/atopalm-face-cream.webp', 'Applique une quantité appropriée de produit uniformément sur l''ensemble de ton visage. Tapote délicatement pour une meilleure absorption.', 1195, '2026-05-07 17:37:40.988094+00', '2026-06-14 15:14:07.808+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4498-7b51-9690-22802e0ec5ae', '__OWNER_ID__', 'Houttuynia Cordata + Tea Tree Serum', 'Mary&May', 'serum', 'dropper', 'Houttuynia Cordata Extract, Melaleuca Alternifolia Leaf Extract, Glycereth-26, 1,2-Hexanediol, Arginine, Carbomer, Ethylhexylglycerin, Caprylyl Glycol', 'Le Houttuynia Cordata + Tea Tree Serum MARY & MAY est un sérum infusé avec 85% d''extrait d''Houttuynia Cordata et 9,7% d''extrait d''arbre à thé pour affiner les pores et apaiser les peaux à problèmes grâce à ses propriétés antibactériennes et anti-inflammatoires. Minimal mais efficace, ce sérum maximise ses bienfaits apaisants avec 85 % d''extrait d''Houttuynia Cordata et 9,7 % d''extrait d''arbre à thé et, grâce à sa formule à absorption rapide, il laisse un fini rafraîchissant. Il est exempt de tests sur les animaux, de parabènes, de parfums et de colorants artificiels, d''alcool, d''huile minérale, de surfactants et d''allergènes.', 30, 'ml', 'mary-may-houttuynia-cordata-tea-tree-serum', 'https://korean-skincare.fr/products/mary-may-houttuynia-cordata-tea-tree-serum', 'https://aurore-cdn.b-cdn.net/products/mary-may-houttuynia-cordata-tea-tree-serum.webp', 'Prélève une quantité adéquate de produit à l''aide du compte-gouttes. Masse délicatement ta peau en suivant son grain. Renouvelle l''application sur le contour des yeux secs."', 1545, '2026-05-07 17:37:40.504587+00', '2026-06-14 15:14:07.808+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-449a-7f68-9a84-ebc77b51cabb', '__OWNER_ID__', 'Idebenone + Blackberry Complex Serum', 'Mary&May', 'serum', 'dropper', 'Purified Water, Rubus Fruticosus Fruit Extract, Euterpe Oleracea Fruit Extract, Vaccinium Angustifolium Fruit Extract, Glycerin, Caprylic/Capric Triglyceride, Glycereth-26, 1,2-Hexanediol, Butylene Glycol, Polyglyceryl-10 Laurate, Idebenone, Hydrogenated Lecithin, Arginine, Carbomer, Ethylhexylglycerin, Caprylyl Glycol', 'L''Idebenone + Blackberry Complex Serum Mary&May est un traitement antioxydant puissant conçu pour protéger la peau, améliorer son élasticité et restaurer un éclat jeunesse. Formulé avec de l’idebenone très puissant et un complexe riche en mûre, ce sérum aide à défendre la peau contre les agressions environnementales tout en soutenant la régénération et la fermeté cutanées. Sa texture légère et rapidement absorbée apporte une nutrition profonde sans lourdeur, laissant la peau lisse et radieuse. Reconnu pour sa forte capacité antioxydante, l''Idebenone + Blackberry Complex Serum Mary&May aide à réduire l’apparence des fines lignes, améliorer le teint et renforcer la vitalité globale. Avec une utilisation continue, il favorise un teint plus ferme, lumineux et résilient. Recommandé pour : Peaux ternes, perte d’élasticité, premiers signes de l’âge, protection antioxydante.', 30, 'ml', 'mary-may-idebenone-blackberry-complex-serum', 'https://korean-skincare.fr/products/mary-may-idebenone-blackberry-complex-serum', 'https://aurore-cdn.b-cdn.net/products/mary-may-idebenone-blackberry-complex-serum.webp', 'Prélève une quantité adéquate de produit à l''aide du compte-gouttes. Masse délicatement ta peau en suivant son grain. Renouvelle l''application sur le contour des yeux secs.', 1761, '2026-05-07 17:37:40.506844+00', '2026-06-14 15:14:07.809+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-449f-7778-b205-60ade7c6c9f8', '__OWNER_ID__', 'Lemon Niacinamide Glow', 'Mary&May', 'moisturizer', 'jar', 'Aqua, Kaolin, Bentonite, Illite, Glycerin, 1,2-Hexanediol, Betaine, Néopentyl Glycol Diheptanoate, Niacinamide, Dipropylene Glycol, Propanediol, Poudre de Zeste de Citrus Limon, Polyacrylate-13, Gomme Xanthane, Montmorillonite, 3-O-Ethyl Ascorbic Acid, Ethylhexylglycerin, Silicate de Magnésium et d''Aluminium, Hydrogenated Polyisobutene, Parfum, Laurate de Polyglycéryl-10, Ethylhexyl Palmitate, Sorbitan Isostéarate de Disodium Exita, Butylene Glycol, Quartz, Tocopherol, Prunus Persica Fruit Extract, Citric Acid, Gluconolactone', 'Le Lemon Niacinamide Glow MARY & MAY est un masque crémeux et délicat à rincer qui s''élimine facilement à l''eau sans nettoyant, laissant la peau hydratée et douce. Doté d''un excellent équilibre, ce masque te permet d''obtenir des résultats professionnels à la maison, en mélangeant des matières premières naturelles broyées à de l''argile riche en minéraux dans des proportions optimales. Un mélange bien équilibré de kaolin et de bentonite, qui absorbe l''huile et les impuretés, et qui possède d''excellentes propriétés apaisantes et anti-pores.', 125, 'g', 'mary-may-lemon-niacinamide-glow', 'https://korean-skincare.fr/products/mary-may-lemon-niacinamide-glow', 'https://aurore-cdn.b-cdn.net/products/mary-may-lemon-niacinamide-glow.webp', 'Après t''être lavé le visage, étale délicatement et uniformément, en évitant le contour des yeux et de la bouche. Masse délicatement. Après 10 à 15 minutes, lorsque le masque a séché, rince-le délicatement à l''eau tiède.', 2295, '2026-05-07 17:37:40.511357+00', '2026-06-14 15:14:07.809+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44a4-79d3-bacf-59c218a5aa98', '__OWNER_ID__', 'Vegan Blackberry Complex Cream Essence', 'Mary&May', 'essence', 'dropper', 'Aqua, Eau de Fleur de Nymphaea Caerulea, Simmondsia Chinensis Seed Oil, Polyoléfine Hydrogénée C6-14, 1,2-Hexanediol, Methylpropanediol, Rubus Fruticosus Fruit Extract, Centella Asiatica Extract, Ficus Carica Fruit Extract, Extrait Hydrolysé de Gardenia Florida, Sodium Hyaluronate, Hydrogenated Lecithin, Butylene Glycol, Glycerin, Trilaureth-4 Phosphate, Polyacrylate de Sodium, Copolymère Pvm/Ma, Cyanocobalamin, Ceramide NP, Maltodextrin, Ethylhexylglycerin, Tocopherol', 'La Vegan Blackberry Complex Cream Essence MARY & MAY est une crème rafraîchissante et nutritive sous forme d''essence qui nourrit et hydrate en profondeur les peaux sèches. Cette formule unique fond sur la peau et lui procure une hydratation intensive. Le complexe de mûre, un mélange d''extrait de mûre et d''autres ingrédients nourrissants, apporte des bienfaits apaisants et nourrissants à la peau. Il aide à renforcer la barrière cutanée rugueuse, laissant la peau lisse et hydratée sans aucune sensation de tiraillement. Cette crème est parfaite pour un usage quotidien et convient à tous les types de peau. Elle est également exempte de parabènes et de parfums artificiels, ce qui en fait un choix sûr et sain pour ta peau.', 140, 'ml', 'mary-may-vegan-blackberry-complex-cream-essence', 'https://korean-skincare.fr/products/mary-may-vegan-blackberry-complex-cream-essence', 'https://aurore-cdn.b-cdn.net/products/mary-may-vegan-blackberry-complex-cream-essence.webp', 'Agite le flacon pour mélanger la couche de crème et la couche d''essence. Après t''être lavé le visage, applique uniformément une quantité appropriée de produit. Tapote légèrement pour faire pénétrer le produit.', 2532, '2026-05-07 17:37:40.516449+00', '2026-06-14 15:14:07.809+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44a7-71f5-880d-fc0853207b5a', '__OWNER_ID__', 'Vegan Low pH Hyaluronic Gel Cleanser', 'Mary&May', 'cleanser', 'tube', 'Aqua, Glycerin, Coco-Glucoside, Decyl Glucoside, Glycinate de Cocoyl de Sodium, Octyldodeceth-16, Alaninate de Cocoyl de Sodium, 1,2-Hexanediol, Gomme Xanthan, Vitis Vinifera Fruit Extract, Centella Asiatica Extract, Ficus Carica Fruit Extract, Gardenia Florida Fruit Extract, Hydrogenated Lecithin, Sodium Hyaluronate, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Citric Acid, Beta-Glucan, Sodium Citrate, Sodium Phytate, Dextrin, Butylene Glycol, Ceramide NP, Hyaluronate de Diméthylsilanol, Hydrolyzed Sodium Hyaluronate, Hydrolyzed Sodium Hyaluronate, Potassium Hyaluronate, Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hydroxypropyltrimonium Hyaluronate, Diméthylsilanol Hyaluronate de Sodium, Sodium Acetyl Hyaluronate, Parfum, Hydroxyacetophenone, Ethylhexylglycerin', 'Le Vegan Low pH Hyaluronic Gel Cleanser MARY & MAY offre une expérience de nettoyage à la fois douce et efficace, parfaite pour une utilisation de jour comme de nuit. Ce gel nettoyant à faible pH, enrichi de 10 000 ppm d''extrait de raisin et d''acide hyaluronique, élimine efficacement les impuretés tout en maintenant l''équilibre naturel d''hydratation de ta peau. Sa formule au pH équilibré aide à protéger et à renforcer la barrière cutanée, ce qui en fait un produit idéal pour tous les types de peaux, y compris les peaux sensibles. Avec sa certification vegan et ses ingrédients classés verts par l''EWG, ce nettoyant doux hydrate et apaise tout en assurant un nettoyage en profondeur sans causer de sécheresse ou d''irritation. Fais l''expérience de cette formule rafraîchissante et non décapante qui laisse à ta peau une sensation de propreté, d''équilibre et de revitalisation. Recommandé pour : Sans risque pour l''acné fongique, peaux sèches, tous types de peaux.', 150, 'ml', 'mary-may-vegan-low-ph-hyaluronic-gel-cleanser', 'https://korean-skincare.fr/products/mary-may-vegan-low-ph-hyaluronic-gel-cleanser', 'https://aurore-cdn.b-cdn.net/products/mary-may-vegan-low-ph-hyaluronic-gel-cleanser.webp', 'Fais mousser une quantité appropriée de produit dans tes mains et masse délicatement sur ton visage humide. Rince à l''eau tiède.', 2195, '2026-05-07 17:37:40.518972+00', '2026-06-14 15:14:07.809+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44a9-7847-aa42-9782c3303b2d', '__OWNER_ID__', 'Vegan Peptide Bakuchiol Sun Stick SPF50+ PA++++', 'Mary&May', 'moisturizer', 'jar', 'Cetylethylhexanoate, Polymère croisé de méthacrylate de méthyle, Butylène Glycol Dicaprylate/Dicaprate, Synthetic Wax, Polymère croisé de diméthicone/silsesquioxane de méthicone de vinyle, Isopropyl Palmitate, Dicaprylyl Carbonate, Salicylate de butyloctyle, Diéthylaminohydroxybenzoylhexylbenzoate, Éthylhexyltriazone, Ozokérite, Polysilicone-15, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Bakuchiol, Diméthicone de vinyle, Titanium Dioxide, Glyceryl Caprylate, Caprylyl Glycol, Polyglyceryl-4 Diisostearate/Polyhydroxystearate/Sebacate, Coco-Caprylate/Caprate, Ethylhexylglycerin, Polyhydroxystearic Acid, Triéthoxycaprylylsilane, Hydroxyde d''aluminium, Tocopherol, Butylene Glycol, Aqua, 1,2-Hexanediol, Laurate de polyglyceryl-10, Acetyl Hexapeptide-8, Acétyl octapeptide-3, Nonapeptide-1, Dipeptide-2, Dipeptide-4, Acétyl tétrapeptide-2, Acétyl tétrapeptide-3, Acetyl Tetrapeptide-5, Acétyl tripeptide-1, Polypeptide d''alanine/histidine/lysine cuivre HCL, Oligopeptide-6, Copper Tripeptide-1, Tripeptide-1, Tripeptide-2, Tripeptide-3, Pentapeptide-3, Hexapeptide-2, Hexapeptide-9, Diacétate de dipeptide diaminobutyroylbenzylamide, Palmitoyl dipeptide-7, Palmitoyl Tetrapeptide-7, Palmitoyl Tripeptide-1, Palmitoyl tripeptide-5, Palmitoyl Pentapeptide-4, Palmitoyl hexapeptide-12, Arôme, Outremer', 'Le Vegan Peptide Bakuchiol Sun Stick SPF50+ PA++++ MARY & MAY est ton compagnon ultime pour la protection solaire et le rajeunissement de la peau. Ce remarquable stick solaire est doté d''un puissant mélange d''extrait de bakuchiol, de 25 types de peptides et de tocophérol pour non seulement protéger ta peau des rayons UV nocifs, mais aussi pour favoriser la synthèse du collagène et atténuer les rides. Dis adieu aux brillances indésirables grâce à l''inclusion de poudre qui garantit que ta peau reste lisse et sèche, même en cas de réapplications fréquentes. Découvre le luxe d''une texture soyeuse qui adhère parfaitement à ta peau, laissant un fini transparent et frais. Le format portable de ce stick en fait un choix idéal pour la protection solaire en déplacement, te permettant de renouveler l''application sans avoir à toucher ton visage, à tout moment et en tout lieu. Mieux encore, il est respectueux des récifs, formulé sans ingrédients nocifs tels que l''Ethylhexyl Methoxycinnamate, le Benzophenone-3, l''Octocrylène, le Benzophenone-1, le Benzophenone-8, ou le 4-Methylbenzylidene Camphor. Améliore ta routine beauté avec le Vegan Peptide Bakuchiol Sun Stick MARY & MAY . Ce stick solaire multifonctionnel te protège non seulement des rayons nocifs du soleil, mais agit aussi en profondeur pour rétablir et rajeunir ta peau. L''extrait de bakuchiol, ainsi que la puissance de 25 peptides et le tocophérol, garantissent que ta peau reste saine, radieuse et exempte des signes de l''âge. Sa formulation unique garantit un fini mat et non gras, pour que tu puisses sortir au soleil en toute confiance avec une peau fraîche, protégée et splendide. Recommandé pour : Peaux sensibles, tous types de peaux.', 18, 'g', 'mary-may-vegan-peptide-bakuchiol-sun-stick-spf50-pa', 'https://korean-skincare.fr/products/mary-may-vegan-peptide-bakuchiol-sun-stick-spf50-pa', 'https://aurore-cdn.b-cdn.net/products/mary-may-vegan-peptide-bakuchiol-sun-stick-spf50-pa.webp', 'Lors de la dernière étape de ta routine beauté, applique-le légèrement sur les zones exposées au soleil. Emporte-le avec toi et applique-le fréquemment sur les zones qui ont besoin d''une protection solaire.', 1670, '2026-05-07 17:37:40.521395+00', '2026-06-14 15:14:07.809+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4758-73a1-8eb0-74c55af3a058', '__OWNER_ID__', 'Cica-Hyal Sun Stick', 'MIXSOON', 'moisturizer', 'jar', 'Aqua, Dicaprylyl Carbonate, Adipate de Dibutyle, Synthetic Wax, Salicylate de Butyloctyle, Zinc Oxide, Méthicone de Caprylyle, Méthyl Triméthicone, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Microcrystalline Wax, Dipropylene Glycol, Silica, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Cérésine, Ethylhexyl Triazone, Isostéarate de Polyglycéryl-4, Copolymère d’Éthylène/Propylène, Caprylic/Capric Triglyceride, Magnesium Sulfate, Lauryl Polyglycéryl-3 Polydiméthylsiloxyéthyl Diméthicone, Glycerin, 1,2-Hexanediol, Bisabolol, Hectorite de Stéaralkonium, Butylene Glycol, Propanediol, Polyricinoléate de Polyglycéryl-3, Diisostéarate de Polyglycéryl-3, Triéthoxycaprylylsilane, Hydrogenated Lecithin, Oléate de Polyglycéryl-10, Polyhydroxystearic Acid, Disodium EDTA, Adenosine, Melia Azadirachta Leaf Extract, Extrait de Fleur de Melia Azadirachta, Tocopherol, Hyaluronic Acid, Hydrolyzed Hyaluronic Acid, Sodium Hyaluronate, Coccinia Indica Fruit Extract, Extrait de Fleur d’Aloe Barbadensis, Solanum Melongena Fruit Extract, Simmondsia Chinensis Seed Oil, Extrait de Corallina Officinalis, Curcuma Longa Root Extract, Ocimum Sanctum Leaf Extract, Centella Asiatica Extract, Extrait de Feuille de Centella Asiatica, Extrait de Racine de Centella Asiatica, Extrait d’Écorce de Pinus Pinaster, Asiaticoside, Acide Asiatique, Madecassoside, Acide Madécassique', 'Protège et apaise ta peau avec le Cica-Hyal Sun Stick MIXSOON, un écran solaire hybride qui offre une protection puissante SPF 50+ PA++++ sans laisser de traces blanches et avec un fini mat et lisse. Ce stick super pratique glisse facilement sur la peau, ce qui facilite les retouches, à tout moment et en tout lieu. Formulé avec trois types d''acide hyaluronique pour une hydratation en profondeur et des extraits de Centella Asiatica pour apaiser les irritations, il convient à tous les types de peaux, y compris les peaux sensibles. Que tu sois en déplacement ou en pleine séance de bronzage, ce stick solaire protège, hydrate et prend soin de ta peau. Recommandé pour : Peaux sensibles et sèches, tous types de peaux.', 15, 'g', 'mixsoon-cica-hyal-sun-stick', 'https://korean-skincare.fr/products/mixsoon-cica-hyal-sun-stick', 'https://aurore-cdn.b-cdn.net/products/mixsoon-cica-hyal-sun-stick.webp', 'Lors de la dernière étape de ta routine beauté, applique une quantité modérée de produit sur les zones exposées au soleil.', 2195, '2026-05-07 17:37:41.208143+00', '2026-06-14 15:14:07.817+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44ae-767d-91b3-f98c073211f7', '__OWNER_ID__', 'Vitamine C + Bifida Lotion', 'Mary&May', 'moisturizer', 'jar', 'Aqua, Caprylic/Capric Triglyceride, Lysat de Ferment Bifida (30,000 ppm), Glycerin, Niacinamide, Cetearyl Alcohol, Dipropylene Glycol, Ascorbic Acid, Butylene Glycol, Glyceryl Stearate SE, Cetyl Ethylhexanoate, Distéarate de Methylglucose Polyglycéryle-3, Tromethamine, Hydroxyacetophenone, Carbomer, Butyrospermum Parkii Butter, Palmitic Acid, Stearic Acid, Panthenol, Parfum, Tocopheryl Acetate, 1,2-Hexanediol, Adenosine, Caprylyl Glycol, Disodium EDTA, Pentylene Glycol, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Ethylhexylglycerin, Hydrolyzed Sodium Hyaluronate', 'La Vitamine C + Bifida Lotion MARY & MAY est une lotion enrichie en lysat de ferment bifida probiotique et en vitamine C qui agissent en synergie pour protéger la peau des dommages causés par l''environnement, révélant ainsi une peau ferme et éclatante. Le lysat de ferment de bifida reconstitue les nutriments pour une peau éclatante de santé, renforce la barrière pour favoriser la régénération de la peau et élimine les cellules mortes pour un teint lisse. Elle est infusé avec 1 000 ppm de vitamine C pour inhiber la synthèse de la mélanine et réduire la mélanine oxydée, améliorant ainsi l''apparence de la peau terne et des mélasmes.', 120, 'ml', 'mary-may-vitamine-c-bifida-lotion', 'https://korean-skincare.fr/products/mary-may-vitamine-c-bifida-lotion', 'https://aurore-cdn.b-cdn.net/products/mary-may-vitamine-c-bifida-lotion.webp', 'Distribue une quantité modérée de la crème. Applique-la sur l''ensemble de ton visage et masse délicatement pour une meilleure absorption.', 1562, '2026-05-07 17:37:40.526281+00', '2026-06-14 15:14:07.81+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44b9-78a4-b830-6068f8b90d9e', '__OWNER_ID__', 'Citrus Unshiu + Tremella Fuciformis Serum', 'Mary&May', 'serum', 'dropper', 'Extrait de Fruit de Citrus Unshiu, Tremella Fuciformis Extract, Arbutine, Glycereth-26, 1,2-Hexanediol, Arginine, Carbomer, Ethylhexylglycerin, Caprylyl Glycol', 'Le Citrus Unshiu + Tremella Fuciformis Serum MARY & MAY est un sérum pour le visage enrichi d''extrait de fruit de Citrus Unshiu et d''extrait de Tremella Fuciformis pour éclaircir le teint, réduire l''hyperpigmentation et reconstituer l''hydratation de la peau. Il contient 83,5 % d''extrait de fruit Citrus Unshiu pour éclaircir le teint, réduire l''hyperpigmentation et produire un effet antioxydant, donnant à la peau un aspect éclatant. Il contient également 9,7 % d''extrait de Tremella Fuciformis, qui a une grande capacité de rétention d''eau et qui procure une hydratation intense à la peau.', 30, 'ml', 'mary-may-citrus-unshiu-tremella-fuciformis-serum', 'https://korean-skincare.fr/products/mary-may-citrus-unshiu-tremella-fuciformis-serum', 'https://aurore-cdn.b-cdn.net/products/mary-may-citrus-unshiu-tremella-fuciformis-serum.webp', 'Prélève une quantité adéquate de produit à l''aide du compte-gouttes. Masse délicatement ta peau en suivant son grain. Renouvelle l''application sur le contour des yeux secs.', 1757, '2026-05-07 17:37:40.537469+00', '2026-06-14 15:14:07.81+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44bd-792e-9477-aba1a6aca238', '__OWNER_ID__', 'Seoul Edition Hand Cream Trio Set', 'Mary&May', 'hand-cream', 'jar', 'Bergamot & Pear Hand Cream : Aqua, Propanediol, Glycerin, Phenyl Trimethicone, Methyl Trimethicone, 1,2-Hexanediol, Trehalose, Coptis Japonica Root Extract, Extrait de Fruit de Poire, Hydrogenated Polyisobutene, Cetearyl Alcohol, Polyglyceryl-3 Methylglucose Distearate, Glyceryl Stearate, Dicaprylyl Carbonate, Ammonium Acryloyldimethyl Taurate/VP Copolymer, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Caprylyl Glycol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Butylene Glycol, Arginine, Ethylhexylglycerin, Disodium EDTA, Sorbitan Isostearate, Ceramide NP, Tocopherol, Parfum Muguet & Lotus Hand Cream : Aqua, Helianthus Annuus Seed Oil, Glycerin, Propanediol, Palmitic Acid, Stearic Acid, Cetearyl Glucoside, Cetearyl Alcohol, Glyceryl Stearate, Caprylic/Capric Triglyceride, Hydrogenated Polydecene, Extrait de Fleur de Lotus, Sodium Hyaluronate, 1,2-Hexanediol, Butyrospermum Parkii Butter, Hydroxyacetophenone, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Butylene Glycol, Ethylhexylglycerin, Gomme Xanthane, Disodium EDTA, Sorbitan Isostearate, Ceramide NP, Tocopherol, Parfum Shea Butter & Rice Bran Hand Cream : Aqua, Butyrospermum Parkii Butter, Glycerin, Cetearyl Alcohol, Coco-Caprylate/Caprate, Polyglyceryl-3 Distearate, Caprylyl Methicone, Glyceryl Stearate, Polymethylsilsesquioxane, Oryza Sativa Extract, 1,2-Hexanediol, Hydroxyethyl Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, Behenyl Alcohol, Hydroxyacetophenone, Sodium Stearoyl Glutamate, Glyceryl Stearate Citrate, Ethylhexylglycerin, Butylene Glycol, Gomme Xanthane, Sorbitan Isostearate, Disodium EDTA, Ceramide NP, Caprylyl Glycol, Tocopherol', 'Le Seoul Edition Hand Cream Trio Set Mary & May offre une expérience de soin luxueuse inspirée par la beauté de la Corée. Ce coffret comprend trois crèmes pour les mains aux parfums uniques : Shea Butter & Rice Bran Hand Cream : Enrichie en beurre de karité et en extrait de son de riz, cette crème sans parfum offre une hydratation longue durée sans effet collant. Muguet & Lotus Hand Cream : Une crème apaisante pour les mains au parfum léger de muguet et de lotus, qui pénètre rapidement et laisse les mains douces sans effet collant. Bergamot & Pear Hand Cream : Un mélange rafraîchissant de bergamote et de poire douce, parfait pour les soins quotidiens. Sa texture gel légère hydrate efficacement les mains et les cuticules. Chaque crème est testée dermatologiquement, certifiée vegan et sans allergènes, ce qui la rend adaptée à tous les types de peaux. Les tubes compacts de 50 ml sont parfaits pour une hydratation sur le pouce, garantissant des mains douces et hydratées tout au long de la journée. Recommandé pour : Peaux sèches, tous types de peaux.', 3, 'pcs', 'mary-may-seoul-edition-hand-cream-trio-set', 'https://korean-skincare.fr/products/mary-may-seoul-edition-hand-cream-trio-set', 'https://aurore-cdn.b-cdn.net/products/mary-may-seoul-edition-hand-cream-trio-set.webp', 'Prélève une quantité modérée de crème. Applique sur tes mains et masse délicatement pour une meilleure absorption.', 2495, '2026-05-07 17:37:40.541492+00', '2026-06-14 15:14:07.81+00', 'bodycare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44ca-7fe4-9963-81c8bbe8e09d', '__OWNER_ID__', 'AHA BHA PHA 30 Days Miracle Cream', 'SOME BY MI', 'moisturizer', 'jar', 'Aqua, Glycerin, Dipropylene Glycol, Butylene Glycol, Niacinamide, Caprylic/Capric Triglyceride, Cetyl Ethylhexanoate, Melaleuca Alternifolia Leaf Water, 1,2-Hexanediol, Saccharide Isomerate, Ammonium Acryloyldimethyltaurate/VP Copolymer, Ethyl Hexanediol, Centella Asiatica Extract, Ricinus Communis Seed Oil, Polyglyceryl-3 Methylglucose Distearate, Betaine, Allantoin, Propanediol, Benzyl Glycol, Cetearyl Glucoside, Sorbitan Olivate, Ceramide NP, Mentha Piperita Oil, Asiaticoside, Madecassic Acid, Asiatic Acid, Disodium EDTA, Melia Azadirachta Leaf Extract, Adenosine, Ethylhexylglycerin, Hydrogenated Castor Oil, Melia Azadirachta Flower Extract, Inulin Lauryl Carbamate, Coptis Japonica Root Extract, Cetearyl Alcohol, Coccinia Indica Fruit Extract, Citric Acid, Lens Esculenta Seed Extract, Sodium Hyaluronate, Fructan, Capryloyl Salicylic Acid, Sodium Citrate, Lactobionic Acid, Enantia Chlorantha Bark Extract, Madecassoside, Raspberry Ketone, Albatrellus Confluens Extract, Pentylene Glycol, Camellia Sinensis Leaf Extract, Aloe Barbadensis Flower Extract, Solanum Melongena Fruit Extract, Houttuynia Cordata Extract, Origanum Vulgare Flower/Leaf/Stem Extract, Thymus Vulgaris Extract, Rosmarinus Officinalis Extract, Lavandula Angustifolia Extract, Caprylyl Glycol, Ocimum Sanctum Leaf Extract, Curcuma Longa Root Extract, Calendula Officinalis Flower Extract, Phenoxyethanol, Hamamelis Extract, Corallina Officinalis Extract, Centella Asiatica Leaf Extract, Salix Alba Bark Extract, Oleanolic Acid, Limonene', 'La crème miracle 30 jours SOME BY MI AHA BHA PHA est une crème apaisante, douce et efficace, conçue pour tous les types de peau, en particulier les peaux sensibles et sujettes à l''acné. Formulée avec 70 % d''extrait de Centella Asiatica et 10 000 ppm d''eau de feuilles de théier, elle offre une hydratation apaisante et rafraîchissante sans effet collant. La crème contient un mélange d''AHA, de BHA et de PHA pour exfolier en douceur les cellules mortes de la peau, éliminer l''excès de sébum et affiner le grain de peau. Enrichie de 4 types de Cica, dont l''extrait de pourpier, elle renforce la barrière cutanée tout en favorisant la santé générale de la peau. Cet hydratant quotidien léger permet un renouvellement doux de la peau, minimise la perte d''hydratation et laisse la peau lisse, calme et revitalisée. Il est parfait pour ceux qui recherchent une solution non irritante pour apaiser et rajeunir les peaux à problèmes. Recommandé pour : Peau sujette à l''acné, tous les types de peau.', 60, 'g', 'some-by-mi-aha-bha-pha-30-days-miracle-cream', 'https://korean-skincare.fr/products/some-by-mi-aha-bha-pha-30-days-miracle-cream', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-aha-bha-pha-30-days-miracle-cream.webp', 'Utilise lors de la dernière étape de ta routine beauté. Étale une quantité généreuse de crème sur ton visage, ton cou et la partie supérieure de ta poitrine. Masse délicatement pour une meilleure absorption.', 1807, '2026-05-07 17:37:40.554885+00', '2026-06-14 15:14:07.81+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44c8-7431-92d7-99089dc36338', '__OWNER_ID__', 'Retinol Intense Reactivating Serum', 'SOME BY MI', 'essence', 'dropper', 'Aqua, Cyclohexasiloxane, Dicaprylyl Carbonate, Glycerin, Methylpropanediol, 1,2-Hexanediol, Niacinamide, Hydrogenated Poly(C6-14 Olefin), Panthenol, Tocopheryl Acetate, Extrait de feuille/racine/tige de Piper Methysticum, Centella Asiatica Extract, Extrait de baie de Panax Ginseng, Glycyrrhiza Glabra Root Extract, Ficus Carica Fruit Extract, Extrait de feuille de Centella Asiatica, Extrait de racine de Centella Asiatica, Melaleuca Alternifolia Leaf Extract, Extrait de Artemisia Capillaris, Extrait de Eclipta Prostrata, Melia Azadirachta Leaf Extract, Huile d''Elaeis Guineensis (Palmier), Hydrogenated Lecithin, Glyceryl Stearate, Bakuchiol, Palmitic Acid, Polyacrylate de sodium, Stearic Acid, Gomme xanthane, Retinol, Acrylates/C10-30 Alcoyl Acrylate Crosspolymer, Butylene Glycol, Dipotassium Glycyrrhizate, Adenosine, Tromethamine, Polyquaternium-51, Beta-Glucan, Cetearyl Alcohol, BHT, Collagène, Myristic Acid, BHA, Filtrat de ferment de racine de Leuconostoc/Radis, Tocopherol, Bifida Ferment Lysate, Ceramide NP, Saccharomyces Ferment Filtrate, Retinal, Asiaticoside, Polyméthacrylate de glycéryle, Madecassoside, Propylene Glycol, Oléate de polyglycéryle-10, Glycolipides, Peptide de Glycine Soja (Soja), Resveratrol, Distearate de saccharose, Acide asiatique, Acide madécassique, Tripeptide-1 palmitoylé, Moringa Oleifera Seed Oil, PEG-100 Stearate, Polysorbate 20, Parfum, Ethylhexylglycerin', 'Le Retinol Intense Reactivating Serum SOME BY MI est un sérum puissant mais doux conçu pour aider à réduire les signes de l''âge, même pour les personnes à la peau sensible. Ce sérum est infusé d''un puissant mélange de rétinol, de rétinal et de bakuchiol pour aider à stimuler l''élasticité de la peau et à réduire l''apparence des rides et ridules, le tout avec une faible irritation. Grâce à la technologie brevetée Elastic-Liposome, ce sérum fait pénétrer les ingrédients actifs en profondeur dans la peau, ce qui permet d''obtenir des résultats optimaux. Non seulement ce sérum combat efficacement les signes du vieillissement, mais il offre également un fini non collant et hydratant. Parfait pour un usage quotidien, ce sérum a passé les tests d''irritation de la peau et est certifié vegan. Obtiens un teint plus jeune et plus éclatant avec le Retinol Intense Reactivating Serum, le complément parfait à ta routine beauté quotidienne.', 30, 'ml', 'some-by-mi-retinol-intense-reactivating-serum', 'https://korean-skincare.fr/products/some-by-mi-retinol-intense-reactivating-serum', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-retinol-intense-reactivating-serum.webp', 'Après le nettoyage, prépare ta peau avec un tonique. Distribue une quantité appropriée de produit lors de l''étape de l''essence et applique-le sur ton visage de façon uniforme. Termine avec une crème hydratante une fois que le produit est entièrement absorbé.', 2248, '2026-05-07 17:37:40.552147+00', '2026-06-14 15:14:07.81+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44cd-75f7-b6ad-df4aea33776a', '__OWNER_ID__', 'Retinol Intense Advanced Triple Action Eye Cream', 'SOME BY MI', 'eye-cream', 'jar', 'Aqua, Glycerin, Caprylic/Capric Triglyceride, Dimethicone, Polysorbate 60, Niacinamide, Methylpropanediol, Cetyl Alcohol, Polyméthylsilsesquioxane, Centella Asiatica Extract, Dioscorea Japonica Root Extract, Extrait de feuille/racine/tige de Piper Methysticum, Melaleuca Alternifolia Leaf Extract, Extrait de baie de Panax Ginseng, Extrait d''Artemisia Capillaris, Extrait de tige de Ganoderma Lucidum, Extrait de Chlorella Vulgaris, Extrait de graine de Glycine Soja, Extrait de fleur de Nymphaea Alba, Huile d''Elaeis Guineensis, Hydrogenated Lecithin, Sodium Hyaluronate, 1,2-Hexanediol, Copolymère de diméthicone/vinyl diméthicone, Panthenol, BHT, Cyclopentasiloxane, Steareth-21, Copolymère de PEG-10 diméthicone/vinyl diméthicone, Polyacrylamide, Steareth-2, Isohexadecane, Carbomer, Hydroxyacetophenone, C13-14 Isoparaffine, Tromethamine, Palmitic Acid, Polyquaternium-51, Stearic Acid, Polysorbate 20, Retinol, Ethylhexylglycerin, Glyceryl Caprylate, Tocopheryl Acetate, Myristate de polyglycéryl-10, PEG-30 dipolyhydroxystéarate, Hydroxyéthylcellulose, Glycosyl tréhalose, Beta-Glucan, Polyméthacrylate de glycéryle, Laureth-7, Butylene Glycol, Disodium EDTA, Hydrolysat d''amidon hydrogéné, Adenosine, Raffinose, Dipotassium Glycyrrhizate, Lecithin, Tocopherol, Pentylene Glycol, BHA, Myristic Acid, Tranexamic Acid, Propanediol, Dipropylene Glycol, Phosphate disodique, Caprylyl Glycol, Collagène, Acide madécassique, Biosaccharide Gum-1, Asiatocoside, Palmitoylproline de sodium, Filtrat de ferment de racine de Leuconostoc/Radis, Acide asiatique, Glutathione, Retinal, Madecassoside, Sodium Phosphate, Ferulic Acid, Acetyl Hexapeptide-8, Copolymère d''acryloyldiméthyltaurate/VP d''ammonium, Tétrahydropipérine, Phlorétine, Arginine, Parfum', 'La Retinol Intense Advanced Triple Action Eye Cream SOME BY MI est un complément indispensable à ta routine beauté ! Cette crème pour les yeux testée dermatologiquement est formulée sans 20 types d''ingrédients nocifs, ce qui la rend douce même pour les peaux les plus sensibles. Cette crème hydratante anti-âge est spécialement conçue pour la zone délicate des yeux et agit pour améliorer l''apparence des cernes et des ridules. Elle contient du rétinol, un puissant ingrédient anti-âge qui aide à réduire l''apparence des rides et des ridules. En plus du rétinol, cette crème pour les yeux contient également du niacinamide, qui possède des vertus éclaircissantes et aide à uniformiser le teint. L''acide hyaluronique et le panthénol procurent une hydratation intense à la peau, la laissant rebondie et souple. Dis au revoir aux yeux fatigués et bonjour à un visage plus jeune et plus radieux avec la Retinol Intense Advanced Triple Action Eye Cream SOME BY MI.', 30, 'ml', 'some-by-mi-retinol-intense-advanced-triple-action-eye-cream', 'https://korean-skincare.fr/products/some-by-mi-retinol-intense-advanced-triple-action-eye-cream', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-retinol-intense-advanced-triple-action-eye-cream.webp', 'Applique une quantité appropriée du produit sur la zone du contour des yeux. Avec l''applicateur, masse délicatement pour une absorption complète.', 1820, '2026-05-07 17:37:40.557204+00', '2026-06-14 15:14:07.811+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44cf-7cc8-9f93-0eea4ea75a75', '__OWNER_ID__', 'Retinol Intense Sheetmask', 'SOME BY MI', 'mask', 'pack', 'Aqua, Glycerin, Glycereth-26, Butylene Glycol, 1,2-Hexanediol, Carbomer, Arginine, Gomme Xanthane, Disodium EDTA, Laurate de Polyglycéryl-10, Adenosine, Dipropylene Glycol, Laurate de Polyglycéryl-4, Zéolite, Sodium Hyaluronate, Glycine, Glutamic Acid, Ethylhexylglycerin, Eau de Fleur de Rosa Centifolia, Caprylic/Capric Triglyceride, Acide Aspartique, Polyacrylate de Sodium, Sodium Chloride, Hydrogenated Lecithin, Collagène Hydrolysé, Acetyl Hexapeptide-8, Centella Asiatica Extract, Sérine, Histidine, Alanine, Thréonine, Proline, Astaxanthine, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Chlorure de Magnésium, Lecithin, Chlorure de Calcium, Retinal, Ascorbic Acid, Copper Tripeptide-1, Tripeptide-1, Palmitoyl Pentapeptide-4, Hexapeptide-9, Parfum', 'Le Retinol Intense Sheetmask SOME BY MI aide à réduire les signes du vieillissement et à améliorer l''élasticité de la peau. Infusé d''ingrédients puissants comme le rétinol, le rétinal et le bakuchiol, ce masque tissu fournit une puissante dose de bienfaits anti-âge à ta peau. Avec 10 types d''acide hyaluronique, ce masque hydrate en profondeur et fortifie la barrière d''hydratation de ta peau, ce qui lui donne un aspect rebondi, radieux et rajeuni. La composition en microfibres spécialement conçue permet une absorption maximale, ce qui garantit que les ingrédients actifs pénètrent en profondeur dans ta peau. Dis adieu aux ridules, aux rides et aux autres signes de vieillissement avec le Retinol Intense Sheetmask SOME BY MI. Découvre la puissance du rétinol et de l''acide hyaluronique, et dévoile une peau rajeunie, radieuse et éclatante.', 1, 'pcs', 'some-by-mi-retinol-intense-sheetmask', 'https://korean-skincare.fr/products/some-by-mi-retinol-intense-sheetmask', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-retinol-intense-sheetmask.webp', 'Après avoir nettoyé et tonifié ton visage, applique le masque tissu en l''ajustant à ton visage. Retire le masque au bout de 10 à 20 minutes. Tapote délicatement ta peau pour favoriser l''absorption.', 395, '2026-05-07 17:37:40.559642+00', '2026-06-14 15:14:07.811+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44d5-73cc-acb2-6eb432a1787e', '__OWNER_ID__', 'AHA BHA PHA 30 Days Miracle Acne Clear Foam', 'SOME BY MI', 'cleanser', 'tube', 'Aqua, Glycerin, Centella Asiatica Extract, Palmitic Acid, Stearic Acid, Lauric Acid, Myristic Acid, Potassium Hydroxide, Lauryl Betaine, Butylene Glycol, PEG-100 Stearate, Glyceryl Stearate, PEG-8 Beeswax, Melaleuca Alternifolia Leaf Water, Sodium Methyl Cocoyl Taurate, Potassium Cocoyl Glycinate, Salicylic Acid, Dipropylene Glycol, Sodium Chloride, Hydroxyacetophenone, Mentha Piperita Oil, Caprylyl Glycol, 1,2-Hexanediol, Disodium EDTA, Hydroxyethylcellulose, Calamine, Gluconolactone, Dipotassium Glycyrrhizate, Citric Acid, Artemisia Vulgaris, Madecassoside, Asiaticoside, Madecassic Acid, Asiatic Acid', 'L''AHA BHA PHA 30 Days Miracle Acne Clear Foam Some By Mi est un nettoyant anti-acné qui aide à affiner la texture de la peau et à contrôler l''excès de sébum. Il est formulé avec des AHA, BHA et PHA pour éliminer les cellules mortes de la peau et dégager les pores, tandis que la présence de Truecica™ permet d''apaiser la peau pendant le nettoyage. Attention : c''est un nettoyant puissant!', 100, 'ml', 'some-by-mi-aha-bha-pha-30-days-miracle-acne-foam', 'https://korean-skincare.fr/products/some-by-mi-aha-bha-pha-30-days-miracle-acne-foam', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-aha-bha-pha-30-days-miracle-acne-foam.webp', 'Prend une quantité suffisante de nettoyant dans la main et fais mousser. Applique sur l''ensemble de ton visage. Rince soigneusement à l''eau tiède.', 1345, '2026-05-07 17:37:40.565008+00', '2026-06-14 15:14:07.811+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44d9-7f0b-90bf-9a641ec2e6d9', '__OWNER_ID__', 'AHA BHA PHA 30 Days Miracle AC SOS Kit', 'SOME BY MI', 'moisturizer', 'jar', 'AHA BHA PHA 30 Days Miracle Acne Clear Foam (30 Ml) : Eau, Glycerin, Centella Asiatica Extract, Palmitic Acid, Stearic Acid, Lauric Acid, Myristic Acid, Potassium Hydroxide, Lauryl Betaine, Butylene Glycol, Glyceryl Stearate, PEG-100 Stearate, Cera Alba, Melaleuca Alternifolia Leaf Water, Sodium Methyl Cocoyl Taurate, Potassium Cocoyl Glycinate, Salicylic Acid, Dipotassium Glycyrrhizate, Sodium Chloride, Hydroxyéthylcellulose, Extrait de Mentha Haplocalix, Ethylhexylglycerin, Huile de Graines de Calophyllum Inophyllum, 1,2-Hexanediol, Disodium EDTA, Hydroxyacetophenone, Calamine, Pentylene Glycol, Gluconolactone, Dipropylene Glycol, Acide Hydroxycaprique, Melaleuca Alternifolia Leaf Oil, Lactic Acid, Asiaticoside, Acide Madécassique, Acide Asiatique AHA BHA PHA Miracle Toner (30 Ml) : Eau, Butylene Glycol, Dipropylene Glycol, Niacinamide, Melaleuca Alternifolia Leaf Water, Benzyl Glycol, Polyglyceryl-4 Caprate, Sodium Citrate, Hydroxyéthylurée, Eau d’Hamamélis (Hamamelis Virginiana), Betaine, Chamaecyparis Obtusa Water, Carica Papaya Fruit Extract, Alcohol, Lactobionic Acid, Glycerin, Salicylic Acid, Panthenol, Gluconolactone, Sodium Hyaluronate, Pentylene Glycol, Extrait de Fleur de Melia Azadirachta, Éthyl Hexanediol, Disodium EDTA, Extrait de Mentha Haplocalix, Camellia Sinensis Leaf Extract, Allantoin, Melia Azadirachta Leaf Extract, Glycolic Acid, BHA, Gluconolactone, Ulmus Davidiana Root Extract, Rosmarinus Officinalis Leaf Oil, Eucalyptus Globulus Leaf Oil, Huile de Feuille d’Origanum Majorana, Lavandula Angustifolia Oil, PEG-60 Huile de Ricin Hydrogénée, 1,2-Hexanediol, Ethylhexylglycerin, Madecassoside, Asiaticoside, Acide Asiatique, Acide Madécassique AHA BHA PHA Miracle Serum (10 Ml) : Eau, Glycerin, Butylene Glycol, Alcohol, Niacinamide, Caprylic/Capric Triglyceride, Cetyl Ethylhexanoate, Melaleuca Alternifolia Leaf Oil, Dipropylene Glycol, Centella Asiatica Extract, Cétéaryl Olivate, Sorbitan Olivate, Salicylic Acid, Betaine, Sodium Hyaluronate, Polyglycéryl-10 Laurate, Panthenol, Gomme Xanthane, PEG-60 Huile de Ricin Hydrogénée, Allantoin, Gluconolactone, Lactic Acid, Lactobionic Acid, Acide Madécassique, Acide Asiatique, Asiaticoside, Melaleuca Alternifolia Leaf Extract, Portulaca Oleracea Extract, Houttuynia Cordata Extract, Curcuma Longa Root Extract, Extrait de Racine de Scutellaria Baicalensis, Glycyrrhiza Glabra Root Extract, Camellia Sinensis Leaf Extract, Sodium Citrate, Disodium EDTA, Ethylhexylglycerin, 1,2-Hexanediol AHA BHA PHA Miracle Cream (20 G) : Eau, Glycerin, Dipropylene Glycol, Butylene Glycol, Niacinamide, Caprylic/Capric Triglyceride, Cetyl Ethylhexanoate, Melaleuca Alternifolia Leaf Water, 1,2-Hexanediol, Macadamia Integrifolia Seed Oil, Cetearyl Alcohol, Sorbitan Olivate, Centella Asiatica Extract, Ricinus Communis Seed Oil, Polyglycéryl-2 Stéarate, Glyceryl Stearate, Polyglycéryl-10 Stéarate, Behenyl Alcohol, Melaleuca Alternifolia Leaf Oil, Betaine, Sodium Hyaluronate, Glycereth-26, Glyceryl Stearate SE, Sorbitan Stéarate, Salicylic Acid, Panthenol, Allantoin, Gluconolactone, Acide Asiatique, Acide Madécassique, Asiaticoside, Madecassoside, Polyacrylate de Sodium, Disodium EDTA, Ethylhexylglycerin, Gomme Xanthane, Camellia Sinensis Leaf Extract, Extrait d’Hamamélis (Hamamelis Virginiana), Extrait de Racine de Scutellaria Baicalensis, Houttuynia Cordata Extract, Lactobacillus Ferment Lysate, Extrait de Lavandula Angustifolia (Lavande), Extrait d’Artemisia Vulgaris, Extrait de Rosmarinus Officinalis (Romarin), Extrait de Feuille d’Origanum Vulgare, Curcuma Longa Root Extract, Extrait de Fleur/Feuille d’Ocimum Basilicum (Basilic), Helianthus Annuus Seed Oil, Coptis Japonica Root Extract, Ulmus Davidiana Root Extract, Collagène Hydrolysé, Tocopherol, Extrait de Mentha Arvensis, Éthyl Ascorbyl Ether, Ceramide NP, Sodium Phytate, Lecithin', 'Le Kit AC SOS 30 Days Miracle SOME BY MI se compose de versions miniatures des quatre produits les plus vendus de SOME BY MI, une marque coréenne qui propose une large gamme de produits fonctionnels et tendance, allant des soins de la peau au maquillage. La marque défend la réglementation relative à l''interdiction des tests sur les animaux et affiche une étiquette "cruelty-free" sur tous ses produits cosmétiques. Elle est fière de ses produits renommés et de leurs effets positifs sur la planète. Ce kit contient : AHA BHA PHA 30 Days Miracle Acne Clear Foam (30ml) : Apaise la peau grâce à de l''eau de Centella Asiatica et de feuille d''Arbre à Thé, et atténue les rougeurs causées par les imperfections. AHA BHA PHA Miracle Toner (30ml) : Agit comme un exfoliant efficace pour purifier et lisser la peau, et révéler tout son éclat. AHA BHA PHA Miracle Serum (10ml) ; Permet d''exfolier la peau, de resserrer les pores, d''hydrater et d''illuminer le teint. AHA BHA PHA Miracle Cream (20g) : A un double effet éclaircissant et anti-rides qui prend soin de la peau tout en lui conférant éclat et douceur. Recommandé pour : Tous types de peaux.', NULL, NULL, 'some-by-mi-aha-bha-pha-30-days-miracle-ac-sos-kit', 'https://korean-skincare.fr/products/some-by-mi-aha-bha-pha-30-days-miracle-ac-sos-kit', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-aha-bha-pha-30-days-miracle-ac-sos-kit.webp', 'Utilise les produits dans l’ordre suivant : Cleansing Gel → Toner → Serum → Cream. Nettoyant : Applique une quantité généreuse de gel nettoyant sur ton visage humide. Masse délicatement par mouvements circulaires pour éliminer les impuretés et l’excès de sébum. Rince abondamment à l’eau tiède, puis sèche en tapotant avec une serviette douce. Tonique : Après le nettoyage, dépose une quantité appropriée de tonique dans tes mains ou sur un coton. Applique uniformément en suivant le grain de peau et tapote doucement pour favoriser l’absorption. Sérum : Applique une quantité modérée de sérum sur le visage, en insistant sur les zones ciblées. Tapote ou presse délicatement jusqu’à absorption complète. Crème : Termine avec une crème nourrissante. Applique-la uniformément sur le visage et le cou, puis tapote doucement pour sceller l’hydratation et finaliser ta routine.', 1895, '2026-05-07 17:37:40.569796+00', '2026-06-14 15:14:07.811+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44dc-75be-b8a8-f1e233aacda5', '__OWNER_ID__', 'Bye Bye Blackhead 30 Days Miracle Green Tea Tox Bubble Cleanser', 'SOME BY MI', 'cleanser', 'tube', 'Aqua, Camellia Sinensis Leaf Water, Disodium Cocoamphodiacetate, Glycerin, Glycinate De Potassium Cocoyl, Coco-Betaine, Méthyl Perfluorobutyl Ether, Méthyl Perfluoroisobutyl Ether, Acrylates Copolymer, Salix Alba Bark Extract, Aqua, Eau De Fleur De Jasminum Officinale (Jasmin), Extrait De Fruit De Chaenomeles Sinensis, Extrait De Feuille De Diospyros Kaki, Extrait D''Écorce De Cinnamomum Cassia, Artemisia Princeps Leaf Extract, Extrait De Chrysanthellum Indicum, Camellia Sinensis Leaf Extract, Extrait De Fleur D''Hibiscus Sabdariffa, Extrait De Lavandula Angustifolia (Lavande), Extrait De Rosmarinus Officinalis (Romarin), Chamomilla Recutita (Matricaria) Flower Extract, Extrait De Géranium Maculatum, Salvia Officinalis Leaf Extract, Extrait De Fleur De Trifolium Pratense (Trèfle), Extrait De Feuille D''Alchemilla Vulgaris, Extrait D''Aspalathus Linearis, Extrait D''Helichrysum Arenarium, Extrait De Feuille De Pinus Densiflora, Extrait De Bambusa Vulgaris, Extrait De Thuja Orientalis, Extrait De Feuille De Chamaecyparis Obtusa, Melaleuca Alternifolia Leaf Water, Centella Asiatica Extract, Vitis Vinifera Fruit Extract, Extrait De Graine De Coffea Arabica (Café), Extrait De Fleur De Carthamus Tinctorius (Carthame), Extrait De Racine De Polygonum Cuspidatum, Extrait De Coque De Castanea Crenata (Châtaigne), Zanthoxylum Piperitum Fruit Extract, Isomérate De Saccharide, Mannane, Feuille De Camellia Sinensis, Poudre De Feuille De Camellia Sinensis, Butylene Glycol, Caprylyl Glycol, Citric Acid, 1,2-Hexanediol, Ethylhexylglycerin, Benzyl Glycol, Cétone De Framboise, Caramel, CI 19140, CI 42090, Disodium EDTA, Mentha Piperita Oil', 'Découvre le puissant nettoyant naturel et purifiant Bye Bye Blackhead 30 Days Miracle Green Tea Tox Bubble Cleanser SOME BY MI, composé de 16 types de feuilles de thé et d''acides BHA d''origine naturelle. Cette ingénieuse mousse nettoyante vient purifier les pores en profondeur, absorbant les impuretés, les points noirs et les comédons incrustés. Il exfolie et hydrate pour maintenir l''équilibre d''hydratation délicat de la peau. Ce nettoyant miracle donnera à ton teint plus d''éclat, de douceur et d''hydratation.', 120, 'g', 'bye-bye-blackhead-30-days-miracle-green-tea-tox-bubble-cleanser', 'https://korean-skincare.fr/products/bye-bye-blackhead-30-days-miracle-green-tea-tox-bubble-cleanser', 'https://aurore-cdn.b-cdn.net/products/bye-bye-blackhead-30-days-miracle-green-tea-tox-bubble-cleanser.webp', 'Étale une petite quantité de produit sur ton visage sec, en évitant le contour des yeux. Étale le produit finement et uniformément, comme si tu appliquais un masque pour visage. Laisse agir pendant 2 à 3 minutes jusqu''à ce que ton visage soit couvert de bulles mousseuses, puis masse ta peau en effectuant de petits mouvements circulaires et en utilisant une petite quantité d''eau. Attends une minute environ puis rince abondamment à l''eau tiède.', 1611, '2026-05-07 17:37:40.5722+00', '2026-06-14 15:14:07.811+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44eb-7707-9ecd-01a272686de2', '__OWNER_ID__', 'Retinol Intense Trial Kit', 'SOME BY MI', 'moisturizer', 'jar', 'Retinol Intense Reactivating Serum : Eau, Cyclohexasiloxane, Dicaprylyl Carbonate, Glycerin, Methylpropanediol, 1,2-Hexanediol, Niacinamide, Hydrogenated Poly(C6-14 Olefin), Panthenol, Tocopheryl Acetate, Extrait de Feuille/Racine/Tige de Piper Methysticum, Centella Asiatica Extract, Extrait de Baie de Panax Ginseng, Glycyrrhiza Glabra Root Extract, Ficus Carica Fruit Extract, Extrait de Feuille de Centella Asiatica, Extrait de Racine de Centella Asiatica, Melaleuca Alternifolia Leaf Extract, Extrait d''Artemisia Capillaris, Extrait de Eclipta Prostrata, Melia Azadirachta Leaf Extract, Huile de Elaeis Guineensis, Hydrogenated Lecithin, Glyceryl Stearate, Bakuchiol, Palmitic Acid, Polyacrylate de Sodium, Stearic Acid, Gomme Xanthane, Retinol, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Butylene Glycol, Dipotassium Glycyrrhizate, Adenosine, Tromethamine, Polyquaternium-51, Beta-Glucan, Cetyl Alcohol, BHT, Collagène, Myristic Acid, BHA, Filtrat de Ferment de Racine de Leuconostoc, Tocopherol, Bifida Ferment Lysate, Ceramide NP, Saccharomyces Ferment Filtrate, Retinal, Asiaticoside, Polyméthacrylate de Glycéryle, Madecassoside, Propylene Glycol, Oléate de Polyglycéryl-10, Glycolipides, Peptide de Glycine Soja, Resveratrol, Distearate de Saccharose, Acide Asiatique, Acide Madecassique, Palmitoyl Tripeptide-1, Moringa Oleifera Seed Oil, PEG-100 Stearate, Polysorbate 20, Parfum, Ethylhexylglycerin. Retinol Intense Advanced Triple Action Eye Cream : Eau, Glycerin, Caprylic/Capric Triglyceride, Dimethicone, Polysorbate 60, Niacinamide, Methylpropanediol, Cetyl Alcohol, Polyméthylsilsesquioxane, Centella Asiatica Extract, Dioscorea Japonica Root Extract, Extrait de Feuille/Racine/Tige de Piper Methysticum, Melaleuca Alternifolia Leaf Extract, Extrait de Baie de Panax Ginseng, Extrait d''Artemisia Capillaris, Extrait de Tige de Ganoderma Lucidum, Extrait de Chlorella Vulgaris, Extrait de Graine de Glycine Soja, Extrait de Fleur de Nymphaea Alba, Huile de Elaeis Guineensis, Hydrogenated Lecithin, Sodium Hyaluronate, 1,2-Hexanediol, Crosspolymère de Diméthicone/Vinyl Diméthicone, Panthenol, BHT, Cyclopentasiloxane, Steareth-21, Crosspolymère de Diméthicone/Vinyl Diméthicone PEG-10, Polyacrylamide, Steareth-2, Isohexadecane, Carbomer, Hydroxyacetophenone, C13-14 Isoparaffin, Tromethamine, Palmitic Acid, Polyquaternium-51, Stearic Acid, Polysorbate 20, Retinol, Ethylhexylglycerin, Glyceryl Caprylate, Tocopheryl Acetate, Myristate de Polyglycéryl-10, Dipolyhydroxystéarate de PEG-30, Hydroxyéthylcellulose, Tréhalose Glycosylé, Beta-Glucan, Polyméthacrylate de Glycéryle, Laureth-7, Butylene Glycol, Disodium EDTA, Hydrolysat d''Amidon Hydrogéné, Adenosine, Raffinose, Dipotassium Glycyrrhizate, Lecithin, Tocopherol, Pentylene Glycol, BHA, Myristic Acid, Tranexamic Acid, Propanediol, Dipropylene Glycol, Phosphate Disodique, Caprylyl Glycol, Collagène, Acide Madecassique, Biosaccharide Gum-1, Asiaticoside, Proline Palmitoyle de Sodium, Filtrat de Ferment de Racine de Leuconostoc, Acide Asiatique, Glutathione, Retinal, Madecassoside, Sodium Phosphate, Ferulic Acid, Acetyl Hexapeptide-8, Ammonium Acryloyldimethyltaurate/VP Copolymer, Tétrahydropipérine, Phlorétine, Arginine, Parfum', 'Améliore ta routine beauté avec le Retinol Intense Trial Kit SOME BY MI, qui comprend le Retinol Intense Reactivating Serum (10ml) et le Retinol Intense Advanced Triple Action Eye Cream (10ml). Le Retinol Intense Reactivating Serum est un produit puissant formulé pour combattre les signes de l''âge, qui convient même aux peaux sensibles. Infusé d''un puissant mélange de rétinol, de rétinal et de bakuchiol, il améliore l''élasticité de la peau et atténue l''apparence des rides et ridules avec un minimum d''irritation. Il est accompagné de la Retinol Intense Advanced Triple Action Eye Cream, une formule testée dermatologiquement et exempte de 20 ingrédients nocifs. Conçue spécifiquement pour la zone délicate des yeux, cette crème hydratante anti-âge cible les cernes et les ridules grâce aux puissants bienfaits du rétinol. Chouchoute ta peau avec ce duo dynamique pour une apparence rajeunie et revitalisée. Recommandé pour : Peaux sensibles, tous types de peaux. Comprend : Retinol Intense Reactivating Serum (10ml) Retinol Intense Advanced Triple Action Eye Cream (10ml)', NULL, NULL, 'some-by-mi-retinol-intense-trial-kit', 'https://korean-skincare.fr/products/some-by-mi-retinol-intense-trial-kit', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-retinol-intense-trial-kit.webp', 'Retinol Intense Reactivating Serum : Après le nettoyage, prépare ta peau avec un tonique. Distribue une quantité appropriée de produit lors de l''étape de l''essence et applique-le sur ton visage de façon uniforme. Termine avec une crème hydratante une fois que le produit est entièrement absorbé. Retinol Intense Advanced Triple Action Eye Cream : Applique une quantité appropriée de produit sur la zone du contour des yeux. Masse délicatement pour une absorption complète.', 1566, '2026-05-07 17:37:40.587238+00', '2026-06-14 15:14:07.812+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44de-7de0-9415-797e316ed534', '__OWNER_ID__', 'AHA BHA PHA 30 Days Miracle Acne Clear Body Cleanser', 'SOME BY MI', 'moisturizer', 'jar', 'Aqua, Glycerin, Centella Asiatica Extract, Palmitic Acid, Stearic Acid, Acide Loachic, Myristic Acid, Potassium Hydroxide, Laurilvetane, Butylene Glycol, PEG-100 Stearate, Glyceryl Stearate, Cera Alba, Melaleuca Alternifolia Leaf Water, Taurate de Sodium Methyl Cocoyl, Glycinate de Potassium Cocoyl, Salicylic Acid, Dipropylène Glycol Dibenzoate, Sodium Chloride, Hydroxyacetophenone, Mentha Piperita Oil, Caprylyl Glycol, 1,2-Hexanediol, Disodium EDTA, Hydroxyéthylcellulose, Calamine, Gluconolactone, Citric Acid, Dipotassium Glycyrrhizate, Extrait d''Artemisia Princeps, Madecassoside, Asiaticoside, Acide Asiatique, Acide Madecassique', 'Découvre le plaisir d''une peau purifiée et revitalisée avec l''AHA BHA PHA 30 Days Miracle Acne Clear Body Cleanser SOME BY MI. Enrichi d''un puissant mélange d''ingrédients anti-acné, ce nettoyant pour le corps est une véritable bouée de sauvetage pour la peau. L''AHA et le PHA font équipe pour exfolier en douceur et éliminer les cellules mortes de la peau, tandis que le BHA agit avec efficacité pour atténuer les problèmes cutanés. La présence de 10 000 ppm d''extraits de Truecica™ et de Houttuynia Cordata apporte une sensation d''apaisement, calmant la peau et favorisant le processus de cicatrisation. Traduit avec DeepL.com (version gratuite)', 400, 'g', 'some-by-mi-aha-bha-pha-30-days-miracle-acne-clear-body-cleanser', 'https://korean-skincare.fr/products/some-by-mi-aha-bha-pha-30-days-miracle-acne-clear-body-cleanser', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-aha-bha-pha-30-days-miracle-acne-clear-body-cleanser.webp', 'Utilise une petite quantité de produit sur une éponge de douche ou un gant de toilette pour le faire mousser. Masse doucement ton corps avec, et rince à l''eau tiède.', 2095, '2026-05-07 17:37:40.574715+00', '2026-06-14 15:14:07.812+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4509-7482-9c8b-698524a5263a', '__OWNER_ID__', 'Yuja Niacin Anti-Blemish Cream', 'SOME BY MI', 'spot-treatment', 'tube', 'Citrus Junos Fruit Extract, Aqua, Butylene Glycol, Niacinamide, Glycerin, Panthenol, 1,2-Hexanediol, Simmondsia Chinensis Seed Oil, Benzyl Glycol, (-)-Alpha-Bisabolol, Triméthicone de Diphenylsiloxyphenyl, Arginine, Caprylylméthicone, Trehalose, Behenyl Alcohol, Copolymère Acrylate/C10-30 Alkyle Acrylate, Copolymère Acrylate de Sodium/Acryloyldiméthyl Taurate de Sodium, Coptis Japonica Root Extract, Polyisobutene, Sorbitan Isostearate, Carbomer, Centella Asiatica Extract, Copolymère Diméthicone/Phényl Vinyl Diméthicone, Carbamate de Lauryle d’Inuline, Extrait de Feuille de Biota Orientalis, Tocopherol, Stearyl Alcohol, Alcool Arachidylique, Glucoside de Xylityle, Ethylhexylglycerin, Adenosine, Anhydroxylitol, Disodium EDTA, Gomme de Xanthane, Zanthoxylum Piperitum Fruit Extract, Oléate de Sorbitane, Glucoside de Caprylyl/Capryl, Xylitol, Zanthoxylum Piperitum Fruit Extract, Zanthoxylum Piperitum Fruit Extract, Extrait de Racine de Polygonum Cuspidatum, Cétone de Framboise, Glutathione, Biotin, Ascorbyl Glucoside, Tétraisopalmitate d’Ascorbyle, Arbutine, Madecassoside, Asiaticoside, Acide Madécassique, Acide Asiatique, Ascorbic Acid, Ménadione, Cyanocobalamin, Huile de Zeste de Citrus Junos, Linalool, Limonene', 'La Yuja Niacin Anti-Blemish Cream SOME BY MI est une crème hydratante et illuminatrice puissante conçue pour cibler les imperfections, les taches de rousseur, les taches brunes et le teint inégal, tout en hydratant la peau en profondeur. Formulée avec 70% d''extrait de yuja pour une nutrition intense et 5% de niacinamide pour améliorer visiblement la texture de la peau et réduire l''hyperpigmentation, cette crème agit pour créer un teint radieux et uniforme. Le panthénol (provitamine B5) stimule l''hydratation, ce qui donne à la peau un aspect plus rebondi et plus sain. Sa formule légère mais confortable pénètre sans effort, ce qui lui permet d''être utilisée le matin comme crème hydratante ou comme masque de nuit pour fixer l''hydratation. Grâce à sa forte concentration en ingrédients naturels et rafraîchissants pour la peau, cette crème éclaircit, apaise et revitalise efficacement les peaux ternes, laissant derrière elle un éclat souple et lumineux. Recommandé pour : Hyperpigmentation, tous types de peaux.', 60, 'g', 'some-by-mi-yuja-niacin-anti-blemish-cream', 'https://korean-skincare.fr/products/some-by-mi-yuja-niacin-anti-blemish-cream', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-yuja-niacin-anti-blemish-cream.webp', 'Applique une quantité appropriée de produit uniformément sur l''ensemble de ton visage, en évitant le contour des yeux et de la bouche. Tapote délicatement pour améliorer la pénétration du produit.', 1895, '2026-05-07 17:37:40.617105+00', '2026-06-14 15:14:07.812+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44e6-7454-804f-4484b3ec91ce', '__OWNER_ID__', 'AHA BHA PHA 30 Days Miracle Cleansing Bar', 'SOME BY MI', 'cleanser', 'bar', 'Glycerin, Aqua, Propylene Glycol, Sodium Palmitate, Sodium Stearate, Potassium Laurate, Sodium Laurate, Cocobetaine, Disodium Laureth Sulfosuccinate, Sucrose, Sorbitol, Decyl Glucoside, Niacinamide, Chlorella Vulgaris Powder, Melaleuca Alternifolia Tea Tree Leaf Oil, Melaleuca Alternifolia Tea Tree Extract, Stearic Acid, Citric Acid 5,000 ppm, Salicylic Acid 5,000 ppm, Hordeum Vulgare Leaf Powder, Houttuynia Cordata Extract, Glycyrrhiza Uralensis Root Extract, Leontopodium Alpinum Extract, Olea Europaea Fruit Oil, Argania Spinosa Kernel Oil, Camellia Sinensis Seed Oil, Adansonia Digitata Seed Extract, Centella Asiatica Extract, Lactobacillus Acid 1,000 ppm, Hydrolyzed Potato Protein, Hydrolyzed Wheat Protein, Hydrolyzed Rice Protein, Hydrolyzed Oat Protein, Disodium EDTA, Limonene', 'L''AHA BHA PHA 30 Days Miracle Cleansing Bar SOME BY MI est un savon nettoyant exfoliant qui laisse la peau plus nette et hydratée. Formulé avec un extrait d''arbre à thé de 10 000 ppm, 2 % de niacinamide et des acides AHA, BHA et PHA, ce savon aide à traiter l''acné, à éclaircir, à exfolier et à éliminer les impuretés des pores. Recommandé pour : Tous types de peaux.', 106, 'g', 'some-by-mi-miracle-cleansing-bar', 'https://korean-skincare.fr/products/some-by-mi-miracle-cleansing-bar', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-miracle-cleansing-bar.webp', 'Applique délicatement sur peau humide en effectuant de légers mouvements circulaires pendant un moment. Rince à l''eau tiède.', 1008, '2026-05-07 17:37:40.582093+00', '2026-06-14 15:14:07.813+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44f7-70b7-8c06-ee0592add8f2', '__OWNER_ID__', 'Super Matcha Pore Care Starter Kit', 'SOME BY MI', 'moisturizer', 'jar', 'Super Matcha Pore Clean Cleansing Gel : Eau de Feuille de Camellia Sinensis (62%), Glycerin, Aqua, Potassium Cocoyl Glycinate, Lauryl Glucoside, Coco-Glucoside, Acrylate Copolymère, Sodium Cocoyl Isethionate, 1,2-Hexanediol, Eau d''Écorce de Salix Alba, Salix Alba Bark Extract, Eau Glaciaire, Eau Gazeuse, Centella Asiatica Extract, Extrait de Feuille de Centella Asiatica, Melia Azadirachta Leaf Extract, Extrait de Fleur de Melia Azadirachta, Calamine, Poudre de Feuille de Camellia Sinensis (50ppm), Poudre de Feuille de Melaleuca Alternifolia, Butylene Glycol, Sodium Hyaluronate, Allantoin, Acide Madecassique, Asiaticoside, Acide Asiatique, Madecassoside, Cocos Nucifera Oil, Coco-Caprylate/Caprate, Caprylyl Glycol, Undecylenate de Glycéryl, Polyglycéryl-10 Myristate, Potassium Cetyl Phosphate, Lauric Acid, Mannane, Lactobionic Acid, Citric Acid, Triethoxycaprylylsilane, Methylpropanediol, Benzylglycol, Ethylhexylglycerin, Framboise Cétone, Parfum. Super Matcha Pore Clean Clay Mask : Eau, Kaolin, Glycerin, Camellia Sinensis Leaf Water, Dioxyde de Titane CI 77891, Bentonite, Silicate de Magnésium et d''Aluminium, Caramel, Extrait de Feuille de Chamaecyparis Obtusa, Silica, Argile de Manicouagan, Feuille de Camellia Sinensis, Poudre de Feuille de Camellia Sinensis, Poudre de Houttuynia Cordata, Centella Asiatica Extract, Camellia Sinensis Leaf Extract, Salix Alba Bark Extract, Extrait de Feuille de Rosa Rugosa, Extrait de Feuille de Mellissa Officinalis, Aqua, Melaleuca Alternifolia Leaf Water, Aqua, Allantoin, Acide Madecassique, Asiaticoside, Acide Asiatique, Capryloyl Salicylic Acid, Butylene Glycol, Gomme Xanthane, Alcool Polyvinylique, 1,2-Hexanediol, Benzyl Glycol, Ethylhexylglycerin, Framboise Cétone, CI 42090. Super Matcha Pore Tightening Toner : Extrait de Feuille de Camellia Sinensis, Propanediol, Salix Alba Bark Extract, Niacinamide, 1,2-Hexanediol, Silicate de Lithium Magnésium Sodium, Chlorure de Calcium, Silica, Sodium Citrate, Polyglycéryl-10 Laurate, Polyglycéryl-10 Myristate, Ethylhexylglycerin, Adenosine, Glycerin, Citric Acid, Édétate Disodique, Parfum, Centella Asiatica Extract, Eau Glaciaire, Eau Gazeuse, Melaleuca Alternifolia Leaf Water, Houttuynia Cordata Extract, Butylene Glycol, Madecassoside, Aqua, Asiaticoside, Acide Asiatique, Acide Madecassique, Glyceryl Caprylate, Hexyl Cinnamal. Super Matcha Pore Tightening Serum : Extrait de Feuille de Camellia Sinensis, Niacinamide, 1,2-Hexanediol, Aqua, Butylene Glycol, Polyglycéryl-10 Laurate, Polyglycéryl-10 Myristate, Glycerin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Arginine, Ethylhexylglycerin, Adenosine, Édétate Disodique, Parfum, Melia Azadirachta Leaf Extract, Extrait de Fleur de Melia Azadirachta, Extrait de Melissa Officinalis, Extrait de Fleur de Citrus Aurantium Dulcis, Extrait de Fruit de Chaenomeles Sinensis, Oenothera Biennis Flower Extract, Pueraria Lobata Root Extract, Pinus Palustris Leaf Extract, Ulmus Davidiana Root Extract, Centella Asiatica Extract, Melaleuca Alternifolia Leaf Water, Salix Alba Bark Extract, Madecassoside, Houttuynia Cordata Extract, Lactobionic Acid, Asiaticoside, Acide Asiatique, Acide Madecassique, Sodium Hyaluronate, Glyceryl Caprylate, Hexyl Cinnamal, Limonene, Linalool', 'Profite d''une expérience cosmétique ultime en matière de soin des pores avec la Super Matcha Pore Care Starter Kit SOME BY MI. Cet ensemble complet comprend le Super Matcha Pore Clean Cleansing Gel, le Tightening Toner, le Tightening Serum, et le Clean Clay Mask, tous infusés des bienfaits de l''eau de matcha, de BHA naturel provenant de l''écorce de saule blanc et d''eau de glacier. Conçue pour combattre les points noirs et affiner la texture de la peau, la routine de ce coffret promet une peau purifiée, claire et rafraîchie. Comprend : Super Matcha Pore Clean Cleansing Gel (42ml) Super Matcha Pore Clean Clay Mask (42g) Super Matcha Pore Tightening Toner (30ml) Super Matcha Pore Tightening Serum (10ml) Recommandé pour :', NULL, NULL, 'some-by-mi-super-match-pore-care-starter-kit', 'https://korean-skincare.fr/products/some-by-mi-super-match-pore-care-starter-kit', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-super-match-pore-care-starter-kit.webp', 'Étape 1 : Super Match Pore Clean Cleansing Gel Distribue une quantité suffisante de produit dans ta main et fais mousser. Masse délicatement ton visage en évitant le contour de tes yeux et de ta bouche. Rince à l''eau tiède. Étape 2 : Super Matcha Pore Clean Clay Mask Après le nettoyage, applique délicatement sur ton visage sec, en évitant le contour des yeux et des lèvres. Rince à l''eau tiède au bout de 15 minutes. Étape 3 : Super Matcha Pore Tightening Toner Applique une quantité appropriée de produit sur une compresse en coton Applique tout en suivant délicatement les lignes de ta peau. Tapote délicatement pour faire pénétrer le produit dans ta peau. Étape 4 : Super Matcha Pore Tightening Serum Prélève une quantité appropriée de produit et applique-le sur l''ensemble de ton visage. Masse délicatement pour une meilleure absorption.', 1957, '2026-05-07 17:37:40.598762+00', '2026-06-14 15:14:07.813+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44ed-7cfb-b42f-0763d8778840', '__OWNER_ID__', 'Hyaluron Moisturizing Glow Luminous Ampoule Mask', 'SOME BY MI', 'mask', 'pack', 'Aqua, Dipropylene Glycol, Glycerin, Methylpropanediol, 1,2-Hexanediol, Butylene Glycol, Hydroxyéthylcellulose, Hydroxyacetophenone, Hexylene Glycol, Carbo (300 ppm), Dipotassium Glycyrrhizate, Disodium EDTA, Extrait de Varech, Myristate de Polyglycéryl-10, Polyglycéryl-Polyglycérol, Laurate de Polyglycéryl-10, Huile de Fleur de Géranium, Extrait de Résine de Boswellia, Glucoside de Xylityl, Aloe Barbadensis Leaf Extract, Anhydroxylitol, Extrait de Racine d''Igname, Xylitol, Hydrolyzed Hyaluronic Acid, Glucose, Hyaluronate d''Acétylé Sodium (1 ppm)', 'Le Hyaluron Moisturizing Glow Luminous Ampoule Mask Some By Mi est infusé d''acide hyaluronique triple et d''eau oxygénée de Jeju qui agissent ensemble pour désaltérer la peau sèche et déshydratée et la rendre plus souple. Les masques tissu Air-light Derma-seal épousent parfaitement les courbes du visage, offrant une texture légère et une adhérence puissante pour délivrer tous les nutriments de manière efficace.', 1, 'pcs', 'some-by-mi-hyaluron-moisturizing-glow-luminous-ampoule-mask', 'https://korean-skincare.fr/products/some-by-mi-hyaluron-moisturizing-glow-luminous-ampoule-mask', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-hyaluron-moisturizing-glow-luminous-ampoule-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 250, '2026-05-07 17:37:40.589697+00', '2026-06-14 15:14:07.813+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44f0-70ec-a08e-0bbd9cf3785d', '__OWNER_ID__', 'Yuja Niacin Blemish Care Serum', 'SOME BY MI', 'serum', 'dropper', 'Citrus Junos Fruit Extract, Niacinamide, Caprylic/Capric Triglyceride, 1,2-Hexanediol, Hydrogenated PolyC6-14 Olefin, Bisabolol, Carbomer, Arginine, Brassica Campestris Seed Oil, Xanthan Gum, Ethylhexylglycerin, Adenosine, Citrus Junos Peel Oil, Melia Azadirachta Flower Extract, Ocimum Sanctum Leaf Extract, Glycyrrhiza Glabra Root Extract, Polyglyceryl-3 Diisostearate, Aqua, Curcuma Longa Root Extract, Corallina Officinalis Extract, Glycerin, Althaea Officinalis Root Extract, Oryza Sativa Extract, 2-O-Ethyl Ascorbic Acid, Hydrogenated Lecithin, Ficus Carica Fruit Extract, Punica Granatum Fruit Extract, Morus Alba Fruit Extract, Ginkgo Biloba Leaf Extract, Tocophersolan, Polyglyceryl-10 Stearate, Panthenol, Sodium Ascorbyl Phosphate, Biotin, Folic Acid, Pyridoxine, Cyanocobalamin, Linoleic Acid, Riboflavin, Beta-Carotene, Inositol, Thiamine HCl, Disodium EDTA, Limonene, Linalool', 'Le Yuja Niacin Blemish Care Serum SOME BY MI est un sérum éclaircissant hautement concentré qui peut aider à cibler le teint terne, les imperfections et l''hyperpigmentation. Il est enrichi à 82 % d''extrait de yuja (cédrat), qui contient 3 fois plus de vitamine C qu''un citron, pour éclaircir et hydrater. Le niacinamide, l''arbutine et le glutathion aident à unifier ton teint, tandis que 12 types de vitamines revitalisent et apaisent ta peau pour un teint frais et lumineux. Recommandé pour : Tous types de peaux.', 50, 'ml', 'some-by-mi-yuja-niacin-blemish-care-serum', 'https://korean-skincare.fr/products/some-by-mi-yuja-niacin-blemish-care-serum', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-yuja-niacin-blemish-care-serum.webp', 'Prélève une quantité suffisante de produit. Masse délicatement sur ta peau en suivant son grain. Renouvelle l''application sur le contour des yeux secs.', 1807, '2026-05-07 17:37:40.591929+00', '2026-06-14 15:14:07.813+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-44f4-76b1-969e-4e789afac597', '__OWNER_ID__', 'Galactomyces Glutathione Daily Mask', 'SOME BY MI', 'mask', 'pack', 'Aqua, Dipropylene Glycol, Glycerin, Niacinamide, Methylpropanediol, Glyceryl Glucoside, Galactomyces Ferment Filtrate, Glycéryléther-26, Érythritol, Laurate de Polyglyceryl-10, Hydroxyacetophenone, Panthenol, Caprylyl Glycol, Esters Hydrolysés de Jojoba, Ethylhexylglycerin, Adenosine, Carbomer, Glucose, Gomme Xanthane, Arginine, 1,2-Hexanediol, Butylene Glycol, Citric Acid, Polyquaternium-51, Huile de Fruit de Citrus Aurantium Bergamia, Diéthylhexyl Sulfosuccinate de Sodium, Pantolactone, Sodium Citrate, Lavandula Angustifolia Oil, Glutathione, Sodium Hyaluronate, Oryza Sativa Extract, Ascorbic Acid, Pyrus Malus Fruit Extract, Dipotassium Glycyrrhizate, Hydrogenated Lecithin, Gluconolactone, Extrait de Brocoli, Extrait de Fleur de Prunus Serrulata, Extrait de Germe de Nelumbo Nucifera, Extrait de Fleur de Lilium Tigrinum, Copper Tripeptide-1, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Sodium Hyaluronate Crosspolymer, Hydroxypropyltrimonium Hyaluronate, Potassium Hyaluronate, Hydrolyzed Sodium Hyaluronate, Pentylene Glycol, Sodium Acetylated Hyaluronate, Disodium EDTA, Limonene, Linalool', 'Le Galactomyces Glutathione Daily Mask SOME BY MI offre une solution revitalisante pour les peaux ternes, en apportant un soin intensif à la fois éclaircissant et illuminateur. Infusé d''ingrédients puissants comme de l''extrait de galactomyces, du glutathion et de la vitamine C, il agit pour améliorer la texture de la peau, réduire les imperfections et restaurer un teint lisse et lumineux. Avec les avantages supplémentaires de l''extrait de riz, de l''extrait de brocoli et d''un complexe éclaircissant de fleurs blanches, il illumine efficacement la peau tandis que l''extrait de pomme, le peptide et le Hyal-Microsome assurent une hydratation en profondeur, laissant la peau hydratée et rafraîchie. Recommandé pour : Peaux sèches, tous types de peaux. Contient : 30 masques tissu.', 30, 'pcs', 'some-by-mi-galactomyces-glutathione-daily-mask', 'https://korean-skincare.fr/products/some-by-mi-galactomyces-glutathione-daily-mask', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-galactomyces-glutathione-daily-mask.webp', 'Après avoir nettoyé ton visage et appliqué un tonique, applique le masque tissu en l''ajustant à ton visage. Retire-le au bout de 10 minutes. Tapote délicatement ta peau pour améliorer l''absorption.', 2395, '2026-05-07 17:37:40.596272+00', '2026-06-14 15:14:07.813+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-450b-7a8d-b21a-cf71537b575c', '__OWNER_ID__', 'Snail Truecica Miracle Repair Cream', 'SOME BY MI', 'moisturizer', 'jar', 'Aqua, Propanediol, Dicaprylyl Carbonate, Niacinamide, Polyglyceryl-3 Methylglucose Distearate, 1,2-Hexanediol, Butylene Glycol, Cyclopentasiloxane, Cetearyl Alcohol, Squalane, Glyceryl Stearate, Carbomer, Citrus Aurantium Bergamia Fruit Oil, Cyclohexasiloxane, Tromethamine, Sodium Polyacrylate, Allantoin, Ethylhexylglycerin, Hydrolyzed Collagen, Glycerin, Adenosine, Centella Asiatica Extract, Salvia Officinalis Oil, Disodium EDTA, Melaleuca Alternifolia Leaf Extract, Artemisia Princeps Leaf Extract, Pentylene Glycol, Tocopherol, Madecassoside, Hydrolyzed Vegetable Protein, Hydrogenated Lecithin, Snail Secretion Filtrate, Asiaticoside, Madecassic Acid, Asiatic Acid, Stearic Acid, Ceramide NP, Ceramide NS, Phytosphingosine, Cholesterol, Ceramide AS, Ceramide AP, Ceramide EOP, Limonene, Linalool', 'La crème réparatrice miracle Some By Mi Snail Truecica est un hydratant doux mais puissant qui aide à guérir et à renforcer les peaux abîmées ou sensibles. Formulée avec Snail Truecica™, un mélange apaisant de mucine d''escargot, de vitamines et de protéines, elle forme une couche légère et respirante sur la peau pour favoriser la cicatrisation naturelle et calmer les irritations. Gorgée de collagène marin, de cinq types de céramides et de peptides d''origine végétale, cette crème aide à construire une barrière cutanée solide de l''intérieur, laissant votre peau lisse, résistante et éclatante de santé. Elle permet également d''éclaircir les zones ternes et d''estomper les marques, le tout sans additifs agressifs, ce qui en fait un excellent choix pour les peaux stressées. Recommandé pour : Hyperpigmentation, peaux normales à sèches.', 60, 'g', 'some-by-mi-snail-truecica-miracle-repair-cream', 'https://korean-skincare.fr/products/some-by-mi-snail-truecica-miracle-repair-cream', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-snail-truecica-miracle-repair-cream.webp', 'Applique le produit lors de la dernière étape de ta routine beauté. Étale une quantité généreuse de crème sur ton visage, ton cou et la partie supérieure de ta poitrine. Masse délicatement ta peau pour une meilleure absorption.', 2052, '2026-05-07 17:37:40.619499+00', '2026-06-14 15:14:07.814+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4500-720b-b147-66fec0e45772', '__OWNER_ID__', 'Tea Tree Calming Glow Luminous Ampoule Mask', 'SOME BY MI', 'mask', 'pack', 'Aqua, Glycerin, Glycereth-26, Extrait de feuille de théier (10 000 ppm), Extrait de centipède, Extrait de fleur de souci, Extrait de thé vert, Extrait d''armoise, Extrait d''écorce de saule blanc, Extrait de feuille d''origan, Extrait de fermentation de lactobacillus/soja, Extrait d''écorce de bouleau, Extrait de marron doré, Extrait de poivre, Pentylene Glycol, Sodium Hyaluronate, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Hyaluronate d''hexanediol, Butylene Glycol, Laurate de polyglycéryle-10, Myristate de polyglycéryle-10, Arginine, Carbomer, Gomme xanthane, Cellulose hydroxyéthyl, Panthenol, Dipotassium Glycyrrhizate, Iodure de disodium, Hexylene Glycol, Hydroxyacetophenone, Glycérine d''éthylhexyle, Huile de bergamote', 'Le Tea Tree Calming Glow Luminous Ampoule Mask Some By Mi est formulé avec de l''extrait de feuille d''arbre à thé et de l''extrait de Centella Asiatica qui apaisent instantanément les peaux fatiguées. Les masques tissu Air-light Derma-seal enveloppent parfaitement les courbures du visage en offrant une texture légère et une puissante adhérence pour délivrer les nutriments de manière efficace.', 1, 'pcs', 'some-by-mi-tea-tree-calming-glow-luminous-ampoule-mask', 'https://korean-skincare.fr/products/some-by-mi-tea-tree-calming-glow-luminous-ampoule-mask', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-tea-tree-calming-glow-luminous-ampoule-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 250, '2026-05-07 17:37:40.607991+00', '2026-06-14 15:14:07.814+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4549-732b-a136-7b988c4fdc9f', '__OWNER_ID__', 'V10 Hyal Airfit Sun Screen', 'SOME BY MI', 'moisturizer', 'jar', 'Aqua, Homosalate, Octocrylene, Ethylhexyl Salicylate, Méthoxydibenzoylméthane de butyle, Salicylate de butyloctyle, Dicaprylyl Carbonate, Cetearyl Alcohol, Dipropylene Glycol, Glucoside de cétéaryle, Acrylate d''alkyle C10-30 en poly, Sorbitan Olivate, Polyméthylsilsesquioxane, Niacinamide, Glycol de benzyle, Glyceryl Stearate SE, Butylene Glycol, Panthenol, Arginine, Carbomer, Brassica Oleracea Italica Extract, Melaleuca Alternifolia Leaf Extract, Ether stéaryloxy de méthylcellulose hydroxypropyle, Centella Asiatica Extract, Camellia Sinensis Leaf Water, Tocopherol, Disodium EDTA, Ethylhexylglycerin, Gomme xanthane, Adenosine, 1,2-Hexanediol, Extrait de feuille de Bambusa Vulgaris, Extrait d''Oldenlandia Diffusa, Extrait de Lonicera Caprifolium, Extrait de levure, Extrait de Limonia Acidissima, Sodium Hyaluronate, Propanediol, Sodium Hyaluronate Crosspolymer, Hyaluronate d''ascorbyl propyle, Glycosaminoglycanes hydrolysés, Glycerin, Acide madécassique, Asiaticoside, Acide asiatique, Caprylyl Glycol, Sodium Ascorbyl Phosphate, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid, Biotin, Cyanocobalamin, Ascorbic Acid, Acide folique, Thiamine HCl, Riboflavine, Pyridoxine, Parfum, Citral, Benzyl Salicylate, Linalool, Limonene', 'Le V10 Hyal Airfit Sun Screen SOME BY MI offre une protection FPS 50 à large spectre sans laisser de traces blanches, ce qui en fait un excellent choix pour se protéger du soleil au quotidien. Cette crème solaire chimique est formulée avec des ingrédients apaisants et hydratants tels que la Centella Asiatica, la feuille d''arbre à thé et les extraits de chèvrefeuille, qui procurent des bienfaits apaisants et hydratants. Le niacinamide améliore l''éclat de la peau, tandis que la formule hypoallergénique, vegan et respectueuse des récifs garantit une utilisation sûre pour tous les types de peau. Sa texture aérée adhère légèrement à la peau sans donner de sensation de lourdeur ou d''étouffement, ce qui la rend parfaite pour ceux qui recherchent une protection solaire efficace avec un fini confortable. Recommandé pour : Peaux sèches, tous types de peaux.', 50, 'ml', 'some-by-mi-v10-hyal-airfit-sun-screen', 'https://korean-skincare.fr/products/some-by-mi-v10-hyal-airfit-sun-screen', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-v10-hyal-airfit-sun-screen.webp', 'Applique lors de la dernière étape de ta routine beauté, en évitant le contour des yeux et de la bouche.', 1837, '2026-05-07 17:37:40.681055+00', '2026-06-14 15:14:07.814+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4502-744b-b3e0-937bdaa1cb62', '__OWNER_ID__', 'Diamond Brightening Calming Glow Luminous Ampoule Mask', 'SOME BY MI', 'mask', 'pack', 'Aqua, Dipropylene Glycol, Glycerin, Methylpropanediol, 1,2-Hexanediol, Butylene Glycol, Hydroxyéthylcellulose, Hydroxyacéto Phénone, Hexylene Glycol, Carbo (300 Ppm), Dipotassium Glycyrrhizate, Édétate Disodique, Extrait De Varech, Myristate De Polyglycéryl-10, Polyglycéryl-10 Laurate, Huile De Fleur De Géranium, Extrait De Résine De Bosswellia, Xylityl Glucoside, Extrait De Feuille D''aloès, Anhydroxylitol, Extrait De Racine D''igname, Xylitol, Hydrolyzed Hyaluronic Acid, Glucose, Sodium Acetylated Hyaluronate', 'Le Diamond Brightening Calming Glow Luminous Ampoule Mask SOME BY MI est formulé avec de l''extrait de perle et de la poudre de diamant pour éclaircir la peau terne et lui donner un éclat luxueux digne d''un joyau. Les masques tissu Air-light Derma-seal épousent parfaitement les courbes du visage, offrant une texture sans poids et une adhérence efficace pour délivrer tous les nutriments de manière efficace.', 1, 'pcs', 'some-by-mi-diamond-brightening-calming-glow-luminous-ampoule-mask', 'https://korean-skincare.fr/products/some-by-mi-diamond-brightening-calming-glow-luminous-ampoule-mask', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-diamond-brightening-calming-glow-luminous-ampoule-mask.webp', 'Retire le masque de son emballage. Déplie le masque tissu et place-le sur ton visage en faisant correspondre les découpes avec tes yeux, ton nez et ta bouche. Assieds-toi et détends-toi pendant 15 à 25 minutes. Retire le masque et jette-le. Fais pénétrer délicatement l''excédent d''essence dans ton visage pour une absorption optimale.', 250, '2026-05-07 17:37:40.610115+00', '2026-06-14 15:14:07.814+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4554-7aa8-9150-1a3996164e64', '__OWNER_ID__', 'Truecica Aqua Calming Suncream', 'SOME BY MI', 'moisturizer', 'jar', 'Aqua, Adipate de Dibutyle, Diethylhexyl Butamido Triazone, Benzoate d''Alkyle C12-15, Dicaprylyl Carbonate, Propanediol, Butylene Glycol, Distearate de Polyglyceryl-3 Méthylglucose, Niacinamide, Acide Téréphtalyldène Dicamphor Sulfonique, 1,2-Hexanediol, Diethylamino Hydroxybenzoyl Hexyl Benzoate, Silica, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Cire de Fruit de Rhus Succedanea, Ethylhexyl Triazone, Tromethamine, Melaleuca Alternifolia Leaf Extract, Centella Asiatica Extract, Extrait d''Artemisia Capillaris, Asiaticoside, Acide Madécassique, Acide Asiatique, Madecassoside, Trehalose, Panthenol, Hydrolyzed Hyaluronic Acid, Aloe Barbadensis Leaf Extract, Palmitoyl Proline de Sodium, Extrait de Fleur de Nymphaea Alba, Cire de Copernicia Cerifera, Phosphate de Cétyl Potassium, Cetyl Alcohol, Alcool Behenyl, Coco-Caprylate/Caprate, Glyceryl Stearate, Polyacrylate Crosspolymer-6, Carbomer, Lavandula Angustifolia Oil, Synthetic Wax, Glutamide de Dibutyl Lauroyl, Palmitate de Dextrine, Polyuréthane-1, Sulfonate de Sodium Stearoxy PG-Hydroxyethylcellulose, Trihydroxystéarate, Cire de Son d''Oryza Sativa, Ethylhexylglycerin, Adenosine, Tocopherol, Dipropylene Glycol, Glycerin, Portulaca Oleracea Extract, Linalool, Geraniol, Limonene', 'La Truecica Aqua Calming Suncream SOME BY MI est une crème solaire testée dermatologiquement, respectueuse des récifs, qui offre une puissante protection SPF 50+ à large spectre, ce qui la rend adaptée à tous les types de peau, y compris les peaux sensibles et à problèmes. Sa formule à base de 79 % d''eau offre une hydratation profonde et durable sans laisser de traces blanches ni de sensation collante. Enrichie en Truecica™ signature de SOME BY MI, d''extrait de feuille d''aloe vera et d''extrait de nénuphar blanc, cette crème solaire délivre des effets apaisants et hydratants, aidant à réduire les taches pigmentaires et à éclaircir les cicatrices tout en luttant contre l''inflammation et en lissant la peau. Sa texture légère glisse sans effort, laissant la peau fraîche et bien protégée contre les rayons UVA et UVB. Recommandé pour : Hyperpigmentation, peaux sèches, tous types de peaux.', 50, 'ml', 'some-by-mi-truecica-aqua-calming-suncream', 'https://korean-skincare.fr/products/some-by-mi-truecica-aqua-calming-suncream', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-truecica-aqua-calming-suncream.webp', 'Applique en dernière étape de ta routine beauté, en évitant le contour des yeux et de la bouche.', 1358, '2026-05-07 17:37:40.692543+00', '2026-06-14 15:14:07.818+00', 'skincare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO public.products VALUES ('019e0384-4504-77c7-ab31-daa2944b224b', '__OWNER_ID__', 'Cica Peptide Derma Scalp Tonic', 'SOME BY MI', 'hair-serum', 'jar', 'Aqua, Alcohol Denat, Menthol, Tromethamine, Salicylic Acid, Panthenol, Biotin, Glycol Butylique, Extrait de Feuille de Mentha Piperita, Extrait de Mentha Viridis, Extrait de Feuille de Mentha Rotundifolia, Extrait de Graine de Glycine Max, Extrait de Graine de Nigella Sativa, Oryza Sativa Extract, Extrait de Fruit de Ribes Nigrum, Rubus Fruticosus Fruit Extract, Extrait de Graine de Sesamum Indicum, Extrait de Graine de Salvia Hispanica, Vaccinium Angustifolium Fruit Extract, Tripeptide-1 de Cuivre, Hexapeptide-9, Nonapeptide-1, Palmitoyl Tripeptide-5, Palmitoyl Pentapeptide-4, Palmitoyl Tripeptide-1, Palmitoyl Oligopeptide, Palmitoyl Tetrapeptide-7, Tripeptide-1, Acetyl Hexapeptide-8, Acetyl Tetrapeptide-2, Protéine de Maïs Hydrolysée, Protéine de Soja Hydrolysée, Protéine de Blé Hydrolysée, Extrait de Protéine de Lait, Centella Asiatica Extract, Madecassoside, Acide Madecassique, Asiaticoside, Acide Asiatic, Camellia Sinensis Leaf Extract, Houttuynia Cordata Extract, Extrait de Fleurs/Feuilles/Tiges de Leonurus Sibiricus, Extrait de Germes de Nelumbo Nucifera, Extrait d’Artemisia Vulgaris, 1,2-Hexanediol, Glycérine Éthylhexyle, Glycol Caprylique, Parfum', 'Renforce le volume et la santé de tes cheveux avec le Cica Peptide Derma Scalp Tonic SOME BY MI, une formule avancée conçue pour lutter contre la chute des cheveux et nourrir ton cuir chevelu. Infusé de 11 types de peptides et d''une forte concentration de cica, ce tonique apporte une hydratation profonde et des nutriments essentiels, pour apaiser les cuirs chevelus stressés tout en favorisant une chevelure brillante et résistante. L''ajout d''un Black Complex et de biotine améliore davantage la santé du cuir chevelu et l''élasticité des cheveux, ce qui en fait un produit idéal pour toutes les personnes qui souhaitent des cheveux plus volumineux et plus sains.', 150, 'ml', 'some-by-mi-cica-peptide-derma-scalp-tonic', 'https://korean-skincare.fr/products/some-by-mi-cica-peptide-derma-scalp-tonic', 'https://aurore-cdn.b-cdn.net/products/some-by-mi-cica-peptide-derma-scalp-tonic.webp', 'Agite bien avant d''utiliser. Divise tes cheveux en sections avec tes doigts et vaporise le produit sur ton cuir chevelu. Masse ton cuir chevelu pour une meilleure absorption.', 1995, '2026-05-07 17:37:40.612322+00', '2026-06-14 15:14:07.814+00', 'haircare', '[]', NULL, 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
