INSERT INTO public.products VALUES ('019e0384-47cb-797d-9b0e-1dbb78fed55b', '__OWNER_ID__', 'Super Soothing Cica & Aloe Essence Toner', 'JUMISO', 'toner', 'pump', 'Eau Minérale, Propanediol, Glycerin, Methylpropanediol, Centella Asiatica Extract, Glycosaminoglycanes Hydrolysés, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Cétone de Framboise, Hydroxypropyltrimonium Hyaluronate, Sodium Acétylé de Hyaluronate, Sodium Hyaluronate, Ethylhexylglycerin, Hyaluronic Acid, Madecassoside, Asiaticoside, Poudre de Jus de Feuille d''Aloe Barbadensis, Benzyl Glycol, Erythritol, Hydroxyéthylcellulose, Biosaccharide Gum-1, Dipotassium Glycyrrhizate, Acide Polyglucuronique, Aqua, Butylene Glycol, Dipropylene Glycol, Caprylyl Glycol, Panthenol, Allantoin, Pantolactone, Gomme Xanthane, 1,2-Hexanediol, Hydroxyacetophenone, Disodium EDTA', 'Le Super Soothing Cica & Aloe Essence Toner Jumiso est un tonique rafraîchissant et léger conçu pour calmer et hydrater les peaux fatiguées et irritées. Enrichi en Centella Asiatica et en feuilles d''Aloe Barbadensis, il apaise instantanément les rougeurs et renforce la barrière cutanée pour un teint rajeuni. Cette essence tonique à base d''eau minérale affine les pores, élimine les impuretés et hydrate la peau en profondeur sans la rendre grasse. Adaptées à tous les types de peaux, ses propriétés anti-inflammatoires et hydratantes aident à restaurer l''éclat naturel de la peau tout en la préparant aux étapes suivantes de ta routine beauté. Recommandé pour : Peaux sensibles et sèches, tous types de peaux.', 125, 'ml', 'jumiso-super-soothing-cica-aloe-essence-toner', 'https://korean-skincare.fr/products/jumiso-super-soothing-cica-aloe-essence-toner', 'https://aurore-cdn.b-cdn.net/products/jumiso-super-soothing-cica-aloe-essence-toner.webp', 'Après avoir nettoyé ta peau, applique le produit uniformément sur ton visage, en évitant le contour des yeux et de la bouche. Tapote délicatement ta peau pour faciliter l''absorption.', 2395, '2026-05-07 17:37:41.323476+00', '2026-06-14 15:14:07.858+00', 'skincare', '[]', 'eau', 'visible', NULL, NULL, NULL, 'verified', NULL, NULL);
